INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(424, 3647, 1, 1, 'Pada mulanya Allah menciptakan langit dan bumi.', 'Allah menciptakan langit dan bumi serta isinya'),
(425, 3647, 1, 2, 'Bumi belum berbentuk dan kosong; gelap gulita menutupi samudera raya, dan Roh Allah melayang-layang di atas permukaan air.', NULL),
(426, 3647, 1, 3, 'Berfirmanlah Allah: \"Jadilah terang.\" Lalu terang itu jadi.', NULL),
(427, 3647, 1, 4, 'Allah melihat bahwa terang itu baik, lalu dipisahkan-Nyalah terang itu dari gelap.', NULL),
(428, 3647, 1, 5, 'Dan Allah menamai terang itu siang, dan gelap itu malam. Jadilah petang dan jadilah pagi, itulah hari pertama.', NULL),
(429, 3647, 1, 6, 'Berfirmanlah Allah: \"Jadilah cakrawala di tengah segala air untuk memisahkan air dari air.\"', NULL),
(430, 3647, 1, 7, 'Maka Allah menjadikan cakrawala dan Ia memisahkan air yang ada di bawah cakrawala itu dari air yang ada di atasnya. Dan jadilah demikian.', NULL),
(431, 3647, 1, 8, 'Lalu Allah menamai cakrawala itu langit. Jadilah petang dan jadilah pagi, itulah hari kedua.', NULL),
(432, 3647, 1, 9, 'Berfirmanlah Allah: \"Hendaklah segala air yang di bawah langit berkumpul pada satu tempat, sehingga kelihatan yang kering.\" Dan jadilah demikian.', NULL),
(433, 3647, 1, 10, 'Lalu Allah menamai yang kering itu darat, dan kumpulan air itu dinamai-Nya laut. Allah melihat bahwa semuanya itu baik.', NULL),
(434, 3647, 1, 11, 'Berfirmanlah Allah: \"Hendaklah tanah menumbuhkan tunas-tunas muda, tumbuh-tumbuhan yang berbiji, segala jenis pohon buah-buahan yang menghasilkan buah yang berbiji, supaya ada tumbuh-tumbuhan di bumi.\" Dan jadilah demikian.', NULL),
(435, 3647, 1, 12, 'Tanah itu menumbuhkan tunas-tunas muda, segala jenis tumbuh-tumbuhan yang berbiji dan segala jenis pohon-pohonan yang menghasilkan buah yang berbiji. Allah melihat bahwa semuanya itu baik.', NULL),
(436, 3647, 1, 13, 'Jadilah petang dan jadilah pagi, itulah hari ketiga.', NULL),
(437, 3647, 1, 14, 'Berfirmanlah Allah: \"Jadilah benda-benda penerang pada cakrawala untuk memisahkan siang dari malam. Biarlah benda-benda penerang itu menjadi tanda yang menunjukkan masa-masa yang tetap dan hari-hari dan tahun-tahun,', NULL),
(438, 3647, 1, 15, 'dan sebagai penerang pada cakrawala biarlah benda-benda itu menerangi bumi.\" Dan jadilah demikian.', NULL),
(439, 3647, 1, 16, 'Maka Allah menjadikan kedua benda penerang yang besar itu, yakni yang lebih besar untuk menguasai siang dan yang lebih kecil untuk menguasai malam, dan menjadikan juga bintang-bintang.', NULL),
(440, 3647, 1, 17, 'Allah menaruh semuanya itu di cakrawala untuk menerangi bumi,', NULL),
(441, 3647, 1, 18, 'dan untuk menguasai siang dan malam, dan untuk memisahkan terang dari gelap. Allah melihat bahwa semuanya itu baik.', NULL),
(442, 3647, 1, 19, 'Jadilah petang dan jadilah pagi, itulah hari keempat.', NULL),
(443, 3647, 1, 20, 'Berfirmanlah Allah: \"Hendaklah dalam air berkeriapan makhluk yang hidup, dan hendaklah burung beterbangan di atas bumi melintasi cakrawala.\"', NULL),
(444, 3647, 1, 21, 'Maka Allah menciptakan binatang-binatang laut yang besar dan segala jenis makhluk hidup yang bergerak, yang berkeriapan dalam air, dan segala jenis burung yang bersayap. Allah melihat bahwa semuanya itu baik.', NULL),
(445, 3647, 1, 22, 'Lalu Allah memberkati semuanya itu, firman-Nya: \"Berkembangbiaklah dan bertambah banyaklah serta penuhilah air dalam laut, dan hendaklah burung-burung di bumi bertambah banyak.\"', NULL),
(446, 3647, 1, 23, 'Jadilah petang dan jadilah pagi, itulah hari kelima.', NULL),
(447, 3647, 1, 24, 'Berfirmanlah Allah: \"Hendaklah bumi mengeluarkan segala jenis makhluk yang hidup, ternak dan binatang melata dan segala jenis binatang liar.\" Dan jadilah demikian.', NULL),
(448, 3647, 1, 25, 'Allah menjadikan segala jenis binatang liar dan segala jenis ternak dan segala jenis binatang melata di muka bumi. Allah melihat bahwa semuanya itu baik.', NULL),
(449, 3647, 1, 26, 'Berfirmanlah Allah: \"Baiklah Kita menjadikan manusia menurut gambar dan rupa Kita, supaya mereka berkuasa atas ikan-ikan di laut dan burung-burung di udara dan atas ternak dan atas seluruh bumi dan atas segala binatang melata yang merayap di bumi.\"', NULL),
(450, 3647, 1, 27, 'Maka Allah menciptakan manusia itu menurut gambar-Nya, menurut gambar Allah diciptakan-Nya dia; laki-laki dan perempuan diciptakan-Nya mereka.', NULL),
(451, 3647, 1, 28, 'Allah memberkati mereka, lalu Allah berfirman kepada mereka: \"Beranakcuculah dan bertambah banyak; penuhilah bumi dan taklukkanlah itu, berkuasalah atas ikan-ikan di laut dan burung-burung di udara dan atas segala binatang yang merayap di bumi.\"', NULL),
(452, 3647, 1, 29, 'Berfirmanlah Allah: \"Lihatlah, Aku memberikan kepadamu segala tumbuh-tumbuhan yang berbiji di seluruh bumi dan segala pohon-pohonan yang buahnya berbiji; itulah akan menjadi makananmu.', NULL),
(453, 3647, 1, 30, 'Tetapi kepada segala binatang di bumi dan segala burung di udara dan segala yang merayap di bumi, yang bernyawa, Kuberikan segala tumbuh-tumbuhan hijau menjadi makanannya.\" Dan jadilah demikian.', NULL),
(454, 3647, 1, 31, 'Maka Allah melihat segala yang dijadikan-Nya itu, sungguh amat baik. Jadilah petang dan jadilah pagi, itulah hari keenam.', NULL),
(455, 3647, 2, 1, 'Demikianlah diselesaikan langit dan bumi dan segala isinya.', NULL),
(456, 3647, 2, 2, 'Ketika Allah pada hari ketujuh telah menyelesaikan pekerjaan yang dibuat-Nya itu, berhentilah Ia pada hari ketujuh dari segala pekerjaan yang telah dibuat-Nya itu.', NULL),
(457, 3647, 2, 3, 'Lalu Allah memberkati hari ketujuh itu dan menguduskannya, karena pada hari itulah Ia berhenti dari segala pekerjaan penciptaan yang telah dibuat-Nya itu.', NULL),
(458, 3647, 2, 4, 'Demikianlah riwayat langit dan bumi pada waktu diciptakan. Ketika TUHAN Allah menjadikan bumi dan langit, --', NULL),
(459, 3647, 2, 5, 'belum ada semak apapun di bumi, belum timbul tumbuh-tumbuhan apapun di padang, sebab TUHAN Allah belum menurunkan hujan ke bumi, dan belum ada orang untuk mengusahakan tanah itu;', NULL),
(460, 3647, 2, 6, 'tetapi ada kabut naik ke atas dari bumi dan membasahi seluruh permukaan bumi itu--', NULL),
(461, 3647, 2, 7, 'ketika itulah TUHAN Allah membentuk manusia itu dari debu tanah dan menghembuskan nafas hidup ke dalam hidungnya; demikianlah manusia itu menjadi makhluk yang hidup.', NULL),
(462, 3647, 2, 8, 'Selanjutnya TUHAN Allah membuat taman di Eden, di sebelah timur; disitulah ditempatkan-Nya manusia yang dibentuk-Nya itu.', 'Manusia dan taman Eden'),
(463, 3647, 2, 9, 'Lalu TUHAN Allah menumbuhkan berbagai-bagai pohon dari bumi, yang menarik dan yang baik untuk dimakan buahnya; dan pohon kehidupan di tengah-tengah taman itu, serta pohon pengetahuan tentang yang baik dan yang jahat.', NULL),
(464, 3647, 2, 10, 'Yang pertama, namanya Pison, yakni yang mengalir mengelilingi seluruh tanah Hawila, tempat emas ada. 2:12 Dan emas dari negeri itu baik; di sana ada damar bedolah dan batu krisopras.', NULL),
(465, 3647, 2, 11, 'Ada suatu sungai mengalir dari Eden untuk membasahi taman itu, dan dari situ sungai itu terbagi menjadi empat cabang.', NULL),
(466, 3647, 2, 12, 'Yang pertama, namanya Pison, yakni yang mengalir mengelilingi seluruh tanah Hawila, tempat emas ada. 2:12 Dan emas dari negeri itu baik; di sana ada damar bedolah dan batu krisopras.', NULL),
(467, 3647, 2, 13, 'Nama sungai yang kedua ialah Gihon, yakni yang mengalir mengelilingi seluruh tanah Kush.', NULL),
(468, 3647, 2, 14, 'Nama sungai yang ketiga ialah Tigris, yakni yang mengalir di sebelah timur Asyur. Dan sungai yang keempat ialah Efrat.', NULL),
(469, 3647, 2, 15, 'TUHAN Allah mengambil manusia itu dan menempatkannya dalam taman Eden untuk mengusahakan dan memelihara taman itu.', NULL),
(470, 3647, 2, 16, 'Lalu TUHAN Allah memberi perintah ini kepada manusia: \"Semua pohon dalam taman ini boleh kaumakan buahnya dengan bebas,', NULL),
(471, 3647, 2, 17, 'tetapi pohon pengetahuan tentang yang baik dan yang jahat itu, janganlah kaumakan buahnya, sebab pada hari engkau memakannya, pastilah engkau mati.\"', NULL),
(472, 3647, 2, 18, 'TUHAN Allah berfirman: \"Tidak baik, kalau manusia itu seorang diri saja. Aku akan menjadikan penolong baginya, yang sepadan dengan dia.\"', NULL),
(473, 3647, 2, 19, 'Lalu TUHAN Allah membentuk dari tanah segala binatang hutan dan segala burung di udara. Dibawa-Nyalah semuanya kepada manusia itu untuk melihat, bagaimana ia menamainya; dan seperti nama yang diberikan manusia itu kepada tiap-tiap makhluk yang hidup, demikianlah nanti nama makhluk itu.', NULL),
(474, 3647, 2, 20, 'Manusia itu memberi nama kepada segala ternak, kepada burung-burung di udara dan kepada segala binatang hutan, tetapi baginya sendiri ia tidak menjumpai penolong yang sepadan dengan dia.', NULL),
(475, 3647, 2, 21, 'Lalu TUHAN Allah membuat manusia itu tidur nyenyak; ketika ia tidur, TUHAN Allah mengambil salah satu rusuk dari padanya, lalu menutup tempat itu dengan daging.', NULL),
(476, 3647, 2, 22, 'Dan dari rusuk yang diambil TUHAN Allah dari manusia itu, dibangun-Nyalah seorang perempuan, lalu dibawa-Nya kepada manusia itu.', NULL),
(477, 3647, 2, 23, 'Lalu berkatalah manusia itu: \"Inilah dia, tulang dari tulangku dan daging dari dagingku. Ia akan dinamai perempuan, sebab ia diambil dari laki-laki.\"', NULL),
(478, 3647, 2, 24, 'Sebab itu seorang laki-laki akan meninggalkan ayahnya dan ibunya dan bersatu dengan isterinya, sehingga keduanya menjadi satu daging.', NULL),
(479, 3647, 2, 25, 'Mereka keduanya telanjang, manusia dan isterinya itu, tetapi mereka tidak merasa malu.', NULL),
(480, 3647, 3, 1, 'Adapun ular ialah yang paling cerdik dari segala binatang di darat yang dijadikan oleh TUHAN Allah. Ular itu berkata kepada perempuan itu: \"Tentulah Allah berfirman: Semua pohon dalam taman ini jangan kamu makan buahnya, bukan?\"', NULL),
(481, 3647, 3, 2, 'Lalu sahut perempuan itu kepada ular itu: \"Buah pohon-pohonan dalam taman ini boleh kami makan,', NULL),
(482, 3647, 3, 3, 'tetapi tentang buah pohon yang ada di tengah-tengah taman, Allah berfirman: Jangan kamu makan ataupun raba buah itu, nanti kamu mati.\"', NULL),
(483, 3647, 3, 4, 'Lalu ular itu berkata kepada perempuan itu: \"Tentulah Allah berfirman: Semua pohon dalam taman ini jangan kamu makan buahnya, bukan?\"', NULL),
(484, 3647, 3, 5, 'Tetapi ular itu berkata kepada perempuan itu: \"Sekali-kali kamu tidak akan mati,', NULL),
(485, 3647, 3, 6, 'Perempuan itu melihat, bahwa buah pohon itu baik untuk dimakan dan sedap kelihatannya, lagipula pohon itu menarik hati karena memberi pengertian. Lalu ia mengambil dari buahnya dan dimakannya dan diberikannya juga kepada suaminya yang bersama-sama dengan dia, dan suaminyapun memakannya.', NULL),
(486, 3647, 3, 7, 'Maka terbukalah mata mereka berdua dan mereka tahu, bahwa mereka telanjang; lalu mereka menyemat daun pohon ara dan membuat cawat.', NULL),
(487, 3647, 3, 8, 'Ketika mereka mendengar bunyi langkah TUHAN Allah, yang berjalan-jalan dalam taman itu pada waktu hari sejuk, bersembunyilah manusia dan isterinya itu terhadap TUHAN Allah di antara pohon-pohonan dalam taman.', NULL),
(488, 3647, 3, 9, 'Tetapi TUHAN Allah memanggil manusia itu dan berfirman kepadanya: \"Di manakah engkau?\"', NULL),
(489, 3647, 3, 10, 'Ia menjawab: \"Ketika aku mendengar, bahwa Engkau ada dalam taman ini, aku menjadi takut, karena aku telanjang; sebab itu aku bersembunyi.\"', NULL),
(490, 3647, 3, 11, 'Firman-Nya: \"Siapakah yang memberitahukan kepadamu, bahwa engkau telanjang? Apakah engkau makan dari buah pohon, yang Kularang engkau makan itu?\"', NULL),
(491, 3647, 3, 12, 'Manusia itu menjawab: \"Perempuan yang Kautempatkan di sisiku, dialah yang memberi dari buah pohon itu kepadaku, maka kumakan.\"', NULL),
(492, 3647, 3, 13, 'Kemudian berfirmanlah TUHAN Allah kepada perempuan itu: \"Apakah yang telah kauperbuat ini?\" Jawab perempuan itu: \"Ular itu yang memperdayakan aku, maka kumakan.\"', NULL),
(493, 3647, 3, 14, 'Lalu berfirmanlah TUHAN Allah kepada ular itu: \"Karena engkau berbuat demikian, terkutuklah engkau di antara segala ternak dan di antara segala binatang hutan; dengan perutmulah engkau akan menjalar dan debu tanahlah akan kaumakan seumur hidupmu.', NULL),
(494, 3647, 3, 15, 'Aku akan mengadakan permusuhan antara engkau dan perempuan ini, antara keturunanmu dan keturunannya; keturunannya akan meremukkan kepalamu, dan engkau akan meremukkan tumitnya.\"', NULL),
(495, 3647, 3, 16, 'Firman-Nya kepada perempuan itu: \"Susah payahmu waktu mengandung akan Kubuat sangat banyak; dengan kesakitan engkau akan melahirkan anakmu; namun engkau akan berahi kepada suamimu dan ia akan berkuasa atasmu.\"', NULL),
(496, 3647, 3, 17, 'Lalu firman-Nya kepada manusia itu: \"Karena engkau mendengarkan perkataan isterimu dan memakan dari buah pohon, yang telah Kuperintahkan kepadamu: Jangan makan dari padanya, maka terkutuklah tanah karena engkau; dengan bersusah payah engkau akan mencari rezekimu dari tanah seumur hidupmu:', NULL),
(497, 3647, 3, 18, 'semak duri dan rumput duri yang akan dihasilkannya bagimu, dan tumbuh-tumbuhan di padang akan menjadi makananmu;', NULL),
(498, 3647, 3, 19, 'dengan berpeluh engkau akan mencari makananmu, sampai engkau kembali lagi menjadi tanah, karena dari situlah engkau diambil; sebab engkau debu dan engkau akan kembali menjadi debu.\"', NULL),
(499, 3647, 3, 20, 'Manusia itu memberi nama Hawa kepada isterinya, sebab dialah yang menjadi ibu semua yang hidup.', NULL),
(500, 3647, 3, 21, 'Dan TUHAN Allah membuat pakaian dari kulit binatang untuk manusia dan untuk isterinya itu, lalu mengenakannya kepada mereka.', NULL),
(501, 3647, 3, 22, 'Berfirmanlah TUHAN Allah: \"Sesungguhnya manusia itu telah menjadi seperti salah satu dari Kita, tahu tentang yang baik dan yang jahat; maka sekarang jangan sampai ia mengulurkan tangannya dan mengambil pula dari buah pohon kehidupan itu dan memakannya, sehingga ia hidup untuk selama-lamanya.\"', NULL),
(502, 3647, 3, 23, 'Lalu TUHAN Allah mengusir dia dari taman Eden supaya ia mengusahakan tanah dari mana ia diambil.', NULL),
(503, 3647, 3, 24, 'Ia menghalau manusia itu dan di sebelah timur taman Eden ditempatkan-Nyalah beberapa kerub dengan pedang yang bernyala-nyala dan menyambar-nyambar, untuk menjaga jalan ke pohon kehidupan.', NULL),
(504, 3648, 1, 1, 'Inilah nama para anak Israel yang datang ke Mesir bersama-sama dengan Yakub; mereka datang dengan keluarganya masing-masing:', 'Orang Israel ditindas di Mesir'),
(505, 3648, 20, 1, 'Lalu Allah mengucapkan segala firman ini:', 'Kesepuluh firman'),
(586, 3647, 4, 1, 'Kemudian manusia itu bersetubuh dengan Hawa, isterinya, dan mengandunglah perempuan itu, lalu melahirkan Kain; maka kata perempuan itu: \"Aku telah mendapat seorang anak laki-laki dengan pertolongan TUHAN.\"', 'Hawa dan Kain'),
(587, 3647, 4, 2, 'Selanjutnya dilahirkannyalah Habel, adik Kain; dan Habel menjadi gembala kambing domba, Kain menjadi petani.', NULL),
(588, 3647, 4, 3, 'Setelah beberapa waktu lamanya, maka Kain mempersembahkan sebagian dari hasil tanah itu kepada TUHAN sebagai korban persembahan;', NULL),
(589, 3647, 4, 4, 'Habel juga mempersembahkan korban persembahan dari anak sulung kambing dombanya, yakni lemak-lemaknya; maka TUHAN mengindahkan Habel dan korban persembahannya itu,', NULL),
(590, 3647, 4, 5, 'tetapi Kain dan korban persembahannya tidak diindahkan-Nya. Lalu hati Kain menjadi sangat panas, dan mukanya muram.', NULL),
(591, 3647, 4, 6, 'Firman TUHAN kepada Kain: \"Mengapa hatimu panas dan mukamu muram?', NULL),
(592, 3647, 4, 7, 'Apakah mukamu tidak akan berseri, jika engkau berbuat baik? Tetapi jika engkau tidak berbuat baik, dosa sudah mengintip di depan pintu; ia sangat menggoda engkau, tetapi engkau harus berkuasa atasnya.\"', NULL),
(593, 3647, 4, 8, 'Kata Kain kepada Habel, adiknya: \"Marilah kita pergi ke padang.\" Ketika mereka ada di padang, tiba-tiba Kain memukul Habel, adiknya itu, lalu membunuh dia.', NULL),
(594, 3647, 4, 9, 'Firman TUHAN kepada Kain: \"Di mana Habel, adikmu itu?\" Jawabnya: \"Aku tidak tahu! Apakah aku penjaga adikku?\"', NULL),
(595, 3647, 4, 10, 'Firman-Nya: \"Apakah yang telah kauperbuat ini? Darah adikmu itu berteriak kepada-Ku dari tanah.', NULL),
(596, 3647, 4, 11, 'Maka sekarang, terkutuklah engkau, terbuang jauh dari tanah yang mengangakan mulutnya untuk menerima darah adikmu itu dari tanganmu.', NULL),
(597, 3647, 4, 12, 'Apabila engkau mengusahakan tanah itu, maka tanah itu tidak akan memberikan hasil sepenuhnya lagi kepadamu; engkau menjadi seorang pelarian dan pengembara di bumi.\"', NULL),
(598, 3647, 4, 13, 'Kata Kain kepada TUHAN: \"Hukumanku itu lebih besar dari pada yang dapat kutanggung.', NULL),
(599, 3647, 4, 14, 'Engkau menghalau aku sekarang dari tanah ini dan aku akan tersembunyi dari hadapan-Mu, seorang pelarian dan pengembara di bumi; maka barangsiapa yang akan bertemu dengan aku, tentulah akan membunuh aku.\"', NULL),
(600, 3647, 4, 15, 'Firman TUHAN kepadanya: \"Sekali-kali tidak! Barangsiapa yang membunuh Kain akan dibalaskan kepadanya tujuh kali lipat.\" Kemudian TUHAN menaruh tanda pada Kain, supaya ia jangan dibunuh oleh barangsiapapun yang bertemu dengan dia.', NULL),
(601, 3647, 4, 16, 'Lalu Kain pergi dari hadapan TUHAN dan ia menetap di tanah Nod, di sebelah timur Eden.', NULL),
(602, 3647, 4, 17, 'Kain bersetubuh dengan isterinya dan mengandunglah perempuan itu, lalu melahirkan Henokh; kemudian Kain mendirikan suatu kota dan dinamainya kota itu Henokh, menurut nama anaknya.', NULL),
(603, 3647, 4, 18, 'Bagi Henokh lahirlah Irad, dan Irad itu memperanakkan Mehuyael dan Mehuyael memperanakkan Metusael, dan Metusael memperanakkan Lamekh. 4:19 Lamekh mengambil isteri dua orang; yang satu namanya Ada, yang lain Zila.', NULL),
(604, 3647, 4, 19, 'Lamekh mengambil isteri dua orang; yang satu namanya Ada, yang lain Zila.', NULL),
(605, 3647, 4, 20, 'Ada itu melahirkan Yabal; dialah yang menjadi bapa orang yang diam dalam kemah dan memelihara ternak.', NULL),
(606, 3647, 4, 21, 'Nama adiknya ialah Yubal; dialah yang menjadi bapa semua orang yang memainkan kecapi dan suling.', NULL),
(607, 3647, 4, 22, 'Zila juga melahirkan anak, yakni Tubal-Kain, bapa semua tukang tembaga dan tukang besi. Adik perempuan Tubal-Kain ialah Naama.', NULL),
(608, 3647, 4, 23, 'Berkatalah Lamekh kepada kedua isterinya itu: \"Ada dan Zila, dengarkanlah suaraku: hai isteri-isteri Lamekh, pasanglah telingamu kepada perkataanku ini: Aku telah membunuh seorang laki-laki karena ia melukai aku, membunuh seorang muda karena ia memukul aku sampai bengkak;', NULL),
(609, 3647, 4, 24, 'sebab jika Kain harus dibalaskan tujuh kali lipat, maka Lamekh tujuh puluh tujuh kali lipat.\"', NULL),
(610, 3647, 4, 25, 'Adam bersetubuh pula dengan isterinya, lalu perempuan itu melahirkan seorang anak laki-laki dan menamainya Set, sebab katanya: \"Allah telah mengaruniakan kepadaku anak yang lain sebagai ganti Habel; sebab Kain telah membunuhnya.\"', NULL),
(611, 3647, 4, 26, 'Lahirlah seorang anak laki-laki bagi Set juga dan anak itu dinamainya Enos. Waktu itulah orang mulai memanggil nama TUHAN.', NULL),
(828, 3647, 5, 1, 'Inilah daftar keturunan Adam. Pada waktu manusia itu diciptakan oleh Allah, dibuat-Nyalah dia menurut rupa Allah;', 'Daftar Keturunan Adam'),
(829, 3647, 5, 2, 'laki-laki dan perempuan diciptakan-Nya mereka. Ia memberkati mereka dan memberikan nama \"Manusia\" kepada mereka, pada waktu mereka diciptakan.', NULL),
(830, 3647, 5, 3, 'Setelah Adam hidup seratus tiga puluh tahun, ia memperanakkan seorang laki-laki menurut rupa dan gambarnya, lalu memberi nama Set kepadanya.', NULL),
(831, 3647, 5, 4, 'Umur Adam, setelah memperanakkan Set, delapan ratus tahun, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(832, 3647, 5, 5, 'Jadi Adam mencapai umur sembilan ratus tiga puluh tahun, lalu ia mati.', NULL),
(833, 3647, 5, 6, 'Setelah Set hidup seratus lima tahun, ia memperanakkan Enos.', NULL),
(834, 3647, 5, 7, 'Dan Set masih hidup delapan ratus tujuh tahun, setelah ia memperanakkan Enos, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(835, 3647, 5, 8, 'Jadi Set mencapai umur sembilan ratus dua belas tahun, lalu ia mati.', NULL),
(836, 3647, 5, 9, 'Setelah Enos hidup sembilan puluh tahun, ia memperanakkan Kenan.', NULL),
(837, 3647, 5, 10, 'Dan Enos masih hidup delapan ratus lima belas tahun, setelah ia memperanakkan Kenan, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(838, 3647, 5, 11, 'Jadi Enos mencapai umur sembilan ratus lima tahun, lalu ia mati.', NULL),
(839, 3647, 5, 12, 'Setelah Kenan hidup tujuh puluh tahun, ia memperanakkan Mahalaleel.', NULL),
(840, 3647, 5, 13, 'Dan Kenan masih hidup delapan ratus empat puluh tahun, setelah ia memperanakkan Mahalaleel, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(841, 3647, 5, 14, 'Jadi Kenan mencapai umur sembilan ratus sepuluh tahun, lalu ia mati.', NULL),
(842, 3647, 5, 15, 'Setelah Mahalaleel hidup enam puluh lima tahun, ia memperanakkan Yared.', NULL),
(843, 3647, 5, 16, 'Dan Mahalaleel masih hidup delapan ratus tiga puluh tahun, setelah ia memperanakkan Yared, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(844, 3647, 5, 17, 'Jadi Mahalaleel mencapai umur delapan ratus sembilan puluh lima tahun, lalu ia mati.', NULL),
(845, 3647, 5, 18, 'Setelah Yared hidup seratus enam puluh dua tahun, ia memperanakkan Henokh.', NULL),
(846, 3647, 5, 19, 'Dan Yared masih hidup delapan ratus tahun, setelah ia memperanakkan Henokh, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(847, 3647, 5, 20, 'Jadi Yared mencapai umur sembilan ratus enam puluh dua tahun, lalu ia mati.', NULL),
(848, 3647, 5, 21, 'Setelah Henokh hidup enam puluh lima tahun, ia memperanakkan Metusalah.', NULL),
(849, 3647, 5, 22, 'Dan Henokh hidup bergaul dengan Allah selama tiga ratus tahun lagi, setelah ia memperanakkan Metusalah, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(850, 3647, 5, 23, 'Jadi Henokh mencapai umur tiga ratus enam puluh lima tahun.', NULL),
(851, 3647, 5, 24, 'Dan Henokh hidup bergaul dengan Allah, lalu ia tidak ada lagi, sebab ia telah diangkat oleh Allah.', NULL),
(852, 3647, 5, 25, 'Setelah Metusalah hidup seratus delapan puluh tujuh tahun, ia memperanakkan Lamekh.', NULL),
(853, 3647, 5, 26, 'Dan Metusalah masih hidup tujuh ratus delapan puluh dua tahun, setelah ia memperanakkan Lamekh, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(854, 3647, 5, 27, 'Jadi Metusalah mencapai umur sembilan ratus enam puluh sembilan tahun, lalu ia mati.', NULL),
(855, 3647, 5, 28, 'Setelah Lamekh hidup seratus delapan puluh dua tahun, ia memperanakkan seorang anak laki-laki,', NULL),
(856, 3647, 5, 29, 'an memberi nama Nuh kepadanya, katanya: \"Anak ini akan memberi kepada kita penghiburan dalam pekerjaan kita yang penuh susah payah di tanah yang telah terkutuk oleh TUHAN.\"', NULL),
(857, 3647, 5, 30, 'Dan Lamekh masih hidup lima ratus sembilan puluh lima tahun, setelah ia memperanakkan Nuh, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(858, 3647, 5, 31, 'Jadi Lamekh mencapai umur tujuh ratus tujuh puluh tujuh tahun, lalu ia mati.', NULL),
(859, 3647, 5, 32, 'Setelah Nuh berumur lima ratus tahun, ia memperanakkan Sem, Ham dan Yafet.', NULL),
(1000, 3647, 6, 1, 'Ketika manusia itu mulai bertambah banyak jumlahnya di muka bumi, dan bagi mereka lahir anak-anak perempuan,', 'Kejahatan manusia'),
(1001, 3647, 6, 2, 'maka anak-anak Allah melihat, bahwa anak-anak perempuan manusia itu cantik-cantik, lalu mereka mengambil isteri dari antara perempuan-perempuan itu, siapa saja yang disukai mereka.', NULL),
(1002, 3647, 6, 3, 'Berfirmanlah TUHAN: \"Roh-Ku tidak akan selama-lamanya tinggal di dalam manusia, karena manusia itu adalah daging, tetapi umurnya akan seratus dua puluh tahun saja.\"', NULL),
(1003, 3647, 6, 4, 'Pada waktu itu orang-orang raksasa ada di bumi, dan juga pada waktu sesudahnya, ketika anak-anak Allah menghampiri anak-anak perempuan manusia, dan perempuan-perempuan itu melahirkan anak bagi mereka; inilah orang-orang yang gagah perkasa di zaman purbakala, orang-orang yang kenamaan.', NULL),
(1004, 3647, 6, 5, 'Ketika dilihat TUHAN, bahwa kejahatan manusia besar di bumi dan bahwa segala kecenderungan hatinya selalu membuahkan kejahatan semata-mata,', NULL),
(1005, 3647, 6, 6, 'maka menyesallah TUHAN, bahwa Ia telah menjadikan manusia di bumi, dan hal itu memilukan hati-Nya.', NULL),
(1006, 3647, 6, 7, 'Berfirmanlah TUHAN: \"Aku akan menghapuskan manusia yang telah Kuciptakan itu dari muka bumi, baik manusia maupun hewan dan binatang-binatang melata dan burung-burung di udara, sebab Aku menyesal, bahwa Aku telah menjadikan mereka.\"', NULL),
(1007, 3647, 6, 8, 'Tetapi Nuh mendapat kasih karunia di mata TUHAN.', NULL),
(1008, 3647, 6, 9, 'Inilah riwayat Nuh: Nuh adalah seorang yang benar dan tidak bercela di antara orang-orang sezamannya; dan Nuh itu hidup bergaul dengan Allah.', 'Riwayat Nuh'),
(1009, 3647, 6, 10, 'Nuh memperanakkan tiga orang laki-laki: Sem, Ham dan Yafet.', NULL),
(1010, 3647, 6, 11, 'Adapun bumi itu telah rusak di hadapan Allah dan penuh dengan kekerasan.', NULL),
(1011, 3647, 6, 12, 'Allah menilik bumi itu dan sungguhlah rusak benar, sebab semua manusia menjalankan hidup yang rusak di bumi.', NULL),
(1012, 3647, 6, 13, 'Berfirmanlah Allah kepada Nuh: \"Aku telah memutuskan untuk mengakhiri hidup segala makhluk, sebab bumi telah penuh dengan kekerasan oleh mereka, jadi Aku akan memusnahkan mereka bersama-sama dengan bumi.', NULL),
(1013, 3647, 6, 14, 'Buatlah bagimu sebuah bahtera dari kayu gofir; bahtera itu harus kaubuat berpetak-petak dan harus kaututup dengan pakal dari luar dan dari dalam.', NULL),
(1014, 3647, 6, 15, 'Beginilah engkau harus membuat bahtera itu: tiga ratus hasta panjangnya, lima puluh hasta lebarnya dan tiga puluh hasta tingginya.', NULL),
(1015, 3647, 6, 16, 'Buatlah atap pada bahtera itu dan selesaikanlah bahtera itu sampai sehasta dari atas, dan pasanglah pintunya pada lambungnya; buatlah bahtera itu bertingkat bawah, tengah dan atas.', NULL),
(1016, 3647, 6, 17, 'Sebab sesungguhnya Aku akan mendatangkan air bah meliputi bumi untuk memusnahkan segala yang hidup dan bernyawa di kolong langit; segala yang ada di bumi akan mati binasa.', NULL),
(1017, 3647, 6, 18, 'Tetapi dengan engkau Aku akan mengadakan perjanjian-Ku, dan engkau akan masuk ke dalam bahtera itu: engkau bersama-sama dengan anak-anakmu dan isterimu dan isteri anak-anakmu.', NULL),
(1018, 3647, 6, 19, 'Dan dari segala yang hidup, dari segala makhluk, dari semuanya haruslah engkau bawa satu pasang ke dalam bahtera itu, supaya terpelihara hidupnya bersama-sama dengan engkau; jantan dan betina harus kaubawa.', NULL),
(1019, 3647, 6, 20, 'Dari segala jenis burung dan dari segala jenis hewan, dari segala jenis binatang melata di muka bumi, dari semuanya itu harus datang satu pasang kepadamu, supaya terpelihara hidupnya.', NULL),
(1020, 3647, 6, 21, 'Dan engkau, bawalah bagimu segala apa yang dapat dimakan; kumpulkanlah itu padamu untuk menjadi makanan bagimu dan bagi mereka.\"', NULL),
(1021, 3647, 6, 22, 'Lalu Nuh melakukan semuanya itu; tepat seperti yang diperintahkan Allah kepadanya, demikianlah dilakukannya.', NULL),
(1022, 3647, 7, 1, 'Lalu berfirmanlah TUHAN kepada Nuh: \"Masuklah ke dalam bahtera itu, engkau dan seisi rumahmu, sebab engkaulah yang Kulihat benar di hadapan-Ku di antara orang zaman ini.', 'Air bah'),
(1023, 3647, 7, 2, 'Dari segala binatang yang tidak haram haruslah kauambil tujuh pasang, jantan dan betinanya, tetapi dari binatang yang haram satu pasang, jantan dan betinanya;', NULL),
(1024, 3647, 7, 3, 'juga dari burung-burung di udara tujuh pasang, jantan dan betina, supaya terpelihara hidup keturunannya di seluruh bumi.', NULL),
(1025, 3647, 7, 4, 'Sebab tujuh hari lagi Aku akan menurunkan hujan ke atas bumi empat puluh hari empat puluh malam lamanya, dan Aku akan menghapuskan dari muka bumi segala yang ada, yang Kujadikan itu.\"', NULL),
(1026, 3647, 7, 5, 'Lalu Nuh melakukan segala yang diperintahkan TUHAN kepadanya.', NULL),
(1027, 3647, 7, 6, 'Nuh berumur enam ratus tahun, ketika air bah datang meliputi bumi.', NULL),
(1028, 3647, 7, 7, 'Masuklah Nuh ke dalam bahtera itu bersama-sama dengan anak-anaknya dan isterinya dan isteri anak-anaknya karena air bah itu.', NULL),
(1029, 3647, 7, 8, 'Dari binatang yang tidak haram dan yang haram, dari burung-burung dan dari segala yang merayap di muka bumi,', NULL),
(1030, 3647, 7, 9, 'datanglah sepasang mendapatkan Nuh ke dalam bahtera itu, jantan dan betina, seperti yang diperintahkan Allah kepada Nuh.', NULL),
(1031, 3647, 7, 10, 'Setelah tujuh hari datanglah air bah meliputi bumi.', NULL),
(1032, 3647, 7, 11, 'Pada waktu umur Nuh enam ratus tahun, pada bulan yang kedua, pada hari yang ketujuh belas bulan itu, pada hari itulah terbelah segala mata air samudera raya yang dahsyat dan terbukalah tingkap-tingkap di langit.', NULL),
(1033, 3647, 7, 12, 'Dan turunlah hujan lebat meliputi bumi empat puluh hari empat puluh malam lamanya.', NULL),
(1034, 3647, 7, 13, 'Pada hari itu juga masuklah Nuh serta Sem, Ham dan Yafet, anak-anak Nuh, dan isteri Nuh, dan ketiga isteri anak-anaknya bersama-sama dengan dia, ke dalam bahtera itu,', NULL),
(1035, 3647, 7, 14, 'mereka itu dan segala jenis binatang liar dan segala jenis ternak dan segala jenis binatang melata yang merayap di bumi dan segala jenis burung, yakni segala yang berbulu bersayap;', NULL),
(1036, 3647, 7, 15, 'dari segala yang hidup dan bernyawa datanglah sepasang mendapatkan Nuh ke dalam bahtera itu.', NULL),
(1037, 3647, 7, 16, 'Dan yang masuk itu adalah jantan dan betina dari segala yang hidup, seperti yang diperintahkan Allah kepada Nuh; lalu TUHAN menutup pintu bahtera itu di belakang Nuh.', NULL),
(1038, 3647, 7, 17, 'Empat puluh hari lamanya air bah itu meliputi bumi; air itu naik dan mengangkat bahtera itu, sehingga melampung tinggi dari bumi.', NULL),
(1039, 3647, 7, 18, 'Ketika air itu makin bertambah-tambah dan naik dengan hebatnya di atas bumi, terapung-apunglah bahtera itu di muka air.', NULL),
(1040, 3647, 7, 19, 'Dan air itu sangat hebatnya bertambah-tambah meliputi bumi, dan ditutupinyalah segala gunung tinggi di seluruh kolong langit,', NULL),
(1041, 3647, 7, 20, 'sampai lima belas hasta di atasnya bertambah-tambah air itu, sehingga gunung-gunung ditutupinya.', NULL),
(1042, 3647, 7, 21, 'Lalu mati binasalah segala yang hidup, yang bergerak di bumi, burung-burung, ternak dan binatang liar dan segala binatang merayap, yang berkeriapan di bumi, serta semua manusia.', NULL),
(1043, 3647, 7, 22, 'Matilah segala yang ada nafas hidup dalam hidungnya, segala yang ada di darat.', NULL),
(1044, 3647, 7, 23, 'Demikianlah dihapuskan Allah segala yang ada, segala yang di muka bumi, baik manusia maupun hewan dan binatang melata dan burung-burung di udara, sehingga semuanya itu dihapuskan dari atas bumi; hanya Nuh yang tinggal hidup dan semua yang bersama-sama dengan dia dalam bahtera itu.', NULL),
(1045, 3647, 7, 24, 'Dan berkuasalah air itu di atas bumi seratus lima puluh hari lamanya.', NULL),
(1046, 3647, 8, 1, 'Maka Allah mengingat Nuh dan segala binatang liar dan segala ternak, yang bersama-sama dengan dia dalam bahtera itu, dan Allah membuat angin menghembus melalui bumi, sehingga air itu turun.', 'Air bah surut'),
(1047, 3647, 8, 2, 'Ditutuplah mata-mata air samudera raya serta tingkap-tingkap di langit dan berhentilah hujan lebat dari langit,', NULL),
(1048, 3647, 8, 3, 'dan makin surutlah air itu dari muka bumi. Demikianlah berkurang air itu sesudah seratus lima puluh hari.', NULL),
(1049, 3647, 8, 4, 'Dalam bulan yang ketujuh, pada hari yang ketujuh belas bulan itu, terkandaslah bahtera itu pada pegunungan Ararat.', NULL),
(1050, 3647, 8, 5, 'Sampai bulan yang kesepuluh makin berkuranglah air itu; dalam bulan yang kesepuluh, pada tanggal satu bulan itu, tampaklah puncak-puncak gunung.', NULL),
(1051, 3647, 8, 6, 'Sesudah lewat empat puluh hari, maka Nuh membuka tingkap yang dibuatnya pada bahtera itu.', NULL),
(1052, 3647, 8, 7, 'Lalu ia melepaskan seekor burung gagak; dan burung itu terbang pulang pergi, sampai air itu menjadi kering dari atas bumi.', NULL),
(1053, 3647, 8, 8, 'Kemudian dilepaskannya seekor burung merpati untuk melihat, apakah air itu telah berkurang dari muka bumi.', NULL),
(1054, 3647, 8, 9, 'Tetapi burung merpati itu tidak mendapat tempat tumpuan kakinya dan pulanglah ia kembali mendapatkan Nuh ke dalam bahtera itu, karena di seluruh bumi masih ada air; lalu Nuh mengulurkan tangannya, ditangkapnya burung itu dan dibawanya masuk ke dalam bahtera.', NULL),
(1055, 3647, 8, 10, 'Ia menunggu tujuh hari lagi, kemudian dilepaskannya pula burung merpati itu dari bahtera;', NULL),
(1056, 3647, 8, 11, 'menjelang waktu senja pulanglah burung merpati itu mendapatkan Nuh, dan pada paruhnya dibawanya sehelai daun zaitun yang segar. Dari situlah diketahui Nuh, bahwa air itu telah berkurang dari atas bumi.', NULL),
(1057, 3647, 8, 12, 'Selanjutnya ditunggunya pula tujuh hari lagi, kemudian dilepaskannya burung merpati itu, tetapi burung itu tidak kembali lagi kepadanya.', NULL),
(1058, 3647, 8, 13, 'Dalam tahun keenam ratus satu, dalam bulan pertama, pada tanggal satu bulan itu, sudahlah kering air itu dari atas bumi; kemudian Nuh membuka tutup bahtera itu dan melihat-lihat; ternyatalah muka bumi sudah mulai kering.', NULL),
(1059, 3647, 8, 14, 'Dalam bulan kedua, pada hari yang kedua puluh tujuh bulan itu, bumi telah kering.', NULL),
(1060, 3647, 8, 15, 'Lalu berfirmanlah Allah kepada Nuh:', NULL),
(1061, 3647, 8, 16, '\"Keluarlah dari bahtera itu, engkau bersama-sama dengan isterimu serta anak-anakmu dan isteri anak-anakmu;', NULL),
(1062, 3647, 8, 17, 'segala binatang yang bersama-sama dengan engkau, segala yang hidup: burung-burung, hewan dan segala binatang melata yang merayap di bumi, suruhlah keluar bersama-sama dengan engkau, supaya semuanya itu berkeriapan di bumi serta berkembang biak dan bertambah banyak di bumi.\"', NULL),
(1063, 3647, 8, 18, 'Lalu keluarlah Nuh bersama-sama dengan anak-anaknya dan isterinya dan isteri anak-anaknya.', NULL),
(1064, 3647, 8, 19, 'Segala binatang liar, segala binatang melata dan segala burung, semuanya yang bergerak di bumi, masing-masing menurut jenisnya, keluarlah juga dari bahtera itu.', NULL),
(1065, 3647, 8, 20, 'Lalu Nuh mendirikan mezbah bagi TUHAN; dari segala binatang yang tidak haram dan dari segala burung yang tidak haram diambilnyalah beberapa ekor, lalu ia mempersembahkan korban bakaran di atas mezbah itu.', NULL),
(1066, 3647, 8, 21, 'Ketika TUHAN mencium persembahan yang harum itu, berfirmanlah TUHAN dalam hati-Nya: \"Aku takkan mengutuk bumi ini lagi karena manusia, sekalipun yang ditimbulkan hatinya adalah jahat dari sejak kecilnya, dan Aku takkan membinasakan lagi segala yang hidup seperti yang telah Kulakukan.', NULL),
(1067, 3647, 8, 22, 'Selama bumi masih ada, takkan berhenti-henti musim menabur dan menuai, dingin dan panas, kemarau dan hujan, siang dan malam.\"', NULL),
(1276, 3647, 9, 1, 'Lalu Allah memberkati Nuh dan anak-anaknya serta berfirman kepada mereka: \"Beranakcuculah dan bertambah banyaklah serta penuhilah bumi.', 'Perjanjian Allah dengan Nuh'),
(1277, 3647, 9, 2, 'Akan takut dan akan gentar kepadamu segala binatang di bumi dan segala burung di udara, segala yang bergerak di muka bumi dan segala ikan di laut; ke dalam tanganmulah semuanya itu diserahkan.', NULL),
(1278, 3647, 9, 3, 'Segala yang bergerak, yang hidup, akan menjadi makananmu. Aku telah memberikan semuanya itu kepadamu seperti juga tumbuh-tumbuhan hijau.', NULL),
(1279, 3647, 9, 4, 'Hanya daging yang masih ada nyawanya, yakni darahnya, janganlah kamu makan.', NULL),
(1280, 3647, 9, 5, 'Tetapi mengenai darah kamu, yakni nyawa kamu, Aku akan menuntut balasnya; dari segala binatang Aku akan menuntutnya, dan dari setiap manusia Aku akan menuntut nyawa sesama manusia.', NULL),
(1281, 3647, 9, 6, 'Siapa yang menumpahkan darah manusia, darahnya akan tertumpah oleh manusia, sebab Allah membuat manusia itu menurut gambar-Nya sendiri.', NULL),
(1282, 3647, 9, 7, 'Dan kamu, beranakcuculah dan bertambah banyak, sehingga tak terbilang jumlahmu di atas bumi, ya, bertambah banyaklah di atasnya.\"', NULL),
(1283, 3647, 9, 8, 'Berfirmanlah Allah kepada Nuh dan kepada anak-anaknya yang bersama-sama dengan dia:', NULL),
(1284, 3647, 9, 9, '\"Sesungguhnya Aku mengadakan perjanjian-Ku dengan kamu dan dengan keturunanmu,', NULL),
(1285, 3647, 9, 10, 'dan dengan segala makhluk hidup yang bersama-sama dengan kamu: burung-burung, ternak dan binatang-binatang liar di bumi yang bersama-sama dengan kamu, segala yang keluar dari bahtera itu, segala binatang di bumi.', NULL),
(1286, 3647, 9, 11, 'Maka Kuadakan perjanjian-Ku dengan kamu, bahwa sejak ini tidak ada yang hidup yang akan dilenyapkan oleh air bah lagi, dan tidak akan ada lagi air bah untuk memusnahkan bumi.\"', NULL),
(1287, 3647, 9, 12, 'Dan Allah berfirman: \"Inilah tanda perjanjian yang Kuadakan antara Aku dan kamu serta segala makhluk yang hidup, yang bersama-sama dengan kamu, turun-temurun, untuk selama-lamanya:', NULL),
(1288, 3647, 9, 13, 'Busur-Ku Kutaruh di awan, supaya itu menjadi tanda perjanjian antara Aku dan bumi.', NULL),
(1289, 3647, 9, 14, 'Apabila kemudian Kudatangkan awan di atas bumi dan busur itu tampak di awan,', NULL),
(1290, 3647, 9, 15, 'maka Aku akan mengingat perjanjian-Ku yang telah ada antara Aku dan kamu serta segala makhluk yang hidup, segala yang bernyawa, sehingga segenap air tidak lagi menjadi air bah untuk memusnahkan segala yang hidup.', NULL),
(1291, 3647, 9, 16, 'Jika busur itu ada di awan, maka Aku akan melihatnya, sehingga Aku mengingat perjanjian-Ku yang kekal antara Allah dan segala makhluk yang hidup, segala makhluk yang ada di bumi.\"', NULL),
(1292, 3647, 9, 17, 'Berfirmanlah Allah kepada Nuh: \"Inilah tanda perjanjian yang Kuadakan antara Aku dan segala makhluk yang ada di bumi.\"', NULL),
(1293, 3647, 9, 18, 'Anak-anak Nuh yang keluar dari bahtera ialah Sem, Ham dan Yafet; Ham adalah bapa Kanaan.', 'Nuh menjadi Petani'),
(1294, 3647, 9, 19, 'Yang tiga inilah anak-anak Nuh, dan dari mereka inilah tersebar penduduk seluruh bumi.', NULL),
(1295, 3647, 9, 20, 'Nuh menjadi petani; dialah yang mula-mula membuat kebun anggur.', NULL),
(1296, 3647, 9, 21, 'Setelah ia minum anggur, mabuklah ia dan ia telanjang dalam kemahnya.', NULL),
(1297, 3647, 9, 22, 'Maka Ham, bapa Kanaan itu, melihat aurat ayahnya, lalu diceritakannya kepada kedua saudaranya di luar.', NULL),
(1298, 3647, 9, 23, 'Sesudah itu Sem dan Yafet mengambil sehelai kain dan membentangkannya pada bahu mereka berdua, lalu mereka berjalan mundur; mereka menutupi aurat ayahnya sambil berpaling muka, sehingga mereka tidak melihat aurat ayahnya.', NULL),
(1299, 3647, 9, 24, 'Setelah Nuh sadar dari mabuknya dan mendengar apa yang dilakukan anak bungsunya kepadanya,', NULL),
(1300, 3647, 9, 25, 'berkatalah ia: \"Terkutuklah Kanaan, hendaklah ia menjadi hamba yang paling hina bagi saudara-saudaranya.\"', NULL),
(1301, 3647, 9, 26, 'Lagi katanya: \"Terpujilah TUHAN, Allah Sem, tetapi hendaklah Kanaan menjadi hamba baginya.', NULL),
(1302, 3647, 9, 27, 'Allah meluaskan kiranya tempat kediaman Yafet, dan hendaklah ia tinggal dalam kemah-kemah Sem, tetapi hendaklah Kanaan menjadi hamba baginya.\"', NULL),
(1303, 3647, 9, 28, 'Nuh masih hidup tiga ratus lima puluh tahun sesudah air bah.', NULL),
(1304, 3647, 9, 29, 'Jadi Nuh mencapai umur sembilan ratus lima puluh tahun, lalu ia mati.', NULL),
(1542, 3647, 10, 1, ',Inilah keturunan Sem, Ham dan Yafet, anak-anak Nuh. Setelah air bah itu lahirlah anak-anak lelaki bagi mereka.', 'Daftar bangsa-bangsa keturunan Sem, Ham dan Yafet'),
(1543, 3647, 10, 2, 'Keturunan Yafet ialah Gomer, Magog, Madai, Yawan, Tubal, Mesekh dan Tiras.', NULL),
(1544, 3647, 10, 3, 'Keturunan Gomer ialah Askenas, Rifat dan Togarma.', NULL),
(1545, 3647, 10, 4, 'Keturunan Yawan ialah Elisa, Tarsis, orang Kitim dan orang Dodanim.', NULL),
(1546, 3647, 10, 5, 'Dari mereka inilah berpencar bangsa-bangsa daerah pesisir. Itulah keturunan Yafet, masing-masing di tanahnya, dengan bahasanya sendiri, menurut kaum dan bangsa mereka.', NULL),
(1547, 3647, 10, 6, 'Keturunan Ham ialah Kush, Misraim, Put dan Kanaan.', NULL),
(1548, 3647, 10, 7, 'Keturunan Kush ialah Seba, Hawila, Sabta, Raema dan Sabtekha; anak-anak Raema ialah Syeba dan Dedan.', NULL),
(1549, 3647, 10, 8, 'Kush memperanakkan Nimrod; dialah yang mula-mula sekali orang yang berkuasa di bumi;', NULL),
(1550, 3647, 10, 9, 'ia seorang pemburu yang gagah perkasa di hadapan TUHAN, sebab itu dikatakan orang: \"Seperti Nimrod, seorang pemburu yang gagah perkasa di hadapan TUHAN.\"', NULL),
(1551, 3647, 10, 10, 'Mula-mula kerajaannya terdiri dari Babel, Erekh, dan Akad, semuanya di tanah Sinear.', NULL),
(1552, 3647, 10, 11, 'Dari negeri itu ia pergi ke Asyur, lalu mendirikan Niniwe, Rehobot-Ir, Kalah', NULL),
(1553, 3647, 10, 12, 'dan Resen di antara Niniwe dan Kalah; itulah kota besar itu.', NULL),
(1554, 3647, 10, 13, 'Misraim memperanakkan orang Ludim, orang Anamim, orang Lehabim, orang Naftuhim,', NULL),
(1555, 3647, 10, 14, 'orang Patrusim, orang Kasluhim dan orang Kaftorim; dari mereka inilah berasal orang Filistin.', NULL),
(1556, 3647, 10, 15, 'Kanaan memperanakkan Sidon, anak sulungnya, dan Het,', NULL),
(1557, 3647, 10, 16, 'serta orang Yebusi, orang Amori dan orang Girgasi;', NULL),
(1558, 3647, 10, 17, 'orang Hewi, orang Arki, orang Sini,', NULL),
(1559, 3647, 10, 18, 'orang Arwadi, orang Semari dan orang Hamati; kemudian berseraklah kaum-kaum orang Kanaan itu.', NULL),
(1560, 3647, 10, 19, 'Daerah orang Kanaan adalah dari Sidon ke arah Gerar sampai ke Gaza, ke arah Sodom, Gomora, Adma dan Zeboim sampai ke Lasa.', NULL),
(1561, 3647, 10, 20, 'Itulah keturunan Ham menurut kaum mereka, menurut bahasa mereka, menurut tanah mereka, menurut bangsa mereka.', NULL),
(1562, 3647, 10, 21, 'Lahirlah juga anak-anak bagi Sem, bapa semua anak Eber serta abang Yafet.', NULL),
(1563, 3647, 10, 22, 'Keturunan Sem ialah Elam, Asyur, Arpakhsad, Lud dan Aram.', NULL),
(1564, 3647, 10, 23, 'Keturunan Aram ialah Us, Hul, Geter dan Mas.', NULL),
(1565, 3647, 10, 24, 'Arpakhsad memperanakkan Selah, dan Selah memperanakkan Eber.', NULL),
(1566, 3647, 10, 25, 'Bagi Eber lahir dua anak laki-laki; nama yang seorang ialah Peleg, sebab dalam zamannya bumi terbagi, dan nama adiknya ialah Yoktan.', NULL),
(1567, 3647, 10, 26, 'Yoktan memperanakkan Almodad, Selef, Hazar-Mawet dan Yerah,', NULL),
(1568, 3647, 10, 27, 'Hadoram, Uzal dan Dikla,', NULL),
(1569, 3647, 10, 28, 'Obal, Abimael dan Syeba,', NULL),
(1570, 3647, 10, 29, 'Ofir, Hawila dan Yobab; itulah semuanya keturunan Yoktan.', NULL),
(1571, 3647, 10, 30, 'Daerah kediaman mereka terbentang dari Mesa ke arah Sefar, yaitu pegunungan di sebelah timur.', NULL),
(1572, 3647, 10, 31, 'Itulah keturunan Sem, menurut kaum mereka, menurut bahasa mereka, menurut tanah mereka, menurut bangsa mereka.', NULL),
(1573, 3647, 10, 32, 'Itulah segala kaum anak-anak Nuh menurut keturunan mereka, menurut bangsa mereka. Dan dari mereka itulah berpencar bangsa-bangsa di bumi setelah air bah itu.', NULL),
(1574, 3647, 11, 1, 'Adapun seluruh bumi, satu bahasanya dan satu logatnya.', 'Menara Babel'),
(1575, 3647, 11, 2, 'Maka berangkatlah mereka ke sebelah timur dan menjumpai tanah datar di tanah Sinear, lalu menetaplah mereka di sana.', NULL),
(1576, 3647, 11, 3, 'Mereka berkata seorang kepada yang lain: \"Marilah kita membuat batu bata dan membakarnya baik-baik.\" Lalu bata itulah dipakai mereka sebagai batu dan ter gala-gala sebagai tanah liat.', NULL),
(1577, 3647, 11, 4, 'Juga kata mereka: \"Marilah kita dirikan bagi kita sebuah kota dengan sebuah menara yang puncaknya sampai ke langit, dan marilah kita cari nama, supaya kita jangan terserak ke seluruh bumi.\"', NULL),
(1578, 3647, 11, 5, 'Lalu turunlah TUHAN untuk melihat kota dan menara yang didirikan oleh anak-anak manusia itu,', NULL),
(1579, 3647, 11, 6, 'dan Ia berfirman: \"Mereka ini satu bangsa dengan satu bahasa untuk semuanya. Ini barulah permulaan usaha mereka; mulai dari sekarang apapun juga yang mereka rencanakan, tidak ada yang tidak akan dapat terlaksana.', NULL),
(1580, 3647, 11, 7, 'Baiklah Kita turun dan mengacaubalaukan di sana bahasa mereka, sehingga mereka tidak mengerti lagi bahasa masing-masing.\"', NULL),
(1581, 3647, 11, 8, 'Demikianlah mereka diserakkan TUHAN dari situ ke seluruh bumi, dan mereka berhenti mendirikan kota itu.', NULL),
(1582, 3647, 11, 9, 'Itulah sebabnya sampai sekarang nama kota itu disebut Babel, karena di situlah dikacaubalaukan TUHAN bahasa seluruh bumi dan dari situlah mereka diserakkan TUHAN ke seluruh bumi.', NULL),
(1583, 3647, 11, 10, 'Inilah keturunan Sem. Setelah Sem berumur seratus tahun, ia memperanakkan Arpakhsad, dua tahun setelah air bah itu.', 'Keturunan Sem'),
(1584, 3647, 11, 11, 'Sem masih hidup lima ratus tahun, setelah ia memperanakkan Arpakhsad, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1585, 3647, 11, 12, 'Setelah Arpakhsad hidup tiga puluh lima tahun, ia memperanakkan Selah.', NULL),
(1586, 3647, 11, 13, 'Arpakhsad masih hidup empat ratus tiga tahun, setelah ia memperanakkan Selah, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1587, 3647, 11, 14, 'Setelah Selah hidup tiga puluh tahun, ia memperanakkan Eber.', NULL),
(1588, 3647, 11, 15, 'Selah masih hidup empat ratus tiga tahun, setelah ia memperanakkan Eber, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1589, 3647, 11, 16, 'Setelah Eber hidup tiga puluh empat tahun, ia memperanakkan Peleg.', NULL),
(1590, 3647, 11, 17, 'Eber masih hidup empat ratus tiga puluh tahun, setelah ia memperanakkan Peleg, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1591, 3647, 11, 18, 'Setelah Peleg hidup tiga puluh tahun, ia memperanakkan Rehu.', NULL),
(1592, 3647, 11, 19, 'Peleg masih hidup dua ratus sembilan tahun, setelah ia memperanakkan Rehu, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1593, 3647, 11, 20, 'Setelah Rehu hidup tiga puluh dua tahun, ia memperanakkan Serug.', NULL),
(1594, 3647, 11, 21, 'Rehu masih hidup dua ratus tujuh tahun, setelah ia memperanakkan Serug, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1595, 3647, 11, 22, 'Setelah Serug hidup tiga puluh tahun, ia memperanakkan Nahor.', NULL),
(1596, 3647, 11, 23, 'Serug masih hidup dua ratus tahun, setelah ia memperanakkan Nahor, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1597, 3647, 11, 24, 'Setelah Nahor hidup dua puluh sembilan tahun, ia memperanakkan Terah.', NULL),
(1598, 3647, 11, 25, 'Nahor masih hidup seratus sembilan belas tahun, setelah ia memperanakkan Terah, dan ia memperanakkan anak-anak lelaki dan perempuan.', NULL),
(1599, 3647, 11, 26, 'Setelah Terah hidup tujuh puluh tahun, ia memperanakkan Abram, Nahor dan Haran.', NULL),
(1600, 3647, 11, 27, 'Inilah keturunan Terah. Terah memperanakkan Abram, Nahor dan Haran, dan Haran memperanakkan Lot.', 'Keturunan Terah'),
(1601, 3647, 11, 28, 'Ketika Terah, ayahnya, masih hidup, matilah Haran di negeri kelahirannya, di Ur-Kasdim.', NULL),
(1602, 3647, 11, 29, 'Abram dan Nahor kedua-duanya kawin; nama isteri Abram ialah Sarai, dan nama isteri Nahor ialah Milka, anak Haran ayah Milka dan Yiska.', NULL),
(1603, 3647, 11, 30, 'Sarai itu mandul, tidak mempunyai anak.', NULL),
(1604, 3647, 11, 31, 'Lalu Terah membawa Abram, anaknya, serta cucunya, Lot, yaitu anak Haran, dan Sarai, menantunya, isteri Abram, anaknya; ia berangkat bersama-sama dengan mereka dari Ur-Kasdim untuk pergi ke tanah Kanaan, lalu sampailah mereka ke Haran, dan menetap di sana.', NULL),
(1605, 3647, 11, 32, 'Umur Terah ada dua ratus lima tahun; lalu ia mati di Haran.', NULL),
(1606, 3647, 12, 1, 'Berfirmanlah TUHAN kepada Abram: \"Pergilah dari negerimu dan dari sanak saudaramu dan dari rumah bapamu ini ke negeri yang akan Kutunjukkan kepadamu;', 'Abram dipanggil Allah'),
(1607, 3647, 12, 2, 'Aku akan membuat engkau menjadi bangsa yang besar, dan memberkati engkau serta membuat namamu masyhur; dan engkau akan menjadi berkat.', NULL),
(1608, 3647, 12, 3, 'Aku akan memberkati orang-orang yang memberkati engkau, dan mengutuk orang-orang yang mengutuk engkau, dan olehmu semua kaum di muka bumi akan mendapat berkat.\"', NULL),
(1609, 3647, 12, 4, 'Lalu pergilah Abram seperti yang difirmankan TUHAN kepadanya, dan Lotpun ikut bersama-sama dengan dia; Abram berumur tujuh puluh lima tahun, ketika ia berangkat dari Haran.', NULL),
(1610, 3647, 12, 5, 'Abram membawa Sarai, isterinya, dan Lot, anak saudaranya, dan segala harta benda yang didapat mereka dan orang-orang yang diperoleh mereka di Haran; mereka berangkat ke tanah Kanaan, lalu sampai di situ.', NULL),
(1611, 3647, 12, 6, 'Abram berjalan melalui negeri itu sampai ke suatu tempat dekat Sikhem, yakni pohon tarbantin di More. Waktu itu orang Kanaan diam di negeri itu.', NULL),
(1612, 3647, 12, 7, 'Ketika itu TUHAN menampakkan diri kepada Abram dan berfirman: \"Aku akan memberikan negeri ini kepada keturunanmu.\" Maka didirikannya di situ mezbah bagi TUHAN yang telah menampakkan diri kepadanya.', NULL),
(1613, 3647, 12, 8, 'Kemudian ia pindah dari situ ke pegunungan di sebelah timur Betel. Ia memasang kemahnya dengan Betel di sebelah barat dan Ai di sebelah timur, lalu ia mendirikan di situ mezbah bagi TUHAN dan memanggil nama TUHAN.', NULL),
(1614, 3647, 12, 9, 'Sesudah itu Abram berangkat dan makin jauh ia berjalan ke Tanah Negeb.', NULL),
(1615, 3647, 12, 10, 'Ketika kelaparan timbul di negeri itu, pergilah Abram ke Mesir untuk tinggal di situ sebagai orang asing, sebab hebat kelaparan di negeri itu.', 'Abram di Mesir'),
(1616, 3647, 12, 11, 'Pada waktu ia akan masuk ke Mesir, berkatalah ia kepada Sarai, isterinya: \"Memang aku tahu, bahwa engkau adalah seorang perempuan yang cantik parasnya.', NULL),
(1617, 3647, 12, 12, 'Apabila orang Mesir melihat engkau, mereka akan berkata: Itu isterinya. Jadi mereka akan membunuh aku dan membiarkan engkau hidup.', NULL),
(1618, 3647, 12, 13, 'Katakanlah, bahwa engkau adikku, supaya aku diperlakukan mereka dengan baik karena engkau, dan aku dibiarkan hidup oleh sebab engkau.\"', NULL),
(1619, 3647, 12, 14, 'Sesudah Abram masuk ke Mesir, orang Mesir itu melihat, bahwa perempuan itu sangat cantik,', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(1620, 3647, 12, 15, 'dan ketika punggawa-punggawa Firaun melihat Sarai, mereka memuji-mujinya di hadapan Firaun, sehingga perempuan itu dibawa ke istananya.', NULL),
(1621, 3647, 12, 16, 'Firaun menyambut Abram dengan baik-baik, karena ia mengingini perempuan itu, dan Abram mendapat kambing domba, lembu sapi, keledai jantan, budak laki-laki dan perempuan, keledai betina dan unta.', NULL),
(1622, 3647, 12, 17, 'Tetapi TUHAN menimpakan tulah yang hebat kepada Firaun, demikian juga kepada seisi istananya, karena Sarai, isteri Abram itu.', NULL),
(1623, 3647, 12, 18, 'Lalu Firaun memanggil Abram serta berkata: \"Apakah yang kauperbuat ini terhadap aku? Mengapa tidak kauberitahukan, bahwa ia isterimu?', NULL),
(1624, 3647, 12, 19, 'Mengapa engkau katakan: dia adikku, sehingga aku mengambilnya menjadi isteriku? Sekarang, inilah isterimu, ambillah dan pergilah!\"', NULL),
(1625, 3647, 12, 20, 'Lalu Firaun memerintahkan beberapa orang untuk mengantarkan Abram pergi, bersama-sama dengan isterinya dan segala kepunyaannya.', NULL),
(1947, 3647, 13, 1, 'Maka pergilah Abram dari Mesir ke Tanah Negeb dengan isterinya dan segala kepunyaannya, dan Lotpun bersama-sama dengan dia.', 'Abram dan Lot berpisah'),
(1948, 3647, 13, 2, 'Adapun Abram sangat kaya, banyak ternak, perak dan emasnya.', NULL),
(1949, 3647, 13, 3, 'Ia berjalan dari tempat persinggahan ke tempat persinggahan, dari Tanah Negeb sampai dekat Betel, di mana kemahnya mula-mula berdiri, antara Betel dan Ai,', NULL),
(1950, 3647, 13, 4, 'ke tempat mezbah yang dibuatnya dahulu di sana; di situlah Abram memanggil nama TUHAN.', NULL),
(1951, 3647, 13, 5, 'Juga Lot, yang ikut bersama-sama dengan Abram, mempunyai domba dan lembu dan kemah.', NULL),
(1952, 3647, 13, 6, 'Tetapi negeri itu tidak cukup luas bagi mereka untuk diam bersama-sama, sebab harta milik mereka amat banyak, sehingga mereka tidak dapat diam bersama-sama.', NULL),
(1953, 3647, 13, 7, 'Karena itu terjadilah perkelahian antara para gembala Abram dan para gembala Lot. Waktu itu orang Kanaan dan orang Feris diam di negeri itu.', NULL),
(1954, 3647, 13, 8, 'Maka berkatalah Abram kepada Lot: \"Janganlah kiranya ada perkelahian antara aku dan engkau, dan antara para gembalaku dan para gembalamu, sebab kita ini kerabat.', NULL),
(1955, 3647, 13, 9, 'Bukankah seluruh negeri ini terbuka untuk engkau? Baiklah pisahkan dirimu dari padaku; jika engkau ke kiri, maka aku ke kanan, jika engkau ke kanan, maka aku ke kiri.\"', NULL),
(1956, 3647, 13, 10, 'Lalu Lot melayangkan pandangnya dan dilihatnyalah, bahwa seluruh Lembah Yordan banyak airnya, seperti taman TUHAN, seperti tanah Mesir, sampai ke Zoar. --Hal itu terjadi sebelum TUHAN memusnahkan Sodom dan Gomora. --', NULL),
(1957, 3647, 13, 11, 'Sebab itu Lot memilih baginya seluruh Lembah Yordan itu, lalu ia berangkat ke sebelah timur dan mereka berpisah.', NULL),
(1958, 3647, 13, 12, 'Abram menetap di tanah Kanaan, tetapi Lot menetap di kota-kota Lembah Yordan dan berkemah di dekat Sodom.', NULL),
(1959, 3647, 13, 13, 'Adapun orang Sodom sangat jahat dan berdosa terhadap TUHAN.', NULL),
(1960, 3647, 13, 14, 'Setelah Lot berpisah dari pada Abram, berfirmanlah TUHAN kepada Abram: \"Pandanglah sekelilingmu dan lihatlah dari tempat engkau berdiri itu ke timur dan barat, utara dan selatan,', NULL),
(1961, 3647, 13, 15, 'sebab seluruh negeri yang kaulihat itu akan Kuberikan kepadamu dan kepada keturunanmu untuk selama-lamanya.', NULL),
(1962, 3647, 13, 16, 'Dan Aku akan menjadikan keturunanmu seperti debu tanah banyaknya, sehingga, jika seandainya ada yang dapat menghitung debu tanah, keturunanmupun akan dapat dihitung juga.', NULL),
(1963, 3647, 13, 17, 'Bersiaplah, jalanilah negeri itu menurut panjang dan lebarnya, sebab kepadamulah akan Kuberikan negeri itu.\"', NULL),
(1964, 3647, 13, 18, 'Sesudah itu Abram memindahkan kemahnya dan menetap di dekat pohon-pohon tarbantin di Mamre, dekat Hebron, lalu didirikannyalah mezbah di situ bagi TUHAN.', NULL),
(1965, 3647, 14, 1, 'Pada zaman Amrafel, raja Sinear, Ariokh, raja Elasar, Kedorlaomer, raja Elam, dan Tideal, raja Goyim, terjadilah,', 'Abram mengalahkan raja-raja di Timur dan menolong Lot'),
(1966, 3647, 14, 2, 'bahwa raja-raja ini berperang melawan Bera, raja Sodom, Birsya, raja Gomora, Syinab, raja Adma, Syemeber, raja Zeboim dan raja negeri Bela, yakni negeri Zoar.', NULL),
(1967, 3647, 14, 3, 'Raja-raja yang disebut terakhir ini semuanya bersekutu dan datang ke lembah Sidim, yakni Laut Asin.', NULL),
(1968, 3647, 14, 4, 'Dua belas tahun lamanya mereka takluk kepada Kedorlaomer, tetapi dalam tahun yang ketiga belas mereka memberontak.', NULL),
(1969, 3647, 14, 5, 'Dalam tahun yang keempat belas datanglah Kedorlaomer serta raja-raja yang bersama-sama dengan dia, lalu mereka mengalahkan orang Refaim di Asyterot-Karnaim, orang Zuzim di Ham, orang Emim di Syawe-Kiryataim', NULL),
(1970, 3647, 14, 6, 'dan orang Hori di pegunungan mereka yang bernama Seir, sampai ke El-Paran di tepi padang gurun.', NULL),
(1971, 3647, 14, 7, 'Sesudah itu baliklah mereka dan sampai ke En-Mispat, yakni Kadesh, dan mengalahkan seluruh daerah orang Amalek, dan juga orang Amori, yang diam di Hazezon-Tamar.', NULL),
(1972, 3647, 14, 8, 'Lalu keluarlah raja negeri Sodom, raja negeri Gomora, raja negeri Adma, raja negeri Zeboim dan raja negeri Bela, yakni negeri Zoar, dan mengatur barisan perangnya melawan mereka di lembah Sidim,', NULL),
(1973, 3647, 14, 9, 'melawan Kedorlaomer, raja Elam, Tideal, raja Goyim, Amrafel, raja Sinear, dan Ariokh, raja Elasar, empat raja lawan lima.', NULL),
(1974, 3647, 14, 10, 'Di lembah Sidim itu di mana-mana ada sumur aspal. Ketika raja Sodom dan raja Gomora melarikan diri, jatuhlah mereka ke dalamnya, dan orang-orang yang masih tinggal hidup melarikan diri ke pegunungan.', NULL),
(1975, 3647, 14, 11, 'Segala harta benda Sodom dan Gomora beserta segala bahan makanan dirampas musuh, lalu mereka pergi.', NULL),
(1976, 3647, 14, 12, 'Juga Lot, anak saudara Abram, beserta harta bendanya, dibawa musuh, lalu mereka pergi--sebab Lot itu diam di Sodom.', NULL),
(1977, 3647, 14, 13, 'Kemudian datanglah seorang pelarian dan menceritakan hal ini kepada Abram, orang Ibrani itu, yang tinggal dekat pohon-pohon tarbantin kepunyaan Mamre, orang Amori itu, saudara Eskol dan Aner, yakni teman-teman sekutu Abram.', NULL),
(1978, 3647, 14, 14, 'Ketika Abram mendengar, bahwa anak saudaranya tertawan, maka dikerahkannyalah orang-orangnya yang terlatih, yakni mereka yang lahir di rumahnya, tiga ratus delapan belas orang banyaknya, lalu mengejar musuh sampai ke Dan.', NULL),
(1979, 3647, 14, 15, 'Dan pada waktu malam berbagilah mereka, ia dan hamba-hambanya itu, untuk melawan musuh; mereka mengalahkan dan mengejar musuh sampai ke Hoba di sebelah utara Damsyik.', NULL),
(1980, 3647, 14, 16, 'Dibawanyalah kembali segala harta benda itu; juga Lot, anak saudaranya itu, serta harta bendanya dibawanya kembali, demikian juga perempuan-perempuan dan orang-orangnya.', NULL),
(1981, 3647, 14, 17, 'Setelah Abram kembali dari mengalahkan Kedorlaomer dan para raja yang bersama-sama dengan dia, maka keluarlah raja Sodom menyongsong dia ke lembah Syawe, yakni Lembah Raja.', 'Pertemuan Abram dengan Melkisedek'),
(1982, 3647, 14, 18, 'Melkisedek, raja Salem, membawa roti dan anggur; ia seorang imam Allah Yang Mahatinggi.', NULL),
(1983, 3647, 14, 19, 'Lalu ia memberkati Abram, katanya: \"Diberkatilah kiranya Abram oleh Allah Yang Mahatinggi, Pencipta langit dan bumi,', NULL),
(1984, 3647, 14, 20, 'dan terpujilah Allah Yang Mahatinggi, yang telah menyerahkan musuhmu ke tanganmu.\" Lalu Abram memberikan kepadanya sepersepuluh dari semuanya.', NULL),
(1985, 3647, 14, 21, 'Berkatalah raja Sodom itu kepada Abram: \"Berikanlah kepadaku orang-orang itu, dan ambillah untukmu harta benda itu.\"', NULL),
(1986, 3647, 14, 22, 'Tetapi kata Abram kepada raja negeri Sodom itu: \"Aku bersumpah demi TUHAN, Allah Yang Mahatinggi, Pencipta langit dan bumi:', NULL),
(1987, 3647, 14, 23, 'Aku tidak akan mengambil apa-apa dari kepunyaanmu itu, sepotong benang atau tali kasutpun tidak, supaya engkau jangan dapat berkata: Aku telah membuat Abram menjadi kaya.', NULL),
(1988, 3647, 14, 24, 'Kalau aku, jangan sekali-kali! Hanya apa yang telah dimakan oleh bujang-bujang ini dan juga bagian orang-orang yang pergi bersama-sama dengan aku, yakni Aner, Eskol dan Mamre, biarlah mereka itu mengambil bagiannya masing-masing.\"', NULL),
(1989, 3647, 15, 1, 'Kemudian datanglah firman TUHAN kepada Abram dalam suatu penglihatan: \"Janganlah takut, Abram, Akulah perisaimu; upahmu akan sangat besar.\"', 'Perjanjian Allah dengan Abram; janji tentang keturunannya'),
(1990, 3647, 15, 2, 'Abram menjawab: \"Ya Tuhan ALLAH, apakah yang akan Engkau berikan kepadaku, karena aku akan meninggal dengan tidak mempunyai anak, dan yang akan mewarisi rumahku ialah Eliezer, orang Damsyik itu.\"', NULL),
(1991, 3647, 15, 3, 'Lagi kata Abram: \"Engkau tidak memberikan kepadaku keturunan, sehingga seorang hambaku nanti menjadi ahli warisku.\"', NULL),
(1992, 3647, 15, 4, 'Tetapi datanglah firman TUHAN kepadanya, demikian: \"Orang ini tidak akan menjadi ahli warismu, melainkan anak kandungmu, dialah yang akan menjadi ahli warismu.\"', NULL),
(1993, 3647, 15, 5, 'Lalu TUHAN membawa Abram ke luar serta berfirman: \"Coba lihat ke langit, hitunglah bintang-bintang, jika engkau dapat menghitungnya.\" Maka firman-Nya kepadanya: \"Demikianlah banyaknya nanti keturunanmu.\"', NULL),
(1994, 3647, 15, 6, 'Lalu percayalah Abram kepada TUHAN, maka TUHAN memperhitungkan hal itu kepadanya sebagai kebenaran.', NULL),
(1995, 3647, 15, 7, 'Lagi firman TUHAN kepadanya: \"Akulah TUHAN, yang membawa engkau keluar dari Ur-Kasdim untuk memberikan negeri ini kepadamu menjadi milikmu.\"', NULL),
(1996, 3647, 15, 8, 'Kata Abram: \"Ya Tuhan ALLAH, dari manakah aku tahu, bahwa aku akan memilikinya?\"', NULL),
(1997, 3647, 15, 9, 'Firman TUHAN kepadanya: \"Ambillah bagi-Ku seekor lembu betina berumur tiga tahun, seekor kambing betina berumur tiga tahun, seekor domba jantan berumur tiga tahun, seekor burung tekukur dan seekor anak burung merpati.\"', NULL),
(1998, 3647, 15, 10, 'Diambilnyalah semuanya itu bagi TUHAN, dipotong dua, lalu diletakkannya bagian-bagian itu yang satu di samping yang lain, tetapi burung-burung itu tidak dipotong dua.', NULL),
(1999, 3647, 15, 11, 'Ketika burung-burung buas hinggap pada daging binatang-binatang itu, maka Abram mengusirnya.', NULL),
(2000, 3647, 15, 12, 'Menjelang matahari terbenam, tertidurlah Abram dengan nyenyak. Lalu turunlah meliputinya gelap gulita yang mengerikan.', NULL),
(2001, 3647, 15, 13, 'Firman TUHAN kepada Abram: \"Ketahuilah dengan sesungguhnya bahwa keturunanmu akan menjadi orang asing dalam suatu negeri, yang bukan kepunyaan mereka, dan bahwa mereka akan diperbudak dan dianiaya, empat ratus tahun lamanya.', NULL),
(2002, 3647, 15, 14, 'Tetapi bangsa yang akan memperbudak mereka, akan Kuhukum, dan sesudah itu mereka akan keluar dengan membawa harta benda yang banyak.', NULL),
(2003, 3647, 15, 15, 'Tetapi engkau akan pergi kepada nenek moyangmu dengan sejahtera; engkau akan dikuburkan pada waktu telah putih rambutmu.', NULL),
(2004, 3647, 15, 16, 'Tetapi keturunan yang keempat akan kembali ke sini, sebab sebelum itu kedurjanaan orang Amori itu belum genap.\"', NULL),
(2005, 3647, 15, 17, 'Ketika matahari telah terbenam, dan hari menjadi gelap, maka kelihatanlah perapian yang berasap beserta suluh yang berapi lewat di antara potongan-potongan daging itu.', NULL),
(2006, 3647, 15, 18, 'Pada hari itulah TUHAN mengadakan perjanjian dengan Abram serta berfirman: \"Kepada keturunanmulah Kuberikan negeri ini, mulai dari sungai Mesir sampai ke sungai yang besar itu, sungai Efrat:', NULL),
(2007, 3647, 15, 19, 'yakni tanah orang Keni, orang Kenas, orang Kadmon,', NULL),
(2008, 3647, 15, 20, 'orang Het, orang Feris, orang Refaim,', NULL),
(2009, 3647, 15, 21, 'orang Amori, orang Kanaan, orang Girgasi dan orang Yebus itu.\"', NULL),
(2010, 3647, 16, 1, 'Adapun Sarai, isteri Abram itu, tidak beranak. Ia mempunyai seorang hamba perempuan, orang Mesir, Hagar namanya.', 'Hagar dan Ismael'),
(2011, 3647, 16, 2, 'Berkatalah Sarai kepada Abram: \"Engkau tahu, TUHAN tidak memberi aku melahirkan anak. Karena itu baiklah hampiri hambaku itu; mungkin oleh dialah aku dapat memperoleh seorang anak.\" Dan Abram mendengarkan perkataan Sarai.', NULL),
(2012, 3647, 16, 3, 'Jadi Sarai, isteri Abram itu, mengambil Hagar, hambanya, orang Mesir itu, --yakni ketika Abram telah sepuluh tahun tinggal di tanah Kanaan--,lalu memberikannya kepada Abram, suaminya, untuk menjadi isterinya.', NULL),
(2013, 3647, 16, 4, 'Abram menghampiri Hagar, lalu mengandunglah perempuan itu. Ketika Hagar tahu, bahwa ia mengandung, maka ia memandang rendah akan nyonyanya itu.', NULL),
(2014, 3647, 16, 5, 'Lalu berkatalah Sarai kepada Abram: \"Penghinaan yang kuderita ini adalah tanggung jawabmu; akulah yang memberikan hambaku ke pangkuanmu, tetapi baru saja ia tahu, bahwa ia mengandung, ia memandang rendah akan aku; TUHAN kiranya yang menjadi Hakim antara aku dan engkau.\"', NULL),
(2015, 3647, 16, 6, 'Kata Abram kepada Sarai: \"Hambamu itu di bawah kekuasaanmu; perbuatlah kepadanya apa yang kaupandang baik.\" Lalu Sarai menindas Hagar, sehingga ia lari meninggalkannya.', NULL),
(2016, 3647, 16, 7, 'Lalu Malaikat TUHAN menjumpainya dekat suatu mata air di padang gurun, yakni dekat mata air di jalan ke Syur.', NULL),
(2017, 3647, 16, 8, 'Katanya: \"Hagar, hamba Sarai, dari manakah datangmu dan ke manakah pergimu?\" Jawabnya: \"Aku lari meninggalkan Sarai, nyonyaku.\"', NULL),
(2018, 3647, 16, 9, 'Lalu kata Malaikat TUHAN itu kepadanya: \"Kembalilah kepada nyonyamu, biarkanlah engkau ditindas di bawah kekuasaannya.\"', NULL),
(2019, 3647, 16, 10, 'Lagi kata Malaikat TUHAN itu kepadanya: \"Aku akan membuat sangat banyak keturunanmu, sehingga tidak dapat dihitung karena banyaknya.\"', NULL),
(2020, 3647, 16, 11, 'Selanjutnya kata Malaikat TUHAN itu kepadanya: \"Engkau mengandung dan akan melahirkan seorang anak laki-laki dan akan menamainya Ismael, sebab TUHAN telah mendengar tentang penindasan atasmu itu.', NULL),
(2021, 3647, 16, 12, 'Seorang laki-laki yang lakunya seperti keledai liar, demikianlah nanti anak itu; tangannya akan melawan tiap-tiap orang dan tangan tiap-tiap orang akan melawan dia, dan di tempat kediamannya ia akan menentang semua saudaranya.\"', NULL),
(2022, 3647, 16, 13, 'Kemudian Hagar menamakan TUHAN yang telah berfirman kepadanya itu dengan sebutan: \"Engkaulah El-Roi.\" Sebab katanya: \"Bukankah di sini kulihat Dia yang telah melihat aku?\"', NULL),
(2023, 3647, 16, 14, 'Sebab itu sumur tadi disebutkan orang: sumur Lahai-Roi; letaknya antara Kadesh dan Bered.', NULL),
(2024, 3647, 16, 15, 'Lalu Hagar melahirkan seorang anak laki-laki bagi Abram dan Abram menamai anak yang dilahirkan Hagar itu Ismael.', NULL),
(2025, 3647, 16, 16, 'Abram berumur delapan puluh enam tahun, ketika Hagar melahirkan Ismael baginya.', NULL),
(2426, 3647, 17, 1, 'Ketika Abram berumur sembilan puluh sembilan tahun, maka TUHAN menampakkan diri kepada Abram dan berfirman kepadanya: \"Akulah Allah Yang Mahakuasa, hiduplah di hadapan-Ku dengan tidak bercela.', 'Sunat sebagai tanda perjanjian Allah dengan Abraham'),
(2427, 3647, 17, 2, 'Aku akan mengadakan perjanjian antara Aku dan engkau, dan Aku akan membuat engkau sangat banyak.\"', NULL),
(2428, 3647, 17, 3, 'Lalu sujudlah Abram, dan Allah berfirman kepadanya:', NULL),
(2429, 3647, 17, 4, '\"Dari pihak-Ku, inilah perjanjian-Ku dengan engkau: Engkau akan menjadi bapa sejumlah besar bangsa.', NULL),
(2430, 3647, 17, 5, 'Karena itu namamu bukan lagi Abram, melainkan Abraham, karena engkau telah Kutetapkan menjadi bapa sejumlah besar bangsa.', NULL),
(2431, 3647, 17, 6, 'Aku akan membuat engkau beranak cucu sangat banyak; engkau akan Kubuat menjadi bangsa-bangsa, dan dari padamu akan berasal raja-raja.', NULL),
(2432, 3647, 17, 7, 'Aku akan mengadakan perjanjian antara Aku dan engkau serta keturunanmu turun-temurun menjadi perjanjian yang kekal, supaya Aku menjadi Allahmu dan Allah keturunanmu.', NULL),
(2433, 3647, 17, 8, 'Kepadamu dan kepada keturunanmu akan Kuberikan negeri ini yang kaudiami sebagai orang asing, yakni seluruh tanah Kanaan akan Kuberikan menjadi milikmu untuk selama-lamanya; dan Aku akan menjadi Allah mereka.\"', NULL),
(2434, 3647, 17, 9, 'Lagi firman Allah kepada Abraham: \"Dari pihakmu, engkau harus memegang perjanjian-Ku, engkau dan keturunanmu turun-temurun.', NULL),
(2435, 3647, 17, 10, 'Inilah perjanjian-Ku, yang harus kamu pegang, perjanjian antara Aku dan kamu serta keturunanmu, yaitu setiap laki-laki di antara kamu harus disunat;', NULL),
(2436, 3647, 17, 11, 'haruslah dikerat kulit khatanmu dan itulah akan menjadi tanda perjanjian antara Aku dan kamu.', NULL),
(2437, 3647, 17, 12, 'Anak yang berumur delapan hari haruslah disunat, yakni setiap laki-laki di antara kamu, turun-temurun: baik yang lahir di rumahmu, maupun yang dibeli dengan uang dari salah seorang asing, tetapi tidak termasuk keturunanmu.', NULL),
(2438, 3647, 17, 13, 'Orang yang lahir di rumahmu dan orang yang engkau beli dengan uang harus disunat; maka dalam dagingmulah perjanjian-Ku itu menjadi perjanjian yang kekal.', NULL),
(2439, 3647, 17, 14, 'Dan orang yang tidak disunat, yakni laki-laki yang tidak dikerat kulit khatannya, maka orang itu harus dilenyapkan dari antara orang-orang sebangsanya: ia telah mengingkari perjanjian-Ku.\"', NULL),
(2440, 3647, 17, 15, 'Selanjutnya Allah berfirman kepada Abraham: \"Tentang isterimu Sarai, janganlah engkau menyebut dia lagi Sarai, tetapi Sara, itulah namanya.', NULL),
(2441, 3647, 17, 16, 'Aku akan memberkatinya, dan dari padanya juga Aku akan memberikan kepadamu seorang anak laki-laki, bahkan Aku akan memberkatinya, sehingga ia menjadi ibu bangsa-bangsa; raja-raja bangsa-bangsa akan lahir dari padanya.\"', NULL),
(2442, 3647, 17, 17, 'Lalu tertunduklah Abraham dan tertawa serta berkata dalam hatinya: \"Mungkinkah bagi seorang yang berumur seratus tahun dilahirkan seorang anak dan mungkinkah Sara, yang telah berumur sembilan puluh tahun itu melahirkan seorang anak?\"', NULL),
(2443, 3647, 17, 18, 'Dan Abraham berkata kepada Allah: \"Ah, sekiranya Ismael diperkenankan hidup di hadapan-Mu!\"', NULL),
(2444, 3647, 17, 19, 'Tetapi Allah berfirman: \"Tidak, melainkan isterimu Saralah yang akan melahirkan anak laki-laki bagimu, dan engkau akan menamai dia Ishak, dan Aku akan mengadakan perjanjian-Ku dengan dia menjadi perjanjian yang kekal untuk keturunannya.', NULL),
(2445, 3647, 17, 20, 'Tentang Ismael, Aku telah mendengarkan permintaanmu; ia akan Kuberkati, Kubuat beranak cucu dan sangat banyak; ia akan memperanakkan dua belas raja, dan Aku akan membuatnya menjadi bangsa yang besar.', NULL),
(2446, 3647, 17, 21, 'Tetapi perjanjian-Ku akan Kuadakan dengan Ishak, yang akan dilahirkan Sara bagimu tahun yang akan datang pada waktu seperti ini juga.\"', NULL),
(2447, 3647, 17, 22, 'Setelah selesai berfirman kepada Abraham, naiklah Allah meninggalkan Abraham.', NULL),
(2448, 3647, 17, 23, 'Setelah itu Abraham memanggil Ismael, anaknya, dan semua orang yang lahir di rumahnya, juga semua orang yang dibelinya dengan uang, yakni setiap laki-laki dari isi rumahnya, lalu ia mengerat kulit khatan mereka pada hari itu juga, seperti yang telah difirmankan Allah kepadanya.', NULL),
(2449, 3647, 17, 24, 'Abraham berumur sembilan puluh sembilan tahun ketika dikerat kulit khatannya.', NULL),
(2450, 3647, 17, 25, 'Dan Ismael, anaknya, berumur tiga belas tahun ketika dikerat kulit khatannya.', NULL),
(2451, 3647, 17, 26, 'Pada hari itu juga Abraham dan Ismael, anaknya, disunat.', NULL),
(2452, 3647, 17, 27, 'Dan semua orang dari isi rumah Abraham, baik yang lahir di rumahnya, maupun yang dibeli dengan uang dari orang asing, disunat bersama-sama dengan dia.', NULL),
(2453, 3647, 18, 1, 'Kemudian TUHAN menampakkan diri kepada Abraham dekat pohon tarbantin di Mamre, sedang ia duduk di pintu kemahnya waktu hari panas terik.', 'Allah mengulangi menjanjikan seorang anak laki-laki kepada Abraham'),
(2454, 3647, 18, 2, 'Ketika ia mengangkat mukanya, ia melihat tiga orang berdiri di depannya. Sesudah dilihatnya mereka, ia berlari dari pintu kemahnya menyongsong mereka, lalu sujudlah ia sampai ke tanah,', NULL),
(2455, 3647, 18, 3, 'serta berkata: \"Tuanku, jika aku telah mendapat kasih tuanku, janganlah kiranya lampaui hambamu ini.', NULL),
(2456, 3647, 18, 4, 'Biarlah diambil air sedikit, basuhlah kakimu dan duduklah beristirahat di bawah pohon ini;', NULL),
(2457, 3647, 18, 5, 'biarlah kuambil sepotong roti, supaya tuan-tuan segar kembali; kemudian bolehlah tuan-tuan meneruskan perjalanannya; sebab tuan-tuan telah datang ke tempat hambamu ini.\" Jawab mereka: \"Perbuatlah seperti yang kaukatakan itu.\"', NULL),
(2458, 3647, 18, 6, 'Lalu Abraham segera pergi ke kemah mendapatkan Sara serta berkata: \"Segeralah! Ambil tiga sukat tepung yang terbaik! Remaslah itu dan buatlah roti bundar!\"', NULL),
(2459, 3647, 18, 7, 'Lalu berlarilah Abraham kepada lembu sapinya, ia mengambil seekor anak lembu yang empuk dan baik dagingnya dan memberikannya kepada seorang bujangnya, lalu orang ini segera mengolahnya.', NULL),
(2460, 3647, 18, 8, 'Kemudian diambilnya dadih dan susu serta anak lembu yang telah diolah itu, lalu dihidangkannya di depan orang-orang itu; dan ia berdiri di dekat mereka di bawah pohon itu, sedang mereka makan.', NULL),
(2461, 3647, 18, 9, 'Lalu kata mereka kepadanya: \"Di manakah Sara, isterimu?\" Jawabnya: \"Di sana, di dalam kemah.\"', NULL),
(2462, 3647, 18, 10, 'Dan firman-Nya: \"Sesungguhnya Aku akan kembali tahun depan mendapatkan engkau, pada waktu itulah Sara, isterimu, akan mempunyai seorang anak laki-laki.\" Dan Sara mendengarkan pada pintu kemah yang di belakang-Nya.', NULL),
(2463, 3647, 18, 11, 'Adapun Abraham dan Sara telah tua dan lanjut umurnya dan Sara telah mati haid.', NULL),
(2464, 3647, 18, 12, 'Jadi tertawalah Sara dalam hatinya, katanya: \"Akan berahikah aku, setelah aku sudah layu, sedangkan tuanku sudah tua?\"', NULL),
(2465, 3647, 18, 13, 'Lalu berfirmanlah TUHAN kepada Abraham: \"Mengapakah Sara tertawa dan berkata: Sungguhkah aku akan melahirkan anak, sedangkan aku telah tua?', NULL),
(2466, 3647, 18, 14, 'Adakah sesuatu apapun yang mustahil untuk TUHAN? Pada waktu yang telah ditetapkan itu, tahun depan, Aku akan kembali mendapatkan engkau, pada waktu itulah Sara mempunyai seorang anak laki-laki.\"', NULL),
(2467, 3647, 18, 15, 'Lalu Sara menyangkal, katanya: \"Aku tidak tertawa,\" sebab ia takut; tetapi TUHAN berfirman: \"Tidak, memang engkau tertawa!\"', NULL),
(2468, 3647, 18, 16, 'Lalu berangkatlah orang-orang itu dari situ dan memandang ke arah Sodom; dan Abraham berjalan bersama-sama dengan mereka untuk mengantarkan mereka.', 'Doa syafaat Abraham untuk Sodom'),
(2469, 3647, 18, 17, 'Berpikirlah TUHAN: \"Apakah Aku akan menyembunyikan kepada Abraham apa yang hendak Kulakukan ini?', NULL),
(2470, 3647, 18, 18, 'Bukankah sesungguhnya Abraham akan menjadi bangsa yang besar serta berkuasa, dan oleh dia segala bangsa di atas bumi akan mendapat berkat?', NULL),
(2471, 3647, 18, 19, 'Sebab Aku telah memilih dia, supaya diperintahkannya kepada anak-anaknya dan kepada keturunannya supaya tetap hidup menurut jalan yang ditunjukkan TUHAN, dengan melakukan kebenaran dan keadilan, dan supaya TUHAN memenuhi kepada Abraham apa yang dijanjikan-Nya kepadanya.\"', NULL),
(2472, 3647, 18, 20, 'Sesudah itu berfirmanlah TUHAN: \"Sesungguhnya banyak keluh kesah orang tentang Sodom dan Gomora dan sesungguhnya sangat berat dosanya.', NULL),
(2473, 3647, 18, 21, 'Baiklah Aku turun untuk melihat, apakah benar-benar mereka telah berkelakuan seperti keluh kesah orang yang telah sampai kepada-Ku atau tidak; Aku hendak mengetahuinya.\"', NULL),
(2474, 3647, 18, 22, 'Lalu berpalinglah orang-orang itu dari situ dan berjalan ke Sodom, tetapi Abraham masih tetap berdiri di hadapan TUHAN.', NULL),
(2475, 3647, 18, 23, 'Abraham datang mendekat dan berkata: \"Apakah Engkau akan melenyapkan orang benar bersama-sama dengan orang fasik?', NULL),
(2476, 3647, 18, 24, 'Bagaimana sekiranya ada lima puluh orang benar dalam kota itu? Apakah Engkau akan melenyapkan tempat itu dan tidakkah Engkau mengampuninya karena kelima puluh orang benar yang ada di dalamnya itu?', NULL),
(2477, 3647, 18, 25, 'Jauhlah kiranya dari pada-Mu untuk berbuat demikian, membunuh orang benar bersama-sama dengan orang fasik, sehingga orang benar itu seolah-olah sama dengan orang fasik! Jauhlah kiranya yang demikian dari pada-Mu! Masakan Hakim segenap bumi tidak menghukum dengan adil?\"', NULL),
(2478, 3647, 18, 26, 'TUHAN berfirman: \"Jika Kudapati lima puluh orang benar dalam kota Sodom, Aku akan mengampuni seluruh tempat itu karena mereka.\"', NULL),
(2479, 3647, 18, 27, 'Abraham menyahut: \"Sesungguhnya aku telah memberanikan diri berkata kepada Tuhan, walaupun aku debu dan abu.', NULL),
(2480, 3647, 18, 28, 'Sekiranya kurang lima orang dari kelima puluh orang benar itu, apakah Engkau akan memusnahkan seluruh kota itu karena yang lima itu?\" Firman-Nya: \"Aku tidak memusnahkannya, jika Kudapati empat puluh lima di sana.\"', NULL),
(2481, 3647, 18, 29, 'Lagi Abraham melanjutkan perkataannya kepada-Nya: \"Sekiranya empat puluh didapati di sana?\" Firman-Nya: \"Aku tidak akan berbuat demikian karena yang empat puluh itu.\"', NULL),
(2482, 3647, 18, 30, 'Katanya: \"Janganlah kiranya Tuhan murka, kalau aku berkata sekali lagi. Sekiranya tiga puluh didapati di sana?\" Firman-Nya: \"Aku tidak akan berbuat demikian, jika Kudapati tiga puluh di sana.\"', NULL),
(2483, 3647, 18, 31, 'Katanya: \"Sesungguhnya aku telah memberanikan diri berkata kepada Tuhan. Sekiranya dua puluh didapati di sana?\" Firman-Nya: \"Aku tidak akan memusnahkannya karena yang dua puluh itu.\"', NULL),
(2484, 3647, 18, 32, 'Katanya: \"Janganlah kiranya Tuhan murka, kalau aku berkata lagi sekali ini saja. Sekiranya sepuluh didapati di sana?\" Firman-Nya: \"Aku tidak akan memusnahkannya karena yang sepuluh itu.\"', NULL),
(2485, 3647, 18, 33, 'Lalu pergilah TUHAN, setelah Ia selesai berfirman kepada Abraham; dan kembalilah Abraham ke tempat tinggalnya.', NULL),
(2946, 3647, 19, 1, 'Kedua malaikat itu tiba di Sodom pada waktu petang. Lot sedang duduk di pintu gerbang Sodom dan ketika melihat mereka, bangunlah ia menyongsong mereka, lalu sujud dengan mukanya sampai ke tanah,', 'Sodom dan Gomora dimusnahkan Lot diselamatkan'),
(2947, 3647, 19, 2, 'serta berkata: \"Tuan-tuan, silakanlah singgah ke rumah hambamu ini, bermalamlah di sini dan basuhlah kakimu, maka besok pagi tuan-tuan boleh melanjutkan perjalanannya.\" Jawab mereka: \"Tidak, kami akan bermalam di tanah lapang.\"', NULL),
(2948, 3647, 19, 3, 'Tetapi karena ia sangat mendesak mereka, singgahlah mereka dan masuk ke dalam rumahnya, kemudian ia menyediakan hidangan bagi mereka, ia membakar roti yang tidak beragi, lalu mereka makan.', NULL),
(2949, 3647, 19, 4, 'Tetapi sebelum mereka tidur, orang-orang lelaki dari kota Sodom itu, dari yang muda sampai yang tua, bahkan seluruh kota, tidak ada yang terkecuali, datang mengepung rumah itu.', NULL),
(2950, 3647, 19, 5, 'Mereka berseru kepada Lot: \"Di manakah orang-orang yang datang kepadamu malam ini? Bawalah mereka keluar kepada kami, supaya kami pakai mereka.\"', NULL),
(2951, 3647, 19, 6, 'Lalu keluarlah Lot menemui mereka, ke depan pintu, tetapi pintu ditutupnya di belakangnya,', NULL),
(2952, 3647, 19, 7, 'dan ia berkata: \"Saudara-saudaraku, janganlah kiranya berbuat jahat.', NULL),
(2953, 3647, 19, 8, 'Kamu tahu, aku mempunyai dua orang anak perempuan yang belum pernah dijamah laki-laki, baiklah mereka kubawa ke luar kepadamu; perbuatlah kepada mereka seperti yang kamu pandang baik; hanya jangan kamu apa-apakan orang-orang ini, sebab mereka memang datang untuk berlindung di dalam rumahku.\"', NULL),
(2954, 3647, 19, 9, 'Tetapi mereka berkata: \"Enyahlah!\" Lagi kata mereka: \"Orang ini datang ke sini sebagai orang asing dan dia mau menjadi hakim atas kita! Sekarang kami akan menganiaya engkau lebih dari pada kedua orang itu!\" Lalu mereka mendesak orang itu, yaitu Lot, dengan keras, dan mereka mendekat untuk mendobrak pintu.', NULL),
(2955, 3647, 19, 10, 'Tetapi kedua orang itu mengulurkan tangannya, menarik Lot masuk ke dalam rumah, lalu menutup pintu.', NULL),
(2956, 3647, 19, 11, 'Dan mereka membutakan mata orang-orang yang di depan pintu rumah itu, dari yang kecil sampai yang besar, sehingga percumalah orang-orang itu mencari-cari pintu.', NULL),
(2957, 3647, 19, 12, 'Lalu kedua orang itu berkata kepada Lot: \"Siapakah kaummu yang ada di sini lagi? Menantu atau anakmu laki-laki, anakmu perempuan, atau siapa saja kaummu di kota ini, bawalah mereka keluar dari tempat ini,', NULL),
(2958, 3647, 19, 13, 'sebab kami akan memusnahkan tempat ini, karena banyak keluh kesah orang tentang kota ini di hadapan TUHAN; sebab itulah TUHAN mengutus kami untuk memusnahkannya.\"', NULL),
(2959, 3647, 19, 14, 'Keluarlah Lot, lalu berbicara dengan kedua bakal menantunya, yang akan kawin dengan kedua anaknya perempuan, katanya: \"Bangunlah, keluarlah dari tempat ini, sebab TUHAN akan memusnahkan kota ini.\" Tetapi ia dipandang oleh kedua bakal menantunya itu sebagai orang yang berolok-olok saja.', NULL),
(2960, 3647, 19, 15, 'Ketika fajar telah menyingsing, kedua malaikat itu mendesak Lot, supaya bersegera, katanya: \"Bangunlah, bawalah isterimu dan kedua anakmu yang ada di sini, supaya engkau jangan mati lenyap karena kedurjanaan kota ini.\"', NULL),
(2961, 3647, 19, 16, 'Ketika ia berlambat-lambat, maka tangannya, tangan isteri dan tangan kedua anaknya dipegang oleh kedua orang itu, sebab TUHAN hendak mengasihani dia; lalu kedua orang itu menuntunnya ke luar kota dan melepaskannya di sana.', NULL),
(2962, 3647, 19, 17, 'Sesudah kedua orang itu menuntun mereka sampai ke luar, berkatalah seorang: \"Larilah, selamatkanlah nyawamu; janganlah menoleh ke belakang, dan janganlah berhenti di manapun juga di Lembah Yordan, larilah ke pegunungan, supaya engkau jangan mati lenyap.\"', NULL),
(2963, 3647, 19, 18, 'Kata Lot kepada mereka: \"Janganlah kiranya demikian, tuanku.', NULL),
(2964, 3647, 19, 19, 'Sungguhlah hambamu ini telah dikaruniai belas kasihan di hadapanmu, dan tuanku telah berbuat kemurahan besar kepadaku dengan memelihara hidupku, tetapi jika aku harus lari ke pegunungan, pastilah aku akan tersusul oleh bencana itu, sehingga matilah aku.', NULL),
(2965, 3647, 19, 20, 'Sungguhlah kota yang di sana itu cukup dekat kiranya untuk lari ke sana; kota itu kecil; izinkanlah kiranya aku lari ke sana. Bukankah kota itu kecil? Jika demikian, nyawaku akan terpelihara.\"', NULL),
(2966, 3647, 19, 21, 'Sahut malaikat itu kepadanya: \"Baiklah, dalam hal inipun permintaanmu akan kuterima dengan baik; yakni kota yang telah kau sebut itu tidak akan kutunggangbalikkan.', NULL),
(2967, 3647, 19, 22, 'Cepatlah, larilah ke sana, sebab aku tidak dapat berbuat apa-apa, sebelum engkau sampai ke sana.\" Itulah sebabnya nama kota itu disebut Zoar.', NULL),
(2968, 3647, 19, 23, 'Matahari telah terbit menyinari bumi, ketika Lot tiba di Zoar.', NULL),
(2969, 3647, 19, 24, 'Kemudian TUHAN menurunkan hujan belerang dan api atas Sodom dan Gomora, berasal dari TUHAN, dari langit;', NULL),
(2970, 3647, 19, 25, 'dan ditunggangbalikkan-Nyalah kota-kota itu dan Lembah Yordan dan semua penduduk kota-kota serta tumbuh-tumbuhan di tanah.', NULL),
(2971, 3647, 19, 26, 'Tetapi isteri Lot, yang berjalan mengikutnya, menoleh ke belakang, lalu menjadi tiang garam.', NULL),
(2972, 3647, 19, 27, 'Ketika Abraham pagi-pagi pergi ke tempat ia berdiri di hadapan TUHAN itu,', NULL),
(2973, 3647, 19, 28, 'dan memandang ke arah Sodom dan Gomora serta ke seluruh tanah Lembah Yordan, maka dilihatnyalah asap dari bumi membubung ke atas sebagai asap dari dapur peleburan.', NULL),
(2974, 3647, 19, 29, 'Demikianlah pada waktu Allah memusnahkan kota-kota di Lembah Yordan dan menunggangbalikkan kota-kota kediaman Lot, maka Allah ingat kepada Abraham, lalu dikeluarkan-Nyalah Lot dari tengah-tengah tempat yang ditunggangbalikkan itu.', NULL),
(2975, 3647, 19, 30, 'Pergilah Lot dari Zoar dan ia menetap bersama-sama dengan kedua anaknya perempuan di pegunungan, sebab ia tidak berani tinggal di Zoar, maka diamlah ia dalam suatu gua beserta kedua anaknya.', 'Lot dan kedua anaknya perempuan'),
(2976, 3647, 19, 31, 'Kata kakaknya kepada adiknya: \"Ayah kita telah tua, dan tidak ada laki-laki di negeri ini yang dapat menghampiri kita, seperti kebiasaan seluruh bumi.', NULL),
(2977, 3647, 19, 32, 'Marilah kita beri ayah kita minum anggur, lalu kita tidur dengan dia, supaya kita menyambung keturunan dari ayah kita.\"', NULL),
(2978, 3647, 19, 33, 'Pada malam itu mereka memberi ayah mereka minum anggur, lalu masuklah yang lebih tua untuk tidur dengan ayahnya; dan ayahnya itu tidak mengetahui ketika anaknya itu tidur dan ketika ia bangun.', NULL),
(2979, 3647, 19, 34, 'Keesokan harinya berkatalah kakaknya kepada adiknya: \"Tadi malam aku telah tidur dengan ayah; baiklah malam ini juga kita beri dia minum anggur; masuklah engkau untuk tidur dengan dia, supaya kita menyambung keturunan dari ayah kita.\"', NULL),
(2980, 3647, 19, 35, 'Demikianlah juga pada malam itu mereka memberi ayah mereka minum anggur, lalu bangunlah yang lebih muda untuk tidur dengan ayahnya; dan ayahnya itu tidak mengetahui ketika anaknya itu tidur dan ketika ia bangun.', NULL),
(2981, 3647, 19, 36, 'Lalu mengandunglah kedua anak Lot itu dari ayah mereka.', NULL),
(2982, 3647, 19, 37, 'Yang lebih tua melahirkan seorang anak laki-laki, dan menamainya Moab; dialah bapa orang Moab yang sekarang.', NULL),
(2983, 3647, 19, 38, 'Yang lebih mudapun melahirkan seorang anak laki-laki, dan menamainya Ben-Ami; dialah bapa bani Amon yang sekarang.', NULL),
(2984, 3647, 20, 1, 'Lalu Abraham berangkat dari situ ke Tanah Negeb dan ia menetap antara Kadesh dan Syur. Ia tinggal di Gerar sebagai orang asing.', 'Abraham dan Abimelekh'),
(2985, 3647, 20, 2, 'Oleh karena Abraham telah mengatakan tentang Sara, isterinya: \"Dia saudaraku,\" maka Abimelekh, raja Gerar, menyuruh mengambil Sara.', NULL),
(2986, 3647, 20, 3, 'Tetapi pada waktu malam Allah datang kepada Abimelekh dalam suatu mimpi serta berfirman kepadanya: \"Engkau harus mati oleh karena perempuan yang telah kauambil itu; sebab ia sudah bersuami.\"', NULL),
(2987, 3647, 20, 4, 'Adapun Abimelekh belum menghampiri Sara. Berkatalah ia: \"Tuhan! Apakah Engkau membunuh bangsa yang tak bersalah?', NULL),
(2988, 3647, 20, 5, 'Bukankah orang itu sendiri mengatakan kepadaku: Dia saudaraku? Dan perempuan itu sendiri telah mengatakan: Ia saudaraku. Jadi hal ini kulakukan dengan hati yang tulus dan dengan tangan yang suci.\"', NULL),
(2989, 3647, 20, 6, 'Lalu berfirmanlah Allah kepadanya dalam mimpi: \"Aku tahu juga, bahwa engkau telah melakukan hal itu dengan hati yang tulus, maka Akupun telah mencegah engkau untuk berbuat dosa terhadap Aku; sebab itu Aku tidak membiarkan engkau menjamah dia.', NULL),
(2990, 3647, 20, 7, 'Jadi sekarang, kembalikanlah isteri orang itu, sebab dia seorang nabi; ia akan berdoa untuk engkau, maka engkau tetap hidup; tetapi jika engkau tidak mengembalikan dia, ketahuilah, engkau pasti mati, engkau dan semua orang yang bersama-sama dengan engkau.\"', NULL),
(2991, 3647, 20, 8, 'Keesokan harinya pagi-pagi Abimelekh memanggil semua hambanya dan memberitahukan seluruh peristiwa itu kepada mereka, lalu sangat takutlah orang-orang itu.', NULL),
(2992, 3647, 20, 9, 'Kemudian Abimelekh memanggil Abraham dan berkata kepadanya: \"Perbuatan apakah yang kaulakukan ini terhadap kami, dan kesalahan apakah yang kulakukan terhadap engkau, sehingga engkau mendatangkan dosa besar atas diriku dan kerajaanku? Engkau telah berbuat hal-hal yang tidak patut kepadaku.\"', NULL),
(2993, 3647, 20, 10, 'Lagi kata Abimelekh kepada Abraham: \"Apakah maksudmu, maka engkau melakukan hal ini?\"', NULL),
(2994, 3647, 20, 11, 'Lalu Abraham berkata: \"Aku berpikir: Takut akan Allah tidak ada di tempat ini; tentulah aku akan dibunuh karena isteriku.', NULL),
(2995, 3647, 20, 12, 'Lagipula ia benar-benar saudaraku, anak ayahku, hanya bukan anak ibuku, tetapi kemudian ia menjadi isteriku.', NULL),
(2996, 3647, 20, 13, 'Ketika Allah menyuruh aku mengembara keluar dari rumah ayahku, berkatalah aku kepada isteriku: Tunjukkanlah kasihmu kepadaku, yakni: katakanlah tentang aku di tiap-tiap tempat di mana kita tiba: Ia saudaraku.\"', NULL),
(2997, 3647, 20, 14, 'Kemudian Abimelekh mengambil kambing domba dan lembu sapi, hamba laki-laki dan perempuan, lalu memberikan semuanya itu kepada Abraham; Sara, isteri Abraham, juga dikembalikannya kepadanya.', NULL),
(2998, 3647, 20, 15, 'Dan Abimelekh berkata: \"Negeriku ini terbuka untuk engkau; menetaplah, di mana engkau suka.\"', NULL),
(2999, 3647, 20, 16, 'Lalu katanya kepada Sara: \"Telah kuberikan kepada saudaramu seribu syikal perak, itulah bukti kesucianmu bagi semua orang yang bersama-sama dengan engkau. Maka dalam segala hal engkau dibenarkan.\"', NULL),
(3000, 3647, 20, 17, 'Lalu Abraham berdoa kepada Allah, dan Allah menyembuhkan Abimelekh dan isterinya dan budak-budaknya perempuan, sehingga mereka melahirkan anak.', NULL),
(3001, 3647, 20, 18, 'Sebab tadinya TUHAN telah menutup kandungan setiap perempuan di istana Abimelekh karena Sara, isteri Abraham itu.', NULL),
(3518, 3647, 21, 1, 'TUHAN memperhatikan Sara, seperti yang difirmankan-Nya, dan TUHAN melakukan kepada Sara seperti yang dijanjikan-Nya.', 'Ishak lahir'),
(3519, 3647, 21, 2, 'Maka mengandunglah Sara, lalu ia melahirkan seorang anak laki-laki bagi Abraham dalam masa tuanya, pada waktu yang telah ditetapkan, sesuai dengan firman Allah kepadanya.', NULL),
(3520, 3647, 21, 3, 'Abraham menamai anaknya yang baru lahir itu Ishak, yang dilahirkan Sara baginya.', NULL),
(3521, 3647, 21, 4, 'Kemudian Abraham menyunat Ishak, anaknya itu, ketika berumur delapan hari, seperti yang diperintahkan Allah kepadanya.', NULL),
(3522, 3647, 21, 5, 'Adapun Abraham berumur seratus tahun, ketika Ishak, anaknya, lahir baginya.', NULL),
(3523, 3647, 21, 6, 'Berkatalah Sara: \"Allah telah membuat aku tertawa; setiap orang yang mendengarnya akan tertawa karena aku.\"', NULL),
(3524, 3647, 21, 7, 'Lagi katanya: \"Siapakah tadinya yang dapat mengatakan kepada Abraham: Sara menyusui anak? Namun aku telah melahirkan seorang anak laki-laki baginya pada masa tuanya.\"', NULL),
(3525, 3647, 21, 8, 'Bertambah besarlah anak itu dan ia disapih, lalu Abraham mengadakan perjamuan besar pada hari Ishak disapih itu.', 'Abraham mengusir Hagar dan Ismael'),
(3526, 3647, 21, 9, 'Pada waktu itu Sara melihat, bahwa anak yang dilahirkan Hagar, perempuan Mesir itu bagi Abraham, sedang main dengan Ishak, anaknya sendiri.', NULL),
(3527, 3647, 21, 10, 'Berkatalah Sara kepada Abraham: \"Usirlah hamba perempuan itu beserta anaknya, sebab anak hamba ini tidak akan menjadi ahli waris bersama-sama dengan anakku Ishak.\"', NULL),
(3528, 3647, 21, 11, 'Hal ini sangat menyebalkan Abraham oleh karena anaknya itu.', NULL),
(3529, 3647, 21, 12, 'Tetapi Allah berfirman kepada Abraham: \"Janganlah sebal hatimu karena hal anak dan budakmu itu; dalam segala yang dikatakan Sara kepadamu, haruslah engkau mendengarkannya, sebab yang akan disebut keturunanmu ialah yang berasal dari Ishak.', NULL),
(3530, 3647, 21, 13, 'Tetapi keturunan dari hambamu itu juga akan Kubuat menjadi suatu bangsa, karena iapun anakmu.\"', NULL),
(3531, 3647, 21, 14, 'Keesokan harinya pagi-pagi Abraham mengambil roti serta sekirbat air dan memberikannya kepada Hagar. Ia meletakkan itu beserta anaknya di atas bahu Hagar, kemudian disuruhnyalah perempuan itu pergi. Maka pergilah Hagar dan mengembara di padang gurun Bersyeba.', NULL),
(3532, 3647, 21, 15, 'Ketika air yang dikirbat itu habis, dibuangnyalah anak itu ke bawah semak-semak,', NULL),
(3533, 3647, 21, 16, 'dan ia duduk agak jauh, kira-kira sepemanah jauhnya, sebab katanya: \"Tidak tahan aku melihat anak itu mati.\" Sedang ia duduk di situ, menangislah ia dengan suara nyaring.', NULL),
(3534, 3647, 21, 17, 'Allah mendengar suara anak itu, lalu Malaikat Allah berseru dari langit kepada Hagar, kata-Nya kepadanya: \"Apakah yang engkau susahkan, Hagar? Janganlah takut, sebab Allah telah mendengar suara anak itu dari tempat ia terbaring.', NULL),
(3535, 3647, 21, 18, 'Bangunlah, angkatlah anak itu, dan bimbinglah dia, sebab Aku akan membuat dia menjadi bangsa yang besar.\"', NULL),
(3536, 3647, 21, 19, 'Lalu Allah membuka mata Hagar, sehingga ia melihat sebuah sumur; ia pergi mengisi kirbatnya dengan air, kemudian diberinya anak itu minum.', NULL),
(3537, 3647, 21, 20, 'Allah menyertai anak itu, sehingga ia bertambah besar; ia menetap di padang gurun dan menjadi seorang pemanah.', NULL),
(3538, 3647, 21, 21, 'Maka tinggallah ia di padang gurun Paran, dan ibunya mengambil seorang isteri baginya dari tanah Mesir.', NULL),
(3539, 3647, 21, 22, 'Pada waktu itu Abimelekh, beserta Pikhol, panglima tentaranya, berkata kepada Abraham: \"Allah menyertai engkau dalam segala sesuatu yang engkau lakukan.', 'Perjanjian Abraham dengan Abimelekh'),
(3540, 3647, 21, 23, 'Oleh sebab itu, bersumpahlah kepadaku di sini demi Allah, bahwa engkau tidak akan berlaku curang kepadaku, atau kepada anak-anakku, atau kepada cucu cicitku; sesuai dengan persahabatan yang kulakukan kepadamu, demikianlah harus engkau berlaku kepadaku dan kepada negeri yang kautinggali sebagai orang asing.\"', NULL),
(3541, 3647, 21, 24, 'Lalu kata Abraham: \"Aku bersumpah!\"', NULL),
(3542, 3647, 21, 25, 'Tetapi Abraham menyesali Abimelekh tentang sebuah sumur yang telah dirampas oleh hamba-hamba Abimelekh.', NULL),
(3543, 3647, 21, 26, 'Jawab Abimelekh: \"Aku tidak tahu, siapa yang melakukan hal itu; lagi tidak kauberitahukan kepadaku, dan sampai hari ini belum pula kudengar.\"', NULL),
(3544, 3647, 21, 27, 'Lalu Abraham mengambil domba dan lembu dan memberikan semuanya itu kepada Abimelekh, kemudian kedua orang itu mengadakan perjanjian.', NULL),
(3545, 3647, 21, 28, 'Tetapi Abraham memisahkan tujuh anak domba betina dari domba-domba itu.', NULL),
(3546, 3647, 21, 29, 'Lalu kata Abimelekh kepada Abraham: \"Untuk apakah ketujuh anak domba yang kaupisahkan ini?\"', NULL),
(3547, 3647, 21, 30, 'Jawabnya: \"Ketujuh anak domba ini harus kauterima dari tanganku untuk menjadi tanda bukti bagiku, bahwa akulah yang menggali sumur ini.\"', NULL),
(3548, 3647, 21, 31, 'Sebab itu orang menyebutkan tempat itu Bersyeba, karena kedua orang itu telah bersumpah di sana.', NULL),
(3549, 3647, 21, 32, 'Setelah mereka mengadakan perjanjian di Bersyeba, pulanglah Abimelekh beserta Pikhol, panglima tentaranya, ke negeri orang Filistin.', NULL),
(3550, 3647, 21, 33, 'Lalu Abraham menanam sebatang pohon tamariska di Bersyeba, dan memanggil di sana nama TUHAN, Allah yang kekal.', NULL),
(3551, 3647, 21, 34, 'Dan masih lama Abraham tinggal sebagai orang asing di negeri orang Filistin.', NULL),
(3552, 3647, 22, 1, 'Setelah semuanya itu Allah mencoba Abraham. Ia berfirman kepadanya: \"Abraham,\" lalu sahutnya: \"Ya, Tuhan.\"', 'Kepercayaan Abraham diuji'),
(3553, 3647, 22, 2, 'Firman-Nya: \"Ambillah anakmu yang tunggal itu, yang engkau kasihi, yakni Ishak, pergilah ke tanah Moria dan persembahkanlah dia di sana sebagai korban bakaran pada salah satu gunung yang akan Kukatakan kepadamu.\"', NULL),
(3554, 3647, 22, 3, 'Keesokan harinya pagi-pagi bangunlah Abraham, ia memasang pelana keledainya dan memanggil dua orang bujangnya beserta Ishak, anaknya; ia membelah juga kayu untuk korban bakaran itu, lalu berangkatlah ia dan pergi ke tempat yang dikatakan Allah kepadanya.', NULL),
(3555, 3647, 22, 4, 'Ketika pada hari ketiga Abraham melayangkan pandangnya, kelihatanlah kepadanya tempat itu dari jauh.', NULL),
(3556, 3647, 22, 5, 'Kata Abraham kepada kedua bujangnya itu: \"Tinggallah kamu di sini dengan keledai ini; aku beserta anak ini akan pergi ke sana; kami akan sembahyang, sesudah itu kami kembali kepadamu.\"', NULL),
(3557, 3647, 22, 6, 'Lalu Abraham mengambil kayu untuk korban bakaran itu dan memikulkannya ke atas bahu Ishak, anaknya, sedang di tangannya dibawanya api dan pisau. Demikianlah keduanya berjalan bersama-sama.', NULL),
(3558, 3647, 22, 7, 'Lalu berkatalah Ishak kepada Abraham, ayahnya: \"Bapa.\" Sahut Abraham: \"Ya, anakku.\" Bertanyalah ia: \"Di sini sudah ada api dan kayu, tetapi di manakah anak domba untuk korban bakaran itu?\"', NULL),
(3559, 3647, 22, 8, 'Sahut Abraham: \"Allah yang akan menyediakan anak domba untuk korban bakaran bagi-Nya, anakku.\" Demikianlah keduanya berjalan bersama-sama.', NULL),
(3560, 3647, 22, 9, 'Sampailah mereka ke tempat yang dikatakan Allah kepadanya. Lalu Abraham mendirikan mezbah di situ, disusunnyalah kayu, diikatnya Ishak, anaknya itu, dan diletakkannya di mezbah itu, di atas kayu api.', NULL),
(3561, 3647, 22, 10, 'Sesudah itu Abraham mengulurkan tangannya, lalu mengambil pisau untuk menyembelih anaknya.', NULL),
(3562, 3647, 22, 11, 'Tetapi berserulah Malaikat TUHAN dari langit kepadanya: \"Abraham, Abraham.\" Sahutnya: \"Ya, Tuhan.\"', NULL),
(3563, 3647, 22, 12, 'Lalu Ia berfirman: \"Jangan bunuh anak itu dan jangan kauapa-apakan dia, sebab telah Kuketahui sekarang, bahwa engkau takut akan Allah, dan engkau tidak segan-segan untuk menyerahkan anakmu yang tunggal kepada-Ku.\"', NULL),
(3564, 3647, 22, 13, 'Lalu Abraham menoleh dan melihat seekor domba jantan di belakangnya, yang tanduknya tersangkut dalam belukar. Abraham mengambil domba itu, lalu mengorbankannya sebagai korban bakaran pengganti anaknya.', NULL),
(3565, 3647, 22, 14, 'Dan Abraham menamai tempat itu: \"TUHAN menyediakan\"; sebab itu sampai sekarang dikatakan orang: \"Di atas gunung TUHAN, akan disediakan.\"', NULL),
(3566, 3647, 22, 15, 'Untuk kedua kalinya berserulah Malaikat TUHAN dari langit kepada Abraham,', NULL),
(3567, 3647, 22, 16, 'kata-Nya: \"Aku bersumpah demi diri-Ku sendiri--demikianlah firman TUHAN--:Karena engkau telah berbuat demikian, dan engkau tidak segan-segan untuk menyerahkan anakmu yang tunggal kepada-Ku,', NULL),
(3568, 3647, 22, 17, 'maka Aku akan memberkati engkau berlimpah-limpah dan membuat keturunanmu sangat banyak seperti bintang di langit dan seperti pasir di tepi laut, dan keturunanmu itu akan menduduki kota-kota musuhnya.', NULL),
(3569, 3647, 22, 18, 'Oleh keturunanmulah semua bangsa di bumi akan mendapat berkat, karena engkau mendengarkan firman-Ku.\"', NULL),
(3570, 3647, 22, 19, 'Kemudian kembalilah Abraham kepada kedua bujangnya, dan mereka bersama-sama berangkat ke Bersyeba; dan Abraham tinggal di Bersyeba.', NULL),
(3571, 3647, 22, 20, 'Sesudah itu Abraham mendapat kabar: \"Juga Milka telah melahirkan anak-anak lelaki bagi Nahor, saudaramu:', 'Keturunan Nahor'),
(3572, 3647, 22, 21, 'Us, anak sulung, dan Bus, adiknya, dan Kemuel, ayah Aram,', NULL),
(3573, 3647, 22, 22, 'juga Kesed, Hazo, Pildash, Yidlaf dan Betuel.\"', NULL),
(3574, 3647, 22, 23, 'Dan Betuel memperanakkan Ribka. Kedelapan orang inilah dilahirkan Milka bagi Nahor, saudara Abraham itu.', NULL),
(3575, 3647, 22, 24, 'Dan gundik Nahor, yang namanya Reuma, melahirkan anak juga, yakni Tebah, Gaham, Tahash dan Maakha.', NULL),
(3576, 3647, 23, 1, 'Sara hidup seratus dua puluh tujuh tahun lamanya; itulah umur Sara.', 'Sara mati dan dikuburkan'),
(3577, 3647, 23, 2, 'Kemudian matilah Sara di Kiryat-Arba, yaitu Hebron, di tanah Kanaan, lalu Abraham datang meratapi dan menangisinya.', NULL),
(3578, 3647, 23, 3, 'Sesudah itu Abraham bangkit dan meninggalkan isterinya yang mati itu, lalu berkata kepada bani Het:', NULL),
(3579, 3647, 23, 4, '\"Aku ini orang asing dan pendatang di antara kamu; berikanlah kiranya kuburan milik kepadaku di tanah kamu ini, supaya kiranya aku dapat mengantarkan dan menguburkan isteriku yang mati itu.\"', NULL),
(3580, 3647, 23, 5, 'Bani Het menjawab Abraham:', NULL),
(3581, 3647, 23, 6, '\"Dengarlah kepada kami, tuanku. Tuanku ini seorang raja agung di tengah-tengah kami; jadi kuburkanlah isterimu yang mati itu dalam kuburan kami yang terpilih, tidak akan ada seorangpun dari kami yang menolak menyediakan kuburannya bagimu untuk menguburkan isterimu yang mati itu.\"', NULL),
(3582, 3647, 23, 7, 'Kemudian bangunlah Abraham lalu sujud kepada bani Het, penduduk negeri itu,', NULL),
(3583, 3647, 23, 8, 'serta berkata kepada mereka: \"Jika kamu setuju, bahwa aku mengantarkan dan menguburkan isteriku yang mati itu, maka dengarkanlah aku dan tolonglah mintakan dengan sangat kepada Efron bin Zohar,', NULL),
(3584, 3647, 23, 9, 'supaya ia memberikan kepadaku gua Makhpela miliknya itu, yang terletak di ujung ladangnya; baiklah itu diberikannya kepadaku dengan harga penuh untuk menjadi kuburan milikku di tengah-tengah kamu.\"', NULL),
(3585, 3647, 23, 10, 'Pada waktu itu Efron hadir di tengah-tengah bani Het. Maka jawab Efron, orang Het itu, kepada Abraham dengan didengar oleh bani Het, oleh semua orang yang datang di pintu gerbang kota:', NULL),
(3586, 3647, 23, 11, '\"Tidak, tuanku, dengarkanlah aku; ladang itu kuberikan kepadamu dan gua yang di sanapun kuberikan kepadamu; di depan mata orang-orang sebangsaku kuberikan itu kepadamu; kuburkanlah isterimu yang mati itu.\"', NULL),
(3587, 3647, 23, 12, 'Lalu sujudlah Abraham di depan penduduk negeri itu', NULL),
(3588, 3647, 23, 13, 'serta berkata kepada Efron dengan didengar oleh mereka: \"Sesungguhnya, jika engkau suka, dengarkanlah aku: aku membayar harga ladang itu; terimalah itu dari padaku, supaya aku dapat menguburkan isteriku yang mati itu di sana.\"', NULL),
(3589, 3647, 23, 14, 'Jawab Efron kepada Abraham:', NULL),
(3590, 3647, 23, 15, '\"Tuanku, dengarkanlah aku: sebidang tanah dengan harga empat ratus syikal perak, apa artinya itu bagi kita? Kuburkan sajalah isterimu yang mati itu.\"', NULL),
(3591, 3647, 23, 16, 'Lalu Abraham menerima usul Efron, maka ditimbangnyalah perak untuk Efron, sebanyak yang dimintanya dengan didengar oleh bani Het itu, empat ratus syikal perak, seperti yang berlaku di antara para saudagar.', NULL),
(3592, 3647, 23, 17, 'Demikianlah ladang Efron, yang letaknya di Makhpela di sebelah timur Mamre, ladang dan gua yang di sana, serta segala pohon di ladang itu, bahkan di seluruh tanah itu sampai ke tepi-tepinya,', NULL),
(3593, 3647, 23, 18, 'diserahkan kepada Abraham menjadi tanah belian, di depan mata bani Het itu, di depan semua orang yang datang di pintu gerbang kota.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(3594, 3647, 23, 19, 'Sesudah itu Abraham menguburkan Sara, isterinya, di dalam gua ladang Makhpela itu, di sebelah timur Mamre, yaitu Hebron di tanah Kanaan.', NULL),
(3595, 3647, 23, 20, 'Demikianlah dari pihak bani Het ladang dengan gua yang ada di sana diserahkan kepada Abraham menjadi kuburan miliknya.', NULL),
(3596, 3647, 24, 1, 'Adapun Abraham telah tua dan lanjut umurnya, serta diberkati TUHAN dalam segala hal.', 'Ribka dipinang bagi Ishak'),
(3597, 3647, 24, 2, 'Berkatalah Abraham kepada hambanya yang paling tua dalam rumahnya, yang menjadi kuasa atas segala kepunyaannya, katanya: \"Baiklah letakkan tanganmu di bawah pangkal pahaku,', NULL),
(3598, 3647, 24, 3, 'supaya aku mengambil sumpahmu demi TUHAN, Allah yang empunya langit dan yang empunya bumi, bahwa engkau tidak akan mengambil untuk anakku seorang isteri dari antara perempuan Kanaan yang di antaranya aku diam.', NULL),
(3599, 3647, 24, 4, 'Tetapi engkau harus pergi ke negeriku dan kepada sanak saudaraku untuk mengambil seorang isteri bagi Ishak, anakku.\"', NULL),
(3600, 3647, 24, 5, 'Lalu berkatalah hambanya itu kepadanya: \"Mungkin perempuan itu tidak suka mengikuti aku ke negeri ini; haruskah aku membawa anakmu itu kembali ke negeri dari mana tuanku keluar?\"', NULL),
(3601, 3647, 24, 6, 'Tetapi Abraham berkata kepadanya: \"Awas, jangan kaubawa anakku itu kembali ke sana.', NULL),
(3602, 3647, 24, 7, 'TUHAN, Allah yang empunya langit, yang telah memanggil aku dari rumah ayahku serta dari negeri sanak saudaraku, dan yang telah berfirman kepadaku, serta yang bersumpah kepadaku, demikian: kepada keturunanmulah akan Kuberikan negeri ini--Dialah juga akan mengutus malaikat-Nya berjalan di depanmu, sehingga engkau dapat mengambil seorang isteri dari sana untuk anakku.', NULL),
(3603, 3647, 24, 8, 'Tetapi jika perempuan itu tidak mau mengikuti engkau, maka lepaslah engkau dari sumpahmu kepadaku ini; hanya saja, janganlah anakku itu kaubawa kembali ke sana.\"', NULL),
(3604, 3647, 24, 9, 'Lalu hamba itu meletakkan tangannya di bawah pangkal paha Abraham, tuannya, dan bersumpah kepadanya tentang hal itu.', NULL),
(3605, 3647, 24, 10, 'Kemudian hamba itu mengambil sepuluh ekor dari unta tuannya dan pergi dengan membawa berbagai-bagai barang berharga kepunyaan tuannya; demikianlah ia berangkat menuju Aram-Mesopotamia ke kota Nahor.', NULL),
(3606, 3647, 24, 11, 'Di sana disuruhnyalah unta itu berhenti di luar kota dekat suatu sumur, pada waktu petang hari, waktu perempuan-perempuan keluar untuk menimba air.', NULL),
(3607, 3647, 24, 12, 'Lalu berkatalah ia: \"TUHAN, Allah tuanku Abraham, buatlah kiranya tercapai tujuanku pada hari ini, tunjukkanlah kasih setia-Mu kepada tuanku Abraham.', NULL),
(3608, 3647, 24, 13, 'Di sini aku berdiri di dekat mata air, dan anak-anak perempuan penduduk kota ini datang keluar untuk menimba air.', NULL),
(3609, 3647, 24, 14, 'Kiranya terjadilah begini: anak gadis, kepada siapa aku berkata: Tolong miringkan buyungmu itu, supaya aku minum, dan yang menjawab: Minumlah, dan unta-untamu juga akan kuberi minum--dialah kiranya yang Kautentukan bagi hamba-Mu, Ishak; maka dengan begitu akan kuketahui, bahwa Engkau telah menunjukkan kasih setia-Mu kepada tuanku itu.\"', NULL),
(3610, 3647, 24, 15, 'Sebelum ia selesai berkata, maka datanglah Ribka, yang lahir bagi Betuel, anak laki-laki Milka, isteri Nahor, saudara Abraham; buyungnya dibawanya di atas bahunya.', NULL),
(3611, 3647, 24, 16, 'Anak gadis itu sangat cantik parasnya, seorang perawan, belum pernah bersetubuh dengan laki-laki; ia turun ke mata air itu dan mengisi buyungnya, lalu kembali naik.', NULL),
(3612, 3647, 24, 17, 'Kemudian berlarilah hamba itu mendapatkannya serta berkata: \"Tolong beri aku minum air sedikit dari buyungmu itu.\"', NULL),
(3613, 3647, 24, 18, 'Jawabnya: \"Minumlah, tuan,\" maka segeralah diturunkannya buyungnya itu ke tangannya, serta diberinya dia minum.', NULL),
(3614, 3647, 24, 19, 'Setelah ia selesai memberi hamba itu minum, berkatalah ia: \"Baiklah untuk unta-untamu juga kutimba air, sampai semuanya puas minum.\"', NULL),
(3615, 3647, 24, 20, 'Kemudian segeralah dituangnya air yang di buyungnya itu ke dalam palungan, lalu berlarilah ia sekali lagi ke sumur untuk menimba air dan ditimbanyalah untuk semua unta orang itu.', NULL),
(3616, 3647, 24, 21, 'Dan orang itu mengamat-amatinya dengan berdiam diri untuk mengetahui apakah TUHAN membuat perjalanannya berhasil atau tidak.', NULL),
(3617, 3647, 24, 22, 'Setelah unta-unta itu puas minum, maka orang itu mengambil anting-anting emas yang setengah syikal beratnya, dan sepasang gelang tangan yang sepuluh syikal emas beratnya,', NULL),
(3618, 3647, 24, 23, 'serta berkata: \"Anak siapakah engkau? Baiklah katakan kepadaku! Adakah di rumah ayahmu tempat bermalam bagi kami?\"', NULL),
(3619, 3647, 24, 24, 'Lalu jawabnya kepadanya: \"Ayahku Betuel, anak Milka, yang melahirkannya bagi Nahor.\"', NULL),
(3620, 3647, 24, 25, 'Lagi kata gadis itu: \"Baik jerami, baik makanan unta banyak pada kami, tempat bermalampun ada.\"', NULL),
(3621, 3647, 24, 26, 'Lalu berlututlah orang itu dan sujud menyembah TUHAN,', NULL),
(3622, 3647, 24, 27, 'serta berkata: \"Terpujilah TUHAN, Allah tuanku Abraham, yang tidak menarik kembali kasih-Nya dan setia-Nya dari tuanku itu; dan TUHAN telah menuntun aku di jalan ke rumah saudara-saudara tuanku ini!\"', NULL),
(3623, 3647, 24, 28, 'Berlarilah gadis itu pergi menceritakan kejadian itu ke rumah ibunya.', NULL),
(3624, 3647, 24, 29, 'Ribka mempunyai saudara laki-laki, namanya Laban. Laban berlari ke luar mendapatkan orang itu, ke mata air tadi,', NULL),
(3625, 3647, 24, 30, 'sesudah dilihatnya anting-anting itu dan gelang pada tangan saudaranya, dan sesudah didengarnya perkataan Ribka, saudaranya, yang bunyinya: \"Begitulah dikatakan orang itu kepadaku.\" Ia mendapatkan orang itu, yang masih berdiri di samping unta-untanya di dekat mata air itu,', NULL),
(3626, 3647, 24, 31, 'dan berkata: \"Marilah engkau yang diberkati TUHAN, mengapa engkau berdiri di luar, padahal telah kusediakan rumah bagimu, dan juga tempat untuk unta-untamu.\"', NULL),
(3627, 3647, 24, 32, 'Masuklah orang itu ke dalam rumah. Ditanggalkanlah pelana unta-unta, diberikan jerami dan makanan kepada unta-unta itu, lalu dibawa air pembasuh kaki untuk orang itu dan orang-orang yang bersama-sama dengan dia.', NULL),
(3628, 3647, 24, 33, 'Tetapi ketika dihidangkan makanan di depannya, berkatalah orang itu: \"Aku tidak akan makan sebelum kusampaikan pesan yang kubawa ini.\" Jawab Laban: \"Silakan!\"', NULL),
(3629, 3647, 24, 34, 'Lalu berkatalah ia: \"Aku ini hamba Abraham.', NULL),
(3630, 3647, 24, 35, 'TUHAN sangat memberkati tuanku itu, sehingga ia telah menjadi kaya; TUHAN telah memberikan kepadanya kambing domba dan lembu sapi, emas dan perak, budak laki-laki dan perempuan, unta dan keledai.', NULL),
(3631, 3647, 24, 36, 'Dan Sara, isteri tuanku itu, sesudah tua, telah melahirkan anak laki-laki bagi tuanku itu; kepada anaknya itu telah diberikan tuanku segala harta miliknya.', NULL),
(3632, 3647, 24, 37, 'Tuanku itu telah mengambil sumpahku: Engkau tidak akan mengambil untuk anakku seorang isteri dari antara perempuan Kanaan, yang negerinya kudiami ini,', NULL),
(3633, 3647, 24, 38, 'tetapi engkau harus pergi ke rumah ayahku dan kepada kaumku untuk mengambil seorang isteri bagi anakku.', NULL),
(3634, 3647, 24, 39, 'Jawabku kepada tuanku itu: Mungkin perempuan itu tidak mau mengikut aku.', NULL),
(3635, 3647, 24, 40, 'Tetapi katanya kepadaku: TUHAN, yang di hadapan-Nya aku hidup, akan mengutus malaikat-Nya menyertai engkau, dan akan membuat perjalananmu berhasil, sehingga engkau akan mengambil bagi anakku seorang isteri dari kaumku dan dari rumah ayahku.', NULL),
(3636, 3647, 24, 41, 'Barulah engkau lepas dari sumpahmu kepadaku, jika engkau sampai kepada kaumku dan mereka tidak memberikan perempuan itu kepadamu; hanya dalam hal itulah engkau lepas dari sumpahmu kepadaku.', NULL),
(3637, 3647, 24, 42, 'Dan hari ini aku sampai ke mata air tadi, lalu kataku: TUHAN, Allah tuanku Abraham, sudilah kiranya Engkau membuat berhasil perjalanan yang kutempuh ini.', NULL),
(3638, 3647, 24, 43, 'Di sini aku berdiri di dekat mata air ini; kiranya terjadi begini: Apabila seorang gadis datang ke luar untuk menimba air dan aku berkata kepadanya: Tolong berikan aku minum air sedikit dari buyungmu itu,', NULL),
(3639, 3647, 24, 44, 'dan ia menjawab: Minumlah, dan untuk unta-untamu juga akan kutimba air, --dialah kiranya isteri, yang telah TUHAN tentukan bagi anak tuanku itu.', NULL),
(3640, 3647, 24, 45, 'Belum lagi aku habis berkata dalam hatiku, Ribka telah datang membawa buyung di atas bahunya, dan turun ke mata air itu, lalu menimba air. Kataku kepadanya: Tolong berikan aku minum.', NULL),
(3641, 3647, 24, 46, 'Segeralah ia menurunkan buyung itu dari atas bahunya serta berkata: Minumlah, dan unta-untamu juga akan kuberi minum. Lalu aku minum, dan unta-unta itu juga diberinya minum.', NULL),
(3642, 3647, 24, 47, 'Sesudah itu aku bertanya kepadanya: Anak siapakah engkau? Jawabnya: Ayahku Betuel anak Nahor yang dilahirkan Milka. Lalu aku mengenakan anting-anting pada hidungnya dan gelang pada tangannya.', NULL),
(3643, 3647, 24, 48, 'Kemudian berlututlah aku dan sujud menyembah TUHAN, serta memuji TUHAN, Allah tuanku Abraham, yang telah menuntun aku di jalan yang benar untuk mengambil anak perempuan saudara tuanku ini bagi anaknya.', NULL),
(3644, 3647, 24, 49, 'Jadi sekarang, apabila kamu mau menunjukkan kasih dan setia kepada tuanku itu, beritahukanlah kepadaku; dan jika tidak, beritahukanlah juga kepadaku, supaya aku tahu entah berpaling ke kanan atau ke kiri.\"', NULL),
(3645, 3647, 24, 50, 'Lalu Laban dan Betuel menjawab: \"Semuanya ini datangnya dari TUHAN; kami tidak dapat mengatakan kepadamu baiknya atau buruknya.', NULL),
(3646, 3647, 24, 51, 'Lihat, Ribka ada di depanmu, bawalah dia dan pergilah, supaya ia menjadi isteri anak tuanmu, seperti yang difirmankan TUHAN.\"', NULL),
(3647, 3647, 24, 52, 'Ketika hamba Abraham itu mendengar perkataan mereka, sujudlah ia sampai ke tanah menyembah TUHAN.', NULL),
(3648, 3647, 24, 53, 'Kemudian hamba itu mengeluarkan perhiasan emas dan perak serta pakaian kebesaran, dan memberikan semua itu kepada Ribka; juga kepada saudaranya dan kepada ibunya diberikannya pemberian yang indah-indah.', NULL),
(3649, 3647, 24, 54, 'Sesudah itu makan dan minumlah mereka, ia dan orang-orang yang bersama-sama dengan dia, dan mereka bermalam di situ. Paginya sesudah mereka bangun, berkatalah hamba itu: \"Lepaslah aku pulang kepada tuanku.\"', NULL),
(3650, 3647, 24, 55, 'Tetapi saudara Ribka berkata, serta ibunya juga: \"Biarkanlah anak gadis itu tinggal pada kami barang sepuluh hari lagi, kemudian bolehlah engkau pergi.\"', NULL),
(3651, 3647, 24, 56, 'Tetapi jawabnya kepada mereka: \"Janganlah tahan aku, sedang TUHAN telah membuat perjalananku berhasil; lepaslah aku, supaya aku pulang kepada tuanku.\"', NULL),
(3652, 3647, 24, 57, 'Kata mereka: \"Baiklah kita panggil anak gadis itu dan menanyakan kepadanya sendiri.\"', NULL),
(3653, 3647, 24, 58, 'Lalu mereka memanggil Ribka dan berkata kepadanya: \"Maukah engkau pergi beserta orang ini?\" Jawabnya: \"Mau.\"', NULL),
(3654, 3647, 24, 59, 'Maka Ribka, saudara mereka itu, dan inang pengasuhnya beserta hamba Abraham dan orang-orangnya dibiarkan mereka pergi.', NULL),
(3655, 3647, 24, 60, 'Dan mereka memberkati Ribka, kata mereka kepadanya: \"Saudara kami, moga-moga engkau menjadi beribu-ribu laksa, dan moga-moga keturunanmu menduduki kota-kota musuhnya.\"', NULL),
(3656, 3647, 24, 61, 'Lalu berkemaslah Ribka beserta hamba-hambanya perempuan, dan mereka naik unta mengikuti orang itu. Demikianlah hamba itu membawa Ribka lalu berjalan pulang.', NULL),
(3657, 3647, 24, 62, 'Adapun Ishak telah datang dari arah sumur Lahai-Roi; ia tinggal di Tanah Negeb.', NULL),
(3658, 3647, 24, 63, 'Menjelang senja Ishak sedang keluar untuk berjalan-jalan di padang. Ia melayangkan pandangnya, maka dilihatnyalah ada unta-unta datang.', NULL),
(3659, 3647, 24, 64, 'Ribka juga melayangkan pandangnya dan ketika dilihatnya Ishak, turunlah ia dari untanya.', NULL),
(3660, 3647, 24, 65, 'Katanya kepada hamba itu: \"Siapakah laki-laki itu yang berjalan di padang ke arah kita?\" Jawab hamba itu: \"Dialah tuanku itu.\" Lalu Ribka mengambil telekungnya dan bertelekunglah ia.', NULL),
(3661, 3647, 24, 66, 'Kemudian hamba itu menceritakan kepada Ishak segala yang dilakukannya.', NULL),
(3662, 3647, 24, 67, 'Lalu Ishak membawa Ribka ke dalam kemah Sara, ibunya, dan mengambil dia menjadi isterinya. Ishak mencintainya dan demikian ia dihiburkan setelah ibunya meninggal.', NULL),
(3663, 3647, 25, 1, 'Abraham mengambil pula seorang isteri, namanya Ketura.', 'Keturunan Abraham dari Ketura'),
(3664, 3647, 25, 2, 'Perempuan itu melahirkan baginya Zimran, Yoksan, Medan, Midian, Isybak dan Suah.', NULL),
(3665, 3647, 25, 3, 'Yoksan memperanakkan Syeba dan Dedan. Keturunan Dedan ialah orang Asyur, orang Letush dan orang Leum.', NULL),
(3666, 3647, 25, 4, 'Anak-anak Midian ialah Efa, Efer, Henokh, Abida dan Eldaa. Itulah semuanya keturunan Ketura.', NULL),
(3667, 3647, 25, 5, 'Abraham memberikan segala harta miliknya kepada Ishak,', NULL),
(3668, 3647, 25, 6, 'tetapi kepada anak-anaknya yang diperolehnya dari gundik-gundiknya ia memberikan pemberian; kemudian ia menyuruh mereka--masih pada waktu ia hidup--meninggalkan Ishak, anaknya, dan pergi ke sebelah timur, ke Tanah Timur.', NULL),
(3669, 3647, 25, 7, 'Abraham mencapai umur seratus tujuh puluh lima tahun,', 'Abraham meninggal dan dikuburkan'),
(3670, 3647, 25, 8, 'lalu ia meninggal. Ia mati pada waktu telah putih rambutnya, tua dan suntuk umur, maka ia dikumpulkan kepada kaum leluhurnya.', NULL),
(3671, 3647, 25, 9, 'Dan anak-anaknya, Ishak dan Ismael, menguburkan dia dalam gua Makhpela, di padang Efron bin Zohar, orang Het itu, padang yang letaknya di sebelah timur Mamre,', NULL),
(3672, 3647, 25, 10, 'yang telah dibeli Abraham dari bani Het; di sanalah terkubur Abraham dan Sara isterinya.', NULL),
(3673, 3647, 25, 11, 'Setelah Abraham mati, Allah memberkati Ishak, anaknya itu; dan Ishak diam dekat sumur Lahai-Roi.', NULL),
(3674, 3647, 25, 12, 'Inilah keturunan Ismael, anak Abraham, yang telah dilahirkan baginya oleh Hagar, perempuan Mesir, hamba Sara itu.', 'Keturunan Ismael'),
(3675, 3647, 25, 13, 'Inilah nama anak-anak Ismael, disebutkan menurut urutan lahirnya: Nebayot, anak sulung Ismael, selanjutnya Kedar, Adbeel, Mibsam,', NULL),
(3676, 3647, 25, 14, 'Misyma, Duma, Masa,', NULL),
(3677, 3647, 25, 15, 'Hadad, Tema, Yetur, Nafish dan Kedma.', NULL),
(3678, 3647, 25, 16, 'Itulah anak-anak Ismael, dan itulah nama-nama mereka, menurut kampung mereka dan menurut perkemahan mereka, dua belas orang raja, masing-masing dengan sukunya.', NULL),
(3679, 3647, 25, 17, 'Umur Ismael ialah seratus tiga puluh tujuh tahun. Sesudah itu ia meninggal. Ia mati dan dikumpulkan kepada kaum leluhurnya.', NULL),
(3680, 3647, 25, 18, 'Mereka itu mendiami daerah dari Hawila sampai Syur, yang letaknya di sebelah timur Mesir ke arah Asyur. Mereka menetap berhadapan dengan semua saudara mereka.', NULL),
(3681, 3647, 25, 19, 'Inilah riwayat keturunan Ishak, anak Abraham. Abraham memperanakkan Ishak.', 'Esau dan Yakub'),
(3682, 3647, 25, 20, 'Dan Ishak berumur empat puluh tahun, ketika Ribka, anak Betuel, orang Aram dari Padan-Aram, saudara perempuan Laban orang Aram itu, diambilnya menjadi isterinya.', NULL),
(3683, 3647, 25, 21, 'Berdoalah Ishak kepada TUHAN untuk isterinya, sebab isterinya itu mandul; TUHAN mengabulkan doanya, sehingga Ribka, isterinya itu, mengandung.', NULL),
(3684, 3647, 25, 22, 'Tetapi anak-anaknya bertolak-tolakan di dalam rahimnya dan ia berkata: \"Jika demikian halnya, mengapa aku hidup?\" Dan ia pergi meminta petunjuk kepada TUHAN.', NULL),
(3685, 3647, 25, 23, 'Firman TUHAN kepadanya: \"Dua bangsa ada dalam kandunganmu, dan dua suku bangsa akan berpencar dari dalam rahimmu; suku bangsa yang satu akan lebih kuat dari yang lain, dan anak yang tua akan menjadi hamba kepada anak yang muda.\"', NULL),
(3686, 3647, 25, 24, 'Setelah genap harinya untuk bersalin, memang anak kembar yang di dalam kandungannya.', NULL),
(3687, 3647, 25, 25, 'Keluarlah yang pertama, warnanya merah, seluruh tubuhnya seperti jubah berbulu; sebab itu ia dinamai Esau.', NULL),
(3688, 3647, 25, 26, 'Sesudah itu keluarlah adiknya; tangannya memegang tumit Esau, sebab itu ia dinamai Yakub. Ishak berumur enam puluh tahun pada waktu mereka lahir.', NULL),
(3689, 3647, 25, 27, 'Lalu bertambah besarlah kedua anak itu: Esau menjadi seorang yang pandai berburu, seorang yang suka tinggal di padang, tetapi Yakub adalah seorang yang tenang, yang suka tinggal di kemah.', NULL),
(3690, 3647, 25, 28, 'Ishak sayang kepada Esau, sebab ia suka makan daging buruan, tetapi Ribka kasih kepada Yakub.', NULL),
(3691, 3647, 25, 29, 'Pada suatu kali Yakub sedang memasak sesuatu, lalu datanglah Esau dengan lelah dari padang.', NULL),
(3692, 3647, 25, 30, 'Kata Esau kepada Yakub: \"Berikanlah kiranya aku menghirup sedikit dari yang merah-merah itu, karena aku lelah.\" Itulah sebabnya namanya disebutkan Edom.', NULL),
(3693, 3647, 25, 31, 'Tetapi kata Yakub: \"Juallah dahulu kepadaku hak kesulunganmu.\"', NULL),
(3694, 3647, 25, 32, 'Sahut Esau: \"Sebentar lagi aku akan mati; apakah gunanya bagiku hak kesulungan itu?\"', NULL),
(3695, 3647, 25, 33, 'Kata Yakub: \"Bersumpahlah dahulu kepadaku.\" Maka bersumpahlah ia kepada Yakub dan dijualnyalah hak kesulungannya kepadanya.', NULL),
(3696, 3647, 25, 34, 'Lalu Yakub memberikan roti dan masakan kacang merah itu kepada Esau; ia makan dan minum, lalu berdiri dan pergi. Demikianlah Esau memandang ringan hak kesulungan itu.', NULL),
(4392, 3647, 26, 1, 'Maka timbullah kelaparan di negeri itu. --Ini bukan kelaparan yang pertama, yang telah terjadi dalam zaman Abraham. Sebab itu Ishak pergi ke Gerar, kepada Abimelekh, raja orang Filistin.', 'Ishak di negeri orang Filistin'),
(4393, 3647, 26, 2, 'Lalu TUHAN menampakkan diri kepadanya serta berfirman: \"Janganlah pergi ke Mesir, diamlah di negeri yang akan Kukatakan kepadamu.', NULL),
(4394, 3647, 26, 3, 'Tinggallah di negeri ini sebagai orang asing, maka Aku akan menyertai engkau dan memberkati engkau, sebab kepadamulah dan kepada keturunanmu akan Kuberikan seluruh negeri ini, dan Aku akan menepati sumpah yang telah Kuikrarkan kepada Abraham, ayahmu.', NULL),
(4395, 3647, 26, 4, 'Aku akan membuat banyak keturunanmu seperti bintang di langit; Aku akan memberikan kepada keturunanmu seluruh negeri ini, dan oleh keturunanmu semua bangsa di bumi akan mendapat berkat,', NULL),
(4396, 3647, 26, 5, 'karena Abraham telah mendengarkan firman-Ku dan memelihara kewajibannya kepada-Ku, yaitu segala perintah, ketetapan dan hukum-Ku.\"', NULL),
(4397, 3647, 26, 6, 'Jadi tinggallah Ishak di Gerar.', NULL),
(4398, 3647, 26, 7, 'Ketika orang-orang di tempat itu bertanya tentang isterinya, berkatalah ia: \"Dia saudaraku,\" sebab ia takut mengatakan: \"Ia isteriku,\" karena pikirnya: \"Jangan-jangan aku dibunuh oleh penduduk tempat ini karena Ribka, sebab elok parasnya.\"', NULL),
(4399, 3647, 26, 8, 'Setelah beberapa lama ia ada di sana, pada suatu kali menjenguklah Abimelekh, raja orang Filistin itu dari jendela, maka dilihatnya Ishak sedang bercumbu-cumbuan dengan Ribka, isterinya.', NULL),
(4400, 3647, 26, 9, 'Lalu Abimelekh memanggil Ishak dan berkata: \"Sesungguhnya dia isterimu, masakan engkau berkata: Dia saudaraku?\" Jawab Ishak kepadanya: \"Karena pikirku: Jangan-jangan aku mati karena dia.\"', NULL),
(4401, 3647, 26, 10, 'Tetapi Abimelekh berkata: \"Apakah juga yang telah kauperbuat ini terhadap kami? Mudah sekali terjadi, salah seorang dari bangsa ini tidur dengan isterimu, sehingga dengan demikian engkau mendatangkan kesalahan atas kami.\"', NULL),
(4402, 3647, 26, 11, 'Lalu Abimelekh memberi perintah kepada seluruh bangsa itu: \"Siapa yang mengganggu orang ini atau isterinya, pastilah ia akan dihukum mati.\"', NULL),
(4403, 3647, 26, 12, 'Maka menaburlah Ishak di tanah itu dan dalam tahun itu juga ia mendapat hasil seratus kali lipat; sebab ia diberkati TUHAN.', NULL),
(4404, 3647, 26, 13, 'Dan orang itu menjadi kaya, bahkan kian lama kian kaya, sehingga ia menjadi sangat kaya.', NULL),
(4405, 3647, 26, 14, 'Ia mempunyai kumpulan kambing domba dan lembu sapi serta banyak anak buah, sehingga orang Filistin itu cemburu kepadanya.', NULL),
(4406, 3647, 26, 15, 'Segala sumur, yang digali dalam zaman Abraham, ayahnya, oleh hamba-hamba ayahnya itu, telah ditutup oleh orang Filistin dan ditimbun dengan tanah.', NULL),
(4407, 3647, 26, 16, 'Lalu kata Abimelekh kepada Ishak: \"Pergilah dari tengah-tengah kami sebab engkau telah menjadi jauh lebih berkuasa dari pada kami.\"', NULL),
(4408, 3647, 26, 17, 'Jadi pergilah Ishak dari situ dan berkemahlah ia di lembah Gerar, dan ia menetap di situ.', NULL),
(4409, 3647, 26, 18, 'Kemudian Ishak menggali kembali sumur-sumur yang digali dalam zaman Abraham, ayahnya, dan yang telah ditutup oleh orang Filistin sesudah Abraham mati; disebutkannyalah nama sumur-sumur itu menurut nama-nama yang telah diberikan oleh ayahnya.', NULL),
(4410, 3647, 26, 19, 'Ketika hamba-hamba Ishak menggali di lembah itu, mereka mendapati di situ mata air yang berbual-bual airnya.', NULL),
(4411, 3647, 26, 20, 'Lalu bertengkarlah para gembala Gerar dengan para gembala Ishak. Kata mereka: \"Air ini kepunyaan kami.\" Dan Ishak menamai sumur itu Esek, karena mereka bertengkar dengan dia di sana.', NULL),
(4412, 3647, 26, 21, 'Kemudian mereka menggali sumur lain, dan mereka bertengkar juga tentang itu. Maka Ishak menamai sumur itu Sitna.', NULL),
(4413, 3647, 26, 22, 'Ia pindah dari situ dan menggali sumur yang lain lagi, tetapi tentang sumur ini mereka tidak bertengkar. Sumur ini dinamainya Rehobot, dan ia berkata: \"Sekarang TUHAN telah memberikan kelonggaran kepada kita, sehingga kita dapat beranak cucu di negeri ini.\"', NULL),
(4414, 3647, 26, 23, 'Dari situ ia pergi ke Bersyeba.', NULL),
(4415, 3647, 26, 24, 'Lalu pada malam itu TUHAN menampakkan diri kepadanya serta berfirman: \"Akulah Allah ayahmu Abraham; janganlah takut, sebab Aku menyertai engkau; Aku akan memberkati engkau dan membuat banyak keturunanmu karena Abraham, hamba-Ku itu.\"', NULL),
(4416, 3647, 26, 25, 'Sesudah itu Ishak mendirikan mezbah di situ dan memanggil nama TUHAN. Ia memasang kemahnya di situ, lalu hamba-hambanya menggali sumur di situ.', NULL),
(4417, 3647, 26, 26, 'Datanglah Abimelekh dari Gerar mendapatkannya, bersama-sama dengan Ahuzat, sahabatnya, dan Pikhol, kepala pasukannya.', NULL),
(4418, 3647, 26, 27, 'Tetapi kata Ishak kepada mereka: \"Mengapa kamu datang mendapatkan aku? Bukankah kamu benci kepadaku, dan telah menyuruh aku keluar dari tanahmu?\"', NULL),
(4419, 3647, 26, 28, 'Jawab mereka: \"Kami telah melihat sendiri, bahwa TUHAN menyertai engkau; sebab itu kami berkata: baiklah kita mengadakan sumpah setia, antara kami dan engkau; dan baiklah kami mengikat perjanjian dengan engkau,', NULL),
(4420, 3647, 26, 29, 'bahwa engkau tidak akan berbuat jahat kepada kami, seperti kami tidak mengganggu engkau, dan seperti kami semata-mata berbuat baik kepadamu dan membiarkan engkau pergi dengan damai; bukankah engkau sekarang yang diberkati TUHAN.\"', NULL),
(4421, 3647, 26, 30, 'Kemudian Ishak mengadakan perjamuan bagi mereka, lalu mereka makan dan minum.', NULL),
(4422, 3647, 26, 31, 'Keesokan harinya pagi-pagi bersumpah-sumpahanlah mereka. Kemudian Ishak melepas mereka, dan mereka meninggalkan dia dengan damai.', NULL),
(4423, 3647, 26, 32, 'Pada hari itu datanglah hamba-hamba Ishak memberitahukan kepadanya tentang sumur yang telah digali mereka, serta berkata kepadanya: \"Kami telah mendapat air.\"', NULL),
(4424, 3647, 26, 33, 'Lalu dinamainyalah sumur itu Syeba. Sebab itu nama kota itu adalah Bersyeba, sampai sekarang.', NULL),
(4425, 3647, 26, 34, 'Ketika Esau telah berumur empat puluh tahun, ia mengambil Yudit, anak Beeri orang Het, dan Basmat, anak Elon orang Het, menjadi isterinya.', NULL),
(4426, 3647, 26, 35, 'Kedua perempuan itu menimbulkan kepedihan hati bagi Ishak dan bagi Ribka.', NULL),
(4427, 3647, 27, 1, 'Ketika Ishak sudah tua, dan matanya telah kabur, sehingga ia tidak dapat melihat lagi, dipanggilnyalah Esau, anak sulungnya, serta berkata kepadanya: \"Anakku.\" Sahut Esau: \"Ya, bapa.\"', 'Yakub diberkati Ishak sebagai anak sulung'),
(4428, 3647, 27, 2, 'Berkatalah Ishak: \"Lihat, aku sudah tua, aku tidak tahu bila hari kematianku.', NULL),
(4429, 3647, 27, 3, 'Maka sekarang, ambillah senjatamu, tabung panah dan busurmu, pergilah ke padang dan burulah bagiku seekor binatang;', NULL),
(4430, 3647, 27, 4, 'olahlah bagiku makanan yang enak, seperti yang kugemari, sesudah itu bawalah kepadaku, supaya kumakan, agar aku memberkati engkau, sebelum aku mati.\"', NULL),
(4431, 3647, 27, 5, 'Tetapi Ribka mendengarkannya, ketika Ishak berkata kepada Esau, anaknya. Setelah Esau pergi ke padang memburu seekor binatang untuk dibawanya kepada ayahnya,', NULL),
(4432, 3647, 27, 6, 'berkatalah Ribka kepada Yakub, anaknya: \"Telah kudengar ayahmu berkata kepada Esau, kakakmu:', NULL),
(4433, 3647, 27, 7, 'Bawalah bagiku seekor binatang buruan dan olahlah bagiku makanan yang enak, supaya kumakan, dan supaya aku memberkati engkau di hadapan TUHAN, sebelum aku mati.', NULL),
(4434, 3647, 27, 8, 'Maka sekarang, anakku, dengarkanlah perkataanku seperti yang kuperintahkan kepadamu.', NULL),
(4435, 3647, 27, 9, 'Pergilah ke tempat kambing domba kita, ambillah dari sana dua anak kambing yang baik, maka aku akan mengolahnya menjadi makanan yang enak bagi ayahmu, seperti yang digemarinya.', NULL),
(4436, 3647, 27, 10, 'Bawalah itu kepada ayahmu, supaya dimakannya, agar dia memberkati engkau, sebelum ia mati.\"', NULL),
(4437, 3647, 27, 11, 'Lalu kata Yakub kepada Ribka, ibunya: \"Tetapi Esau, kakakku, adalah seorang yang berbulu badannya, sedang aku ini kulitku licin.', NULL),
(4438, 3647, 27, 12, 'Mungkin ayahku akan meraba aku; maka nanti ia akan menyangka bahwa aku mau memperolok-olokkan dia; dengan demikian aku akan mendatangkan kutuk atas diriku dan bukan berkat.\"', NULL),
(4439, 3647, 27, 13, 'Tetapi ibunya berkata kepadanya: \"Akulah yang menanggung kutuk itu, anakku; dengarkan saja perkataanku, pergilah ambil kambing-kambing itu.\"', NULL),
(4440, 3647, 27, 14, 'Lalu ia pergi mengambil kambing-kambing itu dan membawanya kepada ibunya; sesudah itu ibunya mengolah makanan yang enak, seperti yang digemari ayahnya.', NULL),
(4441, 3647, 27, 15, 'Kemudian Ribka mengambil pakaian yang indah kepunyaan Esau, anak sulungnya, pakaian yang disimpannya di rumah, lalu disuruhnyalah dikenakan oleh Yakub, anak bungsunya.', NULL),
(4442, 3647, 27, 16, 'Dan kulit anak kambing itu dipalutkannya pada kedua tangan Yakub dan pada lehernya yang licin itu.', NULL),
(4443, 3647, 27, 17, 'Lalu ia memberikan makanan yang enak dan roti yang telah diolahnya itu kepada Yakub, anaknya.', NULL),
(4444, 3647, 27, 18, 'Demikianlah Yakub masuk ke tempat ayahnya serta berkata: \"Bapa!\" Sahut ayahnya: \"Ya, anakku; siapakah engkau?\"', NULL),
(4445, 3647, 27, 19, 'Kata Yakub kepada ayahnya: \"Akulah Esau, anak sulungmu. Telah kulakukan, seperti yang bapa katakan kepadaku. Bangunlah, duduklah dan makanlah daging buruan masakanku ini, agar bapa memberkati aku.\"', NULL),
(4446, 3647, 27, 20, 'Lalu Ishak berkata kepada anaknya itu: \"Lekas juga engkau mendapatnya, anakku!\" Jawabnya: \"Karena TUHAN, Allahmu, membuat aku mencapai tujuanku.\"', NULL),
(4447, 3647, 27, 21, 'Lalu kata Ishak kepada Yakub: \"Datanglah mendekat, anakku, supaya aku meraba engkau, apakah engkau ini anakku Esau atau bukan.\"', NULL),
(4448, 3647, 27, 22, 'Maka Yakub mendekati Ishak, ayahnya, dan ayahnya itu merabanya serta berkata: \"Kalau suara, suara Yakub; kalau tangan, tangan Esau.\"', NULL),
(4449, 3647, 27, 23, 'Jadi Ishak tidak mengenal dia, karena tangannya berbulu seperti tangan Esau, kakaknya. Ishak hendak memberkati dia,', NULL),
(4450, 3647, 27, 24, 'tetapi ia masih bertanya: \"Benarkah engkau ini anakku Esau?\" Jawabnya: \"Ya!\"', NULL),
(4451, 3647, 27, 25, 'Lalu berkatalah Ishak: \"Dekatkanlah makanan itu kepadaku, supaya kumakan daging buruan masakan anakku, agar aku memberkati engkau.\" Jadi didekatkannyalah makanan itu kepada ayahnya, lalu ia makan, dibawanya juga anggur kepadanya, lalu ia minum.', NULL),
(4452, 3647, 27, 26, 'Berkatalah Ishak, ayahnya, kepadanya: \"Datanglah dekat-dekat dan ciumlah aku, anakku.\"', NULL),
(4453, 3647, 27, 27, 'Lalu datanglah Yakub dekat-dekat dan diciumnyalah ayahnya. Ketika Ishak mencium bau pakaian Yakub, diberkatinyalah dia, katanya: \"Sesungguhnya bau anakku adalah sebagai bau padang yang diberkati TUHAN.', 'Yakub lari ke Mesopotamia'),
(4454, 3647, 27, 28, 'Allah akan memberikan kepadamu embun yang dari langit dan tanah-tanah gemuk di bumi dan gandum serta anggur berlimpah-limpah.', NULL),
(4455, 3647, 27, 29, 'Bangsa-bangsa akan takluk kepadamu, dan suku-suku bangsa akan sujud kepadamu; jadilah tuan atas saudara-saudaramu, dan anak-anak ibumu akan sujud kepadamu. Siapa yang mengutuk engkau, terkutuklah ia, dan siapa yang memberkati engkau, diberkatilah ia.\"', NULL),
(4456, 3647, 27, 30, 'Setelah Ishak selesai memberkati Yakub, dan baru saja Yakub keluar meninggalkan Ishak, ayahnya, pulanglah Esau, kakaknya, dari berburu.', NULL),
(4457, 3647, 27, 31, 'Ia juga menyediakan makanan yang enak, lalu membawanya kepada ayahnya. Katanya kepada ayahnya: \"Bapa, bangunlah dan makan daging buruan masakan anakmu, agar engkau memberkati aku.\"', NULL),
(4458, 3647, 27, 32, 'Tetapi kata Ishak, ayahnya, kepadanya: \"Siapakah engkau ini?\" Sahutnya: \"Akulah anakmu, anak sulungmu, Esau.\"', NULL),
(4459, 3647, 27, 33, 'Lalu terkejutlah Ishak dengan sangat serta berkata: \"Siapakah gerangan dia, yang memburu binatang itu dan yang telah membawanya kepadaku? Aku telah memakan semuanya, sebelum engkau datang, dan telah memberkati dia; dan dia akan tetap orang yang diberkati.\"', NULL),
(4460, 3647, 27, 34, 'Sesudah Esau mendengar perkataan ayahnya itu, meraung-raunglah ia dengan sangat keras dalam kepedihan hatinya serta berkata kepada ayahnya: \"Berkatilah aku ini juga, ya bapa!\"', NULL),
(4461, 3647, 27, 35, 'Jawab ayahnya: \"Adikmu telah datang dengan tipu daya dan telah merampas berkat yang untukmu itu.\"', NULL),
(4462, 3647, 27, 36, 'Kata Esau: \"Bukankah tepat namanya Yakub, karena ia telah dua kali menipu aku. Hak kesulunganku telah dirampasnya, dan sekarang dirampasnya pula berkat yang untukku.\" Lalu katanya: \"Apakah bapa tidak mempunyai berkat lain bagiku?\"', NULL),
(4463, 3647, 27, 37, 'Lalu Ishak menjawab Esau, katanya: \"Sesungguhnya telah kuangkat dia menjadi tuan atas engkau, dan segala saudaranya telah kuberikan kepadanya menjadi hambanya, dan telah kubekali dia dengan gandum dan anggur; maka kepadamu, apa lagi yang dapat kuperbuat, ya anakku?\"', NULL),
(4464, 3647, 27, 38, 'Kata Esau kepada ayahnya: \"Hanya berkat yang satu itukah ada padamu, ya bapa? Berkatilah aku ini juga, ya bapa!\" Dan dengan suara keras menangislah Esau.', NULL),
(4465, 3647, 27, 39, 'Lalu Ishak, ayahnya, menjawabnya: \"Sesungguhnya tempat kediamanmu akan jauh dari tanah-tanah gemuk di bumi dan jauh dari embun dari langit di atas.', NULL),
(4466, 3647, 27, 40, 'Engkau akan hidup dari pedangmu dan engkau akan menjadi hamba adikmu. Tetapi akan terjadi kelak, apabila engkau berusaha sungguh-sungguh, maka engkau akan melemparkan kuk itu dari tengkukmu.\"', NULL),
(4467, 3647, 27, 41, 'Esau menaruh dendam kepada Yakub karena berkat yang telah diberikan oleh ayahnya kepadanya, lalu ia berkata kepada dirinya sendiri: \"Hari-hari berkabung karena kematian ayahku itu tidak akan lama lagi; pada waktu itulah Yakub, adikku, akan kubunuh.\"', NULL),
(4468, 3647, 27, 42, 'Ketika diberitahukan perkataan Esau, anak sulungnya itu kepada Ribka, maka disuruhnyalah memanggil Yakub, anak bungsunya, lalu berkata kepadanya: \"Esau, kakakmu, bermaksud membalas dendam membunuh engkau.', NULL),
(4469, 3647, 27, 43, 'Jadi sekarang, anakku, dengarkanlah perkataanku, bersiaplah engkau dan larilah kepada Laban, saudaraku, ke Haran,', NULL),
(4470, 3647, 27, 44, 'dan tinggallah padanya beberapa waktu lamanya, sampai kegeraman', NULL),
(4471, 3647, 27, 45, 'dan kemarahan kakakmu itu surut dari padamu, dan ia lupa apa yang telah engkau perbuat kepadanya; kemudian aku akan menyuruh orang menjemput engkau dari situ. Mengapa aku akan kehilangan kamu berdua pada satu hari juga?\"', NULL),
(4472, 3647, 27, 46, 'Kemudian Ribka berkata kepada Ishak: \"Aku telah jemu hidup karena perempuan-perempuan Het itu; jikalau Yakub juga mengambil seorang isteri dari antara perempuan negeri ini, semacam perempuan Het itu, apa gunanya aku hidup lagi?\"', NULL),
(4473, 3647, 28, 1, 'Kemudian Ishak memanggil Yakub, lalu memberkati dia serta memesankan kepadanya, katanya: \"Janganlah mengambil isteri dari perempuan Kanaan.', NULL),
(4474, 3647, 28, 2, 'Bersiaplah, pergilah ke Padan-Aram, ke rumah Betuel, ayah ibumu, dan ambillah dari situ seorang isteri dari anak-anak Laban, saudara ibumu.', NULL),
(4475, 3647, 28, 3, 'Moga-moga Allah Yang Mahakuasa memberkati engkau, membuat engkau beranak cucu dan membuat engkau menjadi banyak, sehingga engkau menjadi sekumpulan bangsa-bangsa.', NULL),
(4476, 3647, 28, 4, 'Moga-moga Ia memberikan kepadamu berkat yang untuk Abraham, kepadamu serta kepada keturunanmu, sehingga engkau memiliki negeri ini yang kaudiami sebagai orang asing, yang telah diberikan Allah kepada Abraham.\"', NULL),
(4477, 3647, 28, 5, 'Demikianlah Ishak melepas Yakub, lalu berangkatlah Yakub ke Padan-Aram, kepada Laban anak Betuel, orang Aram itu, saudara Ribka ibu Yakub dan Esau.', NULL),
(4478, 3647, 28, 6, 'Ketika Esau melihat, bahwa Ishak telah memberkati Yakub dan melepasnya ke Padan-Aram untuk mengambil isteri dari situ--pada waktu ia memberkatinya ia telah memesankan kepada Yakub: \"Janganlah ambil isteri dari antara perempuan Kanaan\" --', NULL),
(4479, 3647, 28, 7, 'dan bahwa Yakub mendengarkan perkataan ayah dan ibunya, dan pergi ke Padan-Aram,', NULL),
(4480, 3647, 28, 8, 'maka Esaupun menyadari, bahwa perempuan Kanaan itu tidak disukai oleh Ishak, ayahnya.', NULL),
(4481, 3647, 28, 9, 'Sebab itu ia pergi kepada Ismael dan mengambil Mahalat menjadi isterinya, di samping kedua isterinya yang telah ada. Mahalat adalah anak Ismael anak Abraham, adik Nebayot.', NULL),
(4482, 3647, 28, 10, 'Maka Yakub berangkat dari Bersyeba dan pergi ke Haran.', 'Mimpi Yakub di Betel'),
(4483, 3647, 28, 11, 'Ia sampai di suatu tempat, dan bermalam di situ, karena matahari telah terbenam. Ia mengambil sebuah batu yang terletak di tempat itu dan dipakainya sebagai alas kepala, lalu membaringkan dirinya di tempat itu.', NULL),
(4484, 3647, 28, 12, 'Maka bermimpilah ia, di bumi ada didirikan sebuah tangga yang ujungnya sampai di langit, dan tampaklah malaikat-malaikat Allah turun naik di tangga itu.', NULL),
(4485, 3647, 28, 13, 'Berdirilah TUHAN di sampingnya dan berfirman: \"Akulah TUHAN, Allah Abraham, nenekmu, dan Allah Ishak; tanah tempat engkau berbaring ini akan Kuberikan kepadamu dan kepada keturunanmu.', NULL),
(4486, 3647, 28, 14, 'Keturunanmu akan menjadi seperti debu tanah banyaknya, dan engkau akan mengembang ke sebelah timur, barat, utara dan selatan, dan olehmu serta keturunanmu semua kaum di muka bumi akan mendapat berkat.', NULL),
(4487, 3647, 28, 15, 'Sesungguhnya Aku menyertai engkau dan Aku akan melindungi engkau, ke manapun engkau pergi, dan Aku akan membawa engkau kembali ke negeri ini, sebab Aku tidak akan meninggalkan engkau, melainkan tetap melakukan apa yang Kujanjikan kepadamu.\"', NULL),
(4488, 3647, 28, 16, 'Ketika Yakub bangun dari tidurnya, berkatalah ia: \"Sesungguhnya TUHAN ada di tempat ini, dan aku tidak mengetahuinya.\"', NULL),
(4489, 3647, 28, 17, 'Ia takut dan berkata: \"Alangkah dahsyatnya tempat ini. Ini tidak lain dari rumah Allah, ini pintu gerbang sorga.\"', NULL),
(4490, 3647, 28, 18, 'Keesokan harinya pagi-pagi Yakub mengambil batu yang dipakainya sebagai alas kepala dan mendirikan itu menjadi tugu dan menuang minyak ke atasnya.', NULL),
(4491, 3647, 28, 19, 'Ia menamai tempat itu Betel; dahulu nama kota itu Lus.', NULL),
(4492, 3647, 28, 20, 'Lalu bernazarlah Yakub: \"Jika Allah akan menyertai dan akan melindungi aku di jalan yang kutempuh ini, memberikan kepadaku roti untuk dimakan dan pakaian untuk dipakai,', NULL),
(4493, 3647, 28, 21, 'sehingga aku selamat kembali ke rumah ayahku, maka TUHAN akan menjadi Allahku.', NULL),
(4494, 3647, 28, 22, 'Dan batu yang kudirikan sebagai tugu ini akan menjadi rumah Allah. Dari segala sesuatu yang Engkau berikan kepadaku akan selalu kupersembahkan sepersepuluh kepada-Mu.\"', NULL),
(4495, 3647, 29, 1, 'Kemudian berangkatlah Yakub dari situ dan pergi ke negeri Bani Timur.', 'Yakub di rumah Laban'),
(4496, 3647, 29, 2, 'Ketika ia memandang sekelilingnya, dilihatnya ada sebuah sumur di padang, dan ada tiga kumpulan kambing domba berbaring di dekatnya, sebab dari sumur itulah orang memberi minum kumpulan-kumpulan kambing domba itu. Adapun batu penutup sumur itu besar;', NULL),
(4497, 3647, 29, 3, 'dan apabila segala kumpulan kambing domba itu digiring berkumpul ke sana, maka gembala-gembala menggulingkan batu itu dari mulut sumur, lalu kambing domba itu diberi minum; kemudian dikembalikanlah batu itu lagi ke mulut sumur itu.', NULL),
(4498, 3647, 29, 4, 'Bertanyalah Yakub kepada mereka: \"Saudara-saudara, dari manakah kamu ini?\" Jawab mereka: \"Kami ini dari Haran.\"', NULL),
(4499, 3647, 29, 5, 'Lagi katanya kepada mereka: \"Kenalkah kamu Laban, cucu Nahor?\" Jawab mereka: \"Kami kenal.\"', NULL),
(4500, 3647, 29, 6, 'Selanjutnya katanya kepada mereka: \"Selamatkah ia?\" Jawab mereka: \"Selamat! Tetapi lihat, itu datang anaknya perempuan, Rahel, dengan kambing dombanya.\"', NULL),
(4501, 3647, 29, 7, 'Lalu kata Yakub: \"Hari masih siang, belum waktunya untuk mengumpulkan ternak; berilah minum kambing dombamu itu, kemudian pergilah menggembalakannya lagi.\"', NULL),
(4502, 3647, 29, 8, 'Tetapi jawab mereka: \"Kami tidak dapat melakukan itu selama segala kumpulan binatang itu belum berkumpul; barulah batu itu digulingkan dari mulut sumur dan kami memberi minum kambing domba kami.\"', NULL),
(4503, 3647, 29, 9, 'Selagi ia berkata-kata dengan mereka, datanglah Rahel dengan kambing domba ayahnya, sebab dialah yang menggembalakannya.', NULL),
(4504, 3647, 29, 10, 'Ketika Yakub melihat Rahel, anak Laban saudara ibunya, serta kambing domba Laban, ia datang mendekat, lalu menggulingkan batu itu dari mulut sumur, dan memberi minum kambing domba itu.', NULL),
(4505, 3647, 29, 11, 'Kemudian Yakub mencium Rahel serta menangis dengan suara keras.', NULL),
(4506, 3647, 29, 12, 'Lalu Yakub menceritakan kepada Rahel, bahwa ia sanak saudara ayah Rahel, dan anak Ribka. Maka berlarilah Rahel menceritakannya kepada ayahnya.', NULL),
(4507, 3647, 29, 13, 'Segera sesudah Laban mendengar kabar tentang Yakub, anak saudaranya itu, berlarilah ia menyongsong dia, lalu mendekap dan mencium dia, kemudian membawanya ke rumahnya. Maka Yakub menceritakan segala hal ihwalnya kepada Laban.', NULL),
(4508, 3647, 29, 14, 'Kata Laban kepadanya: \"Sesungguhnya engkau sedarah sedaging dengan aku.\" Maka tinggallah Yakub padanya genap sebulan lamanya.', NULL),
(4509, 3647, 29, 15, 'Kemudian berkatalah Laban kepada Yakub: \"Masakan karena engkau adalah sanak saudaraku, engkau bekerja padaku dengan cuma-cuma? Katakanlah kepadaku apa yang patut menjadi upahmu.\"', NULL),
(4510, 3647, 29, 16, 'Laban mempunyai dua anak perempuan; yang lebih tua namanya Lea dan yang lebih muda namanya Rahel.', NULL),
(4511, 3647, 29, 17, 'Lea tidak berseri matanya, tetapi Rahel itu elok sikapnya dan cantik parasnya.', NULL),
(4512, 3647, 29, 18, 'Yakub cinta kepada Rahel, sebab itu ia berkata: \"Aku mau bekerja padamu tujuh tahun lamanya untuk mendapat Rahel, anakmu yang lebih muda itu.\"', NULL),
(4513, 3647, 29, 19, 'Sahut Laban: \"Lebih baiklah ia kuberikan kepadamu dari pada kepada orang lain; maka tinggallah padaku.\"', NULL),
(4514, 3647, 29, 20, 'Jadi bekerjalah Yakub tujuh tahun lamanya untuk mendapat Rahel itu, tetapi yang tujuh tahun itu dianggapnya seperti beberapa hari saja, karena cintanya kepada Rahel.', NULL),
(4515, 3647, 29, 21, 'Sesudah itu berkatalah Yakub kepada Laban: \"Berikanlah kepadaku bakal isteriku itu, sebab jangka waktuku telah genap, supaya aku akan kawin dengan dia.\"', NULL),
(4516, 3647, 29, 22, 'Lalu Laban mengundang semua orang di tempat itu, dan mengadakan perjamuan.', NULL),
(4517, 3647, 29, 23, 'Tetapi pada waktu malam diambilnyalah Lea, anaknya, lalu dibawanya kepada Yakub. Maka Yakubpun menghampiri dia.', NULL),
(4518, 3647, 29, 24, 'Lagipula Laban memberikan Zilpa, budaknya perempuan, kepada Lea, anaknya itu, menjadi budaknya.', NULL),
(4519, 3647, 29, 25, 'Tetapi pada waktu pagi tampaklah bahwa itu Lea! Lalu berkatalah Yakub kepada Laban: \"Apakah yang kauperbuat terhadap aku ini? Bukankah untuk mendapat Rahel aku bekerja padamu? Mengapa engkau menipu aku?\"', NULL),
(4520, 3647, 29, 26, 'Jawab Laban: \"Tidak biasa orang berbuat demikian di tempat kami ini, mengawinkan adiknya lebih dahulu dari pada kakaknya.', NULL),
(4521, 3647, 29, 27, 'Genapilah dahulu tujuh hari perkawinanmu dengan anakku ini; kemudian anakku yang lainpun akan diberikan kepadamu sebagai upah, asal engkau bekerja pula padaku tujuh tahun lagi.\"', NULL),
(4522, 3647, 29, 28, 'Maka Yakub berbuat demikian; ia menggenapi ketujuh hari perkawinannya dengan Lea, kemudian Laban memberikan kepadanya Rahel, anaknya itu, menjadi isterinya.', NULL),
(4523, 3647, 29, 29, 'Lagipula Laban memberikan Bilha, budaknya perempuan, kepada Rahel, anaknya itu, menjadi budaknya.', NULL),
(4524, 3647, 29, 30, 'Yakub menghampiri Rahel juga, malah ia lebih cinta kepada Rahel dari pada kepada Lea. Demikianlah ia bekerja pula pada Laban tujuh tahun lagi.', NULL),
(4525, 3647, 29, 31, 'Ketika TUHAN melihat, bahwa Lea tidak dicintai, dibuka-Nyalah kandungannya, tetapi Rahel mandul.', 'Anak-anak Yakub'),
(4526, 3647, 29, 32, 'Lea mengandung, lalu melahirkan seorang anak laki-laki, dan menamainya Ruben, sebab katanya: \"Sesungguhnya TUHAN telah memperhatikan kesengsaraanku; sekarang tentulah aku akan dicintai oleh suamiku.\"', NULL),
(4527, 3647, 29, 33, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: \"Sesungguhnya, TUHAN telah mendengar, bahwa aku tidak dicintai, lalu diberikan-Nya pula anak ini kepadaku.\" Maka ia menamai anak itu Simeon.', NULL),
(4528, 3647, 29, 34, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: \"Sekali ini suamiku akan lebih erat kepadaku, karena aku telah melahirkan tiga anak laki-laki baginya.\" Itulah sebabnya ia menamai anak itu Lewi.', NULL),
(4529, 3647, 29, 35, 'Mengandung pulalah ia, lalu melahirkan seorang anak laki-laki, maka ia berkata: \"Sekali ini aku akan bersyukur kepada TUHAN.\" Itulah sebabnya ia menamai anak itu Yehuda. Sesudah itu ia tidak melahirkan lagi.', NULL),
(6196, 3647, 30, 1, 'Ketika dilihat Rahel, bahwa ia tidak melahirkan anak bagi Yakub, cemburulah ia kepada kakaknya itu, lalu berkata kepada Yakub: \"Berikanlah kepadaku anak; kalau tidak, aku akan mati.\"', NULL),
(6197, 3647, 30, 2, 'Maka bangkitlah amarah Yakub terhadap Rahel dan ia berkata: \"Akukah pengganti Allah, yang telah menghalangi engkau mengandung?\"', NULL),
(6198, 3647, 30, 3, 'Kata Rahel: \"Ini Bilha, budakku perempuan, hampirilah dia, supaya ia melahirkan anak di pangkuanku, dan supaya oleh dia akupun mempunyai keturunan.\"', NULL),
(6199, 3647, 30, 4, 'Maka diberikannyalah Bilha, budaknya itu, kepada Yakub menjadi isterinya dan Yakub menghampiri budak itu.', NULL),
(6200, 3647, 30, 5, 'Bilha mengandung, lalu melahirkan seorang anak laki-laki bagi Yakub.', NULL),
(6201, 3647, 30, 6, 'Berkatalah Rahel: \"Allah telah memberikan keadilan kepadaku, juga telah didengarkan-Nya permohonanku dan diberikan-Nya kepadaku seorang anak laki-laki.\" Itulah sebabnya ia menamai anak itu Dan.', NULL),
(6202, 3647, 30, 7, 'Mengandung pulalah Bilha, budak perempuan Rahel, lalu melahirkan anak laki-laki yang kedua bagi Yakub.', NULL),
(6203, 3647, 30, 8, 'Berkatalah Rahel: \"Aku telah sangat hebat bergulat dengan kakakku, dan akupun menang.\" Maka ia menamai anak itu Naftali.', NULL),
(6204, 3647, 30, 9, 'Ketika dilihat Lea, bahwa ia tidak melahirkan lagi, diambilnyalah Zilpa, budaknya perempuan, dan diberikannya kepada Yakub menjadi isterinya.', NULL),
(6205, 3647, 30, 10, 'Dan Zilpa, budak perempuan Lea, melahirkan seorang anak laki-laki bagi Yakub.', NULL),
(6206, 3647, 30, 11, 'Berkatalah Lea: \"Mujur telah datang.\" Maka ia menamai anak itu Gad.', NULL),
(6207, 3647, 30, 12, 'Dan Zilpa, budak perempuan Lea, melahirkan anak laki-laki yang kedua bagi Yakub.', NULL),
(6208, 3647, 30, 13, 'Berkatalah Lea: \"Aku ini berbahagia! Tentulah perempuan-perempuan akan menyebutkan aku berbahagia.\" Maka ia menamai anak itu Asyer.', NULL),
(6209, 3647, 30, 14, 'Ketika Ruben pada musim menuai gandum pergi berjalan-jalan, didapatinyalah di padang buah dudaim, lalu dibawanya kepada Lea, ibunya. Kata Rahel kepada Lea: \"Berilah aku beberapa buah dudaim yang didapat oleh anakmu itu.\"', NULL),
(6210, 3647, 30, 15, 'Jawab Lea kepadanya: \"Apakah belum cukup bagimu mengambil suamiku? Sekarang pula mau mengambil lagi buah dudaim anakku?\" Kata Rahel: \"Kalau begitu biarlah ia tidur dengan engkau pada malam ini sebagai ganti buah dudaim anakmu itu.\"', NULL),
(6211, 3647, 30, 16, 'Ketika Yakub pada waktu petang datang dari padang, pergilah Lea mendapatkannya, sambil berkata: \"Engkau harus singgah kepadaku malam ini, sebab memang engkau telah kusewa dengan buah dudaim anakku.\" Sebab itu tidurlah Yakub dengan Lea pada malam itu.', NULL),
(6212, 3647, 30, 17, 'Lalu Allah mendengarkan permohonan Lea. Lea mengandung dan melahirkan anak laki-laki yang kelima bagi Yakub.', NULL),
(6213, 3647, 30, 18, 'Lalu kata Lea: \"Allah telah memberi upahku, karena aku telah memberi budakku perempuan kepada suamiku.\" Maka ia menamai anak itu Isakhar.', NULL),
(6214, 3647, 30, 19, 'Kemudian Lea mengandung pula dan melahirkan anak laki-laki yang keenam bagi Yakub.', NULL),
(6215, 3647, 30, 20, 'Berkatalah Lea: \"Allah telah memberikan hadiah yang indah kepadaku; sekali ini suamiku akan tinggal bersama-sama dengan aku, karena aku telah melahirkan enam orang anak laki-laki baginya.\" Maka ia menamai anak itu Zebulon.', NULL),
(6216, 3647, 30, 21, 'Sesudah itu ia melahirkan seorang anak perempuan dan menamai anak itu Dina.', NULL),
(6217, 3647, 30, 22, 'Lalu ingatlah Allah akan Rahel; Allah mendengarkan permohonannya serta membuka kandungannya.', NULL),
(6218, 3647, 30, 23, 'Maka mengandunglah Rahel dan melahirkan seorang anak laki-laki. Berkatalah ia: \"Allah telah menghapuskan aibku.\"', NULL),
(6219, 3647, 30, 24, 'Maka ia menamai anak itu Yusuf, sambil berkata: \"Mudah-mudahan TUHAN menambah seorang anak laki-laki lagi bagiku.\"', NULL),
(6220, 3647, 30, 25, 'Setelah Rahel melahirkan Yusuf, berkatalah Yakub kepada Laban: \"Izinkanlah aku pergi, supaya aku pulang ke tempat kelahiranku dan ke negeriku.', 'Yakub memperoleh ternak'),
(6221, 3647, 30, 26, 'Berikanlah isteri-isteriku dan anak-anakku, yang menjadi upahku selama aku bekerja padamu, supaya aku pulang, sebab engkau tahu, betapa keras aku bekerja padamu.\"', NULL),
(6222, 3647, 30, 27, 'Tetapi Laban berkata kepadanya: \"Sekiranya aku mendapat kasihmu! Telah nyata kepadaku, bahwa TUHAN memberkati aku karena engkau.\"', NULL),
(6223, 3647, 30, 28, 'Lagi katanya: \"Tentukanlah upahmu yang harus kubayar, maka aku akan memberikannya.\"', NULL),
(6224, 3647, 30, 29, 'Sahut Yakub kepadanya: \"Engkau sendiri tahu, bagaimana aku bekerja padamu, dan bagaimana keadaan ternakmu dalam penjagaanku,', NULL),
(6225, 3647, 30, 30, 'sebab harta milikmu tidak begitu banyak sebelum aku datang, tetapi sekarang telah berkembang dengan sangat, dan TUHAN telah memberkati engkau sejak aku berada di sini; jadi, bilakah dapat aku bekerja untuk rumah tanggaku sendiri?\"', NULL),
(6226, 3647, 30, 31, 'Kata Laban: \"Apakah yang harus kuberikan kepadamu?\" Jawab Yakub: \"Tidak usah kauberikan apa-apa kepadaku; aku mau lagi menggembalakan kambing dombamu dan menjaganya, asal engkau mengizinkan hal ini kepadaku:', NULL),
(6227, 3647, 30, 32, 'Hari ini aku akan lewat dari tengah-tengah segala kambing dombamu dan akan mengasingkan dari situ setiap binatang yang berbintik-bintik dan berbelang-belang; segala domba yang hitam dan segala kambing yang berbelang-belang dan berbintik-bintik, itulah upahku.', NULL),
(6228, 3647, 30, 33, 'Dan kejujuranku akan terbukti di kemudian hari, apabila engkau datang memeriksa upahku: Segala yang tidak berbintik-bintik atau berbelang-belang di antara kambing-kambing dan yang tidak hitam di antara domba-domba, anggaplah itu tercuri olehku.\"', NULL),
(6229, 3647, 30, 34, 'Kemudian kata Laban: \"Baik, jadilah seperti perkataanmu itu.\"', NULL),
(6230, 3647, 30, 35, 'Lalu diasingkannyalah pada hari itu kambing-kambing jantan yang bercoreng-coreng dan berbelang-belang dan segala kambing yang berbintik-bintik dan berbelang-belang, segala yang ada warna putih pada badannya, serta segala yang hitam di antara domba-domba, dan diserahkannyalah semuanya itu kepada anak-anaknya untuk dijaga.', NULL),
(6231, 3647, 30, 36, 'Kemudian Laban menentukan jarak tiga hari perjalanan jauhnya antara dia dan Yakub, maka tetaplah Yakub menggembalakan kambing domba yang tinggal itu.', NULL),
(6232, 3647, 30, 37, 'Lalu Yakub mengambil dahan hijau dari pohon hawar, pohon badam dan pohon berangan, dikupasnyalah dahan-dahan itu sehingga berbelang-belang, sampai yang putihnya kelihatan.', NULL),
(6233, 3647, 30, 38, 'Ia meletakkan dahan-dahan yang dikupasnya itu dalam palungan, dalam tempat minum, ke mana kambing domba itu datang minum, sehingga tepat di depan kambing domba itu. Adapun kambing domba itu suka berkelamin pada waktu datang minum.', NULL),
(6234, 3647, 30, 39, 'Jika kambing domba itu berkelamin dekat dahan-dahan itu, maka anaknya bercoreng-coreng, berbintik-bintik dan berbelang-belang.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(6235, 3647, 30, 40, 'Kemudian Yakub memisahkan domba-domba itu, dihadapkannya kepala-kepala kambing domba itu kepada yang bercoreng-coreng dan kepada segala yang hitam di antara kambing domba Laban. Demikianlah ia beroleh kumpulan-kumpulan hewan baginya sendiri, dan tidak ditempatkannya pada kambing domba Laban.', NULL),
(6236, 3647, 30, 41, 'Dan setiap kali, apabila berkelamin kambing domba yang kuat, maka Yakub meletakkan dahan-dahan itu ke dalam palungan di depan mata kambing domba itu, supaya berkelamin dekat dahan-dahan itu.', NULL),
(6237, 3647, 30, 42, 'Tetapi apabila datang kambing domba yang lemah, ia tidak meletakkan dahan-dahan itu ke dalamnya. Jadi hewan yang lemah untuk Laban dan yang kuat untuk Yakub.', NULL),
(6238, 3647, 30, 43, 'Maka sangatlah bertambah-tambah harta Yakub, dan ia mempunyai banyak kambing domba, budak perempuan dan laki-laki, unta dan keledai.', NULL),
(6239, 3647, 31, 1, 'Kedengaranlah kepada Yakub anak-anak Laban berkata demikian: \"Yakub telah mengambil segala harta milik ayah kita dan dari harta itulah ia membangun segala kekayaannya.\"', 'Yakub lari meninggalkan Laban'),
(6240, 3647, 31, 2, 'Lagi kelihatan kepada Yakub dari muka Laban, bahwa Laban tidak lagi seperti yang sudah-sudah kepadanya.', NULL),
(6241, 3647, 31, 3, 'Lalu berfirmanlah TUHAN kepada Yakub: \"Pulanglah ke negeri nenek moyangmu dan kepada kaummu, dan Aku akan menyertai engkau.\"', NULL),
(6242, 3647, 31, 4, 'Sesudah itu Yakub menyuruh memanggil Rahel dan Lea untuk datang ke padang, ke tempat kambing dombanya,', NULL),
(6243, 3647, 31, 5, 'lalu ia berkata kepada mereka: \"Telah kulihat dari muka ayahmu, bahwa ia tidak lagi seperti yang sudah-sudah kepadaku, tetapi Allah ayahku menyertai aku.', NULL),
(6244, 3647, 31, 6, 'Juga kamu sendiri tahu, bahwa aku telah bekerja sekuat-kuatku pada ayahmu.', NULL),
(6245, 3647, 31, 7, 'Tetapi ayahmu telah berlaku curang kepadaku dan telah sepuluh kali mengubah upahku, tetapi Allah tidak membiarkan dia berbuat jahat kepadaku.', NULL),
(6246, 3647, 31, 8, 'Apabila ia berkata: yang berbintik-bintiklah akan menjadi upahmu, maka segala kambing domba itu beroleh anak yang berbintik-bintik; dan apabila ia berkata: yang bercoreng-corenglah akan menjadi upahmu, maka segala kambing domba itu beroleh anak yang bercoreng-coreng.', NULL),
(6247, 3647, 31, 9, 'Demikianlah Allah mengambil ternak ayahmu dan memberikannya kepadaku.', NULL),
(6248, 3647, 31, 10, 'Pada suatu kali pada masa kambing domba itu suka berkelamin, maka aku bermimpi dan melihat, bahwa jantan-jantan yang menjantani kambing domba itu bercoreng-coreng, berbintik-bintik dan berbelang-belang.', NULL),
(6249, 3647, 31, 11, 'Dan Malaikat Allah berfirman kepadaku dalam mimpi itu: Yakub! Jawabku: Ya Tuhan!', NULL),
(6250, 3647, 31, 12, 'Lalu Ia berfirman: Angkatlah mukamu dan lihatlah, bahwa segala jantan yang menjantani kambing domba itu bercoreng-coreng, berbintik-bintik dan berbelang-belang, sebab telah Kulihat semua yang dilakukan oleh Laban itu kepadamu.', NULL),
(6251, 3647, 31, 13, 'Akulah Allah yang di Betel itu, di mana engkau mengurapi tugu, dan di mana engkau bernazar kepada-Ku; maka sekarang, bersiaplah engkau, pergilah dari negeri ini dan pulanglah ke negeri sanak saudaramu.\"', NULL),
(6252, 3647, 31, 14, 'Lalu Rahel dan Lea menjawab Yakub, katanya: \"Bukankah tidak ada lagi bagian atau warisan kami dalam rumah ayah kami?', NULL),
(6253, 3647, 31, 15, 'Bukankah kami ini dianggapnya sebagai orang asing, karena ia telah menjual kami? Juga bagian kami telah dihabiskannya sama sekali.', NULL),
(6254, 3647, 31, 16, 'Tetapi segala kekayaan, yang telah diambil Allah dari ayah kami, adalah milik kami dan anak-anak kami; maka sekarang, perbuatlah segala yang difirmankan Allah kepadamu.\"', NULL),
(6255, 3647, 31, 17, 'Lalu bersiaplah Yakub, dinaikkannya anak-anaknya dan isteri-isterinya ke atas unta,', NULL),
(6256, 3647, 31, 18, 'digiringnya seluruh ternaknya dan segala apa yang telah diperolehnya, yakni ternak kepunyaannya, yang telah diperolehnya di Padan-Aram, dengan maksud pergi kepada Ishak, ayahnya, ke tanah Kanaan.', NULL),
(6257, 3647, 31, 19, 'Adapun Laban telah pergi menggunting bulu domba-dombanya. Ketika itulah Rahel mencuri terafim ayahnya.', NULL),
(6258, 3647, 31, 20, 'Dan Yakub mengakali Laban, orang Aram itu, dengan tidak memberitahukan kepadanya, bahwa ia mau lari.', NULL),
(6259, 3647, 31, 21, 'Demikianlah ia lari dengan segala harta miliknya. Ia berangkat, menyeberangi sungai Efrat dan berjalan menuju pegunungan Gilead.', NULL),
(6260, 3647, 31, 22, 'Ketika pada hari ketiga dikabarkan kepada Laban, bahwa Yakub telah lari,', 'Laban mengejar Yakub'),
(6261, 3647, 31, 23, 'dibawanyalah sanak saudaranya bersama-sama, dikejarnya Yakub tujuh hari perjalanan jauhnya, lalu ia dapat menyusulnya di pegunungan Gilead.', NULL),
(6262, 3647, 31, 24, 'Pada waktu malam datanglah Allah dalam suatu mimpi kepada Laban, orang Aram itu, serta berfirman kepadanya: \"Jagalah baik-baik, supaya engkau jangan mengatai Yakub dengan sepatah katapun.\"', NULL),
(6263, 3647, 31, 25, 'Ketika Laban sampai kepada Yakub, --Yakub telah memasang kemahnya di pegunungan, juga Laban dengan sanak saudaranya telah memasang kemahnya di pegunungan Gilead--', NULL),
(6264, 3647, 31, 26, 'berkatalah Laban kepada Yakub: \"Apakah yang kauperbuat ini, maka engkau mengakali aku dan mengangkut anak-anakku perempuan sebagai orang tawanan?', NULL),
(6265, 3647, 31, 27, 'Mengapa engkau lari diam-diam dan mengakali aku? Mengapa engkau tidak memberitahu kepadaku, supaya aku menghantarkan engkau dengan sukacita dan nyanyian dengan rebana dan kecapi?', NULL),
(6266, 3647, 31, 28, 'Lagipula engkau tidak memberikan aku kesempatan untuk mencium cucu-cucuku laki-laki dan anak-anakku perempuan. Memang bodoh perbuatanmu itu.', NULL),
(6267, 3647, 31, 29, 'Aku ini berkuasa untuk berbuat jahat kepadamu, tetapi Allah ayahmu telah berfirman kepadaku tadi malam: Jagalah baik-baik, jangan engkau mengatai Yakub dengan sepatah katapun.', NULL),
(6268, 3647, 31, 30, 'Maka sekarang, kalau memang engkau harus pergi, semata-mata karena sangat rindu ke rumah ayahmu, mengapa engkau mencuri dewa-dewaku?\"', NULL),
(6269, 3647, 31, 31, 'Lalu Yakub menjawab Laban: \"Aku takut, karena pikirku, jangan-jangan engkau merampas anak-anakmu itu dari padaku.', NULL),
(6270, 3647, 31, 32, 'Tetapi pada siapa engkau menemui dewa-dewamu itu, janganlah ia hidup lagi. Periksalah di depan saudara-saudara kita segala barang yang ada padaku dan ambillah barangmu.\" Sebab Yakub tidak tahu, bahwa Rahel yang mencuri terafim itu.', NULL),
(6271, 3647, 31, 33, 'Lalu masuklah Laban ke dalam kemah Yakub dan ke dalam kemah Lea dan ke dalam kemah kedua budak perempuan itu, tetapi terafim itu tidak ditemuinya. Setelah keluar dari kemah Lea, ia masuk ke dalam kemah Rahel.', NULL),
(6272, 3647, 31, 34, 'Tetapi Rahel telah mengambil terafim itu dan memasukkannya ke dalam pelana untanya, dan duduk di atasnya. Laban menggeledah seluruh kemah itu, tetapi terafim itu tidak ditemuinya.', NULL),
(6273, 3647, 31, 35, 'Lalu kata Rahel kepada ayahnya: \"Janganlah bapa marah, karena aku tidak dapat bangun berdiri di depanmu, sebab aku sedang haid.\" Dan Laban mencari dengan teliti, tetapi ia tidak menemui terafim itu.', NULL),
(6274, 3647, 31, 36, 'Lalu hati Yakub panas dan ia bertengkar dengan Laban. Ia berkata kepada Laban: \"Apakah kesalahanku, apakah dosaku, maka engkau memburu aku sehebat itu?', NULL),
(6275, 3647, 31, 37, 'Engkau telah menggeledah segala barangku, sekarang apakah yang kautemui dari segala barang rumahmu? Letakkanlah di sini di depan saudara-saudaraku dan saudara-saudaramu, supaya mereka mengadili antara kita berdua.', NULL),
(6276, 3647, 31, 38, 'Selama dua puluh tahun ini aku bersama-sama dengan engkau; domba dan kambing betinamu tidak pernah keguguran dan jantan dari kambing dombamu tidak pernah kumakan.', NULL),
(6277, 3647, 31, 39, 'Yang diterkam oleh binatang buas tidak pernah kubawa kepadamu, aku sendiri yang menggantinya; yang dicuri orang, baik waktu siang, baik waktu malam, selalu engkau tuntut dari padaku.', NULL),
(6278, 3647, 31, 40, 'Aku dimakan panas hari waktu siang dan kedinginan waktu malam, dan mataku jauh dari pada tertidur.', NULL),
(6279, 3647, 31, 41, 'Selama dua puluh tahun ini aku di rumahmu; aku telah bekerja padamu empat belas tahun lamanya untuk mendapat kedua anakmu dan enam tahun untuk mendapat ternakmu, dan engkau telah sepuluh kali mengubah upahku.', NULL),
(6280, 3647, 31, 42, 'Seandainya Allah ayahku, Allah Abraham dan Yang Disegani oleh Ishak tidak menyertai aku, tentulah engkau sekarang membiarkan aku pergi dengan tangan hampa; tetapi kesengsaraanku dan jerih payahku telah diperhatikan Allah dan Ia telah menjatuhkan putusan tadi malam.\"', NULL),
(6281, 3647, 31, 43, 'Lalu Laban menjawab Yakub: \"Perempuan-perempuan ini anakku dan anak-anak lelaki ini cucuku dan ternak ini ternakku, bahkan segala yang kaulihat di sini adalah milikku; jadi apakah yang dapat kuperbuat sekarang kepada anak-anakku ini atau kepada anak-anak yang dilahirkan mereka?', 'Perjanjian antara Yakub dan Laban'),
(6282, 3647, 31, 44, 'Maka sekarang, marilah kita mengikat perjanjian, aku dan engkau, supaya itu menjadi kesaksian antara aku dan engkau.\"', NULL),
(6283, 3647, 31, 45, 'Kemudian Yakub mengambil sebuah batu dan didirikannya menjadi tugu.', NULL),
(6284, 3647, 31, 46, 'Selanjutnya berkatalah Yakub kepada sanak saudaranya: \"Kumpulkanlah batu.\" Maka mereka mengambil batu dan membuat timbunan, lalu makanlah mereka di sana di dekat timbunan itu.', NULL),
(6285, 3647, 31, 47, 'Laban menamai timbunan batu itu Yegar-Sahaduta, tetapi Yakub menamainya Galed.', NULL),
(6286, 3647, 31, 48, 'Lalu kata Laban: \"Timbunan batu inilah pada hari ini menjadi kesaksian antara aku dan engkau.\" Itulah sebabnya timbunan itu dinamainya Galed,', NULL),
(6287, 3647, 31, 49, 'dan juga Mizpa, sebab katanya: \"TUHAN kiranya berjaga-jaga antara aku dan engkau, apabila kita berjauhan.', NULL),
(6288, 3647, 31, 50, 'Jika engkau mengaibkan anak-anakku, dan jika engkau mengambil isteri lain di samping anak-anakku itu, ingatlah, walaupun tidak ada orang dekat kita, Allah juga yang menjadi saksi antara aku dan engkau.\"', NULL),
(6289, 3647, 31, 51, 'Selanjutnya kata Laban kepada Yakub: \"Inilah timbunan batu, dan inilah tugu yang kudirikan antara aku dan engkau--', NULL),
(6290, 3647, 31, 52, 'timbunan batu dan tugu inilah menjadi kesaksian, bahwa aku tidak akan melewati timbunan batu ini mendapatkan engkau, dan bahwa engkaupun tidak akan melewati timbunan batu dan tugu ini mendapatkan aku, dengan berniat jahat.', NULL),
(6291, 3647, 31, 53, 'Allah Abraham dan Allah Nahor, Allah ayah mereka, kiranya menjadi hakim antara kita.\" Lalu Yakub bersumpah demi Yang Disegani oleh Ishak, ayahnya.', NULL),
(6292, 3647, 31, 54, 'Dan Yakub mempersembahkan korban sembelihan di gunung itu. Ia mengundang makan sanak saudaranya, lalu mereka makan serta bermalam di gunung itu.', NULL),
(6293, 3647, 31, 55, 'Keesokan harinya pagi-pagi Laban mencium cucu-cucunya dan anak-anaknya serta memberkati mereka, kemudian pulanglah Laban kembali ke tempat tinggalnya.', NULL),
(6294, 3647, 32, 1, 'Yakub melanjutkan perjalanannya, lalu bertemulah malaikat-malaikat Allah dengan dia.', 'Yakub takut bertemu dengan Esau'),
(6295, 3647, 32, 2, 'Ketika Yakub melihat mereka, berkatalah ia: \"Ini bala tentara Allah.\" Sebab itu dinamainyalah tempat itu Mahanaim.', NULL),
(6296, 3647, 32, 3, 'Sesudah itu Yakub menyuruh utusannya berjalan lebih dahulu mendapatkan Esau, kakaknya, ke tanah Seir, daerah Edom.', NULL),
(6297, 3647, 32, 4, 'Ia memerintahkan kepada mereka: \"Beginilah kamu katakan kepada tuanku, kepada Esau: Beginilah kata hambamu Yakub: Aku telah tinggal pada Laban sebagai orang asing dan diam di situ selama ini.', NULL),
(6298, 3647, 32, 5, 'Aku telah mempunyai lembu sapi, keledai dan kambing domba, budak laki-laki dan perempuan, dan aku menyuruh memberitahukan hal ini kepada tuanku, supaya aku mendapat kasihmu.\"', NULL),
(6299, 3647, 32, 6, 'Kemudian pulanglah para utusan itu kepada Yakub dan berkata: \"Kami telah sampai kepada kakakmu, kepada Esau, dan iapun sedang di jalan menemui engkau, diiringi oleh empat ratus orang.\"', NULL),
(6300, 3647, 32, 7, 'Lalu sangat takutlah Yakub dan merasa sesak hati; maka dibaginyalah orang-orangnya yang bersama-sama dengan dia, kambing dombanya, lembu sapi dan untanya menjadi dua pasukan.', NULL),
(6301, 3647, 32, 8, 'Sebab pikirnya: \"Jika Esau datang menyerang pasukan yang satu, sehingga terpukul kalah, maka pasukan yang tinggal akan terluput.\"', NULL),
(6302, 3647, 32, 9, 'Kemudian berkatalah Yakub: \"Ya Allah nenekku Abraham dan Allah ayahku Ishak, ya TUHAN, yang telah berfirman kepadaku: Pulanglah ke negerimu serta kepada sanak saudaramu dan Aku akan berbuat baik kepadamu--', NULL),
(6303, 3647, 32, 10, 'sekali-kali aku tidak layak untuk menerima segala kasih dan kesetiaan yang Engkau tunjukkan kepada hamba-Mu ini, sebab aku membawa hanya tongkatku ini waktu aku menyeberangi sungai Yordan ini, tetapi sekarang telah menjadi dua pasukan.', NULL),
(6304, 3647, 32, 11, 'Lepaskanlah kiranya aku dari tangan kakakku, dari tangan Esau, sebab aku takut kepadanya, jangan-jangan ia datang membunuh aku, juga ibu-ibu dengan anak-anaknya.', NULL),
(6305, 3647, 32, 12, 'Bukankah Engkau telah berfirman: Tentu Aku akan berbuat baik kepadamu dan menjadikan keturunanmu sebagai pasir di laut, yang karena banyaknya tidak dapat dihitung.\"', NULL),
(6306, 3647, 32, 13, 'Lalu bermalamlah ia di sana pada malam itu. Kemudian diambilnyalah dari apa yang ada padanya suatu persembahan untuk Esau, kakaknya,', NULL),
(6307, 3647, 32, 14, 'yaitu dua ratus kambing betina dan dua puluh kambing jantan, dua ratus domba betina dan dua puluh domba jantan,', NULL),
(6308, 3647, 32, 15, 'tiga puluh unta yang sedang menyusui beserta anak-anaknya, empat puluh lembu betina dan sepuluh lembu jantan, dua puluh keledai betina dan sepuluh keledai jantan.', NULL),
(6309, 3647, 32, 16, 'Diserahkannyalah semuanya itu kepada budak-budaknya untuk dijaga, tiap-tiap kumpulan tersendiri, dan ia berkata kepada mereka: \"Berjalanlah kamu lebih dahulu dan jagalah supaya ada jarak antara kumpulan yang satu dengan kumpulan yang lain.\"', NULL),
(6310, 3647, 32, 17, 'Diperintahkannyalah kepada yang paling di muka: \"Apabila Esau, kakakku, bertemu dengan engkau dan bertanya kepadamu: Siapakah tuanmu? dan ke manakah engkau pergi? dan milik siapakah ternak yang di depanmu itu? --', NULL),
(6311, 3647, 32, 18, 'jawablah: milik hambamu Yakub; inilah persembahan yang dikirim kepada tuanku Esau, dan Yakub sendiripun ada di belakang kami.\"', NULL),
(6312, 3647, 32, 19, 'Begitulah diperintahkannya baik kepada yang kedua maupun kepada yang ketiga dan kepada sekalian orang yang berjalan menggiring kumpulan hewan itu, katanya: \"Seperti perkataanku tadilah kamu katakan kepada Esau, apabila kamu berjumpa dengan dia;', NULL),
(6313, 3647, 32, 20, 'dan kamu harus mengatakan juga: Hambamu Yakub sendiri ada di belakang kami.\" Sebab pikir Yakub: \"Baiklah aku mendamaikan hatinya dengan persembahan yang diantarkan lebih dahulu, kemudian barulah aku akan melihat mukanya; mungkin ia akan menerima aku dengan baik.\"', NULL),
(6314, 3647, 32, 21, 'Jadi persembahan itu diantarkan lebih dahulu, tetapi ia sendiri bermalam pada malam itu di tempat perkemahannya.', NULL),
(6315, 3647, 32, 22, 'Pada malam itu Yakub bangun dan ia membawa kedua isterinya, kedua budaknya perempuan dan kesebelas anaknya, dan menyeberang di tempat penyeberangan sungai Yabok.', 'Pergumulan Yakub dengan Allah'),
(6316, 3647, 32, 23, 'Sesudah ia menyeberangkan mereka, ia menyeberangkan juga segala miliknya.', NULL),
(6317, 3647, 32, 24, 'Lalu tinggallah Yakub seorang diri. Dan seorang laki-laki bergulat dengan dia sampai fajar menyingsing.', NULL),
(6318, 3647, 32, 25, 'Ketika orang itu melihat, bahwa ia tidak dapat mengalahkannya, ia memukul sendi pangkal paha Yakub, sehingga sendi pangkal paha itu terpelecok, ketika ia bergulat dengan orang itu.', NULL),
(6319, 3647, 32, 26, 'Lalu kata orang itu: \"Biarkanlah aku pergi, karena fajar telah menyingsing.\" Sahut Yakub: \"Aku tidak akan membiarkan engkau pergi, jika engkau tidak memberkati aku.\"', NULL),
(6320, 3647, 32, 27, 'Bertanyalah orang itu kepadanya: \"Siapakah namamu?\" Sahutnya: \"Yakub.\"', NULL),
(6321, 3647, 32, 28, 'Lalu kata orang itu: \"Namamu tidak akan disebutkan lagi Yakub, tetapi Israel, sebab engkau telah bergumul melawan Allah dan manusia, dan engkau menang.\"', NULL),
(6322, 3647, 32, 29, 'Bertanyalah Yakub: \"Katakanlah juga namamu.\" Tetapi sahutnya: \"Mengapa engkau menanyakan namaku?\" Lalu diberkatinyalah Yakub di situ.', NULL),
(6323, 3647, 32, 30, 'Yakub menamai tempat itu Pniel, sebab katanya: \"Aku telah melihat Allah berhadapan muka, tetapi nyawaku tertolong!\"', NULL),
(6324, 3647, 32, 31, 'Lalu tampaklah kepadanya matahari terbit, ketika ia telah melewati Pniel; dan Yakub pincang karena pangkal pahanya.', NULL),
(6325, 3647, 32, 32, 'Itulah sebabnya sampai sekarang orang Israel tidak memakan daging yang menutupi sendi pangkal paha, karena Dia telah memukul sendi pangkal paha Yakub, pada otot pangkal pahanya.', NULL),
(6326, 3647, 33, 1, 'Yakubpun melayangkan pandangnya, lalu dilihatnyalah Esau datang dengan diiringi oleh empat ratus orang. Maka diserahkannyalah sebagian dari anak-anak itu kepada Lea dan sebagian kepada Rahel serta kepada kedua budak perempuan itu.', 'Yakub berbaik kembali dengan Esau'),
(6327, 3647, 33, 2, 'Ia menempatkan budak-budak perempuan itu beserta anak-anak mereka di muka, Lea beserta anak-anaknya di belakang mereka, dan Rahel beserta Yusuf di belakang sekali.', NULL),
(6328, 3647, 33, 3, 'Dan ia sendiri berjalan di depan mereka dan ia sujud sampai ke tanah tujuh kali, hingga ia sampai ke dekat kakaknya itu.', NULL),
(6329, 3647, 33, 4, 'Tetapi Esau berlari mendapatkan dia, didekapnya dia, dipeluk lehernya dan diciumnya dia, lalu bertangis-tangisanlah mereka.', NULL),
(6330, 3647, 33, 5, 'Kemudian Esau melayangkan pandangnya, dilihatnyalah perempuan-perempuan dan anak-anak itu, lalu ia bertanya: \"Siapakah orang-orang yang beserta engkau itu?\" Jawab Yakub: \"Anak-anak yang telah dikaruniakan Allah kepada hambamu ini.\"', NULL),
(6331, 3647, 33, 6, 'Sesudah itu mendekatlah budak-budak perempuan itu beserta anak-anaknya, lalu mereka sujud.', NULL),
(6332, 3647, 33, 7, 'Mendekat jugalah Lea beserta anak-anaknya, dan merekapun sujud. Kemudian mendekatlah Yusuf beserta Rahel, dan mereka juga sujud.', NULL),
(6333, 3647, 33, 8, 'Berkatalah Esau: \"Apakah maksudmu dengan seluruh pasukan, yang telah bertemu dengan aku tadi?\" Jawabnya: \"Untuk mendapat kasih tuanku.\"', NULL),
(6334, 3647, 33, 9, 'Tetapi kata Esau: \"Aku mempunyai banyak, adikku; peganglah apa yang ada padamu.\"', NULL),
(6335, 3647, 33, 10, 'Tetapi kata Yakub: \"Janganlah kiranya demikian; jikalau aku telah mendapat kasihmu, terimalah persembahanku ini dari tanganku, karena memang melihat mukamu adalah bagiku serasa melihat wajah Allah, dan engkaupun berkenan menyambut aku.', NULL),
(6336, 3647, 33, 11, 'Terimalah kiranya pemberian tanda salamku ini, yang telah kubawa kepadamu, sebab Allah telah memberi karunia kepadaku dan akupun mempunyai segala-galanya.\" Lalu dibujuk-bujuknyalah Esau, sehingga diterimanya.', NULL),
(6337, 3647, 33, 12, 'Kata Esau: \"Baiklah kita berangkat berjalan terus; aku akan menyertai engkau.\"', NULL),
(6338, 3647, 33, 13, 'Tetapi Yakub berkata kepadanya: \"Tuanku maklum, bahwa anak-anak ini masih kurang kuat, dan bahwa beserta aku ada kambing domba dan lembu sapi yang masih menyusui, jika diburu-buru, satu hari saja, maka seluruh kumpulan binatang itu akan mati.', NULL),
(6339, 3647, 33, 14, 'Biarlah kiranya tuanku berjalan lebih dahulu dari hambamu ini dan aku mau dengan hati-hati beringsut maju menurut langkah hewan, yang berjalan di depanku dan menurut langkah anak-anak, sampai aku tiba pada tuanku di Seir.\"', NULL),
(6340, 3647, 33, 15, 'Lalu kata Esau: \"Kalau begitu, baiklah kutinggalkan padamu beberapa orang dari pengiringku.\" Tetapi Yakub berkata: \"Tidak usah demikian! Biarlah aku mendapat kasih tuanku saja.\"', NULL),
(6341, 3647, 33, 16, 'Jadi pulanglah Esau pada hari itu berjalan ke Seir.', NULL),
(6342, 3647, 33, 17, 'Tetapi Yakub berangkat ke Sukot, lalu mendirikan rumah, dan untuk ternaknya dibuatnya gubuk-gubuk. Itulah sebabnya tempat itu dinamai Sukot.', NULL),
(6343, 3647, 33, 18, 'Dalam perjalanannya dari Padan-Aram sampailah Yakub dengan selamat ke Sikhem, di tanah Kanaan, lalu ia berkemah di sebelah timur kota itu.', NULL),
(6344, 3647, 33, 19, 'Kemudian dibelinyalah dari anak-anak Hemor, bapa Sikhem, sebidang tanah, tempat ia memasang kemahnya, dengan harga seratus kesita.', NULL),
(6345, 3647, 33, 20, 'Ia mendirikan mezbah di situ dan dinamainya itu: \"Allah Israel ialah Allah.\"', NULL),
(6346, 3647, 34, 1, 'Pada suatu kali pergilah Dina, anak perempuan Lea yang dilahirkannya bagi Yakub, mengunjungi perempuan-perempuan di negeri itu.', 'Dina dan Sikhem'),
(6347, 3647, 34, 2, 'Ketika itu terlihatlah ia oleh Sikhem, anak Hemor, orang Hewi, raja negeri itu, lalu Dina itu dilarikannya dan diperkosanya.', NULL),
(6348, 3647, 34, 3, 'Tetapi terikatlah hatinya kepada Dina, anak Yakub; ia cinta kepada gadis itu, lalu menenangkan hati gadis itu.', NULL),
(6349, 3647, 34, 4, 'Sebab itu berkatalah Sikhem kepada Hemor, ayahnya: \"Ambillah bagiku gadis ini untuk menjadi isteriku.\"', NULL),
(6350, 3647, 34, 5, 'Kedengaranlah kepada Yakub, bahwa Sikhem mencemari Dina. Tetapi anak-anaknya ada di padang menjaga ternaknya, jadi Yakub mendiamkan soal itu sampai mereka pulang.', NULL),
(6351, 3647, 34, 6, 'Lalu Hemor ayah Sikhem, pergi mendapatkan Yakub untuk berbicara dengan dia.', NULL),
(6352, 3647, 34, 7, 'Sementara itu anak-anak Yakub pulang dari padang, dan sesudah mendengar peristiwa itu orang-orang ini sakit hati dan sangat marah karena Sikhem telah berbuat noda di antara orang Israel dengan memperkosa anak perempuan Yakub, sebab yang demikian itu tidak patut dilakukan.', NULL),
(6353, 3647, 34, 8, 'Berbicaralah Hemor kepada mereka itu: \"Hati Sikhem anakku mengingini anakmu; kiranya kamu memberikan dia kepadanya menjadi isterinya', NULL),
(6354, 3647, 34, 9, 'dan biarlah kita ambil-mengambil: berikanlah gadis-gadis kamu kepada kami dan ambillah gadis-gadis kami.', NULL),
(6355, 3647, 34, 10, 'Tinggallah pada kami: negeri ini terbuka untuk kamu; tinggallah di sini, jalanilah negeri ini dengan bebas, dan menetaplah di sini.\"', NULL),
(6356, 3647, 34, 11, 'Lalu Sikhem berkata kepada ayah anak itu dan kepada kakak-kakaknya: \"Biarlah kiranya aku mendapat kasihmu, aku akan memberikan kepadamu apa yang kamu minta;', NULL),
(6357, 3647, 34, 12, 'walaupun kamu bebankan kepadaku uang jujuran dan uang mahar seberapa banyakpun, aku akan memberikan apa yang kamu minta; tetapi berilah gadis itu kepadaku menjadi isteriku.\"', NULL),
(6358, 3647, 34, 13, 'Lalu anak-anak Yakub menjawab Sikhem dan Hemor, ayahnya, dengan tipu muslihat. Karena Sikhem telah mencemari Dina, adik mereka itu,', NULL),
(6359, 3647, 34, 14, 'berkatalah mereka kepada kedua orang itu: \"Kami tidak dapat berbuat demikian, memberikan adik kami kepada seorang laki-laki yang tidak bersunat, sebab hal itu aib bagi kami.', NULL),
(6360, 3647, 34, 15, 'Hanyalah dengan syarat ini kami dapat menyetujui permintaanmu: kamu harus sama seperti kami, yaitu setiap laki-laki di antara kamu harus disunat,', NULL),
(6361, 3647, 34, 16, 'barulah kami akan memberikan gadis-gadis kami kepada kamu dan mengambil gadis-gadis kamu; maka kami akan tinggal padamu, dan kita akan menjadi satu bangsa.', NULL),
(6362, 3647, 34, 17, 'Tetapi jika kamu tidak mendengarkan perkataan kami dan kamu tidak disunat, maka kami akan mengambil kembali anak itu, lalu pergi.\"', NULL),
(6363, 3647, 34, 18, 'Lalu Hemor dan Sikhem, anak Hemor, menyetujui usul mereka.', NULL),
(6364, 3647, 34, 19, 'Dan orang muda itu tidak bertangguh melakukannya, sebab ia suka kepada anak Yakub, lagipula ia seorang yang paling dihormati di antara seluruh kaum keluarganya.', NULL),
(6365, 3647, 34, 20, 'Lalu pergilah Hemor dan Sikhem, anaknya itu, ke pintu gerbang kota mereka dan mereka berbicara kepada penduduk kota itu:', NULL),
(6366, 3647, 34, 21, '\"Orang-orang itu mau hidup damai dengan kita, biarlah mereka tinggal di negeri ini dan menjalaninya dengan bebas; bukankah negeri ini cukup luas untuk mereka? Maka kita dapat mengambil gadis-gadis mereka menjadi isteri kita dan kita dapat memberikan gadis-gadis kita kepada mereka.', NULL),
(6367, 3647, 34, 22, 'Namun hanya dengan syarat ini orang-orang itu setuju tinggal bersama-sama dengan kita, sehingga kita menjadi satu bangsa, yaitu setiap laki-laki di antara kita harus disunat seperti mereka bersunat.', NULL),
(6368, 3647, 34, 23, 'Ternak mereka, harta benda mereka dan segala hewan mereka, bukankah semuanya itu akan menjadi milik kita? Hanya biarlah kita menyetujui permintaan mereka, sehingga mereka tetap tinggal pada kita.\"', NULL),
(6369, 3647, 34, 24, 'Maka usul Hemor dan Sikhem, anaknya itu, didengarkan oleh semua orang yang datang berkumpul di pintu gerbang kota itu, lalu disunatlah setiap laki-laki, yakni setiap orang dewasa di kota itu.', NULL),
(6370, 3647, 34, 25, 'Pada hari ketiga, ketika mereka sedang menderita kesakitan, datanglah dua orang anak Yakub, yaitu Simeon dan Lewi, kakak-kakak Dina, setelah masing-masing mengambil pedangnya, menyerang kota itu dengan tidak takut-takut serta membunuh setiap laki-laki.', NULL),
(6371, 3647, 34, 26, 'Juga Hemor dan Sikhem, anaknya, dibunuh mereka dengan mata pedang, dan mereka mengambil Dina dari rumah Sikhem, lalu pergi.', NULL),
(6372, 3647, 34, 27, 'Kemudian datanglah anak-anak Yakub merampasi orang-orang yang terbunuh itu, lalu menjarah kota itu, karena adik mereka telah dicemari.', NULL),
(6373, 3647, 34, 28, 'Kambing dombanya dan lembu sapinya, keledainya dan segala yang di dalam dan di luar kota itu dibawa mereka;', NULL),
(6374, 3647, 34, 29, 'segala kekayaannya, semua anaknya dan perempuannya ditawan dan dijarah mereka, juga seluruhnya yang ada di rumah-rumah.', NULL),
(6375, 3647, 34, 30, 'Yakub berkata kepada Simeon dan Lewi: \"Kamu telah mencelakakan aku dengan membusukkan namaku kepada penduduk negeri ini, kepada orang Kanaan dan orang Feris, padahal kita ini hanya sedikit jumlahnya; apabila mereka bersekutu melawan kita, tentulah mereka akan memukul kita kalah, dan kita akan dipunahkan, aku beserta seisi rumahku.\"', NULL),
(6376, 3647, 34, 31, 'Tetapi jawab mereka: \"Mengapa adik kita diperlakukannya sebagai seorang perempuan sundal!\"', NULL),
(7391, 3647, 35, 1, 'Allah berfirman kepada Yakub: \"Bersiaplah, pergilah ke Betel, tinggallah di situ, dan buatlah di situ mezbah bagi Allah, yang telah menampakkan diri kepadamu, ketika engkau lari dari Esau, kakakmu.\"', 'Yakub di Betel untuk kedua kalinya'),
(7392, 3647, 35, 2, 'Lalu berkatalah Yakub kepada seisi rumahnya dan kepada semua orang yang bersama-sama dengan dia: \"Jauhkanlah dewa-dewa asing yang ada di tengah-tengah kamu, tahirkanlah dirimu dan tukarlah pakaianmu.', NULL),
(7393, 3647, 35, 3, 'Marilah kita bersiap dan pergi ke Betel; aku akan membuat mezbah di situ bagi Allah, yang telah menjawab aku pada masa kesesakanku dan yang telah menyertai aku di jalan yang kutempuh.\"', NULL),
(7394, 3647, 35, 4, 'Mereka menyerahkan kepada Yakub segala dewa asing yang dipunyai mereka dan anting-anting yang ada pada telinga mereka, lalu Yakub menanamnya di bawah pohon besar yang dekat Sikhem.', NULL),
(7395, 3647, 35, 5, 'Sesudah itu berangkatlah mereka. Dan kedahsyatan yang dari Allah meliputi kota-kota sekeliling mereka, sehingga anak-anak Yakub tidak dikejar.', NULL),
(7396, 3647, 35, 6, 'Lalu sampailah Yakub ke Lus yang di tanah Kanaan--yaitu Betel--,ia dan semua orang yang bersama-sama dengan dia.', NULL),
(7397, 3647, 35, 7, 'Didirikannyalah mezbah di situ, dan dinamainyalah tempat itu El-Betel, karena Allah telah menyatakan diri kepadanya di situ, ketika ia lari terhadap kakaknya.', NULL),
(7398, 3647, 35, 8, 'Ketika Debora, inang pengasuh Ribka, mati, dikuburkanlah ia di sebelah hilir Betel di bawah pohon besar, yang dinamai orang: Pohon Besar Penangisan.', NULL),
(7399, 3647, 35, 9, 'Setelah Yakub datang dari Padan-Aram, maka Allah menampakkan diri pula kepadanya dan memberkati dia.', NULL),
(7400, 3647, 35, 10, 'Firman Allah kepadanya: \"Namamu Yakub; dari sekarang namamu bukan lagi Yakub, melainkan Israel, itulah yang akan menjadi namamu.\" Maka Allah menamai dia Israel.', NULL),
(7401, 3647, 35, 11, 'Lagi firman Allah kepadanya: \"Akulah Allah Yang Mahakuasa. Beranakcuculah dan bertambah banyak; satu bangsa, bahkan sekumpulan bangsa-bangsa, akan terjadi dari padamu dan raja-raja akan berasal dari padamu.', NULL),
(7402, 3647, 35, 12, 'Dan negeri ini yang telah Kuberikan kepada Abraham dan kepada Ishak, akan Kuberikan kepadamu dan juga kepada keturunanmu.\"', NULL),
(7403, 3647, 35, 13, 'Lalu naiklah Allah meninggalkan Yakub dari tempat Ia berfirman kepadanya.', NULL),
(7404, 3647, 35, 14, 'Kemudian Yakub mendirikan tugu di tempat itu, yakni tugu batu; ia mempersembahkan korban curahan dan menuangkan minyak di atasnya.', NULL),
(7405, 3647, 35, 15, 'Yakub menamai tempat di mana Allah telah berfirman kepadanya \"Betel\".', NULL),
(7406, 3647, 35, 16, 'Sesudah itu berangkatlah mereka dari Betel. Ketika mereka tidak berapa jauh lagi dari Efrata, bersalinlah Rahel, dan bersalinnya itu sangat sukar.', 'Kelahiran Benyamin -- Rahel mati'),
(7407, 3647, 35, 17, 'Sedang ia sangat sukar bersalin, berkatalah bidan kepadanya: \"Janganlah takut, sekali inipun anak laki-laki yang kaudapat.\"', NULL),
(7408, 3647, 35, 18, 'Dan ketika ia hendak menghembuskan nafas--sebab ia mati kemudian--diberikannyalah nama Ben-oni kepada anak itu, tetapi ayahnya menamainya Benyamin.', NULL),
(7409, 3647, 35, 19, 'Demikianlah Rahel mati, lalu ia dikuburkan di sisi jalan ke Efrata, yaitu Betlehem.', NULL),
(7410, 3647, 35, 20, 'Yakub mendirikan tugu di atas kuburnya; itulah tugu kubur Rahel sampai sekarang.', NULL),
(7411, 3647, 35, 21, 'Sesudah itu berangkatlah Israel, lalu ia memasang kemahnya di seberang Migdal-Eder.', NULL),
(7412, 3647, 35, 22, 'Ketika Israel diam di negeri ini, terjadilah bahwa Ruben sampai tidur dengan Bilha, gundik ayahnya, dan kedengaranlah hal itu kepada Israel.(35-22b) Adapun anak-anak lelaki Yakub dua belas orang jumlahnya.', 'Anak-anak Yakub -- Ishak mati'),
(7413, 3647, 35, 23, 'Anak-anak Lea ialah Ruben, anak sulung Yakub, kemudian Simeon, Lewi, Yehuda, Isakhar dan Zebulon.', NULL),
(7414, 3647, 35, 24, 'Anak-anak Rahel ialah Yusuf dan Benyamin.', NULL),
(7415, 3647, 35, 25, 'Dan anak-anak Bilha, budak perempuan Rahel ialah Dan serta Naftali.', NULL),
(7416, 3647, 35, 26, 'Dan anak-anak Zilpa, budak perempuan Lea ialah Gad dan Asyer. Itulah anak-anak lelaki Yakub, yang dilahirkan baginya di Padan-Aram.', NULL),
(7417, 3647, 35, 27, 'Lalu sampailah Yakub kepada Ishak, ayahnya, di Mamre dekat Kiryat-Arba--itulah Hebron--tempat Abraham dan Ishak tinggal sebagai orang asing.', NULL),
(7418, 3647, 35, 28, 'Adapun umur Ishak seratus delapan puluh tahun.', NULL),
(7419, 3647, 35, 29, 'Lalu meninggallah Ishak, ia mati dan dikumpulkan kepada kaum leluhurnya; ia tua dan suntuk umur, maka Esau dan Yakub, anak-anaknya itu, menguburkan dia.', NULL),
(7420, 3647, 36, 1, 'Inilah keturunan Esau, yaitu Edom.', 'Esau -- Keturunan Esau'),
(7421, 3647, 36, 2, 'Esau mengambil perempuan-perempuan Kanaan menjadi isterinya, yakni Ada, anak Elon orang Het, dan Oholibama, anak Ana anak Zibeon orang Hewi,', NULL),
(7422, 3647, 36, 3, 'dan Basmat, anak Ismael, adik Nebayot.', NULL),
(7423, 3647, 36, 4, 'Ada melahirkan Elifas bagi Esau, dan Basmat melahirkan Rehuel,', NULL),
(7424, 3647, 36, 5, 'dan Oholibama melahirkan Yeush, Yaelam dan Korah. Itulah anak-anak Esau, yang lahir baginya di tanah Kanaan.', NULL),
(7425, 3647, 36, 6, 'Esau membawa isteri-isterinya, anak-anaknya lelaki dan perempuan dan semua orang yang ada di rumahnya, ternaknya, segala hewannya dan segala harta bendanya yang telah diperolehnya di tanah Kanaan, lalu pergilah ia ke negeri lain dan ia meninggalkan Yakub, adiknya itu.', NULL),
(7426, 3647, 36, 7, 'Sebab harta milik mereka terlalu banyak, sehingga mereka tidak dapat tinggal bersama-sama, dan negeri penumpangan mereka tidak dapat memuat mereka karena banyaknya ternak mereka itu.', NULL),
(7427, 3647, 36, 8, 'Maka menetaplah Esau di pegunungan Seir; Esau itulah Edom.', NULL),
(7428, 3647, 36, 9, 'Inilah keturunan Esau, bapa orang Edom, di pegunungan Seir.', NULL),
(7429, 3647, 36, 10, 'Nama anak-anaknya ialah: Elifas, anak Ada isteri Esau; Rehuel, anak Basmat isteri Esau.', NULL),
(7430, 3647, 36, 11, 'Anak-anak Elifas ialah Teman, Omar, Zefo, Gaetam dan Kenas.', NULL),
(7431, 3647, 36, 12, 'Timna adalah gundik Elifas anak Esau; ia melahirkan Amalek bagi Elifas. Itulah cucu-cucu Ada isteri Esau.', NULL),
(7432, 3647, 36, 13, 'Inilah anak-anak Rehuel: Nahat, Zerah, Syama dan Miza. Itulah cucu-cucu Basmat isteri Esau.', NULL),
(7433, 3647, 36, 14, 'Inilah anak-anak Oholibama, isteri Esau itu, anak Ana anak Zibeon; ia melahirkan bagi Esau: Yeush, Yaelam dan Korah.', NULL),
(7434, 3647, 36, 15, 'Inilah kepala-kepala kaum bani Esau: keturunan Elifas anak sulung Esau, ialah kepala kaum Teman, kepala kaum Omar, kepala kaum Zefo, kepala kaum Kenas,', NULL),
(7435, 3647, 36, 16, 'kepala kaum Korah, kepala kaum Gaetam dan kepala kaum Amalek; itulah kepala-kepala kaum Elifas di tanah Edom; itulah keturunan Ada.', NULL),
(7436, 3647, 36, 17, 'Inilah keturunan Rehuel anak Esau: kepala kaum Nahat, kepala kaum Zerah, kepala kaum Syama dan kepala kaum Miza; itulah kepala-kepala kaum Rehuel di tanah Edom; itulah keturunan Basmat isteri Esau.', NULL),
(7437, 3647, 36, 18, 'Inilah keturunan Oholibama isteri Esau: kepala kaum Yeush, kepala kaum Yaelam, kepala kaum Korah; itulah kepala-kepala kaum Oholibama, isteri Esau, anak Ana.', NULL),
(7438, 3647, 36, 19, 'Itulah bani Esau, yakni Edom, dan itulah kepala-kepala kaum mereka.', NULL),
(7439, 3647, 36, 20, 'Inilah anak-anak Seir, orang Hori, penduduk negeri itu: Lotan, Syobal, Zibeon, Ana,', 'Anak-anak Seir'),
(7440, 3647, 36, 21, 'Disyon, Ezer, Disyan; itulah kepala-kepala kaum orang Hori, anak-anak Seir, di tanah Edom.', NULL),
(7441, 3647, 36, 22, 'Anak-anak Lotan ialah Hori dan Heman, dan saudara perempuan Lotan ialah Timna.', NULL),
(7442, 3647, 36, 23, 'Inilah anak-anak Syobal: Alwan, Manahat, Ebal, Syefo dan Onam.', NULL),
(7443, 3647, 36, 24, 'Inilah anak-anak Zibeon: Aya dan Ana; Ana inilah yang menemui mata-mata air panas di padang gurun, ketika ia sedang menggembalakan keledai Zibeon ayahnya itu.', NULL),
(7444, 3647, 36, 25, 'Inilah anak-anak Ana: Disyon dan Oholibama anak perempuan Ana.', NULL),
(7445, 3647, 36, 26, 'Inilah anak-anak Disyon: Hemdan, Esyban, Yitran dan Keran.', NULL),
(7446, 3647, 36, 27, 'Inilah anak-anak Ezer: Bilhan, Zaawan dan Akan.', NULL),
(7447, 3647, 36, 28, 'Inilah anak-anak Disyan: Us dan Aran.', NULL),
(7448, 3647, 36, 29, 'Itulah kepala-kepala kaum orang Hori: kepala kaum Lotan, kepala kaum Syobal, kepala kaum Zibeon, kepala kaum Ana,', NULL),
(7449, 3647, 36, 30, 'kepala kaum Disyon, kepala kaum Ezer dan kepala kaum Disyan; itulah kepala-kepala kaum orang Hori, kaum demi kaum, di tanah Seir.', NULL),
(7450, 3647, 36, 31, 'Inilah raja-raja yang memerintah di tanah Edom, sebelum ada seorang raja memerintah atas orang Israel.', 'Raja-raja Edom'),
(7451, 3647, 36, 32, 'Di Edom yang memerintah ialah Bela bin Beor dan kotanya bernama Dinhaba.', NULL),
(7452, 3647, 36, 33, 'Setelah Bela mati, Yobab bin Zerah dari Bozra menjadi raja menggantikan dia.', NULL),
(7453, 3647, 36, 34, 'Setelah Yobab mati, Husyam, dari negeri orang Teman, menjadi raja menggantikan dia.', NULL),
(7454, 3647, 36, 35, 'Setelah Husyam mati, Hadad bin Bedad menjadi raja menggantikan dia; dialah yang memukul kalah orang Midian di daerah Moab, dan kotanya bernama Awit.', NULL),
(7455, 3647, 36, 36, 'Setelah Hadad mati, Samla dari Masreka menjadi raja menggantikan dia.', NULL),
(7456, 3647, 36, 37, 'Setelah Samla mati, Saul, dari Rehobot yang di pinggir sungai, menjadi raja menggantikan dia.', NULL),
(7457, 3647, 36, 38, 'Setelah Saul mati, Baal-Hanan bin Akhbor menjadi raja menggantikan dia.', NULL),
(7458, 3647, 36, 39, 'Setelah Baal-Hanan bin Akhbor mati, Hadar menjadi raja menggantikan dia; kotanya bernama Pahu dan isterinya bernama Mehetabeel binti Matred binti Mezahab.', NULL),
(7459, 3647, 36, 40, 'Inilah nama kepala-kepala kaum Esau menurut kaum dan tempat mereka, dengan nama mereka masing-masing: kepala kaum Timna, kepala kaum Alwa, kepala kaum Yetet,', NULL),
(7460, 3647, 36, 41, 'kepala kaum Oholibama, kepala kaum Ela, kepala kaum Pinon,', NULL),
(7461, 3647, 36, 42, 'kepala kaum Kenas, kepala kaum Teman, kepala kaum Mibzar,', NULL),
(7462, 3647, 36, 43, 'kepala kaum Magdiel dan kepala kaum Iram; itulah kepala-kepala kaum Edom, menurut tempat kediaman mereka di tanah milik mereka; Edom ialah Esau, bapa orang Edom.', NULL),
(7463, 3647, 37, 1, 'Adapun Yakub, ia diam di negeri penumpangan ayahnya, yakni di tanah Kanaan.', 'Yusuf dan saudara-saudaranya'),
(7464, 3647, 37, 2, 'Inilah riwayat keturunan Yakub. Yusuf, tatkala berumur tujuh belas tahun--jadi masih muda--biasa menggembalakan kambing domba, bersama-sama dengan saudara-saudaranya, anak-anak Bilha dan Zilpa, kedua isteri ayahnya. Dan Yusuf menyampaikan kepada ayahnya kabar tentang kejahatan saudara-saudaranya.', NULL),
(7465, 3647, 37, 3, 'Israel lebih mengasihi Yusuf dari semua anaknya yang lain, sebab Yusuf itulah anaknya yang lahir pada masa tuanya; dan ia menyuruh membuat jubah yang maha indah bagi dia.', NULL),
(7466, 3647, 37, 4, 'Setelah dilihat oleh saudara-saudaranya, bahwa ayahnya lebih mengasihi Yusuf dari semua saudaranya, maka bencilah mereka itu kepadanya dan tidak mau menyapanya dengan ramah.', NULL),
(7467, 3647, 37, 5, 'Pada suatu kali bermimpilah Yusuf, lalu mimpinya itu diceritakannya kepada saudara-saudaranya; sebab itulah mereka lebih benci lagi kepadanya.', NULL),
(7468, 3647, 37, 6, 'Karena katanya kepada mereka: \"Coba dengarkan mimpi yang kumimpikan ini:', NULL),
(7469, 3647, 37, 7, 'Tampak kita sedang di ladang mengikat berkas-berkas gandum, lalu bangkitlah berkasku dan tegak berdiri; kemudian datanglah berkas-berkas kamu sekalian mengelilingi dan sujud menyembah kepada berkasku itu.\"', NULL),
(7470, 3647, 37, 8, 'Lalu saudara-saudaranya berkata kepadanya: \"Apakah engkau ingin menjadi raja atas kami? Apakah engkau ingin berkuasa atas kami?\" Jadi makin bencilah mereka kepadanya karena mimpinya dan karena perkataannya itu.', NULL),
(7471, 3647, 37, 9, 'Lalu ia memimpikan pula mimpi yang lain, yang diceritakannya kepada saudara-saudaranya. Katanya: \"Aku bermimpi pula: Tampak matahari, bulan dan sebelas bintang sujud menyembah kepadaku.\"', NULL),
(7472, 3647, 37, 10, 'Setelah hal ini diceritakannya kepada ayah dan saudara-saudaranya, maka ia ditegor oleh ayahnya: \"Mimpi apa mimpimu itu? Masakan aku dan ibumu serta saudara-saudaramu sujud menyembah kepadamu sampai ke tanah?\"', NULL),
(7473, 3647, 37, 11, 'Maka iri hatilah saudara-saudaranya kepadanya, tetapi ayahnya menyimpan hal itu dalam hatinya.', NULL),
(7474, 3647, 37, 12, 'Pada suatu kali pergilah saudara-saudaranya menggembalakan kambing domba ayahnya dekat Sikhem.', 'Yusuf dijual ke tanah Mesir'),
(7475, 3647, 37, 13, 'Lalu Israel berkata kepada Yusuf: \"Bukankah saudara-saudaramu menggembalakan kambing domba dekat Sikhem? Marilah engkau kusuruh kepada mereka.\" Sahut Yusuf: \"Ya bapa.\"', NULL),
(7476, 3647, 37, 14, 'Kata Israel kepadanya: \"Pergilah engkau melihat apakah baik keadaan saudara-saudaramu dan keadaan kambing domba; dan bawalah kabar tentang itu kepadaku.\" Lalu Yakub menyuruh dia dari lembah Hebron, dan Yusufpun sampailah ke Sikhem.', NULL),
(7477, 3647, 37, 15, 'Ketika Yusuf berjalan ke sana ke mari di padang, bertemulah ia dengan seorang laki-laki, yang bertanya kepadanya: \"Apakah yang kaucari?\"', NULL),
(7478, 3647, 37, 16, 'Sahutnya: \"Aku mencari saudara-saudaraku. Tolonglah katakan kepadaku di mana mereka menggembalakan kambing domba?\"', NULL),
(7479, 3647, 37, 17, 'Lalu kata orang itu: \"Mereka telah berangkat dari sini, sebab telah kudengar mereka berkata: Marilah kita pergi ke Dotan.\" Maka Yusuf menyusul saudara-saudaranya itu dan didapatinyalah mereka di Dotan.', NULL),
(7480, 3647, 37, 18, 'Dari jauh ia telah kelihatan kepada mereka. Tetapi sebelum ia dekat pada mereka, mereka telah bermufakat mencari daya upaya untuk membunuhnya.', NULL),
(7481, 3647, 37, 19, 'Kata mereka seorang kepada yang lain: \"Lihat, tukang mimpi kita itu datang!', NULL),
(7482, 3647, 37, 20, 'Sekarang, marilah kita bunuh dia dan kita lemparkan ke dalam salah satu sumur ini, lalu kita katakan: seekor binatang buas telah menerkamnya. Dan kita akan lihat nanti, bagaimana jadinya mimpinya itu!\"', NULL),
(7483, 3647, 37, 21, 'Ketika Ruben mendengar hal ini, ia ingin melepaskan Yusuf dari tangan mereka, sebab itu katanya: \"Janganlah kita bunuh dia!\"', NULL),
(7484, 3647, 37, 22, 'Lagi kata Ruben kepada mereka: \"Janganlah tumpahkan darah, lemparkanlah dia ke dalam sumur yang ada di padang gurun ini, tetapi janganlah apa-apakan dia\" --maksudnya hendak melepaskan Yusuf dari tangan mereka dan membawanya kembali kepada ayahnya.', NULL),
(7485, 3647, 37, 23, 'Baru saja Yusuf sampai kepada saudara-saudaranya, merekapun menanggalkan jubah Yusuf, jubah maha indah yang dipakainya itu.', NULL),
(7486, 3647, 37, 24, 'Dan mereka membawa dia dan melemparkan dia ke dalam sumur. Sumur itu kosong, tidak berair.', NULL),
(7487, 3647, 37, 25, 'Kemudian duduklah mereka untuk makan. Ketika mereka mengangkat muka, kelihatanlah kepada mereka suatu kafilah orang Ismael datang dari Gilead dengan untanya yang membawa damar, balsam dan damar ladan, dalam perjalanannya mengangkut barang-barang itu ke Mesir.', NULL),
(7488, 3647, 37, 26, 'Lalu kata Yehuda kepada saudara-saudaranya itu: \"Apakah untungnya kalau kita membunuh adik kita itu dan menyembunyikan darahnya?', NULL),
(7489, 3647, 37, 27, 'Marilah kita jual dia kepada orang Ismael ini, tetapi janganlah kita apa-apakan dia, karena ia saudara kita, darah daging kita.\" Dan saudara-saudaranya mendengarkan perkataannya itu.', NULL),
(7490, 3647, 37, 28, 'Ketika ada saudagar-saudagar Midian lewat, Yusuf diangkat ke atas dari dalam sumur itu, kemudian dijual kepada orang Ismael itu dengan harga dua puluh syikal perak. Lalu Yusuf dibawa mereka ke Mesir.', NULL),
(7491, 3647, 37, 29, 'Ketika Ruben kembali ke sumur itu, ternyata Yusuf tidak ada lagi di dalamnya. Lalu dikoyakkannyalah bajunya,', NULL),
(7492, 3647, 37, 30, 'dan kembalilah ia kepada saudara-saudaranya, katanya: \"Anak itu tidak ada lagi, ke manakah aku ini?\"', NULL),
(7493, 3647, 37, 31, 'Kemudian mereka mengambil jubah Yusuf, dan menyembelih seekor kambing, lalu mencelupkan jubah itu ke dalam darahnya.', NULL),
(7494, 3647, 37, 32, 'Jubah maha indah itu mereka suruh antarkan kepada ayah mereka dengan pesan: \"Ini kami dapati. Silakanlah bapa periksa apakah jubah ini milik anak bapa atau tidak?\"', NULL),
(7495, 3647, 37, 33, 'Ketika Yakub memeriksa jubah itu, ia berkata: \"Ini jubah anakku; binatang buas telah memakannya; tentulah Yusuf telah diterkam.\"', NULL),
(7496, 3647, 37, 34, 'Dan Yakub mengoyakkan jubahnya, lalu mengenakan kain kabung pada pinggangnya dan berkabunglah ia berhari-hari lamanya karena anaknya itu.', NULL),
(7497, 3647, 37, 35, 'Sekalian anaknya laki-laki dan perempuan berusaha menghiburkan dia, tetapi ia menolak dihiburkan, serta katanya: \"Tidak! Aku akan berkabung, sampai aku turun mendapatkan anakku, ke dalam dunia orang mati!\" Demikianlah Yusuf ditangisi oleh ayahnya.', NULL),
(7498, 3647, 37, 36, 'Adapun Yusuf, ia dijual oleh orang Midian itu ke Mesir, kepada Potifar, seorang pegawai istana Firaun, kepala pengawal raja.', NULL),
(7499, 3647, 38, 1, 'Pada waktu itu Yehuda meninggalkan saudara-saudaranya dan menumpang pada seorang Adulam, yang namanya Hira.', 'Yehuda dan Tamar'),
(7500, 3647, 38, 2, 'Di situ Yehuda melihat anak perempuan seorang Kanaan; nama orang itu ialah Syua. Lalu Yehuda kawin dengan perempuan itu dan menghampirinya.', NULL),
(7501, 3647, 38, 3, 'Perempuan itu mengandung, lalu melahirkan seorang anak laki-laki dan menamai anak itu Er.', NULL),
(7502, 3647, 38, 4, 'Sesudah itu perempuan itu mengandung lagi, lalu melahirkan seorang anak laki-laki dan menamai anak itu Onan.', NULL),
(7503, 3647, 38, 5, 'Kemudian perempuan itu melahirkan seorang anak laki-laki sekali lagi, dan menamai anak itu Syela. Yehuda sedang berada di Kezib, ketika anak itu dilahirkan.', NULL),
(7504, 3647, 38, 6, 'Sesudah itu Yehuda mengambil bagi Er, anak sulungnya, seorang isteri, yang bernama Tamar.', NULL),
(7505, 3647, 38, 7, 'Tetapi Er, anak sulung Yehuda itu, adalah jahat di mata TUHAN, maka TUHAN membunuh dia.', NULL),
(7506, 3647, 38, 8, 'Lalu berkatalah Yehuda kepada Onan: \"Hampirilah isteri kakakmu itu, kawinlah dengan dia sebagai ganti kakakmu dan bangkitkanlah keturunan bagi kakakmu.\"', NULL),
(7507, 3647, 38, 9, 'Tetapi Onan tahu, bahwa bukan ia yang empunya keturunannya nanti, sebab itu setiap kali ia menghampiri isteri kakaknya itu, ia membiarkan maninya terbuang, supaya ia jangan memberi keturunan kepada kakaknya.', NULL),
(7508, 3647, 38, 10, 'Tetapi yang dilakukannya itu adalah jahat di mata TUHAN, maka TUHAN membunuh dia juga.', NULL),
(7509, 3647, 38, 11, 'Lalu berkatalah Yehuda kepada Tamar, menantunya itu: \"Tinggallah sebagai janda di rumah ayahmu, sampai anakku Syela itu besar,\" sebab pikirnya: \"Jangan-jangan ia mati seperti kedua kakaknya itu.\" Maka pergilah Tamar dan tinggal di rumah ayahnya.', NULL),
(7510, 3647, 38, 12, 'Setelah beberapa lama matilah anak Syua, isteri Yehuda. Habis berkabung pergilah Yehuda ke Timna, kepada orang-orang yang menggunting bulu domba-dombanya, bersama dengan Hira, sahabatnya, orang Adulam itu.', NULL),
(7511, 3647, 38, 13, 'Ketika dikabarkan kepada Tamar: \"Bapa mertuamu sedang di jalan ke Timna untuk menggunting bulu domba-dombanya,\"', NULL),
(7512, 3647, 38, 14, 'maka ditanggalkannyalah pakaian kejandaannya, ia bertelekung dan berselubung, lalu pergi duduk di pintu masuk ke Enaim yang di jalan ke Timna, karena dilihatnya, bahwa Syela telah menjadi besar, dan dia tidak diberikan juga kepada Syela itu untuk menjadi isterinya.', NULL),
(7513, 3647, 38, 15, 'Ketika Yehuda melihat dia, disangkanyalah dia seorang perempuan sundal, karena ia menutupi mukanya.', NULL),
(7514, 3647, 38, 16, 'Lalu berpalinglah Yehuda mendapatkan perempuan yang di pinggir jalan itu serta berkata: \"Marilah, aku mau menghampiri engkau,\" sebab ia tidak tahu, bahwa perempuan itu menantunya. Tanya perempuan itu: \"Apakah yang akan kauberikan kepadaku, jika engkau menghampiri aku?\"', NULL),
(7515, 3647, 38, 17, 'Jawabnya: \"Aku akan mengirimkan kepadamu seekor anak kambing dari kambing dombaku.\" Kata perempuan itu: \"Asal engkau memberikan tanggungannya, sampai engkau mengirimkannya kepadaku.\"', NULL),
(7516, 3647, 38, 18, 'Tanyanya: \"Apakah tanggungan yang harus kuberikan kepadamu?\" Jawab perempuan itu: \"Cap meteraimu serta kalungmu dan tongkat yang ada di tanganmu itu.\" Lalu diberikannyalah semuanya itu kepadanya, maka ia menghampirinya. Perempuan itu mengandung dari padanya.', NULL),
(7517, 3647, 38, 19, 'Bangunlah perempuan itu, lalu pergi, ditanggalkannya telekungnya dan dikenakannya pula pakaian kejandaannya.', NULL),
(7518, 3647, 38, 20, 'Adapun Yehuda, ia mengirimkan anak kambing itu dengan perantaraan sahabatnya, orang Adulam itu, untuk mengambil kembali tanggungannya dari tangan perempuan itu, tetapi perempuan itu tidak dijumpainya lagi.', NULL),
(7519, 3647, 38, 21, 'Ia bertanya-tanya di tempat tinggal perempuan itu: \"Di manakah perempuan jalang, yang duduk tadinya di pinggir jalan di Enaim itu?\" Jawab mereka: \"Tidak ada di sini perempuan jalang.\"', NULL),
(7520, 3647, 38, 22, 'Kembalilah ia kepada Yehuda dan berkata: \"Tidak ada kujumpai dia; dan juga orang-orang di tempat itu berkata: Tidak ada perempuan jalang di sini.\"', NULL),
(7521, 3647, 38, 23, 'Lalu berkatalah Yehuda: \"Biarlah barang-barang itu dipegangnya, supaya kita jangan menjadi buah olok-olok orang; sungguhlah anak kambing itu telah kukirimkan, tetapi engkau tidak menjumpai perempuan itu.\"', NULL),
(7522, 3647, 38, 24, 'Sesudah kira-kira tiga bulan dikabarkanlah kepada Yehuda: \"Tamar, menantumu, bersundal, bahkan telah mengandung dari persundalannya itu.\" Lalu kata Yehuda: \"Bawalah perempuan itu, supaya dibakar.\"', NULL),
(7523, 3647, 38, 25, 'Waktu dibawa, perempuan itu menyuruh orang kepada mertuanya mengatakan: \"Dari laki-laki yang empunya barang-barang inilah aku mengandung.\" Juga dikatakannya: \"Periksalah, siapa yang empunya cap meterai serta kalung dan tongkat ini?\"', NULL),
(7524, 3647, 38, 26, 'Yehuda memeriksa barang-barang itu, lalu berkata: \"Bukan aku, tetapi perempuan itulah yang benar, karena memang aku tidak memberikan dia kepada Syela, anakku.\" Dan ia tidak bersetubuh lagi dengan perempuan itu.', NULL),
(7525, 3647, 38, 27, 'Pada waktu perempuan itu hendak bersalin, nyatalah ada anak kembar dalam kandungannya.', NULL),
(7526, 3647, 38, 28, 'Dan ketika ia bersalin, seorang dari anak itu mengeluarkan tangannya, lalu dipegang oleh bidan, diikatnya dengan benang kirmizi serta berkata: \"Inilah yang lebih dahulu keluar.\"', NULL),
(7527, 3647, 38, 29, 'Ketika anak itu menarik tangannya kembali, keluarlah saudaranya laki-laki, dan bidan itu berkata: \"Alangkah kuatnya engkau menembus ke luar,\" maka anak itu dinamai Peres.', NULL),
(7528, 3647, 38, 30, 'Sesudah itu keluarlah saudaranya laki-laki yang tangannya telah berikat benang kirmizi itu, lalu kepadanya diberi nama Zerah.', NULL),
(7529, 3647, 39, 1, 'Adapun Yusuf telah dibawa ke Mesir; dan Potifar, seorang Mesir, pegawai istana Firaun, kepala pengawal raja, membeli dia dari tangan orang Ismael yang telah membawa dia ke situ.', 'Yusuf dan Potifar'),
(7530, 3647, 39, 2, 'Tetapi TUHAN menyertai Yusuf, sehingga ia menjadi seorang yang selalu berhasil dalam pekerjaannya; maka tinggallah ia di rumah tuannya, orang Mesir itu.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(7531, 3647, 39, 3, 'Setelah dilihat oleh tuannya, bahwa Yusuf disertai TUHAN dan bahwa TUHAN membuat berhasil segala sesuatu yang dikerjakannya,', NULL),
(7532, 3647, 39, 4, 'maka Yusuf mendapat kasih tuannya, dan ia boleh melayani dia; kepada Yusuf diberikannya kuasa atas rumahnya dan segala miliknya diserahkannya pada kekuasaan Yusuf.', NULL),
(7533, 3647, 39, 5, 'Sejak ia memberikan kuasa dalam rumahnya dan atas segala miliknya kepada Yusuf, TUHAN memberkati rumah orang Mesir itu karena Yusuf, sehingga berkat TUHAN ada atas segala miliknya, baik yang di rumah maupun yang di ladang.', NULL),
(7534, 3647, 39, 6, 'Segala miliknya diserahkannya pada kekuasaan Yusuf, dan dengan bantuan Yusuf ia tidak usah lagi mengatur apa-apapun selain dari makanannya sendiri. Adapun Yusuf itu manis sikapnya dan elok parasnya.', NULL),
(7535, 3647, 39, 7, 'Selang beberapa waktu isteri tuannya memandang Yusuf dengan berahi, lalu katanya: \"Marilah tidur dengan aku.\"', NULL),
(7536, 3647, 39, 8, 'Tetapi Yusuf menolak dan berkata kepada isteri tuannya itu: \"Dengan bantuanku tuanku itu tidak lagi mengatur apa yang ada di rumah ini dan ia telah menyerahkan segala miliknya pada kekuasaanku,', NULL),
(7537, 3647, 39, 9, 'bahkan di rumah ini ia tidak lebih besar kuasanya dari padaku, dan tiada yang tidak diserahkannya kepadaku selain dari pada engkau, sebab engkau isterinya. Bagaimanakah mungkin aku melakukan kejahatan yang besar ini dan berbuat dosa terhadap Allah?\"', NULL),
(7538, 3647, 39, 10, 'Walaupun dari hari ke hari perempuan itu membujuk Yusuf, Yusuf tidak mendengarkan bujukannya itu untuk tidur di sisinya dan bersetubuh dengan dia.', NULL),
(7539, 3647, 39, 11, 'Pada suatu hari masuklah Yusuf ke dalam rumah untuk melakukan pekerjaannya, sedang dari seisi rumah itu seorangpun tidak ada di rumah.', NULL),
(7540, 3647, 39, 12, 'Lalu perempuan itu memegang baju Yusuf sambil berkata: \"Marilah tidur dengan aku.\" Tetapi Yusuf meninggalkan bajunya di tangan perempuan itu dan lari ke luar.', NULL),
(7541, 3647, 39, 13, 'Ketika dilihat perempuan itu, bahwa Yusuf meninggalkan bajunya dalam tangannya dan telah lari ke luar,', NULL),
(7542, 3647, 39, 14, 'dipanggilnyalah seisi rumah itu, lalu katanya kepada mereka: \"Lihat, dibawanya ke mari seorang Ibrani, supaya orang ini dapat mempermainkan kita. Orang ini mendekati aku untuk tidur dengan aku, tetapi aku berteriak-teriak dengan suara keras.', NULL),
(7543, 3647, 39, 15, 'Dan ketika didengarnya bahwa aku berteriak sekeras-kerasnya, ditinggalkannyalah bajunya padaku, lalu ia lari ke luar.\"', NULL),
(7544, 3647, 39, 16, 'Juga ditaruhnya baju Yusuf itu di sisinya, sampai tuan rumah pulang.', NULL),
(7545, 3647, 39, 17, 'Perkataan itu jugalah yang diceritakan perempuan itu kepada Potifar, katanya: \"Hamba orang Ibrani yang kaubawa ke mari itu datang kepadaku untuk mempermainkan aku.', NULL),
(7546, 3647, 39, 18, 'Tetapi ketika aku berteriak sekeras-kerasnya, ditinggalkannya bajunya padaku, lalu ia lari ke luar.\"', NULL),
(7547, 3647, 39, 19, 'Baru saja didengar oleh tuannya perkataan yang diceritakan isterinya kepadanya: begini begitulah aku diperlakukan oleh hambamu itu, maka bangkitlah amarahnya.', NULL),
(7548, 3647, 39, 20, 'Lalu Yusuf ditangkap oleh tuannya dan dimasukkan ke dalam penjara, tempat tahanan-tahanan raja dikurung. Demikianlah Yusuf dipenjarakan di sana.', NULL),
(7549, 3647, 39, 21, 'Tetapi TUHAN menyertai Yusuf dan melimpahkan kasih setia-Nya kepadanya, dan membuat Yusuf kesayangan bagi kepala penjara itu.', NULL),
(7550, 3647, 39, 22, 'Sebab itu kepala penjara mempercayakan semua tahanan dalam penjara itu kepada Yusuf, dan segala pekerjaan yang harus dilakukan di situ, dialah yang mengurusnya.', NULL),
(7551, 3647, 39, 23, 'Dan kepala penjara tidak mencampuri segala yang dipercayakannya kepada Yusuf, karena TUHAN menyertai dia dan apa yang dikerjakannya dibuat TUHAN berhasil.', NULL),
(7552, 3647, 40, 1, 'Sesudah semuanya itu terjadilah, bahwa juru minuman raja Mesir dan juru rotinya membuat kesalahan terhadap tuannya, raja Mesir itu,', 'Mimpi juru minuman dan juru roti'),
(7553, 3647, 40, 2, 'maka murkalah Firaun kepada kedua pegawai istananya, kepala juru minuman dan kepala juru roti itu.', NULL),
(7554, 3647, 40, 3, 'Ia menahan mereka dalam rumah kepala pengawal raja, dalam penjara tempat Yusuf dikurung.', NULL),
(7555, 3647, 40, 4, 'Kepala pengawal raja menempatkan Yusuf bersama-sama dengan mereka untuk melayani mereka. Demikianlah mereka ditahan beberapa waktu lamanya.', NULL),
(7556, 3647, 40, 5, 'Pada suatu kali bermimpilah mereka keduanya--baik juru minuman maupun juru roti raja Mesir, yang ditahan dalam penjara itu--masing-masing ada mimpinya, pada satu malam juga, dan mimpi masing-masing itu ada artinya sendiri.', NULL),
(7557, 3647, 40, 6, 'Ketika pada waktu pagi Yusuf datang kepada mereka, segera dilihatnya, bahwa mereka bersusah hati.', NULL),
(7558, 3647, 40, 7, 'Lalu ia bertanya kepada pegawai-pegawai istana Firaun yang ditahan bersama-sama dengan dia dalam rumah tuannya itu: \"Mengapakah hari ini mukamu semuram itu?\"', NULL),
(7559, 3647, 40, 8, 'Jawab mereka kepadanya: \"Kami bermimpi, tetapi tidak ada orang yang dapat mengartikannya.\" Lalu kata Yusuf kepada mereka: \"Bukankah Allah yang menerangkan arti mimpi? Ceritakanlah kiranya mimpimu itu kepadaku.\"', NULL),
(7560, 3647, 40, 9, 'Kemudian juru minuman itu menceritakan mimpinya kepada Yusuf, katanya: \"Dalam mimpiku itu tampak ada pohon anggur di depanku.', NULL),
(7561, 3647, 40, 10, 'Pohon anggur itu ada tiga carangnya dan baru saja pohon itu bertunas, bunganya sudah keluar dan tandan-tandannya penuh buah anggur yang ranum.', NULL),
(7562, 3647, 40, 11, 'Dan di tanganku ada piala Firaun. Buah anggur itu kuambil, lalu kuperas ke dalam piala Firaun, kemudian kusampaikan piala itu ke tangan Firaun.\"', NULL),
(7563, 3647, 40, 12, 'Kata Yusuf kepadanya: \"Beginilah arti mimpi itu: ketiga carang itu artinya tiga hari;', NULL),
(7564, 3647, 40, 13, 'dalam tiga hari ini Firaun akan meninggikan engkau dan mengembalikan engkau ke dalam pangkatmu yang dahulu dan engkau akan menyampaikan piala ke tangan Firaun seperti dahulu kala, ketika engkau jadi juru minumannya.', NULL),
(7565, 3647, 40, 14, 'Tetapi, ingatlah kepadaku, apabila keadaanmu telah baik nanti, tunjukkanlah terima kasihmu kepadaku dengan menceritakan hal ihwalku kepada Firaun dan tolonglah keluarkan aku dari rumah ini.', NULL),
(7566, 3647, 40, 15, 'Sebab aku dicuri diculik begitu saja dari negeri orang Ibrani dan di sinipun aku tidak pernah melakukan apa-apa yang menyebabkan aku layak dimasukkan ke dalam liang tutupan ini.\"', NULL),
(7567, 3647, 40, 16, 'Setelah dilihat oleh kepala juru roti, betapa baik arti mimpi itu, berkatalah ia kepadanya: \"Akupun bermimpi juga. Tampak aku menjunjung tiga bakul berisi penganan.', NULL),
(7568, 3647, 40, 17, 'Dalam bakul atas ada berbagai-bagai makanan untuk Firaun, buatan juru roti, tetapi burung-burung memakannya dari dalam bakul yang di atas kepalaku.\"', NULL),
(7569, 3647, 40, 18, 'Yusuf menjawab: \"Beginilah arti mimpi itu: ketiga bakul itu artinya tiga hari;', NULL),
(7570, 3647, 40, 19, 'dalam tiga hari ini Firaun akan meninggikan engkau, tinggi ke atas, dan menggantung engkau pada sebuah tiang, dan burung-burung akan memakan dagingmu dari tubuhmu.\"', NULL),
(7571, 3647, 40, 20, 'Dan terjadilah pada hari ketiga, hari kelahiran Firaun, maka Firaun mengadakan perjamuan untuk semua pegawainya. Ia meninggikan kepala juru minuman dan kepala juru roti itu di tengah-tengah para pegawainya:', NULL),
(7572, 3647, 40, 21, 'kepala juru minuman itu dikembalikannya ke dalam jabatannya, sehingga ia menyampaikan pula piala ke tangan Firaun;', NULL),
(7573, 3647, 40, 22, 'tetapi kepala juru roti itu digantungnya, seperti yang ditakbirkan Yusuf kepada mereka.', NULL),
(7574, 3647, 40, 23, 'Tetapi Yusuf tidaklah diingat oleh kepala juru minuman itu, melainkan dilupakannya.', NULL),
(7575, 3647, 41, 1, 'Setelah lewat dua tahun lamanya, bermimpilah Firaun, bahwa ia berdiri di tepi sungai Nil.', 'Mimpi Firaun'),
(7576, 3647, 41, 2, 'Tampaklah dari sungai Nil itu keluar tujuh ekor lembu yang indah bangunnya dan gemuk badannya; lalu memakan rumput yang di tepi sungai itu.', NULL),
(7577, 3647, 41, 3, 'Kemudian tampaklah juga tujuh ekor lembu yang lain, yang keluar dari dalam sungai Nil itu, buruk bangunnya dan kurus badannya, lalu berdiri di samping lembu-lembu yang tadi, di tepi sungai itu.', NULL),
(7578, 3647, 41, 4, 'Lembu-lembu yang buruk bangunnya dan kurus badannya itu memakan ketujuh ekor lembu yang indah bangunnya dan gemuk itu. Lalu terjagalah Firaun.', NULL),
(7579, 3647, 41, 5, 'Setelah itu tertidur pulalah ia dan bermimpi kedua kalinya: Tampak timbul dari satu tangkai tujuh bulir gandum yang bernas dan baik.', NULL),
(7580, 3647, 41, 6, 'Tetapi kemudian tampaklah juga tumbuh tujuh bulir gandum yang kurus dan layu oleh angin timur.', NULL),
(7581, 3647, 41, 7, 'Bulir yang kurus itu menelan ketujuh bulir yang bernas dan berisi tadi. Lalu terjagalah Firaun. Agaknya ia bermimpi!', NULL),
(7582, 3647, 41, 8, 'Pada waktu pagi gelisahlah hatinya, lalu disuruhnyalah memanggil semua ahli dan semua orang berilmu di Mesir. Firaun menceritakan mimpinya kepada mereka, tetapi seorangpun tidak ada yang dapat mengartikannya kepadanya.', NULL),
(7583, 3647, 41, 9, 'Lalu berkatalah kepala juru minuman kepada Firaun: \"Hari ini aku merasa perlu menyebutkan kesalahanku yang dahulu.', NULL),
(7584, 3647, 41, 10, 'Waktu itu tuanku Firaun murka kepada pegawai-pegawainya, dan menahan aku dalam rumah pengawal istana, beserta dengan kepala juru roti.', NULL),
(7585, 3647, 41, 11, 'Pada satu malam juga kami bermimpi, aku dan kepala juru roti itu; masing-masing mempunyai mimpi dengan artinya sendiri.', NULL),
(7586, 3647, 41, 12, 'Bersama-sama dengan kami ada di sana seorang muda Ibrani, hamba kepala pengawal istana itu; kami menceritakan mimpi kami kepadanya, lalu diartikannya kepada kami mimpi kami masing-masing.', NULL),
(7587, 3647, 41, 13, 'Dan seperti yang diartikannya itu kepada kami, demikianlah pula terjadi: aku dikembalikan ke dalam pangkatku, dan kepala juru roti itu digantung.\"', NULL),
(7588, 3647, 41, 14, 'Kemudian Firaun menyuruh memanggil Yusuf. Segeralah ia dikeluarkan dari tutupan; ia bercukur dan berganti pakaian, lalu pergi menghadap Firaun.', NULL),
(7589, 3647, 41, 15, 'Berkatalah Firaun kepada Yusuf: \"Aku telah bermimpi, dan seorangpun tidak ada yang dapat mengartikannya, tetapi telah kudengar tentang engkau: hanya dengan mendengar mimpi saja engkau dapat mengartikannya.\"', NULL),
(7590, 3647, 41, 16, 'Yusuf menyahut Firaun: \"Bukan sekali-kali aku, melainkan Allah juga yang akan memberitakan kesejahteraan kepada tuanku Firaun.\"', NULL),
(7591, 3647, 41, 17, 'Lalu berkatalah Firaun kepada Yusuf: \"Dalam mimpiku itu, aku berdiri di tepi sungai Nil;', NULL),
(7592, 3647, 41, 18, 'lalu tampaklah dari sungai Nil itu keluar tujuh ekor lembu yang gemuk badannya dan indah bentuknya, dan makan rumput yang di tepi sungai itu.', NULL),
(7593, 3647, 41, 19, 'Tetapi kemudian tampaklah juga keluar tujuh ekor lembu yang lain, kulit pemalut tulang, sangat buruk bangunnya dan kurus badannya; tidak pernah kulihat yang seburuk itu di seluruh tanah Mesir.', NULL),
(7594, 3647, 41, 20, 'Lembu yang kurus dan buruk itu memakan ketujuh ekor lembu gemuk yang mula-mula.', NULL),
(7595, 3647, 41, 21, 'Lembu-lembu ini masuk ke dalam perutnya, tetapi walaupun telah masuk ke dalam perutnya, tidaklah kelihatan sedikitpun tandanya: bangunnya tetap sama buruknya seperti semula. Lalu terjagalah aku.', NULL),
(7596, 3647, 41, 22, 'Selanjutnya dalam mimpiku itu kulihat timbul dari satu tangkai tujuh bulir gandum yang berisi dan baik.', NULL),
(7597, 3647, 41, 23, 'Tetapi kemudian tampaklah juga tumbuh tujuh bulir yang kering, kurus dan layu oleh angin timur.', NULL),
(7598, 3647, 41, 24, 'Bulir yang kurus itu memakan ketujuh bulir yang baik tadi. Telah kuceritakan hal ini kepada semua ahli, tetapi seorangpun tidak ada yang dapat menerangkannya kepadaku.\"', NULL),
(7599, 3647, 41, 25, 'Lalu kata Yusuf kepada Firaun: \"Kedua mimpi tuanku Firaun itu sama. Allah telah memberitahukan kepada tuanku Firaun apa yang hendak dilakukan-Nya.', NULL),
(7600, 3647, 41, 26, 'Ketujuh ekor lembu yang baik itu ialah tujuh tahun, dan ketujuh bulir gandum yang baik itu ialah tujuh tahun juga; kedua mimpi itu sama.', NULL),
(7601, 3647, 41, 27, 'Ketujuh ekor lembu yang kurus dan buruk, yang keluar kemudian, maksudnya tujuh tahun, demikian pula ketujuh bulir gandum yang hampa dan layu oleh angin timur itu; maksudnya akan ada tujuh tahun kelaparan.', NULL),
(7602, 3647, 41, 28, 'Inilah maksud perkataanku, ketika aku berkata kepada tuanku Firaun: Allah telah memperlihatkan kepada tuanku Firaun apa yang hendak dilakukan-Nya.', NULL),
(7603, 3647, 41, 29, 'Ketahuilah tuanku, akan datang tujuh tahun kelimpahan di seluruh tanah Mesir.', NULL),
(7604, 3647, 41, 30, 'Kemudian akan timbul tujuh tahun kelaparan; maka akan dilupakan segala kelimpahan itu di tanah Mesir, karena kelaparan itu menguruskeringkan negeri ini.', NULL),
(7605, 3647, 41, 31, 'Sesudah itu akan tidak kelihatan lagi bekas-bekas kelimpahan di negeri ini karena kelaparan itu, sebab sangat hebatnya kelaparan itu.', NULL),
(7606, 3647, 41, 32, 'Sampai dua kali mimpi itu diulangi bagi tuanku Firaun berarti: hal itu telah ditetapkan oleh Allah dan Allah akan segera melakukannya.', NULL),
(7607, 3647, 41, 33, 'Oleh sebab itu, baiklah tuanku Firaun mencari seorang yang berakal budi dan bijaksana, dan mengangkatnya menjadi kuasa atas tanah Mesir.', NULL),
(7608, 3647, 41, 34, 'Baiklah juga tuanku Firaun berbuat begini, yakni menempatkan penilik-penilik atas negeri ini dan dalam ketujuh tahun kelimpahan itu memungut seperlima dari hasil tanah Mesir.', NULL),
(7609, 3647, 41, 35, 'Mereka harus mengumpulkan segala bahan makanan dalam tahun-tahun baik yang akan datang ini dan, di bawah kuasa tuanku Firaun, menimbun gandum di kota-kota sebagai bahan makanan, serta menyimpannya.', NULL),
(7610, 3647, 41, 36, 'Demikianlah segala bahan makanan itu menjadi persediaan untuk negeri ini dalam ketujuh tahun kelaparan yang akan terjadi di tanah Mesir, supaya negeri ini jangan binasa karena kelaparan itu.\"', NULL),
(7611, 3647, 41, 37, 'Usul itu dipandang baik oleh Firaun dan oleh semua pegawainya.', 'Yusuf di Mesir sebagai penguasa'),
(7612, 3647, 41, 38, 'Lalu berkatalah Firaun kepada para pegawainya: \"Mungkinkah kita mendapat orang seperti ini, seorang yang penuh dengan Roh Allah?\"', NULL),
(7613, 3647, 41, 39, 'Kata Firaun kepada Yusuf: \"Oleh karena Allah telah memberitahukan semuanya ini kepadamu, tidaklah ada orang yang demikian berakal budi dan bijaksana seperti engkau.', NULL),
(7614, 3647, 41, 40, 'Engkaulah menjadi kuasa atas istanaku, dan kepada perintahmu seluruh rakyatku akan taat; hanya takhta inilah kelebihanku dari padamu.\"', NULL),
(7615, 3647, 41, 41, 'Selanjutnya Firaun berkata kepada Yusuf: \"Dengan ini aku melantik engkau menjadi kuasa atas seluruh tanah Mesir.\"', NULL),
(7616, 3647, 41, 42, 'Sesudah itu Firaun menanggalkan cincin meterainya dari jarinya dan mengenakannya pada jari Yusuf; dipakaikannyalah kepada Yusuf pakaian dari pada kain halus dan digantungkannya kalung emas pada lehernya.', NULL),
(7617, 3647, 41, 43, 'Lalu Firaun menyuruh menaikkan Yusuf dalam keretanya yang kedua, dan berserulah orang di hadapan Yusuf: \"Hormat!\" Demikianlah Yusuf dilantik oleh Firaun menjadi kuasa atas seluruh tanah Mesir.', NULL),
(7618, 3647, 41, 44, 'Berkatalah Firaun kepada Yusuf: \"Akulah Firaun, tetapi dengan tidak setahumu, seorangpun tidak boleh bergerak di seluruh tanah Mesir.\"', NULL),
(7619, 3647, 41, 45, 'Lalu Firaun menamai Yusuf: Zafnat-Paaneah, serta memberikan Asnat, anak Potifera, imam di On, kepadanya menjadi isterinya. Demikianlah Yusuf muncul sebagai kuasa atas seluruh tanah Mesir.', NULL),
(7620, 3647, 41, 46, 'Yusuf berumur tiga puluh tahun ketika ia menghadap Firaun, raja Mesir itu. Maka pergilah Yusuf dari depan Firaun, lalu dikelilinginya seluruh tanah Mesir.', NULL),
(7621, 3647, 41, 47, 'Tanah itu mengeluarkan hasil bertumpuk-tumpuk dalam ketujuh tahun kelimpahan itu,', NULL),
(7622, 3647, 41, 48, 'maka Yusuf mengumpulkan segala bahan makanan ketujuh tahun kelimpahan yang ada di tanah Mesir, lalu disimpannya di kota-kota; hasil daerah sekitar tiap-tiap kota disimpan di dalam kota itu.', NULL),
(7623, 3647, 41, 49, 'Demikianlah Yusuf menimbun gandum seperti pasir di laut, sangat banyak, sehingga orang berhenti menghitungnya, karena memang tidak terhitung.', NULL),
(7624, 3647, 41, 50, 'Sebelum datang tahun kelaparan itu, lahirlah bagi Yusuf dua orang anak laki-laki, yang dilahirkan oleh Asnat, anak Potifera, imam di On.', NULL),
(7625, 3647, 41, 51, 'Yusuf memberi nama Manasye kepada anak sulungnya itu, sebab katanya: \"Allah telah membuat aku lupa sama sekali kepada kesukaranku dan kepada rumah bapaku.\"', NULL),
(7626, 3647, 41, 52, 'Dan kepada anaknya yang kedua diberinya nama Efraim, sebab katanya: \"Allah membuat aku mendapat anak dalam negeri kesengsaraanku.\"', NULL),
(7627, 3647, 41, 53, 'Setelah lewat ketujuh tahun kelimpahan yang ada di tanah Mesir itu,', NULL),
(7628, 3647, 41, 54, 'mulailah datang tujuh tahun kelaparan, seperti yang telah dikatakan Yusuf; dalam segala negeri ada kelaparan, tetapi di seluruh negeri Mesir ada roti.', NULL),
(7629, 3647, 41, 55, 'Ketika seluruh negeri Mesir menderita kelaparan, dan rakyat berteriak meminta roti kepada Firaun, berkatalah Firaun kepada semua orang Mesir: \"Pergilah kepada Yusuf, perbuatlah apa yang akan dikatakannya kepadamu.\"', NULL),
(7630, 3647, 41, 56, 'Kelaparan itu merajalela di seluruh bumi. Maka Yusuf membuka segala lumbung dan menjual gandum kepada orang Mesir, sebab makin hebat kelaparan itu di tanah Mesir.', NULL),
(7631, 3647, 41, 57, 'Juga dari seluruh bumi datanglah orang ke Mesir untuk membeli gandum dari Yusuf, sebab hebat kelaparan itu di seluruh bumi.', NULL),
(7632, 3647, 42, 1, 'Setelah Yakub mendapat kabar, bahwa ada gandum di Mesir, berkatalah ia kepada anak-anaknya: \"Mengapa kamu berpandang-pandangan saja?\"', 'Saudara-saudara Yusuf pergi ke Mesir'),
(7633, 3647, 42, 2, 'Lagi katanya: \"Telah kudengar, bahwa ada gandum di Mesir; pergilah ke sana dan belilah gandum di sana untuk kita, supaya kita tetap hidup dan jangan mati.\"', NULL),
(7634, 3647, 42, 3, 'Lalu pergilah sepuluh orang saudara Yusuf untuk membeli gandum di Mesir.', NULL),
(7635, 3647, 42, 4, 'Tetapi Yakub tidak membiarkan Benyamin, adik Yusuf, pergi bersama-sama dengan saudara-saudaranya, sebab pikirnya: \"Jangan-jangan ia ditimpa kecelakaan nanti.\"', NULL),
(7636, 3647, 42, 5, 'Jadi di antara orang yang datang membeli gandum terdapatlah juga anak-anak Israel, sebab ada kelaparan di tanah Kanaan.', NULL),
(7637, 3647, 42, 6, 'Sementara itu Yusuf telah menjadi mangkubumi di negeri itu; dialah yang menjual gandum kepada seluruh rakyat negeri itu. Jadi ketika saudara-saudara Yusuf datang, kepadanyalah mereka menghadap dan sujud dengan mukanya sampai ke tanah.', NULL),
(7638, 3647, 42, 7, 'Ketika Yusuf melihat saudara-saudaranya, segeralah mereka dikenalnya, tetapi ia berlaku seolah-olah ia seorang asing kepada mereka; ia menegor mereka dengan membentak, katanya: \"Dari mana kamu?\" Jawab mereka: \"Dari tanah Kanaan untuk membeli bahan makanan.\"', NULL),
(7639, 3647, 42, 8, 'Memang Yusuf mengenal saudara-saudaranya itu, tetapi dia tidak dikenal mereka.', NULL),
(7640, 3647, 42, 9, 'Lalu teringatlah Yusuf akan mimpi-mimpinya tentang mereka. Berkatalah ia kepada mereka: \"Kamu ini pengintai, kamu datang untuk melihat-lihat di mana negeri ini tidak dijaga.\"', NULL),
(7641, 3647, 42, 10, 'Tetapi jawab mereka: \"Tidak tuanku! Hanyalah untuk membeli bahan makanan hamba-hambamu ini datang.', NULL),
(7642, 3647, 42, 11, 'Kami ini sekalian anak dari satu ayah; kami ini orang jujur; hamba-hambamu ini bukanlah pengintai.\"', NULL),
(7643, 3647, 42, 12, 'Tetapi ia berkata kepada mereka: \"Tidak! Kamu datang untuk melihat-lihat di mana negeri ini tidak dijaga.\"', NULL),
(7644, 3647, 42, 13, 'Lalu jawab mereka: \"Hamba-hambamu ini dua belas orang, kami bersaudara, anak dari satu ayah di tanah Kanaan, tetapi yang bungsu sekarang ada pada ayah kami, dan seorang sudah tidak ada lagi.\"', NULL),
(7645, 3647, 42, 14, 'Lalu kata Yusuf kepada mereka: \"Sudahlah! Seperti telah kukatakan kepadamu tadi: kamu ini pengintai.', NULL),
(7646, 3647, 42, 15, 'Dalam hal ini juga kamu harus diuji: demi hidup Firaun, kamu tidak akan pergi dari sini, jika saudaramu yang bungsu itu tidak datang ke mari.', NULL),
(7647, 3647, 42, 16, 'Suruhlah seorang dari padamu untuk menjemput adikmu itu, tetapi kamu ini harus tinggal terkurung di sini. Dengan demikian perkataanmu dapat diuji, apakah benar, dan jika tidak, demi hidup Firaun, sungguh-sungguhlah kamu ini pengintai.\"', NULL),
(7648, 3647, 42, 17, 'Dan dimasukkannyalah mereka bersama-sama ke dalam tahanan tiga hari lamanya.', NULL),
(7649, 3647, 42, 18, 'Pada hari yang ketiga berkatalah Yusuf kepada mereka: \"Buatlah begini, maka kamu akan tetap hidup, aku takut akan Allah.', NULL),
(7650, 3647, 42, 19, 'Jika kamu orang jujur, biarkanlah dari kamu bersaudara tinggal seorang terkurung dalam rumah tahanan, tetapi pergilah kamu, bawalah gandum untuk meredakan lapar seisi rumahmu.', NULL),
(7651, 3647, 42, 20, 'Tetapi saudaramu yang bungsu itu haruslah kamu bawa kepadaku, supaya perkataanmu itu ternyata benar dan kamu jangan mati.\" Demikianlah diperbuat mereka.', NULL),
(7652, 3647, 42, 21, 'Mereka berkata seorang kepada yang lain: \"Betul-betullah kita menanggung akibat dosa kita terhadap adik kita itu: bukankah kita melihat bagaimana sesak hatinya, ketika ia memohon belas kasihan kepada kita, tetapi kita tidak mendengarkan permohonannya. Itulah sebabnya kesesakan ini menimpa kita.\"', NULL),
(7653, 3647, 42, 22, 'Lalu Ruben menjawab mereka: \"Bukankah dahulu kukatakan kepadamu: Janganlah kamu berbuat dosa terhadap anak itu! Tetapi kamu tidak mendengarkan perkataanku. Sekarang darahnya dituntut dari pada kita.\"', NULL),
(7654, 3647, 42, 23, 'Tetapi mereka tidak tahu, bahwa Yusuf mengerti perkataan mereka, sebab mereka memakai seorang juru bahasa.', NULL),
(7655, 3647, 42, 24, 'Maka Yusuf mengundurkan diri dari mereka, lalu menangis. Kemudian ia kembali kepada mereka dan berkata-kata dengan mereka; ia mengambil Simeon dari antara mereka; lalu disuruh belenggu di depan mata mereka.', NULL),
(7656, 3647, 42, 25, 'Sesudah itu Yusuf memerintahkan, bahwa tempat gandum mereka akan diisi dengan gandum dan bahwa uang mereka masing-masing akan dikembalikan ke dalam karungnya, serta bekal mereka di jalan akan diberikan kepada mereka. Demikianlah dilakukan orang kepada mereka itu.', NULL),
(7657, 3647, 42, 26, 'Sesudah itu merekapun memuat gandum itu ke atas keledai mereka, lalu berangkat dari situ.', NULL),
(7658, 3647, 42, 27, 'Ketika seorang membuka karungnya untuk memberi makan keledainya di tempat bermalam, dilihatnyalah uangnya ada di dalam mulut karungnya.', NULL),
(7659, 3647, 42, 28, 'Katanya kepada saudara-saudaranya: \"Uangku dikembalikan; lihat, ada dalam karungku!\" Lalu hati mereka menjadi tawar dan mereka berpandang-pandangan dengan gemetar serta berkata: \"Apakah juga yang diperbuat Allah terhadap kita!\"', NULL),
(7660, 3647, 42, 29, 'Ketika mereka sampai kepada Yakub, ayah mereka, di tanah Kanaan, mereka menceritakan segala sesuatu yang dialaminya, katanya:', NULL),
(7661, 3647, 42, 30, '\"Orang itu, yakni yang menjadi tuan atas negeri itu, telah menegor kami dengan membentak dan memperlakukan kami sebagai pengintai negeri itu.', NULL),
(7662, 3647, 42, 31, 'Tetapi kata kami kepadanya: Kami orang jujur, kami bukan pengintai.', NULL),
(7663, 3647, 42, 32, 'Kami dua belas orang bersaudara, anak-anak ayah kami; seorang sudah tidak ada lagi, dan yang bungsu ada sekarang pada ayah kami, di tanah Kanaan.', NULL),
(7664, 3647, 42, 33, 'Lalu kata orang itu, yakni yang menjadi tuan atas negeri itu, kepada kami: Dari hal ini aku akan tahu, apakah kamu orang jujur: dari kamu bersaudara haruslah kamu tinggalkan seorang padaku; kemudian bawalah gandum untuk meredakan lapar seisi rumahmu dan pergilah;', NULL),
(7665, 3647, 42, 34, 'lalu bawalah kepadaku saudaramu yang bungsu itu, maka aku akan tahu, bahwa kamu bukan pengintai, tetapi orang jujur; dan aku akan mengembalikan saudaramu itu kepadamu, dan bolehlah kamu menjalani negeri ini dengan bebas.\"', NULL),
(7666, 3647, 42, 35, 'Ketika mereka mengosongkan karungnya, tampaklah ada pundi-pundi uang masing-masing dalam karungnya; dan ketika mereka beserta ayah mereka melihat pundi-pundi uang itu, ketakutanlah mereka.', NULL),
(7667, 3647, 42, 36, 'Dan Yakub, ayah mereka, berkata kepadanya: \"Kamu membuat aku kehilangan anak-anakku: Yusuf tidak ada lagi, dan Simeon tidak ada lagi, sekarang Benyaminpun hendak kamu bawa juga. Aku inilah yang menanggung segala-galanya itu!\"', NULL),
(7668, 3647, 42, 37, 'Lalu berkatalah Ruben kepada ayahnya: \"Kedua anakku laki-laki boleh engkau bunuh, jika ia tidak kubawa kepadamu; serahkanlah dia ke dalam tanganku, maka dia akan kubawa kembali kepadamu.\"', NULL),
(7669, 3647, 42, 38, 'Tetapi jawabnya: \"Anakku itu tidak akan pergi ke sana bersama-sama dengan kamu, sebab kakaknya telah mati dan hanya dialah yang tinggal; jika dia ditimpa kecelakaan di jalan yang akan kamu tempuh, maka tentulah kamu akan menyebabkan aku yang ubanan ini turun ke dunia orang mati karena dukacita.\"', NULL),
(8963, 3647, 43, 1, 'Tetapi hebat sekali kelaparan di negeri itu.', 'Saudara-saudara Yusuf pergi ke Mesir untuk kedua kalinya'),
(8964, 3647, 43, 2, 'Dan setelah gandum yang dibawa mereka dari Mesir habis dimakan, berkatalah ayah mereka: \"Pergilah pula membeli sedikit bahan makanan untuk kita.\"', NULL),
(8965, 3647, 43, 3, 'Lalu Yehuda menjawabnya: \"Orang itu telah memperingatkan kami dengan sungguh-sungguh: Kamu tidak boleh melihat mukaku, jika adikmu itu tidak ada bersama-sama dengan kamu.', NULL),
(8966, 3647, 43, 4, 'Jika engkau mau membiarkan adik kami pergi bersama-sama dengan kami, maka kami mau pergi ke sana dan membeli bahan makanan bagimu.', NULL),
(8967, 3647, 43, 5, 'Tetapi jika engkau tidak mau membiarkan dia pergi, maka kami tidak akan pergi ke sana, sebab orang itu telah berkata kepada kami: Kamu tidak boleh melihat mukaku, jika adikmu itu tidak ada bersama-sama dengan kamu.\"', NULL),
(8968, 3647, 43, 6, 'Lalu berkatalah Israel: \"Mengapa kamu mendatangkan malapetaka kepadaku dengan memberitahukan kepada orang itu, bahwa masih ada adikmu seorang?\"', NULL),
(8969, 3647, 43, 7, 'Jawab mereka: \"Orang itu telah menanyai kami dengan seksama tentang kami sendiri dan tentang sanak saudara kita: Masih hidupkah ayahmu? Adakah adikmu lagi? Dan kami telah memberitahukan semuanya kepadanya seperti yang sebenarnya. Bagaimana kami dapat menduga bahwa ia akan berkata: Bawalah ke mari adikmu itu.\"', NULL),
(8970, 3647, 43, 8, 'Lalu berkatalah Yehuda kepada Israel, ayahnya: \"Biarkanlah anak itu pergi bersama-sama dengan aku; maka kami akan bersiap dan pergi, supaya kita tetap hidup dan jangan mati, baik kami maupun engkau dan anak-anak kami.', NULL),
(8971, 3647, 43, 9, 'Akulah yang menanggung dia; engkau boleh menuntut dia dari padaku; jika aku tidak membawa dia kepadamu dan menempatkan dia di depanmu, maka akulah yang berdosa terhadap engkau untuk selama-lamanya.', NULL),
(8972, 3647, 43, 10, 'Jika kita tidak berlambat-lambat, maka tentulah kami sekarang sudah dua kali pulang.\"', NULL),
(8973, 3647, 43, 11, 'Lalu Israel, ayah mereka, berkata kepadanya: \"Jika demikian, perbuatlah begini: Ambillah hasil yang terbaik dari negeri ini dalam tempat gandummu dan bawalah kepada orang itu sebagai persembahan: sedikit balsam dan sedikit madu, damar dan damar ladan, buah kemiri dan buah badam.', NULL),
(8974, 3647, 43, 12, 'Dan bawalah uang dua kali lipat banyaknya: uang yang telah dikembalikan ke dalam mulut karung-karungmu itu haruslah kamu bawa kembali; mungkin itu suatu kekhilafan.', NULL),
(8975, 3647, 43, 13, 'Bawalah juga adikmu itu, bersiaplah dan kembalilah pula kepada orang itu.', NULL),
(8976, 3647, 43, 14, 'Allah Yang Mahakuasa kiranya membuat orang itu menaruh belas kasihan kepadamu, supaya ia membiarkan saudaramu yang lain itu beserta Benyamin kembali. Mengenai aku ini, jika terpaksa aku kehilangan anak-anakku, biarlah juga kehilangan!\"', NULL),
(8977, 3647, 43, 15, 'Lalu orang-orang itu mengambil persembahan itu dan mengambil uang dua kali lipat banyaknya, beserta Benyamin juga; mereka bersiap dan pergi ke Mesir. Kemudian berdirilah mereka di depan Yusuf.', NULL),
(8978, 3647, 43, 16, 'Ketika Yusuf melihat Benyamin bersama-sama dengan mereka, berkatalah ia kepada kepala rumahnya: \"Bawalah orang-orang ini ke dalam rumah, sembelihlah seekor hewan dan siapkanlah itu, sebab orang-orang ini akan makan bersama-sama dengan aku pada tengah hari ini.\"', NULL),
(8979, 3647, 43, 17, 'Orang itu melakukan seperti yang dikatakan Yusuf dan dibawanyalah orang-orang itu ke dalam rumah Yusuf.', NULL),
(8980, 3647, 43, 18, 'Lalu ketakutanlah orang-orang itu, karena mereka dibawa ke dalam rumah Yusuf. Kata mereka: \"Yang menjadi sebab kita dibawa ke sini, ialah perkara uang yang dikembalikan ke dalam karung kita pada mulanya itu, supaya kita disergap dan ditangkap dan supaya kita dijadikan budak dan keledai kita diambil.\"', NULL),
(8981, 3647, 43, 19, 'Karena itu mereka mendekati kepala rumah Yusuf itu, dan berkata kepadanya di depan pintu rumah:', NULL),
(8982, 3647, 43, 20, '\"Mohon bicara tuan! Kami dahulu datang ke mari untuk membeli bahan makanan,', NULL),
(8983, 3647, 43, 21, 'tetapi ketika kami sampai ke tempat bermalam dan membuka karung kami, tampaklah uang kami masing-masing dengan tidak kurang jumlahnya ada di dalam mulut karung. Tetapi sekarang kami membawanya kembali.', NULL),
(8984, 3647, 43, 22, 'Uang lain kami bawa juga ke mari untuk membeli bahan makanan; kami tidak tahu siapa yang menaruh uang kami itu ke dalam karung kami.\"', NULL),
(8985, 3647, 43, 23, 'Tetapi jawabnya: \"Tenang sajalah, jangan takut; Allahmu dan Allah bapamu telah memberikan kepadamu harta terpendam dalam karungmu; uangmu itu telah kuterima.\" Kemudian dikeluarkannyalah Simeon dan dibawanya kepada mereka.', NULL),
(8986, 3647, 43, 24, 'Setelah orang itu membawa mereka ke dalam rumah Yusuf, diberikannyalah air, supaya mereka membasuh kaki; juga keledai mereka diberinya makan.', NULL),
(8987, 3647, 43, 25, 'Sesudah itu mereka menyiapkan persembahannya menantikan Yusuf datang pada waktu tengah hari, sebab mereka telah mendengar, bahwa mereka akan makan di situ.', NULL),
(8988, 3647, 43, 26, 'Ketika Yusuf telah pulang, mereka membawa persembahan yang ada pada mereka itu kepada Yusuf di dalam rumah, lalu sujud kepadanya sampai ke tanah.', NULL),
(8989, 3647, 43, 27, 'Sesudah itu ia bertanya kepada mereka apakah mereka selamat; lagi katanya: \"Apakah ayahmu yang tua yang kamu sebutkan itu selamat? Masih hidupkah ia?\"', NULL),
(8990, 3647, 43, 28, 'Jawab mereka: \"Hambamu, ayah kami, ada selamat; ia masih hidup.\" Sesudah itu berlututlah mereka dan sujud.', NULL),
(8991, 3647, 43, 29, 'Ketika Yusuf memandang kepada mereka, dilihatnyalah Benyamin, adiknya, yang seibu dengan dia, lalu katanya: \"Inikah adikmu yang bungsu itu, yang telah kamu sebut-sebut kepadaku?\" Lagi katanya: \"Allah kiranya memberikan kasih karunia kepadamu, anakku!\"', NULL),
(8992, 3647, 43, 30, 'Lalu segeralah Yusuf pergi dari situ, sebab hatinya sangat terharu merindukan adiknya itu, dan dicarinyalah tempat untuk menangis; ia masuk ke dalam kamar, lalu menangis di situ.', NULL),
(8993, 3647, 43, 31, 'Sesudah itu dibasuhnyalah mukanya dan ia tampil ke luar. Ia menahan hatinya dan berkata: \"Hidangkanlah makanan.\"', NULL),
(8994, 3647, 43, 32, 'Lalu dihidangkanlah makanan, bagi Yusuf tersendiri, bagi saudara-saudaranya tersendiri dan bagi orang-orang Mesir yang bersama-sama makan dengan mereka itu tersendiri; sebab orang Mesir tidak boleh makan bersama-sama dengan orang Ibrani, karena hal itu suatu kekejian bagi orang Mesir.', NULL),
(8995, 3647, 43, 33, 'Saudara-saudaranya itu duduk di depan Yusuf, dari yang sulung sampai yang bungsu, sehingga mereka berpandang-pandangan dengan heran.', NULL),
(8996, 3647, 43, 34, 'Lalu disajikan kepada mereka hidangan dari meja Yusuf, tetapi yang diterima Benyamin adalah lima kali lebih banyak dari pada setiap orang yang lain. Lalu minumlah mereka dan bersukaria bersama-sama dengan dia.', NULL),
(8997, 3647, 44, 1, 'Sesudah itu diperintahkannyalah kepada kepala rumahnya: \"Isilah karung orang-orang itu dengan gandum, seberapa yang dapat dibawa mereka, dan letakkanlah uang masing-masing di dalam mulut karungnya.', 'Piala Yusuf hilang dan didapati'),
(8998, 3647, 44, 2, 'Dan pialaku, piala perak itu, taruhlah di dalam mulut karung anak yang bungsu serta uang pembayar gandumnya juga.\" Maka diperbuatnyalah seperti yang dikatakan Yusuf.', NULL),
(8999, 3647, 44, 3, 'Ketika paginya hari terang tanah, orang melepas mereka beserta keledai mereka.', NULL),
(9000, 3647, 44, 4, 'Tetapi baru saja mereka keluar dari kota itu, belum lagi jauh jaraknya, berkatalah Yusuf kepada kepala rumahnya: \"Bersiaplah, kejarlah orang-orang itu, dan apabila engkau sampai kepada mereka, katakanlah kepada mereka: Mengapa kamu membalas yang baik dengan yang jahat?', NULL),
(9001, 3647, 44, 5, 'Bukankah ini piala yang dipakai tuanku untuk minum dan yang biasa dipakainya untuk menelaah? Kamu berbuat jahat dengan melakukan yang demikian.\"', NULL),
(9002, 3647, 44, 6, 'Ketika sampai kepada mereka, diberitakannyalah kepada mereka perkataan Yusuf itu.', NULL),
(9003, 3647, 44, 7, 'Jawab mereka kepadanya: \"Mengapa tuanku mengatakan perkataan yang demikian? Jauhlah dari pada hamba-hambamu ini untuk berbuat begitu!', NULL),
(9004, 3647, 44, 8, 'Bukankah uang yang kami dapati di dalam mulut karung kami telah kami bawa kembali kepadamu dari tanah Kanaan? Masakan kami mencuri emas atau perak dari rumah tuanmu?', NULL),
(9005, 3647, 44, 9, 'Pada siapa dari hamba-hambamu ini kedapatan piala itu, biarlah ia mati, juga kami ini akan menjadi budak tuanku.\"', NULL),
(9006, 3647, 44, 10, 'Sesudah itu berkatalah ia: \"Ya, usulmu itu baik; tetapi pada siapa kedapatan piala itu, hanya dialah yang akan menjadi budakku dan kamu yang lain itu akan bebas dari salah.\"', NULL),
(9007, 3647, 44, 11, 'Lalu segeralah mereka masing-masing menurunkan karungnya ke tanah dan masing-masing membuka karungnya.', NULL),
(9008, 3647, 44, 12, 'Dan kepala rumah itu memeriksanya dengan teliti; ia mulai dengan yang sulung sampai kepada yang bungsu; maka kedapatanlah piala itu dalam karung Benyamin.', NULL),
(9009, 3647, 44, 13, 'Lalu mereka mengoyakkan jubahnya dan masing-masing memuati keledainya, dan mereka kembali ke kota.', NULL),
(9010, 3647, 44, 14, 'Ketika Yehuda dan saudara-saudaranya sampai ke dalam rumah Yusuf, Yusuf masih ada di situ, sujudlah mereka sampai ke tanah di depannya.', NULL),
(9011, 3647, 44, 15, 'Berkatalah Yusuf kepada mereka: \"Perbuatan apakah yang kamu lakukan ini? Tidakkah kamu tahu, bahwa seorang yang seperti aku ini pasti dapat menelaah?\"', NULL),
(9012, 3647, 44, 16, 'Sesudah itu berkatalah Yehuda: \"Apakah yang akan kami katakan kepada tuanku, apakah yang akan kami jawab, dan dengan apakah kami akan membenarkan diri kami? Allah telah memperlihatkan kesalahan hamba-hambamu ini. Maka kami ini, budak tuankulah kami, baik kami maupun orang pada siapa kedapatan piala itu.\"', NULL),
(9013, 3647, 44, 17, 'Tetapi jawabnya: \"Jauhlah dari padaku untuk berbuat demikian! Pada siapa kedapatan piala itu, dialah yang akan menjadi budakku, tetapi kamu ini, pergilah kembali dengan selamat kepada ayahmu.\"', NULL),
(9014, 3647, 44, 18, 'Lalu tampillah Yehuda mendekatinya dan berkata: \"Mohon bicara tuanku, izinkanlah kiranya hambamu ini mengucapkan sepatah kata kepada tuanku dan janganlah kiranya bangkit amarahmu terhadap hambamu ini, sebab tuanku adalah seperti Firaun sendiri.', 'Yehuda membela Benyamin'),
(9015, 3647, 44, 19, 'Tuanku telah bertanya kepada hamba-hambanya ini: Masih adakah ayah atau saudara kamu?', NULL),
(9016, 3647, 44, 20, 'Dan kami menjawab tuanku: Kami masih mempunyai ayah yang tua dan masih ada anaknya yang muda, yang lahir pada masa tuanya; kakaknya telah mati, hanya dia sendirilah yang tinggal dari mereka yang seibu, sebab itu ayahnya sangat mengasihi dia.', NULL),
(9017, 3647, 44, 21, 'Lalu tuanku berkata kepada hamba-hambamu ini: Bawalah dia ke mari kepadaku, supaya mataku memandang dia.', NULL),
(9018, 3647, 44, 22, 'Tetapi jawab kami kepada tuanku: Anak itu tidak dapat meninggalkan ayahnya, sebab jika ia meninggalkan ayahnya, tentulah ayah ini mati.', NULL),
(9019, 3647, 44, 23, 'Kemudian tuanku berkata kepada hamba-hambamu ini: Jika adikmu yang bungsu itu tidak datang ke mari bersama-sama dengan kamu, kamu tidak boleh melihat mukaku lagi.', NULL),
(9020, 3647, 44, 24, 'Setelah kami kembali kepada hambamu, ayahku, maka kami memberitahukan kepadanya perkataan tuanku itu.', NULL),
(9021, 3647, 44, 25, 'Kemudian ayah kami berkata: Kembalilah kamu membeli sedikit bahan makanan bagi kita.', NULL),
(9022, 3647, 44, 26, 'Tetapi jawab kami: Kami tidak dapat pergi ke sana. Jika adik kami yang bungsu bersama-sama dengan kami, barulah kami akan pergi ke sana, sebab kami tidak boleh melihat muka orang itu, apabila adik kami yang bungsu tidak bersama-sama dengan kami.', NULL),
(9023, 3647, 44, 27, 'Kemudian berkatalah hambamu, ayahku, kepada kami: Kamu tahu, bahwa isteriku telah melahirkan dua orang anak bagiku;', NULL),
(9024, 3647, 44, 28, 'yang seorang telah pergi dari padaku, dan aku telah berkata: Tentulah ia diterkam oleh binatang buas, dan sampai sekarang aku tidak melihat dia kembali.', NULL),
(9025, 3647, 44, 29, 'Jika anak ini kamu ambil pula dari padaku, dan ia ditimpa kecelakaan, maka tentulah kamu akan menyebabkan aku yang ubanan ini turun ke dunia orang mati karena nasib celaka.', NULL),
(9026, 3647, 44, 30, 'Maka sekarang, apabila aku datang kepada hambamu, ayahku, dan tidak ada bersama-sama dengan kami anak itu, padahal ayahku tidak dapat hidup tanpa dia,', NULL),
(9027, 3647, 44, 31, 'tentulah akan terjadi, apabila dilihatnya anak itu tidak ada, bahwa ia akan mati, dan hamba-hambamu ini akan menyebabkan hambamu, ayah kami yang ubanan itu, turun ke dunia orang mati karena dukacita.', NULL),
(9028, 3647, 44, 32, 'Tetapi hambamu ini telah menanggung anak itu terhadap ayahku dengan perkataan: Jika aku tidak membawanya kembali kepada bapa, maka akulah yang berdosa kepada bapa untuk selama-lamanya.', NULL),
(9029, 3647, 44, 33, 'Oleh sebab itu, baiklah hambamu ini tinggal menjadi budak tuanku menggantikan anak itu, dan biarlah anak itu pulang bersama-sama dengan saudara-saudaranya.', NULL),
(9030, 3647, 44, 34, 'Sebab masakan aku pulang kepada ayahku, apabila anak itu tidak bersama-sama dengan aku? Aku tidak akan sanggup melihat nasib celaka yang akan menimpa ayahku.\"', NULL),
(9031, 3647, 45, 1, 'Ketika itu Yusuf tidak dapat menahan hatinya lagi di depan semua orang yang berdiri di dekatnya, lalu berserulah ia: \"Suruhlah keluar semua orang dari sini.\" Maka tidak ada seorangpun yang tinggal di situ bersama-sama Yusuf, ketika ia memperkenalkan dirinya kepada saudara-saudaranya.', 'Yusuf memperkenalkan dirinya kepada saudara-saudaranya'),
(9032, 3647, 45, 2, 'Setelah itu menangislah ia keras-keras, sehingga kedengaran kepada orang Mesir dan kepada seisi istana Firaun.', NULL),
(9033, 3647, 45, 3, 'Dan Yusuf berkata kepada saudara-saudaranya: \"Akulah Yusuf! Masih hidupkah bapa?\" Tetapi saudara-saudaranya tidak dapat menjawabnya, sebab mereka takut dan gemetar menghadapi dia.', NULL),
(9034, 3647, 45, 4, 'Lalu kata Yusuf kepada saudara-saudaranya itu: \"Marilah dekat-dekat.\" Maka mendekatlah mereka. Katanya lagi: \"Akulah Yusuf, saudaramu, yang kamu jual ke Mesir.', NULL),
(9035, 3647, 45, 5, 'Tetapi sekarang, janganlah bersusah hati dan janganlah menyesali diri, karena kamu menjual aku ke sini, sebab untuk memelihara kehidupanlah Allah menyuruh aku mendahului kamu.', NULL),
(9036, 3647, 45, 6, 'Karena telah dua tahun ada kelaparan dalam negeri ini dan selama lima tahun lagi orang tidak akan membajak atau menuai.', NULL),
(9037, 3647, 45, 7, 'Maka Allah telah menyuruh aku mendahului kamu untuk menjamin kelanjutan keturunanmu di bumi ini dan untuk memelihara hidupmu, sehingga sebagian besar dari padamu tertolong.', NULL),
(9038, 3647, 45, 8, 'Jadi bukanlah kamu yang menyuruh aku ke sini, tetapi Allah; Dialah yang telah menempatkan aku sebagai bapa bagi Firaun dan tuan atas seluruh istananya dan sebagai kuasa atas seluruh tanah Mesir.', NULL),
(9039, 3647, 45, 9, 'Segeralah kamu kembali kepada bapa dan katakanlah kepadanya: Beginilah kata Yusuf, anakmu: Allah telah menempatkan aku sebagai tuan atas seluruh Mesir; datanglah mendapatkan aku, janganlah tunggu-tunggu.', NULL),
(9040, 3647, 45, 10, 'Engkau akan tinggal di tanah Gosyen dan akan dekat kepadaku, engkau serta anak dan cucumu, kambing domba dan lembu sapimu dan segala milikmu.', NULL),
(9041, 3647, 45, 11, 'Di sanalah aku memelihara engkau--sebab kelaparan ini masih ada lima tahun lagi--supaya engkau jangan jatuh miskin bersama seisi rumahmu dan semua orang yang ikut serta dengan engkau.', NULL),
(9042, 3647, 45, 12, 'Dan kamu telah melihat dengan mata sendiri, dan saudaraku Benyamin juga, bahwa mulutku sendiri mengatakannya kepadamu.', NULL),
(9043, 3647, 45, 13, 'Sebab itu ceritakanlah kepada bapa segala kemuliaanku di negeri Mesir ini, dan segala yang telah kamu lihat, kemudian segeralah bawa bapa ke mari.\"', NULL),
(9044, 3647, 45, 14, 'Lalu dipeluknyalah leher Benyamin, adiknya itu, dan menangislah ia, dan menangis pulalah Benyamin pada bahu Yusuf.', NULL),
(9045, 3647, 45, 15, 'Yusuf mencium semua saudaranya itu dengan mesra dan ia menangis sambil memeluk mereka. Sesudah itu barulah saudara-saudaranya bercakap-cakap dengan dia.', NULL),
(9046, 3647, 45, 16, 'Ketika dalam istana Firaun terdengar kabar, bahwa saudara-saudara Yusuf datang, hal itu diterima dengan baik oleh Firaun dan pegawai-pegawainya.', NULL),
(9047, 3647, 45, 17, 'Lalu berkatalah Firaun kepada Yusuf: \"Katakanlah kepada saudara-saudaramu Buatlah begini: muatilah binatang-binatangmu dan pergilah ke tanah Kanaan,', NULL),
(9048, 3647, 45, 18, 'jemputlah ayahmu dan seisi rumahmu dan datanglah mendapatkan aku, maka aku akan memberikan kepadamu apa yang paling baik di tanah Mesir, sehingga kamu akan mengecap kesuburan tanah ini.', NULL),
(9049, 3647, 45, 19, 'Selanjutnya engkau mendapat perintah mengatakan kepada mereka: Buatlah begini: bawalah kereta dari tanah Mesir untuk anak-anakmu dan isteri-isterimu, jemputlah ayahmu dari sana dan datanglah ke mari.', NULL),
(9050, 3647, 45, 20, 'Janganlah kamu merasa sayang meninggalkan barang-barangmu, sebab apa yang paling baik di seluruh tanah Mesir ini adalah milikmu.\"', NULL),
(9051, 3647, 45, 21, 'Demikianlah dilakukan oleh anak-anak Israel itu. Yusuf memberikan kereta kepada mereka menurut perintah Firaun; juga diberikan kepada mereka bekal di jalan.', NULL),
(9052, 3647, 45, 22, 'Kepada mereka masing-masing diberikannya sepotong pesalin dan kepada Benyamin diberikannya tiga ratus uang perak dan lima potong pesalin.', NULL),
(9053, 3647, 45, 23, 'Di samping itu kepada ayahnya dikirimkannya sepuluh ekor keledai jantan, dimuati dengan apa yang paling baik di Mesir, lagipula sepuluh ekor keledai betina, dimuati dengan gandum dan roti dan makanan untuk ayahnya dalam perjalanan.', NULL),
(9054, 3647, 45, 24, 'Kemudian ia melepas saudara-saudaranya serta berkata kepada mereka: \"Janganlah berbantah-bantah di jalan.\"', NULL),
(9055, 3647, 45, 25, 'Demikianlah mereka pergi dari tanah Mesir dan sampai di tanah Kanaan, kepada Yakub, ayah mereka.', NULL),
(9056, 3647, 45, 26, 'Mereka menceritakan kepadanya: \"Yusuf masih hidup, bahkan dialah yang menjadi kuasa atas seluruh tanah Mesir.\" Tetapi hati Yakub tetap dingin, sebab ia tidak dapat mempercayai mereka.', NULL),
(9057, 3647, 45, 27, 'Tetapi ketika mereka menyampaikan kepadanya segala perkataan yang diucapkan Yusuf, dan ketika dilihatnya kereta yang dikirim oleh Yusuf untuk menjemputnya, maka bangkitlah kembali semangat Yakub, ayah mereka itu.', NULL),
(9058, 3647, 45, 28, 'Kata Yakub: \"Cukuplah itu; anakku Yusuf masih hidup; aku mau pergi melihatnya, sebelum aku mati.\"', NULL),
(10448, 3647, 46, 1, 'Jadi berangkatlah Israel dengan segala miliknya dan ia tiba di Bersyeba, lalu dipersembahkannya korban sembelihan kepada Allah Ishak ayahnya.', 'Yakub pindah ke Mesir'),
(10449, 3647, 46, 2, 'Berfirmanlah Allah kepada Israel dalam penglihatan waktu malam: \"Yakub, Yakub!\" Sahutnya: \"Ya, Tuhan.\"', NULL),
(10450, 3647, 46, 3, 'Lalu firman-Nya: \"Akulah Allah, Allah ayahmu, janganlah takut pergi ke Mesir, sebab Aku akan membuat engkau menjadi bangsa yang besar di sana.', NULL),
(10451, 3647, 46, 4, 'Aku sendiri akan menyertai engkau pergi ke Mesir dan tentulah Aku juga akan membawa engkau kembali; dan tangan Yusuflah yang akan mengatupkan kelopak matamu nanti.\"', NULL),
(10452, 3647, 46, 5, 'Lalu berangkatlah Yakub dari Bersyeba, dan anak-anak Israel membawa Yakub, ayah mereka, beserta anak dan isteri mereka, dan mereka menaiki kereta yang dikirim Firaun untuk menjemputnya.', NULL),
(10453, 3647, 46, 6, 'Mereka membawa juga ternaknya dan harta bendanya, yang telah diperoleh mereka di tanah Kanaan, lalu tibalah mereka di Mesir, yakni Yakub dan seluruh keturunannya bersama-sama dengan dia.', NULL),
(10454, 3647, 46, 7, 'Anak-anak dan cucu-cucunya laki-laki dan perempuan, seluruh keturunannya dibawanyalah ke Mesir.', NULL),
(10455, 3647, 46, 8, 'Inilah nama-nama bani Israel yang datang ke Mesir, yakni Yakub beserta keturunannya. Anak sulung Yakub ialah Ruben.', NULL),
(10456, 3647, 46, 9, 'Anak-anak Ruben ialah Henokh, Palu, Hezron dan Karmi.', NULL),
(10457, 3647, 46, 10, 'Anak-anak Simeon ialah Yemuel, Yamin, Ohad, Yakhin dan Zohar serta Saul, anak seorang perempuan Kanaan.', NULL),
(10458, 3647, 46, 11, 'Anak-anak Lewi ialah Gerson, Kehat dan Merari.', NULL),
(10459, 3647, 46, 12, 'Anak-anak Yehuda ialah Er, Onan, Syela, Peres dan Zerah; tetapi Er dan Onan mati di tanah Kanaan; dan anak-anak Peres ialah Hezron dan Hamul.', NULL),
(10460, 3647, 46, 13, 'Anak-anak Isakhar ialah Tola, Pua, Ayub dan Simron.', NULL),
(10461, 3647, 46, 14, 'Anak-anak Zebulon ialah Sered, Elon dan Yahleel.', NULL),
(10462, 3647, 46, 15, 'Itulah keturunan Lea, yang melahirkan bagi Yakub di Padan-Aram anak-anak lelaki serta Dina juga, anaknya yang perempuan. Jadi seluruhnya, laki-laki dan perempuan, berjumlah tiga puluh tiga jiwa.', NULL),
(10463, 3647, 46, 16, 'Anak-anak Gad ialah Zifyon, Hagi, Syuni, Ezbon, Eri, Arodi dan Areli.', NULL),
(10464, 3647, 46, 17, 'Anak-anak Asyer ialah Yimna, Yiswa, Yiswi dan Beria; Serah ialah saudara perempuan mereka; dan anak-anak Beria ialah Heber dan Malkiel.', NULL),
(10465, 3647, 46, 18, 'Itulah keturunan Zilpa, yakni hamba perempuan yang telah diberikan Laban kepada Lea, anaknya perempuan, dan yang melahirkan anak-anak bagi Yakub; seluruhnya enam belas jiwa.', NULL),
(10466, 3647, 46, 19, 'Anak-anak Rahel, isteri Yakub, ialah Yusuf dan Benyamin.', NULL),
(10467, 3647, 46, 20, 'Bagi Yusuf lahir Manasye dan Efraim di tanah Mesir, yang dilahirkan baginya oleh Asnat, anak perempuan Potifera, imam di On.', NULL),
(10468, 3647, 46, 21, 'Anak-anak Benyamin ialah Bela, Bekher, Asybel, Gera, Naaman, Ehi, Rosh, Mupim, Hupim dan Ared.', NULL),
(10469, 3647, 46, 22, 'Itulah keturunan Rahel, yang telah lahir bagi Yakub, seluruhnya berjumlah empat belas jiwa.', NULL),
(10470, 3647, 46, 23, 'Anak Dan ialah Husim.', NULL),
(10471, 3647, 46, 24, 'Anak-anak Naftali ialah Yahzeel, Guni, Yezer dan Syilem.', NULL),
(10472, 3647, 46, 25, 'Itulah keturunan Bilha, yakni hamba perempuan yang diberikan Laban kepada Rahel, anaknya yang perempuan dan yang melahirkan anak-anak itu bagi Yakub--seluruhnya berjumlah tujuh jiwa.', NULL),
(10473, 3647, 46, 26, 'Semua orang yang tiba di Mesir bersama-sama dengan Yakub, yakni anak-anak kandungnya, dengan tidak terhitung isteri anak-anaknya, seluruhnya berjumlah enam puluh enam jiwa.', NULL),
(10474, 3647, 46, 27, 'Anak-anak Yusuf yang lahir baginya di Mesir ada dua orang. Jadi keluarga Yakub yang tiba di Mesir, seluruhnya berjumlah tujuh puluh jiwa.', NULL),
(10475, 3647, 46, 28, 'Yakub menyuruh Yehuda berjalan lebih dahulu mendapatkan Yusuf, supaya Yusuf datang ke Gosyen menemui ayahnya. Sementara itu sampailah mereka ke tanah Gosyen.', NULL),
(10476, 3647, 46, 29, 'Lalu Yusuf memasang keretanya dan pergi ke Gosyen, mendapatkan Israel, ayahnya. Ketika ia bertemu dengan dia, dipeluknyalah leher ayahnya dan lama menangis pada bahunya.', NULL),
(10477, 3647, 46, 30, 'Berkatalah Israel kepada Yusuf: \"Sekarang bolehlah aku mati, setelah aku melihat mukamu dan mengetahui bahwa engkau masih hidup.\"', NULL),
(10478, 3647, 46, 31, 'Kemudian berkatalah Yusuf kepada saudara-saudaranya dan kepada keluarga ayahnya itu: \"Aku mau menghadap Firaun dan memberitahukan kepadanya: Saudara-saudaraku dan keluarga ayahku, yang tinggal di tanah Kanaan, telah datang kepadaku;', NULL),
(10479, 3647, 46, 32, 'orang-orang itu gembala kambing domba, sebab mereka itu pemelihara ternak, dan kambing dombanya, lembu sapinya dan segala miliknya telah dibawa mereka.', NULL),
(10480, 3647, 46, 33, 'Apabila Firaun memanggil kamu dan bertanya: Apakah pekerjaanmu?', NULL),
(10481, 3647, 46, 34, 'maka jawablah: Hamba-hambamu ini pemelihara ternak, sejak dari kecil sampai sekarang, baik kami maupun nenek moyang kami--dengan maksud supaya kamu boleh diam di tanah Gosyen.\" --Sebab segala gembala kambing domba adalah suatu kekejian bagi orang Mesir.', NULL),
(10482, 3647, 47, 1, 'Kemudian pergilah Yusuf memberitahukan kepada Firaun: \"Ayahku dan saudara-saudaraku beserta kambing dombanya, lembu sapinya dan segala miliknya telah datang dari tanah Kanaan, dan sekarang mereka ada di tanah Gosyen.\"', 'Yakub dan Firaun'),
(10483, 3647, 47, 2, 'Dari antara saudara-saudaranya itu dibawanya lima orang menghadap Firaun.', NULL),
(10484, 3647, 47, 3, 'Firaun bertanya kepada saudara-saudara Yusuf itu: \"Apakah pekerjaanmu?\" Jawab mereka kepada Firaun: \"Hamba-hambamu ini gembala domba, baik kami maupun nenek moyang kami.\"', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(10485, 3647, 47, 4, 'Lagi kata mereka kepada Firaun: \"Kami datang untuk tinggal di negeri ini sebagai orang asing, sebab tidak ada lagi padang rumput untuk kumpulan ternak hamba-hambamu ini, karena hebat kelaparan itu di tanah Kanaan; maka sekarang, izinkanlah hamba-hambamu ini menetap di tanah Gosyen.\"', NULL),
(10486, 3647, 47, 5, 'Lalu berkatalah Firaun kepada Yusuf: \"Ayahmu dan saudara-saudaramu telah datang kepadamu.', NULL),
(10487, 3647, 47, 6, 'Tanah Mesir ini terbuka untukmu. Tunjukkanlah kepada ayahmu dan kepada saudara-saudaramu tempat menetap di tempat yang terbaik dari negeri ini, biarlah mereka diam di tanah Gosyen. Dan jika engkau tahu di antara mereka orang-orang yang tangkas, tempatkanlah mereka menjadi pengawas ternakku.\"', NULL),
(10488, 3647, 47, 7, 'Yusuf membawa juga Yakub, ayahnya, menghadap Firaun. Lalu Yakub memohonkan berkat bagi Firaun.', NULL),
(10489, 3647, 47, 8, 'Kemudian bertanyalah Firaun kepada Yakub: \"Sudah berapa tahun umurmu?\"', NULL),
(10490, 3647, 47, 9, 'Jawab Yakub kepada Firaun: \"Tahun-tahun pengembaraanku sebagai orang asing berjumlah seratus tiga puluh tahun. Tahun-tahun hidupku itu sedikit saja dan buruk adanya, tidak mencapai umur nenek moyangku, yakni jumlah tahun mereka mengembara sebagai orang asing.\"', NULL),
(10491, 3647, 47, 10, 'Lalu Yakub memohonkan berkat bagi Firaun, sesudah itu keluarlah ia dari depan Firaun.', NULL),
(10492, 3647, 47, 11, 'Yusuf menunjukkan kepada ayahnya dan saudara-saudaranya tempat untuk menetap dan memberikan kepada mereka tanah milik di tanah Mesir, di tempat yang terbaik di negeri itu, di tanah Rameses, seperti yang diperintahkan Firaun.', NULL),
(10493, 3647, 47, 12, 'Dan Yusuf memelihara ayahnya, saudara-saudaranya dan seisi rumah ayahnya dengan makanan, menurut jumlah anak-anak mereka.', NULL),
(10494, 3647, 47, 13, 'Di seluruh negeri itu tidak ada makanan, sebab kelaparan itu sangat hebat, sehingga seisi tanah Mesir dan tanah Kanaan lemah lesu karena kelaparan itu.', 'Tindakan Yusuf'),
(10495, 3647, 47, 14, 'Maka Yusuf mengumpulkan segala uang yang terdapat di tanah Mesir dan di tanah Kanaan, yakni uang pembayar gandum yang dibeli mereka; dan Yusuf membawa uang itu ke dalam istana Firaun.', NULL),
(10496, 3647, 47, 15, 'Setelah habis uang di tanah Mesir dan di tanah Kanaan, datanglah semua orang Mesir menghadap Yusuf serta berkata: \"Berilah makanan kepada kami! Mengapa kami harus mati di depanmu? Sebab tidak ada lagi uang.\"', NULL),
(10497, 3647, 47, 16, 'Jawab Yusuf: \"Jika tidak ada lagi uang, berilah ternakmu, maka aku akan memberi makanan kepadamu sebagai ganti ternakmu itu.\"', NULL),
(10498, 3647, 47, 17, 'Lalu mereka membawa ternaknya kepada Yusuf dan Yusuf memberi makanan kepada mereka ganti kuda, kumpulan kambing domba dan kumpulan lembu sapi dan keledainya, jadi disediakannyalah bagi mereka makanan ganti segala ternaknya pada tahun itu.', NULL),
(10499, 3647, 47, 18, 'Setelah lewat tahun itu, datanglah mereka kepadanya, pada tahun yang kedua, serta berkata kepadanya: \"Tidak usah kami sembunyikan kepada tuanku, bahwa setelah uang kami habis dan setelah kumpulan ternak kami menjadi milik tuanku, tidaklah ada lagi yang tinggal yang dapat kami serahkan kepada tuanku selain badan kami dan tanah kami.', NULL),
(10500, 3647, 47, 19, 'Mengapa kami harus mati di depan matamu, baik kami maupun tanah kami? Belilah kami dan tanah kami sebagai ganti makanan, maka kami dengan tanah kami akan menjadi hamba kepada Firaun. Berikanlah benih, supaya kami hidup dan jangan mati, dan supaya tanah itu jangan menjadi tandus.\"', NULL),
(10501, 3647, 47, 20, 'Lalu Yusuf membeli segala tanah orang Mesir untuk Firaun, sebab orang Mesir itu masing-masing menjual ladangnya, karena berat kelaparan itu menimpa mereka. Demikianlah negeri itu menjadi milik Firaun.', NULL),
(10502, 3647, 47, 21, 'Dan tentang rakyat itu, diperhambakannyalah mereka di daerah Mesir dari ujung yang satu sampai ujung yang lain.', NULL),
(10503, 3647, 47, 22, 'Hanya tanah para imam tidak dibelinya, sebab para imam mendapat tunjangan tetap dari Firaun, dan mereka hidup dari tunjangan itu; itulah sebabnya mereka tidak menjual tanahnya.', NULL),
(10504, 3647, 47, 23, 'Berkatalah Yusuf kepada rakyat itu: \"Pada hari ini aku telah membeli kamu dan tanahmu untuk Firaun; inilah benih bagimu, supaya kamu dapat menabur di tanah itu.', NULL),
(10505, 3647, 47, 24, 'Mengenai hasilnya, kamu harus berikan seperlima bagian kepada Firaun, dan yang empat bagian lagi, itulah menjadi benih untuk ladangmu dan menjadi makanan kamu dan mereka yang ada di rumahmu, dan menjadi makanan anak-anakmu.\"', NULL),
(10506, 3647, 47, 25, 'Lalu berkatalah mereka: \"Engkau telah memelihara hidup kami; asal kiranya kami mendapat kasih tuanku, biarlah kami menjadi hamba kepada Firaun.\"', NULL),
(10507, 3647, 47, 26, 'Yusuf membuat hal itu menjadi suatu ketetapan mengenai tanah di Mesir sampai sekarang, yakni bahwa seperlima dari hasilnya menjadi milik Firaun; hanya tanah para imam tidak menjadi milik Firaun.', NULL),
(10508, 3647, 47, 27, 'Maka diamlah Israel di tanah Mesir, di tanah Gosyen, dan mereka menjadi penduduk di situ. Mereka beranak cucu dan sangat bertambah banyak.', 'Yakub pada akhir hidupnya'),
(10509, 3647, 47, 28, 'Dan Yakub masih hidup tujuh belas tahun di tanah Mesir, maka umur Yakub, yakni tahun-tahun hidupnya, menjadi seratus empat puluh tujuh tahun.', NULL),
(10510, 3647, 47, 29, 'Ketika hampir waktunya bahwa Israel akan mati, dipanggilnyalah anaknya, Yusuf, dan berkata kepadanya: \"Jika aku mendapat kasihmu, letakkanlah kiranya tanganmu di bawah pangkal pahaku, dan bersumpahlah, bahwa engkau akan menunjukkan kasih dan setia kepadaku: Janganlah kiranya kuburkan aku di Mesir,', NULL),
(10511, 3647, 47, 30, 'karena aku mau mendapat perhentian bersama-sama dengan nenek moyangku. Sebab itu angkutlah aku dari Mesir dan kuburkanlah aku dalam kubur mereka.\" Jawabnya: \"Aku akan berbuat seperti katamu itu.\"', NULL),
(10512, 3647, 47, 31, 'Kemudian kata Yakub: \"Bersumpahlah kepadaku.\" Maka Yusufpun bersumpah kepadanya. Lalu sujudlah Israel di sebelah kepala tempat tidurnya.', NULL),
(10513, 3647, 48, 1, 'Sesudah itu ada orang mengatakan kepada Yusuf: \"Ayahmu sakit!\" Lalu dibawanyalah kedua anaknya, Manasye dan Efraim.', 'Yakub memberkati Manasye dan Efraim'),
(10514, 3647, 48, 2, 'Ketika diberitahukan kepada Yakub: \"Telah datang anakmu Yusuf kepadamu,\" maka Israel mengumpulkan segenap kekuatannya dan duduklah ia di tempat tidurnya.', NULL),
(10515, 3647, 48, 3, 'Berkatalah Yakub kepada Yusuf: \"Allah, Yang Mahakuasa telah menampakkan diri kepadaku di Lus di tanah Kanaan dan memberkati aku', NULL),
(10516, 3647, 48, 4, 'serta berfirman kepadaku: Akulah yang membuat engkau beranak cucu, dan Aku akan membuat engkau bertambah banyak dan menjadi sekumpulan bangsa-bangsa; Aku akan memberikan negeri ini kepada keturunanmu untuk menjadi miliknya sampai selama-lamanya.', NULL),
(10517, 3647, 48, 5, 'Maka sekarang kedua anakmu yang lahir bagimu di tanah Mesir, sebelum aku datang kepadamu ke Mesir, akulah yang empunya mereka; akulah yang akan empunya Efraim dan Manasye sama seperti Ruben dan Simeon.', NULL),
(10518, 3647, 48, 6, 'Dan keturunanmu yang kauperoleh sesudah mereka, engkaulah yang empunya, tetapi dalam pembagian warisan nama mereka akan disebutkan berdasarkan nama kedua saudaranya itu.', NULL),
(10519, 3647, 48, 7, 'Kalau aku, pada waktu perjalananku dari Padan, aku kematian Rahel di tanah Kanaan di jalan, ketika kami tidak berapa jauh lagi dari Efrata, dan aku menguburkannya di sana, di sisi jalan ke Efrata\" --yaitu Betlehem.', NULL),
(10520, 3647, 48, 8, 'Ketika Israel melihat anak-anak Yusuf itu, bertanyalah ia: \"Siapakah ini?\"', NULL),
(10521, 3647, 48, 9, 'Jawab Yusuf kepada ayahnya: \"Inilah anak-anakku yang telah diberikan Allah kepadaku di sini.\" Maka kata Yakub: \"Dekatkanlah mereka kepadaku, supaya kuberkati mereka.\"', NULL),
(10522, 3647, 48, 10, 'Adapun mata Israel telah kabur karena tuanya, jadi ia tidak dapat lagi melihat. Kemudian Yusuf mendekatkan mereka kepada ayahnya: dan mereka dicium serta didekap oleh ayahnya.', NULL),
(10523, 3647, 48, 11, 'Lalu berkatalah Israel kepada Yusuf: \"Tidak kusangka-sangka, bahwa aku akan melihat mukamu lagi, tetapi sekarang Allah bahkan memberi aku melihat keturunanmu.\"', NULL),
(10524, 3647, 48, 12, 'Lalu Yusuf menarik mereka dari antara lutut ayahnya, dan ia sujud dengan mukanya sampai ke tanah.', NULL),
(10525, 3647, 48, 13, 'Setelah itu Yusuf memegang mereka keduanya, dengan tangan kanan dipegangnya Efraim, yaitu di sebelah kiri Israel, dan dengan tangan kiri Manasye, yaitu di sebelah kanan Israel, lalu didekatkannyalah mereka kepadanya.', NULL),
(10526, 3647, 48, 14, 'Tetapi Israel mengulurkan tangan kanannya dan meletakkannya di atas kepala Efraim, walaupun ia yang bungsu, dan tangan kirinya di atas kepala Manasye--jadi tangannya bersilang, walaupun Manasye yang sulung.', NULL),
(10527, 3647, 48, 15, 'Sesudah itu diberkatinyalah Yusuf, katanya: \"Nenekku dan ayahku, Abraham dan Ishak, telah hidup di hadapan Allah; Allah itu, sebagai Allah yang telah menjadi gembalaku selama hidupku sampai sekarang,', NULL),
(10528, 3647, 48, 16, 'dan sebagai Malaikat yang telah melepaskan aku dari segala bahaya, Dialah kiranya yang memberkati orang-orang muda ini, sehingga namaku serta nama nenek dan bapaku, Abraham dan Ishak, termasyhur oleh karena mereka dan sehingga mereka bertambah-tambah menjadi jumlah yang besar di bumi.\"', NULL),
(10529, 3647, 48, 17, 'Ketika Yusuf melihat bahwa ayahnya meletakkan tangan kanannya di atas kepala Efraim, hal itu dipandangnya tidak baik; lalu dipegangnya tangan ayahnya untuk memindahkannya dari atas kepala Efraim ke atas kepala Manasye.', NULL),
(10530, 3647, 48, 18, 'Katanya kepada ayahnya: \"Janganlah demikian, ayahku, sebab inilah yang sulung, letakkanlah tangan kananmu ke atas kepalanya.\"', NULL),
(10531, 3647, 48, 19, 'Tetapi ayahnya menolak, katanya: \"Aku tahu, anakku, aku tahu; ia juga akan menjadi suatu bangsa dan ia juga akan menjadi besar kuasanya; walaupun begitu, adiknya akan lebih besar kuasanya dari padanya, dan keturunan adiknya itu akan menjadi sejumlah besar bangsa-bangsa.\"', NULL),
(10532, 3647, 48, 20, 'Lalu diberkatinyalah mereka pada waktu itu, katanya: \"Dengan menyebutkan namamulah orang Israel akan memberkati, demikian: Allah kiranya membuat engkau seperti Efraim dan seperti Manasye.\" Demikianlah didahulukannya Efraim dari pada Manasye.', NULL),
(10533, 3647, 48, 21, 'Kemudian berkatalah Israel kepada Yusuf: \"Tidak lama lagi aku akan mati, tetapi Allah akan menyertai kamu dan membawa kamu kembali ke negeri nenek moyangmu.', NULL),
(10534, 3647, 48, 22, 'Dan sekarang aku memberikan kepadamu sebagai kelebihanmu dari pada saudara-saudaramu, suatu punggung gunung yang kurebut dengan pedang dan panahku dari tangan orang Amori.\"', NULL),
(10535, 3647, 49, 1, 'Kemudian Yakub memanggil anak-anaknya dan berkata: \"Datanglah berkumpul, supaya kuberitahukan kepadamu, apa yang akan kamu alami di kemudian hari.', 'Perkataan Yakub yang penghabisan kepada anak-anaknya'),
(10536, 3647, 49, 2, 'Berhimpunlah kamu dan dengarlah, ya anak-anak Yakub, dengarlah kepada Israel, ayahmu.', NULL),
(10537, 3647, 49, 3, 'Ruben, engkaulah anak sulungku, kekuatanku dan permulaan kegagahanku, engkaulah yang terutama dalam keluhuran, yang terutama dalam kesanggupan.', NULL),
(10538, 3647, 49, 4, 'Engkau yang membual sebagai air, tidak lagi engkau yang terutama, sebab engkau telah menaiki tempat tidur ayahmu; waktu itu engkau telah melanggar kesuciannya. Dia telah menaiki petiduranku!', NULL),
(10539, 3647, 49, 5, 'Simeon dan Lewi bersaudara; senjata mereka ialah alat kekerasan.', NULL),
(10540, 3647, 49, 6, 'Janganlah kiranya jiwaku turut dalam permupakatan mereka, janganlah kiranya rohku bersatu dengan perkumpulan mereka, sebab dalam kemarahannya mereka telah membunuh orang dan dalam keangkaraannya mereka telah memotong urat keting lembu.', NULL),
(10541, 3647, 49, 7, 'Terkutuklah kemarahan mereka, sebab amarahnya keras, terkutuklah keberangan mereka, sebab berangnya bengis. Aku akan membagi-bagikan mereka di antara anak-anak Yakub dan menyerakkan mereka di antara anak-anak Israel.', NULL),
(10542, 3647, 49, 8, 'Yehuda, engkau akan dipuji oleh saudara-saudaramu, tanganmu akan menekan tengkuk musuhmu, kepadamu akan sujud anak-anak ayahmu.', NULL),
(10543, 3647, 49, 9, 'Yehuda adalah seperti anak singa: setelah menerkam, engkau naik ke suatu tempat yang tinggi, hai anakku; ia meniarap dan berbaring seperti singa jantan atau seperti singa betina; siapakah yang berani membangunkannya?', NULL),
(10544, 3647, 49, 10, 'Tongkat kerajaan tidak akan beranjak dari Yehuda ataupun lambang pemerintahan dari antara kakinya, sampai dia datang yang berhak atasnya, maka kepadanya akan takluk bangsa-bangsa.', NULL),
(10545, 3647, 49, 11, 'Ia akan menambatkan keledainya pada pohon anggur dan anak keledainya pada pohon anggur pilihan; ia akan mencuci pakaiannya dengan anggur dan bajunya dengan darah buah anggur.', NULL),
(10546, 3647, 49, 12, 'Matanya akan merah karena anggur dan giginya akan putih karena susu.', NULL),
(10547, 3647, 49, 13, 'Zebulon akan diam di tepi pantai laut, ia akan menjadi pangkalan kapal, dan batasnya akan bersisi dengan Sidon.', NULL),
(10548, 3647, 49, 14, 'Isakhar adalah seperti keledai yang kuat tulangnya, yang meniarap diapit bebannya,', NULL),
(10549, 3647, 49, 15, 'ketika dilihatnya, bahwa perhentian itu baik dan negeri itu permai, maka disendengkannyalah bahunya untuk memikul, lalu menjadi budak rodi.', NULL),
(10550, 3647, 49, 16, 'Adapun Dan, ia akan mengadili bangsanya sebagai salah satu suku Israel.', NULL),
(10551, 3647, 49, 17, 'Semoga Dan menjadi seperti ular di jalan, seperti ular beludak di denai yang memagut tumit kuda, sehingga penunggangnya jatuh ke belakang.', NULL),
(10552, 3647, 49, 18, 'Aku menanti-nantikan keselamatan yang dari pada-Mu, ya TUHAN.', NULL),
(10553, 3647, 49, 19, 'Gad, ia akan diserang oleh gerombolan, tetapi ia akan menyerang tumit mereka.', NULL),
(10554, 3647, 49, 20, 'Asyer, makanannya akan limpah mewah dan ia akan memberikan santapan raja-raja.', NULL),
(10555, 3647, 49, 21, 'Naftali adalah seperti rusa betina yang terlepas; ia akan melahirkan anak-anak indah.', NULL),
(10556, 3647, 49, 22, 'Yusuf adalah seperti pohon buah-buahan yang muda, pohon buah-buahan yang muda pada mata air. Dahan-dahannya naik mengatasi tembok.', NULL),
(10557, 3647, 49, 23, 'Walaupun pemanah-pemanah telah mengusiknya, memanahnya dan menyerbunya,', NULL),
(10558, 3647, 49, 24, 'namun panahnya tetap kokoh dan lengan tangannya tinggal liat, oleh pertolongan Yang Mahakuat pelindung Yakub, oleh sebab gembalanya Gunung Batu Israel,', NULL),
(10559, 3647, 49, 25, 'oleh Allah ayahmu yang akan menolong engkau, dan oleh Allah Yang Mahakuasa, yang akan memberkati engkau dengan berkat dari langit di atas, dengan berkat samudera raya yang letaknya di bawah, dengan berkat buah dada dan kandungan.', NULL),
(10560, 3647, 49, 26, 'Berkat ayahmu melebihi berkat gunung-gunung yang sejak dahulu, yakni yang paling sedap di bukit-bukit yang berabad-abad; semuanya itu akan turun ke atas kepala Yusuf, ke atas batu kepala orang yang teristimewa di antara saudara-saudaranya.', NULL),
(10561, 3647, 49, 27, 'Benyamin adalah seperti serigala yang menerkam; pada waktu pagi ia memakan mangsanya dan pada waktu petang ia membagi-bagi rampasannya.\"', NULL),
(10562, 3647, 49, 28, 'Itulah semuanya suku Israel, dua belas jumlahnya; dan itulah yang dikatakan ayahnya kepada mereka, ketika ia memberkati mereka; tiap-tiap orang diberkatinya dengan berkat yang diuntukkan kepada mereka masing-masing.', NULL),
(10563, 3647, 49, 29, 'Kemudian berpesanlah Yakub kepada mereka: \"Apabila aku nanti dikumpulkan kepada kaum leluhurku, kuburkanlah aku di sisi nenek moyangku dalam gua yang di ladang Efron, orang Het itu,', 'Yakub meninggal dan dikuburkan'),
(10564, 3647, 49, 30, 'dalam gua yang di ladang Makhpela di sebelah timur Mamre di tanah Kanaan, ladang yang telah dibeli Abraham dari Efron, orang Het itu, untuk menjadi kuburan milik.', NULL),
(10565, 3647, 49, 31, 'Di situlah dikuburkan Abraham beserta Sara, isterinya; di situlah dikuburkan Ishak beserta Ribka, isterinya,', NULL),
(10566, 3647, 49, 32, 'dan di situlah juga kukuburkan Lea; ladang dengan gua yang ada di sana telah dibeli dari orang Het.\"', NULL),
(10567, 3647, 49, 33, 'Setelah Yakub selesai berpesan kepada anak-anaknya, ditariknyalah kakinya ke atas tempat berbaring dan meninggallah ia, maka ia dikumpulkan kepada kaum leluhurnya.', NULL),
(10568, 3647, 50, 1, 'Lalu Yusuf merebahkan dirinya mendekap muka ayahnya serta menangisi dan mencium dia.', NULL),
(10569, 3647, 50, 2, 'Dan Yusuf memerintahkan kepada tabib-tabib, yaitu hamba-hambanya, untuk merempah-rempahi mayat ayahnya; maka tabib-tabib itu merempah-rempahi mayat Israel.', NULL),
(10570, 3647, 50, 3, 'Hal itu memerlukan empat puluh hari lamanya, sebab demikianlah lamanya waktu yang diperlukan untuk merempah-rempahi, dan orang Mesir menangisi dia tujuh puluh hari lamanya.', NULL),
(10571, 3647, 50, 4, 'Setelah lewat hari-hari penangisan itu, berkatalah Yusuf kepada seisi istana Firaun: \"Jika kiranya aku mendapat kasihmu, katakanlah kepada Firaun,', NULL),
(10572, 3647, 50, 5, 'bahwa ayahku telah menyuruh aku bersumpah, katanya: Tidak lama lagi aku akan mati; dalam kuburku yang telah kugali di tanah Kanaan, di situlah kaukuburkan aku. Oleh sebab itu, izinkanlah aku pergi ke sana, supaya aku menguburkan ayahku; kemudian aku akan kembali.\"', NULL),
(10573, 3647, 50, 6, 'Lalu berkatalah Firaun: \"Pergilah ke sana dan kuburkanlah ayahmu itu, seperti yang telah disuruhnya engkau bersumpah.\"', NULL),
(10574, 3647, 50, 7, 'Lalu berjalanlah Yusuf ke sana untuk menguburkan ayahnya, dan bersama-sama dengan dia berjalanlah semua pegawai Firaun, para tua-tua dari istananya, dan semua tua-tua dari tanah Mesir,', NULL),
(10575, 3647, 50, 8, 'serta seisi rumah Yusuf juga, saudara-saudaranya dan seisi rumah ayahnya; hanya anak-anaknya serta kambing domba dan lembu sapinya ditinggalkan mereka di tanah Gosyen.', NULL),
(10576, 3647, 50, 9, 'Baik kereta maupun orang-orang berkuda turut pergi ke sana bersama-sama dengan dia, sehingga iring-iringan itu sangat besar.', NULL),
(10577, 3647, 50, 10, 'Setelah mereka sampai ke Goren-Haatad, yang di seberang sungai Yordan, maka mereka mengadakan di situ ratapan yang sangat sedih dan riuh; dan Yusuf mengadakan perkabungan tujuh hari lamanya karena ayahnya itu.', NULL),
(10578, 3647, 50, 11, 'Ketika penduduk negeri itu, orang-orang Kanaan, melihat perkabungan di Goren-Haatad itu, berkatalah mereka: \"Inilah perkabungan orang Mesir yang amat riuh.\" Itulah sebabnya tempat itu dinamai Abel-Mizraim, yang letaknya di seberang Yordan.', NULL),
(10579, 3647, 50, 12, 'Anak-anak Yakub melakukan kepadanya, seperti yang dipesankannya kepada mereka.', NULL),
(10580, 3647, 50, 13, 'Anak-anaknya mengangkut dia ke tanah Kanaan, dan mereka menguburkan dia dalam gua di ladang Makhpela yang telah dibeli Abraham dari Efron, orang Het itu, untuk menjadi kuburan milik, yaitu ladang yang di sebelah timur Mamre.', NULL),
(10581, 3647, 50, 14, 'Setelah ayahnya dikuburkan, pulanglah Yusuf ke Mesir, dia dan saudara-saudaranya dan semua orang yang turut pergi ke sana bersama-sama dengan dia untuk menguburkan ayahnya itu.', NULL),
(10582, 3647, 50, 15, 'Ketika saudara-saudara Yusuf melihat, bahwa ayah mereka telah mati, berkatalah mereka: \"Boleh jadi Yusuf akan mendendam kita dan membalaskan sepenuhnya kepada kita segala kejahatan yang telah kita lakukan kepadanya.\"', 'Yusuf menghiburkan hati saudara-saudaranya'),
(10583, 3647, 50, 16, 'Sebab itu mereka menyuruh menyampaikan pesan ini kepada Yusuf: \"Sebelum ayahmu mati, ia telah berpesan:', NULL),
(10584, 3647, 50, 17, 'Beginilah harus kamu katakan kepada Yusuf: Ampunilah kiranya kesalahan saudara-saudaramu dan dosa mereka, sebab mereka telah berbuat jahat kepadamu. Maka sekarang, ampunilah kiranya kesalahan yang dibuat hamba-hamba Allah ayahmu.\" Lalu menangislah Yusuf, ketika orang berkata demikian kepadanya.', NULL),
(10585, 3647, 50, 18, 'Juga saudara-saudaranya datang sendiri dan sujud di depannya serta berkata: \"Kami datang untuk menjadi budakmu.\"', NULL),
(10586, 3647, 50, 19, 'Tetapi Yusuf berkata kepada mereka: \"Janganlah takut, sebab aku inikah pengganti Allah?', NULL),
(10587, 3647, 50, 20, 'Memang kamu telah mereka-rekakan yang jahat terhadap aku, tetapi Allah telah mereka-rekakannya untuk kebaikan, dengan maksud melakukan seperti yang terjadi sekarang ini, yakni memelihara hidup suatu bangsa yang besar.', NULL),
(10588, 3647, 50, 21, 'Jadi janganlah takut, aku akan menanggung makanmu dan makan anak-anakmu juga.\" Demikianlah ia menghiburkan mereka dan menenangkan hati mereka dengan perkataannya.', NULL),
(10589, 3647, 50, 22, 'Adapun Yusuf, ia tetap tinggal di Mesir beserta kaum keluarganya; dan Yusuf hidup seratus sepuluh tahun.', 'Yusuf meninggal'),
(10590, 3647, 50, 23, 'Jadi Yusuf sempat melihat anak cucu Efraim sampai keturunan yang ketiga; juga anak-anak Makhir, anak Manasye, lahir di pangkuan Yusuf.', NULL),
(10591, 3647, 50, 24, 'Berkatalah Yusuf kepada saudara-saudaranya: \"Tidak lama lagi aku akan mati; tentu Allah akan memperhatikan kamu dan membawa kamu keluar dari negeri ini, ke negeri yang telah dijanjikan-Nya dengan sumpah kepada Abraham, Ishak dan Yakub.\"', NULL),
(10592, 3647, 50, 25, 'Lalu Yusuf menyuruh anak-anak Israel bersumpah, katanya: \"Tentu Allah akan memperhatikan kamu; pada waktu itu kamu harus membawa tulang-tulangku dari sini.\"', NULL),
(10593, 3647, 50, 26, 'Kemudian matilah Yusuf, berumur seratus sepuluh tahun. Mayatnya dirempah-rempahi, dan ditaruh dalam peti mati di Mesir.', NULL),
(35153, 3648, 1, 2, 'Ruben, Simeon, Lewi dan Yehuda;', NULL),
(35154, 3648, 1, 3, 'Isakhar, Zebulon dan Benyamin;', NULL),
(35155, 3648, 1, 4, 'Dan serta Naftali, Gad dan Asyer.', NULL),
(35156, 3648, 1, 5, 'Seluruh keturunan yang diperoleh Yakub berjumlah tujuh puluh jiwa. Tetapi Yusuf telah ada di Mesir.', NULL),
(35157, 3648, 1, 6, 'Kemudian matilah Yusuf, serta semua saudara-saudaranya dan semua orang yang seangkatan dengan dia.', NULL),
(35158, 3648, 1, 7, 'Orang-orang Israel beranak cucu dan tak terbilang jumlahnya; mereka bertambah banyak dan dengan dahsyat berlipat ganda, sehingga negeri itu dipenuhi mereka.', NULL),
(35159, 3648, 1, 8, 'Kemudian bangkitlah seorang raja baru memerintah tanah Mesir, yang tidak mengenal Yusuf.', NULL),
(35160, 3648, 1, 9, 'Berkatalah raja itu kepada rakyatnya: \"Bangsa Israel itu sangat banyak dan lebih besar jumlahnya dari pada kita.', NULL),
(35161, 3648, 1, 10, 'Marilah kita bertindak dengan bijaksana terhadap mereka, supaya mereka jangan bertambah banyak lagi dan--jika terjadi peperangan--jangan bersekutu nanti dengan musuh kita dan memerangi kita, lalu pergi dari negeri ini.\"', NULL),
(35162, 3648, 1, 11, 'Sebab itu pengawas-pengawas rodi ditempatkan atas mereka untuk menindas mereka dengan kerja paksa: mereka harus mendirikan bagi Firaun kota-kota perbekalan, yakni Pitom dan Raamses.', NULL),
(35163, 3648, 1, 12, 'Tetapi makin ditindas, makin bertambah banyak dan berkembang mereka, sehingga orang merasa takut kepada orang Israel itu.', NULL),
(35164, 3648, 1, 13, 'Lalu dengan kejam orang Mesir memaksa orang Israel bekerja,', NULL),
(35165, 3648, 1, 14, 'dan memahitkan hidup mereka dengan pekerjaan yang berat, yaitu mengerjakan tanah liat dan batu bata, dan berbagai-bagai pekerjaan di padang, ya segala pekerjaan yang dengan kejam dipaksakan orang Mesir kepada mereka itu.', NULL),
(35166, 3648, 1, 15, 'Raja Mesir juga memerintahkan kepada bidan-bidan yang menolong perempuan Ibrani, seorang bernama Sifra dan yang lain bernama Pua, katanya:', NULL),
(35167, 3648, 1, 16, '\"Apabila kamu menolong perempuan Ibrani pada waktu bersalin, kamu harus memperhatikan waktu anak itu lahir: jika anak laki-laki, kamu harus membunuhnya, tetapi jika anak perempuan, bolehlah ia hidup.\"', NULL),
(35168, 3648, 1, 17, 'Tetapi bidan-bidan itu takut akan Allah dan tidak melakukan seperti yang dikatakan raja Mesir kepada mereka, dan membiarkan bayi-bayi itu hidup.', NULL),
(35169, 3648, 1, 18, 'Lalu raja Mesir memanggil bidan-bidan itu dan bertanya kepada mereka: \"Mengapakah kamu berbuat demikian membiarkan hidup bayi-bayi itu?\"', NULL),
(35170, 3648, 1, 19, 'Jawab bidan-bidan itu kepada Firaun: \"Sebab perempuan Ibrani tidak sama dengan perempuan Mesir; melainkan mereka kuat: sebelum bidan datang, mereka telah bersalin.\"', NULL),
(35171, 3648, 1, 20, 'Maka Allah berbuat baik kepada bidan-bidan itu; bertambah banyaklah bangsa itu dan sangat berlipat ganda.', NULL),
(35172, 3648, 1, 21, 'Dan karena bidan-bidan itu takut akan Allah, maka Ia membuat mereka berumah tangga.', NULL),
(35173, 3648, 1, 22, 'Lalu Firaun memberi perintah kepada seluruh rakyatnya: \"Lemparkanlah segala anak laki-laki yang lahir bagi orang Ibrani ke dalam sungai Nil; tetapi segala anak perempuan biarkanlah hidup.\"', NULL),
(42954, 3648, 2, 1, 'Seorang laki-laki dari keluarga Lewi kawin dengan seorang perempuan Lewi;', 'Musa lahir dan diselamatkan'),
(42955, 3648, 2, 2, 'lalu mengandunglah ia dan melahirkan seorang anak laki-laki. Ketika dilihatnya, bahwa anak itu cantik, disembunyikannya tiga bulan lamanya.', NULL),
(42956, 3648, 2, 3, 'Tetapi ia tidak dapat menyembunyikannya lebih lama lagi, sebab itu diambilnya sebuah peti pandan, dipakalnya dengan gala-gala dan ter, diletakkannya bayi itu di dalamnya dan ditaruhnya peti itu di tengah-tengah teberau di tepi sungai Nil;', NULL),
(42957, 3648, 2, 4, 'kakaknya perempuan berdiri di tempat yang agak jauh untuk melihat, apakah yang akan terjadi dengan dia.', NULL),
(42958, 3648, 2, 5, 'Maka datanglah puteri Firaun untuk mandi di sungai Nil, sedang dayang-dayangnya berjalan-jalan di tepi sungai Nil, lalu terlihatlah olehnya peti yang di tengah-tengah teberau itu, maka disuruhnya hambanya perempuan untuk mengambilnya.', NULL),
(42959, 3648, 2, 6, 'Ketika dibukanya, dilihatnya bayi itu, dan tampaklah anak itu menangis, sehingga belas kasihanlah ia kepadanya dan berkata: \"Tentulah ini bayi orang Ibrani.\"', NULL),
(42960, 3648, 2, 7, 'Lalu bertanyalah kakak anak itu kepada puteri Firaun: \"Akan kupanggilkah bagi tuan puteri seorang inang penyusu dari perempuan Ibrani untuk menyusukan bayi itu bagi tuan puteri?\"', NULL),
(42961, 3648, 2, 8, 'Sahut puteri Firaun kepadanya: \"Baiklah.\" Lalu pergilah gadis itu memanggil ibu bayi itu.', NULL),
(42962, 3648, 2, 9, 'Maka berkatalah puteri Firaun kepada ibu itu: \"Bawalah bayi ini dan susukanlah dia bagiku, maka aku akan memberi upah kepadamu.\" Kemudian perempuan itu mengambil bayi itu dan menyusuinya.', NULL),
(42963, 3648, 2, 10, 'Ketika anak itu telah besar, dibawanyalah kepada puteri Firaun, yang mengangkatnya menjadi anaknya, dan menamainya Musa, sebab katanya: \"Karena aku telah menariknya dari air.\"', NULL),
(42964, 3648, 2, 11, 'Pada waktu itu, ketika Musa telah dewasa, ia keluar mendapatkan saudara-saudaranya untuk melihat kerja paksa mereka; lalu dilihatnyalah seorang Mesir memukul seorang Ibrani, seorang dari saudara-saudaranya itu.', 'Musa membela bangsanya Ia lari ke tanah Midian'),
(42965, 3648, 2, 12, 'Ia menoleh ke sana sini dan ketika dilihatnya tidak ada orang, dibunuhnya orang Mesir itu, dan disembunyikannya mayatnya dalam pasir.', NULL),
(42966, 3648, 2, 13, 'Ketika keesokan harinya ia keluar lagi, didapatinya dua orang Ibrani tengah berkelahi. Ia bertanya kepada yang bersalah itu: \"Mengapa engkau pukul temanmu?\"', NULL),
(42967, 3648, 2, 14, 'Tetapi jawabnya: \"Siapakah yang mengangkat engkau menjadi pemimpin dan hakim atas kami? Apakah engkau bermaksud membunuh aku, sama seperti engkau telah membunuh orang Mesir itu?\" Musa menjadi takut, sebab pikirnya: \"Tentulah perkara itu telah ketahuan.\"', NULL),
(42968, 3648, 2, 15, 'Ketika Firaun mendengar tentang perkara itu, dicarinya ikhtiar untuk membunuh Musa. Tetapi Musa melarikan diri dari hadapan Firaun dan tiba di tanah Midian, lalu ia duduk-duduk di tepi sebuah sumur.', NULL),
(42969, 3648, 2, 16, 'Adapun imam di Midian itu mempunyai tujuh anak perempuan. Mereka datang menimba air dan mengisi palungan-palungan untuk memberi minum kambing domba ayahnya.', NULL),
(42970, 3648, 2, 17, 'Maka datanglah gembala-gembala yang mengusir mereka, lalu Musa bangkit menolong mereka dan memberi minum kambing domba mereka.', NULL),
(42971, 3648, 2, 18, 'Ketika mereka sampai kepada Rehuel, ayah mereka, berkatalah ia: \"Mengapa selekas itu kamu pulang hari ini?\"', NULL),
(42972, 3648, 2, 19, 'Jawab mereka: \"Seorang Mesir menolong kami terhadap gembala-gembala, bahkan ia menimba air banyak-banyak untuk kami dan memberi minum kambing domba.\"', NULL),
(42973, 3648, 2, 20, 'Ia berkata kepada anak-anaknya: \"Di manakah ia? Mengapakah kamu tinggalkan orang itu? Panggillah dia makan.\"', NULL),
(42974, 3648, 2, 21, 'Musa bersedia tinggal di rumah itu, lalu diberikan Rehuellah Zipora, anaknya, kepada Musa.', NULL),
(42975, 3648, 2, 22, 'Perempuan itu melahirkan seorang anak laki-laki, maka Musa menamainya Gersom, sebab katanya: \"Aku telah menjadi seorang pendatang di negeri asing.\"', NULL),
(42976, 3648, 2, 23, 'Lama sesudah itu matilah raja Mesir. Tetapi orang Israel masih mengeluh karena perbudakan, dan mereka berseru-seru, sehingga teriak mereka minta tolong karena perbudakan itu sampai kepada Allah.', 'Musa diutus TUHAN'),
(42977, 3648, 2, 24, 'Allah mendengar mereka mengerang, lalu Ia mengingat kepada perjanjian-Nya dengan Abraham, Ishak dan Yakub.', NULL),
(42978, 3648, 2, 25, 'Maka Allah melihat orang Israel itu, dan Allah memperhatikan mereka.', NULL),
(46141, 3648, 3, 1, 'Adapun Musa, ia biasa menggembalakan kambing domba Yitro, mertuanya, imam di Midian. Sekali, ketika ia menggiring kambing domba itu ke seberang padang gurun, sampailah ia ke gunung Allah, yakni gunung Horeb.', NULL),
(46142, 3648, 3, 2, 'Lalu Malaikat TUHAN menampakkan diri kepadanya di dalam nyala api yang keluar dari semak duri. Lalu ia melihat, dan tampaklah: semak duri itu menyala, tetapi tidak dimakan api.', NULL),
(46143, 3648, 3, 3, 'Musa berkata: \"Baiklah aku menyimpang ke sana untuk memeriksa penglihatan yang hebat itu. Mengapakah tidak terbakar semak duri itu?\"', NULL),
(46144, 3648, 3, 4, 'Ketika dilihat TUHAN, bahwa Musa menyimpang untuk memeriksanya, berserulah Allah dari tengah-tengah semak duri itu kepadanya: \"Musa, Musa!\" dan ia menjawab: \"Ya, Allah.\"', NULL),
(46145, 3648, 3, 5, 'Lalu Ia berfirman: \"Janganlah datang dekat-dekat: tanggalkanlah kasutmu dari kakimu, sebab tempat, di mana engkau berdiri itu, adalah tanah yang kudus.\"', NULL),
(46146, 3648, 3, 6, 'Lagi Ia berfirman: \"Akulah Allah ayahmu, Allah Abraham, Allah Ishak dan Allah Yakub.\" Lalu Musa menutupi mukanya, sebab ia takut memandang Allah.', NULL),
(46147, 3648, 3, 7, 'Dan TUHAN berfirman: \"Aku telah memperhatikan dengan sungguh kesengsaraan umat-Ku di tanah Mesir, dan Aku telah mendengar seruan mereka yang disebabkan oleh pengerah-pengerah mereka, ya, Aku mengetahui penderitaan mereka.', NULL),
(46148, 3648, 3, 8, 'Sebab itu Aku telah turun untuk melepaskan mereka dari tangan orang Mesir dan menuntun mereka keluar dari negeri itu ke suatu negeri yang baik dan luas, suatu negeri yang berlimpah-limpah susu dan madunya, ke tempat orang Kanaan, orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus.', NULL),
(46149, 3648, 3, 9, 'Sekarang seruan orang Israel telah sampai kepada-Ku; juga telah Kulihat, betapa kerasnya orang Mesir menindas mereka.', NULL),
(46150, 3648, 3, 10, 'Jadi sekarang, pergilah, Aku mengutus engkau kepada Firaun untuk membawa umat-Ku, orang Israel, keluar dari Mesir.\"', NULL),
(46151, 3648, 3, 11, 'Tetapi Musa berkata kepada Allah: \"Siapakah aku ini, maka aku yang akan menghadap Firaun dan membawa orang Israel keluar dari Mesir?\"', NULL),
(46152, 3648, 3, 12, 'Lalu firman-Nya: \"Bukankah Aku akan menyertai engkau? Inilah tanda bagimu, bahwa Aku yang mengutus engkau: apabila engkau telah membawa bangsa itu keluar dari Mesir, maka kamu akan beribadah kepada Allah di gunung ini.\"', NULL),
(46153, 3648, 3, 13, 'Lalu Musa berkata kepada Allah: \"Tetapi apabila aku mendapatkan orang Israel dan berkata kepada mereka: Allah nenek moyangmu telah mengutus aku kepadamu, dan mereka bertanya kepadaku: bagaimana tentang nama-Nya? --apakah yang harus kujawab kepada mereka?\"', NULL),
(46154, 3648, 3, 14, 'Firman Allah kepada Musa: \"AKU ADALAH AKU.\" Lagi firman-Nya: \"Beginilah kaukatakan kepada orang Israel itu: AKULAH AKU telah mengutus aku kepadamu.\"', NULL),
(46155, 3648, 3, 15, 'Selanjutnya berfirmanlah Allah kepada Musa: \"Beginilah kaukatakan kepada orang Israel: TUHAN, Allah nenek moyangmu, Allah Abraham, Allah Ishak dan Allah Yakub, telah mengutus aku kepadamu: itulah nama-Ku untuk selama-lamanya dan itulah sebutan-Ku turun-temurun.', NULL),
(46156, 3648, 3, 16, 'Pergilah, kumpulkanlah para tua-tua Israel dan katakanlah kepada mereka: TUHAN, Allah nenek moyangmu, Allah Abraham, Ishak dan Yakub, telah menampakkan diri kepadaku, serta berfirman: Aku sudah mengindahkan kamu, juga apa yang dilakukan kepadamu di Mesir.', NULL),
(46157, 3648, 3, 17, 'Jadi Aku telah berfirman: Aku akan menuntun kamu keluar dari kesengsaraan di Mesir menuju ke negeri orang Kanaan, orang Het, orang Amori, orang Feris, orang Hewi dan orang Yebus, ke suatu negeri yang berlimpah-limpah susu dan madunya.', NULL),
(46158, 3648, 3, 18, 'Dan bilamana mereka mendengarkan perkataanmu, maka engkau harus beserta para tua-tua Israel pergi kepada raja Mesir, dan kamu harus berkata kepadanya: TUHAN, Allah orang Ibrani, telah menemui kami; oleh sebab itu, izinkanlah kiranya kami pergi ke padang gurun tiga hari perjalanan jauhnya untuk mempersembahkan korban kepada TUHAN, Allah kami.', NULL),
(46159, 3648, 3, 19, 'Tetapi Aku tahu, bahwa raja Mesir tidak akan membiarkan kamu pergi, kecuali dipaksa oleh tangan yang kuat.', NULL),
(46160, 3648, 3, 20, 'Tetapi Aku akan mengacungkan tangan-Ku dan memukul Mesir dengan segala perbuatan yang ajaib, yang akan Kulakukan di tengah-tengahnya; sesudah itu ia akan membiarkan kamu pergi.', NULL),
(46161, 3648, 3, 21, 'Dan Aku akan membuat orang Mesir bermurah hati terhadap bangsa ini, sehingga, apabila kamu pergi, kamu tidak pergi dengan tangan hampa,', NULL),
(46162, 3648, 3, 22, 'tetapi tiap-tiap perempuan harus meminta dari tetangganya dan dari perempuan yang tinggal di rumahnya, barang-barang perak dan emas dan kain-kain, yang akan kamu kenakan kepada anak-anakmu lelaki dan perempuan; demikianlah kamu akan merampasi orang Mesir itu.\"', NULL),
(46163, 3648, 4, 1, 'Lalu sahut Musa: \"Bagaimana jika mereka tidak percaya kepadaku dan tidak mendengarkan perkataanku, melainkan berkata: TUHAN tidak menampakkan diri kepadamu?\"', NULL),
(46164, 3648, 4, 2, 'TUHAN berfirman kepadanya: \"Apakah yang di tanganmu itu?\" Jawab Musa: \"Tongkat.\"', NULL),
(46165, 3648, 4, 3, 'Firman TUHAN: \"Lemparkanlah itu ke tanah.\" Dan ketika dilemparkannya ke tanah, maka tongkat itu menjadi ular, sehingga Musa lari meninggalkannya.', NULL),
(46166, 3648, 4, 4, 'Tetapi firman TUHAN kepada Musa: \"Ulurkanlah tanganmu dan peganglah ekornya\" --Musa mengulurkan tangannya, ditangkapnya ular itu, lalu menjadi tongkat di tangannya', NULL),
(46167, 3648, 4, 5, '--\"supaya mereka percaya, bahwa TUHAN, Allah nenek moyang mereka, Allah Abraham, Allah Ishak dan Allah Yakub telah menampakkan diri kepadamu.\"', NULL),
(46168, 3648, 4, 6, 'Lagi firman TUHAN kepadanya: \"Masukkanlah tanganmu ke dalam bajumu.\" Dimasukkannya tangannya ke dalam bajunya, dan setelah ditariknya ke luar, maka tangannya kena kusta, putih seperti salju.', NULL),
(46169, 3648, 4, 7, 'Sesudah itu firman-Nya: \"Masukkanlah tanganmu kembali ke dalam bajumu.\" Musa memasukkan tangannya kembali ke dalam bajunya dan setelah ditariknya ke luar, maka tangan itu pulih kembali seperti seluruh badannya.', NULL),
(46170, 3648, 4, 8, '\"Jika mereka tidak percaya kepadamu dan tidak mengindahkan tanda mujizat yang pertama, maka mereka akan percaya kepada tanda mujizat yang kedua.', NULL),
(46171, 3648, 4, 9, 'Dan jika mereka tidak juga percaya kepada kedua tanda mujizat ini dan tidak mendengarkan perkataanmu, maka engkau harus mengambil air dari sungai Nil dan harus kaucurahkan di tanah yang kering, lalu air yang kauambil itu akan menjadi darah di tanah yang kering itu.\"', NULL),
(46172, 3648, 4, 10, 'Lalu kata Musa kepada TUHAN: \"Ah, Tuhan, aku ini tidak pandai bicara, dahulupun tidak dan sejak Engkau berfirman kepada hamba-Mupun tidak, sebab aku berat mulut dan berat lidah.\"', NULL),
(46173, 3648, 4, 11, 'Tetapi TUHAN berfirman kepadanya: \"Siapakah yang membuat lidah manusia, siapakah yang membuat orang bisu atau tuli, membuat orang melihat atau buta; bukankah Aku, yakni TUHAN?', NULL),
(46174, 3648, 4, 12, 'Oleh sebab itu, pergilah, Aku akan menyertai lidahmu dan mengajar engkau, apa yang harus kaukatakan.\"', NULL),
(46175, 3648, 4, 13, 'Tetapi Musa berkata: \"Ah, Tuhan, utuslah kiranya siapa saja yang patut Kauutus.\"', NULL),
(46176, 3648, 4, 14, 'Maka bangkitlah murka TUHAN terhadap Musa dan Ia berfirman: \"Bukankah di situ Harun, orang Lewi itu, kakakmu? Aku tahu, bahwa ia pandai bicara; lagipula ia telah berangkat menjumpai engkau, dan apabila ia melihat engkau, ia akan bersukacita dalam hatinya.', NULL),
(46177, 3648, 4, 15, 'Maka engkau harus berbicara kepadanya dan menaruh perkataan itu ke dalam mulutnya; Aku akan menyertai lidahmu dan lidahnya dan mengajarkan kepada kamu apa yang harus kamu lakukan.', NULL),
(46178, 3648, 4, 16, 'Ia harus berbicara bagimu kepada bangsa itu, dengan demikian ia akan menjadi penyambung lidahmu dan engkau akan menjadi seperti Allah baginya.', NULL),
(46179, 3648, 4, 17, 'Dan bawalah tongkat ini di tanganmu, yang harus kaupakai untuk membuat tanda-tanda mujizat.\"', NULL),
(46180, 3648, 4, 18, 'Lalu Musa kembali kepada mertuanya Yitro serta berkata kepadanya: \"Izinkanlah kiranya aku kembali kepada saudara-saudaraku, yang ada di Mesir, untuk melihat apakah mereka masih hidup.\" Yitro berkata kepada Musa: \"Pergilah dengan selamat.\"', 'Musa kembali ke Mesir'),
(46181, 3648, 4, 19, 'Adapun TUHAN sudah berfirman kepada Musa di Midian: \"Kembalilah ke Mesir, sebab semua orang yang ingin mencabut nyawamu telah mati.\"', NULL),
(46182, 3648, 4, 20, 'Kemudian Musa mengajak isteri dan anak-anaknya lelaki, lalu menaikkan mereka ke atas keledai dan ia kembali ke tanah Mesir; dan tongkat Allah itu dipegangnya di tangannya.', NULL),
(46183, 3648, 4, 21, 'Firman TUHAN kepada Musa: \"Pada waktu engkau hendak kembali ini ke Mesir, ingatlah, supaya segala mujizat yang telah Kuserahkan ke dalam tanganmu, kauperbuat di depan Firaun. Tetapi Aku akan mengeraskan hatinya, sehingga ia tidak membiarkan bangsa itu pergi.', NULL),
(46184, 3648, 4, 22, 'Maka engkau harus berkata kepada Firaun: Beginilah firman TUHAN: Israel ialah anak-Ku, anak-Ku yang sulung;', NULL),
(46185, 3648, 4, 23, 'sebab itu Aku berfirman kepadamu: Biarkanlah anak-Ku itu pergi, supaya ia beribadah kepada-Ku; tetapi jika engkau menolak membiarkannya pergi, maka Aku akan membunuh anakmu, anakmu yang sulung.\"', NULL),
(46186, 3648, 4, 24, 'Tetapi di tengah jalan, di suatu tempat bermalam, TUHAN bertemu dengan Musa dan berikhtiar untuk membunuhnya.', NULL),
(46187, 3648, 4, 25, 'Lalu Zipora mengambil pisau batu, dipotongnya kulit khatan anaknya, kemudian disentuhnya dengan kulit itu kaki Musa sambil berkata: \"Sesungguhnya engkau pengantin darah bagiku.\"', NULL),
(46188, 3648, 4, 26, 'Lalu TUHAN membiarkan Musa. \"Pengantin darah,\" kata Zipora waktu itu, karena mengingat sunat itu.', NULL),
(46189, 3648, 4, 27, 'Berfirmanlah TUHAN kepada Harun: \"Pergilah ke padang gurun menjumpai Musa.\" Ia pergi dan bertemu dengan dia di gunung Allah, lalu menciumnya.', NULL),
(46190, 3648, 4, 28, 'Kemudian Musa memberitahukan kepada Harun segala firman TUHAN yang disuruhkan-Nya kepadanya untuk disampaikan dan segala tanda mujizat yang diperintahkan-Nya kepadanya untuk dibuat.', NULL),
(46191, 3648, 4, 29, 'Lalu pergilah Musa beserta Harun dan mereka mengumpulkan semua tua-tua Israel.', NULL),
(46192, 3648, 4, 30, 'Harun mengucapkan segala firman yang telah diucapkan TUHAN kepada Musa, serta membuat di depan bangsa itu tanda-tanda mujizat itu.', NULL),
(46193, 3648, 4, 31, 'Lalu percayalah bangsa itu, dan ketika mereka mendengar, bahwa TUHAN telah mengindahkan orang Israel dan telah melihat kesengsaraan mereka, maka berlututlah mereka dan sujud menyembah.', NULL),
(46194, 3648, 5, 1, 'Kemudian Musa dan Harun pergi menghadap Firaun, lalu berkata kepadanya: \"Beginilah firman TUHAN, Allah Israel: Biarkanlah umat-Ku pergi untuk mengadakan perayaan bagi-Ku di padang gurun.\"', NULL),
(46195, 3648, 5, 2, 'Tetapi Firaun berkata: \"Siapakah TUHAN itu yang harus kudengarkan firman-Nya untuk membiarkan orang Israel pergi? Tidak kenal aku TUHAN itu dan tidak juga aku akan membiarkan orang Israel pergi.\"', NULL),
(46196, 3648, 5, 3, 'Lalu kata mereka: \"Allah orang Ibrani telah menemui kami; izinkanlah kiranya kami pergi ke padang gurun tiga hari perjalanan jauhnya, untuk mempersembahkan korban kepada TUHAN, Allah kami, supaya jangan nanti mendatangkan kepada kami penyakit sampar atau pedang.\"', NULL),
(46197, 3648, 5, 4, 'Tetapi raja Mesir berkata kepada mereka: \"Musa dan Harun, mengapakah kamu bawa-bawa bangsa ini melalaikan pekerjaannya? Pergilah melakukan pekerjaanmu!\"', NULL),
(46198, 3648, 5, 5, 'Lagi kata Firaun: \"Lihat, sekarang telah terlalu banyak bangsamu di negeri ini, masakan kamu hendak menghentikan mereka dari kerja paksanya!\"', NULL),
(46199, 3648, 5, 6, 'Pada hari itu juga Firaun memerintahkan kepada pengerah-pengerah bangsa itu dan kepada mandur-mandur mereka sendiri:', NULL),
(46200, 3648, 5, 7, '\"Tidak boleh lagi kamu memberikan jerami kepada bangsa itu untuk membuat batu bata, seperti sampai sekarang; biarlah mereka sendiri yang pergi mengumpulkan jerami,', NULL),
(46201, 3648, 5, 8, 'tetapi jumlah batu bata, yang harus dibuat mereka sampai sekarang, bebankanlah itu juga kepada mereka dan jangan menguranginya, karena mereka pemalas. Itulah sebabnya mereka berteriak-teriak: Izinkanlah kami pergi mempersembahkan korban kepada Allah kami.', NULL),
(46202, 3648, 5, 9, 'Pekerjaan orang-orang ini harus diperberat, sehingga mereka terikat kepada pekerjaannya dan jangan mempedulikan perkataan dusta.\"', NULL),
(46203, 3648, 5, 10, 'Maka para pengerah bangsa itu dan para mandurnya pergi dan berkata kepada mereka: \"Beginilah kata Firaun: Aku tidak memberi jerami lagi kepadamu.', NULL),
(46204, 3648, 5, 11, 'Pergilah kamu sendiri mengambil jerami, di mana saja kamu mendapatnya, tetapi pekerjaanmu sedikitpun tidak boleh kurang.\"', NULL),
(46205, 3648, 5, 12, 'Lalu berseraklah bangsa itu ke seluruh tanah Mesir untuk mengumpulkan tunggul gandum sebagai pengganti jerami.', NULL),
(46206, 3648, 5, 13, 'Dan pengerah-pengerah itu mendesak mereka dengan berkata: \"Selesaikan pekerjaanmu, yaitu tugas sehari, seperti pada waktu ada jerami.\"', NULL),
(46207, 3648, 5, 14, 'Lalu pengerah-pengerah Firaun memukul mandur-mandur Israel, yang mereka angkat, sambil bertanya: \"Mengapakah kamu pada hari ini tidak menyelesaikan jumlah batu bata yang harus kamu buat seperti kemarin?\"', NULL),
(46208, 3648, 5, 15, 'Sesudah itu pergilah para mandur Israel kepada Firaun dan mengadukan halnya kepadanya: \"Mengapakah tuanku berlaku seperti itu terhadap hamba-hambamu ini?', NULL),
(46209, 3648, 5, 16, 'Jerami tidak diberikan lagi kepada hamba-hambamu ini tetapi walaupun begitu, kami diperintahkan: Buatlah batu bata. Dan dalam pada itu hamba-hambamu ini dipukuli, padahal rakyat tuankulah yang bersalah.\"', NULL),
(46210, 3648, 5, 17, 'Tetapi ia berkata: \"Pemalas kamu, pemalas! Itulah sebabnya kamu berkata: Izinkanlah kami pergi mempersembahkan korban kepada TUHAN!', NULL),
(46211, 3648, 5, 18, 'Jadi sekarang, pergilah, bekerja! Jerami tidak akan diberikan lagi kepadamu, tetapi jumlah batu bata yang sama harus kamu serahkan.\"', NULL),
(46212, 3648, 5, 19, 'Maka mengertilah para mandur Israel, bahwa mereka ada dalam keadaan susah, karena dikatakan kepada mereka: \"Kamu tidak boleh mengurangi jumlah batu bata pada tiap-tiap hari.\"', NULL),
(46213, 3648, 5, 20, 'Waktu mereka meninggalkan Firaun berjumpalah mereka dengan Musa dan Harun, yang sedang menantikan mereka,', NULL),
(46214, 3648, 5, 21, 'lalu mereka berkata kepada keduanya: \"Kiranya TUHAN memperhatikan perbuatanmu dan menghukumkan kamu, karena kamu telah membusukkan nama kami kepada Firaun dan hamba-hambanya dan dengan demikian kamu telah memberikan pisau kepada mereka untuk membunuh kami.\"', NULL),
(46215, 3648, 5, 22, 'Lalu Musa kembali menghadap TUHAN, katanya: \"Tuhan, mengapakah Kauperlakukan umat ini begitu bengis? Mengapa pula aku yang Kauutus?', NULL),
(46216, 3648, 5, 23, 'Sebab sejak aku pergi menghadap Firaun untuk berbicara atas nama-Mu, dengan jahat diperlakukannya umat ini, dan Engkau tidak melepaskan umat-Mu sama sekali.\"', NULL),
(46217, 3648, 6, 1, '(5-24) Tetapi TUHAN berfirman kepada Musa: \"Sekarang engkau akan melihat, apa yang akan Kulakukan kepada Firaun; sebab dipaksa oleh tangan yang kuat ia akan membiarkan mereka pergi, ya dipaksa oleh tangan yang kuat ia akan mengusir mereka dari negerinya.\"', NULL),
(46218, 3648, 6, 2, '(6-1) Selanjutnya berfirmanlah Allah kepada Musa: \"Akulah TUHAN.', 'Pengutusan Musa'),
(46219, 3648, 6, 3, '(6-2) Aku telah menampakkan diri kepada Abraham, Ishak dan Yakub sebagai Allah Yang Mahakuasa, tetapi dengan nama-Ku TUHAN Aku belum menyatakan diri.', NULL),
(46220, 3648, 6, 4, '(6-3) Bukan saja Aku telah mengadakan perjanjian-Ku dengan mereka untuk memberikan kepada mereka tanah Kanaan, tempat mereka tinggal sebagai orang asing,', NULL),
(46221, 3648, 6, 5, '(6-4) tetapi Aku sudah mendengar juga erang orang Israel yang telah diperbudak oleh orang Mesir, dan Aku ingat kepada perjanjian-Ku.', NULL),
(46222, 3648, 6, 6, '(6-5) Sebab itu katakanlah kepada orang Israel: Akulah TUHAN, Aku akan membebaskan kamu dari kerja paksa orang Mesir, melepaskan kamu dari perbudakan mereka dan menebus kamu dengan tangan yang teracung dan dengan hukuman-hukuman yang berat.', NULL),
(46223, 3648, 6, 7, '(6-6) Aku akan mengangkat kamu menjadi umat-Ku dan Aku akan menjadi Allahmu, supaya kamu mengetahui, bahwa Akulah, TUHAN, Allahmu, yang membebaskan kamu dari kerja paksa orang Mesir.', NULL),
(46224, 3648, 6, 8, '(6-7) Dan Aku akan membawa kamu ke negeri yang dengan sumpah telah Kujanjikan memberikannya kepada Abraham, Ishak dan Yakub, dan Aku akan memberikannya kepadamu untuk menjadi milikmu; Akulah TUHAN.\"', NULL),
(46225, 3648, 6, 9, '(6-8) Lalu Musa mengatakan demikian kepada orang Israel, tetapi mereka tidak mendengarkan Musa karena mereka putus asa dan karena perbudakan yang berat itu.', NULL),
(46226, 3648, 6, 10, '(6-9) Kemudian TUHAN berfirman kepada Musa:', NULL),
(46227, 3648, 6, 11, '(6-10) \"Pergilah menghadap, katakanlah kepada Firaun, raja Mesir, bahwa ia harus membiarkan orang Israel pergi dari negerinya.\"', NULL),
(46228, 3648, 6, 12, '(6-11) Tetapi Musa berkata di hadapan TUHAN: \"Orang Israel sendiri tidak mendengarkan aku, bagaimanakah mungkin Firaun akan mendengarkan aku, aku seorang yang tidak petah lidahnya!\"', NULL),
(46229, 3648, 6, 13, '(6-12) Demikianlah TUHAN telah berfirman kepada Musa dan Harun, serta mengutus mereka kepada orang Israel dan kepada Firaun, raja Mesir, dengan membawa perintah supaya orang Israel dibawa keluar dari Mesir.', NULL),
(46230, 3648, 6, 14, '(6-13) Inilah para kepala kaum keluarga mereka: Anak-anak Ruben anak sulung Israel: Henokh, Palu, Hezron dan Karmi; itulah kaum-kaum Ruben.', 'Nenek moyang Musa dan Harun'),
(46231, 3648, 6, 15, '(6-14) Anak-anak Simeon: Yemuel, Yamin, Ohad, Yakhin, Zohar, dan Saul, anak seorang perempuan Kanaan; itulah kaum-kaum Simeon.', NULL),
(46232, 3648, 6, 16, '(6-15) Inilah nama anak-anak Lewi menurut urutan kelahirannya: Gerson, Kehat dan Merari. Umur Lewi seratus tiga puluh tujuh tahun.', NULL),
(46233, 3648, 6, 17, '(6-16) Anak-anak Gerson: Libni dan Simei, menurut kaum mereka.', NULL),
(46234, 3648, 6, 18, '(6-17) Anak-anak Kehat: Amram, Yizhar, Hebron dan Uziel. Umur Kehat seratus tiga puluh tiga tahun.', NULL),
(46235, 3648, 6, 19, '(6-18) Anak-anak Merari: Mahli dan Musi. Itulah kaum-kaum Lewi menurut urutannya.', NULL),
(46236, 3648, 6, 20, '(6-19) Dan Amram mengambil Yokhebed, saudara ayahnya, menjadi isterinya, dan perempuan ini melahirkan Harun dan Musa baginya. Umur Amram seratus tiga puluh tujuh tahun.', NULL),
(46237, 3648, 6, 21, '(6-20) Anak-anak Yizhar: Korah, Nefeg dan Zikhri.', NULL),
(46238, 3648, 6, 22, '(6-21) Anak-anak Uziel: Misael, Elsafan dan Sitri.', NULL),
(46239, 3648, 6, 23, '(6-22) Dan Harun mengambil Eliseba, anak perempuan Aminadab, saudara perempuan Nahason, menjadi isterinya, dan perempuan ini melahirkan baginya Nadab, Abihu, Eleazar dan Itamar.', NULL),
(46240, 3648, 6, 24, '(6-23) Anak-anak Korah: Asir, Elkana dan Abiasaf; itulah kaum-kaum orang Korah.', NULL),
(46241, 3648, 6, 25, '(6-24) Eleazar, anak Harun, mengambil salah seorang anak perempuan Putiel menjadi isterinya dan perempuan ini melahirkan Pinehas baginya. Itulah para kepala kaum keluarga orang Lewi menurut kaum mereka.', NULL),
(46242, 3648, 6, 26, '(6-25) Itulah Harun dan Musa, yang diperintahkan TUHAN: \"Bawalah orang Israel keluar dari tanah Mesir menurut pasukan mereka.\"', NULL),
(46243, 3648, 6, 27, '(6-26) Merekalah yang berbicara kepada Firaun, raja Mesir, supaya mereka membawa orang Israel keluar dari Mesir. Itulah Musa dan Harun.', NULL),
(46244, 3648, 6, 28, '(6-27) Pada waktu TUHAN berfirman kepada Musa di tanah Mesir,', 'Musa menghadap Firaun'),
(46245, 3648, 6, 29, '(6-28) TUHAN berfirman kepadanya: \"Akulah TUHAN; katakanlah kepada Firaun, raja Mesir, segala yang Kufirmankan kepadamu.\"', NULL),
(46246, 3648, 6, 30, '(6-29) Tetapi Musa berkata di hadapan TUHAN: \"Bukankah aku ini seorang yang tidak petah lidahnya, bagaimanakah mungkin Firaun akan mendengarkan aku?\"', NULL),
(47934, 3648, 7, 1, 'Berfirmanlah TUHAN kepada Musa: \"Lihat, Aku mengangkat engkau sebagai Allah bagi Firaun, dan Harun, abangmu, akan menjadi nabimu.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(47935, 3648, 7, 2, 'Engkau harus mengatakan segala yang Kuperintahkan kepadamu, dan Harun, abangmu, harus berbicara kepada Firaun, supaya dibiarkannya orang Israel itu pergi dari negerinya.', NULL),
(47936, 3648, 7, 3, 'Tetapi Aku akan mengeraskan hati Firaun, dan Aku akan memperbanyak tanda-tanda dan mujizat-mujizat yang Kubuat di tanah Mesir.', NULL),
(47937, 3648, 7, 4, 'Bilamana Firaun tidak mendengarkan kamu, maka Aku akan mendatangkan tangan-Ku kepada Mesir dan mengeluarkan pasukan-Ku, umat-Ku, orang Israel, dari tanah Mesir dengan hukuman-hukuman yang berat.', NULL),
(47938, 3648, 7, 5, 'Dan orang Mesir itu akan mengetahui, bahwa Akulah TUHAN, apabila Aku mengacungkan tangan-Ku terhadap Mesir dan membawa orang Israel keluar dari tengah-tengah mereka.\"', NULL),
(47939, 3648, 7, 6, 'Demikianlah diperbuat Musa dan Harun; seperti yang diperintahkan TUHAN kepada mereka, demikianlah diperbuat mereka.', NULL),
(47940, 3648, 7, 7, 'Adapun Musa delapan puluh tahun umurnya dan Harun delapan puluh tiga tahun, ketika mereka berbicara kepada Firaun.', NULL),
(47941, 3648, 7, 8, 'Dan TUHAN berfirman kepada Musa dan Harun:', NULL),
(47942, 3648, 7, 9, '\"Apabila Firaun berkata kepada kamu: Tunjukkanlah suatu mujizat, maka haruslah kaukatakan kepada Harun: Ambillah tongkatmu dan lemparkanlah itu di depan Firaun. Maka tongkat itu akan menjadi ular.\"', NULL),
(47943, 3648, 7, 10, 'Musa dan Harun pergi menghadap Firaun, lalu mereka berbuat seperti yang diperintahkan TUHAN; Harun melemparkan tongkatnya di depan Firaun dan para pegawainya, maka tongkat itu menjadi ular.', NULL),
(47944, 3648, 7, 11, 'Kemudian Firaunpun memanggil orang-orang berilmu dan ahli-ahli sihir; dan merekapun, ahli-ahli Mesir itu, membuat yang demikian juga dengan ilmu mantera mereka.', NULL),
(47945, 3648, 7, 12, 'Masing-masing mereka melemparkan tongkatnya, dan tongkat-tongkat itu menjadi ular; tetapi tongkat Harun menelan tongkat-tongkat mereka.', NULL),
(47946, 3648, 7, 13, 'Tetapi hati Firaun berkeras, sehingga tidak mau mendengarkan mereka keduanya--seperti yang telah difirmankan TUHAN.', NULL),
(47947, 3648, 7, 14, 'Berfirmanlah TUHAN kepada Musa: \"Firaun berkeras hati, ia menolak membiarkan bangsa itu pergi.', 'Tulah pertama: air menjadi darah'),
(47948, 3648, 7, 15, 'Pergilah kepada Firaun pada waktu pagi, pada waktu biasanya ia keluar ke sungai; nantikanlah dia di tepi sungai Nil dengan memegang di tanganmu tongkat yang tadinya berubah menjadi ular.', NULL),
(47949, 3648, 7, 16, 'Dan katakanlah kepadanya: TUHAN, Allah orang Ibrani, telah mengutus aku kepadamu untuk mengatakan: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku di padang gurun; meskipun begitu sampai sekarang engkau tidak mau mendengarkan.', NULL),
(47950, 3648, 7, 17, 'Sebab itu beginilah firman TUHAN: Dari hal yang berikut akan kauketahui, bahwa Akulah TUHAN. Lihat, dengan tongkat yang di tanganku ini akan kupukul air yang di sungai Nil dan air itu akan berubah menjadi darah,', NULL),
(47951, 3648, 7, 18, 'dan ikan yang dalam sungai Nil akan mati, sehingga sungai Nil akan berbau busuk; maka orang Mesir akan segan meminum air dari sungai Nil ini.\"', NULL),
(47952, 3648, 7, 19, 'TUHAN berfirman kepada Musa: \"Katakanlah kepada Harun: Ambillah tongkatmu, ulurkanlah tanganmu ke atas segala air orang Mesir, ke atas sungai, selokan, kolam dan ke atas segala kumpulan air yang ada pada mereka, supaya semuanya menjadi darah, dan akan ada darah di seluruh tanah Mesir, bahkan dalam wadah kayu dan wadah batu.\"', NULL),
(47953, 3648, 7, 20, 'Demikianlah Musa dan Harun berbuat seperti yang difirmankan TUHAN; diangkatnya tongkat itu dan dipukulkannya kepada air yang di sungai Nil, di depan mata Firaun dan pegawai-pegawainya, maka seluruh air yang di sungai Nil berubah menjadi darah;', NULL),
(47954, 3648, 7, 21, 'matilah ikan di sungai Nil, sehingga sungai Nil itu berbau busuk dan orang Mesir tidak dapat meminum air dari sungai Nil; dan di seluruh tanah Mesir ada darah.', NULL),
(47955, 3648, 7, 22, 'Tetapi para ahli Mesir membuat yang demikian juga dengan ilmu-ilmu mantera mereka, sehingga hati Firaun berkeras dan ia tidak mau mendengarkan mereka keduanya seperti yang telah difirmankan TUHAN.', NULL),
(47956, 3648, 7, 23, 'Firaun berpaling, lalu masuk ke istananya dan tidak mau memperhatikan hal itu juga.', NULL),
(47957, 3648, 7, 24, 'Tetapi semua orang Mesir menggali-gali di sekitar sungai Nil mencari air untuk diminum, sebab mereka tidak dapat meminum air sungai Nil.', NULL),
(47958, 3648, 7, 25, 'Demikianlah genap tujuh hari berlalu setelah TUHAN menulahi sungai Nil.', NULL),
(47959, 3648, 8, 1, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah menghadap Firaun dan katakan kepadanya: Beginilah firman TUHAN: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku;', 'Tulah kedua: katak'),
(47960, 3648, 8, 2, 'jika engkau menolak membiarkannya pergi, maka Aku akan menulahi seluruh daerahmu dengan katak.', NULL),
(47961, 3648, 8, 3, 'Katak-katak akan mengeriap dalam sungai Nil, lalu naik dan masuk ke dalam istanamu dan kamar tidurmu, ya sampai ke dalam tempat tidurmu, ke dalam rumah pegawai-pegawaimu, dan rakyatmu, bahkan ke dalam pembakaran rotimu serta ke dalam tempat adonanmu.', NULL),
(47962, 3648, 8, 4, 'Katak-katak itu akan naik memanjati engkau, memanjati rakyatmu dan segala pegawaimu.\"', NULL),
(47963, 3648, 8, 5, 'Berfirmanlah TUHAN kepada Musa: \"Katakanlah kepada Harun: Ulurkanlah tanganmu dengan tongkatmu ke atas sungai, ke atas selokan dan ke atas kolam, dan buatlah katak-katak bermunculan meliputi tanah Mesir.\"', NULL),
(47964, 3648, 8, 6, 'Lalu Harun mengulurkan tangannya ke atas segala air di Mesir, maka bermunculanlah katak-katak, lalu menutupi tanah Mesir.', NULL),
(47965, 3648, 8, 7, 'Tetapi para ahli itupun membuat yang demikian juga dengan ilmu-ilmu mantera mereka, sehingga mereka membuat katak-katak bermunculan meliputi tanah Mesir.', NULL),
(47966, 3648, 8, 8, 'Kemudian Firaun memanggil Musa dan Harun serta berkata: \"Berdoalah kepada TUHAN, supaya dijauhkan-Nya katak-katak itu dari padaku dan dari pada rakyatku; maka aku akan membiarkan bangsa itu pergi, supaya mereka mempersembahkan korban kepada TUHAN.\"', NULL),
(47967, 3648, 8, 9, 'Kata Musa kepada Firaun: \"Silakanlah tuanku katakan kepadaku, bila aku akan berdoa untukmu, untuk pegawaimu dan rakyatmu, supaya katak-katak itu dilenyapkan dari padamu dan dari rumah-rumahmu, dan hanya tinggal di sungai Nil saja.\"', NULL),
(47968, 3648, 8, 10, 'Katanya: \"Besok.\" Lalu kata Musa: \"Jadilah seperti katamu itu, supaya tuanku mengetahui, bahwa tidak ada yang seperti TUHAN, Allah kami.', NULL),
(47969, 3648, 8, 11, 'Maka katak-katak itu akan dijauhkan dari padamu, dari rumah-rumahmu, dari pegawai-pegawaimu dan dari rakyatmu; dan hanya akan tinggal di sungai Nil saja.\"', NULL),
(47970, 3648, 8, 12, 'Lalu Musa dan Harun keluar meninggalkan Firaun, dan Musa berseru kepada TUHAN karena katak-katak, yang didatangkan-Nya kepada Firaun.', NULL),
(47971, 3648, 8, 13, 'Dan TUHAN melakukan seperti yang dikatakan Musa, sehingga katak-katak itu mati lenyap dari rumah, dari halaman dan dari ladang.', NULL),
(47972, 3648, 8, 14, 'Dikumpulkan oranglah bangkai-bangkainya bertumpuk-tumpuk, sehingga tanah itu berbau busuk.', NULL),
(47973, 3648, 8, 15, 'Tetapi ketika Firaun melihat, bahwa telah terasa kelegaan, ia tetap berkeras hati, dan tidak mau mendengarkan mereka keduanya--seperti yang telah difirmankan TUHAN.', NULL),
(47974, 3648, 8, 16, 'Berfirmanlah TUHAN kepada Musa: \"Katakanlah kepada Harun: Ulurkanlah tongkatmu dan pukulkanlah itu ke debu tanah, maka debu itu akan menjadi nyamuk di seluruh tanah Mesir.\"', 'Tulah ketiga: nyamuk'),
(47975, 3648, 8, 17, 'Lalu mereka berbuat demikian; Harun mengulurkan tangannya dengan tongkatnya dan memukulkannya ke debu tanah, maka nyamuk-nyamuk itu hinggap pada manusia dan pada binatang. Segala debu tanah menjadi nyamuk di seluruh tanah Mesir.', NULL),
(47976, 3648, 8, 18, 'Para ahli itupun membuat yang demikian juga dengan ilmu-ilmu manteranya untuk mengadakan nyamuk-nyamuk, tetapi mereka tidak dapat. Demikianlah nyamuk-nyamuk itu hinggap pada manusia dan pada binatang.', NULL),
(47977, 3648, 8, 19, 'Lalu berkatalah para ahli itu kepada Firaun: \"Inilah tangan Allah.\" Tetapi hati Firaun berkeras, dan ia tidak mau mendengarkan mereka--seperti yang telah difirmankan TUHAN.', NULL),
(47978, 3648, 8, 20, 'Berfirmanlah TUHAN kepada Musa: \"Bangunlah pagi-pagi dan berdirilah menantikan Firaun, pada waktu biasanya ia keluar ke sungai, dan katakanlah kepadanya: Beginilah firman TUHAN: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku;', 'Tulah keempat: lalat pikat'),
(47979, 3648, 8, 21, 'sebab jika engkau tidak membiarkan umat-Ku itu pergi, maka Aku akan melepaskan pikat terhadap engkau, terhadap pegawai-pegawaimu, rakyatmu dan rumah-rumahmu, sehingga rumah-rumah orang Mesir, bahkan tanah, di mana mereka berdiri akan penuh dengan pikat.', NULL),
(47980, 3648, 8, 22, 'Tetapi pada hari itu Aku akan mengecualikan tanah Gosyen, di mana umat-Ku tinggal, sehingga di sana tidak ada terdapat pikat, supaya engkau mengetahui, bahwa Aku, TUHAN, ada di negeri ini.', NULL),
(47981, 3648, 8, 23, 'Sebab Aku akan mengadakan perbedaan antara umat-Ku dan bangsamu. Besok tanda mujizat ini akan terjadi.\"', NULL),
(47982, 3648, 8, 24, 'TUHAN berbuat demikian; maka datanglah banyak-banyak pikat ke dalam istana Firaun dan ke dalam rumah pegawai-pegawainya dan ke seluruh tanah Mesir; negeri itu menderita karena pikat itu.', NULL),
(47983, 3648, 8, 25, 'Lalu Firaun memanggil Musa dan Harun serta berkata: \"Pergilah, persembahkanlah korban kepada Allahmu di negeri ini.\"', NULL),
(47984, 3648, 8, 26, 'Tetapi Musa berkata: \"Tidak mungkin kami berbuat demikian, sebab korban yang akan kami persembahkan kepada TUHAN, Allah kami, adalah kekejian bagi orang Mesir. Apabila kami mempersembahkan korban yang menjadi kekejian bagi orang Mesir itu, di depan mata mereka, tidakkah mereka akan melempari kami dengan batu?', NULL),
(47985, 3648, 8, 27, 'Kami harus pergi ke padang gurun tiga hari perjalanan jauhnya untuk mempersembahkan korban kepada TUHAN, Allah kami, seperti yang difirmankan-Nya kepada kami.\"', NULL),
(47986, 3648, 8, 28, 'Lalu kata Firaun: \"Baik, aku akan membiarkan kamu pergi untuk mempersembahkan korban kepada TUHAN, Allahmu, di padang gurun; hanya janganlah kamu pergi terlalu jauh. Berdoalah untuk aku.\"', NULL),
(47987, 3648, 8, 29, 'Lalu kata Musa: \"Sekarang aku keluar meninggalkan tuanku dan akan berdoa kepada TUHAN, maka pikat itu akan dijauhkan besok dari Firaun, dari pegawai-pegawainya dan rakyatnya; hanya janganlah Firaun berlaku curang lagi dengan tidak membiarkan bangsa itu pergi untuk mempersembahkan korban kepada TUHAN.\"', NULL),
(47988, 3648, 8, 30, 'Sesudah itu keluarlah Musa meninggalkan Firaun, lalu berdoa kepada TUHAN.', NULL),
(47989, 3648, 8, 31, 'Dan TUHAN membuat seperti yang dikatakan Musa: pikat itu dijauhkan-Nya dari Firaun, dari pegawai-pegawainya dan rakyatnya; seekorpun tidak ada yang tinggal.', NULL),
(47990, 3648, 8, 32, 'Tetapi sekali inipun Firaun tetap berkeras hati; ia tidak membiarkan bangsa itu pergi.', NULL),
(49735, 3648, 9, 1, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah menghadap Firaun dan berbicaralah kepadanya: Beginilah firman TUHAN, Allah orang Ibrani: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku.', 'Tulah kelima: penyakit sampar pada ternak'),
(49736, 3648, 9, 2, 'Sebab jika engkau menolak membiarkan mereka pergi dan masih menahan mereka,', NULL),
(49737, 3648, 9, 3, 'maka ternakmu, yang ada di padang, kuda, keledai, unta, lembu sapi dan kambing domba, akan kena tulah TUHAN, yakni kena penyakit sampar yang dahsyat.', NULL),
(49738, 3648, 9, 4, 'Dan TUHAN akan membuat perbedaan antara ternak orang Israel dan ternak orang Mesir, sehingga tidak ada yang akan mati seekorpun dari segala ternak orang Israel.\"', NULL),
(49739, 3648, 9, 5, 'Selanjutnya TUHAN menentukan waktunya, firman-Nya: \"Besoklah TUHAN akan melakukan hal itu di negeri ini.\"', NULL),
(49740, 3648, 9, 6, 'Dan TUHAN melakukan hal itu keesokan harinya; segala ternak orang Mesir itu mati, tetapi dari ternak orang Israel tidak ada seekorpun yang mati.', NULL),
(49741, 3648, 9, 7, 'Lalu Firaun menyuruh orang ke sana dan sesungguhnyalah dari ternak orang Israel tidak ada seekorpun yang mati. Tetapi Firaun tetap berkeras hati dan tidak mau membiarkan bangsa itu pergi.', NULL),
(49742, 3648, 9, 8, 'Berfirmanlah TUHAN kepada Musa dan Harun: \"Ambillah jelaga dari dapur peleburan serangkup penuh, dan Musa harus menghamburkannya ke udara di depan mata Firaun.', NULL),
(49743, 3648, 9, 9, 'Maka jelaga itu akan menjadi debu meliputi seluruh tanah Mesir, dan akan menjadikan barah yang memecah sebagai gelembung, pada manusia dan binatang di seluruh tanah Mesir.\"', 'Tulah keenam: barah'),
(49744, 3648, 9, 10, 'Lalu mereka mengambil jelaga dari dapur peleburan, dan berdiri di depan Firaun, kemudian Musa menghamburkannya ke udara, maka terjadilah barah, yang memecah sebagai gelembung pada manusia dan binatang,', NULL),
(49745, 3648, 9, 11, 'sehingga ahli-ahli itu tidak dapat tetap berdiri di depan Musa, karena barah-barah itu; sebab ahli-ahli itupun juga kena barah sama seperti semua orang Mesir.', NULL),
(49746, 3648, 9, 12, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga ia tidak mendengarkan mereka--seperti yang telah difirmankan TUHAN kepada Musa.', NULL),
(49747, 3648, 9, 13, 'Berfirmanlah TUHAN kepada Musa: \"Bangunlah pagi-pagi dan berdirilah menantikan Firaun dan katakan kepadanya: Beginilah firman TUHAN, Allah orang Ibrani: Biarkanlah umat-Ku pergi, supaya mereka beribadah kepada-Ku.', 'Tulah ketujuh: hujan es'),
(49748, 3648, 9, 14, 'Sebab sekali ini Aku akan melepaskan segala tulah-Ku terhadap engkau sendiri, terhadap pegawai-pegawaimu dan terhadap rakyatmu, dengan maksud supaya engkau mengetahui, bahwa tidak ada yang seperti Aku di seluruh bumi.', NULL),
(49749, 3648, 9, 15, 'Bukankah sudah lama Aku dapat mengacungkan tangan-Ku untuk membunuh engkau dan rakyatmu dengan penyakit sampar, sehingga engkau terhapus dari atas bumi;', NULL),
(49750, 3648, 9, 16, 'akan tetapi inilah sebabnya Aku membiarkan engkau hidup, yakni supaya memperlihatkan kepadamu kekuatan-Ku, dan supaya nama-Ku dimasyhurkan di seluruh bumi.', NULL),
(49751, 3648, 9, 17, 'Engkau masih selalu mengalangi umat-Ku, sehingga engkau tidak membiarkan mereka pergi.', NULL),
(49752, 3648, 9, 18, 'Sesungguhnya besok kira-kira waktu ini Aku akan menurunkan hujan es yang sangat dahsyat, seperti yang belum pernah terjadi di Mesir sejak Mesir dijadikan sampai sekarang ini.', NULL),
(49753, 3648, 9, 19, 'Oleh sebab itu, ternakmu dan segala yang kaupunyai di padang, suruhlah dibawa ke tempat yang aman; semua orang dan segala hewan, yang ada di padang dan tidak pulang berkumpul ke rumah, akan ditimpa oleh hujan es itu, sehingga mati.\"', NULL),
(49754, 3648, 9, 20, 'Maka siapa di antara para pegawai Firaun yang takut kepada firman TUHAN, menyuruh hamba-hambanya serta ternaknya lari ke rumah,', NULL),
(49755, 3648, 9, 21, 'tetapi siapa yang tidak mengindahkan firman TUHAN, meninggalkan hamba-hambanya serta ternaknya di padang.', NULL),
(49756, 3648, 9, 22, 'Berfirmanlah TUHAN kepada Musa: \"Ulurkanlah tanganmu ke langit, supaya hujan es turun di seluruh tanah Mesir, menimpa manusia dan binatang dan menimpa tumbuh-tumbuhan di padang di tanah Mesir.\"', NULL),
(49757, 3648, 9, 23, 'Lalu Musa mengulurkan tongkatnya ke langit, maka TUHAN mengadakan guruh dan hujan es, dan apipun menyambar ke bumi, dan TUHAN menurunkan hujan es meliputi tanah Mesir.', NULL),
(49758, 3648, 9, 24, 'Dan turunlah hujan es, beserta api yang berkilat-kilat di tengah-tengah hujan es itu, terlalu dahsyat, seperti yang belum pernah terjadi di seluruh negeri orang Mesir, sejak mereka menjadi suatu bangsa.', NULL),
(49759, 3648, 9, 25, 'Hujan es itu menimpa binasa segala sesuatu yang ada di padang, di seluruh tanah Mesir, dari manusia sampai binatang; juga segala tumbuh-tumbuhan di padang ditimpa binasa oleh hujan itu dan segala pohon di padang ditumbangkannya.', NULL),
(49760, 3648, 9, 26, 'Hanya di tanah Gosyen, tempat kediaman orang Israel, tidak ada turun hujan es.', NULL),
(49761, 3648, 9, 27, 'Lalu Firaun menyuruh memanggil Musa dan Harun serta berkata kepada mereka: \"Aku telah berdosa sekali ini, TUHAN itu yang benar, tetapi aku dan rakyatkulah yang bersalah.', NULL),
(49762, 3648, 9, 28, 'Berdoalah kepada TUHAN; guruh yang sangat dahsyat dan hujan es itu sudah cukup. Maka aku akan membiarkan kamu pergi, tidak usah kamu tinggal lebih lama lagi.\"', NULL),
(49763, 3648, 9, 29, 'Dan berkatalah Musa kepadanya: \"Sekeluar aku dari kota ini, aku akan mengembangkan tanganku kepada TUHAN; guruh akan berhenti dan hujan es tidak akan turun lagi, supaya engkau mengetahui, bahwa bumi adalah milik TUHAN.', NULL),
(49764, 3648, 9, 30, 'Tetapi tentang engkau dan para pegawaimu, aku tahu, bahwa kamu belum takut kepada TUHAN Allah.\"', NULL),
(49765, 3648, 9, 31, '--Tanaman rami dan jelai telah tertimpa binasa, sebab jelai itu sedang berbulir dan rami itu sedang berbunga.', NULL),
(49766, 3648, 9, 32, 'Tetapi gandum dan sekoi tidak tertimpa binasa, sebab belum lagi musimnya. --', NULL),
(49767, 3648, 9, 33, 'Lalu keluarlah Musa dari kota itu meninggalkan Firaun, dikembangkannyalah tangannya kepada TUHAN, maka berhentilah guruh dan hujan es dan hujan tidak tercurah lagi ke bumi.', NULL),
(49768, 3648, 9, 34, 'Tetapi ketika Firaun melihat, bahwa hujan, hujan es dan guruh telah berhenti, maka teruslah ia berbuat dosa; ia tetap berkeras hati, baik ia maupun para pegawainya.', NULL),
(49769, 3648, 9, 35, 'Berkeraslah hati Firaun, sehingga ia tidak membiarkan orang Israel pergi--seperti yang telah difirmankan TUHAN dengan perantaraan Musa.', NULL),
(49770, 3648, 10, 1, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah menghadap Firaun, sebab Aku telah membuat hatinya dan hati para pegawainya berkeras, supaya Aku mengadakan tanda-tanda mujizat yang Kubuat ini di antara mereka,', 'Tulah kedelapan: belalang'),
(49771, 3648, 10, 2, 'dan supaya engkau dapat menceriterakan kepada anak cucumu, bagaimana Aku mempermain-mainkan orang Mesir dan tanda-tanda mujizat mana yang telah Kulakukan di antara mereka, supaya kamu mengetahui, bahwa Akulah TUHAN.\"', NULL),
(49772, 3648, 10, 3, 'Lalu Musa dan Harun pergi menghadap Firaun dan berkata kepadanya: \"Beginilah firman TUHAN, Allah orang Ibrani: Berapa lama lagi engkau menolak untuk merendahkan dirimu di hadapan-Ku? Biarkanlah umat-Ku pergi supaya mereka beribadah kepada-Ku.', NULL),
(49773, 3648, 10, 4, 'Sebab jika engkau menolak membiarkan umat-Ku pergi, maka besok Aku akan mendatangkan belalang-belalang ke dalam daerahmu;', NULL),
(49774, 3648, 10, 5, 'belalang itu akan menutupi permukaan bumi, sehingga orang tidak dapat melihat tanah; belalang itu akan memakan habis sisa yang terluput, yang masih tinggal bagimu dari hujan es itu, bahkan akan memakan habis segala pohonmu yang tumbuh di padang.', NULL),
(49775, 3648, 10, 6, 'Belalang itu akan memenuhi rumahmu, rumah semua pegawaimu, rumah semua orang Mesir seperti yang belum pernah dilihat oleh bapamu dan nenek moyangmu, sejak mereka lahir ke bumi sampai hari ini.\" Lalu berpalinglah ia dan keluar meninggalkan Firaun.', NULL),
(49776, 3648, 10, 7, 'Sesudah itu berkatalah para pegawai Firaun kepadanya: \"Berapa lama lagi orang ini akan menjadi jerat kepada kita? Biarkanlah orang-orang itu pergi supaya mereka beribadah kepada TUHAN, Allah mereka. Belumkah tuanku insaf, bahwa Mesir pasti akan binasa?\"', NULL),
(49777, 3648, 10, 8, 'Lalu Musa dan Harun dibawalah kembali kepada Firaun dan berkatalah Firaun kepada mereka: \"Pergilah, beribadahlah kepada TUHAN, Allahmu. Siapa-siapa sebenarnya yang akan pergi itu?\"', NULL),
(49778, 3648, 10, 9, 'Jawab Musa: \"Kami hendak pergi dengan orang-orang yang muda dan yang tua; dengan anak-anak lelaki kami dan perempuan, dengan kambing domba kami dan lembu sapi kami, sebab kami harus mengadakan perayaan untuk TUHAN.\"', NULL),
(49779, 3648, 10, 10, 'Tetapi Firaun berkata kepada mereka: \"TUHAN boleh menyertai kamu, jika aku membiarkan kamu pergi dengan anak-anakmu! Lihat, jahatlah maksudmu!', NULL),
(49780, 3648, 10, 11, 'Bukan demikian, kamu boleh pergi, tetapi hanya laki-laki, dan beribadahlah kepada TUHAN, sebab itulah yang kamu kehendaki.\" Lalu mereka diusir dari depan Firaun.', NULL),
(49781, 3648, 10, 12, 'Berfirmanlah TUHAN kepada Musa: \"Ulurkanlah tanganmu ke atas tanah Mesir mendatangkan belalang dan belalang akan datang meliputi tanah Mesir dan memakan habis segala tumbuh-tumbuhan di tanah, semuanya yang ditinggalkan oleh hujan es itu.\"', NULL),
(49782, 3648, 10, 13, 'Lalu Musa mengulurkan tongkatnya ke atas tanah Mesir, dan TUHAN mendatangkan angin timur melintasi negeri itu, sehari-harian dan semalam-malaman, dan setelah hari pagi, angin timur membawa belalang.', NULL),
(49783, 3648, 10, 14, 'Datanglah belalang meliputi seluruh tanah Mesir dan hinggap di seluruh daerah Mesir, sangat banyak; sebelum itu tidak pernah ada belalang yang demikian banyaknya dan sesudah itupun tidak akan terjadi lagi yang demikian.', NULL),
(49784, 3648, 10, 15, 'Belalang menutupi seluruh permukaan bumi, sehingga negeri itu menjadi gelap olehnya; belalang memakan habis segala tumbuh-tumbuhan di tanah dan segala buah-buahan pada pohon-pohon yang ditinggalkan oleh hujan es itu, sehingga tidak ada tinggal lagi yang hijau pada pohon atau tumbuh-tumbuhan di padang di seluruh tanah Mesir.', NULL),
(49785, 3648, 10, 16, 'Maka segeralah Firaun memanggil Musa dan Harun serta berkata: \"Aku telah berbuat dosa terhadap TUHAN, Allahmu, dan terhadap kamu.', NULL),
(49786, 3648, 10, 17, 'Oleh sebab itu, ampunilah kiranya dosaku untuk sekali ini saja dan berdoalah kepada TUHAN, Allahmu itu, supaya bahaya maut ini dijauhkan-Nya dari padaku.\"', NULL),
(49787, 3648, 10, 18, 'Lalu keluarlah Musa meninggalkan Firaun dan berdoa kepada TUHAN.', NULL),
(49788, 3648, 10, 19, 'Maka TUHAN membuat angin bertiup dari jurusan sebaliknya, yakni angin barat yang sangat kencang, yang membawa belalang itu dan melemparkannya ke dalam Laut Teberau: tidak ada satu belalangpun yang tinggal di seluruh daerah Mesir.', NULL),
(49789, 3648, 10, 20, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga tidak mau membiarkan orang Israel pergi.', NULL),
(49790, 3648, 10, 21, 'Berfirmanlah TUHAN kepada Musa: \"Ulurkanlah tanganmu ke langit, supaya datang gelap meliputi tanah Mesir, sehingga orang dapat meraba gelap itu.\"', 'Tulah kesembilan: gelap gulita'),
(49791, 3648, 10, 22, 'Lalu Musa mengulurkan tangannya ke langit dan datanglah gelap gulita di seluruh tanah Mesir selama tiga hari.', NULL),
(49792, 3648, 10, 23, 'Tidak ada orang yang dapat melihat temannya, juga tidak ada orang yang dapat bangun dari tempatnya selama tiga hari; tetapi pada semua orang Israel ada terang di tempat kediamannya.', NULL),
(49793, 3648, 10, 24, 'Lalu Firaun memanggil Musa serta berkata: \"Pergilah, beribadahlah kepada TUHAN, hanya kambing dombamu dan lembu sapimu harus ditinggalkan, juga anak-anakmu boleh turut beserta kamu.\"', NULL),
(49794, 3648, 10, 25, 'Tetapi Musa berkata: \"Bahkan korban sembelihan dan korban bakaran harus engkau berikan kepada kami, supaya kami menyediakannya untuk TUHAN, Allah kami.', NULL),
(49795, 3648, 10, 26, 'Dan juga ternak kami harus turut beserta kami dan satu kakipun tidak akan tinggal, sebab dari ternak itulah kami harus ambil untuk beribadah kepada TUHAN, Allah kami; dan kami tidak tahu, dengan apa kami harus beribadah kepada TUHAN, sebelum kami sampai di sana.\"', NULL),
(49796, 3648, 10, 27, 'Tetapi TUHAN mengeraskan hati Firaun, sehingga dia tidak mau membiarkan mereka pergi.', NULL),
(49797, 3648, 10, 28, 'Lalu Firaun berkata kepadanya: \"Pergilah dari padaku; awaslah engkau, jangan lihat mukaku lagi, sebab pada waktu engkau melihat mukaku, engkau akan mati.\"', NULL),
(49798, 3648, 10, 29, 'Kemudian Musa berkata: \"Tepat seperti ucapanmu itu! Aku takkan melihat mukamu lagi!\"', NULL),
(49799, 3648, 11, 1, 'Berfirmanlah TUHAN kepada Musa: \"Aku akan mendatangkan satu tulah lagi atas Firaun dan atas Mesir, sesudah itu ia akan membiarkan kamu pergi dari sini; apabila ia membiarkan kamu pergi, ia akan benar-benar mengusir kamu dari sini.', 'Tulah kesepuluh diberitahukan'),
(49800, 3648, 11, 2, 'Baiklah katakan kepada bangsa itu, supaya setiap laki-laki meminta barang-barang emas dan perak kepada tetangganya dan setiap perempuan kepada tetangganya pula.\"', NULL),
(49801, 3648, 11, 3, 'Lalu TUHAN membuat orang Mesir bermurah hati terhadap bangsa itu; lagipula Musa adalah seorang yang sangat terpandang di tanah Mesir, di mata pegawai-pegawai Firaun dan di mata rakyat.', NULL),
(49802, 3648, 11, 4, 'Berkatalah Musa: \"Beginilah firman TUHAN: Pada waktu tengah malam Aku akan berjalan dari tengah-tengah Mesir.', NULL),
(49803, 3648, 11, 5, 'Maka tiap-tiap anak sulung di tanah Mesir akan mati, dari anak sulung Firaun yang duduk di takhtanya sampai kepada anak sulung budak perempuan yang menghadapi batu kilangan, juga segala anak sulung hewan.', NULL),
(49804, 3648, 11, 6, 'Dan seruan yang hebat akan terjadi di seluruh tanah Mesir, seperti yang belum pernah terjadi dan seperti yang tidak akan ada lagi.', NULL),
(49805, 3648, 11, 7, 'Tetapi kepada siapa juga dari orang Israel, seekor anjingpun tidak akan berani menggonggong, baik kepada manusia maupun kepada binatang, supaya kamu mengetahui, bahwa TUHAN membuat perbedaan antara orang Mesir dan orang Israel.', NULL),
(49806, 3648, 11, 8, 'Dan semua pegawaimu ini akan datang kepadaku dan sujud kepadaku serta berkata: Keluarlah, engkau dan seluruh rakyat yang mengikut engkau; sesudah itu aku akan keluar.\" Lalu Musa meninggalkan Firaun dengan marah yang bernyala-nyala.', NULL),
(49807, 3648, 11, 9, 'Berfirmanlah TUHAN kepada Musa: \"Firaun tidak akan mendengarkan kamu, supaya mujizat-mujizat yang Kubuat bertambah banyak di tanah Mesir.\"', NULL),
(49808, 3648, 11, 10, 'Musa dan Harun telah melakukan segala mujizat ini di depan Firaun. Tetapi TUHAN mengeraskan hati Firaun, sehingga tidak membiarkan orang Israel pergi dari negerinya.', NULL),
(49809, 3648, 12, 1, 'Berfirmanlah TUHAN kepada Musa dan Harun di tanah Mesir:', 'Tentang perayaan Paskah'),
(49810, 3648, 12, 2, '\"Bulan inilah akan menjadi permulaan segala bulan bagimu; itu akan menjadi bulan pertama bagimu tiap-tiap tahun.', NULL),
(49811, 3648, 12, 3, 'Katakanlah kepada segenap jemaah Israel: Pada tanggal sepuluh bulan ini diambillah oleh masing-masing seekor anak domba, menurut kaum keluarga, seekor anak domba untuk tiap-tiap rumah tangga.', NULL),
(49812, 3648, 12, 4, 'Tetapi jika rumah tangga itu terlalu kecil jumlahnya untuk mengambil seekor anak domba, maka ia bersama-sama dengan tetangganya yang terdekat ke rumahnya haruslah mengambil seekor, menurut jumlah jiwa; tentang anak domba itu, kamu buatlah perkiraan menurut keperluan tiap-tiap orang.', NULL),
(49813, 3648, 12, 5, 'Anak dombamu itu harus jantan, tidak bercela, berumur setahun; kamu boleh ambil domba atau kambing.', NULL),
(49814, 3648, 12, 6, 'Kamu harus mengurungnya sampai hari yang keempat belas bulan ini; lalu seluruh jemaah Israel yang berkumpul, harus menyembelihnya pada waktu senja.', NULL),
(49815, 3648, 12, 7, 'Kemudian dari darahnya haruslah diambil sedikit dan dibubuhkan pada kedua tiang pintu dan pada ambang atas, pada rumah-rumah di mana orang memakannya.', NULL),
(49816, 3648, 12, 8, 'Dagingnya harus dimakan mereka pada malam itu juga; yang dipanggang mereka harus makan dengan roti yang tidak beragi beserta sayur pahit.', NULL),
(49817, 3648, 12, 9, 'Janganlah kamu memakannya mentah atau direbus dalam air; hanya dipanggang di api, lengkap dengan kepalanya dan betisnya dan isi perutnya.', NULL),
(49818, 3648, 12, 10, 'Janganlah kamu tinggalkan apa-apa dari daging itu sampai pagi; apa yang tinggal sampai pagi kamu bakarlah habis dengan api.', NULL),
(49819, 3648, 12, 11, 'Dan beginilah kamu memakannya: pinggangmu berikat, kasut pada kakimu dan tongkat di tanganmu; buru-burulah kamu memakannya; itulah Paskah bagi TUHAN.', NULL),
(49820, 3648, 12, 12, 'Sebab pada malam ini Aku akan menjalani tanah Mesir, dan semua anak sulung, dari anak manusia sampai anak binatang, akan Kubunuh, dan kepada semua allah di Mesir akan Kujatuhkan hukuman, Akulah, TUHAN.', NULL),
(49821, 3648, 12, 13, 'Dan darah itu menjadi tanda bagimu pada rumah-rumah di mana kamu tinggal: Apabila Aku melihat darah itu, maka Aku akan lewat dari pada kamu. Jadi tidak akan ada tulah kemusnahan di tengah-tengah kamu, apabila Aku menghukum tanah Mesir.', NULL),
(49822, 3648, 12, 14, 'Hari ini akan menjadi hari peringatan bagimu. Kamu harus merayakannya sebagai hari raya bagi TUHAN turun-temurun. Kamu harus merayakannya sebagai ketetapan untuk selamanya.', NULL),
(49823, 3648, 12, 15, 'Kamu makanlah roti yang tidak beragi tujuh hari lamanya; pada hari pertamapun kamu buanglah segala ragi dari rumahmu, sebab setiap orang yang makan sesuatu yang beragi, dari hari pertama sampai hari ketujuh, orang itu harus dilenyapkan dari antara Israel.', NULL),
(49824, 3648, 12, 16, 'Kamu adakanlah pertemuan yang kudus, baik pada hari yang pertama maupun pada hari yang ketujuh; pada hari-hari itu tidak boleh dilakukan pekerjaan apapun; hanya apa yang perlu dimakan setiap orang, itu sajalah yang boleh kamu sediakan.', NULL),
(49825, 3648, 12, 17, 'Jadi kamu harus tetap merayakan hari raya makan roti yang tidak beragi, sebab tepat pada hari ini juga Aku membawa pasukan-pasukanmu keluar dari tanah Mesir. Maka haruslah kamu rayakan hari ini turun-temurun; itulah suatu ketetapan untuk selamanya.', NULL),
(49826, 3648, 12, 18, 'Dalam bulan pertama, pada hari yang keempat belas bulan itu pada waktu petang, kamu makanlah roti yang tidak beragi, sampai kepada hari yang kedua puluh satu bulan itu, pada waktu petang.', NULL),
(49827, 3648, 12, 19, 'Tujuh hari lamanya tidak boleh ada ragi dalam rumahmu, sebab setiap orang yang makan sesuatu yang beragi, orang itu harus dilenyapkan dari antara jemaah Israel, baik ia orang asing, baik ia orang asli.', NULL),
(49828, 3648, 12, 20, 'Sesuatu apapun yang beragi tidak boleh kamu makan; kamu makanlah roti yang tidak beragi di segala tempat kediamanmu.\"', NULL),
(49829, 3648, 12, 21, 'Lalu Musa memanggil semua tua-tua Israel serta berkata kepada mereka: \"Pergilah, ambillah kambing domba untuk kaummu dan sembelihlah anak domba Paskah.', NULL),
(49830, 3648, 12, 22, 'Kemudian kamu harus mengambil seikat hisop dan mencelupkannya dalam darah yang ada dalam sebuah pasu, dan darah itu kamu harus sapukan pada ambang atas dan pada kedua tiang pintu; seorangpun dari kamu tidak boleh keluar pintu rumahnya sampai pagi.', NULL),
(49831, 3648, 12, 23, 'Dan TUHAN akan menjalani Mesir untuk menulahinya; apabila Ia melihat darah pada ambang atas dan pada kedua tiang pintu itu, maka TUHAN akan melewati pintu itu dan tidak membiarkan pemusnah masuk ke dalam rumahmu untuk menulahi.', NULL),
(49832, 3648, 12, 24, 'Kamu harus memegang ini sebagai ketetapan sampai selama-lamanya bagimu dan bagi anak-anakmu.', NULL),
(49833, 3648, 12, 25, 'Dan apabila kamu tiba di negeri yang akan diberikan TUHAN kepadamu, seperti yang difirmankan-Nya, maka kamu harus pelihara ibadah ini.', NULL),
(49834, 3648, 12, 26, 'Dan apabila anak-anakmu berkata kepadamu: Apakah artinya ibadahmu ini?', NULL),
(49835, 3648, 12, 27, 'maka haruslah kamu berkata: Itulah korban Paskah bagi TUHAN yang melewati rumah-rumah orang Israel di Mesir, ketika Ia menulahi orang Mesir, tetapi menyelamatkan rumah-rumah kita.\" Lalu berlututlah bangsa itu dan sujud menyembah.', NULL),
(49836, 3648, 12, 28, 'Pergilah orang Israel, lalu berbuat demikian; seperti yang diperintahkan TUHAN kepada Musa dan Harun, demikianlah diperbuat mereka.', NULL),
(49837, 3648, 12, 29, 'Maka pada tengah malam TUHAN membunuh tiap-tiap anak sulung di tanah Mesir, dari anak sulung Firaun yang duduk di takhtanya sampai kepada anak sulung orang tawanan, yang ada dalam liang tutupan, beserta segala anak sulung hewan.', 'Tulah kesepuluh: Anak sulung mati Orang Israel keluar dari Mesir'),
(49838, 3648, 12, 30, 'Lalu bangunlah Firaun pada malam itu, bersama semua pegawainya dan semua orang Mesir; dan kedengaranlah seruan yang hebat di Mesir, sebab tidak ada rumah yang tidak kematian.', NULL),
(49839, 3648, 12, 31, 'Lalu pada malam itu dipanggilnyalah Musa dan Harun, katanya: \"Bangunlah, keluarlah dari tengah-tengah bangsaku, baik kamu maupun orang Israel; pergilah, beribadahlah kepada TUHAN, seperti katamu itu.', NULL),
(49840, 3648, 12, 32, 'Bawalah juga kambing dombamu dan lembu sapimu, seperti katamu itu, tetapi pergilah! Dan pohonkanlah juga berkat bagiku.\"', NULL),
(49841, 3648, 12, 33, 'Orang Mesir juga mendesak dengan keras kepada bangsa itu, menyuruh bangsa itu pergi dengan segera dari negeri itu, sebab kata mereka: \"Nanti kami mati semuanya.\"', NULL),
(49842, 3648, 12, 34, 'Lalu bangsa itu mengangkat adonannya, sebelum diragi, dengan tempat adonan mereka terbungkus dalam kainnya di atas bahunya.', NULL),
(49843, 3648, 12, 35, 'Orang Israel melakukan juga seperti kata Musa; mereka meminta dari orang Mesir barang-barang emas dan perak serta kain-kain.', NULL),
(49844, 3648, 12, 36, 'Dan TUHAN membuat orang Mesir bermurah hati terhadap bangsa itu, sehingga memenuhi permintaan mereka. Demikianlah mereka merampasi orang Mesir itu.', NULL),
(49845, 3648, 12, 37, 'Kemudian berangkatlah orang Israel dari Raamses ke Sukot, kira-kira enam ratus ribu orang laki-laki berjalan kaki, tidak termasuk anak-anak.', NULL),
(49846, 3648, 12, 38, 'Juga banyak orang dari berbagai-bagai bangsa turut dengan mereka; lagi sangat banyak ternak kambing domba dan lembu sapi.', NULL),
(49847, 3648, 12, 39, 'Adonan yang dibawa mereka dari Mesir dibakarlah menjadi roti bundar yang tidak beragi, sebab adonan itu tidak diragi, karena mereka diusir dari Mesir dan tidak dapat berlambat-lambat, dan mereka tidak pula menyediakan bekal baginya.', NULL),
(49848, 3648, 12, 40, 'Lamanya orang Israel diam di Mesir adalah empat ratus tiga puluh tahun.', NULL),
(49849, 3648, 12, 41, 'Sesudah lewat empat ratus tiga puluh tahun, tepat pada hari itu juga, keluarlah segala pasukan TUHAN dari tanah Mesir.', NULL),
(49850, 3648, 12, 42, 'Malam itulah malam berjaga-jaga bagi TUHAN, untuk membawa mereka keluar dari tanah Mesir. Dan itulah juga malam berjaga-jaga bagi semua orang Israel, turun-temurun, untuk kemuliaan TUHAN.', NULL),
(49851, 3648, 12, 43, 'Berfirmanlah TUHAN kepada Musa dan Harun: \"Inilah ketetapan mengenai Paskah: Tidak seorangpun dari bangsa asing boleh memakannya.', 'Ketetapan lebih lanjut mengenai Paskah'),
(49852, 3648, 12, 44, 'Seorang budak belian barulah boleh memakannya, setelah engkau menyunat dia.', NULL),
(49853, 3648, 12, 45, 'Orang pendatang dan orang upahan tidak boleh memakannya.', NULL),
(49854, 3648, 12, 46, 'Paskah itu harus dimakan dalam satu rumah juga; tidak boleh kaubawa sedikitpun dari daging itu keluar rumah; satu tulangpun tidak boleh kamu patahkan.', NULL),
(49855, 3648, 12, 47, 'Segenap jemaah Israel haruslah merayakannya.', NULL),
(49856, 3648, 12, 48, 'Tetapi apabila seorang asing telah menetap padamu dan mau merayakan Paskah bagi TUHAN, maka setiap laki-laki yang bersama-sama dengan dia, wajiblah disunat; barulah ia boleh mendekat untuk merayakannya; ia akan dianggap sebagai orang asli. Tetapi tidak seorangpun yang tidak bersunat boleh memakannya.', NULL),
(49857, 3648, 12, 49, 'Satu hukum saja akan berlaku untuk orang asli dan untuk orang asing yang menetap di tengah-tengah kamu.\"', NULL),
(49858, 3648, 12, 50, 'Seluruh orang Israel berbuat demikian; seperti yang diperintahkan TUHAN kepada Musa dan Harun, demikianlah diperbuat mereka.', NULL),
(49859, 3648, 12, 51, 'Dan tepat pada hari itu juga TUHAN membawa orang Israel keluar dari tanah Mesir, menurut pasukan mereka.', NULL),
(51729, 3648, 13, 1, 'Berfirmanlah TUHAN kepada Musa:', 'Ketetapan tentang anak sulung Hari raya Roti Tidak Beragi'),
(51730, 3648, 13, 2, '\"Kuduskanlah bagi-Ku semua anak sulung, semua yang lahir terdahulu dari kandungan pada orang Israel, baik pada manusia maupun pada hewan; Akulah yang empunya mereka.\"', NULL),
(51731, 3648, 13, 3, 'Lalu berkatalah Musa kepada bangsa itu: \"Peringatilah hari ini, sebab pada hari ini kamu keluar dari Mesir, dari rumah perbudakan; karena dengan kekuatan tangan-Nya TUHAN telah membawa kamu keluar dari sana. Sebab itu tidak boleh dimakan sesuatupun yang beragi.', NULL),
(51732, 3648, 13, 4, 'Hari ini kamu keluar, dalam bulan Abib.', NULL),
(51733, 3648, 13, 5, 'Apabila TUHAN telah membawa engkau ke negeri orang Kanaan, orang Het, orang Amori, orang Hewi dan orang Yebus, negeri yang telah dijanjikan-Nya dengan sumpah kepada nenek moyangmu untuk memberikannya kepadamu, suatu negeri yang berlimpah-limpah susu dan madunya, maka engkau harus melakukan ibadah ini dalam bulan ini juga.', NULL),
(51734, 3648, 13, 6, 'Makanlah roti yang tidak beragi tujuh hari lamanya dan pada hari yang ketujuh akan diadakan hari raya bagi TUHAN.', NULL),
(51735, 3648, 13, 7, 'Roti yang tidak beragi haruslah dimakan selama tujuh hari itu; sesuatupun yang beragi tidak boleh dilihat padamu, bahkan ragi tidak boleh dilihat padamu di seluruh daerahmu.', NULL),
(51736, 3648, 13, 8, 'Pada hari itu harus kauberitahukan kepada anakmu laki-laki: Ibadah ini adalah karena mengingat apa yang dibuat TUHAN kepadaku pada waktu aku keluar dari Mesir.', NULL),
(51737, 3648, 13, 9, 'Hal itu bagimu harus menjadi tanda pada tanganmu dan menjadi peringatan di dahimu, supaya hukum TUHAN ada di bibirmu; sebab dengan tangan yang kuat TUHAN telah membawa engkau keluar dari Mesir.', NULL),
(51738, 3648, 13, 10, 'Haruslah kaupegang ketetapan ini pada waktunya yang sudah ditentukan, dari tahun ke tahun.', NULL),
(51739, 3648, 13, 11, 'Apabila engkau telah dibawa TUHAN ke negeri orang Kanaan, seperti yang telah dijanjikan-Nya dengan sumpah kepadamu dan kepada nenek moyangmu, dan negeri itu telah diberikan-Nya kepadamu,', NULL),
(51740, 3648, 13, 12, 'maka haruslah kaupersembahkan bagi TUHAN segala yang lahir terdahulu dari kandungan; juga setiap kali ada hewan yang kaupunyai beranak pertama kali, anak jantan yang sulung adalah bagi TUHAN.', NULL),
(51741, 3648, 13, 13, 'Tetapi setiap anak keledai yang lahir terdahulu kautebuslah dengan seekor domba; atau, jika engkau tidak menebusnya, engkau harus mematahkan batang lehernya. Tetapi mengenai manusia, setiap anak sulung di antara anak-anakmu lelaki, haruslah kautebus.', NULL),
(51742, 3648, 13, 14, 'Dan apabila anakmu akan bertanya kepadamu di kemudian hari: Apakah artinya itu? maka haruslah engkau berkata kepadanya: Dengan kekuatan tangan-Nya TUHAN telah membawa kita keluar dari Mesir, dari rumah perbudakan.', NULL),
(51743, 3648, 13, 15, 'Sebab ketika Firaun dengan tegar menolak untuk membiarkan kita pergi, maka TUHAN membunuh semua anak sulung di tanah Mesir, dari anak sulung manusia sampai anak sulung hewan. Itulah sebabnya maka aku biasa mempersembahkan kepada TUHAN segala binatang jantan yang lahir terdahulu dari kandungan, sedang semua anak sulung di antara anak-anakku lelaki kutebus.', NULL),
(51744, 3648, 13, 16, 'Hal itu harus menjadi tanda pada tanganmu dan menjadi lambang di dahimu, sebab dengan kekuatan tangan-Nya TUHAN membawa kita keluar dari Mesir.\"', NULL),
(51745, 3648, 13, 17, 'Setelah Firaun membiarkan bangsa itu pergi, Allah tidak menuntun mereka melalui jalan ke negeri orang Filistin, walaupun jalan ini yang paling dekat; sebab firman Allah: \"Jangan-jangan bangsa itu menyesal, apabila mereka menghadapi peperangan, sehingga mereka kembali ke Mesir.\"', 'Allah menuntun umat-Nya'),
(51746, 3648, 13, 18, 'Tetapi Allah menuntun bangsa itu berputar melalui jalan di padang gurun menuju ke Laut Teberau. Dengan siap sedia berperang berjalanlah orang Israel dari tanah Mesir.', NULL),
(51747, 3648, 13, 19, 'Musa membawa tulang-tulang Yusuf, sebab tadinya Yusuf telah menyuruh anak-anak Israel bersumpah dengan sungguh-sungguh: \"Allah tentu akan mengindahkan kamu, maka kamu harus membawa tulang-tulangku dari sini.\"', NULL),
(51748, 3648, 13, 20, 'Demikianlah mereka berangkat dari Sukot dan berkemah di Etam, di tepi padang gurun.', NULL),
(51749, 3648, 13, 21, 'TUHAN berjalan di depan mereka, pada siang hari dalam tiang awan untuk menuntun mereka di jalan, dan pada waktu malam dalam tiang api untuk menerangi mereka, sehingga mereka dapat berjalan siang dan malam.', NULL),
(51750, 3648, 13, 22, 'Dengan tidak beralih tiang awan itu tetap ada pada siang hari dan tiang api pada waktu malam di depan bangsa itu.', NULL),
(51751, 3648, 14, 1, 'Berfirmanlah TUHAN kepada Musa, demikian:', 'Firaun bertindak untuk penghabisan kali'),
(51752, 3648, 14, 2, '\"Katakanlah kepada orang Israel, supaya mereka balik kembali dan berkemah di depan Pi-Hahirot, antara Migdol dan laut; tepat di depan Baal-Zefon berkemahlah kamu, di tepi laut.', NULL),
(51753, 3648, 14, 3, 'Maka Firaun akan berkata tentang orang Israel: Mereka telah sesat di negeri ini, padang gurun telah mengurung mereka.', NULL),
(51754, 3648, 14, 4, 'Aku akan mengeraskan hati Firaun, sehingga ia mengejar mereka. Dan terhadap Firaun dan seluruh pasukannya Aku akan menyatakan kemuliaan-Ku, sehingga orang Mesir mengetahui, bahwa Akulah TUHAN.\" Lalu mereka berbuat demikian.', NULL),
(51755, 3648, 14, 5, 'Ketika diberitahukan kepada raja Mesir, bahwa bangsa itu telah lari, maka berubahlah hati Firaun dan pegawai-pegawainya terhadap bangsa itu, dan berkatalah mereka: \"Apakah yang telah kita perbuat ini, bahwa kita membiarkan orang Israel pergi dari perbudakan kita?\"', NULL),
(51756, 3648, 14, 6, 'Kemudian ia memasang keretanya dan membawa rakyatnya serta.', NULL),
(51757, 3648, 14, 7, 'Ia membawa enam ratus kereta yang terpilih, ya, segala kereta Mesir, masing-masing lengkap dengan perwiranya.', NULL),
(51758, 3648, 14, 8, 'Demikianlah TUHAN mengeraskan hati Firaun, raja Mesir itu, sehingga ia mengejar orang Israel. Tetapi orang Israel berjalan terus dipimpin oleh tangan yang dinaikkan.', NULL),
(51759, 3648, 14, 9, 'Adapun orang Mesir, segala kuda dan kereta Firaun, orang-orang berkuda dan pasukannya, mengejar mereka dan mencapai mereka pada waktu mereka berkemah di tepi laut, dekat Pi-Hahirot di depan Baal-Zefon.', NULL),
(51760, 3648, 14, 10, 'Ketika Firaun telah dekat, orang Israel menoleh, maka tampaklah orang Mesir bergerak menyusul mereka. Lalu sangat ketakutanlah orang Israel dan mereka berseru-seru kepada TUHAN,', NULL),
(51761, 3648, 14, 11, 'dan mereka berkata kepada Musa: \"Apakah karena tidak ada kuburan di Mesir, maka engkau membawa kami untuk mati di padang gurun ini? Apakah yang kauperbuat ini terhadap kami dengan membawa kami keluar dari Mesir?', NULL),
(51762, 3648, 14, 12, 'Bukankah ini telah kami katakan kepadamu di Mesir: Janganlah mengganggu kami dan biarlah kami bekerja pada orang Mesir. Sebab lebih baik bagi kami untuk bekerja pada orang Mesir dari pada mati di padang gurun ini.\"', NULL),
(51763, 3648, 14, 13, 'Tetapi berkatalah Musa kepada bangsa itu: \"Janganlah takut, berdirilah tetap dan lihatlah keselamatan dari TUHAN, yang akan diberikan-Nya hari ini kepadamu; sebab orang Mesir yang kamu lihat hari ini, tidak akan kamu lihat lagi untuk selama-lamanya.', NULL),
(51764, 3648, 14, 14, 'TUHAN akan berperang untuk kamu, dan kamu akan diam saja.\"', NULL),
(51765, 3648, 14, 15, 'Berfirmanlah TUHAN kepada Musa: \"Mengapakah engkau berseru-seru demikian kepada-Ku? Katakanlah kepada orang Israel, supaya mereka berangkat.', 'Menyeberangi Laut Teberau'),
(51766, 3648, 14, 16, 'Dan engkau, angkatlah tongkatmu dan ulurkanlah tanganmu ke atas laut dan belahlah airnya, sehingga orang Israel akan berjalan dari tengah-tengah laut di tempat kering.', NULL),
(51767, 3648, 14, 17, 'Tetapi sungguh Aku akan mengeraskan hati orang Mesir, sehingga mereka menyusul orang Israel, dan terhadap Firaun dan seluruh pasukannya, keretanya dan orangnya yang berkuda, Aku akan menyatakan kemuliaan-Ku.', NULL),
(51768, 3648, 14, 18, 'Maka orang Mesir akan mengetahui, bahwa Akulah TUHAN, apabila Aku memperlihatkan kemuliaan-Ku terhadap Firaun, keretanya dan orangnya yang berkuda.\"', NULL),
(51769, 3648, 14, 19, 'Kemudian bergeraklah Malaikat Allah, yang tadinya berjalan di depan tentara Israel, lalu berjalan di belakang mereka; dan tiang awan itu bergerak dari depan mereka, lalu berdiri di belakang mereka.', NULL),
(51770, 3648, 14, 20, 'Demikianlah tiang itu berdiri di antara tentara orang Mesir dan tentara orang Israel; dan oleh karena awan itu menimbulkan kegelapan, maka malam itu lewat, sehingga yang satu tidak dapat mendekati yang lain, semalam-malaman itu.', NULL),
(51771, 3648, 14, 21, 'Lalu Musa mengulurkan tangannya ke atas laut, dan semalam-malaman itu TUHAN menguakkan air laut dengan perantaraan angin timur yang keras, membuat laut itu menjadi tanah kering; maka terbelahlah air itu.', NULL),
(51772, 3648, 14, 22, 'Demikianlah orang Israel berjalan dari tengah-tengah laut di tempat kering; sedang di kiri dan di kanan mereka air itu sebagai tembok bagi mereka.', NULL),
(51773, 3648, 14, 23, 'Orang Mesir mengejar dan menyusul mereka--segala kuda Firaun, keretanya dan orangnya yang berkuda--sampai ke tengah-tengah laut.', NULL),
(51774, 3648, 14, 24, 'Dan pada waktu jaga pagi, TUHAN yang di dalam tiang api dan awan itu memandang kepada tentara orang Mesir, lalu dikacaukan-Nya tentara orang Mesir itu.', NULL),
(51775, 3648, 14, 25, 'Ia membuat roda keretanya berjalan miring dan maju dengan berat, sehingga orang Mesir berkata: \"Marilah kita lari meninggalkan orang Israel, sebab Tuhanlah yang berperang untuk mereka melawan Mesir.\"', NULL),
(51776, 3648, 14, 26, 'Berfirmanlah TUHAN kepada Musa: \"Ulurkanlah tanganmu ke atas laut, supaya air berbalik meliputi orang Mesir, meliputi kereta mereka dan orang mereka yang berkuda.\"', NULL),
(51777, 3648, 14, 27, 'Musa mengulurkan tangannya ke atas laut, maka menjelang pagi berbaliklah air laut ke tempatnya, sedang orang Mesir lari menuju air itu; demikianlah TUHAN mencampakkan orang Mesir ke tengah-tengah laut.', NULL),
(51778, 3648, 14, 28, 'Berbaliklah segala air itu, lalu menutupi kereta dan orang berkuda dari seluruh pasukan Firaun, yang telah menyusul orang Israel itu ke laut; seorangpun tidak ada yang tinggal dari mereka.', NULL),
(51779, 3648, 14, 29, 'Tetapi orang Israel berjalan di tempat kering dari tengah-tengah laut, sedang di kiri dan di kanan mereka air itu sebagai tembok bagi mereka.', NULL),
(51780, 3648, 14, 30, 'Demikianlah pada hari itu TUHAN menyelamatkan orang Israel dari tangan orang Mesir. Dan orang Israel melihat orang Mesir mati terhantar di pantai laut.', NULL),
(51781, 3648, 14, 31, 'Ketika dilihat oleh orang Israel, betapa besarnya perbuatan yang dilakukan TUHAN terhadap orang Mesir, maka takutlah bangsa itu kepada TUHAN dan mereka percaya kepada TUHAN dan kepada Musa, hamba-Nya itu.', NULL),
(53704, 3648, 15, 1, 'Pada waktu itu Musa bersama-sama dengan orang Israel menyanyikan nyanyian ini bagi TUHAN yang berbunyi: \"Baiklah aku menyanyi bagi TUHAN, sebab Ia tinggi luhur, kuda dan penunggangnya dilemparkan-Nya ke dalam laut.', 'Nyanyian Musa dan Israel'),
(53705, 3648, 15, 2, 'TUHAN itu kekuatanku dan mazmurku, Ia telah menjadi keselamatanku. Ia Allahku, kupuji Dia, Ia Allah bapaku, kuluhurkan Dia.', NULL),
(53706, 3648, 15, 3, 'TUHAN itu pahlawan perang; TUHAN, itulah nama-Nya.', NULL),
(53707, 3648, 15, 4, 'Kereta Firaun dan pasukannya dibuang-Nya ke dalam laut; para perwiranya yang pilihan dibenamkan ke dalam Laut Teberau.', NULL),
(53708, 3648, 15, 5, 'Samudera raya menutupi mereka; ke air yang dalam mereka tenggelam seperti batu.', NULL),
(53709, 3648, 15, 6, 'Tangan kanan-Mu, TUHAN, mulia karena kekuasaan-Mu, tangan kanan-Mu, TUHAN, menghancurkan musuh.', NULL),
(53710, 3648, 15, 7, 'Dengan keluhuran-Mu yang besar Engkau meruntuhkan siapa yang bangkit menentang Engkau; Engkau melepaskan api murka-Mu, yang memakan mereka sebagai tunggul gandum.', NULL),
(53711, 3648, 15, 8, 'Karena nafas hidung-Mu segala air naik bertimbun-timbun; segala aliran berdiri tegak seperti bendungan; air bah membeku di tengah-tengah laut.', NULL),
(53712, 3648, 15, 9, 'Kata musuh: Aku akan mengejar, akan mencapai mereka, akan membagi-bagi jarahan; nafsuku akan kulampiaskan kepada mereka, akan kuhunus pedangku; tanganku akan melenyapkan mereka!', NULL),
(53713, 3648, 15, 10, 'Engkau meniup dengan taufan-Mu, lautpun menutupi mereka; sebagai timah mereka tenggelam dalam air yang hebat.', NULL),
(53714, 3648, 15, 11, 'Siapakah yang seperti Engkau, di antara para allah, ya TUHAN; siapakah seperti Engkau, mulia karena kekudusan-Mu, menakutkan karena perbuatan-Mu yang masyhur, Engkau pembuat keajaiban?', NULL),
(53715, 3648, 15, 12, 'Engkau mengulurkan tangan kanan-Mu; bumipun menelan mereka.', NULL),
(53716, 3648, 15, 13, 'Dengan kasih setia-Mu Engkau menuntun umat yang telah Kautebus; dengan kekuatan-Mu Engkau membimbingnya ke tempat kediaman-Mu yang kudus.', NULL),
(53717, 3648, 15, 14, 'Bangsa-bangsa mendengarnya, merekapun menggigil; kegentaran menghinggapi penduduk tanah Filistin.', NULL),
(53718, 3648, 15, 15, 'Pada waktu itu gemparlah para kepala kaum di Edom, kedahsyatan menghinggapi orang-orang berkuasa di Moab; semua penduduk tanah Kanaan gemetar.', 'Di Mara dan di Elim'),
(53719, 3648, 15, 16, 'Ngeri dan takut menimpa mereka, karena kebesaran tangan-Mu mereka kaku seperti batu, sampai umat-Mu menyeberang, ya TUHAN, sampai umat yang Kauperoleh menyeberang.', NULL),
(53720, 3648, 15, 17, 'Engkau membawa mereka dan Kaucangkokkan mereka di atas gunung milik-Mu sendiri; di tempat yang telah Kaubuat kediaman-Mu, ya TUHAN; di tempat kudus, yang didirikan tangan-Mu, ya TUHAN.', NULL),
(53721, 3648, 15, 18, 'TUHAN memerintah kekal selama-lamanya.\"', NULL),
(53722, 3648, 15, 19, 'Ketika kuda Firaun dengan keretanya dan orangnya yang berkuda telah masuk ke laut, maka TUHAN membuat air laut berbalik meliputi mereka, tetapi orang Israel berjalan di tempat kering dari tengah-tengah laut.', NULL),
(53723, 3648, 15, 20, 'Lalu Miryam, nabiah itu, saudara perempuan Harun, mengambil rebana di tangannya, dan tampillah semua perempuan mengikutinya memukul rebana serta menari-nari.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(53724, 3648, 15, 21, 'Dan menyanyilah Miryam memimpin mereka: \"Menyanyilah bagi TUHAN, sebab Ia tinggi luhur; kuda dan penunggangnya dilemparkan-Nya ke dalam laut.\"', NULL),
(53725, 3648, 15, 22, 'Musa menyuruh orang Israel berangkat dari Laut Teberau, lalu mereka pergi ke padang gurun Syur; tiga hari lamanya mereka berjalan di padang gurun itu dengan tidak mendapat air.', NULL),
(53726, 3648, 15, 23, 'Sampailah mereka ke Mara, tetapi mereka tidak dapat meminum air yang di Mara itu, karena pahit rasanya. Itulah sebabnya dinamai orang tempat itu Mara.', NULL),
(53727, 3648, 15, 24, 'Lalu bersungut-sungutlah bangsa itu kepada Musa, kata mereka: \"Apakah yang akan kami minum?\"', NULL),
(53728, 3648, 15, 25, 'Musa berseru-seru kepada TUHAN, dan TUHAN menunjukkan kepadanya sepotong kayu; Musa melemparkan kayu itu ke dalam air; lalu air itu menjadi manis. Di sanalah diberikan TUHAN ketetapan-ketetapan dan peraturan-peraturan kepada mereka dan di sanalah TUHAN mencoba mereka,', NULL),
(53729, 3648, 15, 26, 'firman-Nya: \"Jika kamu sungguh-sungguh mendengarkan suara TUHAN, Allahmu, dan melakukan apa yang benar di mata-Nya, dan memasang telingamu kepada perintah-perintah-Nya dan tetap mengikuti segala ketetapan-Nya, maka Aku tidak akan menimpakan kepadamu penyakit manapun, yang telah Kutimpakan kepada orang Mesir; sebab Aku Tuhanlah yang menyembuhkan engkau.\"', NULL),
(53730, 3648, 15, 27, 'Sesudah itu sampailah mereka di Elim; di sana ada dua belas mata air dan tujuh puluh pohon korma, lalu berkemahlah mereka di sana di tepi air itu.', NULL),
(55680, 3648, 16, 1, 'Setelah mereka berangkat dari Elim, tibalah segenap jemaah Israel di padang gurun Sin, yang terletak di antara Elim dan gunung Sinai, pada hari yang kelima belas bulan yang kedua, sejak mereka keluar dari tanah Mesir.', 'Manna, Sabat'),
(55681, 3648, 16, 2, 'Di padang gurun itu bersungut-sungutlah segenap jemaah Israel kepada Musa dan Harun;', NULL),
(55682, 3648, 16, 3, 'dan berkata kepada mereka: \"Ah, kalau kami mati tadinya di tanah Mesir oleh tangan TUHAN ketika kami duduk menghadapi kuali berisi daging dan makan roti sampai kenyang! Sebab kamu membawa kami keluar ke padang gurun ini untuk membunuh seluruh jemaah ini dengan kelaparan.\"', NULL),
(55683, 3648, 16, 4, 'Lalu berfirmanlah TUHAN kepada Musa: \"Sesungguhnya Aku akan menurunkan dari langit hujan roti bagimu; maka bangsa itu akan keluar dan memungut tiap-tiap hari sebanyak yang perlu untuk sehari, supaya mereka Kucoba, apakah mereka hidup menurut hukum-Ku atau tidak.', NULL),
(55684, 3648, 16, 5, 'Dan pada hari yang keenam, apabila mereka memasak yang dibawa mereka pulang, maka yang dibawa itu akan terdapat dua kali lipat banyaknya dari apa yang dipungut mereka sehari-hari.\"', NULL),
(55685, 3648, 16, 6, 'Sesudah itu berkatalah Musa dan Harun kepada seluruh orang Israel: \"Petang ini kamu akan mengetahui bahwa Tuhanlah yang telah membawa kamu keluar dari tanah Mesir.', NULL),
(55686, 3648, 16, 7, 'Dan besok pagi kamu melihat kemuliaan TUHAN, karena Ia telah mendengar sungut-sungutmu kepada-Nya. Sebab, apalah kami ini maka kamu bersungut-sungut kepada kami?\"', NULL),
(55687, 3648, 16, 8, 'Lagi kata Musa: \"Jika memang TUHAN yang memberi kamu makan daging pada waktu petang dan makan roti sampai kenyang pada waktu pagi, karena TUHAN telah mendengar sungut-sungutmu yang kamu sungut-sungutkan kepada-Nya--apalah kami ini? Bukan kepada kami sungut-sungutmu itu, tetapi kepada TUHAN.\"', NULL),
(55688, 3648, 16, 9, 'Kata Musa kepada Harun: \"Katakanlah kepada segenap jemaah Israel: Marilah dekat ke hadapan TUHAN, sebab Ia telah mendengar sungut-sungutmu.\"', NULL),
(55689, 3648, 16, 10, 'Dan sedang Harun berbicara kepada segenap jemaah Israel, mereka memalingkan mukanya ke arah padang gurun--maka tampaklah kemuliaan TUHAN dalam awan.', NULL),
(55690, 3648, 16, 11, 'Lalu berfirmanlah TUHAN kepada Musa:', NULL),
(55691, 3648, 16, 12, '\"Aku telah mendengar sungut-sungut orang Israel; katakanlah kepada mereka: Pada waktu senja kamu akan makan daging dan pada waktu pagi kamu akan kenyang makan roti; maka kamu akan mengetahui, bahwa Akulah TUHAN, Allahmu.\"', NULL),
(55692, 3648, 16, 13, 'Pada waktu petang datanglah berduyun-duyun burung puyuh yang menutupi perkemahan itu; dan pada waktu pagi terletaklah embun sekeliling perkemahan itu.', NULL),
(55693, 3648, 16, 14, 'Ketika embun itu telah menguap, tampaklah pada permukaan padang gurun sesuatu yang halus, sesuatu yang seperti sisik, halus seperti embun beku di bumi.', NULL),
(55694, 3648, 16, 15, 'Ketika orang Israel melihatnya, berkatalah mereka seorang kepada yang lain: \"Apakah ini?\" Sebab mereka tidak tahu apa itu. Tetapi Musa berkata kepada mereka: \"Inilah roti yang diberikan TUHAN kepadamu menjadi makananmu.', NULL),
(55695, 3648, 16, 16, 'Beginilah perintah TUHAN: Pungutlah itu, tiap-tiap orang menurut keperluannya; masing-masing kamu boleh mengambil untuk seisi kemahnya, segomer seorang, menurut jumlah jiwa.\"', NULL),
(55696, 3648, 16, 17, 'Demikianlah diperbuat orang Israel; mereka mengumpulkan, ada yang banyak, ada yang sedikit.', NULL),
(55697, 3648, 16, 18, 'Ketika mereka menakarnya dengan gomer, maka orang yang mengumpulkan banyak, tidak kelebihan dan orang yang mengumpulkan sedikit, tidak kekurangan. Tiap-tiap orang mengumpulkan menurut keperluannya.', NULL),
(55698, 3648, 16, 19, 'Musa berkata kepada mereka: \"Seorangpun tidak boleh meninggalkan dari padanya sampai pagi.\"', NULL),
(55699, 3648, 16, 20, 'Tetapi ada yang tidak mendengarkan Musa dan meninggalkan dari padanya sampai pagi, lalu berulat dan berbau busuk. Maka Musa menjadi marah kepada mereka.', NULL),
(55700, 3648, 16, 21, 'Setiap pagi mereka memungutnya, tiap-tiap orang menurut keperluannya; tetapi ketika matahari panas, cairlah itu.', NULL),
(55701, 3648, 16, 22, 'Dan pada hari yang keenam mereka memungut roti itu dua kali lipat banyaknya, dua gomer untuk tiap-tiap orang; dan datanglah semua pemimpin jemaah memberitahukannya kepada Musa.', NULL),
(55702, 3648, 16, 23, 'Lalu berkatalah Musa kepada mereka: \"Inilah yang dimaksudkan TUHAN: Besok adalah hari perhentian penuh, sabat yang kudus bagi TUHAN; maka roti yang perlu kamu bakar, bakarlah, dan apa yang perlu kamu masak, masaklah; dan segala kelebihannya biarkanlah di tempatnya untuk disimpan sampai pagi.\"', NULL),
(55703, 3648, 16, 24, 'Mereka membiarkannya di tempatnya sampai keesokan harinya, seperti yang diperintahkan Musa; lalu tidaklah berbau busuk dan tidak ada ulat di dalamnya.', NULL),
(55704, 3648, 16, 25, 'Selanjutnya kata Musa: \"Makanlah itu pada hari ini, sebab hari ini adalah sabat untuk TUHAN, pada hari ini tidaklah kamu mendapatnya di padang.', NULL),
(55705, 3648, 16, 26, 'Enam hari lamanya kamu memungutnya, tetapi pada hari yang ketujuh ada sabat; maka roti itu tidak ada pada hari itu.\"', NULL),
(55706, 3648, 16, 27, 'Tetapi ketika pada hari ketujuh ada dari bangsa itu yang keluar memungutnya, tidaklah mereka mendapatnya.', NULL),
(55707, 3648, 16, 28, 'Sebab itu TUHAN berfirman kepada Musa: \"Berapa lama lagi kamu menolak mengikuti segala perintah-Ku dan hukum-Ku?', NULL),
(55708, 3648, 16, 29, 'Perhatikanlah, TUHAN telah memberikan sabat itu kepadamu; itulah sebabnya pada hari keenam Ia memberikan kepadamu roti untuk dua hari. Tinggallah kamu di tempatmu masing-masing, seorangpun tidak boleh keluar dari tempatnya pada hari ketujuh itu.\"', NULL),
(55709, 3648, 16, 30, 'Lalu beristirahatlah bangsa itu pada hari ketujuh.', NULL),
(55710, 3648, 16, 31, 'Umat Israel menyebutkan namanya: manna; warnanya putih seperti ketumbar dan rasanya seperti rasa kue madu.', NULL),
(55711, 3648, 16, 32, 'Musa berkata: \"Beginilah perintah TUHAN: Ambillah segomer penuh untuk disimpan turun-temurun, supaya keturunan mereka melihat roti yang Kuberi kamu makan di padang gurun, ketika Aku membawa kamu keluar dari tanah Mesir.\"', NULL),
(55712, 3648, 16, 33, 'Sebab itu Musa berkata kepada Harun: \"Ambillah sebuah buli-buli, taruhlah manna di dalamnya segomer penuh, dan tempatkanlah itu di hadapan TUHAN untuk disimpan turun-temurun.\"', NULL),
(55713, 3648, 16, 34, 'Seperti yang diperintahkan TUHAN kepada Musa, demikianlah buli-buli itu ditempatkan Harun di hadapan tabut hukum Allah untuk disimpan.', NULL),
(55714, 3648, 16, 35, 'Orang Israel makan manna empat puluh tahun lamanya, sampai mereka tiba di tanah yang didiami orang; mereka makan manna sampai tiba di perbatasan tanah Kanaan.', NULL),
(55715, 3648, 16, 36, 'Adapun segomer ialah sepersepuluh efa.', NULL),
(55716, 3648, 17, 1, 'Kemudian berangkatlah segenap jemaah Israel dari padang gurun Sin, berjalan dari tempat persinggahan ke tempat persinggahan, sesuai dengan titah TUHAN, lalu berkemahlah mereka di Rafidim, tetapi di sana tidak ada air untuk diminum bangsa itu.', 'Di Masa dan di Meriba'),
(55717, 3648, 17, 2, 'Jadi mulailah mereka itu bertengkar dengan Musa, kata mereka: \"Berikanlah air kepada kami, supaya kami dapat minum.\" Tetapi Musa berkata kepada mereka: \"Mengapakah kamu bertengkar dengan aku? Mengapakah kamu mencobai TUHAN?\"', NULL),
(55718, 3648, 17, 3, 'Hauslah bangsa itu akan air di sana; bersungut-sungutlah bangsa itu kepada Musa dan berkata: \"Mengapa pula engkau memimpin kami keluar dari Mesir, untuk membunuh kami, anak-anak kami dan ternak kami dengan kehausan?\"', NULL),
(55719, 3648, 17, 4, 'Lalu berseru-serulah Musa kepada TUHAN, katanya: \"Apakah yang akan kulakukan kepada bangsa ini? Sebentar lagi mereka akan melempari aku dengan batu!\"', NULL),
(55720, 3648, 17, 5, 'Berfirmanlah TUHAN kepada Musa: \"Berjalanlah di depan bangsa itu dan bawalah beserta engkau beberapa orang dari antara para tua-tua Israel; bawalah juga di tanganmu tongkatmu yang kaupakai memukul sungai Nil dan pergilah.', NULL),
(55721, 3648, 17, 6, 'Maka Aku akan berdiri di sana di depanmu di atas gunung batu di Horeb; haruslah kaupukul gunung batu itu dan dari dalamnya akan keluar air, sehingga bangsa itu dapat minum.\" Demikianlah diperbuat Musa di depan mata tua-tua Israel.', NULL),
(55722, 3648, 17, 7, 'Dinamailah tempat itu Masa dan Meriba, oleh karena orang Israel telah bertengkar dan oleh karena mereka telah mencobai TUHAN dengan mengatakan: \"Adakah TUHAN di tengah-tengah kita atau tidak?\"', NULL),
(55723, 3648, 17, 8, 'Lalu datanglah orang Amalek dan berperang melawan orang Israel di Rafidim.', 'Kemenangan orang Israel melawan orang Amalek'),
(55724, 3648, 17, 9, 'Musa berkata kepada Yosua: \"Pilihlah orang-orang bagi kita, lalu keluarlah berperang melawan orang Amalek, besok aku akan berdiri di puncak bukit itu dengan memegang tongkat Allah di tanganku.\"', NULL),
(55725, 3648, 17, 10, 'Lalu Yosua melakukan seperti yang dikatakan Musa kepadanya dan berperang melawan orang Amalek; tetapi Musa, Harun dan Hur telah naik ke puncak bukit.', NULL),
(55726, 3648, 17, 11, 'Dan terjadilah, apabila Musa mengangkat tangannya, lebih kuatlah Israel, tetapi apabila ia menurunkan tangannya, lebih kuatlah Amalek.', NULL),
(55727, 3648, 17, 12, 'Maka penatlah tangan Musa, sebab itu mereka mengambil sebuah batu, diletakkanlah di bawahnya, supaya ia duduk di atasnya; Harun dan Hur menopang kedua belah tangannya, seorang di sisi yang satu, seorang di sisi yang lain, sehingga tangannya tidak bergerak sampai matahari terbenam.', NULL),
(55728, 3648, 17, 13, 'Demikianlah Yosua mengalahkan Amalek dan rakyatnya dengan mata pedang.', NULL),
(55729, 3648, 17, 14, 'Kemudian berfirmanlah TUHAN kepada Musa: \"Tuliskanlah semuanya ini dalam sebuah kitab sebagai tanda peringatan, dan ingatkanlah ke telinga Yosua, bahwa Aku akan menghapuskan sama sekali ingatan kepada Amalek dari kolong langit.\"', NULL),
(55730, 3648, 17, 15, 'Lalu Musa mendirikan sebuah mezbah dan menamainya: \"Tuhanlah panji-panjiku!\"', NULL),
(55731, 3648, 17, 16, 'Ia berkata: \"Tangan di atas panji-panji TUHAN! TUHAN berperang melawan Amalek turun-temurun.\"', NULL),
(55732, 3648, 18, 1, 'Kedengaranlah kepada Yitro, imam di Midian, mertua Musa, segala yang dilakukan Allah kepada Musa dan kepada Israel, umat-Nya, yakni bahwa TUHAN telah membawa orang Israel keluar dari Mesir.', 'Yitro mengunjungi Musa'),
(55733, 3648, 18, 2, 'Lalu Yitro, mertua Musa, membawa serta Zipora, isteri Musa--yang dahulu disuruh Musa pulang--', NULL),
(55734, 3648, 18, 3, 'dan kedua anak laki-laki Zipora; yang seorang bernama Gersom, sebab kata Musa: \"Aku telah menjadi seorang pendatang di negeri asing,\"', NULL),
(55735, 3648, 18, 4, 'dan yang seorang lagi bernama Eliezer, sebab katanya: \"Allah bapaku adalah penolongku dan telah menyelamatkan aku dari pedang Firaun.\"', NULL),
(55736, 3648, 18, 5, 'Ketika Yitro, mertua Musa, beserta anak-anak dan isteri Musa sampai kepadanya di padang gurun, tempat ia berkemah dekat gunung Allah,', NULL),
(55737, 3648, 18, 6, 'disuruhnyalah mengatakan kepada Musa: \"Aku, mertuamu Yitro, datang kepadamu membawa isterimu beserta kedua anaknya.\"', NULL),
(55738, 3648, 18, 7, 'Lalu keluarlah Musa menyongsong mertuanya itu, sujudlah ia kepadanya dan menciumnya; mereka menanyakan keselamatan masing-masing, lalu masuk ke dalam kemah.', NULL),
(55739, 3648, 18, 8, 'Sesudah itu Musa menceritakan kepada mertuanya segala yang dilakukan TUHAN kepada Firaun dan kepada orang Mesir karena Israel dan segala kesusahan yang mereka alami di jalan dan bagaimana TUHAN menyelamatkan mereka.', NULL),
(55740, 3648, 18, 9, 'Bersukacitalah Yitro tentang segala kebaikan, yang dilakukan TUHAN kepada orang Israel, bahwa Ia telah menyelamatkan mereka dari tangan orang Mesir.', NULL),
(55741, 3648, 18, 10, 'Lalu kata Yitro: \"Terpujilah TUHAN, yang telah menyelamatkan kamu dari tangan orang Mesir dan dari tangan Firaun.', NULL),
(55742, 3648, 18, 11, 'Sekarang aku tahu, bahwa TUHAN lebih besar dari segala allah; sebab Ia telah menyelamatkan bangsa ini dari tangan orang Mesir, karena memang orang-orang ini telah bertindak angkuh terhadap mereka.\"', NULL),
(55743, 3648, 18, 12, 'Dan Yitro, mertua Musa, mempersembahkan korban bakaran dan beberapa korban sembelihan bagi Allah; lalu Harun dan semua tua-tua Israel datang untuk makan bersama-sama dengan mertua Musa di hadapan Allah.', NULL),
(55744, 3648, 18, 13, 'Keesokan harinya duduklah Musa mengadili di antara bangsa itu; dan bangsa itu berdiri di depan Musa, dari pagi sampai petang.', 'Pengangkatan hakim-hakim'),
(55745, 3648, 18, 14, 'Ketika mertua Musa melihat segala yang dilakukannya kepada bangsa itu, berkatalah ia: \"Apakah ini yang kaulakukan kepada bangsa itu? Mengapakah engkau seorang diri saja yang duduk, sedang seluruh bangsa itu berdiri di depanmu dari pagi sampai petang?\"', NULL),
(55746, 3648, 18, 15, 'Kata Musa kepada mertuanya itu: \"Sebab bangsa ini datang kepadaku untuk menanyakan petunjuk Allah.', NULL),
(55747, 3648, 18, 16, 'Apabila ada perkara di antara mereka, maka mereka datang kepadaku dan aku mengadili antara yang seorang dan yang lain; lagipula aku memberitahukan kepada mereka ketetapan-ketetapan dan keputusan-keputusan Allah.\"', NULL),
(55748, 3648, 18, 17, 'Tetapi mertua Musa menjawabnya: \"Tidak baik seperti yang kaulakukan itu.', NULL),
(55749, 3648, 18, 18, 'Engkau akan menjadi sangat lelah, baik engkau baik bangsa yang beserta engkau ini; sebab pekerjaan ini terlalu berat bagimu, takkan sanggup engkau melakukannya seorang diri saja.', NULL),
(55750, 3648, 18, 19, 'Jadi sekarang dengarkanlah perkataanku, aku akan memberi nasihat kepadamu dan Allah akan menyertai engkau. Adapun engkau, wakililah bangsa itu di hadapan Allah dan kauhadapkanlah perkara-perkara mereka kepada Allah.', NULL),
(55751, 3648, 18, 20, 'Kemudian haruslah engkau mengajarkan kepada mereka ketetapan-ketetapan dan keputusan-keputusan, dan memberitahukan kepada mereka jalan yang harus dijalani, dan pekerjaan yang harus dilakukan.', NULL),
(55752, 3648, 18, 21, 'Di samping itu kaucarilah dari seluruh bangsa itu orang-orang yang cakap dan takut akan Allah, orang-orang yang dapat dipercaya, dan yang benci kepada pengejaran suap; tempatkanlah mereka di antara bangsa itu menjadi pemimpin seribu orang, pemimpin seratus orang, pemimpin lima puluh orang dan pemimpin sepuluh orang.', NULL),
(55753, 3648, 18, 22, 'Dan sewaktu-waktu mereka harus mengadili di antara bangsa; maka segala perkara yang besar haruslah dihadapkan mereka kepadamu, tetapi segala perkara yang kecil diadili mereka sendiri; dengan demikian mereka meringankan pekerjaanmu, dan mereka bersama-sama dengan engkau turut menanggungnya.', NULL),
(55754, 3648, 18, 23, 'Jika engkau berbuat demikian dan Allah memerintahkan hal itu kepadamu, maka engkau akan sanggup menahannya, dan seluruh bangsa ini akan pulang dengan puas senang ke tempatnya.\"', NULL),
(55755, 3648, 18, 24, 'Musa mendengarkan perkataan mertuanya itu dan dilakukannyalah segala yang dikatakannya.', NULL),
(55756, 3648, 18, 25, 'Dari seluruh orang Israel Musa memilih orang-orang cakap dan mengangkat mereka menjadi kepala atas bangsa itu, menjadi pemimpin seribu orang, pemimpin seratus orang, pemimpin lima puluh orang dan pemimpin sepuluh orang.', NULL),
(55757, 3648, 18, 26, 'Mereka ini mengadili di antara bangsa itu sewaktu-waktu; perkara-perkara yang sukar dihadapkan mereka kepada Musa, tetapi perkara-perkara yang kecil diadili mereka sendiri.', NULL),
(55758, 3648, 18, 27, 'Kemudian Musa membiarkan mertuanya itu pergi dan ia pulang ke negerinya.', NULL),
(57787, 3648, 19, 1, 'Pada bulan ketiga setelah orang Israel keluar dari tanah Mesir, mereka tiba di padang gurun Sinai pada hari itu juga.', 'TUHAN menampakkan diri di gunung Sinai'),
(57788, 3648, 19, 2, 'Setelah mereka berangkat dari Rafidim, tibalah mereka di padang gurun Sinai, lalu mereka berkemah di padang gurun; orang Israel berkemah di sana di depan gunung itu.', NULL),
(57789, 3648, 19, 3, 'Lalu naiklah Musa menghadap Allah, dan TUHAN berseru dari gunung itu kepadanya: \"Beginilah kaukatakan kepada keturunan Yakub dan kauberitakan kepada orang Israel:', NULL),
(57790, 3648, 19, 4, 'Kamu sendiri telah melihat apa yang Kulakukan kepada orang Mesir, dan bagaimana Aku telah mendukung kamu di atas sayap rajawali dan membawa kamu kepada-Ku.', NULL),
(57791, 3648, 19, 5, 'Jadi sekarang, jika kamu sungguh-sungguh mendengarkan firman-Ku dan berpegang pada perjanjian-Ku, maka kamu akan menjadi harta kesayangan-Ku sendiri dari antara segala bangsa, sebab Akulah yang empunya seluruh bumi.', NULL),
(57792, 3648, 19, 6, 'Kamu akan menjadi bagi-Ku kerajaan imam dan bangsa yang kudus. Inilah semuanya firman yang harus kaukatakan kepada orang Israel.\"', NULL),
(57793, 3648, 19, 7, 'Lalu datanglah Musa dan memanggil para tua-tua bangsa itu dan membawa ke depan mereka segala firman yang diperintahkan TUHAN kepadanya.', NULL),
(57794, 3648, 19, 8, 'Seluruh bangsa itu menjawab bersama-sama: \"Segala yang difirmankan TUHAN akan kami lakukan.\" Lalu Musapun menyampaikan jawab bangsa itu kepada TUHAN.', NULL),
(57795, 3648, 19, 9, 'Berfirmanlah TUHAN kepada Musa: \"Sesungguhnya Aku akan datang kepadamu dalam awan yang tebal, dengan maksud supaya dapat didengar oleh bangsa itu apabila Aku berbicara dengan engkau, dan juga supaya mereka senantiasa percaya kepadamu.\" Lalu Musa memberitahukan perkataan bangsa itu kepada TUHAN.', NULL),
(57796, 3648, 19, 10, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah kepada bangsa itu; suruhlah mereka menguduskan diri pada hari ini dan besok, dan mereka harus mencuci pakaiannya.', NULL),
(57797, 3648, 19, 11, 'Menjelang hari ketiga mereka harus bersiap, sebab pada hari ketiga TUHAN akan turun di depan mata seluruh bangsa itu di gunung Sinai.', NULL),
(57798, 3648, 19, 12, 'Sebab itu haruslah engkau memasang batas bagi bangsa itu berkeliling sambil berkata: Jagalah baik-baik, jangan kamu mendaki gunung itu atau kena kepada kakinya, sebab siapapun yang kena kepada gunung itu, pastilah ia dihukum mati.', NULL),
(57799, 3648, 19, 13, 'Tangan seorangpun tidak boleh merabanya, sebab pastilah ia dilempari dengan batu atau dipanahi sampai mati; baik binatang baik manusia, ia tidak akan dibiarkan hidup. Hanya apabila sangkakala berbunyi panjang, barulah mereka boleh mendaki gunung itu.\"', NULL),
(57800, 3648, 19, 14, 'Lalu turunlah Musa dari gunung mendapatkan bangsa itu; disuruhnyalah bangsa itu menguduskan diri dan merekapun mencuci pakaiannya.', NULL),
(57801, 3648, 19, 15, 'Maka kata Musa kepada bangsa itu: \"Bersiaplah menjelang hari yang ketiga, dan janganlah kamu bersetubuh dengan perempuan.\"', NULL),
(57802, 3648, 19, 16, 'Dan terjadilah pada hari ketiga, pada waktu terbit fajar, ada guruh dan kilat dan awan padat di atas gunung dan bunyi sangkakala yang sangat keras, sehingga gemetarlah seluruh bangsa yang ada di perkemahan.', NULL),
(57803, 3648, 19, 17, 'Lalu Musa membawa bangsa itu keluar dari perkemahan untuk menjumpai Allah dan berdirilah mereka pada kaki gunung.', NULL),
(57804, 3648, 19, 18, 'Gunung Sinai ditutupi seluruhnya dengan asap, karena TUHAN turun ke atasnya dalam api; asapnya membubung seperti asap dari dapur, dan seluruh gunung itu gemetar sangat.', NULL),
(57805, 3648, 19, 19, 'Bunyi sangkakala kian lama kian keras. Berbicaralah Musa, lalu Allah menjawabnya dalam guruh.', NULL),
(57806, 3648, 19, 20, 'Lalu turunlah TUHAN ke atas gunung Sinai, ke atas puncak gunung itu, maka TUHAN memanggil Musa ke puncak gunung itu, dan naiklah Musa ke atas.', NULL),
(57807, 3648, 19, 21, 'Kemudian TUHAN berfirman kepada Musa: \"Turunlah, peringatkanlah kepada bangsa itu, supaya mereka jangan menembus mendapatkan TUHAN hendak melihat-lihat; sebab tentulah banyak dari mereka akan binasa.', NULL),
(57808, 3648, 19, 22, 'Juga para imam yang datang mendekat kepada TUHAN haruslah menguduskan dirinya, supaya TUHAN jangan melanda mereka.\"', NULL),
(57809, 3648, 19, 23, 'Lalu berkatalah Musa kepada TUHAN: \"Tidak akan mungkin bangsa itu mendaki gunung Sinai ini, sebab Engkau sendiri telah memperingatkan kepada kami, demikian: Pasanglah batas sekeliling gunung itu dan nyatakanlah itu kudus.\"', NULL),
(57810, 3648, 19, 24, 'Lalu TUHAN berfirman kepadanya: \"Pergilah, turunlah, kemudian naiklah pula, engkau beserta Harun; tetapi para imam dan rakyat tidak boleh menembus untuk mendaki menghadap TUHAN, supaya mereka jangan dilanda-Nya.\"', NULL),
(57811, 3648, 19, 25, 'Lalu turunlah Musa mendapatkan bangsa itu dan menyatakan hal itu kepada mereka.', NULL),
(57813, 3648, 20, 2, '\"Akulah TUHAN, Allahmu, yang membawa engkau keluar dari tanah Mesir, dari tempat perbudakan.', NULL),
(57814, 3648, 20, 3, 'Jangan ada padamu allah lain di hadapan-Ku.', NULL),
(57815, 3648, 20, 4, 'Jangan membuat bagimu patung yang menyerupai apapun yang ada di langit di atas, atau yang ada di bumi di bawah, atau yang ada di dalam air di bawah bumi.', NULL),
(57816, 3648, 20, 5, 'Jangan sujud menyembah kepadanya atau beribadah kepadanya, sebab Aku, TUHAN, Allahmu, adalah Allah yang cemburu, yang membalaskan kesalahan bapa kepada anak-anaknya, kepada keturunan yang ketiga dan keempat dari orang-orang yang membenci Aku,', NULL),
(57817, 3648, 20, 6, 'tetapi Aku menunjukkan kasih setia kepada beribu-ribu orang, yaitu mereka yang mengasihi Aku dan yang berpegang pada perintah-perintah-Ku.', NULL),
(57818, 3648, 20, 7, 'Jangan menyebut nama TUHAN, Allahmu, dengan sembarangan, sebab TUHAN akan memandang bersalah orang yang menyebut nama-Nya dengan sembarangan.', NULL),
(57819, 3648, 20, 8, 'Ingatlah dan kuduskanlah hari Sabat:', NULL),
(57820, 3648, 20, 9, 'enam hari lamanya engkau akan bekerja dan melakukan segala pekerjaanmu,', NULL),
(57821, 3648, 20, 10, 'tetapi hari ketujuh adalah hari Sabat TUHAN, Allahmu; maka jangan melakukan sesuatu pekerjaan, engkau atau anakmu laki-laki, atau anakmu perempuan, atau hambamu laki-laki, atau hambamu perempuan, atau hewanmu atau orang asing yang di tempat kediamanmu.', NULL),
(57822, 3648, 20, 11, 'Sebab enam hari lamanya TUHAN menjadikan langit dan bumi, laut dan segala isinya, dan Ia berhenti pada hari ketujuh; itulah sebabnya TUHAN memberkati hari Sabat dan menguduskannya.', NULL),
(57823, 3648, 20, 12, 'Hormatilah ayahmu dan ibumu, supaya lanjut umurmu di tanah yang diberikan TUHAN, Allahmu, kepadamu.', NULL),
(57824, 3648, 20, 13, 'Jangan membunuh.', NULL),
(57825, 3648, 20, 14, 'Jangan berzinah.', NULL),
(57826, 3648, 20, 15, 'Jangan mencuri.', NULL),
(57827, 3648, 20, 16, 'Jangan mengucapkan saksi dusta tentang sesamamu.', NULL),
(57828, 3648, 20, 17, 'Jangan mengingini rumah sesamamu; jangan mengingini isterinya, atau hambanya laki-laki, atau hambanya perempuan, atau lembunya atau keledainya, atau apapun yang dipunyai sesamamu.\"', NULL),
(57829, 3648, 20, 18, 'Seluruh bangsa itu menyaksikan guruh mengguntur, kilat sabung-menyabung, sangkakala berbunyi dan gunung berasap. Maka bangsa itu takut dan gemetar dan mereka berdiri jauh-jauh.', 'Orang Israel takut menghadapi kedatangan TUHAN'),
(57830, 3648, 20, 19, 'Mereka berkata kepada Musa: \"Engkaulah berbicara dengan kami, maka kami akan mendengarkan; tetapi janganlah Allah berbicara dengan kami, nanti kami mati.\"', NULL),
(57831, 3648, 20, 20, 'Tetapi Musa berkata kepada bangsa itu: \"Janganlah takut, sebab Allah telah datang dengan maksud untuk mencoba kamu dan dengan maksud supaya takut akan Dia ada padamu, agar kamu jangan berbuat dosa.\"', NULL),
(57832, 3648, 20, 21, 'Adapun bangsa itu berdiri jauh-jauh, tetapi Musa pergi mendekati embun yang kelam di mana Allah ada.', NULL),
(57833, 3648, 20, 22, 'Lalu berfirmanlah TUHAN kepada Musa: \"Beginilah kaukatakan kepada orang Israel: Kamu sendiri telah menyaksikan, bahwa Aku berbicara dengan kamu dari langit.', 'Peraturan tentang kebaktian'),
(57834, 3648, 20, 23, 'Janganlah kamu membuat di samping-Ku allah perak, juga allah emas janganlah kamu buat bagimu.', NULL),
(57835, 3648, 20, 24, 'Kaubuatlah bagi-Ku mezbah dari tanah dan persembahkanlah di atasnya korban bakaranmu dan korban keselamatanmu, kambing dombamu dan lembu sapimu. Pada setiap tempat yang Kutentukan menjadi tempat peringatan bagi nama-Ku, Aku akan datang kepadamu dan memberkati engkau.', NULL),
(57836, 3648, 20, 25, 'Tetapi jika engkau membuat bagi-Ku mezbah dari batu, maka jangan engkau mendirikannya dari batu pahat, sebab apabila engkau mengerjakannya dengan beliung, maka engkau melanggar kekudusannya.', NULL),
(57837, 3648, 20, 26, 'Juga jangan engkau naik tangga ke atas ke mezbah-Ku, supaya auratmu jangan kelihatan di atasnya.\"', NULL),
(59916, 3648, 21, 1, '\"Inilah peraturan-peraturan yang harus kaubawa ke depan mereka.', 'Tentang hak budak Ibrani'),
(59917, 3648, 21, 2, 'Apabila engkau membeli seorang budak Ibrani, maka haruslah ia bekerja padamu enam tahun lamanya, tetapi pada tahun yang ketujuh ia diizinkan keluar sebagai orang merdeka, dengan tidak membayar tebusan apa-apa.', NULL),
(59918, 3648, 21, 3, 'Jika ia datang seorang diri saja, maka keluarpun ia seorang diri; jika ia mempunyai isteri, maka isterinya itu diizinkan keluar bersama-sama dengan dia.', NULL),
(59919, 3648, 21, 4, 'Jika tuannya memberikan kepadanya seorang isteri dan perempuan itu melahirkan anak-anak lelaki atau perempuan, maka perempuan itu dengan anak-anaknya tetap menjadi kepunyaan tuannya, dan budak laki-laki itu harus keluar seorang diri.', NULL),
(59920, 3648, 21, 5, 'Tetapi jika budak itu dengan sungguh-sungguh berkata: Aku cinta kepada tuanku, kepada isteriku dan kepada anak-anakku, aku tidak mau keluar sebagai orang merdeka,', NULL),
(59921, 3648, 21, 6, 'maka haruslah tuannya itu membawanya menghadap Allah, lalu membawanya ke pintu atau ke tiang pintu, dan tuannya itu menusuk telinganya dengan penusuk, dan budak itu bekerja pada tuannya untuk seumur hidup.', NULL),
(59922, 3648, 21, 7, 'Apabila ada seorang menjual anaknya yang perempuan sebagai budak, maka perempuan itu tidak boleh keluar seperti cara budak-budak lelaki keluar.', NULL),
(59923, 3648, 21, 8, 'Jika perempuan itu tidak disukai tuannya, yang telah menyediakannya bagi dirinya sendiri, maka haruslah tuannya itu mengizinkan ia ditebus; tuannya itu tidak berhak untuk menjualnya kepada bangsa asing, karena ia memungkiri janjinya kepada perempuan itu.', NULL),
(59924, 3648, 21, 9, 'Jika tuannya itu menyediakannya bagi anaknya laki-laki, maka haruslah tuannya itu memperlakukannya seperti anak-anak perempuan berhak diperlakukan.', NULL),
(59925, 3648, 21, 10, 'Jika tuannya itu mengambil perempuan lain, ia tidak boleh mengurangi makanan perempuan itu, pakaiannya dan persetubuhan dengan dia.', NULL),
(59926, 3648, 21, 11, 'Jika tuannya itu tidak melakukan ketiga hal itu kepadanya, maka perempuan itu harus diizinkan keluar, dengan tidak membayar uang tebusan apa-apa.\"', NULL),
(59927, 3648, 21, 12, '\"Siapa yang memukul seseorang, sehingga mati, pastilah ia dihukum mati.', 'Peraturan tentang jaminan nyawa sesama manusia'),
(59928, 3648, 21, 13, 'Tetapi jika pembunuhan itu tidak disengaja, melainkan tangannya ditentukan Allah melakukan itu, maka Aku akan menunjukkan bagimu suatu tempat, ke mana ia dapat lari.', NULL),
(59929, 3648, 21, 14, 'Tetapi apabila seseorang berlaku angkara terhadap sesamanya, hingga ia membunuhnya dengan tipu daya, maka engkau harus mengambil orang itu dari mezbah-Ku, supaya ia mati dibunuh.', NULL),
(59930, 3648, 21, 15, 'Siapa yang memukul ayahnya atau ibunya, pastilah ia dihukum mati.', NULL),
(59931, 3648, 21, 16, 'Siapa yang menculik seorang manusia, baik ia telah menjualnya, baik orang itu masih terdapat padanya, ia pasti dihukum mati.', NULL),
(59932, 3648, 21, 17, 'Siapa yang mengutuki ayahnya atau ibunya, ia pasti dihukum mati.', NULL),
(59933, 3648, 21, 18, 'Apabila ada orang bertengkar dan yang seorang memukul yang lain dengan batu atau dengan tinjunya, sehingga yang lain itu memang tidak mati, tetapi terpaksa berbaring di tempat tidur,', NULL),
(59934, 3648, 21, 19, 'maka orang yang memukul itu bebas dari hukuman, jika yang lain itu dapat bangkit lagi dan dapat berjalan di luar dengan memakai tongkat; hanya ia harus membayar kerugian orang yang lain itu, karena terpaksa menganggur, dan menanggung pengobatannya sampai sembuh.', NULL),
(59935, 3648, 21, 20, 'Apabila seseorang memukul budaknya laki-laki atau perempuan dengan tongkat, sehingga mati karena pukulan itu, pastilah budak itu dibalaskan.', NULL),
(59936, 3648, 21, 21, 'Hanya jika budak itu masih hidup sehari dua, maka janganlah dituntut belanya, sebab budak itu adalah miliknya sendiri.', NULL),
(59937, 3648, 21, 22, 'Apabila ada orang berkelahi dan seorang dari mereka tertumbuk kepada seorang perempuan yang sedang mengandung, sehingga keguguran kandungan, tetapi tidak mendapat kecelakaan yang membawa maut, maka pastilah ia didenda sebanyak yang dikenakan oleh suami perempuan itu kepadanya, dan ia harus membayarnya menurut putusan hakim.', NULL),
(59938, 3648, 21, 23, 'Tetapi jika perempuan itu mendapat kecelakaan yang membawa maut, maka engkau harus memberikan nyawa ganti nyawa,', NULL),
(59939, 3648, 21, 24, 'mata ganti mata, gigi ganti gigi, tangan ganti tangan, kaki ganti kaki,', NULL),
(59940, 3648, 21, 25, 'lecur ganti lecur, luka ganti luka, bengkak ganti bengkak.', NULL),
(59941, 3648, 21, 26, 'Apabila seseorang memukul mata budaknya laki-laki atau mata budaknya perempuan dan merusakkannya, maka ia harus melepaskan budak itu sebagai orang merdeka pengganti kerusakan matanya itu.', NULL),
(59942, 3648, 21, 27, 'Dan jika ia menumbuk sampai tanggal gigi budaknya laki-laki atau gigi budaknya perempuan, maka ia harus melepaskan budak itu sebagai orang merdeka pengganti kehilangan giginya itu.', NULL),
(59943, 3648, 21, 28, 'Apabila seekor lembu menanduk seorang laki-laki atau perempuan, sehingga mati, maka pastilah lembu itu dilempari mati dengan batu dan dagingnya tidak boleh dimakan, tetapi pemilik lembu itu bebas dari hukuman.', NULL),
(59944, 3648, 21, 29, 'Tetapi jika lembu itu sejak dahulu telah sering menanduk dan pemiliknya telah diperingatkan, tetapi tidak mau menjaganya, kemudian lembu itu menanduk mati seorang laki-laki atau perempuan, maka lembu itu harus dilempari mati dengan batu, tetapi pemiliknyapun harus dihukum mati.', NULL),
(59945, 3648, 21, 30, 'Jika dibebankan kepadanya uang pendamaian, maka haruslah dibayarnya segala yang dibebankan kepadanya itu sebagai tebusan nyawanya.', NULL),
(59946, 3648, 21, 31, 'Kalau ditanduknya seorang anak laki-laki atau perempuan, maka pemiliknya harus diperlakukan menurut peraturan itu juga.', NULL),
(59947, 3648, 21, 32, 'Tetapi jika lembu itu menanduk seorang budak laki-laki atau perempuan, maka pemiliknya harus membayar tiga puluh syikal perak kepada tuan budak itu, dan lembu itu harus dilempari mati dengan batu.', NULL),
(59948, 3648, 21, 33, 'Apabila seseorang membuka sumur, atau apabila seseorang menggali sumur, dengan tidak menutupnya, dan seekor lembu atau keledai jatuh ke dalamnya,', NULL),
(59949, 3648, 21, 34, 'maka pemilik sumur itu harus membayar ganti kerugian: ia harus mengganti harga binatang itu dengan uang kepada pemiliknya, tetapi binatang yang mati itu menjadi kepunyaannya.', NULL),
(59950, 3648, 21, 35, 'Apabila lembu seseorang menanduk lembu orang lain, sehingga mati, maka lembu yang hidup itu harus dijual, uangnya dibagi dan binatang yang mati itupun harus dibagi juga.', NULL),
(59951, 3648, 21, 36, 'Tetapi jikalau lembu itu terkenal telah sering menanduk sejak dahulu, dan walaupun demikian pemiliknya tidak mau menjaganya, maka ia harus membayar ganti kerugian sepenuhnya: lembu ganti lembu, tetapi binatang yang mati itu menjadi kepunyaannya.\"', NULL),
(62066, 3648, 22, 1, '\"Apabila seseorang mencuri seekor lembu atau seekor domba dan membantainya atau menjualnya, maka ia harus membayar gantinya, yakni lima ekor lembu ganti lembu itu dan empat ekor domba ganti domba itu.', 'Peraturan tentang jaminan harta sesama manusia'),
(62067, 3648, 22, 2, 'Jika seorang pencuri kedapatan waktu membongkar, dan ia dipukul orang sehingga mati, maka si pemukul tidak berhutang darah;', NULL),
(62068, 3648, 22, 3, 'tetapi jika pembunuhan itu terjadi setelah matahari terbit, maka ia berhutang darah. Pencuri itu harus membayar ganti kerugian sepenuhnya; jika ia orang yang tak punya, ia harus dijual ganti apa yang dicurinya itu.', NULL),
(62069, 3648, 22, 4, 'Jika yang dicurinya itu masih terdapat padanya dalam keadaan hidup, baik lembu, keledai atau domba, maka ia harus membayar ganti kerugian dua kali lipat.', NULL),
(62070, 3648, 22, 5, 'Apabila seseorang menggembalakan ternaknya di ladangnya atau di kebun anggurnya dan ternak itu dibiarkannya berjalan lepas, sehingga makan habis ladang orang lain, maka ia harus memberikan hasil yang terbaik dari ladangnya sendiri atau hasil yang terbaik dari kebun anggurnya sebagai ganti kerugian.', NULL),
(62071, 3648, 22, 6, 'Apabila ada api dinyalakan dan api itu menjilat semak duri, tetapi tumpukan gandum atau gandum yang belum dituai atau seluruh ladang itu ikut juga dimakan api, maka orang yang menyebabkan kebakaran itu harus membayar ganti kerugian sepenuhnya.', NULL),
(62072, 3648, 22, 7, 'Apabila seseorang menitipkan kepada temannya uang atau barang, dan itu dicuri dari rumah orang itu, maka jika pencuri itu terdapat, ia harus membayar ganti kerugian dua kali lipat.', NULL),
(62073, 3648, 22, 8, 'Jika pencuri itu tidak terdapat, maka tuan rumah harus pergi menghadap Allah untuk bersumpah, bahwa ia tidak mengulurkan tangannya mengambil harta kepunyaan temannya.', NULL),
(62074, 3648, 22, 9, 'Dalam tiap-tiap perkara pertengkaran harta, baik tentang seekor lembu, tentang seekor keledai, tentang seekor domba, tentang sehelai pakaian, baik tentang barang apapun yang kehilangan, kalau seorang mengatakan: Inilah kepunyaanku--maka perkara kedua orang itu harus dibawa ke hadapan Allah. Siapa yang dipersalahkan oleh Allah haruslah membayar kepada temannya ganti kerugian dua kali lipat.', NULL),
(62075, 3648, 22, 10, 'Apabila seseorang menitipkan kepada temannya seekor keledai atau lembu atau seekor domba atau binatang apapun dan binatang itu mati, atau patah kakinya atau dihalau orang dengan kekerasan, dengan tidak ada orang yang melihatnya,', NULL),
(62076, 3648, 22, 11, 'maka sumpah di hadapan TUHAN harus menentukan di antara kedua orang itu, apakah ia tidak mengulurkan tangannya mengambil harta kepunyaan temannya, dan pemilik harus menerima sumpah itu, dan yang lain itu tidak usah membayar ganti kerugian.', NULL),
(62077, 3648, 22, 12, 'Tetapi jika binatang itu benar-benar dicuri orang dari padanya, maka ia harus membayar ganti kerugian kepada pemilik.', NULL),
(62078, 3648, 22, 13, 'Jika binatang itu benar-benar diterkam oleh binatang buas, maka ia harus membawanya sebagai bukti. Tidak usah ia membayar ganti binatang yang diterkam itu.', NULL),
(62079, 3648, 22, 14, 'Apabila seseorang meminjam seekor binatang dari temannya, dan binatang itu patah kakinya atau mati, ketika pemiliknya tidak ada di situ, maka ia harus membayar ganti kerugian sepenuhnya.', NULL),
(62080, 3648, 22, 15, 'Tetapi jika pemiliknya ada di situ, maka tidak usahlah ia membayar ganti kerugian. Jika binatang itu disewa, maka kerugian itu telah termasuk dalam sewa.', NULL),
(62081, 3648, 22, 16, 'Apabila seseorang membujuk seorang anak perawan yang belum bertunangan, dan tidur dengan dia, maka haruslah ia mengambilnya menjadi isterinya dengan membayar mas kawin.', NULL),
(62082, 3648, 22, 17, 'Jika ayah perempuan itu sungguh-sungguh menolak memberikannya kepadanya, maka ia harus juga membayar perak itu sepenuhnya, sebanyak mas kawin anak perawan.\"', NULL),
(62083, 3648, 22, 18, '\"Seorang ahli sihir perempuan janganlah engkau biarkan hidup.', 'Peraturan tentang dosa yang keji'),
(62084, 3648, 22, 19, 'Siapapun yang tidur dengan seekor binatang, pastilah ia dihukum mati.', NULL),
(62085, 3648, 22, 20, 'Siapa yang mempersembahkan korban kepada allah kecuali kepada TUHAN sendiri, haruslah ia ditumpas.\"', NULL),
(62086, 3648, 22, 21, '\"Janganlah kautindas atau kautekan seorang orang asing, sebab kamupun dahulu adalah orang asing di tanah Mesir.', 'Peraturan tentang orang-orang yang tidak mampu'),
(62087, 3648, 22, 22, 'Seseorang janda atau anak yatim janganlah kamu tindas.', NULL),
(62088, 3648, 22, 23, 'Jika engkau memang menindas mereka ini, tentulah Aku akan mendengarkan seruan mereka, jika mereka berseru-seru kepada-Ku dengan nyaring.', NULL),
(62089, 3648, 22, 24, 'Maka murka-Ku akan bangkit dan Aku akan membunuh kamu dengan pedang, sehingga isteri-isterimu menjadi janda dan anak-anakmu menjadi yatim.', NULL),
(62090, 3648, 22, 25, 'Jika engkau meminjamkan uang kepada salah seorang dari umat-Ku, orang yang miskin di antaramu, maka janganlah engkau berlaku sebagai seorang penagih hutang terhadap dia: janganlah kamu bebankan bunga uang kepadanya.', NULL),
(62091, 3648, 22, 26, 'Jika engkau sampai mengambil jubah temanmu sebagai gadai, maka haruslah engkau mengembalikannya kepadanya sebelum matahari terbenam,', NULL),
(62092, 3648, 22, 27, 'sebab hanya itu saja penutup tubuhnya, itulah pemalut kulitnya--pakai apakah ia pergi tidur? Maka apabila ia berseru-seru kepada-Ku, Aku akan mendengarkannya, sebab Aku ini pengasih.\"', NULL),
(62093, 3648, 22, 28, '\"Janganlah engkau mengutuki Allah dan janganlah engkau menyumpahi seorang pemuka di tengah-tengah bangsamu.', 'Berbagai-bagai peraturan'),
(62094, 3648, 22, 29, 'Janganlah lalai mempersembahkan hasil gandummu dan hasil anggurmu. Yang sulung dari anak-anakmu lelaki haruslah kaupersembahkan kepada-Ku.', NULL),
(62095, 3648, 22, 30, 'Demikian juga harus kauperbuat dengan lembu sapimu dan dengan kambing dombamu: tujuh hari lamanya anak-anak binatang itu harus tinggal pada induknya, tetapi pada hari yang kedelapan haruslah kaupersembahkan binatang-binatang itu kepada-Ku.', NULL),
(62096, 3648, 22, 31, 'Haruslah kamu menjadi orang-orang kudus bagi-Ku: daging ternak yang diterkam di padang oleh binatang buas, janganlah kamu makan, tetapi haruslah kamu lemparkan kepada anjing.\"', NULL),
(62097, 3648, 23, 1, '\"Janganlah engkau menyebarkan kabar bohong; janganlah engkau membantu orang yang bersalah dengan menjadi saksi yang tidak benar.', 'Peraturan tentang hak-hak manusia'),
(62098, 3648, 23, 2, 'Janganlah engkau turut-turut kebanyakan orang melakukan kejahatan, dan dalam memberikan kesaksian mengenai sesuatu perkara janganlah engkau turut-turut kebanyakan orang membelokkan hukum.', NULL),
(62099, 3648, 23, 3, 'Juga janganlah memihak kepada orang miskin dalam perkaranya.', NULL),
(62100, 3648, 23, 4, 'Apabila engkau melihat lembu musuhmu atau keledainya yang sesat, maka segeralah kaukembalikan binatang itu.', NULL),
(62101, 3648, 23, 5, 'Apabila engkau melihat rebah keledai musuhmu karena berat bebannya, maka janganlah engkau enggan menolongnya. Haruslah engkau rela menolong dia dengan membongkar muatan keledainya.', NULL),
(62102, 3648, 23, 6, 'Janganlah engkau memperkosa hak orang miskin di antaramu dalam perkaranya.', NULL),
(62103, 3648, 23, 7, 'Haruslah kaujauhkan dirimu dari perkara dusta. Orang yang tidak bersalah dan orang yang benar tidak boleh kaubunuh, sebab Aku tidak akan membenarkan orang yang bersalah.', NULL),
(62104, 3648, 23, 8, 'Suap janganlah kauterima, sebab suap membuat buta mata orang-orang yang melihat dan memutarbalikkan perkara orang-orang yang benar.', NULL),
(62105, 3648, 23, 9, 'Orang asing janganlah kamu tekan, karena kamu sendiri telah mengenal keadaan jiwa orang asing, sebab kamupun dahulu adalah orang asing di tanah Mesir.', NULL),
(62106, 3648, 23, 10, 'Enam tahunlah lamanya engkau menabur di tanahmu dan mengumpulkan hasilnya,', NULL),
(62107, 3648, 23, 11, 'tetapi pada tahun ketujuh haruslah engkau membiarkannya dan meninggalkannya begitu saja, supaya orang miskin di antara bangsamu dapat makan, dan apa yang ditinggalkan mereka haruslah dibiarkan dimakan binatang hutan. Demikian juga kaulakukan dengan kebun anggurmu dan kebun zaitunmu.', NULL),
(62108, 3648, 23, 12, 'Enam harilah lamanya engkau melakukan pekerjaanmu, tetapi pada hari ketujuh haruslah engkau berhenti, supaya lembu dan keledaimu tidak bekerja dan supaya anak budakmu perempuan dan orang asing melepaskan lelah.', NULL),
(62109, 3648, 23, 13, 'Dalam segala hal yang Kufirmankan kepadamu haruslah kamu berawas-awas; nama allah lain janganlah kamu panggil, janganlah nama itu kedengaran dari mulutmu.\"', NULL),
(62110, 3648, 23, 14, '\"Tiga kali setahun haruslah engkau mengadakan perayaan bagi-Ku.', 'Peraturan tentang kebaktian dan hari-hari raya'),
(62111, 3648, 23, 15, 'Hari raya Roti Tidak Beragi haruslah kaupelihara; tujuh hari lamanya engkau harus makan roti yang tidak beragi, seperti yang telah Kuperintahkan kepadamu, pada waktu yang ditetapkan dalam bulan Abib, sebab dalam bulan itulah engkau keluar dari Mesir, tetapi janganlah orang menghadap ke hadirat-Ku dengan tangan hampa.', NULL),
(62112, 3648, 23, 16, 'Kaupeliharalah juga hari raya menuai, yakni menuai buah bungaran dari hasil usahamu menabur di ladang; demikian juga hari raya pengumpulan hasil pada akhir tahun, apabila engkau mengumpulkan hasil usahamu dari ladang.', NULL),
(62113, 3648, 23, 17, 'Tiga kali setahun semua orangmu yang laki-laki harus menghadap ke hadirat Tuhanmu TUHAN.', NULL),
(62114, 3648, 23, 18, 'Janganlah kaupersembahkan darah korban sembelihan yang kepada-Ku beserta sesuatu yang beragi, dan janganlah lemak korban hari raya-Ku bermalam sampai pagi.', NULL),
(62115, 3648, 23, 19, 'Yang terbaik dari buah bungaran hasil tanahmu haruslah kaubawa ke dalam rumah TUHAN, Allahmu. Janganlah kaumasak anak kambing dalam susu induknya.\"', NULL),
(62116, 3648, 23, 20, '\"Sesungguhnya Aku mengutus seorang malaikat berjalan di depanmu, untuk melindungi engkau di jalan dan untuk membawa engkau ke tempat yang telah Kusediakan.', 'Janji dan tegoran kepada Israel'),
(62117, 3648, 23, 21, 'Jagalah dirimu di hadapannya dan dengarkanlah perkataannya, janganlah engkau mendurhaka kepadanya, sebab pelanggaranmu tidak akan diampuninya, sebab nama-Ku ada di dalam dia.', NULL),
(62118, 3648, 23, 22, 'Tetapi jika engkau sungguh-sungguh mendengarkan perkataannya, dan melakukan segala yang Kufirmankan, maka Aku akan memusuhi musuhmu, dan melawan lawanmu.', NULL),
(62119, 3648, 23, 23, 'Sebab malaikat-Ku akan berjalan di depanmu dan membawa engkau kepada orang Amori, orang Het, orang Feris, orang Kanaan, orang Hewi dan orang Yebus, dan Aku akan melenyapkan mereka.', NULL),
(62120, 3648, 23, 24, 'Janganlah engkau sujud menyembah kepada allah mereka atau beribadah kepadanya, dan janganlah engkau meniru perbuatan mereka, tetapi haruslah engkau memusnahkan sama sekali patung-patung berhala buatan mereka, dan tugu-tugu berhala mereka haruslah kauremukkan sama sekali.', NULL),
(62121, 3648, 23, 25, 'Tetapi kamu harus beribadah kepada TUHAN, Allahmu; maka Ia akan memberkati roti makananmu dan air minumanmu dan Aku akan menjauhkan penyakit dari tengah-tengahmu.', NULL),
(62122, 3648, 23, 26, 'Tidak akan ada di negerimu perempuan yang keguguran atau mandul. Aku akan menggenapkan tahun umurmu.', NULL),
(62123, 3648, 23, 27, 'Kengerian terhadap Aku akan Kukirimkan mendahului engkau: Aku akan mengacaukan semua orang yang kaudatangi, dan Aku akan membuat semua musuhmu lari membelakangi engkau.', NULL),
(62124, 3648, 23, 28, 'Lagi Aku akan melepaskan tabuhan mendahului engkau, sehingga binatang-binatang itu menghalau orang Hewi, orang Kanaan dan orang Het itu dari depanmu.', NULL),
(62125, 3648, 23, 29, 'Aku tidak akan menghalau mereka dari depanmu dalam satu tahun, supaya negeri itu jangan menjadi sepi, dan segala binatang hutan jangan bertambah banyak melebihi engkau.', NULL),
(62126, 3648, 23, 30, 'Sedikit demi sedikit Aku akan menghalau mereka dari depanmu, sampai engkau beranak cucu sedemikian, hingga engkau dapat memiliki negeri itu.', NULL),
(62127, 3648, 23, 31, 'Aku akan menentukan batas daerahmu dari Laut Teberau sampai Laut Filistin dan dari padang gurun sampai sungai Efrat, sebab Aku akan menyerahkan penduduk negeri itu ke dalam tanganmu, sehingga engkau menghalau mereka dari depanmu.', NULL),
(62128, 3648, 23, 32, 'Janganlah mengadakan perjanjian dengan mereka ataupun dengan allah mereka.', NULL),
(62129, 3648, 23, 33, 'Mereka tidak akan tetap diam di negerimu, supaya mereka jangan membuat engkau berdosa kepada-Ku, dengan beribadah kepada allah mereka, sebab tentulah hal itu menjadi jerat bagimu.\"', NULL),
(64308, 3648, 24, 1, 'Berfirmanlah Ia kepada Musa: \"Naiklah menghadap TUHAN, engkau dan Harun, Nadab dan Abihu dan tujuh puluh orang dari para tua-tua Israel dan sujudlah kamu menyembah dari jauh.', 'Upacara pengikatan perjanjian antara TUHAN dengan bangsa Israel'),
(64309, 3648, 24, 2, 'Hanya Musa sendirilah yang mendekat kepada TUHAN, tetapi mereka itu tidak boleh mendekat, dan bangsa itu tidak boleh naik bersama-sama dengan dia.\"', NULL),
(64310, 3648, 24, 3, 'Lalu datanglah Musa dan memberitahukan kepada bangsa itu segala firman TUHAN dan segala peraturan itu, maka seluruh bangsa itu menjawab serentak: \"Segala firman yang telah diucapkan TUHAN itu, akan kami lakukan.\"', NULL),
(64311, 3648, 24, 4, 'Lalu Musa menuliskan segala firman TUHAN itu. Keesokan harinya pagi-pagi didirikannyalah mezbah di kaki gunung itu, dengan dua belas tugu sesuai dengan kedua belas suku Israel.', NULL),
(64312, 3648, 24, 5, 'Kemudian disuruhnyalah orang-orang muda dari bangsa Israel, maka mereka mempersembahkan korban bakaran dan menyembelih lembu-lembu jantan sebagai korban keselamatan kepada TUHAN.', NULL),
(64313, 3648, 24, 6, 'Sesudah itu Musa mengambil sebagian dari darah itu, lalu ditaruhnya ke dalam pasu, sebagian lagi dari darah itu disiramkannya pada mezbah itu.', NULL),
(64314, 3648, 24, 7, 'Diambilnyalah kitab perjanjian itu, lalu dibacakannya dengan didengar oleh bangsa itu dan mereka berkata: \"Segala firman TUHAN akan kami lakukan dan akan kami dengarkan.\"', NULL),
(64315, 3648, 24, 8, 'Kemudian Musa mengambil darah itu dan menyiramkannya pada bangsa itu serta berkata: \"Inilah darah perjanjian yang diadakan TUHAN dengan kamu, berdasarkan segala firman ini.\"', NULL),
(64316, 3648, 24, 9, 'Dan naiklah Musa dengan Harun, Nadab dan Abihu dan tujuh puluh orang dari para tua-tua Israel.', NULL),
(64317, 3648, 24, 10, 'Lalu mereka melihat Allah Israel; kaki-Nya berjejak pada sesuatu yang buatannya seperti lantai dari batu nilam dan yang terangnya seperti langit yang cerah.', NULL),
(64318, 3648, 24, 11, 'Tetapi kepada pemuka-pemuka orang Israel itu tidaklah diulurkan-Nya tangan-Nya; mereka memandang Allah, lalu makan dan minum.', NULL),
(64319, 3648, 24, 12, 'TUHAN berfirman kepada Musa: \"Naiklah menghadap Aku, ke atas gunung, dan tinggallah di sana, maka Aku akan memberikan kepadamu loh batu, yakni hukum dan perintah, yang telah Kutuliskan untuk diajarkan kepada mereka.\"', 'Musa di gunung Sinai'),
(64320, 3648, 24, 13, 'Lalu bangunlah Musa dengan Yosua, abdinya, maka naiklah Musa ke atas gunung Allah itu.', NULL),
(64321, 3648, 24, 14, 'Tetapi kepada para tua-tua itu ia berkata: \"Tinggallah di sini menunggu kami, sampai kami kembali lagi kepadamu; bukankah Harun dan Hur ada bersama-sama dengan kamu, siapa yang ada perkaranya datanglah kepada mereka.\"', NULL),
(64322, 3648, 24, 15, 'Maka Musa mendaki gunung dan awan itu menutupinya.', NULL),
(64323, 3648, 24, 16, 'Kemuliaan TUHAN diam di atas gunung Sinai, dan awan itu menutupinya enam hari lamanya; pada hari ketujuh dipanggil-Nyalah Musa dari tengah-tengah awan itu.', NULL),
(64324, 3648, 24, 17, 'Tampaknya kemuliaan TUHAN sebagai api yang menghanguskan di puncak gunung itu pada pemandangan orang Israel.', NULL),
(64325, 3648, 24, 18, 'Masuklah Musa ke tengah-tengah awan itu dengan mendaki gunung itu. Lalu tinggallah ia di atas gunung itu empat puluh hari dan empat puluh malam lamanya.', NULL),
(66522, 3648, 25, 1, 'Berfirmanlah TUHAN kepada Musa:', 'Petunjuk untuk mendirikan Kemah Suci Mengenai persembahan khusus'),
(66523, 3648, 25, 2, '\"Katakanlah kepada orang Israel, supaya mereka memungut bagi-Ku persembahan khusus; dari setiap orang yang terdorong hatinya, haruslah kamu pungut persembahan khusus kepada-Ku itu.', NULL),
(66524, 3648, 25, 3, 'Inilah persembahan khusus yang harus kamu pungut dari mereka: emas, perak, tembaga;', NULL),
(66525, 3648, 25, 4, 'kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing;', NULL),
(66526, 3648, 25, 5, 'kulit domba jantan yang diwarnai merah, kulit lumba-lumba dan kayu penaga;', NULL),
(66527, 3648, 25, 6, 'minyak untuk lampu, rempah-rempah untuk minyak urapan dan untuk ukupan dari wangi-wangian,', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(66528, 3648, 25, 7, 'permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada.', NULL),
(66529, 3648, 25, 8, 'Dan mereka harus membuat tempat kudus bagi-Ku, supaya Aku akan diam di tengah-tengah mereka.', NULL),
(66530, 3648, 25, 9, 'Menurut segala apa yang Kutunjukkan kepadamu sebagai contoh Kemah Suci dan sebagai contoh segala perabotannya, demikianlah harus kamu membuatnya.\"', NULL),
(66531, 3648, 25, 10, '\"Haruslah mereka membuat tabut dari kayu penaga, dua setengah hasta panjangnya, satu setengah hasta lebarnya dan satu setengah hasta tingginya.', 'Mengenai tabut perjanjian'),
(66532, 3648, 25, 11, 'Haruslah engkau menyalutnya dengan emas murni; dari dalam dan dari luar engkau harus menyalutnya dan di atasnya harus kaubuat bingkai emas sekelilingnya.', NULL),
(66533, 3648, 25, 12, 'Haruslah engkau menuang empat gelang emas untuk tabut itu dan pasanglah gelang itu pada keempat penjurunya, yaitu dua gelang pada rusuknya yang satu dan dua gelang pada rusuknya yang kedua.', NULL),
(66534, 3648, 25, 13, 'Engkau harus membuat kayu pengusung dari kayu penaga dan menyalutnya dengan emas.', NULL),
(66535, 3648, 25, 14, 'Haruslah engkau memasukkan kayu pengusung itu ke dalam gelang yang ada pada rusuk tabut itu, supaya dengan itu tabut dapat diangkut.', NULL),
(66536, 3648, 25, 15, 'Kayu pengusung itu haruslah tetap tinggal dalam gelang itu, tidak boleh dicabut dari dalamnya.', NULL),
(66537, 3648, 25, 16, 'Dalam tabut itu haruslah kautaruh loh hukum, yang akan Kuberikan kepadamu.', NULL),
(66538, 3648, 25, 17, 'Juga engkau harus membuat tutup pendamaian dari emas murni, dua setengah hasta panjangnya dan satu setengah hasta lebarnya.', NULL),
(66539, 3648, 25, 18, 'Dan haruslah kaubuat dua kerub dari emas, kaubuatlah itu dari emas tempaan, pada kedua ujung tutup pendamaian itu.', NULL),
(66540, 3648, 25, 19, 'Buatlah satu kerub pada ujung sebelah sini dan satu kerub pada ujung sebelah sana; seiras dengan tutup pendamaian itu kamu buatlah kerub itu di atas kedua ujungnya.', NULL),
(66541, 3648, 25, 20, 'Kerub-kerub itu harus mengembangkan kedua sayapnya ke atas, sedang sayap-sayapnya menudungi tutup pendamaian itu dan mukanya menghadap kepada masing-masing; kepada tutup pendamaian itulah harus menghadap muka kerub-kerub itu.', NULL),
(66542, 3648, 25, 21, 'Haruslah kauletakkan tutup pendamaian itu di atas tabut dan dalam tabut itu engkau harus menaruh loh hukum, yang akan Kuberikan kepadamu.', NULL),
(66543, 3648, 25, 22, 'Dan di sanalah Aku akan bertemu dengan engkau dan dari atas tutup pendamaian itu, dari antara kedua kerub yang di atas tabut hukum itu, Aku akan berbicara dengan engkau tentang segala sesuatu yang akan Kuperintahkan kepadamu untuk disampaikan kepada orang Israel.\"', NULL),
(66544, 3648, 25, 23, '\"Lagi haruslah engkau membuat meja dari kayu penaga, dua hasta panjangnya, sehasta lebarnya dan satu setengah hasta tingginya.', 'Mengenai meja roti sajian'),
(66545, 3648, 25, 24, 'Haruslah engkau menyalutnya dengan emas murni dan membuat bingkai emas sekelilingnya.', NULL),
(66546, 3648, 25, 25, 'Haruslah engkau membuat sekelilingnya jalur pinggir yang setapak tangan lebarnya dan kaubuatlah bingkai emas sekeliling jalur pinggirnya itu.', NULL),
(66547, 3648, 25, 26, 'Haruslah engkau membuat untuk meja itu empat gelang emas dan kaupasanglah gelang-gelang itu di keempat penjurunya, pada keempat kakinya.', NULL),
(66548, 3648, 25, 27, 'Gelang itu haruslah dekat ke jalur pinggirnya sebagai tempat memasukkan kayu pengusung, supaya meja itu dapat diangkut.', NULL),
(66549, 3648, 25, 28, 'Haruslah engkau membuat kayu pengusung itu dari kayu penaga dan menyalutnya dengan emas, dan dengan itulah meja harus diangkut.', NULL),
(66550, 3648, 25, 29, 'Haruslah engkau membuat pinggannya, cawannya, kendinya dan pialanya, yang dipakai untuk persembahan curahan; haruslah engkau membuat semuanya itu dari emas murni.', NULL),
(66551, 3648, 25, 30, 'Dan haruslah engkau tetap meletakkan roti sajian di atas meja itu di hadapan-Ku.\"', NULL),
(66552, 3648, 25, 31, '\"Haruslah engkau membuat kandil dari emas murni; dari emas tempaan harus kandil itu dibuat, baik kakinya baik batangnya; kelopaknya--dengan tombolnya dan kembangnya--haruslah seiras dengan kandil itu.', 'Mengenai kandil'),
(66553, 3648, 25, 32, 'Enam cabang harus timbul dari sisinya: tiga cabang kandil itu dari sisi yang satu dan tiga cabang dari sisi yang lain.', NULL),
(66554, 3648, 25, 33, 'Tiga kelopak yang berupa bunga badam pada cabang yang satu--dengan tombol dan kembangnya--dan tiga kelopak yang serupa pada cabang yang lain--dengan tombol dan kembangnya--;demikianlah juga kaubuat keenam cabang yang timbul dari kandil itu.', NULL),
(66555, 3648, 25, 34, 'Pada kandil itu sendiri harus ada empat kelopak berupa bunga badam--dengan tombolnya dan kembangnya.', NULL),
(66556, 3648, 25, 35, 'Juga harus ada satu tombol di bawah sepasang cabang yang pertama, yang timbul dari kandil itu, dan satu tombol di bawah yang kedua, dan satu tombol di bawah yang ketiga; demikianlah juga kaubuat keenam cabang yang timbul dari kandil itu.', NULL),
(66557, 3648, 25, 36, 'Tombol dan cabang itu harus timbul dari kandil itu, dan semuanya itu haruslah dibuat dari sepotong emas tempaan yang murni.', NULL),
(66558, 3648, 25, 37, 'Haruslah kaubuat pada kandil itu tujuh lampu dan lampu-lampu itu haruslah dipasang di atas kandil itu, sehingga diterangi yang di depannya.', NULL),
(66559, 3648, 25, 38, 'Sepitnya dan penadahnya haruslah dari emas murni.', NULL),
(66560, 3648, 25, 39, 'Dari satu talenta emas murni haruslah dibuat kandil itu dengan segala perkakasnya itu.', NULL),
(66561, 3648, 25, 40, 'Dan ingatlah, bahwa engkau membuat semuanya itu menurut contoh yang telah ditunjukkan kepadamu di atas gunung itu.\"', NULL),
(66562, 3648, 26, 1, '\"Kemah Suci itu haruslah kaubuat dari sepuluh tenda dari lenan halus yang dipintal benangnya dan dari kain ungu tua, kain ungu muda dan kain kirmizi; dengan ada kerubnya, buatan ahli tenun, haruslah kaubuat semuanya itu.', 'Mengenai Kemah Suci'),
(66563, 3648, 26, 2, 'Panjang tiap-tiap tenda haruslah dua puluh delapan hasta dan lebar tiap-tiap tenda empat hasta: segala tenda itu harus sama ukurannya.', NULL),
(66564, 3648, 26, 3, 'Lima dari tenda itu haruslah dirangkap menjadi satu, dan yang lima lagi juga harus dirangkap menjadi satu.', NULL),
(66565, 3648, 26, 4, 'Pada rangkapan yang pertama, di tepi satu tenda yang di ujung, haruslah engkau membuat sosok-sosok kain ungu tua dan demikian juga di tepi satu tenda yang paling ujung pada rangkapan yang kedua.', NULL),
(66566, 3648, 26, 5, 'Lima puluh sosok harus kaubuat pada tenda yang satu dan lima puluh sosok pada tenda yang di ujung pada rangkapan yang kedua, sehingga sosok-sosok itu tepat berhadapan satu sama lain.', NULL),
(66567, 3648, 26, 6, 'Dan haruslah engkau membuat lima puluh kaitan emas dan menyambung tenda-tenda Kemah Suci yang satu dengan yang lain dengan memakai kaitan itu, sehingga menjadi satu.', NULL),
(66568, 3648, 26, 7, 'Juga haruslah engkau membuat tenda-tenda dari bulu kambing menjadi atap kemah yang menudungi Kemah Suci, sebelas tenda harus kaubuat.', NULL),
(66569, 3648, 26, 8, 'Panjang tiap-tiap tenda harus tiga puluh hasta dan lebar tiap-tiap tenda empat hasta: yang sebelas tenda itu harus sama ukurannya.', NULL),
(66570, 3648, 26, 9, 'Lima dari tenda itu haruslah kausambung dengan tersendiri, dan enam dari tenda itu dengan tersendiri, dan tenda yang keenam haruslah kaulipat dua, di sebelah depan kemah itu.', NULL),
(66571, 3648, 26, 10, 'Haruslah engkau membuat lima puluh sosok pada rangkapan yang pertama di tepi satu tenda yang di ujung dan lima puluh sosok di tepi satu tenda pada rangkapan yang kedua.', NULL),
(66572, 3648, 26, 11, 'Haruslah engkau membuat lima puluh kaitan tembaga dan memasukkan kaitan itu ke dalam sosok-sosok dan menyambung tenda-tenda kemah itu, supaya menjadi satu.', NULL),
(66573, 3648, 26, 12, 'Mengenai bagian yang berjuntai itu, yang berlebih pada tenda kemah itu, haruslah setengah dari tenda yang berlebih itu berjuntai di sebelah belakang Kemah Suci.', NULL),
(66574, 3648, 26, 13, 'Sehasta di sebelah sini dan sehasta di sebelah sana pada bagian yang berlebih pada panjang tenda-tenda kemah itu haruslah berjuntai pada sisi-sisi Kemah Suci, di sebelah sini dan di sebelah sana untuk menudunginya.', NULL),
(66575, 3648, 26, 14, 'Juga haruslah engkau membuat untuk kemah itu tudung dari kulit domba jantan yang diwarnai merah, dan tudung dari kulit lumba-lumba di atasnya lagi.', NULL),
(66576, 3648, 26, 15, 'Haruslah engkau membuat untuk Kemah Suci papan dari kayu penaga yang berdiri tegak,', NULL),
(66577, 3648, 26, 16, 'sepuluh hasta panjangnya satu papan dan satu setengah hasta lebarnya tiap-tiap papan.', NULL),
(66578, 3648, 26, 17, 'Tiap-tiap papan harus ada dua pasaknya yang disengkang satu sama lain; demikianlah harus kauperbuat dengan segala papan Kemah Suci.', NULL),
(66579, 3648, 26, 18, 'Haruslah engkau membuat papan-papan untuk Kemah Suci, dua puluh papan pada sebelah selatan.', NULL),
(66580, 3648, 26, 19, 'Dan haruslah kaubuat empat puluh alas perak di bawah kedua puluh papan itu, dua alas di bawah satu papan untuk kedua pasaknya, dan seterusnya dua alas di bawah setiap papan untuk kedua pasaknya.', NULL),
(66581, 3648, 26, 20, 'Juga untuk sisi yang kedua dari Kemah Suci, pada sebelah utara, kaubuatlah dua puluh papan', NULL),
(66582, 3648, 26, 21, 'dengan empat puluh alas peraknya: dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', NULL),
(66583, 3648, 26, 22, 'Untuk sisi belakang Kemah Suci, pada sebelah barat, haruslah kaubuat enam papan.', NULL),
(66584, 3648, 26, 23, 'Dua papan haruslah kaubuat untuk sudut Kemah Suci, di sisi belakang.', NULL),
(66585, 3648, 26, 24, 'Kedua papan itu haruslah kembar pasaknya di sebelah bawah dan seperti itu juga kembar pasaknya di sebelah atas, di dekat gelang yang satu itu; demikianlah harus kedua papan itu; haruslah itu merupakan kedua sudutnya.', NULL),
(66586, 3648, 26, 25, 'Jadi harus ada delapan papan dengan alas peraknya: enam belas alas; dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', NULL),
(66587, 3648, 26, 26, 'Juga haruslah kaubuat kayu lintang dari kayu penaga: lima untuk papan-papan pada sisi yang satu dari Kemah Suci,', NULL),
(66588, 3648, 26, 27, 'lima kayu lintang untuk papan-papan pada sisi yang kedua dari Kemah Suci, dan lima kayu lintang untuk papan-papan pada sisi Kemah Suci yang merupakan sisi belakangnya, pada sebelah barat.', NULL),
(66589, 3648, 26, 28, 'Dan kayu lintang yang di tengah, di tengah-tengah papan-papan itu, haruslah melintang terus dari ujung ke ujung.', NULL),
(66590, 3648, 26, 29, 'Papan-papan itu haruslah kausalut dengan emas, gelang-gelang itu haruslah kaubuat dari emas sebagai tempat memasukkan kayu-kayu lintang itu, dan kayu-kayu lintang itu haruslah kausalut dengan emas.', NULL),
(66591, 3648, 26, 30, 'Kemudian haruslah kaudirikan Kemah Suci sesuai dengan rancangan yang telah ditunjukkan kepadamu di atas gunung itu.', NULL),
(66592, 3648, 26, 31, 'Haruslah kaubuat tabir dari kain ungu tua, dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya; haruslah dibuat dengan ada kerubnya, buatan ahli tenun.', NULL),
(66593, 3648, 26, 32, 'Haruslah engkau menggantungkannya pada empat tiang dari kayu penaga, yang disalut dengan emas, dengan ada kaitannya dari emas, berdasarkan empat alas perak.', NULL),
(66594, 3648, 26, 33, 'Haruslah tabir itu kaugantungkan pada kaitan penyambung tenda itu dan haruslah kaubawa tabut hukum ke sana, ke belakang tabir itu, sehingga tabir itu menjadi pemisah bagimu antara tempat kudus dan tempat maha kudus.', NULL),
(66595, 3648, 26, 34, 'Tutup pendamaian itu haruslah kauletakkan di atas tabut hukum di dalam tempat maha kudus.', NULL),
(66596, 3648, 26, 35, 'Meja itu haruslah kautaruh di depan tabir itu, dan kandil itu berhadapan dengan meja itu pada sisi selatan dari Kemah Suci, dan meja itu haruslah kautempatkan pada sisi utara.', NULL),
(66597, 3648, 26, 36, 'Juga haruslah kaubuat tirai untuk pintu kemah itu dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: tenunan yang berwarna-warna.', NULL),
(66598, 3648, 26, 37, 'Haruslah kaubuat lima tiang dari kayu penaga untuk tirai itu dan kausalutlah itu dengan emas, dengan ada kaitannya dari emas, dan untuk itu haruslah kautuang lima alas dari tembaga.\"', NULL),
(68872, 3648, 27, 1, '\"Haruslah engkau membuat mezbah dari kayu penaga, lima hasta panjangnya dan lima hasta lebarnya, sehingga mezbah itu empat persegi, tetapi tiga hasta tingginya.', 'Mengenai mezbah korban bakaran'),
(68873, 3648, 27, 2, 'Haruslah engkau membuat tanduk-tanduknya pada keempat sudutnya; tanduk-tanduknya itu haruslah seiras dengan mezbah itu dan haruslah engkau menyalutnya dengan tembaga.', NULL),
(68874, 3648, 27, 3, 'Juga harus engkau membuat kuali-kualinya tempat menaruh abunya, dan sodok-sodoknya dan bokor-bokor penyiramannya, garpu-garpunya dan perbaraan-perbaraannya; semua perkakasnya itu harus kaubuat dari tembaga.', NULL),
(68875, 3648, 27, 4, 'Haruslah engkau membuat untuk itu kisi-kisi, yakni jala-jala tembaga, dan pada jala-jala itu haruslah kaubuat empat gelang tembaga pada keempat ujungnya.', NULL),
(68876, 3648, 27, 5, 'Haruslah engkau memasang jala-jala itu di bawah jalur mezbah itu; mulai dari sebelah bawah, sehingga jala-jala itu sampai setengah tinggi mezbah itu.', NULL),
(68877, 3648, 27, 6, 'Haruslah engkau membuat kayu-kayu pengusung untuk mezbah itu, kayu-kayu pengusung dari kayu penaga dan menyalutnya dengan tembaga.', NULL),
(68878, 3648, 27, 7, 'Kayu-kayu pengusungnya itu haruslah dimasukkan ke dalam gelang-gelang itu dan kayu-kayu pengusung itu haruslah ada pada kedua rusuk mezbah itu waktu mezbah itu diangkut.', NULL),
(68879, 3648, 27, 8, 'Mezbah itu harus kaubuat berongga dan dari papan, seperti yang ditunjukkan kepadamu di atas gunung itu, demikianlah harus dibuat mezbah itu.\"', NULL),
(68880, 3648, 27, 9, '\"Haruslah engkau membuat pelataran Kemah Suci; untuk pelataran itu pada sebelah selatan harus dibuat layar dari lenan halus yang dipintal benangnya, seratus hasta panjangnya pada sisi yang satu itu.', 'Mengenai pelataran'),
(68881, 3648, 27, 10, 'Tiang-tiangnya harus ada dua puluh, dan alas-alas tiang itu harus dua puluh, dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya harus dari perak.', NULL),
(68882, 3648, 27, 11, 'Demikian juga pada sebelah utara, pada panjangnya, harus ada layar yang seratus hasta panjangnya, tiang-tiangnya harus ada dua puluh dan alas-alas tiang itu harus dua puluh, dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya harus dari perak.', NULL),
(68883, 3648, 27, 12, 'Dan pada lebar pelataran itu pada sebelah barat harus ada layar yang lima puluh hasta, dengan sepuluh tiangnya dan sepuluh alas tiang itu.', NULL),
(68884, 3648, 27, 13, 'Lebar pelataran itu, yaitu bagian muka pada sebelah timur harus lima puluh hasta,', NULL),
(68885, 3648, 27, 14, 'yakni lima belas hasta layar untuk sisi yang satu di samping pintu gerbang itu, dengan tiga tiangnya dan tiga alas tiang itu;', NULL),
(68886, 3648, 27, 15, 'dan juga untuk sisi yang kedua di samping pintu gerbang itu lima belas hasta layar, dengan tiga tiangnya dan tiga alas tiang itu;', NULL),
(68887, 3648, 27, 16, 'tetapi untuk pintu gerbang pelataran itu tirai dua puluh hasta dari kain ungu tua dan kain ungu muda, kain kirmizi dan dari lenan halus yang dipintal benangnya--tenunan yang berwarna-warna--dengan empat tiangnya dan empat alas tiang itu.', NULL),
(68888, 3648, 27, 17, 'Segala tiang yang mengelilingi pelataran itu haruslah dihubungkan dengan penyambung-penyambung perak, dan kaitan-kaitannya harus dari perak dan alas-alasnya dari tembaga.', NULL),
(68889, 3648, 27, 18, 'Panjang pelataran itu harus seratus hasta, lebarnya lima puluh hasta dan tingginya lima hasta, dari lenan halus yang dipintal benangnya, dan alas-alasnya harus dari tembaga.', NULL),
(68890, 3648, 27, 19, 'Adapun segala perabotan untuk seluruh perlengkapan Kemah Suci, dan juga segala patoknya dan segala patok pelataran: semuanya harus dari tembaga.\"', NULL),
(68891, 3648, 27, 20, '\"Haruslah kauperintahkan kepada orang Israel, supaya mereka membawa kepadamu minyak zaitun tumbuk yang murni untuk lampu, supaya orang dapat memasang lampu agar tetap menyala.', 'Mengenai minyak untuk lampu'),
(68892, 3648, 27, 21, 'Di dalam Kemah Pertemuan di depan tabir yang menutupi tabut hukum, haruslah Harun dan anak-anaknya mengaturnya dari petang sampai pagi di hadapan TUHAN. Itulah suatu ketetapan yang berlaku untuk selama-lamanya bagi orang Israel turun-temurun.\"', NULL),
(68893, 3648, 28, 1, '\"Engkau harus menyuruh abangmu Harun bersama-sama dengan anak-anaknya datang kepadamu, dari tengah-tengah orang Israel, untuk memegang jabatan imam bagi-Ku--Harun dan anak-anak Harun, yakni Nadab, Abihu, Eleazar dan Itamar.', 'Mengenai pakaian imam'),
(68894, 3648, 28, 2, 'Haruslah engkau membuat pakaian kudus bagi Harun, abangmu, sebagai perhiasan kemuliaan.', NULL),
(68895, 3648, 28, 3, 'Haruslah engkau mengatakan kepada semua orang yang ahli, yang telah Kupenuhi dengan roh keahlian, membuat pakaian Harun, untuk menguduskan dia, supaya dipegangnya jabatan imam bagi-Ku.', NULL),
(68896, 3648, 28, 4, 'Inilah pakaian yang harus dibuat mereka: tutup dada, baju efod, gamis, kemeja yang ada raginya, serban dan ikat pinggang. Demikianlah mereka harus membuat pakaian kudus bagi Harun, abangmu, dan bagi anak-anaknya, supaya ia memegang jabatan imam bagi-Ku.', NULL),
(68897, 3648, 28, 5, 'Untuk itu haruslah mereka mengambil emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus.', NULL),
(68898, 3648, 28, 6, 'Baju efod itu harus dibuat mereka dari emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: buatan seorang ahli.', NULL),
(68899, 3648, 28, 7, 'Haruslah ada pada baju efod itu dua tutup bahu yang disambung kepadanya, pada kedua ujungnyalah harus baju efod itu disambung.', NULL),
(68900, 3648, 28, 8, 'Sabuk pengikat yang ada pada baju efod itu haruslah sama buatannya dan seiras dengan baju efod itu, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', NULL),
(68901, 3648, 28, 9, 'Haruslah kauambil dua permata krisopras dan mengukirkan nama para anak Israel pada permata itu,', NULL),
(68902, 3648, 28, 10, 'enam dari nama mereka itu pada permata yang pertama dan keenam nama lagi pada permata yang kedua, menurut urutan kelahirannya.', NULL),
(68903, 3648, 28, 11, 'Seperti buatan seorang pengasah permata, diukirkan seperti meterai, demikianlah harus kauukirkan pada kedua permata itu nama para anak Israel; dililit dengan ikat emas harus kaubuat permata itu.', NULL),
(68904, 3648, 28, 12, 'Kemudian haruslah kautaruh kedua permata itu pada kedua tutup bahu baju efod sebagai permata peringatan untuk mengingat orang Israel; maka ke hadapan TUHAN haruslah Harun membawa nama mereka di atas kedua tutup bahunya menjadi tanda peringatan.', NULL),
(68905, 3648, 28, 13, 'Haruslah kaubuat ikat emas', NULL),
(68906, 3648, 28, 14, 'dan dua untai dari emas murni; sebagai utas haruslah kaubuat itu, yang buatannya sebagai tali berjalin dan haruslah kaupasang untai berjalin itu pada ikat itu.', NULL),
(68907, 3648, 28, 15, 'Haruslah engkau membuat tutup dada pernyataan keputusan: buatan seorang ahli. Buatannya sama dengan baju efod, demikianlah harus engkau membuatnya, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya haruslah engkau membuatnya.', NULL),
(68908, 3648, 28, 16, 'Haruslah itu empat persegi, lipat dua, sejengkal panjangnya dan sejengkal lebarnya.', NULL),
(68909, 3648, 28, 17, 'Haruslah kautatah itu dengan permata tatahan, empat jajar permata: permata yaspis merah, krisolit, malakit, itulah jajar yang pertama;', NULL),
(68910, 3648, 28, 18, 'jajar yang kedua: permata batu darah, lazurit, yaspis hijau;', NULL),
(68911, 3648, 28, 19, 'jajar yang ketiga: permata ambar, akik, kecubung,', NULL),
(68912, 3648, 28, 20, 'jajar yang keempat: permata pirus, krisopras dan nefrit. Dengan berikatkan emas, demikianlah permata-permata itu dalam tatahannya.', NULL),
(68913, 3648, 28, 21, 'Sesuai dengan nama para anak Israel, permata itu haruslah dua belas banyaknya; dan pada tiap-tiap permata haruslah ada, diukirkan seperti meterai, nama salah satu suku dari yang dua belas itu.', NULL),
(68914, 3648, 28, 22, 'Juga haruslah kaubuat untuk tutup dada itu untai berpilin, yang buatannya sebagai tali berjalin, dari emas murni.', NULL),
(68915, 3648, 28, 23, 'Juga haruslah kaubuat untuk tutup dada itu dua gelang emas dan kedua gelang itu harus kaupasang pada kedua ujung tutup dada.', NULL),
(68916, 3648, 28, 24, 'Haruslah kedua untai emas yang berjalin itu kaupasang pada kedua gelang itu, pada ujung tutup dada.', NULL),
(68917, 3648, 28, 25, 'Kedua ujung lain dari kedua untai berjalin itu haruslah kaupasang pada kedua ikat emas itu, demikianlah kaupasang pada tutup bahu baju efod, di sebelah depannya.', NULL),
(68918, 3648, 28, 26, 'Haruslah engkau membuat dua gelang emas dan membubuhnya pada kedua ujung tutup dada itu, pada pinggirnya yang sebelah dalam, yang berhadapan dengan baju efod.', NULL),
(68919, 3648, 28, 27, 'Juga haruslah engkau membuat dua gelang emas dan memasangnya pada kedua tutup bahu baju efod, di sebelah bawah pada bagian depan, dekat ke tempat persambungannya, di sebelah atas sabuk baju efod.', NULL),
(68920, 3648, 28, 28, 'Kemudian haruslah tutup dada itu dengan gelangnya diikatkan kepada gelang baju efod dengan memakai tali ungu tua, sehingga tetap di atas sabuk baju efod, dan tutup dada itu tidak dapat bergeser dari baju efod.', NULL),
(68921, 3648, 28, 29, 'Demikianlah di atas jantungnya harus dibawa Harun nama para anak Israel pada tutup dada pernyataan keputusan itu, apabila ia masuk ke dalam tempat kudus, supaya menjadi tanda peringatan yang tetap di hadapan TUHAN.', NULL),
(68922, 3648, 28, 30, 'Dan di dalam tutup dada pernyataan keputusan itu haruslah kautaruh Urim dan Tumim; haruslah itu di atas jantung Harun, apabila ia masuk menghadap TUHAN, dan Harun harus tetap membawa keputusan bagi orang Israel di atas jantungnya, di hadapan TUHAN.', NULL),
(68923, 3648, 28, 31, 'Haruslah kaubuat gamis baju efod dari kain ungu tua seluruhnya.', NULL),
(68924, 3648, 28, 32, 'Lehernya haruslah di tengah-tengahnya; lehernya itu harus mempunyai pinggir sekelilingnya, buatan tukang tenun, seperti leher baju zirah haruslah lehernya itu, supaya jangan koyak.', NULL),
(68925, 3648, 28, 33, 'Pada ujung gamis itu haruslah kaubuat buah delima dari kain ungu tua, kain ungu muda dan kain kirmizi, pada sekeliling ujung gamis itu, dan di antaranya berselang-seling giring-giring emas,', NULL),
(68926, 3648, 28, 34, 'sehingga satu giring-giring emas dan satu buah delima selalu berselang-seling, pada ujung gamis itu.', NULL),
(68927, 3648, 28, 35, 'Haruslah gamis itu dipakai Harun, apabila ia menyelenggarakan kebaktian, dan bunyinya harus kedengaran, apabila ia masuk ke dalam tempat kudus di hadapan TUHAN dan apabila ia keluar pula, supaya ia jangan mati.', NULL),
(68928, 3648, 28, 36, 'Juga haruslah engkau membuat patam dari emas murni dan pada patam itu kauukirkanlah, diukirkan seperti meterai: Kudus bagi TUHAN.', NULL),
(68929, 3648, 28, 37, 'Haruslah patam itu engkau beri bertali ungu tua, dan haruslah itu dilekatkan pada serban, di sebelah depan serban itu.', NULL),
(68930, 3648, 28, 38, 'Patam itu haruslah ada pada dahi Harun, dan Harun harus menanggung akibat kesalahan terhadap segala yang dikuduskan oleh orang Israel, yakni terhadap segala persembahan kudusnya; maka haruslah patam itu tetap ada pada dahinya, sehingga TUHAN berkenan akan mereka.', NULL),
(68931, 3648, 28, 39, 'Haruslah engkau menenun kemeja dengan ada raginya, dari lenan halus, dan membuat serban dari lenan halus dan haruslah kaubuat ikat pinggang dari tenunan yang berwarna-warna.', NULL),
(68932, 3648, 28, 40, 'Juga bagi anak-anak Harun haruslah kaubuat kemeja-kemeja dan haruslah kaubuat ikat-ikat pinggang bagi mereka, dan destar-destar haruslah kaubuat bagi mereka untuk menjadi perhiasan kemuliaan.', NULL),
(68933, 3648, 28, 41, 'Maka semuanya itu haruslah kaukenakan kepada abangmu Harun bersama-sama dengan anak-anaknya, kemudian engkau harus mengurapi, mentahbiskan dan menguduskan mereka, sehingga mereka dapat memegang jabatan imam bagi-Ku.', NULL),
(68934, 3648, 28, 42, 'Buatlah celana-celana lenan bagi mereka untuk menutupi daging auratnya: celana itu haruslah dari pinggang sampai paha panjangnya.', NULL),
(68935, 3648, 28, 43, 'Harun dan anak-anaknya haruslah memakainya, apabila mereka masuk ke dalam Kemah Pertemuan atau apabila mereka datang ke mezbah untuk menyelenggarakan kebaktian di tempat kudus, supaya mereka jangan membawa kesalahan kepada dirinya, lalu mati. Itulah suatu ketetapan untuk selama-lamanya baginya dan bagi keturunannya.\"', NULL),
(68936, 3648, 29, 1, '\"Inilah yang harus kaulakukan kepada mereka, untuk menguduskan mereka, supaya mereka memegang jabatan imam bagi-Ku: Ambillah seekor lembu jantan muda dan dua ekor domba jantan yang tidak bercela,', 'Mengenai pentahbisan Harun dan anak-anaknya'),
(68937, 3648, 29, 2, 'roti yang tidak beragi dan roti bundar yang tidak beragi, yang diolah dengan minyak, dan roti tipis yang tidak beragi, yang diolesi dengan minyak; dari tepung gandum yang terbaik haruslah kaubuat semuanya itu.', NULL),
(68938, 3648, 29, 3, 'Kautaruhlah semuanya dalam sebuah bakul dan kaupersembahkanlah semuanya dalam bakul itu, demikian juga lembu jantan dan kedua domba jantan itu.', NULL),
(68939, 3648, 29, 4, 'Lalu kausuruhlah Harun dan anak-anaknya datang ke pintu Kemah Pertemuan dan haruslah engkau membasuh mereka dengan air.', NULL),
(68940, 3648, 29, 5, 'Kemudian kauambillah pakaian itu, lalu kaukenakanlah kepada Harun kemeja, gamis baju efod, dan baju efod serta tutup dada; kaukebatkanlah sabuk baju efod kepadanya;', NULL),
(68941, 3648, 29, 6, 'kautaruhlah serban di kepalanya dan jamang yang kudus kaububuh pada serban itu.', NULL),
(68942, 3648, 29, 7, 'Sesudah itu kauambillah minyak urapan dan kautuang ke atas kepalanya, dan kauurapilah dia.', NULL),
(68943, 3648, 29, 8, 'Kausuruhlah anak-anaknya mendekat dan kaukenakanlah kemeja-kemeja itu kepada mereka.', NULL),
(68944, 3648, 29, 9, 'Kauikatkanlah ikat pinggang kepada mereka, kepada Harun dan anak-anaknya, dan kaulilitkanlah destar itu kepada kepala mereka, maka merekalah yang akan memegang jabatan imam; itulah suatu ketetapan untuk selama-lamanya. Demikianlah engkau harus mentahbiskan Harun dan anak-anaknya.', NULL),
(68945, 3648, 29, 10, 'Kemudian haruslah kaubawa lembu jantan itu ke depan Kemah Pertemuan, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala lembu jantan itu.', NULL),
(68946, 3648, 29, 11, 'Haruslah kausembelih lembu jantan itu di hadapan TUHAN di depan pintu Kemah Pertemuan.', NULL),
(68947, 3648, 29, 12, 'Haruslah kauambil sedikit dari darah lembu jantan itu dan kaububuh dengan jarimu pada tanduk-tanduk mezbah, dan segala darah selebihnya haruslah kaucurahkan pada bagian bawah mezbah.', NULL),
(68948, 3648, 29, 13, 'Kemudian kauambillah segala lemak yang menutupi isi perut, umbai hati, kedua buah pinggang dan segala lemak yang melekat padanya, dan kaubakarlah di atas mezbah.', NULL),
(68949, 3648, 29, 14, 'Tetapi daging lembu jantan itu, kulitnya dan kotorannya haruslah kaubakar habis dengan api di luar perkemahan, itulah korban penghapus dosa.', NULL),
(68950, 3648, 29, 15, 'Kemudian haruslah kauambil domba jantan yang satu, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', NULL),
(68951, 3648, 29, 16, 'Haruslah kausembelih domba jantan itu dan kauambillah darahnya dan kausiramkan pada mezbah sekelilingnya.', NULL),
(68952, 3648, 29, 17, 'Haruslah kaupotong-potong domba jantan itu menurut bagian-bagian tertentu, kaubasuhlah isi perutnya dan betis-betisnya dan kautaruh itu di atas potongan-potongannya dan di atas kepalanya.', NULL),
(68953, 3648, 29, 18, 'Kemudian haruslah kaubakar seluruh domba jantan itu di atas mezbah; itulah korban bakaran, suatu persembahan yang harum bagi TUHAN, yakni suatu korban api-apian bagi TUHAN.', NULL),
(68954, 3648, 29, 19, 'Kemudian haruslah kauambil domba jantan yang lain, lalu haruslah Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', NULL),
(68955, 3648, 29, 20, 'Haruslah kausembelih domba jantan itu, kauambillah sedikit dari darahnya dan kaububuh pada cuping telinga kanan Harun dan pada cuping telinga kanan anak-anaknya, pada ibu jari tangan kanan dan pada ibu jari kaki kanan mereka, dan darah selebihnya kausiramkanlah pada mezbah sekelilingnya.', NULL),
(68956, 3648, 29, 21, 'Haruslah kauambil sedikit dari darah yang ada di atas mezbah dan dari minyak urapan itu dan kaupercikkanlah kepada Harun dan kepada pakaiannya, dan juga kepada anak-anaknya dan pada pakaian anak-anaknya; maka ia akan kudus, ia dan pakaiannya, dan juga anak-anaknya dan pakaian anak-anaknya.', NULL),
(68957, 3648, 29, 22, 'Dari domba jantan itu haruslah kauambil lemaknya, ekornya yang berlemak, lemak yang menutupi isi perutnya, umbai hatinya, kedua buah pinggangnya, lemak yang melekat padanya, paha kanannya--sebab itulah domba jantan persembahan pentahbisan--', NULL),
(68958, 3648, 29, 23, 'kauambillah juga satu keping roti, satu roti bundar yang berminyak dan satu roti tipis dari dalam bakul berisi roti yang tidak beragi, yang ada di hadapan TUHAN.', NULL),
(68959, 3648, 29, 24, 'Haruslah kautaruh seluruhnya ke atas telapak tangan Harun dan ke atas telapak tangan anak-anaknya dan haruslah kaupersembahkan semuanya sebagai persembahan unjukan di hadapan TUHAN.', NULL),
(68960, 3648, 29, 25, 'Kemudian haruslah kauambil semuanya dari tangan mereka dan kaubakar di atas mezbah, yaitu di atas korban bakaran, sebagai persembahan yang harum di hadapan TUHAN; itulah suatu korban api-apian bagi TUHAN.', NULL),
(68961, 3648, 29, 26, 'Selanjutnya haruslah kauambil dada dari domba jantan yang adalah bagi pentahbisan Harun dan kaupersembahkan sebagai persembahan unjukan di hadapan TUHAN, dan itulah bagian untukmu.', NULL),
(68962, 3648, 29, 27, 'Demikianlah harus kaukuduskan dada persembahan unjukan dan paha persembahan khusus yang dipersembahkan dari domba jantan yang adalah bagi pentahbisan Harun dan anak-anaknya.', NULL),
(68963, 3648, 29, 28, 'Itulah yang menjadi bagian untuk Harun dan anak-anaknya menurut ketetapan yang berlaku untuk selama-lamanya bagi orang Israel, sebab inilah suatu persembahan khusus, maka haruslah itu menjadi persembahan khusus dari pihak orang Israel, yang diambil dari korban keselamatan mereka, dan menjadi persembahan khusus mereka bagi TUHAN.', NULL),
(68964, 3648, 29, 29, 'Pakaian kudus kepunyaan Harun itu haruslah turun kepada anak-anaknya yang kemudian, supaya mereka memakainya apabila mereka diurapi dan ditahbiskan.', NULL),
(68965, 3648, 29, 30, 'Tujuh hari lamanya haruslah pakaian itu dikenakan oleh imam penggantinya dari antara anak-anaknya, yang akan masuk ke dalam Kemah Pertemuan untuk menyelenggarakan kebaktian di tempat kudus.', NULL),
(68966, 3648, 29, 31, 'Domba jantan persembahan pentahbisan itu haruslah kauambil dan dagingnya kaumasak pada suatu tempat yang kudus.', NULL),
(68967, 3648, 29, 32, 'Haruslah Harun dan anak-anaknya memakan daging domba jantan itu serta roti yang ada di dalam bakul di depan pintu Kemah Pertemuan.', NULL),
(68968, 3648, 29, 33, 'Haruslah mereka memakan semuanya itu yang dipakai untuk mengadakan pendamaian pada waktu mereka ditahbiskan dan dikuduskan, tetapi orang awam janganlah memakannya, sebab persembahan kudus semuanya itu.', NULL),
(68969, 3648, 29, 34, 'Jika ada yang tinggal dari daging persembahan pentahbisan dan dari roti itu sampai pagi, haruslah kaubakar habis yang tinggal itu dengan api, janganlah dimakan, sebab persembahan kudus semuanya itu.', NULL),
(68970, 3648, 29, 35, 'Maka haruslah kauperbuat demikian kepada Harun dan kepada anak-anaknya, tepat seperti yang Kuperintahkan kepadamu; selama tujuh hari haruslah kautahbiskan mereka.', NULL),
(68971, 3648, 29, 36, 'Tiap-tiap hari haruslah engkau mengolah seekor lembu jantan menjadi korban penghapus dosa untuk mengadakan pendamaian dan haruslah kausucikan mezbah itu, dengan mengadakan pendamaian baginya; haruslah engkau mengurapinya untuk menguduskannya.', NULL),
(68972, 3648, 29, 37, 'Tujuh hari lamanya haruslah engkau mengadakan pendamaian bagi mezbah itu; haruslah engkau menguduskannya, maka mezbah itu akan menjadi maha kudus; setiap orang yang kena kepada mezbah itu akan menjadi kudus.\"', NULL),
(68973, 3648, 29, 38, '\"Inilah yang harus kauolah di atas mezbah itu: dua anak domba berumur setahun, tetap tiap-tiap hari.', 'Mengenai korban pagi dan korban petang'),
(68974, 3648, 29, 39, 'Domba yang satu haruslah kauolah pada waktu pagi dan domba yang lain kauolah pada waktu senja.', NULL),
(68975, 3648, 29, 40, 'Dan beserta domba yang satu kauolah sepersepuluh efa tepung yang terbaik dengan minyak tumbuk seperempat hin, dan korban curahan dari seperempat hin anggur.', NULL),
(68976, 3648, 29, 41, 'Domba yang lain haruslah kauolah pada waktu senja; sama seperti korban sajian dan korban curahannya pada waktu pagi harus engkau mengolahnya sebagai persembahan yang harum, suatu korban api-apian bagi TUHAN,', NULL),
(68977, 3648, 29, 42, 'suatu korban bakaran yang tetap di antara kamu turun-temurun, di depan pintu Kemah Pertemuan di hadapan TUHAN. Sebab di sana Aku akan bertemu dengan kamu, untuk berfirman kepadamu.', NULL),
(68978, 3648, 29, 43, 'Di sanalah Aku akan bertemu dengan orang Israel, dan tempat itu akan dikuduskan oleh kemuliaan-Ku.', NULL),
(68979, 3648, 29, 44, 'Aku akan menguduskan Kemah Pertemuan dan mezbah itu, lalu Harun dan anak-anaknya akan Kukuduskan supaya mereka memegang jabatan imam bagi-Ku.', NULL),
(68980, 3648, 29, 45, 'Aku akan diam di tengah-tengah orang Israel dan Aku akan menjadi Allah mereka.', NULL),
(68981, 3648, 29, 46, 'Maka mereka akan mengetahui, bahwa Akulah, TUHAN, Allah mereka, yang telah membawa mereka keluar dari tanah Mesir, supaya Aku diam di tengah-tengah mereka; Akulah TUHAN, Allah mereka.\"', NULL),
(71365, 3648, 30, 1, '\"Haruslah kaubuat mezbah, tempat pembakaran ukupan; haruslah kaubuat itu dari kayu penaga;', 'Mengenai mezbah pembakaran ukupan'),
(71366, 3648, 30, 2, 'sehasta panjangnya dan sehasta lebarnya, sehingga menjadi empat persegi, tetapi haruslah dua hasta tingginya; tanduk-tanduknya haruslah seiras dengan mezbah itu.', NULL),
(71367, 3648, 30, 3, 'Haruslah kausalut itu dengan emas murni, bidang atasnya dan bidang-bidang sisinya sekelilingnya, serta tanduk-tanduknya. Haruslah kaubuat bingkai emas sekelilingnya.', NULL),
(71368, 3648, 30, 4, 'Haruslah kaubuat dua gelang emas untuk mezbah itu di bawah bingkainya; pada kedua rusuknya haruslah kaubuat gelang itu, pada kedua bidang sisinya, dan haruslah gelang itu menjadi tempat memasukkan kayu pengusung, supaya dengan itu mezbah dapat diangkut.', NULL),
(71369, 3648, 30, 5, 'Haruslah kaubuat kayu pengusung itu dari kayu penaga dan kausalutlah dengan emas.', NULL),
(71370, 3648, 30, 6, 'Haruslah kautaruh tempat pembakaran itu di depan tabir penutup tabut hukum, di depan tutup pendamaian yang di atas loh hukum, di mana Aku akan bertemu dengan engkau.', NULL),
(71371, 3648, 30, 7, 'Di atasnya haruslah Harun membakar ukupan dari wangi-wangian; tiap-tiap pagi, apabila ia membersihkan lampu-lampu, haruslah ia membakarnya.', NULL),
(71372, 3648, 30, 8, 'Juga apabila Harun memasang lampu-lampu itu pada waktu senja, haruslah ia membakarnya sebagai ukupan yang tetap di hadapan TUHAN di antara kamu turun-temurun.', NULL),
(71373, 3648, 30, 9, 'Di atas mezbah itu janganlah kamu persembahkan ukupan yang lain ataupun korban bakaran ataupun korban sajian, juga korban curahan janganlah kamu curahkan di atasnya.', NULL),
(71374, 3648, 30, 10, 'Sekali setahun haruslah Harun mengadakan pendamaian di atas tanduk-tanduknya; dengan darah korban penghapus dosa pembawa pendamaian haruslah ia sekali setahun mengadakan pendamaian bagi mezbah itu di antara kamu turun-temurun; itulah barang maha kudus bagi TUHAN.\"', NULL),
(71375, 3648, 30, 11, 'TUHAN berfirman kepada Musa:', 'Mengenai bejana pembasuhan'),
(71376, 3648, 30, 12, '\"Apabila engkau menghitung jumlah orang Israel pada waktu mereka didaftarkan, maka haruslah mereka masing-masing mempersembahkan kepada TUHAN uang pendamaian karena nyawanya, pada waktu orang mendaftarkan mereka, supaya jangan ada tulah di antara mereka pada waktu pendaftarannya itu.', NULL),
(71377, 3648, 30, 13, 'Inilah yang harus dipersembahkan tiap-tiap orang yang akan termasuk orang-orang yang terdaftar itu: setengah syikal, ditimbang menurut syikal kudus--syikal ini dua puluh gera beratnya--;setengah syikal itulah persembahan khusus kepada TUHAN.', NULL),
(71378, 3648, 30, 14, 'Setiap orang yang akan termasuk orang-orang yang terdaftar itu, yang berumur dua puluh tahun ke atas, haruslah mempersembahkan persembahan khusus itu kepada TUHAN.', NULL),
(71379, 3648, 30, 15, 'Orang kaya janganlah mempersembahkan lebih dan orang miskin janganlah mempersembahkan kurang dari setengah syikal itu pada waktu dipersembahkan persembahan khusus itu kepada TUHAN untuk mengadakan pendamaian bagi nyawa kamu sekalian.', NULL),
(71380, 3648, 30, 16, 'Dan haruslah engkau memungut uang pendamaian itu dari orang Israel dan menggunakannya untuk ibadah dalam Kemah Pertemuan; supaya itu menjadi peringatan di hadapan TUHAN untuk mengingat kepada orang Israel dan untuk mengadakan pendamaian bagi nyawa kamu sekalian.\"', NULL),
(71381, 3648, 30, 17, 'Berfirmanlah TUHAN kepada Musa:', 'Mengenai minyak urapan yang kudus'),
(71382, 3648, 30, 18, '\"Haruslah engkau membuat bejana dan juga alasnya dari tembaga, untuk pembasuhan, dan kautempatkanlah itu antara Kemah Pertemuan dan mezbah, dan kautaruhlah air ke dalamnya.', NULL),
(71383, 3648, 30, 19, 'Maka Harun dan anak-anaknya haruslah membasuh tangan dan kaki mereka dengan air dari dalamnya.', NULL),
(71384, 3648, 30, 20, 'Apabila mereka masuk ke dalam Kemah Pertemuan, haruslah mereka membasuh tangan dan kaki dengan air, supaya mereka jangan mati. Demikian juga apabila mereka datang ke mezbah itu untuk menyelenggarakan kebaktian dan untuk membakar korban api-apian bagi TUHAN,', NULL),
(71385, 3648, 30, 21, 'haruslah mereka membasuh tangan dan kaki mereka, supaya mereka jangan mati. Itulah yang harus menjadi ketetapan bagi mereka untuk selama-lamanya, bagi dia dan bagi keturunannya turun-temurun.\"', NULL),
(71386, 3648, 30, 22, 'Berfirmanlah TUHAN kepada Musa:', 'Mengenai minyak urapan yang kudus'),
(71387, 3648, 30, 23, '\"Ambillah rempah-rempah pilihan, mur tetesan lima ratus syikal, dan kayu manis yang harum setengah dari itu, yakni dua ratus lima puluh syikal, dan tebu yang baik dua ratus lima puluh syikal,', NULL),
(71388, 3648, 30, 24, 'dan kayu teja lima ratus syikal, ditimbang menurut syikal kudus, dan minyak zaitun satu hin.', NULL),
(71389, 3648, 30, 25, 'Haruslah kaubuat semuanya itu menjadi minyak urapan yang kudus, suatu campuran rempah-rempah yang dicampur dengan cermat seperti buatan seorang tukang campur rempah-rempah; itulah yang harus menjadi minyak urapan yang kudus.', NULL),
(71390, 3648, 30, 26, 'Haruslah engkau mengurapi dengan itu Kemah Pertemuan dan tabut hukum,', NULL),
(71391, 3648, 30, 27, 'meja dengan segala perkakasnya, kandil dengan perkakasnya, dan mezbah pembakaran ukupan;', NULL),
(71392, 3648, 30, 28, 'mezbah korban bakaran dengan segala perkakasnya, bejana pembasuhan dengan alasnya.', NULL),
(71393, 3648, 30, 29, 'Haruslah kaukuduskan semuanya, sehingga menjadi maha kudus; setiap orang yang kena kepadanya akan menjadi kudus.', NULL),
(71394, 3648, 30, 30, 'Engkau harus juga mengurapi dan menguduskan Harun dan anak-anaknya supaya mereka memegang jabatan imam bagi-Ku.', NULL),
(71395, 3648, 30, 31, 'Dan kepada orang Israel haruslah kaukatakan demikian: Inilah yang harus menjadi minyak urapan yang kudus bagi-Ku di antara kamu turun-temurun.', NULL),
(71396, 3648, 30, 32, 'Kepada badan orang biasa janganlah minyak itu dicurahkan, dan janganlah kaubuat minyak yang semacam itu dengan memakai campuran itu juga: itulah minyak yang kudus, dan haruslah itu kudus bagimu.', NULL),
(71397, 3648, 30, 33, 'Orang yang mencampur rempah-rempah menjadi minyak yang semacam itu atau yang membubuhnya pada badan orang awam, haruslah dilenyapkan dari antara bangsanya.\"', NULL),
(71398, 3648, 30, 34, 'Berfirmanlah TUHAN kepada Musa: \"Ambillah wangi-wangian, yakni getah damar, kulit lokan dan getah rasamala, wangi-wangian itu serta kemenyan yang tulen, masing-masing sama banyaknya.', 'Mengenai ukupan yang kudus'),
(71399, 3648, 30, 35, 'Semuanya ini haruslah kaubuat menjadi ukupan, suatu campuran rempah-rempah, seperti buatan seorang tukang campur rempah-rempah, digarami, murni, kudus.', NULL),
(71400, 3648, 30, 36, 'Sebagian dari ukupan itu haruslah kaugiling sampai halus, dan sedikit dari padanya kauletakkanlah di hadapan tabut hukum di dalam Kemah Pertemuan, di mana Aku akan bertemu dengan engkau; haruslah itu maha kudus bagimu.', NULL),
(71401, 3648, 30, 37, 'Dan tentang ukupan yang harus kaubuat menurut campuran yang seperti itu juga janganlah kamu buat bagi kamu sendiri; itulah bagian untuk TUHAN, yang kudus bagimu.', NULL),
(71402, 3648, 30, 38, 'Orang yang akan membuat minyak yang semacam itu dengan maksud untuk menghirup baunya, haruslah dilenyapkan dari antara bangsanya.\"', NULL),
(71403, 3648, 31, 1, 'Berfirmanlah TUHAN kepada Musa:', 'Bezaleel dan Aholiab ditunjuk'),
(71404, 3648, 31, 2, '\"Lihat, telah Kutunjuk Bezaleel bin Uri bin Hur, dari suku Yehuda,', NULL),
(71405, 3648, 31, 3, 'dan telah Kupenuhi dia dengan Roh Allah, dengan keahlian dan pengertian dan pengetahuan, dalam segala macam pekerjaan,', NULL),
(71406, 3648, 31, 4, 'untuk membuat berbagai rancangan supaya dikerjakan dari emas, perak dan tembaga;', NULL),
(71407, 3648, 31, 5, 'untuk mengasah batu permata supaya ditatah; untuk mengukir kayu dan untuk bekerja dalam segala macam pekerjaan.', NULL),
(71408, 3648, 31, 6, 'Juga Aku telah menetapkan di sampingnya Aholiab bin Ahisamakh, dari suku Dan; dalam hati setiap orang ahli telah Kuberikan keahlian. Haruslah mereka membuat segala apa yang telah Kuperintahkan kepadamu:', NULL),
(71409, 3648, 31, 7, 'Kemah Pertemuan, tabut untuk hukum, tutup pendamaian yang terletak di atasnya, dan segala perabotan kemah itu,', NULL),
(71410, 3648, 31, 8, 'yakni meja dengan perkakasnya, kandil dari emas murni dengan segala perkakasnya, mezbah pembakaran ukupan,', NULL),
(71411, 3648, 31, 9, 'mezbah korban bakaran dengan segala perkakasnya, bejana pembasuhan dengan alasnya,', NULL),
(71412, 3648, 31, 10, 'pakaian jabatan, baik pakaian kudus kepunyaan imam Harun, maupun pakaian anak-anaknya, untuk memegang jabatan imam,', NULL),
(71413, 3648, 31, 11, 'minyak urapan dan ukupan dari wangi-wangian untuk tempat kudus; tepat seperti yang telah Kuperintahkan kepadamu haruslah mereka membuat semuanya.\"', NULL),
(71414, 3648, 31, 12, 'Berfirmanlah TUHAN kepada Musa:', 'Peringatan untuk menguduskan hari Sabat'),
(71415, 3648, 31, 13, '\"Katakanlah kepada orang Israel, demikian: Akan tetapi hari-hari Sabat-Ku harus kamu pelihara, sebab itulah peringatan antara Aku dan kamu, turun-temurun, sehingga kamu mengetahui, bahwa Akulah TUHAN, yang menguduskan kamu.', NULL),
(71416, 3648, 31, 14, 'Haruslah kamu pelihara hari Sabat, sebab itulah hari kudus bagimu; siapa yang melanggar kekudusan hari Sabat itu, pastilah ia dihukum mati, sebab setiap orang yang melakukan pekerjaan pada hari itu, orang itu harus dilenyapkan dari antara bangsanya.', NULL),
(71417, 3648, 31, 15, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada sabat, hari perhentian penuh, hari kudus bagi TUHAN: setiap orang yang melakukan pekerjaan pada hari Sabat, pastilah ia dihukum mati.', NULL),
(71418, 3648, 31, 16, 'Maka haruslah orang Israel memelihara hari Sabat, dengan merayakan sabat, turun-temurun, menjadi perjanjian kekal.', NULL),
(71419, 3648, 31, 17, 'Antara Aku dan orang Israel maka inilah suatu peringatan untuk selama-lamanya, sebab enam hari lamanya TUHAN menjadikan langit dan bumi, dan pada hari yang ketujuh Ia berhenti bekerja untuk beristirahat.\"', NULL),
(71420, 3648, 31, 18, 'Dan TUHAN memberikan kepada Musa, setelah Ia selesai berbicara dengan dia di gunung Sinai, kedua loh hukum Allah, loh batu, yang ditulisi oleh jari Allah.', 'Musa menerima kedua loh hukum'),
(71421, 3648, 32, 1, 'Ketika bangsa itu melihat, bahwa Musa mengundur-undurkan turun dari gunung itu, maka berkumpullah mereka mengerumuni Harun dan berkata kepadanya: \"Mari, buatlah untuk kami allah, yang akan berjalan di depan kami sebab Musa ini, orang yang telah memimpin kami keluar dari tanah Mesir--kami tidak tahu apa yang telah terjadi dengan dia.\"', 'Anak lembu emas'),
(71422, 3648, 32, 2, 'Lalu berkatalah Harun kepada mereka: \"Tanggalkanlah anting-anting emas yang ada pada telinga isterimu, anakmu laki-laki dan perempuan, dan bawalah semuanya kepadaku.\"', NULL),
(71423, 3648, 32, 3, 'Lalu seluruh bangsa itu menanggalkan anting-anting emas yang ada pada telinga mereka dan membawanya kepada Harun.', NULL),
(71424, 3648, 32, 4, 'Diterimanyalah itu dari tangan mereka, dibentuknya dengan pahat, dan dibuatnyalah dari padanya anak lembu tuangan. Kemudian berkatalah mereka: \"Hai Israel, inilah Allahmu, yang telah menuntun engkau keluar dari tanah Mesir!\"', NULL),
(71425, 3648, 32, 5, 'Ketika Harun melihat itu, didirikannyalah mezbah di depan anak lembu itu. Berserulah Harun, katanya: \"Besok hari raya bagi TUHAN!\"', NULL),
(71426, 3648, 32, 6, 'Dan keesokan harinya pagi-pagi maka mereka mempersembahkan korban bakaran dan korban keselamatan, sesudah itu duduklah bangsa itu untuk makan dan minum; kemudian bangunlah mereka dan bersukaria.', NULL),
(71427, 3648, 32, 7, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah, turunlah, sebab bangsamu yang kaupimpin keluar dari tanah Mesir telah rusak lakunya.', NULL),
(71428, 3648, 32, 8, 'Segera juga mereka menyimpang dari jalan yang Kuperintahkan kepada mereka; mereka telah membuat anak lembu tuangan, dan kepadanya mereka sujud menyembah dan mempersembahkan korban, sambil berkata: Hai Israel, inilah Allahmu yang telah menuntun engkau keluar dari tanah Mesir.\"', NULL),
(71429, 3648, 32, 9, 'Lagi firman TUHAN kepada Musa: \"Telah Kulihat bangsa ini dan sesungguhnya mereka adalah suatu bangsa yang tegar tengkuk.', NULL),
(71430, 3648, 32, 10, 'Oleh sebab itu biarkanlah Aku, supaya murka-Ku bangkit terhadap mereka dan Aku akan membinasakan mereka, tetapi engkau akan Kubuat menjadi bangsa yang besar.\"', NULL),
(71431, 3648, 32, 11, 'Lalu Musa mencoba melunakkan hati TUHAN, Allahnya, dengan berkata: \"Mengapakah, TUHAN, murka-Mu bangkit terhadap umat-Mu, yang telah Kaubawa keluar dari tanah Mesir dengan kekuatan yang besar dan dengan tangan yang kuat?', NULL),
(71432, 3648, 32, 12, 'Mengapakah orang Mesir akan berkata: Dia membawa mereka keluar dengan maksud menimpakan malapetaka kepada mereka dan membunuh mereka di gunung dan membinasakannya dari muka bumi? Berbaliklah dari murka-Mu yang bernyala-nyala itu dan menyesallah karena malapetaka yang hendak Kaudatangkan kepada umat-Mu.', NULL),
(71433, 3648, 32, 13, 'Ingatlah kepada Abraham, Ishak dan Israel, hamba-hamba-Mu itu, sebab kepada mereka Engkau telah bersumpah demi diri-Mu sendiri dengan berfirman kepada mereka: Aku akan membuat keturunanmu sebanyak bintang di langit, dan seluruh negeri yang telah Kujanjikan ini akan Kuberikan kepada keturunanmu, supaya dimilikinya untuk selama-lamanya.\"', NULL),
(71434, 3648, 32, 14, 'Dan menyesallah TUHAN karena malapetaka yang dirancangkan-Nya atas umat-Nya.', NULL),
(71435, 3648, 32, 15, 'Setelah itu berpalinglah Musa, lalu turun dari gunung dengan kedua loh hukum Allah dalam tangannya, loh-loh yang bertulis pada kedua sisinya; bertulis sebelah-menyebelah.', NULL),
(71436, 3648, 32, 16, 'Kedua loh itu ialah pekerjaan Allah dan tulisan itu ialah tulisan Allah, ditukik pada loh-loh itu.', NULL),
(71437, 3648, 32, 17, 'Ketika Yosua mendengar suara bangsa itu bersorak, berkatalah ia kepada Musa: \"Ada bunyi sorak peperangan kedengaran di perkemahan.\"', NULL),
(71438, 3648, 32, 18, 'Tetapi jawab Musa: \"Bukan bunyi nyanyian kemenangan, bukan bunyi nyanyian kekalahan--bunyi orang menyanyi berbalas-balasan, itulah yang kudengar.\"', NULL),
(71439, 3648, 32, 19, 'Dan ketika ia dekat ke perkemahan itu dan melihat anak lembu dan melihat orang menari-nari, maka bangkitlah amarah Musa; dilemparkannyalah kedua loh itu dari tangannya dan dipecahkannya pada kaki gunung itu.', NULL),
(71440, 3648, 32, 20, 'Sesudah itu diambilnyalah anak lembu yang dibuat mereka itu, dibakarnya dengan api dan digilingnya sampai halus, kemudian ditaburkannya ke atas air dan disuruhnya diminum oleh orang Israel.', NULL),
(71441, 3648, 32, 21, 'Lalu berkatalah Musa kepada Harun: \"Apakah yang dilakukan bangsa ini kepadamu, sehingga engkau mendatangkan dosa yang sebesar itu kepada mereka?\"', NULL),
(71442, 3648, 32, 22, 'Tetapi jawab Harun: \"Janganlah bangkit amarah tuanku; engkau sendiri tahu, bahwa bangsa ini jahat semata-mata.', NULL),
(71443, 3648, 32, 23, 'Mereka berkata kepadaku: Buatlah untuk kami allah, yang akan berjalan di depan kami sebab Musa ini, orang yang telah memimpin kami keluar dari tanah Mesir--kami tidak tahu apa yang telah terjadi dengan dia.', NULL),
(71444, 3648, 32, 24, 'Lalu aku berkata kepada mereka: Siapa yang empunya emas haruslah menanggalkannya. Mereka memberikannya kepadaku dan aku melemparkannya ke dalam api, dan keluarlah anak lembu ini.\"', NULL),
(71445, 3648, 32, 25, 'Ketika Musa melihat, bahwa bangsa itu seperti kuda terlepas dari kandang--sebab Harun telah melepaskannya, sampai menjadi buah cemooh bagi lawan mereka--', NULL),
(71446, 3648, 32, 26, 'maka berdirilah Musa di pintu gerbang perkemahan itu serta berkata: \"Siapa yang memihak kepada TUHAN datanglah kepadaku!\" Lalu berkumpullah kepadanya seluruh bani Lewi.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(71447, 3648, 32, 27, 'Berkatalah ia kepada mereka: \"Beginilah firman TUHAN, Allah Israel: Baiklah kamu masing-masing mengikatkan pedangnya pada pinggangnya dan berjalanlah kian ke mari melalui perkemahan itu dari pintu gerbang ke pintu gerbang, dan biarlah masing-masing membunuh saudaranya dan temannya dan tetangganya.\"', NULL),
(71448, 3648, 32, 28, 'Bani Lewi melakukan seperti yang dikatakan Musa dan pada hari itu tewaslah kira-kira tiga ribu orang dari bangsa itu.', NULL),
(71449, 3648, 32, 29, 'Kemudian berkatalah Musa: \"Baktikanlah dirimu mulai hari ini kepada TUHAN, masing-masing dengan membayarkan jiwa anaknya laki-laki dan saudaranya--yakni supaya kamu diberi berkat pada hari ini.\"', NULL),
(71450, 3648, 32, 30, 'Keesokan harinya berkatalah Musa kepada bangsa itu: \"Kamu ini telah berbuat dosa besar, tetapi sekarang aku akan naik menghadap TUHAN, mungkin aku akan dapat mengadakan pendamaian karena dosamu itu.\"', NULL),
(71451, 3648, 32, 31, 'Lalu kembalilah Musa menghadap TUHAN dan berkata: \"Ah, bangsa ini telah berbuat dosa besar, sebab mereka telah membuat allah emas bagi mereka.', NULL),
(71452, 3648, 32, 32, 'Tetapi sekarang, kiranya Engkau mengampuni dosa mereka itu--dan jika tidak, hapuskanlah kiranya namaku dari dalam kitab yang telah Kautulis.\"', NULL),
(71453, 3648, 32, 33, 'Tetapi TUHAN berfirman kepada Musa: \"Siapa yang berdosa kepada-Ku, nama orang itulah yang akan Kuhapuskan dari dalam kitab-Ku.', NULL),
(71454, 3648, 32, 34, 'Tetapi pergilah sekarang, tuntunlah bangsa itu ke tempat yang telah Kusebutkan kepadamu; akan berjalan malaikat-Ku di depanmu, tetapi pada hari pembalasan-Ku itu Aku akan membalaskan dosa mereka kepada mereka.\"', NULL),
(71455, 3648, 32, 35, 'Demikianlah TUHAN menulahi bangsa itu, karena mereka telah menyuruh membuat anak lembu buatan Harun itu.', NULL),
(73930, 3648, 33, 1, 'Berfirmanlah TUHAN kepada Musa: \"Pergilah, berjalanlah dari sini, engkau dan bangsa itu yang telah kaupimpin keluar dari tanah Mesir, ke negeri yang telah Kujanjikan dengan sumpah kepada Abraham, Ishak dan Yakub, demikian: Kepada keturunanmulah akan Kuberikan negeri itu--', 'Musa meminta penyertaan TUHAN di gurun'),
(73931, 3648, 33, 2, 'Aku akan mengutus seorang malaikat berjalan di depanmu dan akan menghalau orang Kanaan, orang Amori, orang Het, orang Feris, orang Hewi dan orang Yebus--', NULL),
(73932, 3648, 33, 3, 'yakni ke suatu negeri yang berlimpah-limpah susu dan madu. Sebab Aku tidak akan berjalan di tengah-tengahmu, karena engkau ini bangsa yang tegar tengkuk, supaya Aku jangan membinasakan engkau di jalan.\"', NULL),
(73933, 3648, 33, 4, 'Ketika bangsa itu mendengar ancaman yang mengerikan ini, berkabunglah mereka dan seorangpun tidak ada yang memakai perhiasannya.', NULL),
(73934, 3648, 33, 5, 'Berfirmanlah TUHAN kepada Musa: \"Katakanlah kepada orang Israel: Kamu ini bangsa yang tegar tengkuk. Jika Aku berjalan di tengah-tengahmu sesaatpun, tentulah Aku akan membinasakan kamu. Oleh sebab itu, tanggalkanlah perhiasanmu, maka Aku akan melihat, apa yang akan Kulakukan kepadamu.\"', NULL),
(73935, 3648, 33, 6, 'Demikianlah orang Israel tidak memakai perhiasan-perhiasan lagi sejak dari gunung Horeb.', NULL),
(73936, 3648, 33, 7, 'Sesudah itu Musa mengambil kemah dan membentangkannya di luar perkemahan, jauh dari perkemahan, dan menamainya Kemah Pertemuan. Setiap orang yang mencari TUHAN, keluarlah ia pergi ke Kemah Pertemuan yang di luar perkemahan.', NULL),
(73937, 3648, 33, 8, 'Apabila Musa keluar pergi ke kemah itu, bangunlah seluruh bangsa itu dan berdirilah mereka, masing-masing di pintu kemahnya, dan mereka mengikuti Musa dengan matanya, sampai ia masuk ke dalam kemah.', NULL),
(73938, 3648, 33, 9, 'Apabila Musa masuk ke dalam kemah itu, turunlah tiang awan dan berhenti di pintu kemah dan berbicaralah TUHAN dengan Musa di sana.', NULL),
(73939, 3648, 33, 10, 'Setelah seluruh bangsa itu melihat, bahwa tiang awan berhenti di pintu kemah, maka mereka bangun dan sujud menyembah, masing-masing di pintu kemahnya.', NULL),
(73940, 3648, 33, 11, 'Dan TUHAN berbicara kepada Musa dengan berhadapan muka seperti seorang berbicara kepada temannya; kemudian kembalilah ia ke perkemahan. Tetapi abdinya, Yosua bin Nun, seorang yang masih muda, tidaklah meninggalkan kemah itu.', NULL),
(73941, 3648, 33, 12, 'Lalu berkatalah Musa kepada TUHAN: \"Memang Engkau berfirman kepadaku: Suruhlah bangsa ini berangkat, tetapi Engkau tidak memberitahukan kepadaku, siapa yang akan Kauutus bersama-sama dengan aku. Namun demikian Engkau berfirman: Aku mengenal namamu dan juga engkau mendapat kasih karunia di hadapan-Ku.', NULL),
(73942, 3648, 33, 13, 'Maka sekarang, jika aku kiranya mendapat kasih karunia di hadapan-Mu, beritahukanlah kiranya jalan-Mu kepadaku, sehingga aku mengenal Engkau, supaya aku tetap mendapat kasih karunia di hadapan-Mu. Ingatlah, bahwa bangsa ini umat-Mu.\"', NULL),
(73943, 3648, 33, 14, 'Lalu Ia berfirman: \"Aku sendiri hendak membimbing engkau dan memberikan ketenteraman kepadamu.\"', NULL),
(73944, 3648, 33, 15, 'Berkatalah Musa kepada-Nya: \"Jika Engkau sendiri tidak membimbing kami, janganlah suruh kami berangkat dari sini.', NULL),
(73945, 3648, 33, 16, 'Dari manakah gerangan akan diketahui, bahwa aku telah mendapat kasih karunia di hadapan-Mu, yakni aku dengan umat-Mu ini? Bukankah karena Engkau berjalan bersama-sama dengan kami, sehingga kami, aku dengan umat-Mu ini, dibedakan dari segala bangsa yang ada di muka bumi ini?\"', NULL),
(73946, 3648, 33, 17, 'Berfirmanlah TUHAN kepada Musa: \"Juga hal yang telah kaukatakan ini akan Kulakukan, karena engkau telah mendapat kasih karunia di hadapan-Ku dan Aku mengenal engkau.\"', NULL),
(73947, 3648, 33, 18, 'Tetapi jawabnya: \"Perlihatkanlah kiranya kemuliaan-Mu kepadaku.\"', NULL),
(73948, 3648, 33, 19, 'Tetapi firman-Nya: \"Aku akan melewatkan segenap kegemilangan-Ku dari depanmu dan menyerukan nama TUHAN di depanmu: Aku akan memberi kasih karunia kepada siapa yang Kuberi kasih karunia dan mengasihani siapa yang Kukasihani.\"', NULL),
(73949, 3648, 33, 20, 'Lagi firman-Nya: \"Engkau tidak tahan memandang wajah-Ku, sebab tidak ada orang yang memandang Aku dapat hidup.\"', NULL),
(73950, 3648, 33, 21, 'Berfirmanlah TUHAN: \"Ada suatu tempat dekat-Ku, di mana engkau dapat berdiri di atas gunung batu;', NULL),
(73951, 3648, 33, 22, 'apabila kemuliaan-Ku lewat, maka Aku akan menempatkan engkau dalam lekuk gunung itu dan Aku akan menudungi engkau dengan tangan-Ku, sampai Aku berjalan lewat.', NULL),
(73952, 3648, 33, 23, 'Kemudian Aku akan menarik tangan-Ku dan engkau akan melihat belakang-Ku, tetapi wajah-Ku tidak akan kelihatan.\"', NULL),
(73953, 3648, 34, 1, 'Berfirmanlah TUHAN kepada Musa: \"Pahatlah dua loh batu sama dengan yang mula-mula, maka Aku akan menulis pada loh itu segala firman yang ada pada loh yang mula-mula, yang telah kaupecahkan.', 'Dua loh batu yang baru'),
(73954, 3648, 34, 2, 'Bersiaplah menjelang pagi dan naiklah pada waktu pagi ke atas gunung Sinai; berdirilah di sana menghadap Aku di puncak gunung itu.', NULL),
(73955, 3648, 34, 3, 'Tetapi janganlah ada seorangpun yang naik bersama-sama dengan engkau dan juga seorangpun tidak boleh kelihatan di seluruh gunung itu, bahkan kambing domba dan lembu sapipun tidak boleh makan rumput di sekitar gunung itu.\"', NULL),
(73956, 3648, 34, 4, 'Lalu Musa memahat dua loh batu sama dengan yang mula-mula; bangunlah ia pagi-pagi dan naiklah ia ke atas gunung Sinai, seperti yang diperintahkan TUHAN kepadanya, dan membawa kedua loh batu itu di tangannya.', NULL),
(73957, 3648, 34, 5, 'Turunlah TUHAN dalam awan, lalu berdiri di sana dekat Musa serta menyerukan nama TUHAN.', NULL),
(73958, 3648, 34, 6, 'Berjalanlah TUHAN lewat dari depannya dan berseru: \"TUHAN, TUHAN, Allah penyayang dan pengasih, panjang sabar, berlimpah kasih-Nya dan setia-Nya,', NULL),
(73959, 3648, 34, 7, 'yang meneguhkan kasih setia-Nya kepada beribu-ribu orang, yang mengampuni kesalahan, pelanggaran dan dosa; tetapi tidaklah sekali-kali membebaskan orang yang bersalah dari hukuman, yang membalaskan kesalahan bapa kepada anak-anaknya dan cucunya, kepada keturunan yang ketiga dan keempat.\"', NULL),
(73960, 3648, 34, 8, 'Segeralah Musa berlutut ke tanah, lalu sujud menyembah', NULL),
(73961, 3648, 34, 9, 'serta berkata: \"Jika aku telah mendapat kasih karunia di hadapan-Mu, ya Tuhan, berjalanlah kiranya Tuhan di tengah-tengah kami; sekalipun bangsa ini suatu bangsa yang tegar tengkuk, tetapi ampunilah kesalahan dan dosa kami; ambillah kami menjadi milik-Mu.\"', NULL),
(73962, 3648, 34, 10, 'Firman-Nya: \"Sungguh, Aku mengadakan suatu perjanjian. Di depan seluruh bangsamu ini akan Kulakukan perbuatan-perbuatan yang ajaib, seperti yang belum pernah dijadikan di seluruh bumi di antara segala bangsa; seluruh bangsa, yang di tengah-tengahnya engkau diam, akan melihat perbuatan TUHAN, sebab apa yang akan Kulakukan dengan engkau, sungguh-sungguh dahsyat.', NULL),
(73963, 3648, 34, 11, 'Tetapi engkau, berpeganglah pada yang Kuperintahkan kepadamu pada hari ini. Lihat, Aku akan menghalau dari depanmu orang Amori, orang Kanaan, orang Het, orang Feris, orang Hewi dan orang Yebus.', NULL),
(73964, 3648, 34, 12, 'Berawas-awaslah, janganlah kauadakan perjanjian dengan penduduk negeri yang kaudatangi itu, supaya jangan mereka menjadi jerat bagimu di tengah-tengahmu.', NULL),
(73965, 3648, 34, 13, 'Sebaliknya, mezbah-mezbah mereka haruslah kamu rubuhkan, tugu-tugu berhala mereka kamu remukkan, dan tiang-tiang berhala mereka kamu tebang.', NULL),
(73966, 3648, 34, 14, 'Sebab janganlah engkau sujud menyembah kepada allah lain, karena TUHAN, yang nama-Nya Cemburuan, adalah Allah yang cemburu.', NULL),
(73967, 3648, 34, 15, 'Janganlah engkau sampai mengadakan perjanjian dengan penduduk negeri itu; apabila mereka berzinah dengan mengikuti allah mereka dan mempersembahkan korban kepada allah mereka, maka mereka akan mengundang engkau dan engkau akan ikut makan korban sembelihan mereka.', NULL),
(73968, 3648, 34, 16, 'Apabila engkau mengambil anak-anak perempuan mereka menjadi isteri anak-anakmu dan anak-anak perempuan itu akan berzinah dengan mengikuti allah mereka, maka mereka akan membujuk juga anak-anakmu laki-laki untuk berzinah dengan mengikuti allah mereka.', NULL),
(73969, 3648, 34, 17, 'Janganlah kaubuat bagimu allah tuangan.', NULL),
(73970, 3648, 34, 18, 'Hari raya Roti Tidak Beragi haruslah kaupelihara; tujuh hari lamanya engkau harus makan roti yang tidak beragi, seperti yang Kuperintahkan kepadamu, pada waktu yang ditetapkan dalam bulan Abib, sebab dalam bulan Abib itulah engkau keluar dari Mesir.', NULL),
(73971, 3648, 34, 19, 'Segala apa yang lahir terdahulu dari kandungan, Akulah yang empunya, juga segala ternakmu yang jantan, anak yang lahir terdahulu dari lembu atau domba.', NULL),
(73972, 3648, 34, 20, 'Tetapi anak yang lahir terdahulu dari keledai haruslah kautebus dengan seekor domba; jika tidak kautebus, haruslah kaupatahkan batang lehernya. Setiap yang sulung dari antara anak-anakmu haruslah kautebus, dan janganlah orang menghadap ke hadirat-Ku dengan tangan hampa.', NULL),
(73973, 3648, 34, 21, 'Enam harilah lamanya engkau bekerja, tetapi pada hari yang ketujuh haruslah engkau berhenti, dan dalam musim membajak dan musim menuai haruslah engkau memelihara hari perhentian juga.', NULL),
(73974, 3648, 34, 22, 'Hari raya Tujuh Minggu, yakni hari raya buah bungaran dari penuaian gandum, haruslah kaurayakan, juga hari raya pengumpulan hasil pada pergantian tahun.', NULL),
(73975, 3648, 34, 23, 'Tiga kali setahun segala orangmu yang laki-laki harus menghadap ke hadirat Tuhanmu TUHAN, Allah Israel,', NULL),
(73976, 3648, 34, 24, 'sebab Aku akan menghalau bangsa-bangsa dari depanmu dan meluaskan daerahmu; dan tiada seorangpun yang akan mengingini negerimu, apabila engkau pergi untuk menghadap ke hadirat TUHAN, Allahmu, tiga kali setahun.', NULL),
(73977, 3648, 34, 25, 'Janganlah darah korban sembelihan yang kepada-Ku kaupersembahkan beserta sesuatu yang beragi, dan janganlah ada dari korban sembelihan pada hari raya Paskah bermalam sampai pagi.', NULL),
(73978, 3648, 34, 26, 'Yang terbaik dari buah bungaran hasil tanahmu haruslah kaubawa ke dalam rumah TUHAN, Allahmu. Janganlah engkau masak anak kambing dalam susu induknya.\"', NULL),
(73979, 3648, 34, 27, 'Berfirmanlah TUHAN kepada Musa: \"Tuliskanlah segala firman ini, sebab berdasarkan firman ini telah Kuadakan perjanjian dengan engkau dan dengan Israel.\"', NULL),
(73980, 3648, 34, 28, 'Dan Musa ada di sana bersama-sama dengan TUHAN empat puluh hari empat puluh malam lamanya, tidak makan roti dan tidak minum air, dan ia menuliskan pada loh itu segala perkataan perjanjian, yakni Kesepuluh Firman.', NULL),
(73981, 3648, 34, 29, 'Ketika Musa turun dari gunung Sinai--kedua loh hukum Allah ada di tangan Musa ketika ia turun dari gunung itu--tidaklah ia tahu, bahwa kulit mukanya bercahaya oleh karena ia telah berbicara dengan TUHAN.', NULL),
(73982, 3648, 34, 30, 'Ketika Harun dan segala orang Israel melihat Musa, tampak kulit mukanya bercahaya, maka takutlah mereka mendekati dia.', NULL),
(73983, 3648, 34, 31, 'Tetapi Musa memanggil mereka, maka Harun dan segala pemimpin jemaah itu berbalik kepadanya dan Musa berbicara kepada mereka.', NULL),
(73984, 3648, 34, 32, 'Sesudah itu mendekatlah segala orang Israel, lalu disampaikannyalah kepada mereka segala perintah yang diucapkan TUHAN kepadanya di atas gunung Sinai.', NULL),
(73985, 3648, 34, 33, 'Setelah Musa selesai berbicara dengan mereka, diselubunginyalah mukanya.', NULL),
(73986, 3648, 34, 34, 'Tetapi apabila Musa masuk menghadap TUHAN untuk berbicara dengan Dia, ditanggalkannyalah selubung itu sampai ia keluar; dan apabila ia keluar dikatakannyalah kepada orang Israel apa yang diperintahkan kepadanya.', NULL),
(73987, 3648, 34, 35, 'Apabila orang Israel melihat muka Musa, bahwa kulit muka Musa bercahaya, maka Musa menyelubungi mukanya kembali sampai ia masuk menghadap untuk berbicara dengan TUHAN.', NULL),
(73988, 3648, 35, 1, 'Lalu Musa menyuruh berkumpul segenap jemaah Israel dan berkata kepada mereka: \"Inilah firman yang diperintahkan TUHAN untuk dilakukan.', 'Peringatan untuk menguduskan hari Sabat'),
(73989, 3648, 35, 2, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada perhentian kudus bagimu, yakni sabat, hari perhentian penuh bagi TUHAN; setiap orang yang melakukan pekerjaan pada hari itu, haruslah dihukum mati.', NULL),
(73990, 3648, 35, 3, 'Janganlah kamu memasang api di manapun dalam tempat kediamanmu pada hari Sabat.\"', NULL),
(73991, 3648, 35, 4, 'Berfirmanlah TUHAN kepada Musa: \"Pahatlah dua loh batu sama dengan yang mula-mula, maka Aku akan menulis pada loh itu segala firman yang ada pada loh yang mula-mula, yang telah kaupecahkan.', 'Persembahan khusus untuk mendirikan Kemah Suci dan untuk kebaktian di dalamnya'),
(73992, 3648, 35, 5, 'Ambillah bagi TUHAN persembahan khusus dari barang kepunyaanmu; setiap orang yang terdorong hatinya harus membawanya sebagai persembahan khusus kepada TUHAN: emas, perak, tembaga,', NULL),
(73993, 3648, 35, 6, 'kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing;', NULL),
(73994, 3648, 35, 7, 'kulit domba jantan yang diwarnai merah, kulit-kulit lumba-lumba, kayu penaga,', NULL),
(73995, 3648, 35, 8, 'minyak untuk penerangan, rempah-rempah untuk minyak urapan dan untuk ukupan dari wangi-wangian,', NULL),
(73996, 3648, 35, 9, 'permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada.', NULL),
(73997, 3648, 35, 10, 'Segala orang yang ahli di antara kamu haruslah datang untuk membuat segala yang diperintahkan TUHAN,', NULL),
(73998, 3648, 35, 11, 'yakni Kemah Suci, atap kemahnya dan tudungnya, kaitannya, dan papannya, kayu lintangnya, tiangnya dan alasnya;', NULL),
(73999, 3648, 35, 12, 'tabut dengan kayu pengusungnya, tutup pendamaian dan tabir penudung;', NULL),
(74000, 3648, 35, 13, 'meja dengan kayu pengusungnya, segala perkakasnya dan roti sajian;', NULL),
(74001, 3648, 35, 14, 'kandil untuk penerangan dengan perkakasnya, lampunya dan minyak untuk penerangan;', NULL),
(74002, 3648, 35, 15, 'mezbah pembakaran ukupan dengan kayu pengusungnya, minyak urapan dan ukupan dari wangi-wangian; tirai pintu untuk pintu Kemah Suci;', NULL),
(74003, 3648, 35, 16, 'mezbah korban bakaran dengan kisi-kisi tembaganya, kayu pengusungnya dan segala perkakasnya, bejana pembasuhan dengan alasnya;', NULL),
(74004, 3648, 35, 17, 'layar pelataran, tiangnya, alasnya dan tirai pintu gerbang pelataran itu;', NULL),
(74005, 3648, 35, 18, 'patok Kemah Suci dan patok pelataran dan talinya;', NULL),
(74006, 3648, 35, 19, 'pakaian jabatan untuk menyelenggarakan kebaktian di tempat kudus, dan pakaian kudus bagi imam Harun, dan pakaian anak-anaknya untuk memegang jabatan imam.\"', NULL),
(74007, 3648, 35, 20, 'Lalu pergilah segenap jemaah Israel dari depan Musa.', NULL),
(74008, 3648, 35, 21, 'Sesudah itu datanglah setiap orang yang tergerak hatinya, setiap orang yang terdorong jiwanya, membawa persembahan khusus kepada TUHAN untuk pekerjaan melengkapi Kemah Pertemuan dan untuk segala ibadah di dalamnya dan untuk pakaian kudus itu.', NULL),
(74009, 3648, 35, 22, 'Maka datanglah mereka, baik laki-laki maupun perempuan, setiap orang yang terdorong hatinya, dengan membawa anting-anting hidung, anting-anting telinga, cincin meterai dan kerongsang, segala macam barang emas; demikian juga setiap orang yang mempersembahkan persembahan unjukan dari emas bagi TUHAN.', NULL),
(74010, 3648, 35, 23, 'Juga setiap orang yang mempunyai kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing, kulit domba jantan yang diwarnai merah dan kulit lumba-lumba, datang membawanya.', NULL),
(74011, 3648, 35, 24, 'Setiap orang yang hendak mempersembahkan persembahan khusus dari perak atau tembaga, membawa persembahan khusus yang kepada TUHAN itu, dan setiap orang yang mempunyai kayu penaga membawanya juga untuk segala pekerjaan mendirikan itu.', NULL),
(74012, 3648, 35, 25, 'Setiap perempuan yang ahli, memintal dengan tangannya sendiri dan membawa yang dipintalnya itu, yakni kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus.', NULL),
(74013, 3648, 35, 26, 'Semua perempuan yang tergerak hatinya oleh karena ia berkeahlian, memintal bulu kambing.', NULL),
(74014, 3648, 35, 27, 'Pemimpin-pemimpin membawa permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada,', NULL),
(74015, 3648, 35, 28, 'rempah-rempah dan minyak untuk penerangan, untuk minyak urapan dan untuk ukupan dari wangi-wangian.', NULL),
(74016, 3648, 35, 29, 'Semua laki-laki dan perempuan, yang terdorong hatinya akan membawa sesuatu untuk segala pekerjaan yang diperintahkan TUHAN dengan perantaraan Musa untuk dilakukan--mereka itu, yakni orang Israel, membawanya sebagai pemberian sukarela bagi TUHAN.', NULL),
(74017, 3648, 35, 30, 'Berkatalah Musa kepada orang Israel: \"Lihatlah, TUHAN telah menunjuk Bezaleel bin Uri bin Hur, dari suku Yehuda,', 'Pengangkatan Bezaleel dan Aholiab'),
(74018, 3648, 35, 31, 'dan telah memenuhinya dengan Roh Allah, dengan keahlian, pengertian dan pengetahuan, dalam segala macam pekerjaan,', NULL),
(74019, 3648, 35, 32, 'yakni untuk membuat berbagai rancangan supaya dikerjakan dari emas, perak dan tembaga;', NULL),
(74020, 3648, 35, 33, 'untuk mengasah batu permata supaya ditatah; untuk mengukir kayu dan untuk bekerja dalam segala macam pekerjaan yang dirancang itu.', NULL),
(74021, 3648, 35, 34, 'Dan TUHAN menanam dalam hatinya, dan dalam hati Aholiab bin Ahisamakh dari suku Dan, kepandaian untuk mengajar.', NULL),
(74022, 3648, 35, 35, 'Ia telah memenuhi mereka dengan keahlian, untuk membuat segala macam pekerjaan seorang tukang, pekerjaan seorang ahli, pekerjaan seorang yang membuat tenunan yang berwarna-warna dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus, dan pekerjaan seorang tukang tenun, yakni sebagai pelaksana segala macam pekerjaan dan perancang segala sesuatu.', NULL),
(76590, 3648, 36, 1, 'Demikianlah harus bekerja Bezaleel dan Aholiab, dan setiap orang yang ahli, yang telah dikaruniai TUHAN keahlian dan pengertian, sehingga ia tahu melakukan segala macam pekerjaan untuk mendirikan tempat kudus, tepat menurut yang diperintahkan TUHAN.\"', NULL),
(76591, 3648, 36, 2, 'Lalu Musa memanggil Bezaleel dan Aholiab dan setiap orang yang ahli, yang dalam hatinya telah ditanam TUHAN keahlian, setiap orang yang tergerak hatinya untuk datang melakukan pekerjaan itu.', NULL),
(76592, 3648, 36, 3, 'Mereka menerima dari pada Musa seluruh persembahan khusus, yang telah dibawa oleh orang Israel untuk melaksanakan pekerjaan mendirikan tempat kudus. Tetapi orang Israel itu masih terus membawa pemberian sukarela kepada Musa tiap-tiap pagi.', NULL),
(76593, 3648, 36, 4, 'Dan segala orang ahli yang melakukan seluruh pekerjaan untuk tempat kudus itu, datanglah masing-masing dari pekerjaan yang dilakukannya,', NULL),
(76594, 3648, 36, 5, 'dan berkata kepada Musa: \"Rakyat membawa lebih banyak dari yang diperlukan untuk mengerjakan pekerjaan yang diperintahkan TUHAN untuk dilakukan.\"', NULL),
(76595, 3648, 36, 6, 'Lalu Musa memerintahkan, supaya dimaklumkan di mana-mana di perkemahan itu, demikian: \"Tidak usah lagi ada orang laki-laki atau perempuan yang membuat sesuatu menjadi persembahan khusus bagi tempat kudus.\" Demikianlah rakyat itu dicegah membawa persembahan lagi.', NULL),
(76596, 3648, 36, 7, 'Sebab bahan yang diperlukan mereka telah cukup untuk melakukan segala pekerjaan itu, bahkan berlebih.', NULL),
(76597, 3648, 36, 8, 'Lalu semua ahli di antara tukang-tukang itu membuat Kemah Suci dari sepuluh tenda dari lenan halus yang dipintal benangnya dan dari kain ungu tua, kain ungu muda dan kain kirmizi; dengan ada kerubnya, buatan ahli tenun, dibuat orang semuanya itu.', 'Membuat Kemah Suci'),
(76598, 3648, 36, 9, 'Panjang tiap-tiap tenda dua puluh delapan hasta dan lebar tiap-tiap tenda empat hasta: semua tenda itu sama ukurannya.', NULL),
(76599, 3648, 36, 10, 'Lima dari tenda itu dirangkap menjadi satu, dan yang lima lagi juga dirangkap menjadi satu.', NULL),
(76600, 3648, 36, 11, 'Pada rangkapan yang pertama, di tepi satu tenda yang di ujung, dibuatlah sosok-sosok kain ungu tua dan demikian juga di tepi satu tenda yang paling ujung pada rangkapan yang kedua.', NULL),
(76601, 3648, 36, 12, 'Lima puluh sosok dibuat orang pada tenda yang pertama dan lima puluh sosok pada tenda yang di ujung pada rangkapan yang kedua, sehingga sosok-sosok itu tepat berhadapan satu sama lain.', NULL),
(76602, 3648, 36, 13, 'Dibuatlah lima puluh kaitan emas dan disambunglah tenda-tenda Kemah Suci, yang satu dengan yang lain, dengan memakai kaitan itu, sehingga menjadi satu.', NULL),
(76603, 3648, 36, 14, 'Dibuatlah tenda-tenda dari bulu kambing menjadi atap kemah yang menudungi Kemah Suci, sebelas tenda dibuat orang.', NULL),
(76604, 3648, 36, 15, 'Panjang tiap-tiap tenda tiga puluh hasta dan empat hasta lebarnya tiap-tiap tenda: yang sebelas tenda itu sama ukurannya.', NULL),
(76605, 3648, 36, 16, 'Disambunglah lima dari tenda itu dengan tersendiri dan enam dari tenda itu dengan tersendiri.', NULL),
(76606, 3648, 36, 17, 'Dibuatlah lima puluh sosok pada rangkapan yang pertama di tepi satu tenda yang di ujung, dan dibuat lima puluh sosok di tepi satu tenda pada rangkapan yang kedua.', NULL),
(76607, 3648, 36, 18, 'Dibuat oranglah lima puluh kaitan tembaga untuk menyambung tenda-tenda kemah itu, sehingga menjadi satu.', NULL),
(76608, 3648, 36, 19, 'Juga dibuatlah untuk kemah itu tudung dari kulit domba jantan yang diwarnai merah, dan tudung dari kulit lumba-lumba di atasnya lagi.', NULL),
(76609, 3648, 36, 20, 'Dibuat oranglah untuk Kemah Suci itu papan dari kayu penaga yang berdiri tegak,', NULL),
(76610, 3648, 36, 21, 'sepuluh hasta panjangnya satu papan dan satu setengah hasta lebarnya tiap-tiap papan.', NULL),
(76611, 3648, 36, 22, 'Tiap-tiap papan ada dua pasaknya yang disengkang satu sama lain; demikianlah diperbuat dengan segala papan Kemah Suci.', NULL),
(76612, 3648, 36, 23, 'Dibuat oranglah papan-papan untuk Kemah Suci, dua puluh papan pada sebelah selatan.', NULL),
(76613, 3648, 36, 24, 'Dan empat puluh alas perak dibuat orang di bawah kedua puluh papan itu, dua alas di bawah satu papan untuk kedua pasaknya, dan seterusnya dua alas di bawah setiap papan untuk kedua pasaknya.', NULL),
(76614, 3648, 36, 25, 'Juga dibuat orang untuk sisi yang kedua dari Kemah Suci, pada sebelah utara, dua puluh papan', NULL),
(76615, 3648, 36, 26, 'dengan empat puluh alas peraknya: dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', NULL),
(76616, 3648, 36, 27, 'Untuk sisi belakang Kemah Suci, pada sebelah barat, dibuat oranglah enam papan.', NULL),
(76617, 3648, 36, 28, 'Dua papan dibuat orang untuk sudut Kemah Suci, di sisi belakang.', NULL),
(76618, 3648, 36, 29, 'Kedua papan itu kembar pasaknya di sebelah bawah dan seperti itu juga kembar pasaknya di sebelah atas, di dekat gelang yang satu itu, demikianlah dibuat orang dengan kedua papan yang untuk kedua sudutnya itu.', NULL),
(76619, 3648, 36, 30, 'Jadi ada delapan papan dengan alas peraknya: enam belas alas; dua-dua alas di bawah satu papan.', NULL),
(76620, 3648, 36, 31, 'Dibuatlah juga kayu lintang dari kayu penaga: lima untuk papan-papan pada sisi yang satu dari Kemah Suci,', NULL),
(76621, 3648, 36, 32, 'lima kayu lintang untuk papan-papan pada sisi yang kedua dari Kemah Suci, dan lima kayu lintang untuk papan-papan Kemah Suci yang merupakan sisi belakangnya, pada sebelah barat.', NULL),
(76622, 3648, 36, 33, 'Dibuat oranglah kayu lintang yang di tengah menjadi melintang terus di tengah-tengah papan-papan itu dari ujung ke ujung.', NULL),
(76623, 3648, 36, 34, 'Papan-papan itu disalut dengan emas, gelang-gelang itu dibuat dari emas sebagai tempat memasukkan kayu-kayu lintang itu, dan kayu-kayu lintang itu disalut dengan emas.', NULL),
(76624, 3648, 36, 35, 'Dibuatlah tabir itu dari kain ungu tua, dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya; dibuat dengan ada kerubnya, buatan ahli tenun.', NULL),
(76625, 3648, 36, 36, 'Dibuat oranglah untuk itu empat tiang dari kayu penaga dan disalutlah itu dengan emas, dengan ada kaitannya dari emas, lagi dituanglah empat alas perak untuk tiang itu.', NULL),
(76626, 3648, 36, 37, 'Juga dibuat oranglah tirai untuk pintu kemah itu dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: tenunan yang berwarna-warna;', NULL),
(76627, 3648, 36, 38, 'dan kelima tiangnya dengan kaitan untuk tiang itu; disalutlah ujungnya dan penyambung-penyambungnya dengan emas, dan kelima alasnya itu adalah dari tembaga.', NULL),
(76628, 3648, 37, 1, 'Bezaleel membuat tabut itu dari kayu penaga, dua setengah hasta panjangnya, satu setengah hasta lebarnya, dan satu setengah hasta tingginya.', 'Membuat tabut perjanjian'),
(76629, 3648, 37, 2, 'Disalutnyalah itu dengan emas murni, dari dalam dan dari luar, dan dibuatnyalah bingkai emas sekelilingnya.', NULL),
(76630, 3648, 37, 3, 'Dituangnyalah empat gelang emas untuk tabut itu, pada keempat penjurunya, yaitu dua gelang pada rusuknya yang satu dan dua gelang pada rusuknya yang kedua.', NULL),
(76631, 3648, 37, 4, 'Dibuatnyalah kayu pengusung dari kayu penaga dan disalutnyalah itu dengan emas.', NULL),
(76632, 3648, 37, 5, 'Dan dimasukkannyalah kayu pengusung itu ke dalam gelang yang pada rusuk tabut itu, supaya tabut dapat diangkut.', NULL),
(76633, 3648, 37, 6, 'Dibuatnyalah tutup pendamaian dari emas murni, dua setengah hasta panjangnya dan satu setengah hasta lebarnya.', NULL),
(76634, 3648, 37, 7, 'Dibuatnyalah dua kerub dari emas, dari emas tempaan dibuatnya itu, pada kedua ujung tutup pendamaian itu,', NULL),
(76635, 3648, 37, 8, 'satu kerub pada ujung sebelah sini dan satu kerub pada ujung sebelah sana; seiras dengan tutup pendamaian itu dibuatnya kerub itu pada kedua ujungnya.', NULL),
(76636, 3648, 37, 9, 'Kerub-kerub itu mengembangkan kedua sayapnya ke atas, sayap-sayapnya menudungi tutup pendamaian itu dan mukanya menghadap kepada masing-masing; kepada tutup pendamaian itulah menghadap muka kerub-kerub itu.', NULL),
(76637, 3648, 37, 10, 'Dibuatnyalah meja itu dari kayu penaga, dua hasta panjangnya, sehasta lebarnya dan satu setengah hasta tingginya.', 'Membuat meja roti sajian'),
(76638, 3648, 37, 11, 'Disalutnyalah itu dengan emas murni dan dibuatnya bingkai emas sekelilingnya.', NULL),
(76639, 3648, 37, 12, 'Dibuatnyalah sekelilingnya jalur pinggir yang setapak tangan lebarnya dan dibuatnya bingkai emas sekeliling jalur pinggirnya itu.', NULL),
(76640, 3648, 37, 13, 'Dituangnyalah untuk meja itu empat gelang emas dan dipasangnyalah gelang-gelang itu di keempat penjurunya, pada keempat kakinya.', NULL),
(76641, 3648, 37, 14, 'Dekat ke jalur pinggirnyalah gelang itu, yakni tempat memasukkan kayu pengusung, supaya meja itu dapat diangkut.', NULL),
(76642, 3648, 37, 15, 'Dibuatnyalah kayu pengusung itu dari kayu penaga dan disalutnya dengan emas, yaitu supaya meja itu dapat diangkut.', NULL),
(76643, 3648, 37, 16, 'Dan dibuatnyalah perkakas yang di atas meja itu, yakni pinggannya, cawannya, piala dan kendinya, yang dipakai untuk persembahan curahan, semuanya dari emas murni.', NULL),
(76644, 3648, 37, 17, 'Dibuatnyalah kandil itu dari emas murni; dari emas tempaan dibuatnya kandil itu, baik kakinya baik batangnya; kelopaknya--dengan tombolnya dan kembangnya--dibuat seiras dengan kandil itu.', 'Membuat kandil'),
(76645, 3648, 37, 18, 'Ada enam cabang timbul dari sisinya: tiga cabang kandil itu dari sisi yang satu dan tiga cabang dari sisi yang lain.', NULL),
(76646, 3648, 37, 19, 'Tiga kelopak yang berupa bunga badam pada cabang yang satu--dengan tombol dan kembangnya--dan tiga kelopak yang serupa pada cabang yang lain--dengan tombol dan kembangnya--;demikian juga dibuat keenam cabang yang timbul dari kandil itu.', NULL),
(76647, 3648, 37, 20, 'Pada kandil itu sendiri ada empat kelopak berupa bunga badam--dengan tombolnya dan kembangnya.', NULL),
(76648, 3648, 37, 21, 'Juga ada satu tombol di bawah sepasang cabang yang pertama yang timbul dari kandil itu, dan satu tombol di bawah yang kedua, dan satu tombol di bawah yang ketiga; demikianlah juga dibuat keenam cabang yang timbul dari situ.', NULL),
(76649, 3648, 37, 22, 'Tombol dan cabang itu timbul dari kandil itu, dan semuanya itu dibuat dari sepotong emas tempaan yang murni.', NULL),
(76650, 3648, 37, 23, 'Dibuatnyalah pada kandil itu tujuh lampu dengan sepitnya dan penadahnya dari emas murni.', NULL),
(76651, 3648, 37, 24, 'Dari satu talenta emas murni dibuatnyalah kandil itu dengan segala perkakasnya.', NULL),
(76652, 3648, 37, 25, 'Dibuatnyalah mezbah pembakaran ukupan itu dari kayu penaga, sehasta panjangnya dan sehasta lebarnya, empat persegi, tetapi dua hasta tingginya; tanduk-tanduknya seiras dengan mezbah itu.', 'Membuat mezbah pembakaran ukupan'),
(76653, 3648, 37, 26, 'Disalutnyalah itu dengan emas murni, bidang atasnya dan bidang-bidang sisinya sekelilingnya, serta tanduk-tanduknya. Dibuatnyalah bingkai emas sekelilingnya.', NULL),
(76654, 3648, 37, 27, 'Dibuatnyalah dua gelang emas untuk mezbah itu di bawah bingkainya, pada kedua rusuknya, pada kedua bidang sisinya, sebagai tempat memasukkan kayu pengusung, supaya dengan itu mezbah dapat diangkut.', NULL),
(76655, 3648, 37, 28, 'Dan dibuatnyalah kayu pengusung itu dari kayu penaga dan disalutnya dengan emas.', NULL),
(76656, 3648, 37, 29, 'Dan dibuatnyalah minyak urapan yang kudus itu dan ukupan murni dari wangi-wangian, seperti buatan seorang tukang campur rempah-rempah.', 'Membuat minyak urapan dan ukupan dari wangi-wangian'),
(79291, 3648, 38, 1, 'Dibuatnyalah mezbah korban bakaran itu dari kayu penaga, lima hasta panjangnya dan lima hasta lebarnya, empat persegi, tetapi tiga hasta tingginya.', 'Membuat mezbah korban bakaran'),
(79292, 3648, 38, 2, 'Dibuatnyalah tanduk-tanduknya pada keempat sudutnya; tanduk-tanduknya itu dibuat seiras dengan mezbah itu dan disalutnya dengan tembaga.', NULL),
(79293, 3648, 38, 3, 'Dibuatnyalah segala perkakas mezbah itu, yakni kuali-kuali, sodok-sodok, bokor-bokor penyiraman, garpu-garpu dan perbaraan-perbaraan, semua perkakasnya itu dibuatnya dari tembaga.', NULL),
(79294, 3648, 38, 4, 'Dibuatnyalah untuk mezbah itu kisi-kisi, yakni jala-jala tembaga, di bawah jalur, mulai dari sebelah bawah sampai setengah tingginya.', NULL),
(79295, 3648, 38, 5, 'Dituangnyalah empat gelang pada keempat ujung kisi-kisi tembaga itu, yakni tempat memasukkan kayu pengusung.', NULL),
(79296, 3648, 38, 6, 'Dibuatnyalah kayu-kayu pengusung itu dari kayu penaga dan disalutnya dengan tembaga.', NULL),
(79297, 3648, 38, 7, 'Dan dimasukkannyalah kayu-kayu pengusung itu ke dalam gelang-gelang yang pada rusuk mezbah itu, supaya dengan itu mezbah dapat diangkut. Mezbah itu dibuatnya berongga dan dari papan.', NULL),
(79298, 3648, 38, 8, 'Dibuatnyalah bejana pembasuhan dan juga alasnya dari tembaga, dari cermin-cermin para pelayan perempuan yang melayani di depan pintu Kemah Pertemuan.', 'Membuat bejana pembasuhan'),
(79299, 3648, 38, 9, 'Dibuatnyalah pelataran itu; pada sebelah selatan: layar pelataran itu dari lenan halus yang dipintal benangnya, seratus hasta panjangnya;', 'Membuat pelataran'),
(79300, 3648, 38, 10, 'kedua puluh tiang layar itu dengan kedua puluh alas tiang itu dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak.', NULL),
(79301, 3648, 38, 11, 'Pada sebelah utara: seratus hasta; kedua puluh tiang layar itu dengan kedua puluh alas tiang itu dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak.', NULL),
(79302, 3648, 38, 12, 'Pada sebelah barat: layar lima puluh hasta; dengan sepuluh tiangnya dan sepuluh alas tiang itu, dan kaitan-kaitan tiang itu serta penyambung-penyambungnya dari perak.', NULL),
(79303, 3648, 38, 13, 'Dan pada sebelah timur: lima puluh hasta,', NULL),
(79304, 3648, 38, 14, 'yakni layar lima belas hasta untuk sisi yang satu di samping pintu gerbang itu, dengan tiga tiangnya dan tiga alas tiang itu;', NULL),
(79305, 3648, 38, 15, 'dan juga untuk sisi yang kedua di samping pintu gerbang itu--sebelah-menyebelah pintu gerbang pelataran itu ada layar--lima belas hasta, dengan tiga tiangnya dan tiga alas tiang itu.', NULL),
(79306, 3648, 38, 16, 'Segala layar yang mengelilingi pelataran, adalah dari lenan halus yang dipintal benangnya.', NULL),
(79307, 3648, 38, 17, 'Alas-alas untuk tiang-tiang itu adalah dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak, juga salut kepalanya dari perak. Dihubungkanlah dengan penyambung-penyambung dari perak segala tiang-tiang pelataran itu.', NULL),
(79308, 3648, 38, 18, 'Tirai pintu gerbang pelataran itu tenunan yang berwarna-warna dari kain ungu tua, kain ungu muda, kain kirmizi dan dari lenan halus yang dipintal benangnya; dua puluh hasta panjangnya, tetapi tingginya--yang juga lebar kain itu--adalah lima hasta, sama dengan tinggi layar pelataran itu.', NULL),
(79309, 3648, 38, 19, 'Keempat tiangnya dan keempat alas tiang itu dari tembaga; tetapi kaitan-kaitannya dari perak, dan juga salut kepalanya, serta penyambung-penyambungnya dari perak.', NULL),
(79310, 3648, 38, 20, 'Segala patok untuk Kemah Suci dan untuk pelataran itu, sekelilingnya, adalah dari tembaga.', NULL),
(79311, 3648, 38, 21, 'Inilah daftar biaya untuk mendirikan Kemah Suci, yakni Kemah Suci, tempat hukum Allah, yang disusun atas perintah Musa, oleh orang Lewi di bawah pimpinan Itamar, anak imam Harun.', 'Biaya untuk mendirikan Kemah Suci'),
(79312, 3648, 38, 22, 'Bezaleel bin Uri bin Hur, dari suku Yehuda, membuat segala yang diperintahkan TUHAN kepada Musa,', NULL),
(79313, 3648, 38, 23, 'dan bersama-sama dengan dia turut Aholiab, anak Ahisamakh, dari suku Dan, seorang tukang dan ahli, seorang yang membuat tenunan yang berwarna-warna dari kain ungu tua, dari kain ungu muda, dari kain kirmizi dan dari lenan halus. --', NULL),
(79314, 3648, 38, 24, 'Segala emas yang dipakai untuk segala pekerjaan mendirikan tempat kudus itu, yakni emas dari persembahan unjukan, ada dua puluh sembilan talenta dan tujuh ratus tiga puluh syikal, ditimbang menurut syikal kudus.', NULL),
(79315, 3648, 38, 25, 'Perak persembahan mereka yang didaftarkan dari antara jemaah itu ada seratus talenta dan seribu tujuh ratus tujuh puluh lima syikal, ditimbang menurut syikal kudus:', NULL),
(79316, 3648, 38, 26, 'sebeka seorang, yaitu setengah syikal, ditimbang menurut syikal kudus, untuk setiap orang yang termasuk orang-orang yang terdaftar, yang berumur dua puluh tahun ke atas, sejumlah enam ratus tiga ribu lima ratus lima puluh orang.', NULL),
(79317, 3648, 38, 27, 'Seratus talenta perak dipakai untuk menuang alas-alas tempat kudus dan alas-alas tiang tabir itu, seratus alas sesuai dengan seratus talenta itu, jadi satu talenta untuk satu alas.', NULL),
(79318, 3648, 38, 28, 'Dari yang seribu tujuh ratus tujuh puluh lima syikal itu dibuatnyalah kaitan-kaitan untuk tiang-tiang itu, disalutnyalah kepala tiang itu dan dihubungkannya tiang-tiang itu dengan penyambung-penyambung.', NULL),
(79319, 3648, 38, 29, 'Tembaga dari persembahan unjukan itu ada tujuh puluh talenta dan dua ribu empat ratus syikal.', NULL),
(79320, 3648, 38, 30, 'Dari padanya dibuatnyalah alas-alas pintu Kemah Pertemuan, dan mezbah tembaga dengan kisi-kisi tembaganya, segala perkakas mezbah itu,', NULL),
(79321, 3648, 38, 31, 'alas-alas pelataran sekelilingnya, alas-alas pintu gerbang pelataran itu, segala patok Kemah Suci dan segala patok pelataran sekelilingnya.', NULL),
(79322, 3648, 39, 1, 'Dari kain ungu tua, kain ungu muda dan kain kirmizi dibuat merekalah pakaian jabatan yang dipakai apabila diselenggarakan kebaktian di tempat kudus; juga dibuat mereka pakaian-pakaian kudus untuk Harun, seperti yang diperintahkan TUHAN kepada Musa.', 'Membuat pakaian imam'),
(79323, 3648, 39, 2, 'Dibuatnyalah baju efod dari emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', NULL),
(79324, 3648, 39, 3, 'Mereka menempa emas papan dan dipotong-potongnyalah itu menjadi benang emas, untuk dipakankan pada kain ungu tua, pada kain ungu muda, pada kain kirmizi dan pada lenan halus: buatan seorang ahli.', NULL),
(79325, 3648, 39, 4, 'Dibuat merekalah tutup bahu pada baju efod itu, yang disambung kepadanya, dikedua ujungnyalah baju efod itu disambung.', NULL),
(79326, 3648, 39, 5, 'Sabuk pengikat yang ada pada baju efod itu adalah seiras dan sama buatannya dengan baju efod itu, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79327, 3648, 39, 6, 'Dikerjakan merekalah permata krisopras, yakni dililit dengan ikat emas, diukirkan padanya nama para anak Israel, yang diukirkan seperti meterai.', NULL),
(79328, 3648, 39, 7, 'Ditaruhnyalah itu pada kedua tutup bahu baju efod sebagai permata peringatan untuk mengingat orang Israel, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79329, 3648, 39, 8, 'Dibuatnyalah tutup dada, buatan seorang ahli. Buatannya sama dengan baju efod, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', NULL),
(79330, 3648, 39, 9, 'Empat persegi dibuatnya itu; lipat dua dibuat mereka tutup dada itu, sejengkal panjangnya dan sejengkal lebarnya.', NULL),
(79331, 3648, 39, 10, 'Ditatah merekalah itu dengan empat jajar permata: permata yaspis merah, krisolit, malakit, itulah jajar yang pertama;', NULL),
(79332, 3648, 39, 11, 'jajar yang kedua: permata batu darah, lazurit, yaspis hijau;', NULL),
(79333, 3648, 39, 12, 'jajar yang ketiga: permata ambar, akik, kecubung;', NULL),
(79334, 3648, 39, 13, 'jajar yang keempat: permata pirus, krisopras dan nefrit. Dililit dengan ikat emas, demikianlah permata-permata itu dalam tatahannya.', NULL),
(79335, 3648, 39, 14, 'Sesuai dengan nama para anak Israel, permata itu adalah dua belas banyaknya; dan pada tiap-tiap permata ada diukirkan seperti meterai, nama salah satu suku dari yang dua belas itu.', NULL),
(79336, 3648, 39, 15, 'Juga dibuat merekalah untuk tutup dada itu untai berpilin, yang buatannya sebagai tali berjalin, dari emas murni.', NULL),
(79337, 3648, 39, 16, 'Dibuat merekalah dua ikat emas dan dua gelang emas dan kedua gelang itu dipasang pada kedua ujung tutup dada.', NULL),
(79338, 3648, 39, 17, 'Dipasang merekalah kedua untai emas yang berjalin itu pada kedua gelang itu di ujung tutup dada.', NULL),
(79339, 3648, 39, 18, 'Kedua ujung lain dari kedua untai berjalin itu dipasang merekalah pada kedua ikat emas itu, demikianlah dipasang pada tutup bahu baju efod, di sebelah depannya.', NULL),
(79340, 3648, 39, 19, 'Dibuat merekalah dua gelang emas dan dibubuh pada kedua ujung tutup dada itu, pada pinggirnya yang sebelah dalam, yang berhadapan dengan baju efod.', NULL),
(79341, 3648, 39, 20, 'Juga dibuat merekalah dua gelang emas dan dipasang pada kedua tutup bahu baju efod, di sebelah bawah pada bagian depan, dekat ke tempat persambungannya, di sebelah atas sabuk baju efod.', NULL),
(79342, 3648, 39, 21, 'Kemudian diikatkan merekalah tutup dada itu dengan gelangnya kepada gelang baju efod dengan memakai tali ungu tua, sehingga tetap di atas sabuk baju efod, dan tutup dada itu tidak dapat bergeser dari baju efod--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79343, 3648, 39, 22, 'Dibuatnyalah gamis baju efod, buatan tukang tenun, dari kain ungu tua seluruhnya.', NULL),
(79344, 3648, 39, 23, 'Leher gamis itu di tengah-tengahnya seperti leher baju zirah, lehernya itu mempunyai pinggir sekelilingnya, supaya jangan koyak.', NULL),
(79345, 3648, 39, 24, 'Dibuat merekalah pada ujung gamis itu buah delima dari kain ungu tua, kain ungu muda dan kain kirmizi, yang dipintal benangnya.', NULL),
(79346, 3648, 39, 25, 'Dibuat merekalah giring-giring dari emas murni dan ditaruhlah giring-giring itu di antara buah delima, pada ujung gamis itu, berselang-seling di antara buah delima itu,', NULL),
(79347, 3648, 39, 26, 'sehingga satu giring-giring dan satu buah delima selalu berselang-seling, pada sekeliling ujung gamis, yang dipakai apabila diselenggarakan kebaktian seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79348, 3648, 39, 27, 'Dibuat merekalah kemeja dari lenan halus, buatan tukang tenun, untuk Harun dan anak-anaknya,', NULL),
(79349, 3648, 39, 28, 'serban dari lenan halus, destar yang indah dari lenan halus, celana lenan dari lenan halus yang dipintal benangnya,', NULL),
(79350, 3648, 39, 29, 'dan ikat pinggang dari lenan halus yang dipintal benangnya, kain ungu tua, kain ungu muda dan kain kirmizi, dari tenunan yang berwarna-warna--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79351, 3648, 39, 30, 'Dibuat merekalah patam, jamang yang kudus dari emas murni, dan pada jamang itu dituliskan tulisan, diukirkan seperti meterai: Kudus bagi TUHAN.', NULL),
(79352, 3648, 39, 31, 'Dipasang merekalah pada patam itu tali ungu tua untuk mengikatkan patam itu pada serbannya, di sebelah atas--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79353, 3648, 39, 32, 'Demikianlah diselesaikan segala pekerjaan melengkapi Kemah Suci, yakni Kemah Pertemuan itu. Orang Israel telah melakukannya tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah mereka melakukannya.', 'Pekerjaan itu diterima baik oleh Musa'),
(79354, 3648, 39, 33, 'Dibawa merekalah Kemah Suci itu kepada Musa, yakni kemah dengan segala perabotannya: kaitannya, papannya, kayu lintangnya, tiangnya dan alasnya,', NULL),
(79355, 3648, 39, 34, 'tudung dari kulit domba jantan yang diwarnai merah, tudung dari kulit lumba-lumba, tabir penudung,', NULL),
(79356, 3648, 39, 35, 'tabut hukum Allah dengan kayu-kayu pengusungnya dan tutup pendamaian,', NULL),
(79357, 3648, 39, 36, 'meja, segala perkakasnya dan roti sajian,', NULL),
(79358, 3648, 39, 37, 'kandil dari emas murni, lampu-lampunya--lampu yang harus teratur di atasnya--dan segala perkakasnya, minyak untuk penerangan,', NULL),
(79359, 3648, 39, 38, 'mezbah dari emas, minyak urapan, ukupan dari wangi-wangian, tirai pintu kemah,', NULL),
(79360, 3648, 39, 39, 'mezbah tembaga dengan kisi-kisi tembaganya, kayu-kayu pengusungnya dan segala perkakasnya, bejana pembasuhan dengan alasnya,', NULL),
(79361, 3648, 39, 40, 'layar pelataran, tiangnya dan alasnya, dan tirai untuk pintu gerbang pelataran, talinya dan patoknya, segala perkakas untuk pekerjaan mendirikan Kemah Suci, yakni Kemah Pertemuan itu;', NULL),
(79362, 3648, 39, 41, 'pakaian jabatan yang dipakai apabila diselenggarakan kebaktian di tempat kudus, pakaian kudus untuk imam Harun, dan pakaian anak-anaknya untuk memegang jabatan imam.', NULL),
(79363, 3648, 39, 42, 'Tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah dilakukan orang Israel segala pekerjaan melengkapi itu.', NULL),
(79364, 3648, 39, 43, 'Dan Musa melihat segala pekerjaan itu, dan sesungguhnyalah, mereka telah melakukannya seperti yang diperintahkan TUHAN, demikianlah mereka melakukannya. Lalu Musa memberkati mereka.', NULL),
(79365, 3648, 40, 1, 'Berfirmanlah TUHAN kepada Musa:', 'Musa mendirikan Kemah Suci'),
(79366, 3648, 40, 2, '\"Pada hari yang pertama dari bulan yang pertama haruslah engkau mendirikan Kemah Suci, yakni Kemah Pertemuan itu.', NULL),
(79367, 3648, 40, 3, 'Kautempatkanlah di dalamnya tabut hukum dan kaupasanglah tabir sebagai penudung di depan tabut itu.', NULL),
(79368, 3648, 40, 4, 'Kaubawalah ke dalamnya meja dan taruhlah di atasnya perkakas menurut susunannya; kaubawalah ke dalamnya kandil dan kaupasang lampu-lampunya di atasnya.', NULL),
(79369, 3648, 40, 5, 'Kautaruhlah mezbah emas untuk membakar ukupan di depan tabut hukum. Kaugantungkanlah tirai pintu Kemah Suci.', NULL),
(79370, 3648, 40, 6, 'Kautaruhlah mezbah korban bakaran di depan pintu Kemah Suci, yakni Kemah Pertemuan itu.', NULL),
(79371, 3648, 40, 7, 'Kautaruhlah bejana pembasuhan di antara Kemah Pertemuan dan mezbah itu, lalu kautaruhlah air ke dalamnya.', NULL),
(79372, 3648, 40, 8, 'Haruslah kaubuat pelataran keliling dan kaugantungkanlah tirai pintu gerbang pelataran itu.', NULL),
(79373, 3648, 40, 9, 'Kemudian kauambillah minyak urapan dan kauurapilah Kemah Suci dengan segala yang ada di dalamnya; demikianlah harus engkau menguduskannya, dengan segala perabotannya, sehingga menjadi kudus.', NULL),
(79374, 3648, 40, 10, 'Juga kauurapilah mezbah korban bakaran itu dengan segala perkakasnya; demikianlah engkau harus menguduskan mezbah itu, sehingga mezbah itu maha kudus.', NULL),
(79375, 3648, 40, 11, 'Juga kauurapilah bejana pembasuhan itu dengan alasnya, dan demikianlah engkau harus menguduskannya.', NULL),
(79376, 3648, 40, 12, 'Kemudian kausuruhlah Harun dan anak-anaknya datang ke pintu Kemah Pertemuan dan kaubasuhlah mereka dengan air.', NULL),
(79377, 3648, 40, 13, 'Kaukenakanlah pakaian yang kudus kepada Harun, kauurapi dan kaukuduskanlah dia supaya ia memegang jabatan imam bagi-Ku.', NULL),
(79378, 3648, 40, 14, 'Juga anak-anaknya kausuruhlah mendekat dan kaukenakanlah kemeja kepada mereka.', NULL),
(79379, 3648, 40, 15, 'Urapilah mereka, seperti engkau mengurapi ayah mereka, supaya mereka memegang jabatan imam bagi-Ku; dan ini terjadi, supaya berdasarkan pengurapan itu mereka memegang jabatan imam untuk selama-lamanya turun-temurun.\"', NULL),
(79380, 3648, 40, 16, 'Dan Musa melakukan semuanya itu tepat seperti yang diperintahkan TUHAN kepadanya, demikianlah dilakukannya.', NULL),
(79381, 3648, 40, 17, 'Dan terjadilah dalam bulan yang pertama tahun yang kedua, pada tanggal satu bulan itu, maka didirikanlah Kemah Suci.', NULL),
(79382, 3648, 40, 18, 'Musa mendirikan Kemah Suci itu, dipasangnyalah alas-alasnya, ditaruhnya papan-papannya, dipasangnya kayu-kayu lintangnya dan didirikannya tiang-tiangnya.', NULL),
(79383, 3648, 40, 19, 'Dikembangkannyalah atap kemah yang menudungi Kemah Suci dan diletakkannyalah tudung kemah di atasnya--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79384, 3648, 40, 20, 'Diambilnyalah loh hukum Allah dan ditaruhnya ke dalam tabut, dikenakannyalah kayu pengusung pada tabut itu dan diletakkannya tutup pendamaian di atas tabut itu.', NULL),
(79385, 3648, 40, 21, 'Dibawanyalah tabut itu ke dalam Kemah Suci, digantungkannyalah tabir penudung dan dipasangnya sebagai penudung di depan tabut hukum Allah--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79386, 3648, 40, 22, 'Ditaruhnyalah meja di dalam Kemah Pertemuan pada sisi Kemah Suci sebelah utara, di depan tabir itu.', NULL),
(79387, 3648, 40, 23, 'Diletakkannyalah di atasnya roti sajian menurut susunannya, di hadapan TUHAN--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79388, 3648, 40, 24, 'Ditempatkannyalah kandil di dalam Kemah Pertemuan berhadapan dengan meja itu, pada sisi Kemah Suci sebelah selatan.', NULL),
(79389, 3648, 40, 25, 'Dipasangnyalah lampu-lampu di atasnya di hadapan TUHAN--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79390, 3648, 40, 26, 'Ditempatkannyalah mezbah emas di dalam Kemah Pertemuan di depan tabir itu.', NULL),
(79391, 3648, 40, 27, 'Dibakarnyalah di atasnya ukupan dari wangi-wangian seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79392, 3648, 40, 28, 'Digantungkannyalah tirai pintu Kemah Suci.', NULL),
(79393, 3648, 40, 29, 'Mezbah korban bakaran ditempatkannyalah di depan pintu Kemah Suci, yakni Kemah Pertemuan itu, dan dipersembahkannyalah di atasnya korban bakaran dan korban sajian--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79394, 3648, 40, 30, 'Ditempatkannyalah bejana pembasuhan di antara Kemah Pertemuan dan mezbah itu, lalu ditaruhnyalah air ke dalamnya untuk pembasuhan.', NULL),
(79395, 3648, 40, 31, 'Musa dan Harun serta anak-anaknya membasuh tangan dan kaki mereka dengan air dari dalamnya.', NULL),
(79396, 3648, 40, 32, 'Apabila mereka masuk ke dalam Kemah Pertemuan dan apabila mereka datang mendekat kepada mezbah itu, maka mereka membasuh kaki dan tangan--seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(79397, 3648, 40, 33, 'Didirikannyalah tiang-tiang pelataran sekeliling Kemah Suci dan mezbah itu, dan digantungkannyalah tirai pintu gerbang pelataran itu. Demikianlah diselesaikan Musa pekerjaan itu.', NULL),
(79398, 3648, 40, 34, 'Lalu awan itu menutupi Kemah Pertemuan, dan kemuliaan TUHAN memenuhi Kemah Suci,', 'Kemuliaan TUHAN memenuhi Kemah Suci');
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(79399, 3648, 40, 35, 'sehingga Musa tidak dapat memasuki Kemah Pertemuan, sebab awan itu hinggap di atas kemah itu, dan kemuliaan TUHAN memenuhi Kemah Suci.', NULL),
(79400, 3648, 40, 36, 'Apabila awan itu naik dari atas Kemah Suci, berangkatlah orang Israel dari setiap tempat mereka berkemah.', NULL),
(79401, 3648, 40, 37, 'Tetapi jika awan itu tidak naik, maka merekapun tidak berangkat sampai hari awan itu naik.', NULL),
(79402, 3648, 40, 38, 'Sebab awan TUHAN itu ada di atas Kemah Suci pada siang hari, dan pada malam hari ada api di dalamnya, di depan mata seluruh umat Israel pada setiap tempat mereka berkemah.', NULL),
(82149, 3649, 1, 1, 'TUHAN memanggil Musa dan berfirman kepadanya dari dalam Kemah Pertemuan:', 'Korban bakaran'),
(82150, 3649, 1, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila seseorang di antaramu hendak mempersembahkan persembahan kepada TUHAN, haruslah persembahanmu yang kamu persembahkan itu dari ternak, yakni dari lembu sapi atau dari kambing domba.', NULL),
(82151, 3649, 1, 3, 'Jikalau persembahannya merupakan korban bakaran dari lembu, haruslah ia mempersembahkan seekor jantan yang tidak bercela. Ia harus membawanya ke pintu Kemah Pertemuan, supaya TUHAN berkenan akan dia.', NULL),
(82152, 3649, 1, 4, 'Lalu ia harus meletakkan tangannya ke atas kepala korban bakaran itu, sehingga baginya persembahan itu diperkenan untuk mengadakan pendamaian baginya.', NULL),
(82153, 3649, 1, 5, 'Kemudian haruslah ia menyembelih lembu itu di hadapan TUHAN, dan anak-anak Harun, imam-imam itu, harus mempersembahkan darah lembu itu dan menyiramkannya pada sekeliling mezbah yang di depan pintu Kemah Pertemuan.', NULL),
(82154, 3649, 1, 6, 'Kemudian haruslah ia menguliti korban bakaran itu dan memotong-motongnya menurut bagian-bagian tertentu.', NULL),
(82155, 3649, 1, 7, 'Anak-anak imam Harun haruslah menaruh api di atas mezbah dan menyusun kayu di atas api itu.', NULL),
(82156, 3649, 1, 8, 'Dan mereka harus mengatur potongan-potongan korban itu dan kepala serta lemaknya di atas kayu yang sedang menyala di atas mezbah.', NULL),
(82157, 3649, 1, 9, 'Tetapi isi perutnya dan betisnya haruslah dibasuh dengan air dan seluruhnya itu harus dibakar oleh imam di atas mezbah sebagai korban bakaran, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(82158, 3649, 1, 10, 'Jikalau persembahannya untuk korban bakaran adalah dari kambing domba, baik dari domba, maupun dari kambing, haruslah ia mempersembahkan seekor jantan yang tidak bercela.', NULL),
(82159, 3649, 1, 11, 'Haruslah ia menyembelihnya pada sisi mezbah sebelah utara di hadapan TUHAN, lalu haruslah anak-anak Harun, imam-imam itu, menyiramkan darahnya pada mezbah sekelilingnya.', NULL),
(82160, 3649, 1, 12, 'Kemudian haruslah ia memotong-motongnya menurut bagian-bagian tertentu, dan bersama-sama kepalanya dan lemaknya diaturlah semuanya itu oleh imam di atas kayu yang sedang menyala di atas mezbah.', NULL),
(82161, 3649, 1, 13, 'Isi perut dan betisnya haruslah dibasuhnya dengan air, dan seluruhnya itu haruslah dipersembahkan oleh imam dan dibakar di atas mezbah: itulah korban bakaran, suatu korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(82162, 3649, 1, 14, 'Jikalau persembahannya kepada TUHAN merupakan korban bakaran dari burung, haruslah ia mempersembahkan korbannya itu dari burung tekukur atau dari anak burung merpati.', NULL),
(82163, 3649, 1, 15, 'Imam harus membawanya ke mezbah, lalu memulas kepalanya dan membakarnya di atas mezbah. Darahnya harus ditekan ke luar pada dinding mezbah.', NULL),
(82164, 3649, 1, 16, 'Temboloknya serta dengan bulunya haruslah disisihkan dan dibuang ke samping mezbah sebelah timur, ke tempat abu.', NULL),
(82165, 3649, 1, 17, 'Dan ia harus mencabik burung itu pada pangkal sayapnya, tetapi tidak sampai terpisah; lalu imam harus membakarnya di atas mezbah, di atas kayu yang sedang terbakar; itulah korban bakaran, suatu korban api-apian yang baunya menyenangkan bagi TUHAN.\"', NULL),
(87685, 3649, 2, 1, '\"Apabila seseorang hendak mempersembahkan persembahan berupa korban sajian kepada TUHAN, hendaklah persembahannya itu tepung yang terbaik dan ia harus menuangkan minyak serta membubuhkan kemenyan ke atasnya.', 'Korban sajian'),
(87686, 3649, 2, 2, 'Lalu korban itu harus dibawanya kepada anak-anak Harun, imam-imam itu. Setelah diambil dari korban itu tepung segenggam dengan minyak beserta seluruh kemenyannya, maka imam haruslah membakar semuanya itu di atas mezbah sebagai bagian ingat-ingatan korban itu, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(87687, 3649, 2, 3, 'Korban sajian selebihnya adalah teruntuk bagi Harun dan anak-anaknya, yakni bagian maha kudus dari segala korban api-apian TUHAN.', NULL),
(87688, 3649, 2, 4, 'Apabila engkau hendak mempersembahkan persembahan berupa korban sajian dari apa yang dibakar di dalam pembakaran roti, haruslah itu dari tepung yang terbaik, berupa roti bundar yang tidak beragi, yang diolah dengan minyak, atau roti tipis yang tidak beragi, yang diolesi dengan minyak.', NULL),
(87689, 3649, 2, 5, 'Jikalau persembahanmu merupakan korban sajian dari yang dipanggang di atas panggangan, haruslah itu dari tepung yang terbaik, diolah dengan minyak, berupa roti yang tidak beragi.', NULL),
(87690, 3649, 2, 6, 'Korban itu harus dipotong-potong, lalu kautuangkanlah minyak ke atasnya; itulah korban sajian.', NULL),
(87691, 3649, 2, 7, 'Jikalau persembahanmu merupakan korban sajian dari yang dimasak di dalam wajan, haruslah itu diolah dari tepung yang terbaik bersama-sama minyak.', NULL),
(87692, 3649, 2, 8, 'Maka korban sajian yang diolah menurut salah satu cara itu haruslah kaupersembahkan kepada TUHAN, yakni harus disampaikan kepada imam, yang membawanya ke mezbah.', NULL),
(87693, 3649, 2, 9, 'Kemudian imam harus mengkhususkan dari korban sajian itu bagian ingat-ingatannya lalu membakarnya di atas mezbah sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(87694, 3649, 2, 10, 'Korban sajian selebihnya adalah bagian Harun dan anak-anaknya, yakni bagian maha kudus dari segala korban api-apian TUHAN!', NULL),
(87695, 3649, 2, 11, 'Suatu korban sajian yang kamu persembahkan kepada TUHAN janganlah diolah beragi, karena dari ragi atau dari madu tidak boleh kamu membakar sesuatupun sebagai korban api-apian bagi TUHAN.', NULL),
(87696, 3649, 2, 12, 'Tetapi sebagai persembahan dari hasil pertama boleh kamu mempersembahkannya kepada TUHAN, hanya janganlah dibawa ke atas mezbah menjadi bau yang menyenangkan.', NULL),
(87697, 3649, 2, 13, 'Dan tiap-tiap persembahanmu yang berupa korban sajian haruslah kaububuhi garam, janganlah kaulalaikan garam perjanjian Allahmu dari korban sajianmu; beserta segala persembahanmu haruslah kaupersembahkan garam.', NULL),
(87698, 3649, 2, 14, 'Jikalau engkau hendak mempersembahkan korban sajian dari hulu hasil kepada TUHAN, haruslah engkau mempersembahkan bulir gandum yang dipanggang di atas api, emping gandum baru, sebagai korban sajian dari hulu hasil gandummu.', NULL),
(87699, 3649, 2, 15, 'Haruslah kaububuh minyak dan kautaruh kemenyan ke atasnya; itulah korban sajian.', NULL),
(87700, 3649, 2, 16, 'Haruslah imam membakar sebagai ingat-ingatannya, sebagian dari emping gandumnya dan minyaknya beserta seluruh kemenyannya sebagai korban api-apian bagi TUHAN.\"', NULL),
(87701, 3649, 3, 1, '\"Jikalau persembahannya merupakan korban keselamatan, maka jikalau yang dipersembahkannya itu dari lembu, seekor jantan atau seekor betina, haruslah ia membawa yang tidak bercela ke hadapan TUHAN.', NULL),
(87702, 3649, 3, 2, 'Lalu ia harus meletakkan tangannya di atas kepala persembahannya itu, dan menyembelihnya di depan pintu Kemah Pertemuan, lalu anak-anak Harun, imam-imam itu haruslah menyiramkan darahnya pada mezbah sekelilingnya.', NULL),
(87703, 3649, 3, 3, 'Kemudian dari korban keselamatan itu ia harus mempersembahkan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu sebagai korban api-apian bagi TUHAN,', NULL),
(87704, 3649, 3, 4, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', NULL),
(87705, 3649, 3, 5, 'Anak-anak Harun harus membakarnya di atas mezbah, yakni di atas korban bakaran yang sedang dibakar di atas api, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(87706, 3649, 3, 6, 'Jikalau persembahannya untuk korban keselamatan bagi TUHAN adalah dari kambing domba, seekor jantan atau seekor betina, haruslah ia mempersembahkan yang tidak bercela.', NULL),
(87707, 3649, 3, 7, 'Jikalau ia mempersembahkan seekor domba sebagai persembahannya, ia harus membawanya ke hadapan TUHAN.', NULL),
(87708, 3649, 3, 8, 'Lalu ia harus meletakkan tangannya ke atas kepala persembahannya itu dan menyembelihnya di depan Kemah Pertemuan, lalu anak-anak Harun harus menyiramkan darahnya pada mezbah sekelilingnya.', NULL),
(87709, 3649, 3, 9, 'Kemudian dari korban keselamatan itu ia harus mempersembahkan lemaknya sebagai korban api-apian bagi TUHAN, yakni segenap ekornya yang berlemak yang harus dipotong dekat pada tulang belakang, dan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu,', NULL),
(87710, 3649, 3, 10, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang, dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', NULL),
(87711, 3649, 3, 11, 'Imam harus membakarnya di atas mezbah sebagai santapan berupa korban api-apian bagi TUHAN.', NULL),
(87712, 3649, 3, 12, 'Jikalau persembahannya seekor kambing, ia harus membawanya ke hadapan TUHAN.', NULL),
(87713, 3649, 3, 13, 'Lalu ia harus meletakkan tangannya di atas kepala kambing itu dan menyembelihnya di depan Kemah Pertemuan, lalu anak-anak Harun harus menyiramkan darahnya pada mezbah sekelilingnya.', NULL),
(87714, 3649, 3, 14, 'Kemudian dari kambing itu ia harus mempersembahkan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu sebagai persembahannya berupa korban api-apian bagi TUHAN,', NULL),
(87715, 3649, 3, 15, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', NULL),
(87716, 3649, 3, 16, 'Imam harus membakar semuanya itu di atas mezbah sebagai santapan berupa korban api-apian menjadi bau yang menyenangkan. Segala lemak adalah kepunyaan TUHAN.', NULL),
(87717, 3649, 3, 17, 'Inilah suatu ketetapan untuk selamanya bagi kamu turun-temurun di segala tempat kediamanmu: janganlah sekali-kali kamu makan lemak dan darah.\"', NULL),
(93296, 3649, 4, 1, 'TUHAN berfirman kepada Musa:', NULL),
(93297, 3649, 4, 2, '\"Katakanlah kepada orang Israel: Apabila seseorang tidak dengan sengaja berbuat dosa dalam sesuatu hal yang dilarang TUHAN dan ia memang melakukan salah satu dari padanya,', NULL),
(93298, 3649, 4, 3, 'maka jikalau yang berbuat dosa itu imam yang diurapi, sehingga bangsanya turut bersalah, haruslah ia mempersembahkan kepada TUHAN karena dosa yang telah diperbuatnya itu, seekor lembu jantan muda yang tidak bercela sebagai korban penghapus dosa.', NULL),
(93299, 3649, 4, 4, 'Ia harus membawa lembu itu ke pintu Kemah Pertemuan, ke hadapan TUHAN, lalu ia harus meletakkan tangannya ke atas kepala lembu itu, dan menyembelih lembu itu di hadapan TUHAN.', NULL),
(93300, 3649, 4, 5, 'Imam yang diurapi itu harus mengambil sebagian dari darah lembu itu, lalu membawanya ke dalam Kemah Pertemuan.', NULL),
(93301, 3649, 4, 6, 'Imam harus mencelupkan jarinya ke dalam darah itu, dan memercikkan sedikit dari darah itu, tujuh kali di hadapan TUHAN, di depan tabir penyekat tempat kudus.', NULL),
(93302, 3649, 4, 7, 'Kemudian imam itu harus membubuh sedikit dari darah itu pada tanduk-tanduk mezbah pembakaran ukupan dari wangi-wangian, yang ada di hadapan TUHAN di dalam Kemah Pertemuan, dan semua darah selebihnya harus dicurahkannya kepada bagian bawah mezbah korban bakaran yang di depan pintu Kemah Pertemuan.', NULL),
(93303, 3649, 4, 8, 'Segala lemak lembu jantan korban penghapus dosa itu harus dikhususkannya dari lembu itu, yakni lemak yang menyelubungi isi perut dan segala lemak yang melekat pada isi perut itu,', NULL),
(93304, 3649, 4, 9, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang, dan umbai hati yang harus dipisahkannya beserta buah pinggang itu,', NULL),
(93305, 3649, 4, 10, 'sama seperti yang dikhususkan dari lembu korban keselamatan. Imam harus membakar semuanya di atas mezbah korban bakaran.', NULL),
(93306, 3649, 4, 11, 'Adapun kulit lembu jantan itu dan segala dagingnya, beserta kepala dan betisnya dan isi perutnya dan kotorannya,', NULL),
(93307, 3649, 4, 12, 'jadi lembu jantan itu seluruhnya harus dibawanya ke luar perkemahan, ke suatu tempat yang tahir, ke tempat pembuangan abu, dan lembu itu harus dibakarnya sampai habis di atas kayu api di tempat pembuangan abu.', NULL),
(93308, 3649, 4, 13, 'Jikalau yang berbuat dosa dengan tak sengaja itu segenap umat Israel, dan jemaah tidak menyadarinya, sehingga mereka melakukan salah satu hal yang dilarang TUHAN, dan mereka bersalah,', NULL),
(93309, 3649, 4, 14, 'maka apabila dosa yang diperbuat mereka itu ketahuan, haruslah jemaah itu mempersembahkan seekor lembu jantan yang muda sebagai korban penghapus dosa. Lembu itu harus dibawa mereka ke depan Kemah Pertemuan.', NULL),
(93310, 3649, 4, 15, 'Lalu para tua-tua umat itu harus meletakkan tangan mereka di atas kepala lembu jantan itu di hadapan TUHAN, dan lembu itu harus disembelih di hadapan TUHAN.', NULL),
(93311, 3649, 4, 16, 'Imam yang diurapi harus membawa sebagian dari darah lembu itu ke dalam Kemah Pertemuan.', NULL),
(93312, 3649, 4, 17, 'Imam harus mencelupkan jarinya ke dalam darah itu dan memercikkannya tujuh kali di hadapan TUHAN, di depan tabir.', NULL),
(93313, 3649, 4, 18, 'Kemudian dari darah itu harus dibubuhnya sedikit pada tanduk-tanduk mezbah yang di hadapan TUHAN di dalam Kemah Pertemuan, dan semua darah selebihnya harus dicurahkannya kepada bagian bawah mezbah korban bakaran yang di depan pintu Kemah Pertemuan.', NULL),
(93314, 3649, 4, 19, 'Segala lemak harus dikhususkannya dari lembu itu dan dibakarnya di atas mezbah.', NULL),
(93315, 3649, 4, 20, 'Beginilah harus diperbuatnya dengan lembu jantan itu: seperti yang diperbuatnya dengan lembu jantan korban penghapus dosa, demikianlah harus diperbuatnya dengan lembu itu. Dengan demikian imam itu mengadakan pendamaian bagi mereka, sehingga mereka menerima pengampunan.', NULL),
(93316, 3649, 4, 21, 'Dan haruslah ia membawa lembu jantan itu ke luar perkemahan, lalu membakarnya sampai habis seperti ia membakar habis lembu jantan yang pertama. Itulah korban penghapus dosa untuk jemaah.', NULL),
(93317, 3649, 4, 22, 'Jikalau yang berbuat dosa itu seorang pemuka yang tidak dengan sengaja melakukan salah satu hal yang dilarang TUHAN, Allahnya, sehingga ia bersalah,', NULL),
(93318, 3649, 4, 23, 'maka jikalau dosa yang telah diperbuatnya itu diberitahukan kepadanya, haruslah ia membawa sebagai persembahannya seekor kambing jantan yang tidak bercela.', NULL),
(93319, 3649, 4, 24, 'Lalu haruslah ia meletakkan tangannya ke atas kepala kambing itu dan menyembelihnya di tempat yang biasa orang menyembelih korban bakaran di hadapan TUHAN; itulah korban penghapus dosa.', NULL),
(93320, 3649, 4, 25, 'Kemudian haruslah imam mengambil dengan jarinya sedikit dari darah korban penghapus dosa itu, lalu membubuhnya pada tanduk-tanduk mezbah korban bakaran. Darah selebihnya haruslah dicurahkannya kepada bagian bawah mezbah korban bakaran.', NULL),
(93321, 3649, 4, 26, 'Tetapi segala lemak harus dibakarnya di atas mezbah, seperti juga lemak korban keselamatan. Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosanya, sehingga ia menerima pengampunan.', NULL),
(93322, 3649, 4, 27, 'Jikalau yang berbuat dosa dengan tak sengaja itu seorang dari rakyat jelata, dan ia melakukan salah satu hal yang dilarang TUHAN, sehingga ia bersalah,', NULL),
(93323, 3649, 4, 28, 'maka jikalau dosa yang telah diperbuatnya itu diberitahukan kepadanya, haruslah ia membawa sebagai persembahannya karena dosa yang telah diperbuatnya itu seekor kambing betina yang tidak bercela.', NULL),
(93324, 3649, 4, 29, 'Lalu haruslah ia meletakkan tangannya ke atas kepala korban penghapus dosa dan menyembelih korban itu di tempat korban bakaran.', NULL),
(93325, 3649, 4, 30, 'Kemudian imam harus mengambil dengan jarinya sedikit dari darah korban itu, lalu membubuhnya pada tanduk-tanduk mezbah korban bakaran. Semua darah selebihnya haruslah dicurahkannya kepada bagian bawah mezbah.', NULL),
(93326, 3649, 4, 31, 'Tetapi segala lemak haruslah dipisahkannya, seperti juga lemak korban keselamatan dipisahkan, lalu haruslah dibakar oleh imam di atas mezbah menjadi bau yang menyenangkan bagi TUHAN. Dengan demikian imam mengadakan pendamaian bagi orang itu sehingga ia menerima pengampunan.', NULL),
(93327, 3649, 4, 32, 'Jika ia membawa seekor domba sebagai persembahannya menjadi korban penghapus dosa, haruslah ia membawa seekor betina yang tidak bercela.', NULL),
(93328, 3649, 4, 33, 'Lalu haruslah ia meletakkan tangannya ke atas kepala korban penghapus dosa itu, dan menyembelihnya menjadi korban penghapus dosa di tempat yang biasa orang menyembelih korban bakaran.', NULL),
(93329, 3649, 4, 34, 'Kemudian imam harus mengambil dengan jarinya sedikit dari darah korban penghapus dosa itu, lalu membubuhnya pada tanduk-tanduk mezbah korban bakaran. Semua darah selebihnya haruslah dicurahkannya kepada bagian bawah mezbah.', NULL),
(93330, 3649, 4, 35, 'Tetapi segala lemak haruslah dipisahkannya, seperti juga lemak domba korban keselamatan dipisahkan, lalu imam harus membakar semuanya itu di atas mezbah di atas segala korban api-apian TUHAN. Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosa yang telah diperbuatnya, sehingga ia menerima pengampunan.', NULL),
(93331, 3649, 5, 1, 'Apabila seseorang berbuat dosa, yakni jika ia mendengar seorang mengutuki, dan ia dapat naik saksi karena ia melihat atau mengetahuinya, tetapi ia tidak mau memberi keterangan, maka ia harus menanggung kesalahannya sendiri.', NULL),
(93332, 3649, 5, 2, 'Atau bila seseorang kena kepada sesuatu yang najis, baik bangkai binatang liar yang najis, atau bangkai hewan yang najis, atau bangkai binatang yang mengeriap yang najis, tanpa menyadari hal itu, maka ia menjadi najis dan bersalah.', NULL),
(93333, 3649, 5, 3, 'Atau apabila ia kena kepada kenajisan berasal dari manusia, dengan kenajisan apapun juga ia menjadi najis, tanpa menyadari hal itu, tetapi kemudian ia mengetahuinya, maka ia bersalah.', NULL),
(93334, 3649, 5, 4, 'Atau apabila seseorang bersumpah teledor dengan bibirnya hendak berbuat yang buruk atau yang baik, sumpah apapun juga yang diucapkan orang dengan teledor, tanpa menyadari hal itu, tetapi kemudian ia mengetahuinya, maka ia bersalah dalam salah satu perkara itu.', NULL),
(93335, 3649, 5, 5, 'Jadi apabila ia bersalah dalam salah satu perkara itu, haruslah ia mengakui dosa yang telah diperbuatnya itu,', NULL),
(93336, 3649, 5, 6, 'dan haruslah ia mempersembahkan kepada TUHAN sebagai tebusan salah karena dosa itu seekor betina dari domba atau kambing, menjadi korban penghapus dosa. Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosanya.', NULL),
(93337, 3649, 5, 7, 'Tetapi jikalau ia tidak mampu untuk menyediakan kambing atau domba, maka sebagai tebusan salah karena dosa yang telah diperbuatnya itu, haruslah ia mempersembahkan kepada TUHAN dua ekor burung tekukur atau dua ekor anak burung merpati, yang seekor menjadi korban penghapus dosa dan yang seekor lagi menjadi korban bakaran.', NULL),
(93338, 3649, 5, 8, 'Haruslah ia membawanya kepada imam, dan imam itu haruslah lebih dahulu mempersembahkan burung untuk korban penghapus dosa itu. Dan haruslah ia memulas kepalanya pada pangkal tengkuknya, tetapi tidak sampai terpisah.', NULL),
(93339, 3649, 5, 9, 'Sedikit dari darah korban penghapus dosa itu haruslah dipercikkannya ke dinding mezbah, tetapi darah selebihnya haruslah ditekan ke luar pada bagian bawah mezbah; itulah korban penghapus dosa.', NULL),
(93340, 3649, 5, 10, 'Yang kedua haruslah diolahnya menjadi korban bakaran, sesuai dengan peraturan. Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosa yang telah diperbuatnya, sehingga ia menerima pengampunan.', NULL),
(93341, 3649, 5, 11, 'Tetapi jikalau ia tidak mampu menyediakan dua ekor burung tekukur atau dua ekor anak burung merpati, maka haruslah ia membawa sebagai persembahannya karena dosanya itu sepersepuluh efa tepung yang terbaik menjadi korban penghapus dosa. Tidak boleh ditaruhnya minyak dan dibubuhnya kemenyan di atasnya, karena itulah korban penghapus dosa.', NULL),
(93342, 3649, 5, 12, 'Lalu haruslah itu dibawanya kepada imam dan imam itu haruslah mengambil dari padanya segenggam sebagai bagian ingat-ingatannya, lalu membakarnya di atas mezbah di atas segala korban.', NULL),
(93343, 3649, 5, 13, 'Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosanya dalam salah satu perkara itu, sehingga ia menerima pengampunan. Selebihnya adalah bagian imam, sama seperti korban sajian.\"', NULL),
(93344, 3649, 5, 14, 'TUHAN berfirman kepada Musa:', 'Korban penebus salah'),
(93345, 3649, 5, 15, '\"Apabila seseorang berubah setia dan tidak sengaja berbuat dosa dalam sesuatu hal kudus yang dipersembahkan kepada TUHAN, maka haruslah ia mempersembahkan kepada TUHAN sebagai tebusan salahnya seekor domba jantan yang tidak bercela dari kambing domba, dinilai menurut syikal perak, yakni menurut syikal kudus, menjadi korban penebus salah.', NULL),
(93346, 3649, 5, 16, 'Hal kudus yang menyebabkan orang itu berdosa, haruslah dibayar gantinya dengan menambah seperlima, lalu menyerahkannya kepada imam. Imam harus mengadakan pendamaian bagi orang itu dengan domba jantan korban penebus salah itu, sehingga ia menerima pengampunan.', NULL),
(93347, 3649, 5, 17, 'Jikalau seseorang berbuat dosa dengan melakukan salah satu hal yang dilarang TUHAN tanpa mengetahuinya, maka ia bersalah dan harus menanggung kesalahannya sendiri.', NULL),
(93348, 3649, 5, 18, 'Haruslah ia membawa kepada imam seekor domba jantan yang tidak bercela dari kambing domba, yang sudah dinilai, sebagai korban penebus salah. Imam itu haruslah mengadakan pendamaian bagi orang itu karena perbuatan yang tidak disengajanya dan yang tidak diketahuinya itu, sehingga ia menerima pengampunan.', NULL),
(93349, 3649, 5, 19, 'Itulah korban penebus salah; orang itu sungguh bersalah terhadap TUHAN.\"', NULL),
(101879, 3649, 6, 1, 'TUHAN berfirman kepada Musa:', NULL),
(101880, 3649, 6, 2, '\"Apabila seseorang berbuat dosa dan berubah setia terhadap TUHAN, dan memungkiri terhadap sesamanya barang yang dipercayakan kepadanya, atau barang yang diserahkan kepadanya atau barang yang dirampasnya, atau apabila ia telah melakukan pemerasan atas sesamanya,', NULL),
(101881, 3649, 6, 3, 'atau bila ia menemui barang hilang, dan memungkirinya, dan ia bersumpah dusta--dalam perkara apapun yang diperbuat seseorang, sehingga ia berdosa--', NULL),
(101882, 3649, 6, 4, 'apabila dengan demikian ia berbuat dosa dan bersalah, maka haruslah ia memulangkan barang yang telah dirampasnya atau yang telah diperasnya atau yang telah dipercayakan kepadanya atau barang hilang yang ditemuinya itu,', NULL),
(101883, 3649, 6, 5, 'atau segala sesuatu yang dimungkirinya dengan bersumpah dusta. Haruslah ia membayar gantinya sepenuhnya dengan menambah seperlima; haruslah ia menyerahkannya kepada pemiliknya pada hari ia mempersembahkan korban penebus salahnya.', NULL),
(101884, 3649, 6, 6, 'Sebagai korban penebus salahnya haruslah ia mempersembahkan kepada TUHAN seekor domba jantan yang tidak bercela dari kambing domba, yang sudah dinilai, menjadi korban penebus salah, dengan menyerahkannya kepada imam.', NULL),
(101885, 3649, 6, 7, 'Imam harus mengadakan pendamaian bagi orang itu di hadapan TUHAN, sehingga ia menerima pengampunan atas perkara apapun yang diperbuatnya sehingga ia bersalah.\"', NULL),
(101886, 3649, 6, 8, 'TUHAN berfirman kepada Musa:', 'Korban bakaran'),
(101887, 3649, 6, 9, '\"Perintahkanlah kepada Harun dan anak-anaknya: Inilah hukum tentang korban bakaran. Korban bakaran itu haruslah tinggal di atas perapian di atas mezbah semalam-malaman sampai pagi, dan api mezbah haruslah dipelihara menyala di atasnya.', NULL),
(101888, 3649, 6, 10, 'Imam haruslah mengenakan pakaian lenannya, dan mengenakan celana lenan untuk menutup auratnya. Lalu ia harus mengangkat abu yang ada di atas mezbah sesudah korban bakaran habis dimakan api, dan haruslah ia membuangnya di samping mezbah.', NULL),
(101889, 3649, 6, 11, 'Kemudian haruslah ia menanggalkan pakaiannya dan mengenakan pakaian lain, lalu membawa abu itu ke luar perkemahan ke suatu tempat yang tahir.', NULL),
(101890, 3649, 6, 12, 'Api yang di atas mezbah itu harus dijaga supaya terus menyala, jangan dibiarkan padam. Tiap-tiap pagi imam harus menaruh kayu di atas mezbah, mengatur korban bakaran di atasnya dan membakar segala lemak korban keselamatan di sana.', NULL),
(101891, 3649, 6, 13, 'Harus dijaga supaya api tetap menyala di atas mezbah, janganlah dibiarkan padam.\"', NULL),
(101892, 3649, 6, 14, '\"Inilah hukum tentang korban sajian. Anak-anak Harun haruslah membawanya ke hadapan TUHAN ke depan mezbah.', 'Korban sajian'),
(101893, 3649, 6, 15, 'Setelah dikhususkan dari korban sajian itu segenggam tepung yang terbaik dengan minyak, serta seluruh kemenyan yang di atas korban sajian itu, maka haruslah semuanya dibakar di atas mezbah sehingga baunya menyenangkan sebagai bagian ingat-ingatannya bagi TUHAN.', NULL),
(101894, 3649, 6, 16, 'Selebihnya haruslah dimakan oleh Harun dan anak-anaknya; haruslah itu dimakan sebagai roti yang tidak beragi di suatu tempat yang kudus, haruslah mereka memakannya di pelataran Kemah Pertemuan.', NULL),
(101895, 3649, 6, 17, 'Janganlah itu dibakar beragi. Telah Kuberikan itu sebagai bagian mereka dari pada segala korban api-apian-Ku; itulah bagian maha kudus, sama seperti korban penghapus dosa dan korban penghapus salah.', NULL),
(101896, 3649, 6, 18, 'Setiap laki-laki di antara anak-anak Harun haruslah memakannya; itulah suatu ketetapan untuk selamanya bagi kamu turun-temurun; itulah bagianmu dari segala korban api-apian TUHAN. Setiap orang yang kena kepada korban-korban itu menjadi kudus.\"', NULL),
(101897, 3649, 6, 19, 'TUHAN berfirman kepada Musa:', NULL),
(101898, 3649, 6, 20, '\"Inilah persembahan Harun dan anak-anaknya, yang harus dipersembahkan oleh mereka kepada TUHAN pada hari ia diurapi: sepersepuluh efa tepung yang terbaik sebagai korban sajian yang tetap, setengahnya pada waktu pagi dan setengahnya pada waktu petang.', NULL),
(101899, 3649, 6, 21, 'Haruslah itu diolah di atas panggangan bersama-sama minyak, setelah teraduk haruslah engkau membawanya dan mempersembahkannya sebagai korban sajian, sesudah dibakar dan berpotong-potong sebagai bau yang menyenangkan bagi TUHAN.', NULL),
(101900, 3649, 6, 22, 'Dan imam dari antara anak-anaknya yang diurapi sebagai penggantinya, haruslah mengolahnya; itulah suatu ketetapan untuk selamanya. Seluruhnya haruslah dibakar bagi TUHAN.', NULL),
(101901, 3649, 6, 23, 'Tiap-tiap korban sajian dari seorang imam itu haruslah menjadi korban yang terbakar seluruhnya, janganlah dimakan.\"', NULL),
(101902, 3649, 6, 24, 'TUHAN berfirman kepada Musa, demikian:', 'Korban penghapus dosa'),
(101903, 3649, 6, 25, '\"Katakanlah kepada Harun dan anak-anaknya: Inilah hukum tentang korban penghapus dosa. Di tempat korban bakaran disembelih, di situlah harus disembelih korban penghapus dosa di hadapan TUHAN. Itulah persembahan maha kudus.', NULL),
(101904, 3649, 6, 26, 'Imam yang mempersembahkan korban penghapus dosa itulah yang harus memakannya; haruslah itu dimakan di suatu tempat yang kudus, di pelataran Kemah Pertemuan.', NULL),
(101905, 3649, 6, 27, 'Setiap orang yang kena kepada daging korban itu menjadi kudus, dan bila darahnya ada yang tepercik kepada sesuatu pakaian, haruslah engkau mencuci pakaian itu di suatu tempat yang kudus.', NULL),
(101906, 3649, 6, 28, 'Dan belanga tanah, tempat korban itu dimasak, haruslah dipecahkan, dan jikalau dimasak di dalam belanga tembaga, haruslah belanga itu digosok dan dibasuh dengan air.', NULL),
(101907, 3649, 6, 29, 'Setiap laki-laki di antara para imam haruslah memakannya; itulah persembahan maha kudus.', NULL),
(101908, 3649, 6, 30, 'Tetapi setiap korban penghapus dosa, yang dari darahnya dibawa sebagian ke dalam Kemah Pertemuan untuk mengadakan pendamaian di dalam tempat kudus, janganlah dimakan, melainkan dibakar habis dengan api.\"', NULL),
(101909, 3649, 7, 1, '\"Inilah hukum tentang korban penebus salah. Korban itu ialah persembahan maha kudus.', 'Korban penebus salah'),
(101910, 3649, 7, 2, 'Di tempat orang menyembelih korban bakaran, di situlah harus disembelih korban penebus salah, dan darahnya haruslah disiramkan pada mezbah itu sekelilingnya.', NULL),
(101911, 3649, 7, 3, 'Segala lemak dari korban itu haruslah dipersembahkan, yakni ekornya yang berlemak dan lemak yang menutupi isi perut,', NULL),
(101912, 3649, 7, 4, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang, dan umbai hati yang harus dipisahkan beserta buah pinggang itu.', NULL),
(101913, 3649, 7, 5, 'Haruslah imam membakar semuanya itu di atas mezbah sebagai korban api-apian bagi TUHAN; itulah korban penebus salah.', NULL),
(101914, 3649, 7, 6, 'Setiap laki-laki di antara para imam haruslah memakannya; haruslah itu dimakan di suatu tempat yang kudus; itulah bagian maha kudus.', NULL),
(101915, 3649, 7, 7, 'Seperti halnya dengan korban penghapus dosa, demikian juga halnya dengan korban penebus salah; satu hukum berlaku atas keduanya: imam yang mengadakan pendamaian dengan korban itu, bagi dialah korban itu.', NULL),
(101916, 3649, 7, 8, 'Imam yang mempersembahkan korban bakaran seseorang, bagi dia juga kulit korban bakaran yang dipersembahkannya itu.', NULL),
(101917, 3649, 7, 9, 'Tiap-tiap korban sajian yang dibakar di dalam pembakaran roti, dan segala yang diolah di dalam wajan dan di atas panggangan adalah bagi imam yang mempersembahkannya.', NULL),
(101918, 3649, 7, 10, 'Tiap-tiap korban sajian yang diolah dengan minyak atau yang kering adalah bagi semua anak-anak Harun, semuanya dapat bagian.\"', NULL),
(101919, 3649, 7, 11, 'Korban keselamatan', '\"Inilah hukum tentang korban keselamatan, yang harus dipersembahkan orang kepada TUHAN.'),
(101920, 3649, 7, 12, 'Jikalau ia mempersembahkannya untuk memberi syukur, haruslah beserta korban syukur itu dipersembahkannya roti bundar yang tidak beragi yang diolah dengan minyak, dan roti tipis yang tidak beragi yang diolesi dengan minyak, serta roti bundar dari tepung yang terbaik yang teraduk, yang diolah dengan minyak.', NULL),
(101921, 3649, 7, 13, 'Ia harus mempersembahkan persembahannya itu beserta dengan roti bundar yang beragi, di samping korban syukur yang menjadi korban keselamatannya.', NULL),
(101922, 3649, 7, 14, 'Dan dari padanya, yakni dari setiap bagian persembahan itu haruslah dipersembahkannya satu roti sebagai persembahan khusus bagi TUHAN. Persembahan itu adalah bagian imam yang menyiramkan darah korban keselamatan.', NULL),
(101923, 3649, 7, 15, 'Dan daging korban syukur yang menjadi korban keselamatannya itu haruslah dimakan pada hari dipersembahkannya itu. Sedikitpun dari padanya janganlah ditinggalkan sampai pagi.', NULL),
(101924, 3649, 7, 16, 'Jikalau korban sembelihan yang dipersembahkan itu merupakan korban nazar atau korban sukarela, haruslah itu dimakan pada hari mempersembahkannya dan yang selebihnya boleh juga dimakan pada keesokan harinya.', NULL),
(101925, 3649, 7, 17, 'Tetapi apa yang masih tinggal dari daging korban sembelihan itu sampai hari yang ketiga, haruslah dibakar habis dengan api.', NULL),
(101926, 3649, 7, 18, 'Karena jikalau pada hari yang ketiga masih dimakan dari daging korban keselamatan itu, maka TUHAN tidak berkenan akan orang yang mempersembahkannya dan korban itu dianggap batal baginya, bahkan menjadi sesuatu yang jijik, dan orang yang memakannya harus menanggung kesalahannya sendiri.', NULL),
(101927, 3649, 7, 19, 'Bila daging itu kena kepada sesuatu yang najis, janganlah dimakan, tetapi haruslah dibakar habis dengan api. Tiap-tiap orang yang tahir boleh memakan dari daging korban itu.', NULL),
(101928, 3649, 7, 20, 'Tetapi seseorang yang memakan daging dari korban keselamatan yang untuk TUHAN, sedang ia dalam keadaan najis, haruslah nyawa orang itu dilenyapkan dari antara bangsanya.', NULL),
(101929, 3649, 7, 21, 'Dan apabila seseorang kena kepada sesuatu yang najis, yakni kepada kenajisan berasal dari manusia, atau kepada hewan yang najis atau kepada setiap binatang yang merayap yang najis, lalu memakan dari pada daging korban keselamatan yang untuk TUHAN, maka haruslah nyawa orang itu dilenyapkan dari antara bangsanya.\"', NULL),
(101930, 3649, 7, 22, 'TUHAN berfirman kepada Musa:', 'Larangan memakan lemak dan darah'),
(101931, 3649, 7, 23, '\"Katakanlah kepada orang Israel: Segala lemak dari lembu, domba ataupun kambing janganlah kamu makan.', NULL),
(101932, 3649, 7, 24, 'Lemak bangkai atau lemak binatang yang mati diterkam boleh dipergunakan untuk segala keperluan, tetapi jangan sekali-kali kamu memakannya.', NULL),
(101933, 3649, 7, 25, 'Karena setiap orang yang memakan lemak dari hewan yang dipergunakan untuk mempersembahkan korban api-apian bagi TUHAN, nyawa orang yang memakan itu, haruslah dilenyapkan dari antara bangsanya.', NULL),
(101934, 3649, 7, 26, 'Demikian juga janganlah kamu memakan darah apapun di segala tempat kediamanmu, baik darah burung-burung ataupun darah hewan.', NULL),
(101935, 3649, 7, 27, 'Setiap orang yang memakan darah apapun, nyawa orang itu haruslah dilenyapkan dari antara bangsanya.\"', NULL),
(101936, 3649, 7, 28, 'TUHAN berfirman kepada Musa, demikian:', 'Bagian imam dari pada segala korban keselamatan'),
(101937, 3649, 7, 29, '\"Katakanlah kepada orang Israel: Orang yang mempersembahkan korban keselamatannya kepada TUHAN, haruslah membawa kepada TUHAN sebagian dari korban keselamatannya itu sebagai persembahannya.', NULL),
(101938, 3649, 7, 30, 'Dengan tangannya sendirilah harus ia membawa segala korban api-apian TUHAN; adapun lemaknya, haruslah dibawanya beserta dadanya, supaya dadanya itu diunjukkan sebagai persembahan unjukan di hadapan TUHAN.', NULL),
(101939, 3649, 7, 31, 'Lalu haruslah imam membakar lemaknya di atas mezbah, tetapi dadanya itu adalah bagian Harun dan anak-anaknya.', NULL),
(101940, 3649, 7, 32, 'Paha kanannya harus kamu serahkan kepada imam sebagai persembahan khusus dari segala korban keselamatanmu.', NULL),
(101941, 3649, 7, 33, 'Siapa dari antara anak-anak Harun yang mempersembahkan darah dan lemak korban keselamatan, maka dialah yang harus mendapat paha kanan itu sebagai bagiannya.', NULL),
(101942, 3649, 7, 34, 'Karena dada persembahan unjukan dan paha persembahan khusus telah Kuambil dari orang Israel dari segala korban keselamatan mereka dan telah Kuberikan kepada imam Harun, dan kepada anak-anaknya; itulah suatu ketetapan yang berlaku bagi orang Israel untuk selamanya.\"', NULL),
(101943, 3649, 7, 35, 'Itulah bagian Harun dan bagian anak-anaknya dari segala korban api-apian TUHAN pada hari mereka itu disuruh datang untuk memegang jabatan imam bagi TUHAN;', NULL),
(101944, 3649, 7, 36, 'itulah yang harus diserahkan menurut perintah TUHAN dari pihak Israel kepada mereka pada hari mereka itu diurapi-Nya; itulah suatu ketetapan untuk selamanya bagi mereka turun-temurun.', NULL),
(101945, 3649, 7, 37, 'Itulah hukum tentang korban bakaran, korban sajian, korban penghapus dosa, korban penebus salah, persembahan pentahbisan dan korban keselamatan,', NULL),
(101946, 3649, 7, 38, 'yang diperintahkan TUHAN kepada Musa di atas gunung Sinai pada hari TUHAN memerintahkan kepada orang Israel mempersembahkan persembahan mereka kepada TUHAN di padang gurun Sinai.', NULL),
(101947, 3649, 8, 1, 'TUHAN berfirman kepada Musa:', 'Pentahbisan Harun dan anak-anaknya'),
(101948, 3649, 8, 2, '\"Panggillah Harun dan anak-anaknya bersama-sama dengan dia, dan ambillah pakaian-pakaian, minyak urapan, dan lembu jantan korban penghapus dosa, dua domba jantan dan bakul berisi roti yang tidak beragi,', NULL),
(101949, 3649, 8, 3, 'lalu suruhlah berkumpul segenap umat ke depan pintu Kemah Pertemuan.\"', NULL),
(101950, 3649, 8, 4, 'Musa melakukan seperti yang diperintahkan TUHAN kepadanya, lalu berkumpullah umat itu di depan Kemah Pertemuan.', NULL),
(101951, 3649, 8, 5, 'Berkatalah Musa kepada umat itu: \"Inilah firman yang diperintahkan TUHAN untuk dilakukan.\"', NULL),
(101952, 3649, 8, 6, 'Lalu Musa menyuruh Harun dan anak-anaknya mendekat, dan dibasuhnyalah mereka dengan air.', NULL),
(101953, 3649, 8, 7, 'Sesudah itu dikenakannyalah kemeja kepadanya, diikatkannya ikat pinggang, dikenakannya gamis, dikenakannya baju efod, diikatkannya sabuk baju efod dan dikebatkannya sabuk itu kepadanya.', NULL),
(101954, 3649, 8, 8, 'Dikenakannyalah tutup dada kepadanya dan dibubuhnya di dalam tutup dada itu Urim dan Tumim.', NULL),
(101955, 3649, 8, 9, 'Kemudian ditaruhnyalah serban di kepalanya, dan di atas serban itu di sebelah depan ditaruhnyalah patam emas, yakni jamang yang kudus, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101956, 3649, 8, 10, 'Musa mengambil minyak urapan, lalu diurapinyalah Kemah Suci serta segala yang ada di dalamnya dan dikuduskannya semuanya itu.', NULL),
(101957, 3649, 8, 11, 'Dipercikkannyalah sedikit dari minyak itu ke mezbah tujuh kali dan diurapinya mezbah itu serta segala perkakasnya, dan juga bejana pembasuhan serta alasnya untuk menguduskannya.', NULL),
(101958, 3649, 8, 12, 'Kemudian dituangkannya sedikit dari minyak urapan itu ke atas kepala Harun dan diurapinyalah dia untuk menguduskannya.', NULL),
(101959, 3649, 8, 13, 'Musa menyuruh anak-anak Harun mendekat, lalu dikenakannyalah kemeja kepada mereka, diikatkannya ikat pinggang dan dililitkannya destar, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101960, 3649, 8, 14, 'Disuruhnyalah membawa lembu jantan korban penghapus dosa, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala lembu jantan korban penghapus dosa itu.', NULL),
(101961, 3649, 8, 15, 'Lembu itu disembelih, lalu Musa mengambil darahnya, kemudian dengan jarinya dibubuhnyalah darah itu pada tanduk-tanduk mezbah sekelilingnya, dan dengan demikian disucikannyalah mezbah itu dari dosa; darah selebihnya dituangkannya pada bagian bawah mezbah. Dengan demikian dikuduskannya mezbah itu dan diadakannya pendamaian baginya.', NULL),
(101962, 3649, 8, 16, 'Diambillah segala lemak yang melekat pada isi perut, umbai hati, kedua buah pinggang serta lemaknya, lalu Musa membakarnya di atas mezbah.', NULL),
(101963, 3649, 8, 17, 'Tetapi lembu jantan itu dengan kulit, daging dan kotorannya dibakarnya habis di luar perkemahan, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101964, 3649, 8, 18, 'Kemudian disuruhnya membawa domba jantan korban bakaran, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', NULL),
(101965, 3649, 8, 19, 'Domba itu disembelih, lalu Musa menyiramkan darahnya pada mezbah sekelilingnya.', NULL),
(101966, 3649, 8, 20, 'Domba itu dipotong-potong menurut bagian-bagian tertentu, lalu Musa membakar kepalanya dan bagian-bagiannya dan lemaknya.', NULL),
(101967, 3649, 8, 21, 'Tetapi isi perut dan betisnya dibasuh dengan air, lalu Musa membakar seluruh domba jantan itu di atas mezbah. Itulah korban bakaran, yang baunya menyenangkan; yakni suatu korban api-apian bagi TUHAN, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101968, 3649, 8, 22, 'Kemudian disuruhnya membawa domba jantan yang lain, yakni domba persembahan pentahbisan, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', NULL),
(101969, 3649, 8, 23, 'Domba jantan itu disembelih, lalu Musa mengambil sedikit dari darahnya dan membubuhnya pada cuping telinga kanan Harun, pada ibu jari tangan kanan dan pada ibu jari kaki kanannya.', NULL),
(101970, 3649, 8, 24, 'Musa menyuruh anak-anak Harun mendekat, lalu membubuh sedikit dari darah itu pada cuping telinga kanan mereka, pada ibu jari tangan kanan dan pada ibu jari kaki kanan mereka, lalu Musa menyiramkan darah selebihnya pada mezbah sekelilingnya.', NULL),
(101971, 3649, 8, 25, 'Diambilnyalah lemaknya, ekornya yang berlemak, segala lemaknya yang melekat pada isi perut, umbai hatinya, kedua buah pinggang serta lemaknya dan paha kanannya.', NULL),
(101972, 3649, 8, 26, 'Dan dari dalam bakul berisi roti yang tidak beragi, yang ada di hadapan TUHAN, diambilnyalah satu roti bundar yang tidak beragi, satu roti bundar yang diolah dengan minyak dan satu roti tipis, lalu diletakkannya di atas segala lemak dan di atas paha kanan itu,', NULL),
(101973, 3649, 8, 27, 'dan ditaruhnya seluruhnya di telapak tangan Harun dan di telapak tangan anak-anaknya, dan dipersembahkannya semuanya sebagai persembahan unjukan di hadapan TUHAN.', NULL),
(101974, 3649, 8, 28, 'Kemudian Musa mengambil semuanya dari telapak tangan mereka, lalu dibakarnya di atas mezbah, yaitu di atas korban bakaran. Itulah persembahan pentahbisan untuk menjadi bau yang menyenangkan; itulah suatu korban api-apian bagi TUHAN.', NULL),
(101975, 3649, 8, 29, 'Musa mengambil dada domba itu, dan mempersembahkannya sebagai persembahan unjukan di hadapan TUHAN. Itulah yang didapat Musa sebagai bagiannya dari domba jantan persembahan pentahbisan itu, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101976, 3649, 8, 30, 'Dan lagi Musa mengambil sedikit dari minyak urapan dan dari darah yang di atas mezbah itu, lalu dipercikkannya kepada Harun, ke pakaiannya, dan juga kepada anak-anaknya dan ke pakaian anak-anaknya. Dengan demikian ditahbiskannyalah Harun, pakaiannya, dan juga anak-anaknya dan pakaian anak-anaknya.', NULL),
(101977, 3649, 8, 31, 'Berkatalah Musa kepada Harun dan kepada anak-anaknya: \"Masaklah daging itu di depan pintu Kemah Pertemuan; di sanalah harus kamu memakannya dengan roti yang ada di dalam bakul untuk persembahan pentahbisan, seperti yang telah kuperintahkan dengan berkata: Harun dan anak-anaknya haruslah memakannya.', NULL),
(101978, 3649, 8, 32, 'Dan apa yang tinggal dari daging dan roti itu haruslah kamu bakar habis dengan api.', NULL),
(101979, 3649, 8, 33, 'Janganlah kamu pergi dari depan pintu Kemah Pertemuan selama tujuh hari, sampai kepada genapnya perayaan pentahbisan, karena perayaan pentahbisan akan berlangsung tujuh hari lamanya.', NULL),
(101980, 3649, 8, 34, 'Seperti yang diperbuat pada hari ini, demikian juga diperintahkan TUHAN kamu perbuat kelak untuk mengadakan pendamaian bagimu.', NULL),
(101981, 3649, 8, 35, 'Di depan pintu Kemah Pertemuan haruslah kamu tinggal siang malam tujuh hari lamanya, dan kamu harus lakukan kewajibanmu terhadap TUHAN dengan setia, supaya janganlah kamu mati, karena demikianlah diperintahkan kepadaku.\"', NULL),
(101982, 3649, 8, 36, 'Maka Harun dan anak-anaknya melakukan segala firman yang diperintahkan TUHAN dengan perantaraan Musa.', NULL),
(101983, 3649, 9, 1, 'Pada hari yang kedelapan Musa memanggil Harun serta anak-anaknya dan para tua-tua Israel,', NULL),
(101984, 3649, 9, 2, 'lalu berkatalah ia kepada Harun: \"Ambillah bagimu sendiri seekor lembu muda, untuk korban penghapus dosa, dan seekor domba jantan untuk korban bakaran, kedua-duanya yang tidak bercela, kemudian persembahkanlah itu di hadapan TUHAN.', NULL),
(101985, 3649, 9, 3, 'Dan kepada orang Israel haruslah engkau berkata, begini: Ambillah seekor kambing jantan untuk korban penghapus dosa, dan seekor anak lembu dan seekor domba, masing-masing berumur setahun dan yang tidak bercela, untuk korban bakaran.', NULL),
(101986, 3649, 9, 4, 'Dan lagi seekor lembu dan seekor domba jantan untuk korban keselamatan, supaya dikorbankan di hadapan TUHAN, dan korban sajian yang diolah dengan minyak, karena pada hari ini TUHAN akan menampakkan diri kepadamu.\"', NULL),
(101987, 3649, 9, 5, 'Kemudian dibawa merekalah apa yang diperintahkan Musa ke Kemah Pertemuan, lalu mendekatlah segenap umat itu dan berdiri di hadapan TUHAN.', NULL),
(101988, 3649, 9, 6, 'Kata Musa: \"Inilah firman yang diperintahkan TUHAN kamu perbuat, agar kemuliaan TUHAN tampak kepadamu.\"', NULL),
(101989, 3649, 9, 7, 'Kata Musa kepada Harun: \"Datanglah mendekat kepada mezbah, olahlah korban penghapus dosa dan korban bakaranmu, dan adakanlah pendamaian bagimu sendiri dan bagi bangsa itu; sesudah itu olahlah persembahan bangsa itu dan adakanlah pendamaian bagi mereka, seperti yang diperintahkan TUHAN.\"', NULL),
(101990, 3649, 9, 8, 'Maka mendekatlah Harun kepada mezbah, dan disembelihnyalah anak lembu yang akan menjadi korban penghapus dosa baginya sendiri.', NULL),
(101991, 3649, 9, 9, 'Anak-anak Harun menyampaikan darah lembu itu kepadanya, dan Harun mencelupkan jarinya ke dalam darah itu dan membubuhnya pada tanduk-tanduk mezbah. Darah selebihnya dituangkannya pada bagian bawah mezbah.', NULL),
(101992, 3649, 9, 10, 'Lemak, buah pinggang dan umbai hati dari korban penghapus dosa itu dibakarnya di atas mezbah, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(101993, 3649, 9, 11, 'Tetapi daging dan kulitnya dibakarnya habis di luar perkemahan.', NULL),
(101994, 3649, 9, 12, 'Kemudian ia menyembelih korban bakaran, lalu anak-anak Harun menyerahkan darah korban itu kepadanya, maka Harun menyiramkannya pada mezbah sekelilingnya.', NULL),
(101995, 3649, 9, 13, 'Juga diserahkan merekalah kepadanya korban bakaran itu menurut bagian-bagian tertentu beserta dengan kepalanya, lalu dibakarnya di atas mezbah.', NULL),
(101996, 3649, 9, 14, 'Isi perut dan betisnya dibasuhnya dan dibakarnya dengan korban bakaran di atas mezbah.', NULL),
(101997, 3649, 9, 15, 'Sesudah itu dibawanya persembahan bangsa ke mezbah; diambilnyalah kambing jantan yang akan menjadi korban penghapus dosa yang bagi bangsa itu, lalu disembelihnya dan dipersembahkannya sebagai korban penghapus dosa seperti yang pertama.', NULL),
(101998, 3649, 9, 16, 'Kemudian dibawanyalah korban bakaran ke mezbah, dan diolahnya sesuai dengan peraturan.', NULL),
(101999, 3649, 9, 17, 'Selanjutnya dibawanyalah korban sajian dan diambilnya segenggam dari padanya, lalu dibakarnya di atas mezbah, di samping korban bakaran pada waktu pagi.', NULL),
(102000, 3649, 9, 18, 'Ia menyembelih juga lembu dan domba jantan yang akan menjadi korban keselamatan bagi bangsa itu, lalu anak-anak Harun menyerahkan darah korban itu kepadanya, maka Harun menyiramkannya pada mezbah sekelilingnya.', NULL),
(102001, 3649, 9, 19, 'Tetapi segala lemak dari lembu dan dari domba jantan itu, yakni ekor yang berlemak, lemak yang menutupi isi perut, buah pinggang dan umbai hati,', NULL),
(102002, 3649, 9, 20, 'segala lemak itu diletakkan mereka di atas dada kedua korban itu, lalu Harun membakar segala lemak itu di atas mezbah.', NULL),
(102003, 3649, 9, 21, 'Dada dan paha kanan itu dipersembahkan Harun sebagai persembahan unjukan di hadapan TUHAN, seperti yang diperintahkan Musa.', NULL),
(102004, 3649, 9, 22, 'Harun mengangkat kedua tangannya atas bangsa itu, lalu memberkati mereka, kemudian turunlah ia, setelah mempersembahkan korban penghapus dosa, korban bakaran dan korban keselamatan.', NULL),
(102005, 3649, 9, 23, 'Masuklah Musa dan Harun ke dalam Kemah Pertemuan. Setelah keluar, mereka memberkati bangsa itu, lalu tampaklah kemuliaan TUHAN kepada segenap bangsa itu.', NULL),
(102006, 3649, 9, 24, 'Dan keluarlah api dari hadapan TUHAN, lalu menghanguskan korban bakaran dan segala lemak di atas mezbah. Tatkala seluruh bangsa itu melihatnya, bersorak-sorailah mereka, lalu sujud menyembah.', NULL),
(102007, 3649, 10, 1, 'Kemudian anak-anak Harun, Nadab dan Abihu, masing-masing mengambil perbaraannya, membubuh api ke dalamnya serta menaruh ukupan di atas api itu. Dengan demikian mereka mempersembahkan ke hadapan TUHAN api yang asing yang tidak diperintahkan-Nya kepada mereka.', 'Kematian Nadab dan Abihu'),
(102008, 3649, 10, 2, 'Maka keluarlah api dari hadapan TUHAN, lalu menghanguskan keduanya, sehingga mati di hadapan TUHAN.', NULL),
(102009, 3649, 10, 3, 'Berkatalah Musa kepada Harun: \"Inilah yang difirmankan TUHAN: Kepada orang yang karib kepada-Ku Kunyatakan kekudusan-Ku, dan di muka seluruh bangsa itu akan Kuperlihatkan kemuliaan-Ku.\" Dan Harun berdiam diri.', NULL),
(102010, 3649, 10, 4, 'Kemudian Musa memanggil Misael dan Elsafan, anak-anak Uziel, paman Harun, lalu berkatalah ia kepada mereka: \"Datang ke mari, angkatlah saudara-saudaramu ini dari depan tempat kudus ke luar perkemahan.\"', NULL),
(102011, 3649, 10, 5, 'Mereka datang, dan mengangkat mayat keduanya, masih berpakaian kemeja, ke luar perkemahan, seperti yang dikatakan Musa.', NULL),
(102012, 3649, 10, 6, 'Kemudian berkatalah Musa kepada Harun dan kepada Eleazar dan Itamar, anak-anak Harun: \"Janganlah kamu berkabung dan janganlah kamu berdukacita, supaya jangan kamu mati dan jangan TUHAN memurkai segenap umat ini, tetapi saudara-saudaramu, yaitu seluruh bangsa Israel, merekalah yang harus menangis karena api yang dinyalakan TUHAN itu.', NULL),
(102013, 3649, 10, 7, 'Janganlah kamu pergi dari depan pintu Kemah Pertemuan, supaya jangan kamu mati, karena minyak urapan TUHAN ada di atasmu.\" Mereka melakukan sesuai dengan perkataan Musa.', NULL),
(102014, 3649, 10, 8, 'TUHAN berfirman kepada Harun:', 'Larangan tentang minuman keras bagi imam yang menyelenggarakan kebaktian'),
(102015, 3649, 10, 9, '\"Janganlah engkau minum anggur atau minuman keras, engkau serta anak-anakmu, bila kamu masuk ke dalam Kemah Pertemuan, supaya jangan kamu mati. Itulah suatu ketetapan untuk selamanya bagi kamu turun-temurun.', NULL),
(102016, 3649, 10, 10, 'Haruslah kamu dapat membedakan antara yang kudus dengan yang tidak kudus, antara yang najis dengan yang tidak najis,', NULL),
(102017, 3649, 10, 11, 'dan haruslah kamu dapat mengajarkan kepada orang Israel segala ketetapan yang telah difirmankan TUHAN kepada mereka dengan perantaraan Musa.\"', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(102018, 3649, 10, 12, 'Kemudian berkatalah Musa kepada Harun dan kepada Eleazar dan Itamar, anak-anak Harun yang tinggal itu: \"Ambillah korban sajian yang tinggal dari segala korban api-apian TUHAN, dan makanlah itu sebagai roti yang tidak beragi di samping mezbah, karena itulah bagian maha kudus.', 'Bagian imam dari korban'),
(102019, 3649, 10, 13, 'Haruslah kamu memakannya di suatu tempat yang kudus, karena itulah ketetapan bagimu dan anak-anakmu dari segala korban api-apian TUHAN, sebab demikianlah diperintahkan kepadaku.', NULL),
(102020, 3649, 10, 14, 'Dada persembahan unjukan dan paha persembahan khusus itu haruslah kamu makan di suatu tempat yang tahir, engkau ini serta anak-anakmu laki-laki dan perempuan, karena semuanya diberikan sebagai ketetapan bagimu dan anak-anakmu dari segala korban keselamatan orang Israel.', NULL),
(102021, 3649, 10, 15, 'Paha persembahan khusus dan dada persembahan unjukan itu haruslah dibawa mereka ke tempat segala korban api-apian yang dari lemak itu, supaya dipersembahkan sebagai persembahan unjukan di hadapan TUHAN. Itulah suatu ketetapan untuk selamanya bagimu serta bagi anak-anakmu seperti yang diperintahkan TUHAN.\"', NULL),
(102022, 3649, 10, 16, 'Kemudian Musa mencari dengan teliti kambing jantan korban penghapus dosa itu, tetapi ternyata kambing itu sudah habis dibakar. Sebab itu dimarahinyalah Eleazar dan Itamar, anak-anak Harun yang tinggal itu, katanya:', NULL),
(102023, 3649, 10, 17, '\"Mengapa tidak kamu makan korban penghapus dosa itu di tempat yang kudus? Bukankah itu sesuatu bagian maha kudus dan TUHAN memberikannya kepadamu, supaya kamu mengangkut kesalahan umat itu dan mengadakan pendamaian bagi mereka di hadapan TUHAN?', NULL),
(102024, 3649, 10, 18, 'Lihat, darahnya itu tidak dibawa masuk ke dalam tempat kudus; bukankah seharusnya kamu memakannya di tempat kudus, seperti yang telah kuperintahkan?\"', NULL),
(102025, 3649, 10, 19, 'Lalu berkatalah Harun kepada Musa: \"Memang benar, pada hari ini mereka telah mempersembahkan korban penghapus dosa dan korban bakaran mereka ke hadapan TUHAN, tetapi hal-hal seperti tadilah yang kualami. Jikalau pada hari ini aku memakan juga korban penghapus dosa, mungkinkah hal itu disetujui oleh TUHAN?\"', NULL),
(102026, 3649, 10, 20, 'Ketika Musa mendengar itu, ia menyetujuinya.', NULL),
(102027, 3649, 11, 1, 'Lalu TUHAN berfirman kepada Musa dan Harun, kata-Nya kepada mereka:', 'Binatang yang haram dan yang tidak haram'),
(102028, 3649, 11, 2, '\"Katakanlah kepada orang Israel, begini: Inilah binatang-binatang yang boleh kamu makan dari segala binatang berkaki empat yang ada di atas bumi:', NULL),
(102029, 3649, 11, 3, 'setiap binatang yang berkuku belah, yaitu yang kukunya bersela panjang, dan yang memamah biak boleh kamu makan.', NULL),
(102030, 3649, 11, 4, 'Tetapi inilah yang tidak boleh kamu makan dari yang memamah biak atau dari yang berkuku belah: unta, karena memang memamah biak, tetapi tidak berkuku belah; haram itu bagimu.', NULL),
(102031, 3649, 11, 5, 'Juga pelanduk, karena memang memamah biak, tetapi tidak berkuku belah; haram itu bagimu.', NULL),
(102032, 3649, 11, 6, 'Juga kelinci, karena memang memamah biak, tetapi tidak berkuku belah, haram itu bagimu.', NULL),
(102033, 3649, 11, 7, 'Demikian juga babi hutan, karena memang berkuku belah, yaitu kukunya bersela panjang, tetapi tidak memamah biak; haram itu bagimu.', NULL),
(102034, 3649, 11, 8, 'Daging binatang-binatang itu janganlah kamu makan dan bangkainya janganlah kamu sentuh; haram semuanya itu bagimu.', NULL),
(102035, 3649, 11, 9, 'Inilah yang boleh kamu makan dari segala yang hidup di dalam air: segala yang bersirip dan bersisik di dalam air, di dalam lautan, dan di dalam sungai, itulah semuanya yang boleh kamu makan.', NULL),
(102036, 3649, 11, 10, 'Tetapi segala yang tidak bersirip atau bersisik di dalam lautan dan di dalam sungai, dari segala yang berkeriapan di dalam air dan dari segala makhluk hidup yang ada di dalam air, semuanya itu kejijikan bagimu.', NULL),
(102037, 3649, 11, 11, 'Sesungguhnya haruslah semuanya itu kejijikan bagimu; dagingnya janganlah kamu makan, dan bangkainya haruslah kamu jijikkan.', NULL),
(102038, 3649, 11, 12, 'Segala yang tidak bersirip dan tidak bersisik di dalam air, adalah kejijikan bagimu.', NULL),
(102039, 3649, 11, 13, 'Inilah yang harus kamu jijikkan dari burung-burung, janganlah dimakan, karena semuanya itu adalah kejijikan: burung rajawali, ering janggut dan elang laut;', NULL),
(102040, 3649, 11, 14, 'elang merah dan elang hitam menurut jenisnya;', NULL),
(102041, 3649, 11, 15, 'setiap burung gagak menurut jenisnya;', NULL),
(102042, 3649, 11, 16, 'burung unta, burung hantu, camar dan elang sikap menurut jenisnya;', NULL),
(102043, 3649, 11, 17, 'burung pungguk, burung dendang air dan burung hantu besar;', NULL),
(102044, 3649, 11, 18, 'burung hantu putih, burung undan, burung ering;', NULL),
(102045, 3649, 11, 19, 'burung ranggung, bangau menurut jenisnya, meragai dan kelelawar.', NULL),
(102046, 3649, 11, 20, 'Segala binatang yang merayap dan bersayap dan berjalan dengan keempat kakinya adalah kejijikan bagimu.', NULL),
(102047, 3649, 11, 21, 'Tetapi inilah yang boleh kamu makan dari segala binatang yang merayap dan bersayap dan yang berjalan dengan keempat kakinya, yaitu yang mempunyai paha di sebelah atas kakinya untuk melompat di atas tanah.', NULL),
(102048, 3649, 11, 22, 'Inilah yang boleh kamu makan dari antaranya: belalang-belalang menurut jenisnya, yaitu belalang-belalang gambar menurut jenisnya, belalang-belalang kunyit menurut jenisnya, dan belalang-belalang padi menurut jenisnya.', NULL),
(102049, 3649, 11, 23, 'Selainnya segala binatang yang merayap dan bersayap dan yang berkaki empat adalah kejijikan bagimu.', NULL),
(102050, 3649, 11, 24, 'Semua yang berikut akan menajiskan kamu--setiap orang yang kena kepada bangkainya, menjadi najis sampai matahari terbenam,', NULL),
(102051, 3649, 11, 25, 'dan setiap orang yang ada membawa dari bangkainya haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam--,', NULL),
(102052, 3649, 11, 26, 'yakni segala binatang yang berkuku belah, tetapi tidak bersela panjang, dan yang tidak memamah biak; haram semuanya itu bagimu dan setiap orang yang kena kepadanya, menjadi najis.', NULL),
(102053, 3649, 11, 27, 'Demikian juga segala yang berjalan dengan telapak kakinya di antara segala binatang yang berjalan dengan keempat kakinya, semuanya itu haram bagimu; setiap orang yang kena kepada bangkainya, menjadi najis sampai matahari terbenam.', NULL),
(102054, 3649, 11, 28, 'Dan siapa yang membawa bangkainya, haruslah mencuci pakaiannya dan ia menjadi najis sampai matahari terbenam. Haram semuanya itu bagimu.', NULL),
(102055, 3649, 11, 29, 'Inilah yang haram bagimu di antara segala binatang yang merayap dan berkeriapan di atas bumi: tikus buta, tikus, dan katak menurut jenisnya', NULL),
(102056, 3649, 11, 30, 'dan landak, biawak, dan bengkarung, siput dan bunglon.', NULL),
(102057, 3649, 11, 31, 'Itulah semuanya yang haram bagimu di antara segala binatang yang mengeriap. Setiap orang yang kena kepada binatang-binatang itu sesudah binatang-binatang itu mati, menjadi najis sampai matahari terbenam.', NULL),
(102058, 3649, 11, 32, 'Dan segala sesuatu menjadi najis, kalau seekor yang mati dari binatang-binatang itu jatuh ke atasnya: perkakas kayu apa saja atau pakaian atau kulit atau karung, setiap barang yang dipergunakan untuk sesuatu apapun, haruslah dimasukkan ke dalam air dan menjadi najis sampai matahari terbenam, kemudian menjadi tahir pula.', NULL),
(102059, 3649, 11, 33, 'Kalau seekor dari binatang-binatang itu jatuh ke dalam sesuatu belanga tanah, maka segala yang ada di dalamnya menjadi najis dan belanga itu harus kamu pecahkan.', NULL),
(102060, 3649, 11, 34, 'Dalam hal itu segala makanan yang boleh dimakan, kalau kena air dari belanga itu, menjadi najis, dan segala minuman yang boleh diminum dalam belanga seperti itu, menjadi najis.', NULL),
(102061, 3649, 11, 35, 'Kalau bangkai seekor dari binatang-binatang itu jatuh ke atas sesuatu benda, itu menjadi najis; pembakaran roti dan anglo haruslah diremukkan, karena semuanya itu najis dan haruslah najis juga bagimu;', NULL),
(102062, 3649, 11, 36, 'tetapi mata air atau sumur yang memuat air, tetap tahir, sedangkan siapa yang kena kepada bangkai binatang-binatang itu menjadi najis.', NULL),
(102063, 3649, 11, 37, 'Apabila bangkai seekor dari binatang-binatang itu jatuh ke atas benih apapun yang akan ditaburkan, maka benih itu tetap tahir.', NULL),
(102064, 3649, 11, 38, 'Tetapi apabila benih itu telah dibubuhi air, lalu ke atasnya jatuh bangkai seekor dari binatang-binatang itu, maka najislah benih itu bagimu.', NULL),
(102065, 3649, 11, 39, 'Apabila mati salah seekor binatang yang menjadi makanan bagimu, maka siapa yang kena kepada bangkainya menjadi najis sampai matahari terbenam.', NULL),
(102066, 3649, 11, 40, 'Dan siapa yang makan dari bangkainya itu, haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam; demikian juga siapa yang membawa bangkainya haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam.', NULL),
(102067, 3649, 11, 41, 'Segala binatang yang merayap dan berkeriapan di atas bumi, adalah kejijikan, janganlah dimakan.', NULL),
(102068, 3649, 11, 42, 'Segala yang merayap dengan perutnya dan segala yang berjalan dengan keempat kakinya, atau segala yang berkaki banyak, semua yang termasuk binatang yang merayap dan berkeriapan di atas bumi, janganlah kamu makan, karena semuanya itu adalah kejijikan.', NULL),
(102069, 3649, 11, 43, 'Janganlah kamu membuat dirimu jijik oleh setiap binatang yang merayap dan berkeriapan dan janganlah kamu menajiskan dirimu dengan semuanya itu, sehingga kamu menjadi najis karenanya.', NULL),
(102070, 3649, 11, 44, 'Sebab Akulah TUHAN, Allahmu, maka haruslah kamu menguduskan dirimu dan haruslah kamu kudus, sebab Aku ini kudus, dan janganlah kamu menajiskan dirimu dengan setiap binatang yang mengeriap dan merayap di atas bumi.', NULL),
(102071, 3649, 11, 45, 'Sebab Akulah TUHAN yang telah menuntun kamu keluar dari tanah Mesir, supaya menjadi Allahmu; jadilah kudus, sebab Aku ini kudus.', NULL),
(102072, 3649, 11, 46, 'Itulah hukum tentang binatang berkaki empat, burung-burung dan segala makhluk hidup yang bergerak di dalam air dan segala makhluk yang mengeriap di atas bumi,', NULL),
(102073, 3649, 11, 47, 'yakni untuk membedakan antara yang najis dengan yang tahir, antara binatang yang boleh dimakan dengan binatang yang tidak boleh dimakan.\"', NULL),
(102074, 3649, 12, 1, 'TUHAN berfirman kepada Musa, demikian:', 'Pentahiran sesudah melahirkan anak'),
(102075, 3649, 12, 2, '\"Katakanlah kepada orang Israel: Apabila seorang perempuan bersalin dan melahirkan anak laki-laki, maka najislah ia selama tujuh hari. Sama seperti pada hari-hari ia bercemar kain ia najis.', NULL),
(102076, 3649, 12, 3, 'Dan pada hari yang kedelapan haruslah dikerat daging kulit khatan anak itu.', NULL),
(102077, 3649, 12, 4, 'Selanjutnya tiga puluh tiga hari lamanya perempuan itu harus tinggal menantikan pentahiran dari darah nifas, tidak boleh ia kena kepada sesuatu apapun yang kudus dan tidak boleh ia masuk ke tempat kudus, sampai sudah genap hari-hari pentahirannya.', NULL),
(102078, 3649, 12, 5, 'Tetapi jikalau ia melahirkan anak perempuan, maka najislah ia selama dua minggu, sama seperti pada waktu ia bercemar kain; selanjutnya enam puluh enam hari lamanya ia harus tinggal menantikan pentahiran dari darah nifas.', NULL),
(102079, 3649, 12, 6, 'Bila sudah genap hari-hari pentahirannya, maka untuk anak laki-laki atau anak perempuan haruslah dibawanya seekor domba berumur setahun sebagai korban bakaran dan seekor anak burung merpati atau burung tekukur sebagai korban penghapus dosa ke pintu Kemah Pertemuan, dengan menyerahkannya kepada imam.', NULL),
(102080, 3649, 12, 7, 'Imam itu harus mempersembahkannya ke hadapan TUHAN dan mengadakan pendamaian bagi perempuan itu. Demikianlah perempuan itu ditahirkan dari leleran darahnya. Itulah hukum tentang perempuan yang melahirkan anak laki-laki atau anak perempuan.', NULL),
(102081, 3649, 12, 8, 'Tetapi jikalau ia tidak mampu untuk menyediakan seekor kambing atau domba, maka haruslah ia mengambil dua ekor burung tekukur atau dua ekor anak burung merpati, yang seekor sebagai korban bakaran dan yang seekor lagi sebagai korban penghapus dosa, dan imam itu harus mengadakan pendamaian bagi perempuan itu, maka tahirlah ia.\"', NULL),
(102082, 3649, 13, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'Penyakit kusta'),
(102083, 3649, 13, 2, '\"Apabila pada kulit badan seseorang ada bengkak atau bintil-bintil atau panau, yang mungkin menjadi penyakit kusta pada kulitnya, ia harus dibawa kepada imam Harun, atau kepada salah seorang dari antara anak-anaknya, imam-imam itu.', NULL),
(102084, 3649, 13, 3, 'Imam haruslah memeriksa penyakit pada kulit itu, dan kalau bulu di tempat penyakit itu sudah berubah menjadi putih, dan penyakit itu kelihatan lebih dalam dari kulit, maka itu penyakit kusta; kalau imam melihat hal itu, haruslah ia menyatakan orang itu najis.', NULL),
(102085, 3649, 13, 4, 'Tetapi jikalau yang ada pada kulitnya itu hanya panau putih dan tidak kelihatan lebih dalam dari kulit, dan bulunya tidak berubah menjadi putih, imam harus mengurung orang itu tujuh hari lamanya.', NULL),
(102086, 3649, 13, 5, 'Pada hari yang ketujuh haruslah imam memeriksa dia; bila menurut penglihatannya penyakit itu masih tetap dan tidak meluas pada kulit, imam harus mengurung dia tujuh hari lagi untuk kedua kalinya.', NULL),
(102087, 3649, 13, 6, 'Kemudian pada hari yang ketujuh haruslah imam memeriksa dia untuk kedua kalinya; bila penyakit itu menjadi pudar dan tidak meluas pada kulit, imam harus menyatakan dia tahir; itu hanya bintil-bintil. Orang itu harus mencuci pakaiannya dan ia menjadi tahir.', NULL),
(102088, 3649, 13, 7, 'Tetapi jikalau bintil-bintil itu memang meluas pada kulit, sesudah ia minta diperiksa oleh imam untuk dinyatakan tahir, haruslah ia minta diperiksa untuk kedua kalinya.', NULL),
(102089, 3649, 13, 8, 'Kalau menurut pemeriksaan imam bintil-bintil itu meluas pada kulit, imam harus menyatakan dia najis; itu penyakit kusta.', NULL),
(102090, 3649, 13, 9, 'Apabila seseorang kena kusta, ia harus dibawa kepada imam.', NULL),
(102091, 3649, 13, 10, 'Kalau menurut pemeriksaan imam pada kulitnya ada bengkak yang putih, yang mengubah bulunya menjadi putih, dan ada daging liar timbul pada bengkak itu,', NULL),
(102092, 3649, 13, 11, 'maka kusta idapanlah yang ada pada kulitnya. Imam harus menyatakan dia najis dengan tidak usah mengurung dia, karena orang itu memang sudah najis.', NULL),
(102093, 3649, 13, 12, 'Jikalau kusta itu timbul di mana-mana pada kulit, sehingga menutupi seluruh kulit orang sakit itu, dari kepala sampai kakinya, seberapa dapat dilihat oleh imam,', NULL),
(102094, 3649, 13, 13, 'dan kalau menurut pemeriksaannya kusta itu menutupi seluruh tubuh orang itu, maka ia harus dinyatakan tahir oleh imam; ia seluruhnya telah berubah menjadi putih, jadi ia tahir.', NULL),
(102095, 3649, 13, 14, 'Tetapi pada waktu ada tampak daging liar padanya, najislah ia.', NULL),
(102096, 3649, 13, 15, 'Kalau daging liar itu dilihat oleh imam, ia harus menyatakan orang itu najis, karena daging liar itu najis, dan itu penyakit kusta.', NULL),
(102097, 3649, 13, 16, 'Atau apabila daging liar itu susut dan berubah menjadi putih, haruslah orang itu datang kepada imam.', NULL),
(102098, 3649, 13, 17, 'Kalau menurut pemeriksaannya penyakit itu telah berubah menjadi putih, haruslah imam menyatakan orang itu tahir; memang ia tahir.', NULL),
(102099, 3649, 13, 18, 'Apabila pada kulit seseorang ada barah yang telah sembuh,', NULL),
(102100, 3649, 13, 19, 'tetapi di tempat barah itu timbul bengkak yang putih atau panau yang putih kemerah-merahan, haruslah orang itu minta diperiksa oleh imam.', NULL),
(102101, 3649, 13, 20, 'Kalau menurut pemeriksaannya panau itu kelihatan lebih dalam dari pada kulit dan bulunya telah berubah menjadi putih, maka imam harus menyatakan orang itu najis, karena penyakit kustalah yang timbul di dalam barah itu.', NULL),
(102102, 3649, 13, 21, 'Tetapi jikalau panau itu diperiksa oleh imam dan ternyata tidak ada bulu yang putih padanya, dan tidak lebih dalam dari pada kulit, malahan pudar, imam harus mengurung orang itu tujuh hari lamanya.', NULL),
(102103, 3649, 13, 22, 'Dan jikalau panau itu memang meluas pada kulit, imam harus menyatakan dia najis; itu penyakit kusta.', NULL),
(102104, 3649, 13, 23, 'Tetapi jikalau panau itu masih tetap dan tidak meluas, maka itu bekas barah, dan imam harus menyatakan orang itu tahir.', NULL),
(102105, 3649, 13, 24, 'Atau apabila pada kulit seseorang ada lecur karena api dan daging liar yang timbul pada lecur itu menjadi panau yang putih kemerah-merahan atau putih,', NULL),
(102106, 3649, 13, 25, 'maka imam harus memeriksa panau itu; bila ternyata bulu pada panau itu berubah menjadi putih dan panau itu kelihatan lebih dalam dari kulit, maka yang timbul di dalam lecur itu adalah penyakit kusta, dan imam harus menyatakan orang itu najis; itu penyakit kusta.', NULL),
(102107, 3649, 13, 26, 'Tetapi jikalau menurut pemeriksaannya tidak ada pada panau itu bulu yang putih dan panau itu tidak lebih dalam dari pada kulit, malahan pudar, imam harus mengurung orang itu tujuh hari lamanya.', NULL),
(102108, 3649, 13, 27, 'Pada hari yang ketujuh imam harus memeriksa lagi dia; jikalau panau itu memang meluas pada kulit, maka haruslah imam menyatakan dia najis, itu penyakit kusta.', NULL),
(102109, 3649, 13, 28, 'Tetapi jikalau panau itu masih tetap dan tidak meluas pada kulit, malahan pudar, maka itu bengkak lecur dan imam harus menyatakan dia tahir, sebab itu bekas lecur.', NULL),
(102110, 3649, 13, 29, 'Apabila seorang laki-laki atau perempuan mendapat penyakit pada kepala atau pada janggut,', NULL),
(102111, 3649, 13, 30, 'imam harus memeriksa penyakit itu; bila itu kelihatan lebih dalam dari kulit, dan ada padanya rambut halus yang kuning, maka imam harus menyatakan orang itu najis, karena itu kudis kepala, yakni kusta kepala atau kusta janggut.', NULL),
(102112, 3649, 13, 31, 'Dan apabila menurut pemeriksaannya penyakit kudis itu tidak kelihatan lebih dalam dari kulit dan tidak ada padanya rambut yang hitam, maka imam harus mengurung orang yang kena penyakit kudis itu tujuh hari lamanya.', NULL),
(102113, 3649, 13, 32, 'Pada hari yang ketujuh imam harus memeriksa penyakit itu; bila ternyata kudis itu tidak meluas dan tidak ada rambut yang kuning padanya, dan kudis itu tidak kelihatan lebih dalam dari kulit,', NULL),
(102114, 3649, 13, 33, 'maka orang itu harus bercukur, hanya tempat kudis itu tidak boleh dicukurnya. Lalu imam harus mengurung orang yang kena kudis itu untuk kedua kalinya tujuh hari lagi.', NULL),
(102115, 3649, 13, 34, 'Kemudian pada hari yang ketujuh imam harus memeriksa lagi kudis itu; bila ternyata, kudis itu tidak meluas pada kulit, dan tidak kelihatan lebih dalam dari kulit, maka imam harus menyatakan orang itu tahir, dan ia harus mencuci pakaiannya dan ia menjadi tahir.', NULL),
(102116, 3649, 13, 35, 'Tetapi jikalau kudis itu memang meluas pada kulit, sesudah ia dinyatakan tahir,', NULL),
(102117, 3649, 13, 36, 'dan menurut pemeriksaan imam kudis itu meluas pada kulit, maka imam tidak usah lagi mencari rambut yang kuning, memang orang itu najis.', NULL),
(102118, 3649, 13, 37, 'Tetapi jikalau menurut penglihatan imam kudis itu masih tetap, dan ada rambut hitam tumbuh pada kudis itu, maka kudis itu sudah sembuh, dan orang itu tahir, dan imam harus menyatakan dia tahir.', NULL),
(102119, 3649, 13, 38, 'Apabila pada kulit seorang laki-laki atau perempuan ada panau-panau, yakni panau-panau yang putih,', NULL),
(102120, 3649, 13, 39, 'imam harus melakukan pemeriksaan; bila ternyata pada kulitnya ada panau-panau pudar dan putih, maka hanya kuraplah yang timbul pada kulitnya dan orang itu tahir.', NULL),
(102121, 3649, 13, 40, 'Apabila rambut kepala seorang laki-laki meluruh, dan ia hanya menjadi botak, ia tahir.', NULL),
(102122, 3649, 13, 41, 'Jikalau rambutnya meluruh pada sebelah mukanya, dan ia menjadi botak sebelah depan, ia tahir.', NULL),
(102123, 3649, 13, 42, 'Tetapi apabila pada kepala yang botak itu, sebelah atas atau sebelah depan, ada penyakit yang putih kemerah-merahan, maka penyakit kustalah yang timbul pada bagian kepala yang botak itu.', NULL),
(102124, 3649, 13, 43, 'Lalu imam harus memeriksa dia; bila ternyata bahwa bengkak pada bagian kepala yang botak itu putih kemerah-merahan, dan kelihatannya seperti kusta pada kulit,', NULL),
(102125, 3649, 13, 44, 'maka orang itu sakit kusta, dan ia najis, dan imam harus menyatakan dia najis, karena penyakit yang di kepalanya itu.', NULL),
(102126, 3649, 13, 45, 'Orang yang sakit kusta harus berpakaian yang cabik-cabik, rambutnya terurai dan lagi ia harus menutupi mukanya sambil berseru-seru: Najis! Najis!', NULL),
(102127, 3649, 13, 46, 'Selama ia kena penyakit itu, ia tetap najis; memang ia najis; ia harus tinggal terasing, di luar perkemahan itulah tempat kediamannya.', NULL),
(102128, 3649, 13, 47, 'Apabila pada pakaian ada tanda kusta, pada pakaian bulu domba atau pakaian lenan,', NULL),
(102129, 3649, 13, 48, 'entah pada benang lungsin atau benang pakannya, entah pada kulit atau sesuatu barang kulit,', NULL),
(102130, 3649, 13, 49, '--kalau tanda pada barang-barang itu sudah kemerah-merahan warnanya, maka itu kusta--hal itu harus diperiksakan kepada imam.', NULL),
(102131, 3649, 13, 50, 'Kalau tanda itu telah diperiksa oleh imam, ia harus mengasingkan yang mempunyai tanda itu tujuh hari lamanya.', NULL),
(102132, 3649, 13, 51, 'Pada hari yang ketujuh ia harus memeriksa tanda itu lagi; apabila tanda itu meluas pada pakaian atau benang lungsin atau benang pakan atau pada kulit, entah untuk barang apapun kulit itu dipakai, maka itu adalah kusta yang jahat sekali, dan barang itu najis.', NULL),
(102133, 3649, 13, 52, 'Ia harus membakar barang-barang yang mempunyai tanda itu, karena itu kusta yang jahat sekali; barang-barang itu harus dibakar habis.', NULL),
(102134, 3649, 13, 53, 'Tetapi jikalau menurut pemeriksaan imam tanda itu tidak meluas pada barang-barang itu,', NULL),
(102135, 3649, 13, 54, 'maka imam harus memerintahkan orang mencuci barang yang mempunyai tanda itu, lalu ia harus mengasingkannya tujuh hari lagi untuk kedua kalinya.', NULL),
(102136, 3649, 13, 55, 'Kemudian sesudah barang itu dicuci, imam harus memeriksa tanda itu lagi; bila ternyata rupa tanda itu tidak berubah, biarpun itu tidak meluas, maka barang itu najis, dan engkau harus membakarnya habis, karena tanda itu semakin mendalam pada sebelah belakang atau sebelah muka.', NULL),
(102137, 3649, 13, 56, 'Dan jikalau menurut pemeriksaan imam tanda itu menjadi pudar sesudah dicuci, maka ia harus mengoyakkannya dari barang-barang itu.', NULL),
(102138, 3649, 13, 57, 'Tetapi jikalau tanda itu tampak pula pada barang-barang itu, maka itu kusta yang sedang timbul; barang yang mempunyai tanda itu, haruslah kaubakar habis.', NULL),
(102139, 3649, 13, 58, 'Tetapi barang-barang yang telah kaucuci, sehingga tanda itu lenyap dari padanya, haruslah dicuci untuk kedua kalinya, barulah menjadi tahir.', NULL),
(102140, 3649, 13, 59, 'Itulah hukum tentang kusta yang ada pada pakaian bulu domba atau lenan atau pada benang lungsin atau pada benang pakan atau pada setiap barang kulit, untuk menyatakan tahir atau najisnya.\"', NULL),
(102141, 3649, 14, 1, 'TUHAN berfirman kepada Musa:', NULL),
(102142, 3649, 14, 2, '\"Inilah yang harus menjadi hukum tentang orang yang sakit kusta pada hari pentahirannya: ia harus dibawa kepada imam,', NULL),
(102143, 3649, 14, 3, 'dan imam harus pergi ke luar perkemahan; kalau menurut pemeriksaan imam penyakit kusta itu telah sembuh dari padanya,', NULL),
(102144, 3649, 14, 4, 'maka imam harus memerintahkan, supaya bagi orang yang akan ditahirkan itu diambil dua ekor burung yang hidup dan yang tidak haram, juga kayu aras, kain kirmizi dan hisop.', NULL),
(102145, 3649, 14, 5, 'Imam harus memerintahkan supaya burung yang seekor disembelih di atas belanga tanah berisi air mengalir.', NULL),
(102146, 3649, 14, 6, 'Tetapi burung yang masih hidup haruslah diambilnya bersama-sama dengan kayu aras, kain kirmizi dan hisop, lalu bersama-sama dengan burung itu semuanya harus dicelupkannya ke dalam darah burung yang sudah disembelih di atas air mengalir itu.', NULL),
(102147, 3649, 14, 7, 'Kemudian ia harus memercik tujuh kali kepada orang yang akan ditahirkan dari kusta itu dan dengan demikian mentahirkan dia, lalu burung yang hidup itu haruslah dilepaskannya ke padang.', NULL),
(102148, 3649, 14, 8, 'Orang yang akan ditahirkan itu haruslah mencuci pakaiannya, mencukur seluruh rambutnya dan membasuh tubuhnya dengan air, maka ia menjadi tahir. Sesudah itu ia boleh masuk ke dalam perkemahan, tetapi harus tinggal di luar kemahnya sendiri tujuh hari lamanya.', NULL),
(102149, 3649, 14, 9, 'Maka pada hari yang ketujuh ia harus mencukur seluruh rambutnya: rambut kepala, janggut, alis, bahkan segala bulunya harus dicukur, pakaiannya dicuci, dan tubuhnya dibasuh dengan air; maka ia menjadi tahir.', NULL),
(102150, 3649, 14, 10, 'Pada hari yang kedelapan ia harus mengambil dua ekor domba jantan yang tidak bercela dan seekor domba betina berumur setahun yang tidak bercela dan tiga persepuluh efa tepung yang terbaik diolah dengan minyak sebagai korban sajian, serta satu log minyak.', NULL),
(102151, 3649, 14, 11, 'Imam yang melakukan pentahiran itu harus menempatkan orang yang akan ditahirkan bersama-sama dengan persembahannya di hadapan TUHAN di depan pintu Kemah Pertemuan.', NULL),
(102152, 3649, 14, 12, 'Dan ia harus mengambil domba jantan yang seekor dan mempersembahkannya sebagai tebusan salah bersama-sama dengan minyak yang satu log itu, dan ia harus mempersembahkannya sebagai persembahan unjukan di hadapan TUHAN.', NULL),
(102153, 3649, 14, 13, 'Domba jantan itu harus disembelihnya di tempat orang menyembelih korban penghapus dosa dan korban bakaran, di tempat kudus, karena korban penebus salah, begitu juga korban penghapus dosa, adalah bagian imam; itulah bagian maha kudus.', NULL),
(102154, 3649, 14, 14, 'Imam harus mengambil sedikit dari darah tebusan salah itu dan harus membubuhnya pada cuping telinga kanan dari orang yang akan ditahirkan dan pada ibu jari tangan kanan dan pada ibu jari kaki kanannya.', NULL),
(102155, 3649, 14, 15, 'Imam harus mengambil sedikit dari minyak yang satu log itu dan menuangnya ke telapak tangan kiri imam sendiri;', NULL),
(102156, 3649, 14, 16, 'ia harus mencelupkan jari kanannya ke dalam minyak yang di telapak tangan kirinya itu dan sedikit dari minyak itu haruslah dipercikkannya dengan jarinya tujuh kali di hadapan TUHAN.', NULL),
(102157, 3649, 14, 17, 'Dari minyak selebihnya imam harus membubuh sedikit pada cuping telinga kanan orang itu, pada ibu jari tangan kanannya dan pada ibu jari kaki kanannya, di tempat mana darah tebusan salah dibubuhkan.', NULL),
(102158, 3649, 14, 18, 'Dan apa yang tinggal dari minyak itu haruslah dibubuhnya pada kepala orang yang akan ditahirkan. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN.', NULL),
(102159, 3649, 14, 19, 'Imam harus mempersembahkan korban penghapus dosa dan dengan demikian mengadakan pendamaian bagi orang yang akan ditahirkan dari kenajisannya, dan sesudah itu ia harus menyembelih korban bakaran.', NULL),
(102160, 3649, 14, 20, 'Kemudian imam harus mempersembahkan korban bakaran dan korban sajian di atas mezbah. Dengan demikian imam mengadakan pendamaian bagi orang itu, maka ia menjadi tahir.', NULL),
(102161, 3649, 14, 21, 'Tetapi jikalau orang itu miskin dan tidak mampu, ia harus mengambil domba jantan seekor saja sebagai tebusan salah untuk persembahan unjukan, supaya diadakan pendamaian bagi orang itu, juga sepersepuluh efa tepung yang terbaik diolah dengan minyak untuk korban sajian, dan satu log minyak.', NULL),
(102162, 3649, 14, 22, 'Dan lagi dua ekor burung tekukur atau dua ekor burung merpati sekadar kemampuannya, yang seekor harus menjadi korban penghapus dosa dan yang seekor lagi menjadi korban bakaran.', NULL),
(102163, 3649, 14, 23, 'Pada hari yang kedelapan ia harus membawa semuanya untuk pentahirannya kepada imam, ke depan pintu Kemah Pertemuan di hadapan TUHAN.', NULL),
(102164, 3649, 14, 24, 'Kemudian imam harus mengambil domba tebusan salah dan minyak yang satu log itu, lalu imam harus mempersembahkan semuanya sebagai persembahan unjukan di hadapan TUHAN.', NULL),
(102165, 3649, 14, 25, 'Ia harus menyembelih domba tebusan salah dan imam harus mengambil sedikit dari darah tebusan salah itu dan membubuhnya pada cuping telinga kanan orang itu dan pada ibu jari tangan kanan dan ibu jari kaki kanannya.', NULL),
(102166, 3649, 14, 26, 'Dan imam harus menuang sedikit dari minyak itu ke telapak tangan kirinya sendiri,', NULL),
(102167, 3649, 14, 27, 'lalu sedikit dari minyak itu haruslah dipercikkan oleh imam dengan jari kanannya tujuh kali di hadapan TUHAN.', NULL),
(102168, 3649, 14, 28, 'Kemudian imam harus membubuh sedikit dari minyak itu pada cuping telinga kanan dari orang yang akan ditahirkan, pada ibu jari tangan kanannya dan pada ibu jari kaki kanannya, di tempat mana dibubuhi darah tebusan salah itu.', NULL),
(102169, 3649, 14, 29, 'Dan minyak selebihnya haruslah dibubuhnya pada kepala orang yang akan ditahirkan, supaya diadakan pendamaian bagi orang itu di hadapan TUHAN.', NULL),
(102170, 3649, 14, 30, 'Lalu ia harus mempersembahkan seekor dari kedua burung tekukur atau anak burung merpati, yang dibawa orang itu sekadar kemampuannya,', NULL),
(102171, 3649, 14, 31, 'yang seekor sebagai korban penghapus dosa, dan yang seekor lagi sebagai korban bakaran, di samping korban sajian. Dengan demikian imam mengadakan pendamaian bagi orang yang akan ditahirkan di hadapan TUHAN.', NULL),
(102172, 3649, 14, 32, 'Itulah hukum tentang pentahiran seorang yang kena kusta yang tidak mampu.\"', NULL),
(102173, 3649, 14, 33, 'TUHAN berfirman kepada Musa dan Harun:', NULL),
(102174, 3649, 14, 34, '\"Apabila kamu masuk ke tanah Kanaan yang akan Kuberikan kepadamu menjadi milikmu dan Aku mendatangkan tanda kusta di sebuah rumah di negeri milikmu itu,', NULL),
(102175, 3649, 14, 35, 'maka pemilik rumah itu harus datang memberitahukannya kepada imam: Ada kelihatan seperti tanda kusta di rumahku.', NULL),
(102176, 3649, 14, 36, 'Maka imam harus memerintahkan supaya rumah itu dikosongkan, sebelum ia datang memeriksa tanda kusta itu, supaya jangan menjadi najis segala yang ada di dalam rumah itu, dan sesudah itu barulah imam datang untuk memeriksanya.', NULL),
(102177, 3649, 14, 37, 'Kalau menurut pemeriksaannya tanda pada dinding rumah itu merupakan lekuk-lekuk yang kehijau-hijauan atau kemerah-merahan warnanya, yang kelihatan lebih dalam dari permukaan dinding itu,', NULL),
(102178, 3649, 14, 38, 'imam harus keluar dari rumah itu, lalu berdiri di depan pintu rumah, dan menutup rumah itu tujuh hari lamanya.', NULL),
(102179, 3649, 14, 39, 'Pada hari yang ketujuh imam harus datang kembali; kalau menurut pemeriksaannya tanda kusta itu meluas pada dinding rumah,', NULL),
(102180, 3649, 14, 40, 'maka imam harus memerintahkan supaya orang mengungkit batu-batu yang kena tanda itu dan membuangnya ke luar kota ke suatu tempat yang najis.', NULL),
(102181, 3649, 14, 41, 'Dan ia harus mengikis rumah itu sebelah dalam berkeliling, dan kikisan lepa itu haruslah ditumpahkan ke luar kota ke suatu tempat yang najis.', NULL),
(102182, 3649, 14, 42, 'Dan orang harus mengambil batu-batu lain, lalu memasangnya sebagai pengganti batu-batu tadi, dan harus mengambil lepa lain dan melepa rumah itu.', NULL),
(102183, 3649, 14, 43, 'Tetapi jikalau tanda itu timbul lagi di dalam rumah itu, sesudah batu-batunya diungkit dan sesudah rumah itu dikikis, bahkan sesudah dilepa lagi,', NULL),
(102184, 3649, 14, 44, 'dan kalau imam datang dan menurut pemeriksaannya tanda itu meluas di dalam rumah, maka kusta ganaslah yang di dalam rumah itu, dan rumah itu najis.', NULL),
(102185, 3649, 14, 45, 'Rumah itu haruslah dirombak, yakni batunya, kayunya dan segala lepa rumah itu, lalu dibawa semuanya ke luar kota ke suatu tempat yang najis.', NULL),
(102186, 3649, 14, 46, 'Dan orang yang masuk ke dalam rumah itu selama rumah itu ditutup, menjadi najis sampai matahari terbenam.', NULL),
(102187, 3649, 14, 47, 'Dan orang yang tidur di dalam rumah itu haruslah mencuci pakaiannya; demikian juga orang yang makan di dalam rumah itu haruslah mencuci pakaiannya.', NULL),
(102188, 3649, 14, 48, 'Tetapi jikalau imam datang dan menurut pemeriksaannya tanda itu tidak meluas di dalam rumah itu, sesudah dilepa, maka imam harus menyatakan rumah itu tahir, karena tanda itu telah hilang.', NULL),
(102189, 3649, 14, 49, 'Kemudian, untuk menyucikan rumah itu, haruslah ia mengambil dua ekor burung, kayu aras, kain kirmizi dan hisop.', NULL),
(102190, 3649, 14, 50, 'Burung yang seekor haruslah disembelihnya di atas belanga tanah berisi air mengalir.', NULL),
(102191, 3649, 14, 51, 'Lalu ia harus mengambil kayu aras dan hisop, kain kirmizi dan burung yang masih hidup itu, dan mencelupkan semuanya ke dalam darah burung yang sudah disembelih dan ke dalam air mengalir itu, kemudian ia harus memercik kepada rumah itu tujuh kali.', NULL),
(102192, 3649, 14, 52, 'Dengan demikian ia harus menyucikan rumah itu dengan darah burung, air mengalir, burung yang hidup, kayu aras, hisop, dan kain kirmizi.', NULL),
(102193, 3649, 14, 53, 'Dan burung yang hidup itu harus dilepaskannya ke luar kota ke padang. Dengan demikian ia mengadakan pendamaian bagi rumah itu, maka rumah itu menjadi tahir.', NULL),
(102194, 3649, 14, 54, 'Itulah hukum tentang setiap penyakit kusta, kudis kepala,', NULL),
(102195, 3649, 14, 55, 'tentang kusta pada pakaian dan rumah,', NULL),
(102196, 3649, 14, 56, 'tentang bengkak, bintil-bintil dan panau,', NULL),
(102197, 3649, 14, 57, 'untuk memberi petunjuk dalam hal najis atau dalam hal tahir; itulah hukum tentang kusta.\"', NULL),
(105360, 3649, 15, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'Ketidaktahiran pada laki-laki dan perempuan'),
(105361, 3649, 15, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila aurat seorang laki-laki mengeluarkan lelehan, maka najislah ia karena lelehannya itu.', NULL),
(105362, 3649, 15, 3, 'Beginilah kenajisannya berhubung dengan lelehannya itu: bila auratnya membiarkan lelehan itu mengalir, atau bila auratnya menahannya, sehingga tidak mengeluarkan lelehan, maka itulah kenajisannya.', NULL),
(105363, 3649, 15, 4, 'Setiap tempat tidur, yang ditiduri orang yang mengeluarkan lelehan itu menjadi najis, dan setiap barang yang didudukinya menjadi najis juga.', NULL),
(105364, 3649, 15, 5, 'Setiap orang yang kena kepada tempat tidurnya haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105365, 3649, 15, 6, 'Siapa yang duduk di atas barang yang telah diduduki oleh orang yang demikian haruslah mencuci pakaiannya, membasuh tubuhnya dengan air, dan ia menjadi najis sampai matahari terbenam.', NULL),
(105366, 3649, 15, 7, 'Siapa yang kena kepada tubuh orang yang demikian, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105367, 3649, 15, 8, 'Apabila orang yang demikian meludahi orang yang tahir, haruslah orang ini mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105368, 3649, 15, 9, 'Dan setiap pelana yang diduduki orang yang demikian menjadi najis.', NULL),
(105369, 3649, 15, 10, 'Setiap orang yang kena kepada sesuatu bekas tempat orang tadi menjadi najis sampai matahari terbenam. Siapa yang mengangkatnya, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105370, 3649, 15, 11, 'Dan setiap orang yang kena pada orang yang demikian, sedang orang ini tidak mencuci tangan dahulu dengan air, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105371, 3649, 15, 12, 'Kalau orang itu kena pada belanga tanah, itu haruslah dipecahkan, dan setiap perkakas kayu haruslah dicuci dengan air.', NULL),
(105372, 3649, 15, 13, 'Apabila orang yang demikian sudah bersih dari lelehannya, ia harus menghitung tujuh hari lagi untuk dapat dinyatakan tahir, lalu mencuci pakaiannya, membasuh tubuhnya dengan air mengalir, maka ia menjadi tahir.', NULL),
(105373, 3649, 15, 14, 'Pada hari yang kedelapan ia harus mengambil dua ekor burung tekukur atau dua ekor anak burung merpati, dan datang ke hadapan TUHAN, ke pintu Kemah Pertemuan, dan menyerahkan burung-burung itu kepada imam.', NULL),
(105374, 3649, 15, 15, 'Lalu imam harus mempersembahkannya, yang seekor sebagai korban penghapus dosa dan yang seekor lagi sebagai korban bakaran. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN karena lelehannya.', NULL),
(105375, 3649, 15, 16, 'Apabila seorang laki-laki tertumpah maninya, ia harus membasuh seluruh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105376, 3649, 15, 17, 'Setiap pakaian dan setiap kulit, yang kena tumpahan mani itu, haruslah dicuci dengan air dan menjadi najis sampai matahari terbenam.', NULL),
(105377, 3649, 15, 18, 'Juga seorang perempuan, kalau seorang laki-laki tidur dengan dia dengan ada tumpahan mani, maka keduanya harus membasuh tubuhnya dengan air dan mereka menjadi najis sampai matahari terbenam.', NULL),
(105378, 3649, 15, 19, 'Apabila seorang perempuan mengeluarkan lelehan, dan lelehannya itu adalah darah dari auratnya, ia harus tujuh hari lamanya dalam cemar kainnya, dan setiap orang yang kena kepadanya, menjadi najis sampai matahari terbenam.', NULL),
(105379, 3649, 15, 20, 'Segala sesuatu yang ditidurinya selama ia cemar kain menjadi najis. Dan segala sesuatu yang didudukinya menjadi najis juga.', NULL),
(105380, 3649, 15, 21, 'Setiap orang yang kena kepada tempat tidur perempuan itu haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105381, 3649, 15, 22, 'Setiap orang yang kena kepada sesuatu barang yang diduduki perempuan itu haruslah mencuci pakaiannya, membasuh diri dengan air dan ia menjadi najis sampai matahari terbenam.', NULL),
(105382, 3649, 15, 23, 'Juga pada waktu ia kena kepada sesuatu yang ada di tempat tidur atau di atas barang yang diduduki perempuan itu, ia menjadi najis sampai matahari terbenam.', NULL),
(105383, 3649, 15, 24, 'Jikalau seorang laki-laki tidur dengan perempuan itu, dan ia kena cemar kain perempuan itu, maka ia menjadi najis selama tujuh hari, dan setiap tempat tidur yang ditidurinya menjadi najis juga.', NULL),
(105384, 3649, 15, 25, 'Apabila seorang perempuan berhari-hari lamanya mengeluarkan lelehan, yakni lelehan darah yang bukan pada waktu cemar kainnya, atau apabila ia mengeluarkan lelehan lebih lama dari waktu cemar kainnya, maka selama lelehannya yang najis itu perempuan itu adalah seperti pada hari-hari cemar kainnya, yakni ia najis.', NULL),
(105385, 3649, 15, 26, 'Setiap tempat tidur yang ditidurinya, selama ia mengeluarkan lelehan, haruslah baginya seperti tempat tidur pada waktu cemar kainnya dan setiap barang yang didudukinya menjadi najis sama seperti kenajisan cemar kainnya.', NULL),
(105386, 3649, 15, 27, 'Setiap orang yang kena kepada barang-barang itu menjadi najis, dan ia harus mencuci pakaiannya, membasuh tubuhnya dengan air, dan ia menjadi najis sampai matahari terbenam.', NULL),
(105387, 3649, 15, 28, 'Tetapi jikalau perempuan itu sudah tahir dari lelehannya, ia harus menghitung tujuh hari lagi, sesudah itu barulah ia menjadi tahir.', NULL),
(105388, 3649, 15, 29, 'Pada hari yang kedelapan ia harus mengambil dua ekor burung tekukur atau dua ekor anak burung merpati dan membawanya kepada imam ke pintu Kemah Pertemuan.', NULL),
(105389, 3649, 15, 30, 'Imam harus mempersembahkan yang seekor sebagai korban penghapus dosa dan yang seekor lagi sebagai korban bakaran. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN, karena lelehannya yang najis itu.', NULL),
(105390, 3649, 15, 31, 'Begitulah kamu harus menghindarkan orang Israel dari kenajisannya, supaya mereka jangan mati di dalam kenajisannya, bila mereka menajiskan Kemah Suci-Ku yang ada di tengah-tengah mereka itu.\"', NULL),
(105391, 3649, 15, 32, 'Itulah hukum tentang seorang laki-laki yang mengeluarkan lelehan atau yang tertumpah maninya yang menyebabkan dia najis,', NULL),
(105392, 3649, 15, 33, 'dan tentang seorang perempuan yang bercemar kain dan tentang seseorang, baik laki-laki maupun perempuan, yang mengeluarkan lelehan, dan tentang laki-laki yang tidur dengan perempuan yang najis.', NULL),
(108588, 3649, 16, 1, 'Sesudah kedua anak Harun mati, yang terjadi pada waktu mereka mendekat ke hadapan TUHAN, berfirmanlah TUHAN kepada Musa.', 'Hari raya Pendamaian'),
(108589, 3649, 16, 2, 'Firman TUHAN kepadanya: \"Katakanlah kepada Harun, kakakmu, supaya ia jangan sembarang waktu masuk ke dalam tempat kudus di belakang tabir, ke depan tutup pendamaian yang di atas tabut supaya jangan ia mati; karena Aku menampakkan diri dalam awan di atas tutup pendamaian.', NULL),
(108590, 3649, 16, 3, 'Beginilah caranya Harun masuk ke dalam tempat kudus itu, yakni dengan membawa seekor lembu jantan muda untuk korban penghapus dosa dan seekor domba jantan untuk korban bakaran.', NULL),
(108591, 3649, 16, 4, 'Ia harus mengenakan kemeja lenan yang kudus dan ia harus menutupi auratnya dengan celana lenan dan ia harus memakai ikat pinggang lenan dan berlilitkan serban lenan; itulah pakaian kudus yang harus dikenakannya, sesudah ia membasuh tubuhnya dengan air.', NULL),
(108592, 3649, 16, 5, 'Dari umat Israel ia harus mengambil dua ekor kambing jantan untuk korban penghapus dosa dan seekor domba jantan untuk korban bakaran.', NULL),
(108593, 3649, 16, 6, 'Kemudian Harun harus mempersembahkan lembu jantan yang akan menjadi korban penghapus dosa baginya sendiri dan dengan demikian mengadakan pendamaian baginya dan bagi keluarganya.', NULL),
(108594, 3649, 16, 7, 'Ia harus mengambil kedua ekor kambing jantan itu dan menempatkannya di hadapan TUHAN di depan pintu Kemah Pertemuan,', NULL),
(108595, 3649, 16, 8, 'dan harus membuang undi atas kedua kambing jantan itu, sebuah undi bagi TUHAN dan sebuah bagi Azazel.', NULL),
(108596, 3649, 16, 9, 'Lalu Harun harus mempersembahkan kambing jantan yang kena undi bagi TUHAN itu dan mengolahnya sebagai korban penghapus dosa.', NULL),
(108597, 3649, 16, 10, 'Tetapi kambing jantan yang kena undi bagi Azazel haruslah ditempatkan hidup-hidup di hadapan TUHAN untuk mengadakan pendamaian, lalu dilepaskan bagi Azazel ke padang gurun.', NULL),
(108598, 3649, 16, 11, 'Harun harus mempersembahkan lembu jantan yang akan menjadi korban penghapus dosa baginya sendiri dan mengadakan pendamaian baginya dan bagi keluarganya; ia harus menyembelih lembu jantan itu.', NULL),
(108599, 3649, 16, 12, 'Dan ia harus mengambil perbaraan berisi penuh bara api dari atas mezbah yang di hadapan TUHAN, serta serangkup penuh ukupan dari wangi-wangian yang digiling sampai halus, lalu membawanya masuk ke belakang tabir.', NULL),
(108600, 3649, 16, 13, 'Kemudian ia harus meletakkan ukupan itu di atas api yang di hadapan TUHAN, sehingga asap ukupan itu menutupi tutup pendamaian yang di atas hukum Allah, supaya ia jangan mati.', NULL),
(108601, 3649, 16, 14, 'Lalu ia harus mengambil sedikit dari darah lembu jantan itu dan memercikkannya dengan jarinya ke atas tutup pendamaian di bagian muka, dan ke depan tutup pendamaian itu ia harus memercikkan sedikit dari darah itu dengan jarinya tujuh kali.', NULL),
(108602, 3649, 16, 15, 'Lalu ia harus menyembelih domba jantan yang akan menjadi korban penghapus dosa bagi bangsa itu dan membawa darahnya masuk ke belakang tabir, kemudian haruslah diperbuatnya dengan darah itu seperti yang diperbuatnya dengan darah lembu jantan, yakni ia harus memercikkannya ke atas tutup pendamaian dan ke depan tutup pendamaian itu.', NULL),
(108603, 3649, 16, 16, 'Dengan demikian ia mengadakan pendamaian bagi tempat kudus itu karena segala kenajisan orang Israel dan karena segala pelanggaran mereka, apapun juga dosa mereka. Demikianlah harus diperbuatnya dengan Kemah Pertemuan yang tetap diam di antara mereka di tengah-tengah segala kenajisan mereka.', NULL),
(108604, 3649, 16, 17, 'Seorangpun tidak boleh hadir di dalam Kemah Pertemuan, bila Harun masuk untuk mengadakan pendamaian di tempat kudus, sampai ia keluar, setelah mengadakan pendamaian baginya sendiri, bagi keluarganya dan bagi seluruh jemaah orang Israel.', NULL),
(108605, 3649, 16, 18, 'Kemudian haruslah ia pergi ke luar ke mezbah yang ada di hadapan TUHAN, dan mengadakan pendamaian bagi mezbah itu. Ia harus mengambil sedikit dari darah lembu jantan dan dari darah domba jantan itu dan membubuhnya pada tanduk-tanduk mezbah sekelilingnya.', NULL),
(108606, 3649, 16, 19, 'Kemudian ia harus memercikkan sedikit dari darah itu ke mezbah itu dengan jarinya tujuh kali dan mentahirkan serta menguduskannya dari segala kenajisan orang Israel.', NULL),
(108607, 3649, 16, 20, 'Setelah selesai mengadakan pendamaian bagi tempat kudus dan Kemah Pertemuan serta mezbah, ia harus mempersembahkan kambing jantan yang masih hidup itu,', NULL),
(108608, 3649, 16, 21, 'dan Harun harus meletakkan kedua tangannya ke atas kepala kambing jantan yang hidup itu dan mengakui di atas kepala kambing itu segala kesalahan orang Israel dan segala pelanggaran mereka, apapun juga dosa mereka; ia harus menanggungkan semuanya itu ke atas kepala kambing jantan itu dan kemudian melepaskannya ke padang gurun dengan perantaraan seseorang yang sudah siap sedia untuk itu.', NULL),
(108609, 3649, 16, 22, 'Demikianlah kambing jantan itu harus mengangkut segala kesalahan Israel ke tanah yang tandus, dan kambing itu harus dilepaskan di padang gurun.', NULL),
(108610, 3649, 16, 23, 'Sesudah itu Harun harus masuk ke dalam Kemah Pertemuan dan menanggalkan pakaian lenan, yang dikenakannya ketika ia masuk ke dalam tempat kudus dan harus meninggalkannya di sana.', NULL),
(108611, 3649, 16, 24, 'Ia harus membasuh tubuhnya dengan air di suatu tempat yang kudus dan mengenakan pakaiannya sendiri, lalu ia harus keluar dan mempersembahkan korban bakarannya sendiri dan korban bakaran bangsa itu; dengan demikian ia mengadakan pendamaian baginya sendiri dan bagi bangsa itu.', NULL),
(108612, 3649, 16, 25, 'Kemudian ia harus membakar lemak korban penghapus dosa di atas mezbah.', NULL),
(108613, 3649, 16, 26, 'Maka orang yang melepaskan kambing jantan bagi Azazel itu harus mencuci pakaiannya, membasuh tubuhnya dengan air dan sesudah itu barulah boleh masuk ke perkemahan.', NULL),
(108614, 3649, 16, 27, 'Lembu jantan dan kambing jantan korban penghapus dosa, yang darahnya telah dibawa masuk untuk mengadakan pendamaian di dalam tempat kudus, harus dibawa keluar dari perkemahan, dan kulitnya, dagingnya dan kotorannya harus dibakar habis.', NULL),
(108615, 3649, 16, 28, 'Siapa yang membakar semuanya itu, harus mencuci pakaiannya, membasuh tubuhnya dengan air dan sesudah itu barulah boleh masuk ke perkemahan.', NULL),
(108616, 3649, 16, 29, 'Inilah yang harus menjadi ketetapan untuk selama-lamanya bagi kamu, yakni pada bulan yang ketujuh, pada tanggal sepuluh bulan itu kamu harus merendahkan diri dengan berpuasa dan janganlah kamu melakukan sesuatu pekerjaan, baik orang Israel asli maupun orang asing yang tinggal di tengah-tengahmu.', NULL),
(108617, 3649, 16, 30, 'Karena pada hari itu harus diadakan pendamaian bagimu untuk mentahirkan kamu. Kamu akan ditahirkan dari segala dosamu di hadapan TUHAN.', NULL),
(108618, 3649, 16, 31, 'Hari itu harus menjadi sabat, hari perhentian penuh, bagimu dan kamu harus merendahkan diri dengan berpuasa. Itulah suatu ketetapan untuk selama-lamanya.', NULL),
(108619, 3649, 16, 32, 'Dan pendamaian harus diadakan oleh imam yang telah diurapi dan telah ditahbiskan untuk memegang jabatan imam menggantikan ayahnya; ia harus mengenakan pakaian lenan, yakni pakaian kudus.', NULL),
(108620, 3649, 16, 33, 'Ia harus mengadakan pendamaian bagi tempat maha kudus, bagi Kemah Pertemuan dan bagi mezbah, juga bagi para imam dan bagi seluruh bangsa itu, yakni jemaah itu.', NULL),
(108621, 3649, 16, 34, 'Itulah yang harus menjadi ketetapan untuk selama-lamanya bagimu, supaya sekali setahun diadakan pendamaian bagi orang Israel karena segala dosa mereka.\" Maka Harun melakukan seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(108622, 3649, 17, 1, 'TUHAN berfirman kepada Musa:', 'Tempat menyembelih dan mempersembahkan korban'),
(108623, 3649, 17, 2, '\"Berbicaralah kepada Harun dan kepada anak-anaknya dan kepada seluruh orang Israel, dan katakan kepada mereka: Inilah firman yang diperintahkan TUHAN:', NULL),
(108624, 3649, 17, 3, 'Setiap orang dari kaum Israel yang menyembelih lembu atau domba atau kambing di dalam perkemahan atau di luarnya,', NULL),
(108625, 3649, 17, 4, 'tetapi tidak membawanya ke pintu Kemah Pertemuan, untuk dipersembahkan sebagai persembahan kepada TUHAN di depan Kemah Suci TUHAN, hal itu harus dihitungkan kepada orang itu sebagai hutang darah, karena ia telah menumpahkan darah, dan orang itu haruslah dilenyapkan dari tengah-tengah bangsanya.', NULL),
(108626, 3649, 17, 5, 'Maksudnya supaya orang Israel membawa korban sembelihan mereka, yang biasa dipersembahkan mereka di padang, kepada TUHAN ke pintu Kemah Pertemuan dengan menyerahkannya kepada imam, untuk dipersembahkan kepada TUHAN sebagai korban keselamatan.', NULL),
(108627, 3649, 17, 6, 'Imam harus menyiramkan darahnya pada mezbah TUHAN di depan pintu Kemah Pertemuan dan membakar lemaknya menjadi bau yang menyenangkan bagi TUHAN.', NULL),
(108628, 3649, 17, 7, 'Janganlah mereka mempersembahkan lagi korban mereka kepada jin-jin, sebab menyembah jin-jin itu adalah zinah. Itulah yang harus menjadi ketetapan untuk selama-lamanya bagi mereka turun-temurun.', NULL),
(108629, 3649, 17, 8, 'Dan haruslah kaukatakan kepada mereka: Setiap orang dari kaum Israel atau dari orang asing yang tinggal di tengah-tengah mereka, yang mempersembahkan korban bakaran atau korban sembelihan,', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(108630, 3649, 17, 9, 'tetapi tidak membawanya ke pintu Kemah Pertemuan supaya dipersembahkan kepada TUHAN, maka orang itu haruslah dilenyapkan dari antara orang-orang sebangsanya.\"', NULL),
(108631, 3649, 17, 10, '\"Setiap orang dari bangsa Israel dan dari orang asing yang tinggal di tengah-tengah mereka, yang makan darah apapun juga Aku sendiri akan menentang dia dan melenyapkan dia dari tengah-tengah bangsanya.', 'Larangan tentang makan darah atau bangkai'),
(108632, 3649, 17, 11, 'Karena nyawa makhluk ada di dalam darahnya dan Aku telah memberikan darah itu kepadamu di atas mezbah untuk mengadakan pendamaian bagi nyawamu, karena darah mengadakan pendamaian dengan perantaraan nyawa.', NULL),
(108633, 3649, 17, 12, 'Itulah sebabnya Aku berfirman kepada orang Israel: Seorangpun di antaramu janganlah makan darah. Demikian juga orang asing yang tinggal di tengah-tengahmu tidak boleh makan darah.', NULL),
(108634, 3649, 17, 13, 'Setiap orang dari orang Israel dan dari orang asing yang tinggal di tengah-tengahmu, yang menangkap dalam perburuan seekor binatang atau burung yang boleh dimakan, haruslah mencurahkan darahnya, lalu menimbunnya dengan tanah.', NULL),
(108635, 3649, 17, 14, 'Karena darah itulah nyawa segala makhluk. Sebab itu Aku telah berfirman kepada orang Israel: Darah makhluk apapun janganlah kamu makan, karena darah itulah nyawa segala makhluk: setiap orang yang memakannya haruslah dilenyapkan.', NULL),
(108636, 3649, 17, 15, 'Dan setiap orang yang makan bangkai atau sisa mangsa binatang buas, baik ia orang Israel asli maupun orang asing, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam, barulah ia menjadi tahir.', NULL),
(108637, 3649, 17, 16, 'Tetapi jikalau ia tidak mencuci pakaiannya dan tidak membasuh tubuhnya, ia akan menanggung kesalahannya sendiri.\"', NULL),
(108638, 3649, 18, 1, 'TUHAN berfirman kepada Musa:', 'Kudusnya perkawinan'),
(108639, 3649, 18, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Akulah TUHAN, Allahmu.', NULL),
(108640, 3649, 18, 3, 'Janganlah kamu berbuat seperti yang diperbuat orang di tanah Mesir, di mana kamu diam dahulu; juga janganlah kamu berbuat seperti yang diperbuat orang di tanah Kanaan, ke mana Aku membawa kamu; janganlah kamu hidup menurut kebiasaan mereka.', NULL),
(108641, 3649, 18, 4, 'Kamu harus lakukan peraturan-Ku dan harus berpegang pada ketetapan-Ku dengan hidup menurut semuanya itu; Akulah TUHAN, Allahmu.', NULL),
(108642, 3649, 18, 5, 'Sesungguhnya kamu harus berpegang pada ketetapan-Ku dan peraturan-Ku. Orang yang melakukannya, akan hidup karenanya; Akulah TUHAN.', NULL),
(108643, 3649, 18, 6, 'Siapapun di antaramu janganlah menghampiri seorang kerabatnya yang terdekat untuk menyingkapkan auratnya; Akulah TUHAN.', NULL),
(108644, 3649, 18, 7, 'Janganlah kausingkapkan aurat isteri ayahmu, karena ia hak ayahmu; dia ibumu, jadi janganlah singkapkan auratnya.', NULL),
(108645, 3649, 18, 8, 'Janganlah kausingkapkan aurat seorang isteri ayahmu, karena ia hak ayahmu.', NULL),
(108646, 3649, 18, 9, 'Mengenai aurat saudaramu perempuan, anak ayahmu atau anak ibumu, baik yang lahir di rumah ayahmu maupun yang lahir di luar, janganlah kausingkapkan auratnya.', NULL),
(108647, 3649, 18, 10, 'Mengenai aurat anak perempuan dari anakmu laki-laki atau anakmu perempuan, janganlah kausingkapkan auratnya, karena dengan begitu engkau menodai keturunanmu.', NULL),
(108648, 3649, 18, 11, 'Mengenai aurat anak perempuan dari seorang isteri ayahmu, yang lahir pada ayahmu sendiri, janganlah kausingkapkan auratnya, karena ia saudaramu perempuan.', NULL),
(108649, 3649, 18, 12, 'Janganlah kausingkapkan aurat saudara perempuan ayahmu, karena ia kerabat ayahmu.', NULL),
(108650, 3649, 18, 13, 'Janganlah kausingkapkan aurat saudara perempuan ibumu, karena ia kerabat ibumu.', NULL),
(108651, 3649, 18, 14, 'Janganlah kausingkapkan aurat isteri saudara laki-laki ayahmu, janganlah kauhampiri isterinya, karena ia isteri saudara ayahmu.', NULL),
(108652, 3649, 18, 15, 'Janganlah kausingkapkan aurat menantumu perempuan, karena ia isteri anakmu laki-laki, maka janganlah kausingkapkan auratnya.', NULL),
(108653, 3649, 18, 16, 'Janganlah kausingkapkan aurat isteri saudaramu laki-laki, karena itu hak saudaramu laki-laki.', NULL),
(108654, 3649, 18, 17, 'Janganlah kausingkapkan aurat seorang perempuan dan anaknya perempuan. Janganlah kauambil anak perempuan dari anaknya laki-laki atau dari anaknya perempuan untuk menyingkapkan auratnya, karena mereka adalah kerabatmu; itulah perbuatan mesum.', NULL),
(108655, 3649, 18, 18, 'Janganlah kauambil seorang perempuan sebagai madu kakaknya untuk menyingkapkan auratnya di samping kakaknya selama kakaknya itu masih hidup.', NULL),
(108656, 3649, 18, 19, 'Janganlah kauhampiri seorang perempuan pada waktu cemar kainnya yang menajiskan untuk menyingkapkan auratnya.', NULL),
(108657, 3649, 18, 20, 'Dan janganlah engkau bersetubuh dengan isteri sesamamu, sehingga engkau menjadi najis dengan dia.', NULL),
(108658, 3649, 18, 21, 'Janganlah kauserahkan seorang dari anak-anakmu untuk dipersembahkan kepada Molokh, supaya jangan engkau melanggar kekudusan nama Allahmu; Akulah TUHAN.', NULL),
(108659, 3649, 18, 22, 'Janganlah engkau tidur dengan laki-laki secara orang bersetubuh dengan perempuan, karena itu suatu kekejian.', NULL),
(108660, 3649, 18, 23, 'Janganlah engkau berkelamin dengan binatang apapun, sehingga engkau menjadi najis dengan binatang itu. Seorang perempuan janganlah berdiri di depan seekor binatang untuk berkelamin, karena itu suatu perbuatan keji.', NULL),
(108661, 3649, 18, 24, 'Janganlah kamu menajiskan dirimu dengan semuanya itu, sebab dengan semuanya itu bangsa-bangsa yang akan Kuhalaukan dari depanmu telah menjadi najis.', NULL),
(108662, 3649, 18, 25, 'Negeri itu telah menjadi najis dan Aku telah membalaskan kesalahannya kepadanya, sehingga negeri itu memuntahkan penduduknya.', NULL),
(108663, 3649, 18, 26, 'Tetapi kamu ini haruslah tetap berpegang pada ketetapan-Ku dan peraturan-Ku dan jangan melakukan sesuatupun dari segala kekejian itu, baik orang Israel asli maupun orang asing yang tinggal di tengah-tengahmu,', NULL),
(108664, 3649, 18, 27, '--karena segala kekejian itu telah dilakukan oleh penghuni negeri yang sebelum kamu, sehingga negeri itu sudah menjadi najis--', NULL),
(108665, 3649, 18, 28, 'supaya kamu jangan dimuntahkan oleh negeri itu, apabila kamu menajiskannya, seperti telah dimuntahkannya bangsa yang sebelum kamu.', NULL),
(108666, 3649, 18, 29, 'Karena setiap orang yang melakukan sesuatupun dari segala kekejian itu, orang itu harus dilenyapkan dari tengah-tengah bangsanya.', NULL),
(108667, 3649, 18, 30, 'Dengan demikian kamu harus tetap berpegang pada kewajibanmu terhadap Aku, dan jangan kamu melakukan sesuatu dari kebiasaan yang keji itu, yang dilakukan sebelum kamu, dan janganlah kamu menajiskan dirimu dengan semuanya itu; Akulah TUHAN, Allahmu.\"', NULL),
(108668, 3649, 19, 1, 'TUHAN berfirman kepada Musa:', 'Kudusnya hidup'),
(108669, 3649, 19, 2, '\"Berbicaralah kepada segenap jemaah Israel dan katakan kepada mereka: Kuduslah kamu, sebab Aku, TUHAN, Allahmu, kudus.', NULL),
(108670, 3649, 19, 3, 'Setiap orang di antara kamu haruslah menyegani ibunya dan ayahnya dan memelihara hari-hari sabat-Ku; Akulah TUHAN, Allahmu.', NULL),
(108671, 3649, 19, 4, 'Janganlah kamu berpaling kepada berhala-berhala dan janganlah kamu membuat bagimu dewa tuangan; Akulah TUHAN, Allahmu.', NULL),
(108672, 3649, 19, 5, 'Apabila kamu mempersembahkan korban keselamatan kepada TUHAN, kamu harus mempersembahkannya sedemikian, hingga TUHAN berkenan akan kamu.', NULL),
(108673, 3649, 19, 6, 'Dan haruslah itu dimakan pada hari mempersembahkannya atau boleh juga pada keesokan harinya, tetapi apa yang tinggal sampai hari yang ketiga haruslah dibakar habis.', NULL),
(108674, 3649, 19, 7, 'Jikalau dimakan juga pada hari yang ketiga, maka itu menjadi sesuatu yang jijik dan TUHAN tidak berkenan akan orang itu.', NULL),
(108675, 3649, 19, 8, 'Siapa yang memakannya, akan menanggung kesalahannya sendiri, karena ia telah melanggar kekudusan persembahan kudus yang kepada TUHAN. Nyawa orang itu haruslah dilenyapkan dari antara orang-orang sebangsanya.', NULL),
(108676, 3649, 19, 9, 'Pada waktu kamu menuai hasil tanahmu, janganlah kausabit ladangmu habis-habis sampai ke tepinya, dan janganlah kaupungut apa yang ketinggalan dari penuaianmu.', NULL),
(108677, 3649, 19, 10, 'Juga sisa-sisa buah anggurmu janganlah kaupetik untuk kedua kalinya dan buah yang berjatuhan di kebun anggurmu janganlah kaupungut, tetapi semuanya itu harus kautinggalkan bagi orang miskin dan bagi orang asing; Akulah TUHAN, Allahmu.', NULL),
(108678, 3649, 19, 11, 'Janganlah kamu mencuri, janganlah kamu berbohong dan janganlah kamu berdusta seorang kepada sesamanya.', NULL),
(108679, 3649, 19, 12, 'Janganlah kamu bersumpah dusta demi nama-Ku, supaya engkau jangan melanggar kekudusan nama Allahmu; Akulah TUHAN.', NULL),
(108680, 3649, 19, 13, 'Janganlah engkau memeras sesamamu manusia dan janganlah engkau merampas; janganlah kautahan upah seorang pekerja harian sampai besok harinya.', NULL),
(108681, 3649, 19, 14, 'Janganlah kaukutuki orang tuli dan di depan orang buta janganlah kautaruh batu sandungan, tetapi engkau harus takut akan Allahmu; Akulah TUHAN.', NULL),
(108682, 3649, 19, 15, 'Janganlah kamu berbuat curang dalam peradilan; janganlah engkau membela orang kecil dengan tidak sewajarnya dan janganlah engkau terpengaruh oleh orang-orang besar, tetapi engkau harus mengadili orang sesamamu dengan kebenaran.', NULL),
(108683, 3649, 19, 16, 'Janganlah engkau pergi kian ke mari menyebarkan fitnah di antara orang-orang sebangsamu; janganlah engkau mengancam hidup sesamamu manusia; Akulah TUHAN.', NULL),
(108684, 3649, 19, 17, 'Janganlah engkau membenci saudaramu di dalam hatimu, tetapi engkau harus berterus terang menegor orang sesamamu dan janganlah engkau mendatangkan dosa kepada dirimu karena dia.', NULL),
(108685, 3649, 19, 18, 'Janganlah engkau menuntut balas, dan janganlah menaruh dendam terhadap orang-orang sebangsamu, melainkan kasihilah sesamamu manusia seperti dirimu sendiri; Akulah TUHAN.', NULL),
(108686, 3649, 19, 19, 'Kamu harus berpegang kepada ketetapan-Ku. Janganlah kawinkan dua jenis ternak dan janganlah taburi ladangmu dengan dua jenis benih, dan janganlah pakai pakaian yang dibuat dari pada dua jenis bahan.', NULL),
(108687, 3649, 19, 20, 'Apabila seorang laki-laki bersetubuh dengan seorang perempuan, yakni seorang budak perempuan yang ada di bawah kuasa laki-laki lain, tetapi yang tidak pernah ditebus dan tidak juga diberi surat tanda merdeka, maka perbuatan itu haruslah dihukum; tetapi janganlah keduanya dihukum mati, karena perempuan itu belum dimerdekakan.', NULL),
(108688, 3649, 19, 21, 'Laki-laki itu harus membawa tebusan salahnya kepada TUHAN ke pintu Kemah Pertemuan, yakni seekor domba jantan sebagai korban penebus salah.', NULL),
(108689, 3649, 19, 22, 'Imam harus mengadakan pendamaian bagi orang itu dengan domba jantan korban penebus salah di hadapan TUHAN, karena dosa yang telah diperbuatnya, sehingga ia beroleh pengampunan dari dosanya itu.', NULL),
(108690, 3649, 19, 23, 'Apabila kamu sudah masuk ke negeri itu dan menanam bermacam-macam pohon buah-buahan, janganlah kamu memetik buahnya selama tiga tahun dan jangan memakannya.', NULL),
(108691, 3649, 19, 24, 'Tetapi pada tahun yang keempat haruslah segala buahnya menjadi persembahan kudus sebagai puji-pujian bagi TUHAN.', NULL),
(108692, 3649, 19, 25, 'Barulah pada tahun yang kelima kamu boleh memakan buahnya, supaya hasilnya ditambah bagimu; Akulah TUHAN, Allahmu.', NULL),
(108693, 3649, 19, 26, 'Janganlah kamu makan sesuatu yang darahnya masih ada. Janganlah kamu melakukan telaah atau ramalan.', NULL),
(108694, 3649, 19, 27, 'Janganlah kamu mencukur tepi rambut kepalamu berkeliling dan janganlah engkau merusakkan tepi janggutmu.', NULL),
(108695, 3649, 19, 28, 'Janganlah kamu menggoresi tubuhmu karena orang mati dan janganlah merajah tanda-tanda pada kulitmu; Akulah TUHAN.', NULL),
(108696, 3649, 19, 29, 'Janganlah engkau merusak kesucian anakmu perempuan dengan menjadikan dia perempuan sundal, supaya negeri itu jangan melakukan persundalan, sehingga negeri itu penuh dengan perbuatan mesum.', NULL),
(108697, 3649, 19, 30, 'Kamu harus memelihara hari-hari sabat-Ku dan menghormati tempat kudus-Ku; Akulah TUHAN.', NULL),
(108698, 3649, 19, 31, 'Janganlah kamu berpaling kepada arwah atau kepada roh-roh peramal; janganlah kamu mencari mereka dan dengan demikian menjadi najis karena mereka; Akulah TUHAN, Allahmu.', NULL),
(108699, 3649, 19, 32, 'Engkau harus bangun berdiri di hadapan orang ubanan dan engkau harus menaruh hormat kepada orang yang tua dan engkau harus takut akan Allahmu; Akulah TUHAN.', NULL),
(108700, 3649, 19, 33, 'Apabila seorang asing tinggal padamu di negerimu, janganlah kamu menindas dia.', NULL),
(108701, 3649, 19, 34, 'Orang asing yang tinggal padamu harus sama bagimu seperti orang Israel asli dari antaramu, kasihilah dia seperti dirimu sendiri, karena kamu juga orang asing dahulu di tanah Mesir; Akulah TUHAN, Allahmu.', NULL),
(108702, 3649, 19, 35, 'Janganlah kamu berbuat curang dalam peradilan, mengenai ukuran, timbangan dan sukatan.', NULL),
(108703, 3649, 19, 36, 'Neraca yang betul, batu timbangan yang betul, efa yang betul dan hin yang betul haruslah kamu pakai; Akulah TUHAN, Allahmu yang membawa kamu keluar dari tanah Mesir.', NULL),
(108704, 3649, 19, 37, 'Demikianlah kamu harus berpegang pada segala ketetapan-Ku dan segala peraturan-Ku serta melakukan semuanya itu; Akulah TUHAN.\"', NULL),
(112017, 3649, 20, 1, 'TUHAN berfirman kepada Musa:', 'Kudusnya umat TUHAN'),
(112018, 3649, 20, 2, '\"Engkau harus berkata kepada orang Israel: Setiap orang, baik dari antara orang Israel maupun dari antara orang asing yang tinggal di tengah-tengah orang Israel, yang menyerahkan seorang dari anak-anaknya kepada Molokh, pastilah ia dihukum mati, yakni rakyat negeri harus melontari dia dengan batu.', NULL),
(112019, 3649, 20, 3, 'Aku sendiri akan menentang orang itu dan akan melenyapkan dia dari tengah-tengah bangsanya, karena ia menyerahkan seorang dari anak-anaknya kepada Molokh, dengan maksud menajiskan tempat kudus-Ku dan melanggar kekudusan nama-Ku yang kudus.', NULL),
(112020, 3649, 20, 4, 'Tetapi jikalau rakyat negeri menutup mata terhadap orang itu, ketika ia menyerahkan seorang dari anak-anaknya kepada Molokh, dan tidak menghukum dia mati,', NULL),
(112021, 3649, 20, 5, 'maka Aku sendiri akan menentang orang itu serta kaumnya dan akan melenyapkan dia dari tengah-tengah bangsanya dan semua orang yang turut berzinah mengikuti dia, yakni berzinah dengan menyembah Molokh.', NULL),
(112022, 3649, 20, 6, 'Orang yang berpaling kepada arwah atau kepada roh-roh peramal, yakni yang berzinah dengan bertanya kepada mereka, Aku sendiri akan menentang orang itu dan melenyapkan dia dari tengah-tengah bangsanya.', NULL),
(112023, 3649, 20, 7, 'Maka kamu harus menguduskan dirimu, dan kuduslah kamu, sebab Akulah TUHAN, Allahmu.', NULL),
(112024, 3649, 20, 8, 'Demikianlah kamu harus berpegang pada ketetapan-Ku dan melakukannya; Akulah TUHAN yang menguduskan kamu.', NULL),
(112025, 3649, 20, 9, 'Apabila ada seseorang yang mengutuki ayahnya atau ibunya, pastilah ia dihukum mati; ia telah mengutuki ayahnya atau ibunya, maka darahnya tertimpa kepadanya sendiri.', NULL),
(112026, 3649, 20, 10, 'Bila seorang laki-laki berzinah dengan isteri orang lain, yakni berzinah dengan isteri sesamanya manusia, pastilah keduanya dihukum mati, baik laki-laki maupun perempuan yang berzinah itu.', NULL),
(112027, 3649, 20, 11, 'Bila seorang laki-laki tidur dengan seorang isteri ayahnya, jadi ia melanggar hak ayahnya, pastilah keduanya dihukum mati, dan darah mereka tertimpa kepada mereka sendiri.', NULL),
(112028, 3649, 20, 12, 'Bila seorang laki-laki tidur dengan menantunya perempuan, pastilah keduanya dihukum mati; mereka telah melakukan suatu perbuatan keji, maka darah mereka tertimpa kepada mereka sendiri.', NULL),
(112029, 3649, 20, 13, 'Bila seorang laki-laki tidur dengan laki-laki secara orang bersetubuh dengan perempuan, jadi keduanya melakukan suatu kekejian, pastilah mereka dihukum mati dan darah mereka tertimpa kepada mereka sendiri.', NULL),
(112030, 3649, 20, 14, 'Bila seorang laki-laki mengambil seorang perempuan dan ibunya, itu suatu perbuatan mesum; ia dan kedua perempuan itu harus dibakar, supaya jangan ada perbuatan mesum di tengah-tengah kamu.', NULL),
(112031, 3649, 20, 15, 'Bila seorang laki-laki berkelamin dengan seekor binatang, pastilah ia dihukum mati, dan binatang itupun harus kamu bunuh juga.', NULL),
(112032, 3649, 20, 16, 'Bila seorang perempuan menghampiri binatang apapun untuk berkelamin, haruslah kaubunuh perempuan dan binatang itu; mereka pasti dihukum mati dan darah mereka tertimpa kepada mereka sendiri.', NULL),
(112033, 3649, 20, 17, 'Bila seorang laki-laki mengambil saudaranya perempuan, anak ayahnya atau anak ibunya, dan mereka bersetubuh, maka itu suatu perbuatan sumbang, dan mereka harus dilenyapkan di depan orang-orang sebangsanya; orang itu telah menyingkapkan aurat saudaranya perempuan, maka ia harus menanggung kesalahannya sendiri.', NULL),
(112034, 3649, 20, 18, 'Bila seorang laki-laki tidur dengan seorang perempuan yang bercemar kain, jadi ia menyingkapkan aurat perempuan itu dan membuka tutup lelerannya sedang perempuan itupun membiarkan tutup leleran darahnya itu disingkapkan, keduanya harus dilenyapkan dari tengah-tengah bangsanya.', NULL),
(112035, 3649, 20, 19, 'Janganlah kausingkapkan aurat saudara perempuan ibumu atau saudara perempuan ayahmu, karena aurat seorang kerabatnya sendirilah yang dibuka, dan mereka harus menanggung kesalahannya sendiri.', NULL),
(112036, 3649, 20, 20, 'Bila seorang laki-laki tidur dengan isteri saudara ayahnya, jadi ia melanggar hak saudara ayahnya, mereka mendatangkan dosa kepada dirinya, dan mereka akan mati dengan tidak beranak.', NULL),
(112037, 3649, 20, 21, 'Bila seorang laki-laki mengambil isteri saudaranya, itu suatu kecemaran, karena ia melanggar hak saudaranya laki-laki, dan mereka akan tidak beranak.', NULL),
(112038, 3649, 20, 22, 'Demikianlah kamu harus berpegang pada segala ketetapan-Ku dan segala peraturan-Ku serta melakukan semuanya itu, supaya jangan kamu dimuntahkan oleh negeri ke mana Aku membawa kamu untuk diam di sana.', NULL),
(112039, 3649, 20, 23, 'Janganlah kamu hidup menurut kebiasaan bangsa yang akan Kuhalau dari depanmu: karena semuanya itu telah dilakukan mereka, sehingga Aku muak melihat mereka.', NULL),
(112040, 3649, 20, 24, 'Tetapi kepadamu Aku telah berfirman: Kamulah yang akan menduduki tanah mereka dan Akulah yang akan memberikannya kepadamu menjadi milikmu, suatu negeri yang berlimpah-limpah susu dan madunya; Akulah TUHAN, Allahmu, yang memisahkan kamu dari bangsa-bangsa lain.', NULL),
(112041, 3649, 20, 25, 'Kamu harus membedakan binatang yang tidak haram dari yang haram, dan burung-burung yang haram dari yang tidak haram, supaya kamu jangan membuat dirimu jijik oleh binatang berkaki empat dan burung-burung dan oleh segala yang merayap di muka bumi, yang telah Kupisahkan supaya kamu haramkan.', NULL),
(112042, 3649, 20, 26, 'Kuduslah kamu bagi-Ku, sebab Aku ini, TUHAN, kudus dan Aku telah memisahkan kamu dari bangsa-bangsa lain, supaya kamu menjadi milik-Ku.', NULL),
(112043, 3649, 20, 27, 'Apabila seorang laki-laki atau perempuan dirasuk arwah atau roh peramal, pastilah mereka dihukum mati, yakni mereka harus dilontari dengan batu dan darah mereka tertimpa kepada mereka sendiri.\"', NULL),
(112044, 3649, 21, 1, 'TUHAN berfirman kepada Musa: \"Berbicaralah kepada para imam, anak-anak Harun, dan katakan kepada mereka: Seorang imam janganlah menajiskan diri dengan orang mati di antara orang-orang sebangsanya,', 'Kudusnya para imam'),
(112045, 3649, 21, 2, 'kecuali kalau yang mati itu adalah kerabatnya yang terdekat, yakni: ibunya, ayahnya, anaknya laki-laki atau perempuan, saudaranya laki-laki,', NULL),
(112046, 3649, 21, 3, 'saudaranya perempuan, yang masih perawan dan dekat kepadanya karena belum mempunyai suami, dengan mereka itu bolehlah ia menajiskan diri.', NULL),
(112047, 3649, 21, 4, 'Sebagai suami janganlah ia menajiskan diri di antara orang-orang sebangsanya dan dengan demikian melanggar kekudusannya.', NULL),
(112048, 3649, 21, 5, 'Janganlah mereka menggundul sebagian kepalanya, dan janganlah mereka mencukur tepi janggutnya, dan janganlah mereka menggoresi kulit tubuhnya.', NULL),
(112049, 3649, 21, 6, 'Mereka itu harus kudus bagi Allahnya dan janganlah mereka melanggar kekudusan nama Allahnya, karena merekalah yang mempersembahkan segala korban api-apian TUHAN, santapan Allah mereka, dan karena itu haruslah mereka kudus.', NULL),
(112050, 3649, 21, 7, 'Janganlah mereka mengambil seorang perempuan sundal atau perempuan yang sudah dirusak kesuciannya atau seorang perempuan yang telah diceraikan oleh suaminya, karena imam itu kudus bagi Allahnya.', NULL),
(112051, 3649, 21, 8, 'Dan kamu harus menganggap dia kudus, karena dialah yang mempersembahkan santapan Allahmu. Ia harus kudus bagimu, sebab Aku, TUHAN, yang menguduskan kamu adalah kudus.', NULL),
(112052, 3649, 21, 9, 'Apabila anak perempuan seorang imam membiarkan kehormatannya dilanggar dengan bersundal, maka ia melanggar kekudusan ayahnya, dan ia harus dibakar dengan api.', NULL),
(112053, 3649, 21, 10, 'Imam yang terbesar di antara saudara-saudaranya, yang sudah diurapi dengan menuangkan minyak urapan di atas kepalanya dan yang ditahbiskan dengan mengenakan kepadanya segala pakaian kudus, janganlah membiarkan rambutnya terurai dan janganlah ia mencabik pakaiannya.', NULL),
(112054, 3649, 21, 11, 'Janganlah ia dekat kepada semua mayat, bahkan janganlah ia menajiskan diri dengan mayat ayahnya atau ibunya.', NULL),
(112055, 3649, 21, 12, 'Janganlah ia keluar dari tempat kudus, supaya jangan dilanggarnya kekudusan tempat kudus Allahnya, karena minyak urapan Allahnya, yang menandakan bahwa ia telah dikhususkan, ada di atas kepalanya; Akulah TUHAN.', NULL),
(112056, 3649, 21, 13, 'Ia harus mengambil seorang perempuan yang masih perawan.', NULL),
(112057, 3649, 21, 14, 'Seorang janda atau perempuan yang telah diceraikan atau yang dirusak kesuciannya atau perempuan sundal, janganlah diambil, melainkan harus seorang perawan dari antara orang-orang sebangsanya,', NULL),
(112058, 3649, 21, 15, 'supaya jangan ia melanggar kekudusan keturunannya di antara orang-orang sebangsanya, sebab Akulah TUHAN, yang menguduskan dia.\"', NULL),
(112059, 3649, 21, 16, 'TUHAN berfirman kepada Musa:', NULL),
(112060, 3649, 21, 17, '\"Katakanlah kepada Harun, begini: Setiap orang dari antara keturunanmu turun-temurun yang bercacat badannya, janganlah datang mendekat untuk mempersembahkan santapan Allahnya,', NULL),
(112061, 3649, 21, 18, 'karena setiap orang yang bercacat badannya tidak boleh datang mendekat: orang buta, orang timpang, orang yang bercacat mukanya, orang yang terlalu panjang anggotanya,', NULL),
(112062, 3649, 21, 19, 'orang yang patah kakinya atau tangannya,', NULL),
(112063, 3649, 21, 20, 'orang yang berbongkol atau yang kerdil badannya atau yang bular matanya, orang yang berkedal atau berkurap atau yang rusak buah pelirnya.', NULL),
(112064, 3649, 21, 21, 'Setiap orang dari keturunan imam Harun, yang bercacat badannya, janganlah datang untuk mempersembahkan segala korban api-apian TUHAN; karena badannya bercacat janganlah ia datang dekat untuk mempersembahkan santapan Allahnya.', NULL),
(112065, 3649, 21, 22, 'Mengenai santapan Allahnya, baik persembahan-persembahan maha kudus maupun persembahan-persembahan kudus boleh dimakannya.', NULL),
(112066, 3649, 21, 23, 'Hanya janganlah ia datang sampai ke tabir dan janganlah ia datang ke mezbah, karena badannya bercacat, supaya jangan dilanggarnya kekudusan seluruh tempat kudus-Ku, sebab Akulah TUHAN, yang menguduskan mereka.\"', NULL),
(112067, 3649, 21, 24, 'Demikianlah Musa menyampaikan firman itu kepada Harun serta anak-anaknya dan kepada semua orang Israel.', NULL),
(112068, 3649, 22, 1, 'TUHAN berfirman kepada Musa:', 'Kudusnya kebaktian korban'),
(112069, 3649, 22, 2, '\"Katakanlah kepada Harun dan anak-anaknya, supaya mereka berlaku hati-hati terhadap persembahan-persembahan kudus yang dikuduskan orang Israel bagi-Ku, agar jangan mereka melanggar kekudusan nama-Ku yang kudus; Akulah TUHAN.', NULL),
(112070, 3649, 22, 3, 'Katakanlah kepada mereka: Setiap orang di antara kamu turun-temurun, yakni dari antara segala keturunanmu yang datang mendekat kepada persembahan-persembahan kudus yang dikuduskan orang Israel bagi TUHAN, sedang ia dalam keadaan najis, maka orang itu akan dilenyapkan dari hadapan-Ku; Akulah TUHAN.', NULL),
(112071, 3649, 22, 4, 'Seseorang dari keturunan Harun yang sakit kusta atau yang mengeluarkan lelehan, janganlah memakan persembahan-persembahan kudus, sebelum ia menjadi tahir; dan orang yang kena kepada sesuatu yang najis karena orang mati atau orang yang tertumpah maninya', NULL),
(112072, 3649, 22, 5, 'atau orang yang kena kepada seekor binatang yang merayap yang menajiskan dia atau kepada salah seorang manusia yang menajiskan dia, dengan kenajisan apapun ia menjadi najis,', NULL),
(112073, 3649, 22, 6, 'orang yang kena kepada yang demikian itu menjadi najis sampai matahari terbenam dan janganlah ia makan dari persembahan-persembahan kudus, sebelum ia membasuh tubuhnya dengan air.', NULL),
(112074, 3649, 22, 7, 'Sesudah matahari terbenam, barulah ia menjadi tahir dan sesudah itu bolehlah ia makan dari persembahan-persembahan kudus itu, karena itulah yang menjadi makanannya.', NULL),
(112075, 3649, 22, 8, 'Janganlah ia makan bangkai atau sisa mangsa binatang buas, supaya jangan ia menjadi najis karenanya; Akulah TUHAN.', NULL),
(112076, 3649, 22, 9, 'Dan mereka harus tetap berpegang pada kewajibannya terhadap Aku, supaya dalam hal itu jangan mereka mendatangkan dosa kepada dirinya dan mati oleh karenanya, karena mereka telah melanggar kekudusan kewajiban itu; Akulah TUHAN, yang menguduskan mereka.', NULL),
(112077, 3649, 22, 10, 'Setiap orang awam janganlah memakan persembahan kudus; demikian juga pendatang yang tinggal pada imam ataupun orang upahan.', NULL),
(112078, 3649, 22, 11, 'Tetapi apabila seseorang telah dibeli oleh imam dengan uangnya menjadi budak beliannya, maka orang itu boleh turut memakannya, demikian juga mereka yang lahir di rumahnya.', NULL),
(112079, 3649, 22, 12, 'Apabila anak perempuan imam bersuamikan orang awam, janganlah ia makan persembahan khusus dari persembahan-persembahan kudus.', NULL),
(112080, 3649, 22, 13, 'Tetapi apabila perempuan itu menjadi janda atau diceraikan, dan ia tidak mempunyai anak, dan telah kembali ke rumah ayahnya seperti waktu ia masih gadis, maka ia boleh makan dari makanan ayahnya; tetapi setiap orang awam janganlah memakannya.', NULL),
(112081, 3649, 22, 14, 'Apabila seseorang dengan tidak sengaja memakan persembahan kudus, ia harus memberi gantinya kepada imam dengan menambah seperlima.', NULL),
(112082, 3649, 22, 15, 'Janganlah pada imam melanggar kekudusan persembahan-persembahan kudus orang Israel yang telah dikhususkan bagi TUHAN,', NULL),
(112083, 3649, 22, 16, 'karena dengan demikian mereka mendatangkan kepada orang Israel kesalahan yang harus ditebus, apabila mereka memakan persembahan-persembahan kudus mereka, sebab Akulah TUHAN, yang menguduskan mereka.\"', NULL),
(112084, 3649, 22, 17, 'TUHAN berfirman kepada Musa:', NULL),
(112085, 3649, 22, 18, '\"Berbicaralah kepada Harun serta anak-anaknya dan kepada semua orang Israel dan katakan kepada mereka: Siapapun dari umat Israel dan dari orang asing di antara orang Israel yang mempersembahkan persembahannya, baik berupa sesuatu persembahan nazar maupun berupa sesuatu persembahan sukarela, yang hendak dipersembahkan mereka kepada TUHAN sebagai korban bakaran,', NULL),
(112086, 3649, 22, 19, 'maka supaya TUHAN berkenan akan kamu, haruslah persembahan itu tidak bercela dari lembu jantan, domba atau kambing.', NULL),
(112087, 3649, 22, 20, 'Segala yang bercacat badannya janganlah kamu persembahkan, karena dengan itu TUHAN tidak berkenan akan kamu.', NULL),
(112088, 3649, 22, 21, 'Juga apabila seseorang mempersembahkan kepada TUHAN korban keselamatan sebagai pembayar nazar khusus atau sebagai korban sukarela dari lembu atau kambing domba, maka korban itu haruslah yang tidak bercela, supaya TUHAN berkenan akan dia, janganlah badannya bercacat sedikitpun.', NULL),
(112089, 3649, 22, 22, 'Binatang yang buta atau yang patah tulang, yang luka atau yang berbisul, yang berkedal atau yang berkurap, semuanya itu janganlah kamu persembahkan kepada TUHAN dan binatang yang demikian janganlah kamu taruh sebagai korban api-apian bagi TUHAN ke atas mezbah.', NULL),
(112090, 3649, 22, 23, 'Tetapi seekor lembu atau domba yang terlalu panjang atau terlalu pendek anggotanya bolehlah kaupersembahkan sebagai korban sukarela, tetapi sebagai korban nazar TUHAN tidak akan berkenan akan binatang itu.', NULL),
(112091, 3649, 22, 24, 'Tetapi binatang yang buah pelirnya terjepit, ditumbuk, direnggut atau dikerat, janganlah kamu persembahkan kepada TUHAN; janganlah kamu berbuat demikian di negerimu.', NULL),
(112092, 3649, 22, 25, 'Juga dari tangan orang asing janganlah kamu persembahkan sesuatu dari semuanya itu sebagai santapan Allahmu, karena semuanya itu telah rusak dan bercacat badannya; TUHAN tidak akan berkenan akan kamu karena persembahan-persembahan itu.\"', NULL),
(112093, 3649, 22, 26, 'TUHAN berfirman kepada Musa:', NULL),
(112094, 3649, 22, 27, '\"Apabila seekor anak lembu atau anak domba atau anak kambing dilahirkan, maka haruslah itu tinggal tujuh hari lamanya dengan induknya, tetapi sejak hari kedelapan dan seterusnya TUHAN berkenan akan binatang itu kalau dipersembahkan berupa korban api-apian bagi-Nya.', NULL),
(112095, 3649, 22, 28, 'Seekor lembu atau kambing atau domba janganlah kamu sembelih bersama dengan anaknya pada satu hari juga.', NULL),
(112096, 3649, 22, 29, 'Dan apabila kamu menyembelih korban syukur bagi TUHAN, kamu harus menyembelihnya sedemikian, hingga TUHAN berkenan akan kamu.', NULL),
(112097, 3649, 22, 30, 'Pada hari itu juga korban itu harus dimakan; janganlah kamu tinggalkan apa-apa dari padanya sampai pagi; Akulah TUHAN.', NULL),
(112098, 3649, 22, 31, 'Dengan demikian kamu harus berpegang pada perintah-Ku dan melakukannya; Akulah TUHAN.', NULL),
(112099, 3649, 22, 32, 'Janganlah melanggar kekudusan nama-Ku yang kudus, supaya Aku dikuduskan di tengah-tengah orang Israel, sebab Akulah TUHAN, yang menguduskan kamu,', NULL),
(112100, 3649, 22, 33, 'yang membawa kamu keluar dari tanah Mesir, supaya Aku menjadi Allahmu; Akulah TUHAN.\"', NULL),
(112101, 3649, 23, 1, 'TUHAN berfirman kepada Musa:', 'Hari-hari raya'),
(112102, 3649, 23, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Hari-hari raya yang ditetapkan TUHAN yang harus kamu maklumkan sebagai waktu pertemuan kudus, waktu perayaan yang Kutetapkan, adalah yang berikut.', NULL),
(112103, 3649, 23, 3, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada sabat, hari perhentian penuh, yakni hari pertemuan kudus; janganlah kamu melakukan sesuatu pekerjaan; itulah sabat bagi TUHAN di segala tempat kediamanmu.', NULL),
(112104, 3649, 23, 4, 'Inilah hari-hari raya yang ditetapkan TUHAN, hari-hari pertemuan kudus, yang harus kamu maklumkan masing-masing pada waktunya yang tetap.', NULL),
(112105, 3649, 23, 5, 'Dalam bulan yang pertama, pada tanggal empat belas bulan itu, pada waktu senja, ada Paskah bagi TUHAN.', NULL),
(112106, 3649, 23, 6, 'Dan pada hari yang kelima belas bulan itu ada hari raya Roti Tidak Beragi bagi TUHAN; tujuh hari lamanya kamu harus makan roti yang tidak beragi.', NULL),
(112107, 3649, 23, 7, 'Pada hari yang pertama kamu harus mengadakan pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat.', NULL),
(112108, 3649, 23, 8, 'Kamu harus mempersembahkan korban api-apian kepada TUHAN tujuh hari lamanya; pada hari yang ketujuh haruslah ada pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat.\"', NULL),
(112109, 3649, 23, 9, 'TUHAN berfirman kepada Musa:', NULL),
(112110, 3649, 23, 10, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila kamu sampai ke negeri yang akan Kuberikan kepadamu, dan kamu menuai hasilnya, maka kamu harus membawa seberkas hasil pertama dari penuaianmu kepada imam,', NULL),
(112111, 3649, 23, 11, 'dan imam itu haruslah mengunjukkan berkas itu di hadapan TUHAN, supaya TUHAN berkenan akan kamu. Imam harus mengunjukkannya pada hari sesudah sabat itu.', NULL),
(112112, 3649, 23, 12, 'Pada hari kamu mengunjukkan berkas itu kamu harus mempersembahkan seekor domba berumur setahun yang tidak bercela, sebagai korban bakaran bagi TUHAN,', NULL),
(112113, 3649, 23, 13, 'serta dengan korban sajiannya dari dua persepuluh efa tepung yang terbaik, diolah dengan minyak, sebagai korban api-apian bagi TUHAN yakni bau yang menyenangkan, serta dengan korban curahannya dari seperempat hin anggur.', NULL),
(112114, 3649, 23, 14, 'Sampai pada hari itu juga janganlah kamu makan roti, atau bertih gandum atau gandum baru, sampai kamu telah membawa persembahan Allahmu; itulah suatu ketetapan untuk selama-lamanya bagi kamu turun-temurun di segala tempat kediamanmu.', NULL),
(112115, 3649, 23, 15, 'Kemudian kamu harus menghitung, mulai dari hari sesudah sabat itu, yaitu waktu kamu membawa berkas persembahan unjukan, harus ada genap tujuh minggu;', NULL),
(112116, 3649, 23, 16, 'sampai pada hari sesudah sabat yang ketujuh kamu harus hitung lima puluh hari; lalu kamu harus mempersembahkan korban sajian yang baru kepada TUHAN.', NULL),
(112117, 3649, 23, 17, 'Dari tempat kediamanmu kamu harus membawa dua buah roti unjukan yang harus dibuat dari dua persepuluh efa tepung yang terbaik dan yang dibakar sesudah dicampur dengan ragi sebagai hulu hasil bagi TUHAN.', NULL),
(112118, 3649, 23, 18, 'Beserta roti itu kamu harus mempersembahkan tujuh ekor domba berumur setahun yang tidak bercela dan seekor lembu jantan muda dan dua ekor domba jantan; semuanya itu haruslah menjadi korban bakaran bagi TUHAN, serta dengan korban sajiannya dan korban-korban curahannya, suatu korban api-apian yang baunya menyenangkan bagi TUHAN.', NULL),
(112119, 3649, 23, 19, 'Kemudian kamu harus mempersembahkan seekor kambing jantan sebagai korban penghapus dosa, dan dua ekor domba yang berumur setahun sebagai korban keselamatan.', NULL),
(112120, 3649, 23, 20, 'Imam harus mengunjukkan semuanya beserta roti hulu hasil itu sebagai persembahan unjukan di hadapan TUHAN, beserta kedua ekor domba itu. Semuanya itu haruslah menjadi persembahan kudus bagi TUHAN dan adalah bagian imam.', NULL),
(112121, 3649, 23, 21, 'Pada hari itu juga kamu harus mengumumkan hari raya dan kamu harus mengadakan pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat; itulah suatu ketetapan untuk selama-lamanya di segala tempat kediamanmu turun-temurun.', NULL),
(112122, 3649, 23, 22, 'Pada waktu kamu menuai hasil tanahmu, janganlah kausabit ladangmu habis-habis sampai ke tepinya dan janganlah kaupungut apa yang ketinggalan dari penuaianmu, semuanya itu harus kautinggalkan bagi orang miskin dan bagi orang asing; Akulah TUHAN, Allahmu.\"', NULL),
(112123, 3649, 23, 23, 'TUHAN berfirman kepada Musa:', NULL),
(112124, 3649, 23, 24, '\"Katakanlah kepada orang Israel, begini: Dalam bulan yang ketujuh, pada tanggal satu bulan itu, kamu harus mengadakan hari perhentian penuh yang diperingati dengan meniup serunai, yakni hari pertemuan kudus.', NULL),
(112125, 3649, 23, 25, 'Janganlah kamu melakukan sesuatu pekerjaan berat dan kamu harus mempersembahkan korban api-apian kepada TUHAN.\"', NULL),
(112126, 3649, 23, 26, 'TUHAN berfirman kepada Musa:', NULL),
(112127, 3649, 23, 27, '\"Akan tetapi pada tanggal sepuluh bulan yang ketujuh itu ada hari Pendamaian; kamu harus mengadakan pertemuan kudus dan harus merendahkan diri dengan berpuasa dan mempersembahkan korban api-apian kepada TUHAN.', NULL),
(112128, 3649, 23, 28, 'Pada hari itu janganlah kamu melakukan sesuatu pekerjaan; itulah hari Pendamaian untuk mengadakan pendamaian bagimu di hadapan TUHAN, Allahmu.', NULL),
(112129, 3649, 23, 29, 'Karena setiap orang yang pada hari itu tidak merendahkan diri dengan berpuasa, haruslah dilenyapkan dari antara orang-orang sebangsanya.', NULL),
(112130, 3649, 23, 30, 'Setiap orang yang melakukan sesuatu pekerjaan pada hari itu, orang itu akan Kubinasakan dari tengah-tengah bangsanya.', NULL),
(112131, 3649, 23, 31, 'Janganlah kamu melakukan sesuatu pekerjaan; itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun di segala tempat kediamanmu.', NULL),
(112132, 3649, 23, 32, 'Itu harus menjadi suatu sabat, hari perhentian penuh bagimu, dan kamu harus merendahkan diri dengan berpuasa. Mulai pada malam tanggal sembilan bulan itu, dari matahari terbenam sampai matahari terbenam, kamu harus merayakan sabatmu.\"', NULL),
(112133, 3649, 23, 33, 'TUHAN berfirman kepada Musa:', NULL),
(112134, 3649, 23, 34, '\"Katakanlah kepada orang Israel, begini: Pada hari yang kelima belas bulan yang ketujuh itu ada hari raya Pondok Daun bagi TUHAN tujuh hari lamanya.', NULL),
(112135, 3649, 23, 35, 'Pada hari yang pertama haruslah ada pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat.', NULL),
(112136, 3649, 23, 36, 'Tujuh hari lamanya kamu harus mempersembahkan korban api-apian kepada TUHAN, dan pada hari yang kedelapan kamu harus mengadakan pertemuan kudus dan mempersembahkan korban api-apian kepada TUHAN. Itulah hari raya perkumpulan, janganlah kamu melakukan sesuatu pekerjaan berat.', NULL),
(112137, 3649, 23, 37, 'Itulah hari-hari raya yang ditetapkan TUHAN, yang harus kamu maklumkan sebagai hari pertemuan kudus untuk mempersembahkan korban api-apian kepada TUHAN, yaitu korban bakaran dan korban sajian, korban sembelihan dan korban-korban curahan, setiap hari sebanyak yang ditetapkan untuk hari itu,', NULL),
(112138, 3649, 23, 38, 'belum termasuk hari-hari Sabat TUHAN dan belum termasuk persembahan-persembahanmu atau segala korban nazarmu atau segala korban sukarelamu, yang kamu hendak persembahkan kepada TUHAN.', NULL),
(112139, 3649, 23, 39, 'Akan tetapi pada hari yang kelima belas bulan yang ketujuh itu pada waktu mengumpulkan hasil tanahmu, kamu harus mengadakan perayaan bagi TUHAN tujuh hari lamanya; pada hari yang pertama haruslah ada perhentian penuh dan juga pada hari yang kedelapan harus ada perhentian penuh.', NULL),
(112140, 3649, 23, 40, 'Pada hari yang pertama kamu harus mengambil buah-buah dari pohon-pohon yang elok, pelepah-pelepah pohon-pohon korma, ranting-ranting dari pohon-pohon yang rimbun dan dari pohon-pohon gandarusa dan kamu harus bersukaria di hadapan TUHAN, Allahmu, tujuh hari lamanya.', NULL),
(112141, 3649, 23, 41, 'Kamu harus merayakannya sebagai perayaan bagi TUHAN tujuh hari lamanya dalam setahun; itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun. Dalam bulan yang ketujuh kamu harus merayakannya.', NULL),
(112142, 3649, 23, 42, 'Di dalam pondok-pondok daun kamu harus tinggal tujuh hari lamanya, setiap orang asli di Israel haruslah tinggal di dalam pondok-pondok daun,', NULL),
(112143, 3649, 23, 43, 'supaya diketahui oleh keturunanmu, bahwa Aku telah menyuruh orang Israel tinggal di dalam pondok-pondok selama Aku menuntun mereka sesudah keluar dari tanah Mesir, Akulah TUHAN, Allahmu.\"', NULL),
(112144, 3649, 23, 44, 'Demikianlah Musa menyampaikan kepada orang Israel firman tentang hari-hari raya yang ditetapkan TUHAN.', NULL),
(112145, 3649, 24, 1, 'TUHAN berfirman kepada Musa:', 'Minyak untuk lampu'),
(112146, 3649, 24, 2, '\"Perintahkanlah kepada orang Israel, supaya mereka membawa kepadamu minyak zaitun tumbuk yang tulen untuk lampu, supaya lampu dapat dipasang dan tetap menyala.', NULL),
(112147, 3649, 24, 3, 'Harun harus tetap mengatur lampu-lampu itu di depan tabir yang menutupi tabut hukum, di dalam Kemah Pertemuan, dari petang sampai pagi, di hadapan TUHAN. Itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun.', NULL),
(112148, 3649, 24, 4, 'Di atas kandil dari emas murni haruslah tetap diaturnya lampu-lampu itu di hadapan TUHAN.\"', NULL),
(112149, 3649, 24, 5, '\"Engkau harus mengambil tepung yang terbaik dan membakar dua belas roti bundar dari padanya, setiap roti bundar harus dibuat dari dua persepuluh efa;', 'Roti sajian'),
(112150, 3649, 24, 6, 'engkau harus mengaturnya menjadi dua susun, enam buah sesusun, di atas meja dari emas murni itu, di hadapan TUHAN.', NULL),
(112151, 3649, 24, 7, 'Engkau harus membubuh kemenyan tulen di atas tiap-tiap susun; kemenyan itulah yang harus menjadi bagian ingat-ingatan roti itu, yakni suatu korban api-apian bagi TUHAN.', NULL),
(112152, 3649, 24, 8, 'Setiap hari Sabat ia harus tetap mengaturnya di hadapan TUHAN; itulah dari pihak orang Israel suatu kewajiban perjanjian untuk selama-lamanya.', NULL),
(112153, 3649, 24, 9, 'Roti itu teruntuk bagi Harun serta anak-anaknya dan mereka harus memakannya di suatu tempat yang kudus; itulah bagian maha kudus baginya dari segala korban api-apian TUHAN; itulah suatu ketetapan untuk selama-lamanya.\"', NULL),
(112154, 3649, 24, 10, 'Pada suatu hari datanglah seorang laki-laki, ibunya seorang Israel sedang ayahnya seorang Mesir, di tengah-tengah perkemahan orang Israel; dan orang itu berkelahi dengan seorang Israel di perkemahan.', 'Penghujat nama TUHAN dihukum Lain-lain kejahatan'),
(112155, 3649, 24, 11, 'Anak perempuan Israel itu menghujat nama TUHAN dengan mengutuk, lalu dibawalah ia kepada Musa. Nama ibunya ialah Selomit binti Dibri dari suku Dan.', NULL),
(112156, 3649, 24, 12, 'Ia dimasukkan dalam tahanan untuk menantikan keputusan sesuai dengan firman TUHAN.', NULL),
(112157, 3649, 24, 13, 'Lalu berfirmanlah TUHAN kepada Musa:', NULL),
(112158, 3649, 24, 14, '\"Bawalah orang yang mengutuk itu ke luar perkemahan dan semua orang yang mendengar haruslah meletakkan tangannya ke atas kepala orang itu, sesudahnya haruslah seluruh jemaah itu melontari dia dengan batu.', NULL),
(112159, 3649, 24, 15, 'Engkau harus mengatakan kepada orang Israel, begini: Setiap orang yang mengutuki Allah harus menanggung kesalahannya sendiri.', NULL),
(112160, 3649, 24, 16, 'Siapa yang menghujat nama TUHAN, pastilah ia dihukum mati dan dilontari dengan batu oleh seluruh jemaah itu. Baik orang asing maupun orang Israel asli, bila ia menghujat nama TUHAN, haruslah dihukum mati.', NULL),
(112161, 3649, 24, 17, 'Juga apabila seseorang membunuh seorang manusia, pastilah ia dihukum mati.', NULL),
(112162, 3649, 24, 18, 'Tetapi siapa yang memukul mati seekor ternak, harus membayar gantinya, seekor ganti seekor.', NULL),
(112163, 3649, 24, 19, 'Apabila seseorang membuat orang sesamanya bercacat, maka seperti yang telah dilakukannya, begitulah harus dilakukan kepadanya:', NULL),
(112164, 3649, 24, 20, 'patah ganti patah, mata ganti mata, gigi ganti gigi; seperti dibuatnya orang lain bercacat, begitulah harus dibuat kepadanya.', NULL),
(112165, 3649, 24, 21, 'Siapa yang memukul mati seekor ternak, ia harus membayar gantinya, tetapi siapa yang membunuh seorang manusia, ia harus dihukum mati.', NULL),
(112166, 3649, 24, 22, 'Satu hukum berlaku bagi kamu, baik bagi orang asing maupun bagi orang Israel asli, sebab Akulah TUHAN, Allahmu.\"', NULL),
(112167, 3649, 24, 23, 'Demikianlah Musa menyampaikan firman itu kepada orang Israel, lalu dibawalah orang yang mengutuk itu ke luar perkemahan, dan dilontarilah dia dengan batu. Maka orang Israel melakukan seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(112168, 3649, 25, 1, 'TUHAN berfirman kepada Musa di gunung Sinai:', 'Tahun Sabat dan tahun Yobel'),
(112169, 3649, 25, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila kamu telah masuk ke negeri yang akan Kuberikan kepadamu, maka tanah itu harus mendapat perhentian sebagai sabat bagi TUHAN.', NULL),
(112170, 3649, 25, 3, 'Enam tahun lamanya engkau harus menaburi ladangmu, dan enam tahun lamanya engkau harus merantingi kebun anggurmu dan mengumpulkan hasil tanah itu,', NULL),
(112171, 3649, 25, 4, 'tetapi pada tahun yang ketujuh haruslah ada bagi tanah itu suatu sabat, masa perhentian penuh, suatu sabat bagi TUHAN. Ladangmu janganlah kautaburi dan kebun anggurmu janganlah kaurantingi.', NULL),
(112172, 3649, 25, 5, 'Dan apa yang tumbuh sendiri dari penuaianmu itu, janganlah kautuai dan buah anggur dari pokok anggurmu yang tidak dirantingi, janganlah kaupetik. Tahun itu harus menjadi tahun perhentian penuh bagi tanah itu.', NULL),
(112173, 3649, 25, 6, 'Hasil tanah selama sabat itu haruslah menjadi makanan bagimu, yakni bagimu sendiri, bagi budakmu laki-laki, bagi budakmu perempuan, bagi orang upahan dan bagi orang asing di antaramu, yang semuanya tinggal padamu.', NULL),
(112174, 3649, 25, 7, 'Juga bagi ternakmu, dan bagi binatang liar yang ada di tanahmu, segala hasil tanah itu menjadi makanannya.', NULL),
(112175, 3649, 25, 8, 'Selanjutnya engkau harus menghitung tujuh tahun sabat, yakni tujuh kali tujuh tahun; sehingga masa tujuh tahun sabat itu sama dengan empat puluh sembilan tahun.', NULL),
(112176, 3649, 25, 9, 'Lalu engkau harus memperdengarkan bunyi sangkakala di mana-mana dalam bulan yang ketujuh pada tanggal sepuluh bulan itu; pada hari raya Pendamaian kamu harus memperdengarkan bunyi sangkakala itu di mana-mana di seluruh negerimu.', NULL),
(112177, 3649, 25, 10, 'Kamu harus menguduskan tahun yang kelima puluh, dan memaklumkan kebebasan di negeri itu bagi segenap penduduknya. Itu harus menjadi tahun Yobel bagimu, dan kamu harus masing-masing pulang ke tanah miliknya dan kepada kaumnya.', NULL),
(112178, 3649, 25, 11, 'Tahun yang kelima puluh itu harus menjadi tahun Yobel bagimu, jangan kamu menabur, dan apa yang tumbuh sendiri dalam tahun itu jangan kamu tuai, dan pokok anggur yang tidak dirantingi jangan kamu petik buahnya.', NULL),
(112179, 3649, 25, 12, 'Karena tahun itu adalah tahun Yobel, haruslah itu kudus bagimu; hasil tahun itu yang hendak kamu makan harus diambil dari ladang.', NULL),
(112180, 3649, 25, 13, 'Dalam tahun Yobel itu kamu harus masing-masing pulang ke tanah miliknya.', NULL),
(112181, 3649, 25, 14, 'Apabila kamu menjual sesuatu kepada sesamamu atau membeli dari padanya, janganlah kamu merugikan satu sama lain.', NULL),
(112182, 3649, 25, 15, 'Apabila engkau membeli dari sesamamu haruslah menurut jumlah tahun sesudah tahun Yobel, dan apabila ia menjual kepadamu haruslah menurut jumlah tahun panen.', NULL),
(112183, 3649, 25, 16, 'Makin besar jumlah tahun itu, makin besarlah pembeliannya, dan makin kecil jumlah tahun itu, makin kecillah pembeliannya, karena jumlah panenlah yang dijualnya kepadamu.', NULL),
(112184, 3649, 25, 17, 'Janganlah kamu merugikan satu sama lain, tetapi engkau harus takut akan Allahmu, sebab Akulah TUHAN, Allahmu.', NULL),
(112185, 3649, 25, 18, 'Demikianlah kamu harus melakukan ketetapan-Ku dan tetap berpegang pada peraturan-Ku serta melakukannya, maka kamu akan diam di tanahmu dengan aman tenteram.', NULL),
(112186, 3649, 25, 19, 'Tanah itu akan memberi hasilnya, dan kamu akan makan sampai kenyang dan diam di sana dengan aman tenteram.', NULL),
(112187, 3649, 25, 20, 'Apabila kamu bertanya: Apakah yang akan kami makan dalam tahun yang ketujuh itu, bukankah kami tidak boleh menabur dan tidak boleh mengumpulkan hasil tanah kami?', NULL),
(112188, 3649, 25, 21, 'Maka Aku akan memerintahkan berkat-Ku kepadamu dalam tahun yang keenam, supaya diberinya hasil untuk tiga tahun.', NULL),
(112189, 3649, 25, 22, 'Dalam tahun yang kedelapan kamu akan menabur, tetapi kamu akan makan dari hasil yang lama sampai kepada tahun yang kesembilan, sampai masuk hasilnya, kamu akan memakan yang lama.\"', NULL),
(112190, 3649, 25, 23, '\"Tanah jangan dijual mutlak, karena Akulah pemilik tanah itu, sedang kamu adalah orang asing dan pendatang bagi-Ku.', NULL),
(112191, 3649, 25, 24, 'Di seluruh tanah milikmu haruslah kamu memberi hak menebus tanah.', NULL),
(112192, 3649, 25, 25, 'Apabila saudaramu jatuh miskin, sehingga harus menjual sebagian dari miliknya, maka seorang kaumnya yang berhak menebus, yakni kaumnya yang terdekat harus datang dan menebus yang telah dijual saudaranya itu.', 'Penebusan tanah'),
(112193, 3649, 25, 26, 'Apabila seseorang tidak mempunyai penebus, tetapi kemudian ia mampu, sehingga didapatnya yang perlu untuk menebus miliknya itu,', NULL),
(112194, 3649, 25, 27, 'maka ia harus memasukkan tahun-tahun sesudah penjualannya itu dalam perhitungan, dan kelebihannya haruslah dikembalikannya kepada orang yang membeli dari padanya, supaya ia boleh pulang ke tanah miliknya.', NULL),
(112195, 3649, 25, 28, 'Tetapi jikalau ia tidak mampu untuk mengembalikannya kepadanya, maka yang telah dijualnya itu tetap di tangan orang yang membelinya sampai kepada tahun Yobel; dalam tahun Yobel tanah itu akan bebas, dan orang itu boleh pulang ke tanah miliknya.\"', NULL),
(112196, 3649, 25, 29, '\"Apabila seseorang menjual rumah tempat tinggal di suatu kota yang berpagar tembok, maka hak menebus hanya berlaku selama setahun mulai dari hari penjualannya; hak menebus berlaku hanya satu tahun.', 'Penebusan rumah'),
(112197, 3649, 25, 30, 'Tetapi jikalau rumah itu tidak ditebus dalam jangka waktu setahun itu, rumah itu secara mutlak menjadi milik si pembeli turun temurun; dalam tahun Yobel rumah itu tidaklah bebas.', NULL),
(112198, 3649, 25, 31, 'Tetapi rumah-rumah di desa-desa yang tidak dikelilingi pagar tembok haruslah dianggap sama dengan ladang-ladang di negeri itu, atasnya harus ada hak menebus dan dalam tahun Yobel rumah itu harus bebas.', NULL),
(112199, 3649, 25, 32, 'Mengenai rumah-rumah di kota-kota orang Lewi, hak menebus rumah-rumah itu ada pada orang-orang Lewi untuk selama-lamanya.', NULL),
(112200, 3649, 25, 33, 'Sekalipun dari antara orang Lewi yang melakukan penebusan, tetapi rumah yang terjual di kota miliknya itu haruslah bebas dalam tahun Yobel, karena segala rumah di kota-kota orang Lewi adalah milik mereka masing-masing di tengah-tengah orang Israel.', NULL),
(112201, 3649, 25, 34, 'Dan padang penggembalaan sekitar kota-kota mereka janganlah dijual, karena itu milik mereka untuk selama-lamanya.\"', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(112202, 3649, 25, 35, '\"Apabila saudaramu jatuh miskin, sehingga tidak sanggup bertahan di antaramu, maka engkau harus menyokong dia sebagai orang asing dan pendatang, supaya ia dapat hidup di antaramu.', 'Perlakuan terhadap orang miskin'),
(112203, 3649, 25, 36, 'Janganlah engkau mengambil bunga uang atau riba dari padanya, melainkan engkau harus takut akan Allahmu, supaya saudaramu dapat hidup di antaramu.', NULL),
(112204, 3649, 25, 37, 'Janganlah engkau memberi uangmu kepadanya dengan meminta bunga, juga makananmu janganlah kauberikan dengan meminta riba.', NULL),
(112205, 3649, 25, 38, 'Akulah TUHAN, Allahmu, yang membawa kamu keluar dari tanah Mesir, untuk memberikan kepadamu tanah Kanaan, supaya Aku menjadi Allahmu.', NULL),
(112206, 3649, 25, 39, 'Apabila saudaramu jatuh miskin di antaramu, sehingga menyerahkan dirinya kepadamu, maka janganlah memperbudak dia.', NULL),
(112207, 3649, 25, 40, 'Sebagai orang upahan dan sebagai pendatang ia harus tinggal di antaramu; sampai kepada tahun Yobel ia harus bekerja padamu.', NULL),
(112208, 3649, 25, 41, 'Kemudian ia harus diizinkan keluar dari padamu, ia bersama-sama anak-anaknya, lalu pulang kembali kepada kaumnya dan ia boleh pulang ke tanah milik nenek moyangnya.', NULL),
(112209, 3649, 25, 42, 'Karena mereka itu hamba-hamba-Ku yang Kubawa keluar dari tanah Mesir, janganlah mereka itu dijual, secara orang menjual budak.', NULL),
(112210, 3649, 25, 43, 'Janganlah engkau memerintah dia dengan kejam, melainkan engkau harus takut akan Allahmu.', NULL),
(112211, 3649, 25, 44, 'Tetapi budakmu laki-laki atau perempuan yang boleh kaumiliki adalah dari antara bangsa-bangsa yang di sekelilingmu; hanya dari antara merekalah kamu boleh membeli budak laki-laki dan perempuan.', NULL),
(112212, 3649, 25, 45, 'Juga dari antara anak-anak pendatang yang tinggal di antaramu boleh kamu membelinya dan dari antara kaum mereka yang tinggal di antaramu, yang dilahirkan di negerimu. Orang-orang itu boleh menjadi milikmu.', NULL),
(112213, 3649, 25, 46, 'Kamu harus membagikan mereka sebagai milik pusaka kepada anak-anakmu yang kemudian, supaya diwarisi sebagai milik; kamu harus memperbudakkan mereka untuk selama-lamanya, tetapi atas saudara-saudaramu orang-orang Israel, janganlah memerintah dengan kejam yang satu sama yang lain.', NULL),
(112214, 3649, 25, 47, 'Apabila seorang asing atau seorang pendatang di antaramu telah menjadi mampu, sedangkan saudaramu yang tinggal padanya jatuh miskin, sehingga menyerahkan dirinya kepada orang asing atau pendatang yang di antaramu itu atau kepada seorang yang berasal dari kaum orang asing,', NULL),
(112215, 3649, 25, 48, 'maka sesudah ia menyerahkan dirinya, ia berhak ditebus, yakni seorang dari antara saudara-saudaranya boleh menebus dia,', NULL),
(112216, 3649, 25, 49, 'atau saudara ayahnya atau anak laki-laki saudara ayahnya atau seorang kerabatnya yang terdekat dari kaumnya atau kalau ia telah mampu, ia sendiri berhak menebus dirinya.', NULL),
(112217, 3649, 25, 50, 'Bersama-sama dengan si pembelinya ia harus membuat perhitungan, mulai dari tahun ia menyerahkan dirinya kepada orang itu sampai kepada tahun Yobel, dan harga penjualan dirinya haruslah ditentukan menurut jumlah tahun-tahun itu; masa ia tinggal pada orang itu haruslah dihitung seperti masa kerja orang upahan.', NULL),
(112218, 3649, 25, 51, 'Jikalau jumlah tahun itu masih besar, maka dari harga pembeliannya harus dikembalikan sebagai penebus dirinya menurut jumlah tahun itu.', NULL),
(112219, 3649, 25, 52, 'Jika waktu yang masih tinggal sampai kepada tahun Yobel sedikit lagi saja, maka ia harus membuat perhitungan dengan orang itu; menurut jumlah tahun itulah ia harus membayar uang tebusan dirinya.', NULL),
(112220, 3649, 25, 53, 'Demikianlah ia harus tinggal padanya sebagai orang upahan dari tahun ke tahun. Janganlah ia diperintah dengan kejam oleh orang itu di depan matamu.', NULL),
(112221, 3649, 25, 54, 'Tetapi jikalau ia tidak ditebus dengan cara demikian, maka ia harus diizinkan keluar dalam tahun Yobel, ia bersama-sama anak-anaknya.', NULL),
(112222, 3649, 25, 55, 'Karena pada-Kulah orang Israel menjadi hamba; mereka itu adalah hamba-hamba-Ku yang Kubawa keluar dari tanah Mesir; Akulah TUHAN, Allahmu.\"', NULL),
(112223, 3649, 26, 1, '\"Janganlah kamu membuat berhala bagimu, dan patung atau tugu berhala janganlah kamu dirikan bagimu; juga batu berukir janganlah kamu tempatkan di negerimu untuk sujud menyembah kepadanya, sebab Akulah TUHAN, Allahmu.', 'Berkat'),
(112224, 3649, 26, 2, 'Kamu harus memelihara hari-hari Sabat-Ku dan menghormati tempat kudus-Ku, Akulah TUHAN.', NULL),
(112225, 3649, 26, 3, 'Jikalau kamu hidup menurut ketetapan-Ku dan tetap berpegang pada perintah-Ku serta melakukannya,', NULL),
(112226, 3649, 26, 4, 'maka Aku akan memberi kamu hujan pada masanya, sehingga tanah itu memberi hasilnya dan pohon-pohonan di ladangmu akan memberi buahnya.', NULL),
(112227, 3649, 26, 5, 'Lamanya musim mengirik bagimu akan sampai kepada musim memetik buah anggur dan lamanya musim memetik buah anggur akan sampai kepada musim menabur. Kamu akan makan makananmu sampai kenyang dan diam di negerimu dengan aman tenteram.', NULL),
(112228, 3649, 26, 6, 'Dan Aku akan memberi damai sejahtera di dalam negeri itu, sehingga kamu akan berbaring dengan tidak dikejutkan oleh apapun; Aku akan melenyapkan binatang buas dari negeri itu, dan pedang tidak akan melintas di negerimu.', NULL),
(112229, 3649, 26, 7, 'Kamu akan mengejar musuhmu, dan mereka akan tewas di hadapanmu oleh pedang.', NULL),
(112230, 3649, 26, 8, 'Lima orang dari antaramu akan mengejar seratus, dan seratus orang dari antaramu akan mengejar selaksa dan semua musuhmu akan tewas di hadapanmu oleh pedang.', NULL),
(112231, 3649, 26, 9, 'Dan Aku akan berpaling kepadamu dan akan membuat kamu beranak cucu serta bertambah banyak dan Aku akan meneguhkan perjanjian-Ku dengan kamu.', NULL),
(112232, 3649, 26, 10, 'Kamu masih akan makan hasil lama dari panen yang lampau, dan hasil lama itu akan kamu keluarkan untuk menyimpan yang baru.', NULL),
(112233, 3649, 26, 11, 'Aku akan menempatkan Kemah Suci-Ku di tengah-tengahmu dan hati-Ku tidak akan muak melihat kamu.', NULL),
(112234, 3649, 26, 12, 'Tetapi Aku akan hadir di tengah-tengahmu dan Aku akan menjadi Allahmu dan kamu akan menjadi umat-Ku.', NULL),
(112235, 3649, 26, 13, 'Akulah TUHAN, Allahmu, yang membawa kamu keluar dari tanah Mesir, supaya kamu jangan lagi menjadi budak mereka. Aku telah mematahkan kayu kuk yang di atasmu dan membuat kamu berjalan tegak.\"', NULL),
(112236, 3649, 26, 14, '\"Tetapi jikalau kamu tidak mendengarkan Daku, dan tidak melakukan segala perintah itu,', 'Kutuk'),
(112237, 3649, 26, 15, 'jikalau kamu menolak ketetapan-Ku dan hatimu muak mendengar peraturan-Ku, sehingga kamu tidak melakukan segala perintah-Ku dan kamu mengingkari perjanjian-Ku,', NULL),
(112238, 3649, 26, 16, 'maka Akupun akan berbuat begini kepadamu, yakni Aku akan mendatangkan kekejutan atasmu, batuk kering serta demam, yang membuat mata rusak dan jiwa merana; kamu akan sia-sia menabur benihmu, karena hasilnya akan habis dimakan musuhmu.', NULL),
(112239, 3649, 26, 17, 'Aku sendiri akan menentang kamu, sehingga kamu akan dikalahkan oleh musuhmu, dan mereka yang membenci kamu akan menguasai kamu, dan kamu akan lari, sungguhpun tidak ada orang mengejar kamu.', NULL),
(112240, 3649, 26, 18, 'Dan jikalau kamu dalam keadaan yang demikianpun tidak mendengarkan Daku, maka Aku akan lebih keras menghajar kamu sampai tujuh kali lipat karena dosamu,', NULL),
(112241, 3649, 26, 19, 'dan Aku akan mematahkan kekuasaanmu yang kaubanggakan dan akan membuat langit di atasmu sebagai besi dan tanahmu sebagai tembaga.', NULL),
(112242, 3649, 26, 20, 'Maka tenagamu akan habis dengan sia-sia, tanahmu tidak akan memberi hasilnya dan pohon-pohonan di tanah itu tidak akan memberi buahnya.', NULL),
(112243, 3649, 26, 21, 'Jikalau hidupmu tetap bertentangan dengan Daku dan kamu tidak mau mendengarkan Daku, maka Aku akan makin menambah hukuman atasmu sampai tujuh kali lipat setimpal dengan dosamu.', NULL),
(112244, 3649, 26, 22, 'Aku akan melepaskan kepadamu binatang liar yang akan memunahkan anak-anakmu dan yang akan melenyapkan ternakmu, serta membuat kamu menjadi sedikit, sehingga jalan-jalanmu menjadi sunyi.', NULL),
(112245, 3649, 26, 23, 'Jikalau kamu dalam keadaan yang demikianpun tidak mau Kuajar, dan hidupmu tetap bertentangan dengan Daku,', NULL),
(112246, 3649, 26, 24, 'maka Akupun akan bertindak melawan kamu dan Aku sendiri akan menghukum kamu tujuh kali lipat karena dosamu,', NULL),
(112247, 3649, 26, 25, 'dan Aku akan mendatangkan ke atasmu suatu pedang, yang akan melakukan pembalasan oleh karena perjanjian itu; bila kamu berkumpul kelak di kota-kotamu, maka Aku akan melepas penyakit sampar ke tengah-tengahmu dan kamu akan diserahkan ke dalam tangan musuh.', NULL),
(112248, 3649, 26, 26, 'Jika Aku memusnahkan persediaan makananmu, maka sepuluh perempuan akan membakar roti di dalam satu pembakaran. Mereka akan mengembalikan rotimu menurut timbangan tertentu, dan kamu akan makan, tetapi tidak menjadi kenyang.', NULL),
(112249, 3649, 26, 27, 'Dan jikalau kamu dalam keadaan yang demikianpun tidak mendengarkan Daku, dan hidupmu tetap bertentangan dengan Daku,', NULL),
(112250, 3649, 26, 28, 'maka Akupun akan bertindak keras melawan kamu dan Aku sendiri akan menghajar kamu tujuh kali lipat karena dosamu,', NULL),
(112251, 3649, 26, 29, 'dan kamu akan memakan daging anak-anakmu lelaki dan anak-anakmu perempuan.', NULL),
(112252, 3649, 26, 30, 'Dan bukit-bukit pengorbananmu akan Kupunahkan, dan segala pedupaanmu akan Kulenyapkan. Aku akan melemparkan bangkai-bangkaimu ke atas bangkai-bangkai berhalamu dan hati-Ku akan muak melihat kamu.', NULL),
(112253, 3649, 26, 31, 'Kota-kotamu akan Kubuat menjadi reruntuhan dan tempat-tempat kudusmu akan Kurusakkan dan Aku tidak mau lagi menghirup bau persembahanmu yang menyenangkan.', NULL),
(112254, 3649, 26, 32, 'Aku sendiri akan merusakkan negeri itu, sehingga musuhmu yang tinggal di situ akan tercengang karenanya.', NULL),
(112255, 3649, 26, 33, 'Tetapi kamu akan Kuserakkan di antara bangsa-bangsa lain dan Aku akan menghunus pedang di belakang kamu, dan tanahmu akan menjadi tempat tandus dan kota-kotamu akan menjadi reruntuhan.', NULL),
(112256, 3649, 26, 34, 'Pada waktu itulah tanah itu pulih dari dilalaikannya tahun-tahun sabatnya selama tanah itu tandus dan selama kamu tinggal di negeri musuh-musuhmu; pada waktu itulah tanah itu akan menjalani sabatnya dan dipulihkan tahun-tahun sabat yang belum didapatnya.', NULL),
(112257, 3649, 26, 35, 'Selama ketandusannya tanah itu akan menjalani sabat yang belum dijalaninya pada tiap-tiap tahun sabatmu, ketika kamu masih diam di situ.', NULL),
(112258, 3649, 26, 36, 'Dan mengenai mereka yang masih tinggal hidup dari antaramu, Aku akan mendatangkan kecemasan ke dalam hati mereka di dalam negeri-negeri musuh mereka, sehingga bunyi daun yang ditiupkan anginpun akan mengejar mereka, dan mereka akan lari seperti orang lari menjauhi pedang, dan mereka akan rebah, sungguhpun tidak ada orang yang mengejar.', NULL),
(112259, 3649, 26, 37, 'Dan mereka akan jatuh tersandung seorang kepada seorang seolah-olah hendak menjauhi pedang, sungguhpun yang mengejar tidak ada, dan kamu tidak akan dapat bertahan di hadapan musuh-musuhmu.', NULL),
(112260, 3649, 26, 38, 'Dan kamu akan binasa di antara bangsa-bangsa lain, dan negeri musuhmu akan memusnahkan kamu.', NULL),
(112261, 3649, 26, 39, 'Dan siapa yang masih tinggal hidup dari antaramu, mereka akan hancur lebur dalam hukumannya di negeri-negeri musuh mereka, dan karena kesalahan nenek moyang mereka juga mereka akan hancur lebur sama seperti nenek moyangnya.', NULL),
(112262, 3649, 26, 40, 'Tetapi bila mereka mengakui kesalahan mereka dan kesalahan nenek moyang mereka dalam hal berubah setia yang dilakukan mereka terhadap Aku dan mengakui juga bahwa hidup mereka bertentangan dengan Daku', NULL),
(112263, 3649, 26, 41, '--Akupun bertindak melawan mereka dan membawa mereka ke negeri musuh mereka--atau bila kemudian hati mereka yang tidak bersunat itu telah tunduk dan mereka telah membayar pulih kesalahan mereka,', NULL),
(112264, 3649, 26, 42, 'maka Aku akan mengingat perjanjian-Ku dengan Yakub; juga perjanjian dengan Ishak dan perjanjian-Ku dengan Abrahampun akan Kuingat dan negeri itu akan Kuingat juga.', NULL),
(112265, 3649, 26, 43, 'Jadi tanah itu akan ditinggalkan mereka dan akan pulih dari akibat tahun-tahun sabat yang dilalaikan selama tanah itu tandus, oleh karena ditinggalkan mereka, dan mereka akan membayar pulih kesalahan mereka, tak lain dan tak bukan karena mereka menolak peraturan-Ku dan hati mereka muak mendengarkan ketetapan-Ku.', NULL),
(112266, 3649, 26, 44, 'Namun demikian, apabila mereka ada di negeri musuh mereka, Aku tidak akan menolak mereka dan tidak akan muak melihat mereka, sehingga Aku membinasakan mereka dan membatalkan perjanjian-Ku dengan mereka, sebab Akulah TUHAN, Allah mereka.', NULL),
(112267, 3649, 26, 45, 'Untuk keselamatan mereka Aku akan mengingat perjanjian dengan orang-orang dahulu yang Kubawa keluar dari tanah Mesir di depan mata bangsa-bangsa lain, supaya Aku menjadi Allah mereka; Akulah TUHAN.\"', NULL),
(112268, 3649, 26, 46, 'Itulah ketetapan-ketetapan dan peraturan-peraturan serta hukum-hukum yang diberikan TUHAN, berlaku di antara Dia dengan orang Israel, di gunung Sinai, dengan perantaraan Musa.', NULL),
(115833, 3649, 27, 1, 'TUHAN berfirman kepada Musa:', 'Membayar nazar'),
(115834, 3649, 27, 2, '\"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila seorang mengucapkan nazar khusus kepada TUHAN mengenai orang menurut penilaian yang berlaku untuk itu,', NULL),
(115835, 3649, 27, 3, 'maka tentang nilai bagi orang laki-laki dari yang berumur dua puluh tahun sampai yang berumur enam puluh tahun, nilai itu harus lima puluh syikal perak, ditimbang menurut syikal kudus.', NULL),
(115836, 3649, 27, 4, 'Tetapi jikalau itu seorang perempuan, maka nilai itu harus tiga puluh syikal.', NULL),
(115837, 3649, 27, 5, 'Jikalau itu mengenai seorang dari yang berumur lima tahun sampai yang berumur dua puluh tahun, maka bagi laki-laki nilai itu harus dua puluh syikal dan bagi perempuan sepuluh syikal.', NULL),
(115838, 3649, 27, 6, 'Jikalau itu mengenai seorang dari yang berumur satu bulan sampai yang berumur lima tahun, maka bagi laki-laki nilai itu harus lima syikal perak, dan bagi perempuan tiga syikal perak.', NULL),
(115839, 3649, 27, 7, 'Jikalau itu mengenai seorang yang berumur enam puluh tahun atau lebih, jikalau itu mengenai laki-laki, maka nilai itu harus lima belas syikal dan bagi perempuan sepuluh syikal.', NULL),
(115840, 3649, 27, 8, 'Tetapi jikalau orang itu terlalu miskin untuk membayar nilai itu, maka haruslah dihadapkannya orang yang dinazarkannya itu kepada imam, dan imam harus menilainya; sesuai dengan kemampuan orang yang bernazar itu imam harus menentukan nilainya.', NULL),
(115841, 3649, 27, 9, 'Jikalau itu termasuk hewan yang boleh dipersembahkan sebagai persembahan kepada TUHAN, maka apapun dari pada hewan itu yang dipersembahkan orang itu kepada TUHAN haruslah kudus.', NULL),
(115842, 3649, 27, 10, 'Janganlah ia menggantinya dan janganlah ia menukarnya, yang baik dengan yang buruk atau yang buruk dengan yang baik. Tetapi jikalau ia menukar juga seekor hewan dengan seekor hewan lain, maka baik hewan itu maupun tukarnya haruslah kudus.', NULL),
(115843, 3649, 27, 11, 'Jikalau itu barang seekor dari antara hewan haram yang tidak boleh dipersembahkan sebagai persembahan kepada TUHAN, maka hewan itu harus dihadapkannya kepada imam,', NULL),
(115844, 3649, 27, 12, 'dan imam harus menetapkan nilainya menurut baik atau buruknya, dan seperti penilaian imam demikianlah jadinya.', NULL),
(115845, 3649, 27, 13, 'Dan jikalau orang itu mau menebusnya juga, ia harus menambahkan seperlima kepada nilai itu.', NULL),
(115846, 3649, 27, 14, 'Apabila seorang menguduskan rumahnya sebagai persembahan kudus bagi TUHAN, maka imam harus menetapkan nilainya menurut baik atau buruknya, dan seperti nilai yang ditetapkan imam demikianlah harus dipegang teguh.', NULL),
(115847, 3649, 27, 15, 'Tetapi jikalau orang yang menguduskan itu mau menebus rumahnya, maka ia harus menambah harganya dengan seperlima dari uang nilainya dan rumah itu menjadi kepunyaannya pula.', NULL),
(115848, 3649, 27, 16, 'Jikalau seseorang menguduskan sebagian dari ladang miliknya bagi TUHAN, maka nilainya haruslah sesuai dengan taburannya, yakni sehomer taburan benih jelai berharga lima puluh syikal perak.', NULL),
(115849, 3649, 27, 17, 'Jikalau ia menguduskan ladangnya mulai dari tahun Yobel, maka nilainya haruslah dipegang teguh.', NULL),
(115850, 3649, 27, 18, 'Tetapi jikalau ia menguduskan ladangnya sesudah tahun Yobel, maka imam harus menghitung harganya bagi orang itu sesuai dengan tahun-tahun yang masih tinggal sampai kepada tahun Yobel, dan harga itu harus dikurangkan dari nilainya.', NULL),
(115851, 3649, 27, 19, 'Dan jikalau orang yang menguduskannya benar-benar mau menebus ladang itu, maka ia harus menambah harganya dengan seperlima dari uang nilainya dan ladang itu tetap dimilikinya.', NULL),
(115852, 3649, 27, 20, 'Tetapi jikalau ia tidak menebus ladang itu, malahan ladang itu telah dijualnya kepada orang lain, maka tidak dapat ditebus lagi.', NULL),
(115853, 3649, 27, 21, 'Tetapi pada waktu bebas dalam tahun Yobel, ladang itu haruslah kudus bagi TUHAN, sama seperti ladang yang dikhususkan bagi TUHAN. Imamlah yang harus memilikinya.', NULL),
(115854, 3649, 27, 22, 'Dan jikalau ia menguduskan bagi TUHAN ladang yang telah dibelinya dan yang tidak termasuk ladang miliknya dahulu,', NULL),
(115855, 3649, 27, 23, 'maka imam harus menghitung baginya harga nilainya sampai kepada tahun Yobel dan orang itu haruslah mempersembahkan nilai itu pada hari itu juga sebagai persembahan kudus bagi TUHAN.', NULL),
(115856, 3649, 27, 24, 'Dalam tahun Yobel ladang itu harus dipulangkan kepada orang yang menjualnya kepadanya, yakni kepada orang yang mula-mula memiliki tanah itu.', NULL),
(115857, 3649, 27, 25, 'Dan segala nilai harus menurut syikal kudus, syikal itu harus dua puluh gera beratnya.', NULL),
(115858, 3649, 27, 26, 'Akan tetapi anak sulung, yang sebagai anak sulung menjadi hak TUHAN dari antara hewan, tidak boleh dikuduskan oleh siapapun, baik seekor lembu maupun seekor kambing atau domba, itu milik TUHAN.', NULL),
(115859, 3649, 27, 27, 'Tetapi jikalau itu dari antara hewan yang haram, maka haruslah orang menebusnya menurut nilainya dengan menambah seperlima dan jikalau tidak ditebus, haruslah dijual menurut nilainya.', NULL),
(115860, 3649, 27, 28, 'Akan tetapi segala yang sudah dikhususkan oleh seseorang bagi TUHAN dari segala miliknya, baik manusia atau hewan, maupun ladang miliknya, tidak boleh dijual dan tidak boleh ditebus, karena segala yang dikhususkan adalah maha kudus bagi TUHAN.', NULL),
(115861, 3649, 27, 29, 'Setiap orang yang dikhususkan, yang harus ditumpas di antara manusia, tidak boleh ditebus, pastilah ia dihukum mati.', NULL),
(115862, 3649, 27, 30, 'Demikian juga segala persembahan persepuluhan dari tanah, baik dari hasil benih di tanah maupun dari buah pohon-pohonan, adalah milik TUHAN; itulah persembahan kudus bagi TUHAN.', NULL),
(115863, 3649, 27, 31, 'Tetapi jikalau seseorang mau menebus juga sebagian dari persembahan persepuluhannya itu, maka ia harus menambah seperlima.', NULL),
(115864, 3649, 27, 32, 'Mengenai segala persembahan persepuluhan dari lembu sapi atau kambing domba, maka dari segala yang lewat dari bawah tongkat gembala waktu dihitung, setiap yang kesepuluh harus menjadi persembahan kudus bagi TUHAN.', NULL),
(115865, 3649, 27, 33, 'Janganlah dipilih-pilih mana yang baik dan mana yang buruk, dan janganlah ditukar; jikalau orang menukarnya juga, maka baik hewan itu maupun tukarnya haruslah kudus dan tidak boleh ditebus.\"', NULL),
(115866, 3649, 27, 34, 'Itulah perintah-perintah yang diperintahkan TUHAN kepada Musa di gunung Sinai untuk disampaikan kepada orang Israel.', NULL),
(141053, 3650, 1, 1, 'TUHAN berfirman kepada Musa di padang gurun Sinai, dalam Kemah Pertemuan, pada tanggal satu bulan yang kedua dalam tahun yang kedua sesudah mereka keluar dari tanah Mesir:', 'Laskar Israel dihitung'),
(141054, 3650, 1, 2, '\"Hitunglah jumlah segenap umat Israel menurut kaum-kaum yang ada dalam setiap suku mereka, dan catatlah nama semua laki-laki di Israel', NULL),
(141055, 3650, 1, 3, 'yang berumur dua puluh tahun ke atas dan yang sanggup berperang, orang demi orang. Engkau ini beserta Harun harus mencatat mereka menurut pasukannya masing-masing.', NULL),
(141056, 3650, 1, 4, 'Dari tiap-tiap suku harus ada satu orang yang mendampingi kamu, yakni orang yang menjadi kepala dari suku yang diwakilinya itu.', NULL),
(141057, 3650, 1, 5, 'Dan inilah nama semua orang yang harus mendampingi kamu. Dari suku Ruben: Elizur bin Syedeur;', NULL),
(141058, 3650, 1, 6, 'dari suku Simeon: Selumiel bin Zurisyadai;', NULL),
(141059, 3650, 1, 7, 'dari suku Yehuda: Nahason bin Aminadab;', NULL),
(141060, 3650, 1, 8, 'dari suku Isakhar: Netaneel bin Zuar;', NULL),
(141061, 3650, 1, 9, 'dari suku Zebulon: Eliab bin Helon;', NULL),
(141062, 3650, 1, 10, 'dari keturunan Yusuf: Elisama bin Amihud dari suku Efraim, dan Gamaliel bin Pedazur dari suku Manasye;', NULL),
(141063, 3650, 1, 11, 'dari suku Benyamin: Abidan bin Gideoni;', NULL),
(141064, 3650, 1, 12, 'dari suku Dan: Ahiezer bin Amisyadai;', NULL),
(141065, 3650, 1, 13, 'dari suku Asyer: Pagiel bin Okhran;', NULL),
(141066, 3650, 1, 14, 'dari suku Gad: Elyasaf bin Rehuel;', NULL),
(141067, 3650, 1, 15, 'dari suku Naftali: Ahira bin Enan.\"', NULL),
(141068, 3650, 1, 16, 'Itulah orang-orang yang dipilih dari umat itu, masing-masing sebagai pemimpin dari suku bapa leluhurnya; mereka inilah kepala-kepala pasukan Israel.', NULL),
(141069, 3650, 1, 17, 'Lalu Musa dan Harun memanggil orang-orang yang tertunjuk namanya itu,', NULL),
(141070, 3650, 1, 18, 'dan pada tanggal satu bulan yang kedua mereka menyuruh segenap umat berkumpul. Kemudian silsilah orang-orang Israel disusun menurut kaum-kaum yang ada dalam setiap suku mereka, sedang nama-nama mereka yang berumur dua puluh tahun ke atas dicatat orang demi orang,', NULL),
(141071, 3650, 1, 19, 'seperti yang diperintahkan TUHAN kepada Musa. Demikianlah Musa mencatat mereka di padang gurun Sinai.', NULL),
(141072, 3650, 1, 20, 'Ketika silsilah bani Ruben, yaitu keturunan anak sulung Israel, disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama semua laki-laki yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang, orang demi orang.', NULL),
(141073, 3650, 1, 21, 'Jumlah yang dicatat dari suku Ruben ada empat puluh enam ribu lima ratus orang.', NULL),
(141074, 3650, 1, 22, 'Ketika silsilah bani Simeon disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama semua laki-laki yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang, orang demi orang.', NULL),
(141075, 3650, 1, 23, 'Jumlah yang dicatat dari suku Simeon ada lima puluh sembilan ribu tiga ratus orang.', NULL),
(141076, 3650, 1, 24, 'Ketika silsilah bani Gad disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141077, 3650, 1, 25, 'Jumlah yang dicatat dari suku Gad ada empat puluh lima ribu enam ratus lima puluh orang.', NULL),
(141078, 3650, 1, 26, 'Ketika silsilah bani Yehuda disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141079, 3650, 1, 27, 'Jumlah yang dicatat dari suku Yehuda ada tujuh puluh empat ribu enam ratus orang.', NULL),
(141080, 3650, 1, 28, 'Ketika silsilah bani Isakhar disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141081, 3650, 1, 29, 'Jumlah yang dicatat dari suku Isakhar ada lima puluh empat ribu empat ratus orang.', NULL),
(141082, 3650, 1, 30, 'Ketika silsilah bani Zebulon disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141083, 3650, 1, 31, 'Jumlah yang dicatat dari suku Zebulon ada lima puluh tujuh ribu empat ratus orang.', NULL),
(141084, 3650, 1, 32, 'Mengenai keturunan Yusuf: Ketika silsilah bani Efraim disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141085, 3650, 1, 33, 'Jumlah yang dicatat dari suku Efraim ada empat puluh ribu lima ratus orang.', NULL),
(141086, 3650, 1, 34, 'Dan ketika silsilah bani Manasye disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141087, 3650, 1, 35, 'Jumlah yang dicatat dari suku Manasye ada tiga puluh dua ribu dua ratus orang.', NULL),
(141088, 3650, 1, 36, 'Ketika silsilah bani Benyamin disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141089, 3650, 1, 37, 'Jumlah yang dicatat dari suku Benyamin ada tiga puluh lima ribu empat ratus orang.', NULL),
(141090, 3650, 1, 38, 'Ketika silsilah bani Dan disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141091, 3650, 1, 39, 'Jumlah yang dicatat dari suku Dan ada enam puluh dua ribu tujuh ratus orang.', NULL),
(141092, 3650, 1, 40, 'Ketika silsilah bani Asyer disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141093, 3650, 1, 41, 'Jumlah yang dicatat dari suku Asyer ada empat puluh satu ribu lima ratus orang.', NULL),
(141094, 3650, 1, 42, 'Ketika silsilah bani Naftali disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', NULL),
(141095, 3650, 1, 43, 'Jumlah yang dicatat dari suku Naftali ada lima puluh tiga ribu empat ratus orang.', NULL),
(141096, 3650, 1, 44, 'Itulah jumlah orang-orang yang dicatat oleh Musa dengan Harun dan dengan kedua belas pemimpin Israel yang masing-masing mewakili sukunya.', NULL),
(141097, 3650, 1, 45, 'Jadi semua orang Israel yang dicatat menurut suku-suku mereka, yaitu orang-orang yang berumur dua puluh tahun ke atas dan yang sanggup berperang di antara orang Israel,', NULL),
(141098, 3650, 1, 46, 'berjumlah enam ratus tiga ribu lima ratus lima puluh orang.', NULL),
(141099, 3650, 1, 47, 'Tetapi mereka yang menurut suku bapa leluhurnya termasuk orang Lewi, tidak turut dicatat bersama-sama dengan mereka itu.', NULL),
(141100, 3650, 1, 48, 'Sebab TUHAN telah berfirman kepada Musa:', NULL),
(141101, 3650, 1, 49, '\"Hanya suku Lewi janganlah kaucatat dan janganlah kauhitung jumlahnya bersama-sama dengan orang Israel,', NULL),
(141102, 3650, 1, 50, 'tetapi tugaskanlah mereka untuk mengawasi Kemah Suci, tempat hukum Allah dengan segala perabotan dan perlengkapannya; mereka harus mengangkat Kemah Suci dengan segala perabotannya; mereka harus mengurusnya dan harus berkemah di sekelilingnya.', NULL),
(141103, 3650, 1, 51, 'Apabila berangkat, Kemah Suci harus dibongkar oleh orang Lewi, dan apabila berkemah, Kemah Suci harus dipasang oleh mereka; sedang orang awam yang mendekat harus dihukum mati.', NULL),
(141104, 3650, 1, 52, 'Orang Israel haruslah berkemah masing-masing di tempat perkemahannya dan masing-masing dekat panji-panjinya, menurut pasukan mereka,', NULL),
(141105, 3650, 1, 53, 'tetapi orang Lewi haruslah berkemah di sekeliling Kemah Suci, tempat hukum Allah supaya umat Israel jangan kena murka; orang Lewi haruslah memelihara Kemah Suci, tempat hukum itu.\"', NULL),
(141106, 3650, 1, 54, 'Maka orang Israel berbuat demikian; tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah diperbuat mereka.', NULL),
(141107, 3650, 2, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'Suku-suku Israel ditunjuk tempat perkemahannya'),
(141108, 3650, 2, 2, '\"Orang Israel harus berkemah masing-masing dekat panji-panjinya, menurut lambang suku-sukunya. Mereka harus berkemah di sekeliling Kemah Pertemuan, agak jauh dari padanya.', NULL),
(141109, 3650, 2, 3, 'Yang berkemah di sebelah timur dekat panji-panjinya, ialah laskar Yehuda, menurut pasukan-pasukan mereka. Pemimpin bani Yehuda ialah Nahason bin Aminadab.', NULL),
(141110, 3650, 2, 4, 'Pasukannya terdiri dari tujuh puluh empat ribu enam ratus orang yang dicatat.', NULL),
(141111, 3650, 2, 5, 'Yang berkemah di dekatnya ialah suku Isakhar. Pemimpin bani Isakhar ialah Netaneel bin Zuar.', NULL),
(141112, 3650, 2, 6, 'Pasukannya terdiri dari lima puluh empat ribu empat ratus orang yang dicatat.', NULL),
(141113, 3650, 2, 7, 'Kemudian suku Zebulon. Pemimpin bani Zebulon ialah Eliab bin Helon.', NULL),
(141114, 3650, 2, 8, 'Pasukannya terdiri dari lima puluh tujuh ribu empat ratus orang yang dicatat.', NULL),
(141115, 3650, 2, 9, 'Jumlah orang yang dicatat dalam laskar Yehuda menurut pasukan-pasukan mereka ada seratus delapan puluh enam ribu empat ratus orang. Merekalah yang terdahulu berangkat.', NULL),
(141116, 3650, 2, 10, 'Panji-panji laskar Ruben adalah di sebelah selatan, menurut pasukan-pasukan mereka. Pemimpin bani Ruben ialah Elizur bin Syedeur.', NULL),
(141117, 3650, 2, 11, 'Pasukannya terdiri dari empat puluh enam ribu lima ratus orang yang dicatat.', NULL),
(141118, 3650, 2, 12, 'Yang berkemah di dekatnya ialah suku Simeon. Pemimpin bani Simeon ialah Selumiel bin Zurisyadai.', NULL),
(141119, 3650, 2, 13, 'Pasukannya terdiri dari lima puluh sembilan ribu tiga ratus orang yang dicatat.', NULL),
(141120, 3650, 2, 14, 'Kemudian suku Gad. Pemimpin bani Gad ialah Elyasaf bin Rehuel.', NULL),
(141121, 3650, 2, 15, 'Pasukannya terdiri dari empat puluh lima ribu enam ratus lima puluh orang yang dicatat.', NULL),
(141122, 3650, 2, 16, 'Jumlah orang yang dicatat dalam laskar Ruben menurut pasukan-pasukan mereka ada seratus lima puluh satu ribu empat ratus lima puluh orang. Merekalah yang nomor dua berangkat.', NULL),
(141123, 3650, 2, 17, 'Sesudah itu berangkatlah Kemah Pertemuan dengan laskar orang Lewi, di tengah-tengah laskar yang lain itu. Sama seperti mereka berkemah, demikianlah juga mereka berangkat, masing-masing di tempatnya menurut panji-panji mereka.', NULL),
(141124, 3650, 2, 18, 'Panji-panji laskar Efraim, menurut pasukan-pasukan mereka, adalah di sebelah barat. Pemimpin bani Efraim ialah Elisama bin Amihud.', NULL),
(141125, 3650, 2, 19, 'Pasukannya terdiri dari empat puluh ribu lima ratus orang yang dicatat.', NULL),
(141126, 3650, 2, 20, 'Di dekatnya ialah suku Manasye. Pemimpin bani Manasye ialah Gamaliel bin Pedazur.', NULL),
(141127, 3650, 2, 21, 'Pasukannya terdiri dari tiga puluh dua ribu dua ratus orang yang dicatat.', NULL),
(141128, 3650, 2, 22, 'Kemudian suku Benyamin. Pemimpin bani Benyamin ialah Abidan bin Gideoni.', NULL),
(141129, 3650, 2, 23, 'Pasukannya terdiri dari tiga puluh lima ribu empat ratus orang yang dicatat.', NULL),
(141130, 3650, 2, 24, 'Jumlah orang yang dicatat dalam laskar Efraim menurut pasukan-pasukan mereka ada seratus delapan ribu seratus orang. Merekalah yang nomor tiga berangkat.', NULL),
(141131, 3650, 2, 25, 'Panji-panji laskar Dan adalah di sebelah utara, menurut pasukan-pasukan mereka. Pemimpin bani Dan ialah Ahiezer bin Amisyadai.', NULL),
(141132, 3650, 2, 26, 'Pasukannya terdiri dari enam puluh dua ribu tujuh ratus orang yang dicatat.', NULL),
(141133, 3650, 2, 27, 'Yang berkemah di dekatnya ialah suku Asyer. Pemimpin bani Asyer ialah Pagiel bin Okhran.', NULL),
(141134, 3650, 2, 28, 'Pasukannya terdiri dari empat puluh satu ribu lima ratus orang yang dicatat.', NULL),
(141135, 3650, 2, 29, 'Kemudian suku Naftali. Pemimpin bani Naftali ialah Ahira bin Enan.', NULL),
(141136, 3650, 2, 30, 'Pasukannya terdiri dari lima puluh tiga ribu empat ratus orang yang dicatat.', NULL),
(141137, 3650, 2, 31, 'Jumlah orang yang dicatat dalam laskar Dan ada seratus lima puluh tujuh ribu enam ratus orang. Merekalah yang terkemudian berangkat, menurut panji-panji mereka.\"', NULL),
(141138, 3650, 2, 32, 'Itulah pencatatan orang Israel menurut suku-suku mereka. Jumlah orang yang dicatat dalam laskar-laskar dengan pasukan-pasukannya ada enam ratus tiga ribu lima ratus lima puluh orang.', NULL),
(141139, 3650, 2, 33, 'Tetapi orang Lewi tidak turut dicatat bersama-sama dengan orang Israel, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(141140, 3650, 2, 34, 'Maka orang Israel berbuat demikian; tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah mereka berkemah menurut panji-panji mereka, dan demikianlah mereka berangkat, masing-masing menurut kaumnya dan sukunya.', NULL),
(141141, 3650, 3, 1, 'Inilah keturunan Harun dan Musa pada waktu TUHAN berfirman kepada Musa di gunung Sinai.', 'Orang Lewi'),
(141142, 3650, 3, 2, 'Nama anak-anak Harun, ialah: yang sulung Nadab, kemudian Abihu, Eleazar dan Itamar.', NULL),
(141143, 3650, 3, 3, 'Itulah nama anak-anak Harun, imam-imam yang diurapi, yang telah ditahbiskan untuk memegang jabatan imam.', NULL),
(141144, 3650, 3, 4, 'Tetapi Nadab dan Abihu sudah mati di hadapan TUHAN di padang gurun Sinai, ketika mereka mempersembahkan api yang asing ke hadapan TUHAN. Mereka tidak mempunyai anak. Jadi ketika Harun, ayah mereka, masih hidup, yang memegang jabatan imam ialah Eleazar dan Itamar.', NULL),
(141145, 3650, 3, 5, 'TUHAN berfirman kepada Musa:', NULL),
(141146, 3650, 3, 6, '\"Suruhlah suku Lewi mendekat dan menghadap imam Harun, supaya mereka melayani dia.', NULL),
(141147, 3650, 3, 7, 'Mereka harus mengerjakan tugas-tugas bagi Harun dan bagi segenap umat Israel di depan Kemah Pertemuan dan dengan demikian melakukan pekerjaan jabatannya pada Kemah Suci.', NULL),
(141148, 3650, 3, 8, 'Mereka harus memelihara segala perabotan Kemah Pertemuan, dan mengerjakan tugas-tugas bagi orang Israel dan dengan demikian melakukan pekerjaan jabatannya pada Kemah Suci.', NULL),
(141149, 3650, 3, 9, 'Orang Lewi harus kauserahkan kepada Harun dan anak-anaknya; dari antara orang Israel haruslah orang-orang itu diserahkan kepadanya dengan sepenuhnya.', NULL),
(141150, 3650, 3, 10, 'Tetapi Harun dan anak-anaknya haruslah kautugaskan untuk memegang jabatannya sebagai imam, sedang orang awam yang mendekat harus dihukum mati.\"', NULL),
(141151, 3650, 3, 11, 'TUHAN berfirman kepada Musa:', NULL),
(141152, 3650, 3, 12, '\"Sesungguhnya, Aku mengambil orang Lewi dari antara orang Israel ganti semua anak sulung mereka, yang terdahulu lahir dari kandungan, supaya orang Lewi menjadi kepunyaan-Ku,', NULL),
(141153, 3650, 3, 13, 'sebab Akulah yang punya semua anak sulung. Pada waktu Aku membunuh semua anak sulung di tanah Mesir, maka Aku menguduskan bagi-Ku semua anak sulung yang ada pada orang Israel, baik dari manusia maupun dari hewan; semuanya itu kepunyaan-Ku; Akulah TUHAN.\"', NULL),
(141154, 3650, 3, 14, 'TUHAN berfirman kepada Musa di padang gurun Sinai:', NULL),
(141155, 3650, 3, 15, '\"Catatlah bani Lewi menurut puak-puak dan kaum-kaum mereka; semua laki-laki yang berumur satu bulan ke atas harus kaucatat.\"', NULL),
(141156, 3650, 3, 16, 'Lalu Musa mencatat mereka sesuai dengan titah TUHAN, seperti yang diperintahkan kepadanya.', NULL),
(141157, 3650, 3, 17, 'Inilah anak-anak Lewi dengan nama mereka: Gerson, Kehat dan Merari.', NULL),
(141158, 3650, 3, 18, 'Inilah nama anak-anak Gerson dan kaum-kaum mereka: Libni dan Simei.', NULL),
(141159, 3650, 3, 19, 'Anak-anak Kehat dan kaum-kaum mereka ialah Amram, Yizhar, Hebron dan Uziel.', NULL),
(141160, 3650, 3, 20, 'Anak-anak Merari dan kaum-kaum mereka ialah Mahli dan Musi. Inilah kaum-kaum orang Lewi yang ada dalam puak-puak mereka.', NULL),
(141161, 3650, 3, 21, 'Puak Gerson terdiri dari kaum Libni dan kaum Simei; itulah kaum-kaum Gerson.', NULL),
(141162, 3650, 3, 22, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada tujuh ribu lima ratus orang.', NULL),
(141163, 3650, 3, 23, 'Kaum-kaum Gerson ini berkemah di belakang Kemah Suci di sebelah barat.', NULL),
(141164, 3650, 3, 24, 'Pemimpin puak Gerson ialah Elyasaf bin Lael.', NULL),
(141165, 3650, 3, 25, 'Yang harus dipelihara oleh bani Gerson dalam Kemah Pertemuan ialah Kemah Suci dan Kemah dengan tudungnya, tirai pintu Kemah Pertemuan,', NULL),
(141166, 3650, 3, 26, 'layar pelataran dan tirai pintu pelataran yang ada sekeliling Kemah Suci dan mezbah, dan talinya, termasuk segala pekerjaan yang berhubungan dengan semuanya itu.', NULL),
(141167, 3650, 3, 27, 'Puak Kehat terdiri dari kaum Amram, kaum Yizhar, kaum Hebron dan kaum Uziel; itulah kaum-kaum Kehat.', NULL),
(141168, 3650, 3, 28, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada delapan ribu enam ratus orang, yakni mereka yang memelihara barang-barang kudus.', NULL),
(141169, 3650, 3, 29, 'Kaum-kaum bani Kehat ini berkemah pada sisi Kemah Suci sebelah selatan.', NULL),
(141170, 3650, 3, 30, 'Pemimpin puak Kehat dan kaum-kaumnya ialah Elisafan bin Uziel.', NULL),
(141171, 3650, 3, 31, 'Yang harus dipelihara mereka ialah tabut, meja, kandil, mezbah-mezbah, perkakas tempat kudus yang dipakai untuk menyelenggarakan ibadah, juga tirai, termasuk segala pekerjaan yang berhubungan dengan semuanya itu.', NULL),
(141172, 3650, 3, 32, 'Adapun pemimpin tertinggi orang Lewi ialah Eleazar, anak imam Harun, yang mengawasi mereka yang memelihara barang-barang kudus.', NULL),
(141173, 3650, 3, 33, 'Puak Merari terdiri dari kaum Mahli dan kaum Musi; itulah kaum-kaum Merari.', NULL),
(141174, 3650, 3, 34, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada enam ribu dua ratus orang.', NULL),
(141175, 3650, 3, 35, 'Pemimpin puak Merari dan kaum-kaumnya ialah Zuriel bin Abihail. Mereka berkemah pada sisi Kemah Suci sebelah utara.', NULL),
(141176, 3650, 3, 36, 'Yang ditugaskan kepada bani Merari untuk dipelihara ialah papan Kemah Suci, kayu lintangnya, tiang-tiangnya, alasnya, segala perabotannya, termasuk segala pekerjaan yang berhubungan dengan semuanya itu,', NULL),
(141177, 3650, 3, 37, 'juga tiang pelataran sekelilingnya, alas, patok dan talinya.', NULL),
(141178, 3650, 3, 38, 'Yang berkemah di depan Kemah Suci di sebelah timur, di depan Kemah Pertemuan, ialah Musa, dan Harun serta anak-anaknya, yang mengerjakan tugas pemeliharaan tempat kudus bagi orang Israel; tetapi orang awam yang mendekat, haruslah dihukum mati.', NULL),
(141179, 3650, 3, 39, 'Jumlah orang Lewi yang sesuai dengan titah TUHAN dicatat oleh Musa dan Harun, menurut kaum-kaum mereka, yakni semua laki-laki yang berumur satu bulan ke atas, ada dua puluh dua ribu orang.', NULL),
(141180, 3650, 3, 40, 'Lalu berfirmanlah TUHAN kepada Musa: \"Catatlah semua anak sulung laki-laki Israel yang berumur satu bulan ke atas, lalu hitunglah jumlah mereka,', NULL),
(141181, 3650, 3, 41, 'dan ambillah orang-orang Lewi bagi-Ku--Akulah TUHAN--sebagai ganti semua anak sulung yang ada pada orang Israel, juga hewan orang Lewi ganti semua anak sulung di antara hewan orang Israel.\"', NULL),
(141182, 3650, 3, 42, 'Maka Musa mencatat semua anak sulung yang ada pada orang Israel, seperti yang diperintahkan TUHAN kepadanya.', NULL),
(141183, 3650, 3, 43, 'Semua anak sulung laki-laki yang dicatat namanya dalam pencatatan itu, yakni yang berumur satu bulan ke atas, ada dua puluh dua ribu dua ratus tujuh puluh tiga orang.', NULL),
(141184, 3650, 3, 44, 'Lalu berfirmanlah TUHAN kepada Musa:', NULL),
(141185, 3650, 3, 45, '\"Ambillah orang Lewi ganti semua anak sulung yang ada pada orang Israel, juga hewan orang Lewi ganti hewan mereka, supaya orang Lewi itu menjadi kepunyaan-Ku; Akulah TUHAN.', NULL),
(141186, 3650, 3, 46, 'Sebagai uang tebusan untuk kedua ratus tujuh puluh tiga anak sulung Israel yang melebihi jumlah orang Lewi itu,', NULL),
(141187, 3650, 3, 47, 'haruslah engkau mengambil lima syikal seorang; engkau harus mengambilnya menurut syikal kudus--syikal ini dua puluh gera beratnya--.', NULL),
(141188, 3650, 3, 48, 'Berikanlah perak itu kepada Harun dan anak-anaknya sebagai uang tebusan untuk orang-orang yang kelebihan itu.\"', NULL),
(141189, 3650, 3, 49, 'Lalu Musa mengambil uang tebusan untuk orang-orang yang melebihi jumlah mereka yang telah ditebus oleh orang Lewi itu;', NULL),
(141190, 3650, 3, 50, 'dari pada anak-anak sulung Israel diambilnya perak itu, seribu tiga ratus enam puluh lima syikal, ditimbang menurut syikal kudus,', NULL),
(141191, 3650, 3, 51, 'maka Musa memberikan uang tebusan itu kepada Harun dan anak-anaknya sesuai dengan titah TUHAN, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(141192, 3650, 4, 1, 'TUHAN berfirman kepada Musa dan Harun:', NULL),
(141193, 3650, 4, 2, '\"Hitunglah jumlah bani Kehat sebagai suatu golongan tersendiri di antara bani Lewi, menurut kaum-kaum yang ada dalam puak mereka.', NULL),
(141194, 3650, 4, 3, 'Hitunglah yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, semua orang yang kena wajib tugas, supaya mereka melakukan pekerjaan di Kemah Pertemuan.', NULL),
(141195, 3650, 4, 4, 'Pekerjaan jabatan orang Kehat di Kemah Pertemuan ialah mengurus barang-barang yang maha kudus.', NULL),
(141196, 3650, 4, 5, 'Kalau perkemahan akan berangkat, haruslah Harun dan anak-anaknya masuk ke dalam untuk menurunkan tabir penudung, dan menudungkannya kepada tabut hukum.', NULL),
(141197, 3650, 4, 6, 'Di atasnya mereka harus meletakkan tutup dari kulit lumba-lumba, dan di atasnya lagi mereka harus membentangkan sehelai kain yang seluruhnya ungu tua, kemudian mereka harus memasang kayu-kayu pengusung tabut itu.', NULL),
(141198, 3650, 4, 7, 'Lagipula di atas meja roti sajian mereka harus membentangkan sehelai kain ungu tua, dan di atasnya mereka harus meletakkan pinggan, cawan, piala dan kendi korban curahan; juga roti sajian harus tetap ada di atasnya.', NULL),
(141199, 3650, 4, 8, 'Di atas semuanya itu mereka harus membentangkan sehelai kain kirmizi, lalu menudungnya dengan tudung dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung meja itu.', NULL),
(141200, 3650, 4, 9, 'Lalu mereka harus mengambil sehelai kain ungu tua dan menudungkannya kepada kandil untuk penerangan dengan lampu-lampunya, sepit-sepit dan penadah-penadahnya, dan segala perkakas minyaknya yang dipakai untuk mengurus kandil itu.', NULL),
(141201, 3650, 4, 10, 'Dan mereka harus meletakkannya dengan segala perkakasnya ke atas tudung dengan dari kulit lumba-lumba dan meletakkannya di atas usungan.', NULL),
(141202, 3650, 4, 11, 'Di atas mezbah dari emas itu mereka harus membentangkan sehelai kain ungu tua dan menudunginya dengan tudung dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung mezbah itu.', NULL),
(141203, 3650, 4, 12, 'Lalu mereka harus mengambil segala perkakas yang dipakai untuk menyelenggarakan kebaktian di tempat kudus, meletakkannya di atas sehelai kain ungu tua dan menudunginya dengan tudung dari kulit lumba-lumba, kemudian meletakkannya di atas usungan.', NULL),
(141204, 3650, 4, 13, 'Dan mereka harus membersihkan mezbah itu dari abu, lalu membentangkan sehelai kain ungu muda di atasnya,', NULL),
(141205, 3650, 4, 14, 'sesudah itu meletakkan di atasnya segala perkakasnya yang dipakai untuk mengurusnya, yakni perbaraan, garpu, penyodok, bokor penyiraman, segala perkakas mezbah itu, dan di atasnya mereka harus membentangkan tutup dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung mezbah itu.', NULL),
(141206, 3650, 4, 15, 'Setelah Harun dan anak-anaknya selesai menudungi barang-barang kudus dan segala perkakas tempat kudus, pada waktu perkemahan akan berangkat, barulah orang Kehat boleh masuk ke dalam untuk mengangkat barang-barang itu; tetapi janganlah mereka kena kepada barang-barang kudus itu, nanti mereka mati. Jadi itulah barang-barang di Kemah Pertemuan yang harus diangkat bani Kehat.', NULL),
(141207, 3650, 4, 16, 'Tetapi Eleazar, anak imam Harun, bertanggung jawab atas minyak untuk penerangan, ukupan dari wangi-wangian, korban sajian yang tetap dan minyak urapan; ia bertanggung jawab atas segenap Kemah Suci dan segala isinya, yakni barang-barang kudus dan perabotannya.\"', NULL),
(141208, 3650, 4, 17, 'TUHAN berfirman kepada Musa dan Harun:', NULL),
(141209, 3650, 4, 18, '\"Perhatikanlah supaya puak Kehat dan kaum-kaumnya jangan musnah binasa dari tengah-tengah orang Lewi.', NULL),
(141210, 3650, 4, 19, 'Inilah yang harus kamu lakukan bagi mereka, supaya mereka tinggal hidup dan jangan mati, apabila mereka mendekat ke barang-barang maha kudus: Harun dan anak-anaknya haruslah masuk ke dalam dan menempatkan mereka masing-masing di tempat tugasnya dekat barang yang harus diangkat.', NULL),
(141211, 3650, 4, 20, 'Tetapi janganlah orang Kehat masuk ke dalam untuk melihat barang-barang kudus itu walau sesaatpun, nanti mereka mati.\"', NULL),
(141212, 3650, 4, 21, 'TUHAN berfirman kepada Musa:', NULL),
(141213, 3650, 4, 22, '\"Hitunglah juga jumlah bani Gerson menurut puak dan kaum-kaum mereka.', NULL),
(141214, 3650, 4, 23, 'Catatlah mereka yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, yakni setiap orang yang wajib tugas, supaya mereka melakukan pekerjaan jabatan di Kemah Pertemuan.', NULL),
(141215, 3650, 4, 24, 'Inilah tugas kaum-kaum Gerson dalam hal pekerjaan jabatan dan pengangkatan barang itu:', NULL),
(141216, 3650, 4, 25, 'mereka harus mengangkat tenda-tenda Kemah Suci, dan Kemah Pertemuan tudungnya dan tudung dari kulit lumba-lumba yang ada di atasnya, tirai pintu Kemah Pertemuan,', NULL),
(141217, 3650, 4, 26, 'layar-layar pelataran dan tirai pintu gerbang pelataran yang ada sekeliling Kemah Suci dan mezbah, dengan talinya dan segala perkakas untuk pekerjaan jabatan mereka; dan mereka harus melakukan segala tugas yang perlu berkenaan dengan semuanya itu.', NULL),
(141218, 3650, 4, 27, 'Seluruh pekerjaan jabatan bani Gerson harus dilakukan sesuai dengan perintah Harun dan anak-anaknya, yakni segala tugas pengangkatan barang dan pekerjaan jabatan itu; kamu harus membuat mereka penanggung jawab atas segala yang harus diangkat mereka.', NULL),
(141219, 3650, 4, 28, 'Itulah tugas kaum-kaum bani Gerson di Kemah Pertemuan. Mereka harus mengerjakan di bawah pimpinan Itamar, anak imam Harun itu.', NULL),
(141220, 3650, 4, 29, 'Orang Merari haruslah kaucatat menurut kaum-kaum yang ada dalam puak mereka.', NULL),
(141221, 3650, 4, 30, 'Catatlah mereka yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, yakni setiap orang yang kena wajib tugas, supaya mereka melakukan pekerjaan jabatan pada Kemah Pertemuan.', NULL),
(141222, 3650, 4, 31, 'Inilah yang wajib diangkat mereka berhubung dengan seluruh pekerjaan jabatan mereka di Kemah Pertemuan: papan-papan Kemah Suci, kayu-kayu lintangnya, tiang-tiangnya, alas-alasnya,', NULL),
(141223, 3650, 4, 32, 'tiang-tiang pelataran sekelilingnya, alas-alasnya, patok-patok dan tali-talinya, serta segala perkakasnya; semuanya termasuk tugas mereka. Dengan terperinci haruslah kamu tunjuk perkakas yang wajib diangkat mereka itu.', NULL),
(141224, 3650, 4, 33, 'Itulah tugas kaum-kaum bani Merari, yakni seluruh pekerjaan jabatan mereka di Kemah Pertemuan, yang harus dilakukan di bawah pimpinan Itamar, anak imam Harun.\"', NULL),
(141225, 3650, 4, 34, 'Demikianlah Musa dan Harun dengan para pemimpin umat Israel mencatat bani Kehat menurut kaum-kaum yang ada dalam puak mereka,', NULL),
(141226, 3650, 4, 35, 'yakni orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan.', NULL),
(141227, 3650, 4, 36, 'Maka jumlah pencatatan mereka menurut kaum-kaum mereka ada dua ribu tujuh ratus lima puluh orang.', NULL),
(141228, 3650, 4, 37, 'Itulah orang-orang yang dicatat dari kaum-kaum Kehat, semua orang yang melakukan pekerjaan jabatan di Kemah Pertemuan, yakni mereka yang dicatat oleh Musa dan Harun, sesuai dengan titah TUHAN dengan perantaraan Musa.', NULL),
(141229, 3650, 4, 38, 'Bani Gerson yang dicatat menurut kaum-kaum yang ada dalam puak mereka,', NULL),
(141230, 3650, 4, 39, 'yaitu orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan,', NULL),
(141231, 3650, 4, 40, 'jadi mereka yang dicatat menurut kaum-kaum yang ada dalam puak mereka, berjumlah dua ribu enam ratus tiga puluh orang.', NULL),
(141232, 3650, 4, 41, 'Itulah jumlah pencatatan kaum-kaum bani Gerson, semua orang yang melakukan pekerjaan jabatan di Kemah Pertemuan, yakni mereka yang dicatat oleh Musa dan Harun sesuai dengan titah TUHAN.', NULL),
(141233, 3650, 4, 42, 'Bani Merari yang dicatat menurut kaum-kaum yang ada dalam puak mereka,', NULL),
(141234, 3650, 4, 43, 'yaitu orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan,', NULL),
(141235, 3650, 4, 44, 'jadi mereka yang dicatat menurut kaum-kaum mereka, berjumlah tiga ribu dua ratus orang.', NULL),
(141236, 3650, 4, 45, 'Itulah jumlah pencatatan kaum-kaum bani Merari, yakni mereka yang dicatat oleh Musa dan Harun, sesuai dengan titah TUHAN dengan perantaraan Musa.', NULL),
(141237, 3650, 4, 46, 'Semua orang Lewi yang dicatat oleh Musa dan Harun dengan para pemimpin Israel menurut kaum-kaum yang ada dalam puak-puak mereka,', NULL),
(141238, 3650, 4, 47, 'yakni orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang wajib melakukan pekerjaan jabatan di Kemah Pertemuan dan pekerjaan pengangkatan barang,', NULL),
(141239, 3650, 4, 48, 'jadi mereka yang dicatat, berjumlah delapan ribu lima ratus delapan puluh orang.', NULL);
INSERT INTO `bible_verses` (`id`, `book_id`, `chapter_num`, `verse_num`, `verse_text`, `title`) VALUES
(141240, 3650, 4, 49, 'Sesuai dengan titah TUHAN dengan perantaraan Musa, maka mereka masing-masing dibuat penanggung jawab atas apa yang harus dikerjakan dan diangkatnya. Demikianlah mereka dicatat, seperti yang diperintahkan TUHAN kepada Musa.', NULL),
(141241, 3650, 5, 1, 'TUHAN berfirman kepada Musa:', NULL),
(141242, 3650, 5, 2, '\"Perintahkanlah kepada orang Israel, supaya semua orang yang sakit kusta, semua orang yang mengeluarkan lelehan, dan semua orang yang najis oleh mayat disuruh meninggalkan tempat perkemahan;', NULL),
(141243, 3650, 5, 3, 'baik laki-laki maupun perempuan haruslah kausuruh pergi; ke luar tempat perkemahan haruslah mereka kausuruh pergi, supaya mereka jangan menajiskan tempat perkemahan di mana Aku diam di tengah-tengah mereka.\"', NULL),
(141244, 3650, 5, 4, 'Maka orang Israel berbuat demikian, mereka menyuruh orang-orang itu meninggalkan tempat perkemahan; seperti yang difirmankan TUHAN kepada Musa, demikianlah diperbuat orang Israel.', NULL),
(141245, 3650, 5, 5, 'TUHAN berfirman kepada Musa:', NULL),
(141246, 3650, 5, 6, '\"Berbicaralah kepada orang Israel: Apabila seseorang, laki-laki atau perempuan, melakukan sesuatu dosa terhadap sesamanya manusia, dan oleh karena itu berubah setia terhadap TUHAN, sehingga orang itu menjadi bersalah,', NULL),
(141247, 3650, 5, 7, 'maka haruslah ia mengakui dosa yang telah dilakukannya itu; kemudian membayar tebusan sepenuhnya dengan menambah seperlima, lalu menyerahkannya kepada orang terhadap siapa ia bersalah.', NULL),
(141248, 3650, 5, 8, 'Tetapi apabila orang itu tidak ada kaumnya, kepada siapa dapat dibayar tebusan salah itu, maka tebusan salah yang harus dibayar itu menjadi kepunyaan TUHAN, dan adalah bagian imam, belum terhitung domba jantan pendamaian yang dipakai untuk mengadakan pendamaian bagi orang itu.', NULL),
(141249, 3650, 5, 9, 'Dari persembahan-persembahan kudus yang disampaikan orang Israel kepada imam, persembahan khususnya adalah bagian imam.', NULL),
(141250, 3650, 5, 10, 'Sedang persembahan-persembahan kudus yang dibawa oleh seseorang adalah bagian orang itu sendiri; hanya apa yang diserahkannya kepada seorang imam adalah bagian imam itu.\"', NULL),
(141251, 3650, 5, 11, 'TUHAN berfirman kepada Musa:', NULL),
(141252, 3650, 5, 12, '\"Berbicaralah kepada orang Israel dan katakanlah kepada mereka: Apabila isteri seseorang berbuat serong dan tidak setia terhadap suaminya,', NULL),
(141253, 3650, 5, 13, 'dan laki-laki lain tidur dan bersetubuh dengan perempuan itu, dengan tidak diketahui suaminya, karena tinggal rahasia bahwa perempuan itu mencemarkan dirinya, tidak ada saksi terhadap dia, dia tidak kedapatan,', NULL),
(141254, 3650, 5, 14, 'dan apabila kemudian roh cemburu menguasai suami itu, sehingga ia menjadi cemburu terhadap isterinya, dan perempuan itu memang telah mencemarkan dirinya, atau apabila roh cemburu menguasai suami itu, sehingga ia menjadi cemburu terhadap isterinya, walaupun perempuan itu tidak mencemarkan dirinya,', NULL),
(141255, 3650, 5, 15, 'maka haruslah orang itu membawa isterinya kepada imam. Dan orang itu harus membawa persembahan karena perempuan itu sebanyak sepersepuluh efa tepung jelai, yang ke atasnya tidak dituangkannya minyak dan yang tidak dibubuhinya kemenyan, karena korban itu ialah korban sajian cemburuan, suatu korban peringatan yang mengingatkan kepada kedurjanaan.', NULL),
(141256, 3650, 5, 16, 'Maka haruslah imam menyuruh perempuan itu mendekat dan menghadapkannya kepada TUHAN.', NULL),
(141257, 3650, 5, 17, 'Lalu imam harus membawa air kudus dalam suatu tempayan tanah, kemudian harus memungut debu yang ada di lantai Kemah Suci dan membubuhnya ke dalam air itu.', NULL),
(141258, 3650, 5, 18, 'Apabila imam sudah menghadapkan perempuan itu kepada TUHAN, haruslah ia menguraikan rambut perempuan itu, lalu meletakkan korban peringatan, yakni korban sajian cemburuan, ke atas telapak tangan perempuan itu, sedang di tangan imam haruslah ada air pahit yang mendatangkan kutuk.', NULL),
(141259, 3650, 5, 19, 'Maka haruslah imam menyumpah perempuan itu dengan berkata kepadanya: Jika tidak benar ada laki-laki yang tidur dengan engkau, dan jika tidak engkau berbuat serong kepada kecemaran, padahal engkau di bawah kuasa suamimu, maka luputlah engkau dari air pahit yang mendatangkan kutuk ini;', NULL),
(141260, 3650, 5, 20, 'tetapi jika engkau, padahal engkau di bawah kuasa suamimu, berbuat serong dan mencemarkan dirimu, oleh karena orang lain dari suamimu sendiri bersetubuh dengan engkau--', NULL),
(141261, 3650, 5, 21, 'dalam hal ini haruslah imam menyumpah perempuan itu dengan sumpah kutuk, dan haruslah imam berkata kepada perempuan itu--maka TUHAN kiranya membuat engkau menjadi sumpah kutuk di tengah-tengah bangsamu dengan mengempiskan pahamu dan mengembungkan perutmu,', NULL),
(141262, 3650, 5, 22, 'sebab air yang mendatangkan kutuk ini akan masuk ke dalam tubuhmu untuk mengembungkan perutmu dan mengempiskan pahamu. Dan haruslah perempuan itu berkata: Amin, amin.', NULL),
(141263, 3650, 5, 23, 'Lalu imam harus menuliskan kutuk itu pada sehelai kertas dan menghapusnya dengan air pahit itu,', NULL),
(141264, 3650, 5, 24, 'dan ia harus memberi perempuan itu minum air pahit yang mendatangkan kutuk itu, dan air itu akan masuk ke dalam badannya dan menyebabkan sakit yang pedih.', NULL),
(141265, 3650, 5, 25, 'Maka haruslah imam mengambil korban sajian cemburuan dari tangan perempuan itu lalu mengunjukkannya ke hadapan TUHAN, dan membawanya ke mezbah.', NULL),
(141266, 3650, 5, 26, 'Sesudah itu haruslah imam mengambil segenggam dari korban sajian itu sebagai bagian ingat-ingatannya dan membakarnya di atas mezbah, kemudian memberi perempuan itu minum air itu.', NULL),
(141267, 3650, 5, 27, 'Setelah terjadi demikian, apabila perempuan itu memang mencemarkan dirinya dan berubah setia terhadap suaminya, air yang mendatangkan sumpah serapah itu akan masuk ke badannya dan menyebabkan sakit yang pedih, sehingga perutnya mengembung dan pahanya mengempis, dan perempuan itu akan menjadi sumpah kutuk di antara bangsanya.', NULL),
(141268, 3650, 5, 28, 'Tetapi apabila perempuan itu tidak mencemarkan dirinya, melainkan ia suci, maka ia akan bebas dan akan dapat beranak.\"', NULL),
(141269, 3650, 5, 29, 'Itulah hukum tentang perkara cemburuan, kalau seorang perempuan telah berbuat serong dan mencemarkan dirinya, padahal ia di bawah kuasa suaminya,', NULL),
(141270, 3650, 5, 30, 'atau kalau roh cemburu menguasai seorang laki-laki, sehingga ia cemburu terhadap isterinya; ia harus menghadapkan perempuan itu kepada TUHAN dan imam haruslah melaksanakan seluruh hukum ini kepada perempuan itu.', NULL),
(141271, 3650, 5, 31, 'Laki-laki itu akan bebas dari pada salah, tetapi perempuan itu haruslah menanggung akibat kesalahannya.', NULL),
(141272, 3650, 6, 1, 'TUHAN berfirman kepada Musa:', 'Hukum mengenai kenaziran'),
(141273, 3650, 6, 2, '\"Berbicaralah kepada orang Israel dan katakanlah kepada mereka: Apabila seseorang, laki-laki atau perempuan, mengucapkan nazar khusus, yakni nazar orang nazir, untuk mengkhususkan dirinya bagi TUHAN,', NULL),
(141274, 3650, 6, 3, 'maka haruslah ia menjauhkan dirinya dari anggur dan minuman yang memabukkan, jangan meminum cuka anggur atau cuka minuman yang memabukkan dan jangan meminum sesuatu minuman yang dibuat dari buah anggur, dan jangan memakan buah anggur, baik yang segar maupun yang kering.', NULL),
(141275, 3650, 6, 4, 'Selama waktu kenazirannya janganlah ia makan sesuatu apapun yang berasal dari pohon anggur, dari bijinya sampai kepada pucuk rantingnya.', NULL),
(141276, 3650, 6, 5, 'Selama waktu nazarnya sebagai orang nazir janganlah pisau cukur lalu di kepalanya; sampai genap waktunya ia mengkhususkan dirinya bagi TUHAN, haruslah ia tetap kudus dan membiarkan rambutnya tumbuh panjang.', NULL),
(141277, 3650, 6, 6, 'Selama waktunya ia mengkhususkan dirinya bagi TUHAN, janganlah ia dekat kepada mayat orang;', NULL),
(141278, 3650, 6, 7, 'bahkan apabila mati ayahnya ataupun ibunya, saudaranya laki-laki ataupun saudaranya perempuan, janganlah ia menajiskan dirinya kepada mereka, sebab tanda kenaziran bagi Allahnya ada di atas kepalanya.', NULL),
(141279, 3650, 6, 8, 'Selama waktu kenazirannya ia kudus bagi TUHAN.', NULL),
(141280, 3650, 6, 9, 'Tetapi apabila seseorang mati di dekatnya dengan sangat tiba-tiba, sehingga ia menajiskan rambut kenazirannya, maka haruslah ia mencukur rambutnya pada hari pentahirannya, yaitu pada hari yang ketujuh haruslah ia mencukurnya.', NULL),
(141281, 3650, 6, 10, 'Pada hari yang kedelapan haruslah ia membawa dua ekor burung tekukur atau dua ekor anak burung merpati kepada imam, ke pintu Kemah Pertemuan.', NULL),
(141282, 3650, 6, 11, 'Maka haruslah imam mengolah yang seekor menjadi korban penghapus dosa dan yang lain menjadi korban bakaran, dan mengadakan pendamaian bagi dia, oleh karena dia telah berdosa dengan berada dekat mayat. Pada hari itu juga ia harus menguduskan kepalanya', NULL),
(141283, 3650, 6, 12, 'dan mengkhususkan waktu kenazirannya bagi TUHAN. Ia harus membawa seekor domba jantan berumur setahun menjadi korban penebus salah. Hari-hari yang sudah lewat dianggap batal, karena rambut kenazirannya telah menjadi najis.', NULL),
(141284, 3650, 6, 13, 'Dan inilah hukum tentang seorang nazir. Apabila waktu kenazirannya genap, ia harus dibawa ke pintu Kemah Pertemuan,', NULL),
(141285, 3650, 6, 14, 'dan ia harus mempersembahkan sebagai persembahannya kepada TUHAN seekor domba jantan berumur setahun yang tidak bercela untuk korban bakaran dan seekor domba betina berumur setahun yang tidak bercela untuk korban penghapus dosa dan seekor domba jantan yang tidak bercela untuk korban keselamatan,', NULL),
(141286, 3650, 6, 15, 'juga sebakul roti yang tidak beragi, yakni roti bundar dari tepung yang terbaik, yang diolah dengan minyak, dan roti tipis yang tidak beragi diolesi dengan minyak, serta dengan korban sajian dan korban-korban curahannya.', NULL),
(141287, 3650, 6, 16, 'Lalu haruslah imam membawa semuanya itu ke hadapan TUHAN dan mengolah korban penghapus dosa dan korban bakarannya;', NULL),
(141288, 3650, 6, 17, 'domba jantan itu haruslah diolahnya sebagai korban keselamatan bagi TUHAN, beserta sebakul roti yang tidak beragi itu; juga haruslah imam mengolah korban sajian dan korban curahannya.', NULL),
(141289, 3650, 6, 18, 'Maka haruslah orang nazir itu mencukur rambut kenazirannya di depan pintu Kemah Pertemuan, lalu mengambil rambut kenazirannya itu dan melemparkannya ke dalam api yang di bawah korban keselamatan.', NULL),
(141290, 3650, 6, 19, 'Imam haruslah mengambil paha depan domba jantan itu, sesudah dimasak, dan satu roti bundar yang tidak beragi dari dalam bakul, dengan satu roti tipis yang tidak beragi, lalu meletakkannya ke atas telapak tangan orang nazir itu, setelah orang ini mencukur rambut kenazirannya;', NULL),
(141291, 3650, 6, 20, 'kemudian haruslah imam mengunjukkan semuanya itu ke hadapan TUHAN sebagai persembahan unjukan; semuanya itu menjadi bagian kudus bagi imam, beserta dada persembahan unjukan dan beserta paha persembahan khusus. Sesudah itu barulah boleh orang nazir itu minum anggur.\"', NULL),
(141292, 3650, 6, 21, 'Itulah hukum tentang orang nazir yang menazarkan persembahannya kepada TUHAN berdasarkan kenazirannya, belum dihitung apa yang ia mampu mempersembahkan di samping itu. Sesuai dengan bunyi nazar yang diikrarkannya, demikianlah harus dilakukannya berdasarkan hukum tentang kenazirannya.', NULL),
(141293, 3650, 6, 22, 'TUHAN berfirman kepada Musa:', NULL),
(141294, 3650, 6, 23, '\"Berbicaralah kepada Harun dan anak-anaknya: Beginilah harus kamu memberkati orang Israel, katakanlah kepada mereka:', NULL),
(141295, 3650, 6, 24, 'TUHAN memberkati engkau dan melindungi engkau;', NULL),
(141296, 3650, 6, 25, 'TUHAN menyinari engkau dengan wajah-Nya dan memberi engkau kasih karunia;', NULL),
(141297, 3650, 6, 26, 'TUHAN menghadapkan wajah-Nya kepadamu dan memberi engkau damai sejahtera.', NULL),
(141298, 3650, 6, 27, 'Demikianlah harus mereka meletakkan nama-Ku atas orang Israel, maka Aku akan memberkati mereka.\"', NULL),
(141299, 3650, 7, 1, 'Pada waktu Musa selesai mendirikan Kemah Suci, diurapinya dan dikuduskannyalah itu dengan segala perabotannya, juga mezbah dengan segala perkakasnya; dan setelah diurapi dan dikuduskannya semuanya itu,', 'Persembahan pada waktu pentahbisan Kemah Suci'),
(141300, 3650, 7, 2, 'maka para pemimpin Israel, para kepala suku mereka, mempersembahkan persembahan. Mereka itu ialah para pemimpin suku yang bertanggung jawab atas pencatatan itu.', NULL),
(141301, 3650, 7, 3, 'Sebagai persembahan dibawa mereka ke hadapan TUHAN: enam kereta beratap dengan dua belas ekor lembu; satu kereta untuk dua orang pemimpin dan satu ekor lembu untuk satu orang pemimpin, lalu mereka membawa semuanya itu ke depan Kemah Suci.', NULL),
(141302, 3650, 7, 4, 'Kemudian TUHAN berfirman kepada Musa:', NULL),
(141303, 3650, 7, 5, '\"Terimalah semuanya itu dari mereka, supaya dipergunakan untuk pekerjaan pada Kemah Pertemuan; berikanlah semuanya itu kepada orang Lewi, sesuai dengan keperluan pekerjaan masing-masing.\"', NULL),
(141304, 3650, 7, 6, 'Lalu Musa menerima kereta-kereta dan lembu-lembu itu dan memberikannya kepada orang Lewi;', NULL),
(141305, 3650, 7, 7, 'dua kereta dengan empat ekor lembu diberikannya kepada bani Gerson, sesuai dengan keperluan pekerjaan mereka,', NULL),
(141306, 3650, 7, 8, 'dan empat kereta dengan delapan ekor lembu diberikannya kepada bani Merari, sesuai dengan keperluan pekerjaan mereka di bawah pimpinan Itamar, anak imam Harun itu.', NULL),
(141307, 3650, 7, 9, 'Tetapi kepada bani Kehat tidak diberikannya apa-apa, karena pekerjaan mereka ialah mengurus barang-barang kudus, yang harus diangkat di atas bahunya.', NULL),
(141308, 3650, 7, 10, 'Lagi para pemimpin mempersembahkan persembahan pentahbisan mezbah, pada hari mezbah itu diurapi; para pemimpin membawa persembahan mereka ke depan mezbah itu.', NULL),
(141309, 3650, 7, 11, 'TUHAN berfirman kepada Musa: \"Satu pemimpin setiap hari haruslah mempersembahkan persembahannya untuk mentahbiskan mezbah itu.\"', NULL),
(141310, 3650, 7, 12, 'Yang mempersembahkan persembahannya pada hari pertama ialah Nahason bin Aminadab, dari suku Yehuda.', NULL),
(141311, 3650, 7, 13, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', NULL),
(141312, 3650, 7, 14, 'satu cawan sepuluh syikal emas beratnya, berisi ukupan;', NULL),
(141313, 3650, 7, 15, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', NULL),
(141314, 3650, 7, 16, 'seekor kambing jantan, untuk korban penghapus dosa;', NULL),
(141315, 3650, 7, 17, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Nahason bin Aminadab.', NULL),
(141316, 3650, 7, 18, 'Pada hari kedua Netaneel bin Zuar, pemimpin suku Isakhar, mempersembahkan persembahan.', NULL),
(141317, 3650, 7, 19, 'Sebagai persembahannya dipersembahkannya satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', NULL),
(141318, 3650, 7, 20, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', NULL),
(141319, 3650, 7, 21, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', NULL),
(141320, 3650, 7, 22, 'seekor kambing jantan untuk korban penghapus dosa;', NULL),
(141321, 3650, 7, 23, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Netaneel bin Zuar.', NULL),
(141322, 3650, 7, 24, 'Pada hari ketiga: pemimpin bani Zebulon, Eliab bin Helon.', NULL),
(141323, 3650, 7, 25, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', NULL),
